    "explanation": "**[핵심 개념]**\n다항식의 극한은 극한의 성질을 이용하여 직접 대입으로 구할 수 있습니다. 다항식 $f(x)$에 대해 $x \\to a$일 때, $\\lim_{x \\to a} f(x) = f(a)$가 성립합니다. 이는 다항식이 모든 실수에서 연속함수이기 때문입니다.\n\n**[풀이]**\n\n주어진 극한을 계산하겠습니다.\n\n$$\\lim_{x \\to 2} (3x^2 - 5x + 1)$$\n\n다항식은 연속함수이므로, 극한값은 $x = 2$를 함수에 직접 대입하여 구합니다.\n\n$$= 3(2)^2 - 5(2) + 1$$\n\n각 항을 계산하면:\n- 첫 번째 항: $3(2)^2 = 3 \\times 4 = 12$\n- 두 번째 항: $-5(2) = -10$\n- 세 번째 항: $1$\n\n따라서:\n$$= 12 - 10 + 1 = 3$$\n\n**[정답 확인]**\n다항식 함수는 정의역의 모든 점에서 연속이므로, $x = 2$를 직접 대입하여 구한 값 3이 극한값입니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으나, 계산 실수가 있을 경우:\n- $3 \\times 4 = 12$를 잘못 계산하면 오답\n- $12 - 10 = 2$로 계산한 후 $+1$을 빠뜨리면 2\n- 부호를 실수하면 다른 값들이 나올 수 있습니다.\n\n**[핵심 포인트]**\n**다항식 함수의 극한은 연속성에 의해 직접 대입으로 구할 수 있습니다.** $x \\to a$일 때 $\\lim_{x \\to a} f(x) = f(a)$ (단, $f$는 다항식)",
