    "answer": 2,
    "explanation": "**[핵심 개념]**\n극한값을 구할 때 직접 대입했을 때 $\\frac{0}{0}$ 꼴의 부정형이 나타나면, 식을 정리하여 부정형을 제거해야 한다. 특히 분자가 인수분해 가능한 경우, 인수분해를 통해 공통인수를 약분하면 부정형을 해결할 수 있다.\n\n**[풀이]**\n\n**Step 1: 직접 대입으로 극한형 확인**\n\n$x = 1$을 직접 대입하면:\n$$\\frac{1^2 - 1}{1 - 1} = \\frac{0}{0}$$\n\n$\\frac{0}{0}$ 꼴의 부정형이므로, 식을 정리해야 한다.\n\n**Step 2: 분자 인수분해**\n\n분자 $x^2 - 1$은 제곱의 차 공식을 이용하여 인수분해할 수 있다:\n$$x^2 - 1 = (x+1)(x-1)$$\n\n**Step 3: 공통인수 약분**\n\n주어진 식을 다시 쓰면:\n$$\\lim_{x \\to 1} \\frac{x^2 - 1}{x - 1} = \\lim_{x \\to 1} \\frac{(x+1)(x-1)}{x-1}$$\n\n$x \\to 1$일 때 $x \\neq 1$이므로 $(x-1) \\neq 0$이다. 따라서 공통인수를 약분할 수 있다:\n$$\\lim_{x \\to 1} \\frac{(x+1)(x-1)}{x-1} = \\lim_{x \\to 1} (x+1)$$\n\n**Step 4: 극한값 계산**\n\n이제 부정형이 제거되었으므로 직접 대입 가능:\n$$\\lim_{x \\to 1} (x+1) = 1 + 1 = 2$$\n\n**[정답 확인]**\n인수분해를 통해 부정형을 제거한 후 직접 대입한 결과가 2이므로, 정답은 **③번**이다.\n\n**[오답 분석]**\n- ① 0: $x = 1$을 원래 식에 직접 대입한 분자 값만 본 경우\n- ② 1: 부정형을 잘못 해석하거나 계산 실수로 $x$ 값 자체를 답이라고 본 경우\n- ④ 3: 분자와 분모의 차수를 잘못 이해하여 계산한 경우\n- ⑤ 4: 인수분해 후 $(x+1)$ 대신 다른 식으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n- 극한값 계산 시 $\\frac{0}{0}$ 꼴 부정형이 나타나면 **반드시 인수분해나 다른 정리를 통해 부정형을 제거**해야 한다.\n- 인수분해는 제곱의 차, 합/차의 세제곱 등 기본 공식을 활용하여 빠르게 처리할 수 있어야 한다.",
