    "answer": 2,
    "explanation": "**[핵심 개념]**\n$x \\to \\infty$일 때 유리함수의 극한은 분자와 분모의 최고차항의 계수 비로 수렴합니다. 분자와 분모를 최고차항으로 나누거나, 최고차항만 비교하는 방법을 사용합니다.\n\n**[풀이]**\n\n**방법 1: 최고차항으로 나누기**\n\n$x \\to \\infty$일 때 분자, 분모 모두 무한대로 발산하므로 $\\frac{\\infty}{\\infty}$ 꼴입니다.\n\n분자와 분모를 최고차항인 $x^2$으로 나누면:\n\n$$\\lim_{x \\to \\infty} \\dfrac{4x^2 + 3x}{2x^2 - 1} = \\lim_{x \\to \\infty} \\dfrac{\\dfrac{4x^2}{x^2} + \\dfrac{3x}{x^2}}{\\dfrac{2x^2}{x^2} - \\dfrac{1}{x^2}}$$\n\n$$= \\lim_{x \\to \\infty} \\dfrac{4 + \\dfrac{3}{x}}{2 - \\dfrac{1}{x^2}}$$\n\n$x \\to \\infty$일 때, $\\dfrac{3}{x} \\to 0$이고 $\\dfrac{1}{x^2} \\to 0$이므로:\n\n$$= \\dfrac{4 + 0}{2 - 0} = \\dfrac{4}{2} = 2$$\n\n**방법 2: 최고차항 비교 (간편법)**\n\n분자와 분모의 최고차항만 추출하면:\n\n$$\\lim_{x \\to \\infty} \\dfrac{4x^2 + 3x}{2x^2 - 1} = \\lim_{x \\to \\infty} \\dfrac{4x^2}{2x^2} = \\dfrac{4}{2} = 2$$\n\n**[정답 확인]**\n분자와 분모의 최고차가 같은 $x^2$이므로, 그 계수의 비인 $\\dfrac{4}{2} = 2$가 극한값입니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않아 일반적인 오류를 분석하면:\n- **4를 선택하는 경우**: 분자의 최고차 계수만 고려한 실수\n- **0을 선택하는 경우**: 저차항들을 잘못 계산하거나 극한 개념을 오해한 경우\n- **무한대를 선택하는 경우**: 극한이 발산한다고 잘못 생각한 경우\n\n**[핵심 포인트]**\n**유리함수의 무한대 극한**: 분자와 분모의 최고차항의 차수가 같으면 그 계수의 비가 극한값입니다. $\\lim_{x \\to \\infty} \\dfrac{ax^n + \\cdots}{bx^n + \\cdots} = \\dfrac{a}{b}$",
