    "explanation": "**[핵심 개념]**\n극한값을 구할 때 직접 대입했을 때 $\\frac{0}{0}$ 꼴이 나오면 부정형입니다. 이 경우 분자와 분모를 인수분해하여 공통인수를 약분한 후 극한값을 구합니다. 이를 **인수분해를 이용한 부정형 해결**이라고 합니다.\n\n**[풀이]**\n\n**1단계: 직접 대입으로 부정형 확인**\n\n$x = 3$을 직접 대입하면:\n- 분자: $3^2 - 9 = 9 - 9 = 0$\n- 분모: $3^2 - 5(3) + 6 = 9 - 15 + 6 = 0$\n\n$\\frac{0}{0}$ 꼴의 부정형이므로 인수분해를 진행합니다.\n\n**2단계: 분자 인수분해**\n\n$$x^2 - 9 = (x+3)(x-3)$$\n\n**3단계: 분모 인수분해**\n\n$$x^2 - 5x + 6$$\n\n$x^2 - 5x + 6 = 0$의 근을 구하면: $(x-2)(x-3) = 0$이므로 $x = 2$ 또는 $x = 3$\n\n따라서:\n$$x^2 - 5x + 6 = (x-2)(x-3)$$\n\n**4단계: 공통인수 약분**\n\n$$\\lim_{x \\to 3} \\dfrac{x^2 - 9}{x^2 - 5x + 6} = \\lim_{x \\to 3} \\dfrac{(x+3)(x-3)}{(x-2)(x-3)}$$\n\n$x \\to 3$일 때 $x \\neq 3$이므로 $(x-3)$으로 약분 가능:\n\n$$= \\lim_{x \\to 3} \\dfrac{x+3}{x-2}$$\n\n**5단계: 극한값 계산**\n\n이제 부정형이 해결되었으므로 직접 대입:\n\n$$= \\dfrac{3+3}{3-2} = \\dfrac{6}{1} = 6$$\n\n**[정답 확인]**\n분자와 분모의 공통인수 $(x-3)$을 약분한 후 $x=3$을 대입하면 $\\frac{6}{1} = 6$이 되어 정답은 **③번**입니다.\n\n**[오답 분석]**\n- ① 2: 분모만 약분하여 $\\frac{6}{3}$로 계산한 경우\n- ② 4: 계산 과정에서 실수한 경우\n- ④ 8: 약분 과정을 생략하고 잘못 계산한 경우\n- ⑤ 10: $x+3$의 값만으로 계산한 경우\n\n**[핵심 포인트]**\n$\\frac{0}{0}$ 부정형은 반드시 **분자와 분모를 동시에 인수분해**하여 공통인수를 약분해야 합니다. 한쪽만 인수분해하거나 약분 없이 대입하면 오답이 됩니다.",
