    "explanation": "**[핵심 개념]**\n무한대로의 극한에서 유리함수의 극한값을 구할 때는 분자와 분모의 차수를 비교합니다.\n- 분자의 차수 > 분모의 차수 → 발산\n- 분자의 차수 = 분모의 차수 → 최고차 계수의 비\n- 분자의 차수 < 분모의 차수 → 0\n\n**[풀이]**\n\n$\\lim_{x \\to \\infty} \\dfrac{3x + 1}{x^2 + 2}$를 구하기 위해 분자와 분모의 차수를 확인합니다.\n\n**1단계: 차수 확인**\n- 분자: $3x + 1$ (1차)\n- 분모: $x^2 + 2$ (2차)\n- 분자의 차수(1) < 분모의 차수(2)\n\n**2단계: 분자와 분모를 분모의 최고차로 나누기**\n\n$$\\lim_{x \\to \\infty} \\dfrac{3x + 1}{x^2 + 2} = \\lim_{x \\to \\infty} \\dfrac{\\dfrac{3x}{x^2} + \\dfrac{1}{x^2}}{\\dfrac{x^2}{x^2} + \\dfrac{2}{x^2}}$$\n\n$$= \\lim_{x \\to \\infty} \\dfrac{\\dfrac{3}{x} + \\dfrac{1}{x^2}}{1 + \\dfrac{2}{x^2}}$$\n\n**3단계: 극한 계산**\n\n$x \\to \\infty$일 때:\n- $\\dfrac{3}{x} \\to 0$\n- $\\dfrac{1}{x^2} \\to 0$\n- $\\dfrac{2}{x^2} \\to 0$\n\n따라서:\n$$\\lim_{x \\to \\infty} \\dfrac{\\dfrac{3}{x} + \\dfrac{1}{x^2}}{1 + \\dfrac{2}{x^2}} = \\dfrac{0 + 0}{1 + 0} = \\dfrac{0}{1} = 0$$\n\n**[정답 확인]**\n분자의 차수가 분모의 차수보다 작으므로 극한값은 0입니다.\n\n**[오답 분석]**\n- ② 1: 분자와 분모의 최고차 계수의 비로 잘못 계산한 경우\n- ③ 3: 분자의 최고차 계수만 고려한 경우\n- ④ $\\frac{3}{2}$: 계수들의 비를 잘못 구한 경우\n- ⑤ 발산: 분자의 차수가 분모보다 크거나 같을 때의 경우로 착각\n\n**[핵심 포인트]**\n유리함수에서 $x \\to \\infty$일 때, **분자의 차수가 분모의 차수보다 작으면 극한값은 0**입니다. 이는 분모가 분자보다 더 빠르게 증가하기 때문입니다.",
