    "problem": "$\\lim_{x \\to 0} \\dfrac{\\sqrt{x+4} - 2}{x}$의 값을 구하시오. (답은 기약분수의 분자와 분모의 합으로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 5,
    "explanation": "**[핵심 개념]**\n$x \\to 0$일 때 $\\frac{0}{0}$ 꼴의 부정형 극한은 인수분해, 유리화, 로피탈의 정리 등으로 해결합니다. 이 문제는 분자가 무리식이므로 유리화(분자의 켤레식을 곱하기)를 사용하여 부정형을 제거합니다.\n\n**[풀이]**\n\n$x \\to 0$일 때 분자: $\\sqrt{0+4} - 2 = 2 - 2 = 0$, 분모: $0$이므로 $\\frac{0}{0}$ 꼴입니다.\n\n분자와 분모에 $\\sqrt{x+4} + 2$를 곱하여 유리화합니다.\n\n$$\\lim_{x \\to 0} \\frac{\\sqrt{x+4} - 2}{x} = \\lim_{x \\to 0} \\frac{(\\sqrt{x+4} - 2)(\\sqrt{x+4} + 2)}{x(\\sqrt{x+4} + 2)}$$\n\n분자를 전개합니다. $(a-b)(a+b) = a^2 - b^2$ 공식을 적용하면:\n\n$$= \\lim_{x \\to 0} \\frac{(\\sqrt{x+4})^2 - 2^2}{x(\\sqrt{x+4} + 2)}$$\n\n$$= \\lim_{x \\to 0} \\frac{x+4 - 4}{x(\\sqrt{x+4} + 2)}$$\n\n$$= \\lim_{x \\to 0} \\frac{x}{x(\\sqrt{x+4} + 2)}$$\n\n$x \\neq 0$이므로 $x$를 약분합니다:\n\n$$= \\lim_{x \\to 0} \\frac{1}{\\sqrt{x+4} + 2}$$\n\n이제 $x = 0$을 대입합니다:\n\n$$= \\frac{1}{\\sqrt{0+4} + 2} = \\frac{1}{\\sqrt{4} + 2} = \\frac{1}{2 + 2} = \\frac{1}{4}$$\n\n기약분수 $\\frac{1}{4}$의 분자는 1, 분모는 4이므로:\n\n$$\\text{분자 + 분모} = 1 + 4 = 5$$\n\n**[정답 확인]**\n유리화를 통해 부정형을 제거한 후 극한값 $\\frac{1}{4}$을 구했고, 분자와 분모의 합은 5입니다.\n\n**[오답 분석]**\n- 극한값 자체를 답으로 하는 경우 ($\\frac{1}{4}$를 선택): 문제에서 \"기약분수의 분자와 분모의 합\"을 구하라고 명시했으므로 틀렸습니다.\n- 유리화 없이 직접 계산하는 경우: $\\frac{0}{0}$ 꼴로 남아 계산 불가능합니다.\n\n**[핵심 포인트]**\n무리식을 포함한 극한에서는 **켤레식을 곱하여 유리화**하면 부정형이 해결됩니다. 또한 문제에서 요구하는 최종 답의 형태를 정확히 파악해야 합니다.",
