    "explanation": "**[핵심 개념]**\n$x \\to a$일 때 $\\frac{0}{0}$ 꼴의 부정형이 나타나면, 분자와 분모를 인수분해하여 공통인수를 약분한 후 극한값을 구합니다. 이는 인수분해를 이용한 극한 계산의 기본 방법입니다.\n\n**[풀이]**\n\n$x = 1$을 직접 대입하면:\n$$\\frac{1^3 - 1}{1^2 - 1} = \\frac{0}{0}$$\n\n$\\frac{0}{0}$ 꼴의 부정형이므로, 분자와 분모를 인수분해합니다.\n\n**분자 인수분해:**\n$$x^3 - 1 = (x-1)(x^2 + x + 1)$$\n\n**분모 인수분해:**\n$$x^2 - 1 = (x-1)(x+1)$$\n\n따라서:\n$$\\lim_{x \\to 1} \\dfrac{x^3 - 1}{x^2 - 1} = \\lim_{x \\to 1} \\dfrac{(x-1)(x^2 + x + 1)}{(x-1)(x+1)}$$\n\n$x \\to 1$일 때 $x \\neq 1$이므로 $(x-1)$으로 약분할 수 있습니다:\n$$= \\lim_{x \\to 1} \\dfrac{x^2 + x + 1}{x+1}$$\n\n이제 $x = 1$을 대입하면:\n$$= \\dfrac{1^2 + 1 + 1}{1+1} = \\dfrac{3}{2}$$\n\n**[정답 확인]**\n분자와 분모를 각각 인수분해하여 공통인수를 제거한 후 대입하면 $\\frac{3}{2}$을 얻으므로 정답은 ③입니다.\n\n**[오답 분석]**\n- ① $\\frac{1}{2}$: 분자만 인수분해하고 분모를 잘못 계산한 경우\n- ② $1$: 약분 후 분모의 극한값을 잘못 계산한 경우 ($x+1$이 2가 됨을 간과)\n- ④ $2$: 약분 후 분자의 극한값을 잘못 계산한 경우\n- ⑤ $3$: 분모를 무시하고 분자의 극한만 구한 경우\n\n**[핵심 포인트]**\n극한에서 $\\frac{0}{0}$ 꼴이 나타나면 **인수분해로 공통인수를 제거**하는 것이 핵심입니다. 특히 $a^3 - b^3 = (a-b)(a^2 + ab + b^2)$ 공식을 기억하세요.",
