    "answer": 2,
    "explanation": "**[핵심 개념]**\n$\\infty - \\infty$ 꼴의 부정형 극한을 다룰 때는 분자를 유리화(또는 적절한 변형)하여 계산합니다. \n일반적으로 $\\sqrt{A} - \\sqrt{B}$ 형태는 $\\frac{A-B}{\\sqrt{A}+\\sqrt{B}}$로 변형하여 계산합니다.\n\n**[풀이]**\n\n주어진 극한은 $x \\to \\infty$일 때 $\\sqrt{x^2 + 4x} - x$ 형태로, $\\infty - \\infty$ 꼴의 부정형입니다.\n\n**Step 1: 분자를 유리화**\n\n$\\sqrt{x^2 + 4x} - x$에 $\\frac{\\sqrt{x^2 + 4x} + x}{\\sqrt{x^2 + 4x} + x}$를 곱합니다.\n\n$$\\sqrt{x^2 + 4x} - x = \\frac{(\\sqrt{x^2 + 4x} - x)(\\sqrt{x^2 + 4x} + x)}{\\sqrt{x^2 + 4x} + x}$$\n\n**Step 2: 분자 정리**\n\n분자를 $(a-b)(a+b) = a^2 - b^2$ 공식으로 계산:\n\n$$= \\frac{(x^2 + 4x) - x^2}{\\sqrt{x^2 + 4x} + x} = \\frac{4x}{\\sqrt{x^2 + 4x} + x}$$\n\n**Step 3: 극한 계산**\n\n$x \\to \\infty$일 때, 분자와 분모를 $x$로 나눕니다.\n\n$$\\lim_{x \\to \\infty} \\frac{4x}{\\sqrt{x^2 + 4x} + x}$$\n\n$x > 0$이므로 $\\sqrt{x^2 + 4x} = \\sqrt{x^2(1 + \\frac{4}{x})} = x\\sqrt{1 + \\frac{4}{x}}$\n\n$$= \\lim_{x \\to \\infty} \\frac{4x}{x\\sqrt{1 + \\frac{4}{x}} + x} = \\lim_{x \\to \\infty} \\frac{4x}{x(\\sqrt{1 + \\frac{4}{x}} + 1)}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{4}{\\sqrt{1 + \\frac{4}{x}} + 1}$$\n\n**Step 4: 극한값 계산**\n\n$x \\to \\infty$일 때, $\\frac{4}{x} \\to 0$이므로:\n\n$$= \\frac{4}{\\sqrt{1 + 0} + 1} = \\frac{4}{1 + 1} = \\frac{4}{2} = 2$$\n\n**[정답 확인]**\n유리화를 통해 부정형을 해결하면 $\\frac{4x}{x(\\sqrt{1 + \\frac{4}{x}} + 1)}$로 정리되고, $x \\to \\infty$일 때 $\\frac{4}{2} = 2$가 됩니다.\n\n**[오답 분석]**\n- ① 0: 유리화 전 $\\infty - \\infty$를 단순히 0으로 계산한 오류\n- ② 1: 분자를 $4x$가 아닌 다른 값으로 잘못 계산한 경우\n- ④ 4: 분모의 +1을 누락하고 $\\frac{4}{\\sqrt{1}}$로만 계산한 오류\n- ⑤ 발산: 유리화 없이 무한대로 발산한다고 잘못 판단\n\n**[핵심 포인트]**\n1. $\\infty - \\infty$ 꼴은 반드시 유리화(또는 인수분해)로 부정형을 해결해야 합니다.\n2. $\\sqrt{x^2 + ax}$는 $x\\sqrt{1 + \\frac{a}{x}}$로 변형하여 극한을 구합니다.",
