    "type": "극한",
    "problem": "$\\lim_{x \\to 2} \\dfrac{x^2 - 4}{x^3 - 8}$의 값을 구하시오. (답은 기약분수의 분자와 분모의 합으로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n$x \\to a$일 때 $\\frac{0}{0}$ 꼴의 부정형이 나타나면, 분자와 분모를 인수분해하여 공통인수를 약분한 후 극한값을 구합니다. 또는 로피탈의 정리를 사용할 수 있습니다.\n\n**[풀이]**\n\n$x = 2$를 직접 대입하면:\n$$\\frac{2^2 - 4}{2^3 - 8} = \\frac{4-4}{8-8} = \\frac{0}{0}$$\n\n$\\frac{0}{0}$ 꼴의 부정형이므로 인수분해를 이용합니다.\n\n**분자 인수분해:**\n$$x^2 - 4 = (x-2)(x+2)$$\n\n**분모 인수분해:**\n$$x^3 - 8 = x^3 - 2^3 = (x-2)(x^2 + 2x + 4)$$\n\n(합차공식: $a^3 - b^3 = (a-b)(a^2+ab+b^2)$)\n\n**공통인수 약분:**\n$$\\lim_{x \\to 2} \\frac{x^2 - 4}{x^3 - 8} = \\lim_{x \\to 2} \\frac{(x-2)(x+2)}{(x-2)(x^2 + 2x + 4)}$$\n\n$x \\to 2$일 때, $x \\neq 2$이므로 $(x-2)$로 약분:\n$$= \\lim_{x \\to 2} \\frac{x+2}{x^2 + 2x + 4}$$\n\n**극한값 계산:**\n$$= \\frac{2+2}{2^2 + 2 \\cdot 2 + 4} = \\frac{4}{4 + 4 + 4} = \\frac{4}{12} = \\frac{1}{3}$$\n\n**기약분수로 표현:**\n$$\\frac{1}{3}$$\n\n분자: $1$, 분모: $3$\n\n**분자와 분모의 합:** $1 + 3 = 4$\n\n**[정답 확인]**\n인수분해를 통해 공통인수를 약분한 후 직접 대입하면 $\\frac{1}{3}$을 얻고, 이 기약분수의 분자와 분모의 합은 $1+3=4$입니다.\n\n**[오답 분석]**\n- $\\frac{0}{0}$ 꼴을 무시하고 직접 대입하면 답을 얻을 수 없습니다.\n- 분모를 $(x-2)(x+2)^2$으로 잘못 인수분해하면 다른 답이 나옵니다.\n- 약분 후 $\\frac{4}{12}$를 더 간단히 하지 않으면 기약분수가 아닙니다.\n\n**[핵심 포인트]**\n1. 극한에서 $\\frac{0}{0}$ 꼴이 나타나면 **인수분해**로 공통인수를 제거해야 합니다.\n2. 3차식 인수분해는 합차공식 $a^3 - b^3 = (a-b)(a^2+ab+b^2)$를 항상 기억하세요.",
