    "problem": "다항함수 $f(x)$가 $\\lim_{x \\to 1} \\dfrac{f(x)}{x-1} = 5$를 만족할 때, $f(1)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n극한식 $\\lim_{x \\to a} \\dfrac{f(x)}{x-a} = L$ (단, $L \\neq 0$)이 수렴하려면 분자가 0으로 수렴해야 합니다. 분자가 0이 아닌 값으로 수렴하면 분모가 0으로 가므로 극한은 발산하기 때문입니다. 따라서 $\\lim_{x \\to a} f(x) = 0$이어야 하고, 이는 $f(a) = 0$을 의미합니다.\n\n**[풀이]**\n\n주어진 극한식을 분석합니다:\n$$\\lim_{x \\to 1} \\dfrac{f(x)}{x-1} = 5$$\n\n이 극한이 유한한 값 5로 수렴한다는 것이 핵심입니다.\n\n**Step 1: 분자의 극한값 결정**\n\n$x \\to 1$일 때, 분모 $(x-1) \\to 0$입니다.\n\n극한값이 5(유한한 값)로 수렴하려면, 분자도 반드시 0으로 수렴해야 합니다.\n\n만약 $\\lim_{x \\to 1} f(x) \\neq 0$이면:\n- $\\lim_{x \\to 1} f(x) = c$ (단, $c \\neq 0$)인 경우\n- $\\lim_{x \\to 1} \\dfrac{f(x)}{x-1} = \\dfrac{c}{0}$ → 발산 (극한이 존재하지 않음)\n\n**Step 2: 연속함수의 성질 적용**\n\n$f(x)$는 다항함수이므로 모든 점에서 연속입니다.\n\n따라서:\n$$\\lim_{x \\to 1} f(x) = f(1)$$\n\n**Step 3: 결론**\n\nStep 1에서 $\\lim_{x \\to 1} f(x) = 0$이어야 하므로:\n$$f(1) = 0$$\n\n**[정답 확인]**\n\n다항함수 $f(x)$에서 분수 극한 $\\lim_{x \\to 1} \\dfrac{f(x)}{x-1}$이 유한한 값으로 수렴하려면 반드시 $f(1) = 0$이어야 하며, 이는 분자가 $(x-1)$을 인수로 가져야 함을 의미합니다.\n\n**[오답 분석]**\n\n객관식 선지가 제시되지 않았으나, 학생들이 범할 수 있는 오류:\n- $f(1) = 5$로 답하는 경우: 극한값 5를 $f(1)$의 값으로 착각\n- $f(1) = 1$로 답하는 경우: 극한 조건을 제대로 분석하지 못함\n\n**[핵심 포인트]**\n\n극한 $\\lim_{x \\to a} \\dfrac{f(x)}{x-a}$가 0이 아닌 유한값으로 수렴 $\\Rightarrow$ **반드시 $f(a) = 0$** (분자가 분모의 인수를 가져야 함)",
