    "answer": 1,
    "explanation": "**[핵심 개념]**\n극한값이 존재하려면 분모가 0으로 갈 때 분자도 0으로 가야 합니다. $x \\to 1$일 때 분모 $(x-1) \\to 0$이므로, 극한값이 유한한 값 10이 되려면 분자도 0으로 가야 합니다. 이를 **0/0 꼴의 부정형**이라 하며, 이 조건으로부터 상수를 결정할 수 있습니다.\n\n**[풀이]**\n\n**1단계: 분자가 x=1에서 0이 되는 조건**\n\n극한값이 존재하고 유한하려면:\n$$\\lim_{x \\to 1} \\frac{ax^2 + bx - 3}{x - 1} = 10$$\n\n$x \\to 1$일 때 분모 $(x-1) \\to 0$이므로, 분자도 0으로 가야 합니다.\n$$a(1)^2 + b(1) - 3 = 0$$\n$$a + b - 3 = 0$$\n$$a + b = 3 \\quad \\cdots (1)$$\n\n**2단계: 로피탈의 정리 또는 인수분해를 이용**\n\n조건 (1)에서 $b = 3 - a$이므로, 분자를 다시 쓰면:\n$$ax^2 + bx - 3 = ax^2 + (3-a)x - 3$$\n\n분자가 $(x-1)$을 인수로 가지므로:\n$$ax^2 + (3-a)x - 3 = (x-1)(ax + c)$$\n\n전개하면:\n$$(x-1)(ax + c) = ax^2 + cx - ax - c = ax^2 + (c-a)x - c$$\n\n계수를 비교하면:\n- $x$의 계수: $c - a = 3 - a$ → $c = 3$\n- 상수항: $-c = -3$ → $c = 3$ ✓\n\n따라서:\n$$ax^2 + (3-a)x - 3 = (x-1)(ax + 3)$$\n\n**3단계: 극한값 계산**\n\n$$\\lim_{x \\to 1} \\frac{(x-1)(ax + 3)}{x - 1} = \\lim_{x \\to 1} (ax + 3)$$\n\n$$= a(1) + 3 = a + 3 = 10$$\n\n$$a = 7$$\n\n**4단계: b 구하기**\n\n조건 (1)에서:\n$$b = 3 - a = 3 - 7 = -4$$\n\n**5단계: a + b 확인**\n\n$$a + b = 7 + (-4) = 3$$\n\n**[정답 확인]**\n분자가 $x=1$에서 0이 되는 조건 $a+b=3$과 극한값이 10인 조건 $a+3=10$을 연립하면 $a=7, b=-4$를 얻어 $a+b=3$이 됩니다.\n\n**[오답 분석]**\n- ① 1: $a+b=3$이 아닌 다른 값으로 잘못 계산\n- ③ 5: 극한값 계산에서 실수하여 $a+3=12$로 잘못 설정\n- ④ 7: $a$값만 선택한 오류\n- ⑤ 9: 분자 조건을 무시하고 극한값만 사용한 오류\n\n**[핵심 포인트]**\n분모가 0으로 가는 극한 문제에서는 반드시 **분자도 0이 되어야 한다**는 조건을 먼저 세우고, 이를 통해 상수 간의 관계식을 얻은 후 극한값 조건을 적용해야 합니다.",
