    "answer": 2,
    "explanation": "**[핵심 개념]**\n$\\infty - \\infty$ 꼴의 부정형 극한을 다룰 때는 유리화(분모 실수화) 기법을 사용합니다. $\\sqrt{A} - \\sqrt{B}$ 형태는 $\\frac{A-B}{\\sqrt{A}+\\sqrt{B}}$로 변환하여 계산합니다. 또한 $x \\to \\infty$일 때 분자와 분모의 최고차항을 비교하여 극한값을 구합니다.\n\n**[풀이]**\n\n주어진 극한은 $x \\to \\infty$일 때 $\\sqrt{4x^2 + 6x + 1} - 2x$ 형태로, $\\infty - \\infty$ 꼴의 부정형입니다.\n\n**Step 1: 유리화를 위해 켤레식을 곱하고 나눕니다.**\n\n$$\\lim_{x \\to \\infty} (\\sqrt{4x^2 + 6x + 1} - 2x) = \\lim_{x \\to \\infty} \\frac{(\\sqrt{4x^2 + 6x + 1} - 2x)(\\sqrt{4x^2 + 6x + 1} + 2x)}{\\sqrt{4x^2 + 6x + 1} + 2x}$$\n\n**Step 2: 분자를 $(a-b)(a+b) = a^2 - b^2$ 공식으로 전개합니다.**\n\n분자 $= (\\sqrt{4x^2 + 6x + 1})^2 - (2x)^2 = 4x^2 + 6x + 1 - 4x^2 = 6x + 1$\n\n따라서:\n$$\\lim_{x \\to \\infty} \\frac{6x + 1}{\\sqrt{4x^2 + 6x + 1} + 2x}$$\n\n**Step 3: $x \\to \\infty$일 때 분모를 정리합니다.**\n\n분모에서 $\\sqrt{4x^2 + 6x + 1}$를 인수분해하면:\n\n$$\\sqrt{4x^2 + 6x + 1} = \\sqrt{x^2(4 + \\frac{6}{x} + \\frac{1}{x^2})} = x\\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}}$$\n\n($x > 0$이므로)\n\n따라서 분모는:\n$$x\\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}} + 2x = x\\left(\\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}} + 2\\right)$$\n\n**Step 4: 극한을 계산합니다.**\n\n$$\\lim_{x \\to \\infty} \\frac{6x + 1}{x\\left(\\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}} + 2\\right)} = \\lim_{x \\to \\infty} \\frac{6 + \\frac{1}{x}}{\\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}} + 2}$$\n\n$x \\to \\infty$일 때, $\\frac{1}{x} \\to 0$, $\\frac{6}{x} \\to 0$, $\\frac{1}{x^2} \\to 0$이므로:\n\n$$= \\frac{6 + 0}{\\sqrt{4 + 0 + 0} + 2} = \\frac{6}{\\sqrt{4} + 2} = \\frac{6}{2 + 2} = \\frac{6}{4} = \\frac{3}{2}$$\n\n**[정답 확인]**\n유리화를 통해 $\\infty - \\infty$ 꼴을 제거한 후, 분자가 $6x + 1$, 분모가 $x\\left(\\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}} + 2\\right)$로 정리되어 $\\frac{3}{2}$를 얻습니다.\n\n**[오답 분석]**\n- ① $\\frac{1}{2}$: 분모를 $4x$로 잘못 계산한 경우\n- ② $1$: 분모를 $6x$로 잘못 계산한 경우\n- ④ $2$: 유리화 과정에서 계산 실수가 있는 경우\n- ⑤ $3$: 분모를 $2x$로만 계산한 경우\n\n**[핵심 포인트]**\n$\\sqrt{ax^2 + bx + c} - dx$ 형태의 극한은 **유리화를 먼저 진행**하고, 분모의 최고차항이 $x$가 되도록 인수분해하여 계산합니다. 분자의 일차항 계수와 분모의 최고차항 계수의 비가 극한값이 됩니다.",
