    "answer": -12,
    "explanation": "**[핵심 개념]**\n\n극한값이 존재하려면 분모가 0으로 수렴할 때 분자도 0으로 수렴해야 합니다(부정형 $\\frac{0}{0}$). 이 조건을 이용하여 미지수를 구한 후, 로피탈의 정리 또는 인수분해를 통해 극한값을 계산합니다.\n\n**[풀이]**\n\n$\\lim_{x \\to 2} \\dfrac{f(x)}{x^2 - 4} = 3$이 수렴하려면, $x \\to 2$일 때 분모 $x^2 - 4 \\to 0$이므로 분자도 0으로 수렴해야 합니다.\n\n따라서 $f(2) = 0$이어야 합니다.\n\n$$f(2) = 4 + 2a + b = 0$$\n$$2a + b = -4 \\cdots (1)$$\n\n이제 극한값 조건을 이용합니다. 분모를 인수분해하면:\n$$x^2 - 4 = (x-2)(x+2)$$\n\n$f(2) = 0$이므로 $f(x) = (x-2) \\cdot q(x)$로 인수분해됩니다.\n\n$$f(x) = x^2 + ax + b = (x-2)(x - r)$$\n\n전개하면:\n$$x^2 + ax + b = x^2 - (2+r)x + 2r$$\n\n계수를 비교하면:\n- $a = -(2+r)$\n- $b = 2r$\n\n극한값을 계산하면:\n$$\\lim_{x \\to 2} \\dfrac{f(x)}{x^2-4} = \\lim_{x \\to 2} \\dfrac{(x-2)(x-r)}{(x-2)(x+2)}$$\n\n$$= \\lim_{x \\to 2} \\dfrac{x-r}{x+2} = \\dfrac{2-r}{4} = 3$$\n\n따라서:\n$$2 - r = 12$$\n$$r = -10$$\n\n이를 이용하여:\n- $b = 2r = 2(-10) = -20$\n- $a = -(2+r) = -(2-10) = 8$\n\n검증: $2a + b = 2(8) + (-20) = 16 - 20 = -4$ ✓\n\n따라서:\n$$a + b = 8 + (-20) = -12$$\n\n**[정답 확인]**\n\n$f(x) = x^2 + 8x - 20 = (x-2)(x+10)$일 때, $\\lim_{x \\to 2} \\dfrac{(x-2)(x+10)}{(x-2)(x+2)} = \\lim_{x \\to 2} \\dfrac{x+10}{x+2} = \\dfrac{12}{4} = 3$이므로 모든 조건을 만족합니다.\n\n**[오답 분석]**\n\n객관식이 아니므로 해당 사항 없음.\n\n**[핵심 포인트]**\n\n1. 극한값이 존재하는 부정형에서는 먼저 **$f(2) = 0$ 조건**을 찾아야 합니다.\n2. 이 조건으로 $a, b$ 사이의 관계식을 세운 후, 극한값 조건으로 미지수를 구하는 **두 단계 풀이**가 핵심입니다.",
