    "answer": 1,
    "explanation": "**[핵심 개념]**\n$\\infty - \\infty$ 꼴의 부정형 극한을 구할 때는 분자를 유리화(conjugate)하는 방법을 사용합니다. $\\sqrt{A} - \\sqrt{B}$ 형태일 때, $\\frac{\\sqrt{A} - \\sqrt{B}}{1} \\times \\frac{\\sqrt{A} + \\sqrt{B}}{\\sqrt{A} + \\sqrt{B}}$로 곱하면 분자가 $A - B$가 되어 식을 간단히 할 수 있습니다.\n\n**[풀이]**\n\n주어진 극한: $\\lim_{x \\to \\infty} \\left( \\sqrt{x^2 + 3x} - \\sqrt{x^2 - x} \\right)$\n\n**Step 1: 분자의 유리화**\n\n분자와 분모에 $\\sqrt{x^2 + 3x} + \\sqrt{x^2 - x}$를 곱합니다.\n\n$$\\lim_{x \\to \\infty} \\frac{\\left(\\sqrt{x^2 + 3x} - \\sqrt{x^2 - x}\\right)\\left(\\sqrt{x^2 + 3x} + \\sqrt{x^2 - x}\\right)}{\\sqrt{x^2 + 3x} + \\sqrt{x^2 - x}}$$\n\n**Step 2: 분자 계산**\n\n$(A - B)(A + B) = A^2 - B^2$ 공식을 적용하면:\n\n$$= \\lim_{x \\to \\infty} \\frac{(x^2 + 3x) - (x^2 - x)}{\\sqrt{x^2 + 3x} + \\sqrt{x^2 - x}}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{x^2 + 3x - x^2 + x}{\\sqrt{x^2 + 3x} + \\sqrt{x^2 - x}}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{4x}{\\sqrt{x^2 + 3x} + \\sqrt{x^2 - x}}$$\n\n**Step 3: 분모 정리**\n\n$x \\to \\infty$일 때, 분모에서 $\\sqrt{x^2 + 3x}$와 $\\sqrt{x^2 - x}$를 정리합니다.\n\n$$\\sqrt{x^2 + 3x} = |x|\\sqrt{1 + \\frac{3}{x}} = x\\sqrt{1 + \\frac{3}{x}}$$ ($x > 0$일 때)\n\n$$\\sqrt{x^2 - x} = x\\sqrt{1 - \\frac{1}{x}}$$\n\n따라서 분모는:\n$$x\\sqrt{1 + \\frac{3}{x}} + x\\sqrt{1 - \\frac{1}{x}} = x\\left(\\sqrt{1 + \\frac{3}{x}} + \\sqrt{1 - \\frac{1}{x}}\\right)$$\n\n**Step 4: 극한 계산**\n\n$$= \\lim_{x \\to \\infty} \\frac{4x}{x\\left(\\sqrt{1 + \\frac{3}{x}} + \\sqrt{1 - \\frac{1}{x}}\\right)}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{4}{\\sqrt{1 + \\frac{3}{x}} + \\sqrt{1 - \\frac{1}{x}}}$$\n\n$x \\to \\infty$일 때, $\\frac{3}{x} \\to 0$, $\\frac{1}{x} \\to 0$이므로:\n\n$$= \\frac{4}{\\sqrt{1 + 0} + \\sqrt{1 - 0}} = \\frac{4}{1 + 1} = \\frac{4}{2} = 2$$\n\n**[정답 확인]**\n유리화를 통해 $\\infty - \\infty$ 꼴을 $\\frac{4x}{x(\\sqrt{1 + \\frac{3}{x}} + \\sqrt{1 - \\frac{1}{x}})}$로 변환하면, 극한값이 $\\frac{4}{2} = 2$로 명확히 구해집니다.\n\n**[오답 분석]**\n- ① 1: 분자 $4x$를 $2x$로 잘못 계산한 경우\n- ③ 3: 분모를 $\\sqrt{1 + \\frac{3}{x}} + \\sqrt{1 - \\frac{1}{x}} \\approx 1.33...$으로 근사하여 $\\frac{4}{1.33} \\approx 3$으로 잘못 계산\n- ④ 4: 분모의 극한값을 1로만 계산한 경우 (한 개의 제곱근만 고려)\n- ⑤ 발산: 유리화 없이 직접 극한을 구하려 한 경우\n\n**[핵심 포인트]**\n1. $\\infty - \\infty$ 꼴은 반드시 유리화하여 정확한 형태로 변환해야 합니다.\n2. $x \\to \\infty$일 때, $\\sqrt{x^2 + ax} = x\\sqrt{1 + \\frac{a}{x}} \\to x$임을 이용하여 최고차항으로 인수분해하는 것이 중요합니다.",
