    "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\dfrac{f(x) - 2x^3}{x^2} = 3$, $\\lim_{x \\to 0} \\dfrac{f(x)}{x} = -1$을 만족할 때, $f(1)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n다항함수의 차수와 계수를 극한 조건으로부터 결정하는 문제입니다. \n\n1) $\\lim_{x \\to \\infty} \\frac{f(x) - 2x^3}{x^2} = 3$ : $f(x)$의 최고차항이 $2x^3$이고, 그 다음 차수가 $x^2$항이 있음을 의미\n2) $\\lim_{x \\to 0} \\frac{f(x)}{x} = -1$ : $f(x)$가 $x$를 인수로 가지며, $f(0) = 0$이고 $f'(0) = -1$을 의미\n\n**[풀이]**\n\n**1단계: 첫 번째 극한 조건 분석**\n\n$$\\lim_{x \\to \\infty} \\frac{f(x) - 2x^3}{x^2} = 3$$\n\n이 극한이 수렴하려면 $f(x)$의 최고차항이 $2x^3$이어야 합니다. \n\n$f(x) = 2x^3 + ax^2 + bx + c$ (단, $a, b, c$는 상수)로 놓으면:\n\n$$\\lim_{x \\to \\infty} \\frac{2x^3 + ax^2 + bx + c - 2x^3}{x^2} = \\lim_{x \\to \\infty} \\frac{ax^2 + bx + c}{x^2} = a = 3$$\n\n따라서 $a = 3$이고, $f(x) = 2x^3 + 3x^2 + bx + c$\n\n**2단계: 두 번째 극한 조건 분석**\n\n$$\\lim_{x \\to 0} \\frac{f(x)}{x} = -1$$\n\n이 극한이 존재하려면 $f(0) = 0$이어야 합니다:\n\n$$f(0) = 2(0)^3 + 3(0)^2 + b(0) + c = c = 0$$\n\n따라서 $c = 0$이고, $f(x) = 2x^3 + 3x^2 + bx$\n\n이제:\n$$\\lim_{x \\to 0} \\frac{f(x)}{x} = \\lim_{x \\to 0} \\frac{2x^3 + 3x^2 + bx}{x} = \\lim_{x \\to 0} (2x^2 + 3x + b) = b = -1$$\n\n따라서 $b = -1$\n\n**3단계: $f(x)$ 결정 및 $f(1)$ 계산**\n\n$$f(x) = 2x^3 + 3x^2 - x$$\n\n$$f(1) = 2(1)^3 + 3(1)^2 - 1 = 2 + 3 - 1 = 4$$\n\n**[정답 확인]**\n\n$f(x) = 2x^3 + 3x^2 - x$일 때, $\\lim_{x \\to \\infty} \\frac{f(x) - 2x^3}{x^2} = \\lim_{x \\to \\infty} \\frac{3x^2 - x}{x^2} = 3$ ✓ 이고, $\\lim_{x \\to 0} \\frac{f(x)}{x} = \\lim_{x \\to 0} (2x^2 + 3x - 1) = -1$ ✓ 이므로 두 조건을 모두 만족합니다.\n\n**[핵심 포인트]**\n\n- 극한 조건으로부터 다항함수의 계수를 단계적으로 결정할 때, 최고차항부터 낮은 차수로 내려가며 분석합니다.\n- $\\lim_{x \\to 0} \\frac{f(x)}{x}$가 존재하면 $f(0) = 0$이어야 하며, 이 극한값은 $f'(0)$과 같습니다.",
