    "answer": 1,
    "explanation": "**[핵심 개념]**\n$x \\to a$일 때 $\\frac{0}{0}$ 꼴의 부정형이 나타나면, 분자와 분모를 인수분해하거나 유리화하여 약분해야 한다. 특히 제곱근이 포함된 식은 분자의 켤레식을 곱하여 유리화하는 방법이 효과적이다.\n\n**[풀이]**\n\n먼저 $x = 1$을 직접 대입하면:\n$$\\frac{\\sqrt{3(1)+1} - 2}{1^2 - 1} = \\frac{\\sqrt{4} - 2}{0} = \\frac{2-2}{0} = \\frac{0}{0}$$\n\n$\\frac{0}{0}$ 꼴이므로 유리화를 진행한다.\n\n분자 $\\sqrt{3x+1} - 2$의 켤레식 $\\sqrt{3x+1} + 2$를 분자와 분모에 곱한다:\n\n$$\\lim_{x \\to 1} \\frac{\\sqrt{3x+1} - 2}{x^2 - 1} = \\lim_{x \\to 1} \\frac{(\\sqrt{3x+1} - 2)(\\sqrt{3x+1} + 2)}{(x^2 - 1)(\\sqrt{3x+1} + 2)}$$\n\n분자를 $(a-b)(a+b) = a^2 - b^2$ 공식으로 전개:\n$$= \\lim_{x \\to 1} \\frac{(3x+1) - 4}{(x^2 - 1)(\\sqrt{3x+1} + 2)}$$\n\n$$= \\lim_{x \\to 1} \\frac{3x - 3}{(x^2 - 1)(\\sqrt{3x+1} + 2)}$$\n\n분자를 인수분해: $3x - 3 = 3(x-1)$\n\n분모를 인수분해: $x^2 - 1 = (x-1)(x+1)$\n\n$$= \\lim_{x \\to 1} \\frac{3(x-1)}{(x-1)(x+1)(\\sqrt{3x+1} + 2)}$$\n\n$(x-1)$로 약분:\n$$= \\lim_{x \\to 1} \\frac{3}{(x+1)(\\sqrt{3x+1} + 2)}$$\n\n이제 $x = 1$을 대입:\n$$= \\frac{3}{(1+1)(\\sqrt{3(1)+1} + 2)} = \\frac{3}{2(\\sqrt{4} + 2)} = \\frac{3}{2(2+2)} = \\frac{3}{2 \\times 4} = \\frac{3}{8}$$\n\n**[정답 확인]**\n유리화를 통해 약분 가능한 형태로 변환한 후 극한을 계산하면 $\\frac{3}{8}$이 나온다.\n\n**[오답 분석]**\n- ① $\\frac{1}{8}$: 분모의 2를 곱하지 않은 경우\n- ③ $\\frac{1}{4}$: 분자를 올바르게 유리화하지 않은 경우\n- ④ $\\frac{3}{4}$: 분모에서 $x+1$만 계산하고 켤레식 항을 빼먹은 경우\n- ⑤ $\\frac{3}{2}$: 분모의 $(x+1)$을 약분하지 않은 경우\n\n**[핵심 포인트]**\n제곱근이 포함된 $\\frac{0}{0}$ 꼴 극한은 켤레식을 이용한 유리화가 필수이다. 유리화 후 인수분해로 약분 가능한 항을 찾아내는 것이 핵심이다.",
