    "_type": "limit",
    "type": "극한",
    "problem": "$\\lim_{x \\to \\infty} \\left( \\sqrt{x^2 + ax + 3} - x \\right) = 2$를 만족하는 상수 $a$의 값은?",
    "answerType": "choice",
