    "answer": 3,
    "explanation": "**[핵심 개념]**\n$\\infty - \\infty$ 꼴의 부정형 극한을 구할 때는 유리화(분자의 유리화)를 이용합니다. $\\sqrt{A} - B$ 형태일 때, $\\frac{(\\sqrt{A} - B)(\\sqrt{A} + B)}{\\sqrt{A} + B} = \\frac{A - B^2}{\\sqrt{A} + B}$로 변형하여 계산합니다.\n\n**[풀이]**\n\n주어진 극한식을 정리하기 위해 분자를 유리화합니다.\n\n$$\\lim_{x \\to \\infty} \\left( \\sqrt{x^2 + ax + 3} - x \\right)$$\n\n분자와 분모에 $\\sqrt{x^2 + ax + 3} + x$를 곱합니다:\n\n$$= \\lim_{x \\to \\infty} \\frac{(\\sqrt{x^2 + ax + 3} - x)(\\sqrt{x^2 + ax + 3} + x)}{\\sqrt{x^2 + ax + 3} + x}$$\n\n분자를 전개하면:\n\n$$= \\lim_{x \\to \\infty} \\frac{(x^2 + ax + 3) - x^2}{\\sqrt{x^2 + ax + 3} + x}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{ax + 3}{\\sqrt{x^2 + ax + 3} + x}$$\n\n$x \\to \\infty$일 때, 분자와 분모를 $x$로 나눕니다:\n\n$$= \\lim_{x \\to \\infty} \\frac{a + \\frac{3}{x}}{\\sqrt{1 + \\frac{a}{x} + \\frac{3}{x^2}} + 1}$$\n\n$x \\to \\infty$일 때, $\\frac{3}{x} \\to 0$, $\\frac{a}{x} \\to 0$, $\\frac{3}{x^2} \\to 0$이므로:\n\n$$= \\frac{a + 0}{\\sqrt{1 + 0 + 0} + 1} = \\frac{a}{1 + 1} = \\frac{a}{2}$$\n\n주어진 조건에서 이 극한값이 2이므로:\n\n$$\\frac{a}{2} = 2$$\n\n$$a = 4$$\n\n**[정답 확인]**\n$a = 4$일 때 $\\lim_{x \\to \\infty} \\frac{4x + 3}{\\sqrt{x^2 + 4x + 3} + x} = \\frac{4}{2} = 2$가 성립합니다.\n\n**[오답 분석]**\n- ① $a = 1$: $\\frac{1}{2} = 2$ (거짓)\n- ② $a = 2$: $\\frac{2}{2} = 1 \\neq 2$ (거짓)\n- ③ $a = 3$: $\\frac{3}{2} = 1.5 \\neq 2$ (거짓)\n- ⑤ $a = 5$: $\\frac{5}{2} = 2.5 \\neq 2$ (거짓)\n\n**[핵심 포인트]**\n$\\infty - \\infty$ 꼴의 극한에서는 **유리화를 통해 분자를 정리**하는 것이 핵심입니다. 유리화 후 최고차 항으로 분자·분모를 나누면 극한값을 쉽게 구할 수 있습니다.",
