    "problem": "함수 $f(x) = \\begin{cases} 2x + 1 & (x \\neq 1) \\\\ 5 & (x = 1) \\end{cases}$이 $x = 1$에서 연속인지 판별하시오. 연속이면 1, 불연속이면 0으로 답하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n함수 $f(x)$가 $x = a$에서 연속이기 위한 조건은 다음 세 가지를 모두 만족해야 합니다.\n\n1) $f(a)$가 정의되어 있다.\n2) $\\lim_{x \\to a} f(x)$가 존재한다.\n3) $\\lim_{x \\to a} f(x) = f(a)$\n\n이 중 하나라도 만족하지 않으면 불연속입니다.\n\n**[풀이]**\n\n주어진 함수에서 $x = 1$에서의 연속성을 판별합니다.\n\n**1단계: $f(1)$ 확인**\n\n함수의 정의에 따라 $x = 1$일 때:\n$$f(1) = 5$$\n\n따라서 함수값이 정의되어 있습니다. ✓\n\n**2단계: $\\lim_{x \\to 1} f(x)$ 계산**\n\n$x \\neq 1$인 근처에서 $f(x) = 2x + 1$이므로:\n\n$$\\lim_{x \\to 1} f(x) = \\lim_{x \\to 1} (2x + 1) = 2(1) + 1 = 3$$\n\n따라서 극한값이 존재합니다. ✓\n\n**3단계: $\\lim_{x \\to 1} f(x)$와 $f(1)$ 비교**\n\n$$\\lim_{x \\to 1} f(x) = 3 \\neq 5 = f(1)$$\n\n극한값과 함수값이 다릅니다. ✗\n\n연속성의 세 조건 중 세 번째 조건을 만족하지 않으므로, 함수는 $x = 1$에서 **불연속**입니다.\n\n**[정답 확인]**\n\n극한값 3과 함수값 5가 일치하지 않으므로 $x = 1$에서 불연속이며, 따라서 답은 **0**입니다.\n\n**[오답 분석]**\n\n- **답 1 (연속)**: 함수값은 정의되어 있고 극한값도 존재하지만, 둘이 같지 않아야 연속입니다. 세 조건을 모두 만족하지 못하므로 오답입니다.\n\n**[핵심 포인트]**\n\n함수의 정의역이 나뉘어진 경우, **극한값과 함수값을 반드시 비교**해야 합니다. 함수값이 정의되어 있고 극한이 존재해도 두 값이 같지 않으면 불연속입니다. (이를 '제거 가능한 불연속'이라 하며, 점프 불연속의 한 종류입니다.)",
