    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n함수 $f(x)$가 $x = a$에서 연속이 되려면 다음 **세 조건**을 모두 만족해야 합니다:\n\n1. $f(a)$가 정의되어 있어야 함 (함수값 존재)\n2. $\\lim_{x \\to a} f(x)$가 존재해야 함 (좌극한 = 우극한)\n3. $\\lim_{x \\to a} f(x) = f(a)$ (극한값 = 함수값)\n\n**[풀이]**\n\n$x = 2$에서 연속성을 판정하기 위해 세 조건을 차례로 확인합니다.\n\n**조건 1: 함수값 $f(2)$의 존재성**\n\n주어진 함수의 정의에서 $x = 2$일 때:\n$$f(2) = 5$$\n\n함수값이 정의되어 있으므로 조건 1을 만족합니다. ✓\n\n**조건 2: 극한값의 존재성 (좌극한과 우극한이 같은가)**\n\n좌극한 ($x \\to 2^-$, 즉 $x < 2$에서 접근):\n$$\\lim_{x \\to 2^-} f(x) = \\lim_{x \\to 2^-} (x^2 + 1) = 2^2 + 1 = 5$$\n\n우극한 ($x \\to 2^+$, 즉 $x > 2$에서 접근):\n$$\\lim_{x \\to 2^+} f(x) = \\lim_{x \\to 2^+} (3x - 1) = 3(2) - 1 = 5$$\n\n좌극한 = 우극한 = 5이므로 극한값이 존재합니다:\n$$\\lim_{x \\to 2} f(x) = 5$$\n\n조건 2를 만족합니다. ✓\n\n**조건 3: 극한값과 함수값의 일치**\n\n$$\\lim_{x \\to 2} f(x) = 5 = f(2)$$\n\n세 번째 조건도 만족합니다. ✓\n\n**[정답 확인]**\n\n세 연속성 조건을 모두 만족하므로 함수 $f(x)$는 $x = 2$에서 **연속**입니다.\n\n**[오답 분석]**\n\n- **② 불연속 (함수값 미정의)**: $f(2) = 5$로 명확히 정의됨 ✗\n- **③ 불연속 (극한 미존재)**: 좌극한 = 우극한 = 5로 극한이 존재함 ✗\n- **④ 불연속 (함수값 ≠ 극한값)**: $f(2) = 5 = \\lim_{x \\to 2} f(x)$로 같음 ✗\n- **⑤ 판별 불가**: 함수가 명확히 정의되어 판별 가능함 ✗\n\n**[핵심 포인트]**\n\n구간별로 정의된 함수의 연속성 판정에서는 **경계점에서 좌극한, 우극한, 함수값 세 가지를 반드시 확인**하고, 세 값이 모두 같아야만 연속입니다. 이 문제는 우연히 세 값이 모두 5로 일치하는 경우입니다.",
