    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n함수가 특정 점에서 연속이기 위한 조건은 다음 세 가지를 모두 만족해야 합니다:\n1. $f(a)$가 정의되어 있다\n2. $\\lim_{x \\to a} f(x)$가 존재한다\n3. $\\lim_{x \\to a} f(x) = f(a)$\n\n특히, 구간별로 정의된 함수가 경계점 $x = c$에서 연속이려면:\n$$\\lim_{x \\to c^-} f(x) = \\lim_{x \\to c^+} f(x) = f(c)$$\n\n**[풀이]**\n\n$x = 1$에서 함수가 연속이 되는 조건을 찾기 위해 좌극한, 우극한, 함수값을 각각 구합니다.\n\n**Step 1: $x = 1$에서의 함수값 구하기**\n\n$x \\geq 1$일 때 $f(x) = ax + 2$이므로:\n$$f(1) = a(1) + 2 = a + 2$$\n\n**Step 2: $x = 1$에서의 좌극한 구하기**\n\n$x < 1$일 때 $f(x) = 3x - 1$이므로:\n$$\\lim_{x \\to 1^-} f(x) = 3(1) - 1 = 3 - 1 = 2$$\n\n**Step 3: $x = 1$에서의 우극한 구하기**\n\n$x \\geq 1$일 때 $f(x) = ax + 2$이므로:\n$$\\lim_{x \\to 1^+} f(x) = a(1) + 2 = a + 2$$\n\n**Step 4: 연속 조건 적용**\n\n함수가 $x = 1$에서 연속이려면:\n$$\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^+} f(x) = f(1)$$\n\n따라서:\n$$2 = a + 2$$\n\n$$a = 0$$\n\n**[정답 확인]**\n\n$a = 0$일 때, $\\lim_{x \\to 1^-} f(x) = 2$, $f(1) = 0 + 2 = 2$, $\\lim_{x \\to 1^+} f(x) = 2$로 모두 같으므로 연속입니다.\n\n**[오답 분석]**\n\n- ① $a = -2$: $f(1) = -2 + 2 = 0 \\neq 2$ (불연속)\n- ② $a = -1$: $f(1) = -1 + 2 = 1 \\neq 2$ (불연속)\n- ④ $a = 1$: $f(1) = 1 + 2 = 3 \\neq 2$ (불연속)\n- ⑤ $a = 2$: $f(1) = 2 + 2 = 4 \\neq 2$ (불연속)\n\n**[핵심 포인트]**\n\n구간별 함수의 경계점에서의 연속성은 좌극한과 우극한, 함수값이 모두 같아야 하며, 특히 경계점이 어느 구간에 속하는지 확인하여 함수값을 올바르게 구하는 것이 중요합니다.",
