    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n함수 $f(x)$가 $x=a$에서 연속이기 위한 조건:\n1) $f(a)$가 정의되어 있다\n2) $\\lim_{x \\to a} f(x)$가 존재한다\n3) $\\lim_{x \\to a} f(x) = f(a)$\n\n세 조건을 모두 만족해야 연속입니다. 하나라도 만족하지 않으면 불연속입니다.\n\n**[풀이]**\n\n각 선택지를 $x=0$에서의 연속성으로 검토합니다.\n\n**① $f(x) = x^3 - 2x + 1$**\n- 다항함수이므로 모든 실수에서 연속입니다.\n- $x=0$에서: $f(0) = 1$, $\\lim_{x \\to 0} f(x) = 1$ ✓ 연속\n\n**② $f(x) = |x|$**\n- $f(0) = 0$\n- $\\lim_{x \\to 0^+} |x| = 0$, $\\lim_{x \\to 0^-} |x| = 0$\n- $\\lim_{x \\to 0} |x| = 0 = f(0)$ ✓ 연속\n\n**③ $f(x) = \\dfrac{1}{x}$**\n- $x=0$에서 **$f(0)$이 정의되지 않습니다** (분모가 0)\n- 따라서 연속성의 첫 번째 조건을 만족하지 않으므로 **불연속**입니다.\n\n**④ $f(x) = \\sqrt{x^2 + 1}$**\n- 합성함수(다항함수와 제곱근의 합성)이고, $x^2 + 1 > 0$ (항상 양수)\n- $f(0) = \\sqrt{1} = 1$\n- $\\lim_{x \\to 0} \\sqrt{x^2 + 1} = 1$ ✓ 연속\n\n**⑤ $f(x) = x|x|$**\n- $f(0) = 0 \\cdot |0| = 0$\n- $x \\geq 0$일 때: $f(x) = x \\cdot x = x^2$이므로 $\\lim_{x \\to 0^+} f(x) = 0$\n- $x < 0$일 때: $f(x) = x \\cdot (-x) = -x^2$이므로 $\\lim_{x \\to 0^-} f(x) = 0$\n- $\\lim_{x \\to 0} f(x) = 0 = f(0)$ ✓ 연속\n\n**[정답 확인]**\n\n③번 $f(x) = \\dfrac{1}{x}$는 $x=0$에서 정의되지 않으므로 불연속입니다.\n\n**[오답 분석]**\n\n- ① 다항함수는 항상 연속\n- ② 절댓값 함수는 연속 (꺾이는 점에서도 연속)\n- ④ 제곱근 안의 식이 항상 양수이므로 연속\n- ⑤ 좌극한과 우극한이 모두 0으로 같으므로 연속\n\n**[핵심 포인트]**\n\n- **다항함수는 항상 연속**이라는 것을 기억하세요.\n- $x=0$에서 불연속인 함수는 **정의되지 않거나**, **좌우 극한이 다르거나**, **극한값 ≠ 함수값**인 경우입니다.",
