    "problem": "함수 $f(x) = \\begin{cases} \\dfrac{\\sqrt{x+4} - 2}{x} & (x \\neq 0) \\\\ a & (x = 0) \\end{cases}$이 $x = 0$에서 연속이 되도록 하는 상수 $a$의 값은? (답은 기약분수의 분자와 분모의 합으로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 5,
    "explanation": "**[핵심 개념]**\n함수가 특정 점에서 연속이 되기 위한 조건은 $\\lim_{x \\to a} f(x) = f(a)$를 만족해야 한다는 것입니다. 따라서 $x=0$에서 연속이려면 $\\lim_{x \\to 0} \\frac{\\sqrt{x+4} - 2}{x} = a$를 만족하는 $a$를 찾아야 합니다. 이 극한은 $0/0$ 꼴의 부정형이므로 분자를 유리화하여 계산합니다.\n\n**[풀이]**\n$x=0$에서 연속이 되기 위한 조건:\n$$\\lim_{x \\to 0} f(x) = f(0) = a$$\n\n$x \\to 0$일 때 $\\frac{\\sqrt{x+4} - 2}{x}$는 $\\frac{0}{0}$ 꼴이므로, 분자를 유리화합니다.\n\n분자와 분모에 $\\sqrt{x+4} + 2$를 곱합니다:\n$$\\lim_{x \\to 0} \\frac{\\sqrt{x+4} - 2}{x} = \\lim_{x \\to 0} \\frac{(\\sqrt{x+4} - 2)(\\sqrt{x+4} + 2)}{x(\\sqrt{x+4} + 2)}$$\n\n분자를 전개하면 (차의 제곱 공식 이용):\n$$(\\sqrt{x+4} - 2)(\\sqrt{x+4} + 2) = (\\sqrt{x+4})^2 - 2^2 = x+4 - 4 = x$$\n\n따라서:\n$$\\lim_{x \\to 0} \\frac{x}{x(\\sqrt{x+4} + 2)} = \\lim_{x \\to 0} \\frac{1}{\\sqrt{x+4} + 2}$$\n\n$x \\to 0$일 때:\n$$\\lim_{x \\to 0} \\frac{1}{\\sqrt{x+4} + 2} = \\frac{1}{\\sqrt{0+4} + 2} = \\frac{1}{\\sqrt{4} + 2} = \\frac{1}{2 + 2} = \\frac{1}{4}$$\n\n따라서 $a = \\frac{1}{4}$입니다.\n\n기약분수 $\\frac{1}{4}$의 분자는 1, 분모는 4이므로:\n$$\\text{분자 + 분모} = 1 + 4 = 5$$\n\n**[정답 확인]**\n$a = \\frac{1}{4}$일 때 $\\lim_{x \\to 0} f(x) = \\frac{1}{4} = f(0)$이므로 연속 조건을 만족하며, 분자와 분모의 합은 5입니다.\n\n**[오답 분석]**\n- 분자를 유리화하지 않고 직접 극한을 구하려 하면 $0/0$ 꼴에서 진전이 없습니다.\n- 유리화 과정에서 실수하여 분자를 $x^2$으로 잘못 계산하면 틀린 답이 나옵니다.\n- 극한값을 구한 후 분자와 분모를 더하는 과정을 빠뜨리면 $\\frac{1}{4}$를 답으로 제출하여 틀립니다.\n\n**[핵심 포인트]**\n$\\frac{0}{0}$ 꼴의 부정형에서는 분자를 유리화하여 소거 가능한 형태로 만드는 것이 핵심입니다. 연속성 문제에서는 항상 극한값을 구한 후 함수값과 같은지 확인해야 합니다.",
