    "problem": "함수 $f(x) = \\begin{cases} ax^2 + 1 & (x \\leq 1) \\\\ bx + 3 & (x > 1) \\end{cases}$이 $x = 1$에서 미분가능할 때, $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": -6,
    "explanation": "**[핵심 개념]**\n함수가 어떤 점에서 미분가능하려면 다음 두 조건을 만족해야 합니다:\n1. **연속성**: $\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^+} f(x) = f(1)$\n2. **미분가능성**: 좌미분계수 = 우미분계수, 즉 $f'(1^-) = f'(1^+)$\n\n**[풀이]**\n\n**Step 1: 연속성 조건**\n\n$x = 1$에서 연속이려면 좌극한과 우극한이 같아야 합니다.\n\n$$\\lim_{x \\to 1^-} f(x) = a(1)^2 + 1 = a + 1$$\n\n$$\\lim_{x \\to 1^+} f(x) = b(1) + 3 = b + 3$$\n\n$$f(1) = a(1)^2 + 1 = a + 1$$\n\n연속성 조건에서:\n$$a + 1 = b + 3$$\n$$a - b = 2 \\quad \\cdots (1)$$\n\n**Step 2: 미분가능성 조건**\n\n각 구간에서 도함수를 구합니다.\n\n- $x < 1$일 때: $f'(x) = 2ax$\n  $$f'(1^-) = 2a(1) = 2a$$\n\n- $x > 1$일 때: $f'(x) = b$\n  $$f'(1^+) = b$$\n\n미분가능성 조건에서:\n$$2a = b \\quad \\cdots (2)$$\n\n**Step 3: 연립방정식 풀이**\n\n식 (1)과 식 (2)를 연립합니다:\n$$a - b = 2$$\n$$2a = b$$\n\n식 (2)를 식 (1)에 대입:\n$$a - 2a = 2$$\n$$-a = 2$$\n$$a = -2$$\n\n식 (2)에서:\n$$b = 2a = 2(-2) = -4$$\n\n**Step 4: 답 구하기**\n\n$$a + b = -2 + (-4) = -6$$\n\n**[정답 확인]**\n$a = -2, b = -4$를 원래 함수에 대입하면 $x=1$에서 $f(1) = -1$로 연속이고, $f'(1^-) = f'(1^+) = -4$로 미분가능하므로 조건을 만족합니다.\n\n**[오답 분석]**\n선택지가 제시되지 않아 일반적인 오답을 분석하면:\n- **0, 2, -2 등**: 연속성 조건만 고려하고 미분가능성 조건을 빠뜨린 경우\n- **-4, -8**: 계산 실수로 $a$와 $b$ 중 하나만 구한 경우\n\n**[핵심 포인트]**\n미분가능 → 연속 + 좌미분계수 = 우미분계수. 항상 **연속성과 미분가능성 두 조건**을 모두 확인해야 합니다.",
