    "explanation": "**[핵심 개념]**\n\n함수의 연속성 판정: 함수 $f(x)$가 $x=a$에서 연속이려면 ① $f(a)$가 정의되고 ② $\\lim_{x \\to a} f(x)$가 존재하며 ③ $\\lim_{x \\to a} f(x) = f(a)$를 만족해야 한다.\n\n곱함수의 극한: $\\lim_{x \\to a} [h(x) \\cdot g(x)] = \\lim_{x \\to a} h(x) \\cdot \\lim_{x \\to a} g(x)$ (단, 두 극한이 모두 존재할 때). 특히 $\\lim_{x \\to a} h(x) = 0$이면 $g(x)$가 유계이거나 극한을 가질 때 곱의 극한은 0이 될 수 있다.\n\n**[풀이]**\n\n$f(x) = (x^2 - 1)g(x)$에서 $x=1$에서의 연속성을 판정하자.\n\n**Step 1: $f(1)$ 구하기**\n\n$f(1) = (1^2 - 1)g(1) = 0 \\cdot g(1) = 0$\n\n(참고: $g(1)$의 값이 정의되지 않았거나 무엇이든 상관없이, $x^2-1$ 부분이 0이 되므로 $f(1) = 0$)\n\n**Step 2: $\\lim_{x \\to 1} f(x)$ 구하기**\n\n$$\\lim_{x \\to 1} f(x) = \\lim_{x \\to 1} (x^2 - 1)g(x)$$\n\n$(x^2 - 1)$을 인수분해하면:\n\n$$\\lim_{x \\to 1} (x^2 - 1)g(x) = \\lim_{x \\to 1} (x-1)(x+1)g(x)$$\n\n주어진 조건에서 $\\lim_{x \\to 1} g(x) = 3$이므로:\n\n$$= \\lim_{x \\to 1} (x-1) \\cdot \\lim_{x \\to 1} (x+1) \\cdot \\lim_{x \\to 1} g(x)$$\n\n$$= 0 \\cdot 2 \\cdot 3 = 0$$\n\n**Step 3: 연속성 판정**\n\n$$\\lim_{x \\to 1} f(x) = 0 = f(1)$$\n\n따라서 $f(x)$는 $x=1$에서 **연속**이다.\n\n**[정답 확인]**\n\n$g(x)$가 불연속이더라도, 함수 $f(x)$는 $(x^2-1)$ 인수 때문에 $x=1$에서 극한값이 0이 되고 함수값도 0이므로 연속이다.\n\n**[오답 분석]**\n\n② **불연속 ($g(x)$ 불연속이므로)**: $g(x)$가 불연속이라고 해서 $f(x) = (x^2-1)g(x)$가 반드시 불연속인 것은 아니다. $(x^2-1)$이 0이 되는 점에서는 곱이 0으로 압축될 수 있다.\n\n③ **불연속 (극한 미존재)**: 극한이 존재한다. $\\lim_{x \\to 1} (x-1) = 0$이므로 극한값이 0으로 결정된다.\n\n④ **판별 불가 ($g(1)$ 미지)**: $g(1)$이 정의되지 않았더라도 $f(1) = 0 \\cdot g(1) = 0$이므로 판별 가능하다.\n\n⑤ **연속 ($f(1) = 3$, 극한 = 3)**: $f(1) = 0$이지 3이 아니다.\n\n**[핵심 포인트]**\n\n곱함수 $f(x) = (x^2-1)g(x)$에서 $(x^2-1)$ 인수가 $x=1$에서 0이 되므로, 비록 $g(x)$가 불연속이더라도 $f(x)$의 극한은 0이 되어 $x=1$에서 연속이 된다. 이것이 **\"0배의 매력\"** 원리이다.",
