    "answer": 4,
    "explanation": "**[핵심 개념]**\n함수가 특정 점에서 연속이기 위한 조건은 $\\lim_{x \\to c} f(x) = f(c)$를 만족해야 한다는 것입니다. 즉, 극한값과 함수값이 같아야 합니다. 이 문제에서는 $x=2$에서의 극한값을 구하기 위해 분자와 분모를 인수분해하여 약분하는 기술이 필요합니다.\n\n**[풀이]**\n\n$x = 2$에서 함수 $f(x)$가 연속이려면 다음 조건을 만족해야 합니다:\n$$\\lim_{x \\to 2} f(x) = f(2) = a$$\n\n$x \\neq 2$일 때 $f(x) = \\dfrac{x^3 - 8}{x^2 - 4}$이므로, $x \\to 2$일 때의 극한을 구합니다.\n\n**Step 1: 분자와 분모를 인수분해**\n\n분자: $x^3 - 8 = (x-2)(x^2 + 2x + 4)$ (3제곱 차 공식)\n\n분모: $x^2 - 4 = (x-2)(x+2)$ (제곱 차 공식)\n\n**Step 2: 약분**\n\n$x \\neq 2$일 때:\n$$f(x) = \\frac{(x-2)(x^2 + 2x + 4)}{(x-2)(x+2)} = \\frac{x^2 + 2x + 4}{x+2}$$\n\n**Step 3: 극한값 계산**\n\n$$\\lim_{x \\to 2} f(x) = \\lim_{x \\to 2} \\frac{x^2 + 2x + 4}{x+2}$$\n\n$x \\to 2$일 때 분모가 0이 아니므로 직접 대입:\n\n$$\\lim_{x \\to 2} f(x) = \\frac{2^2 + 2(2) + 4}{2+2} = \\frac{4 + 4 + 4}{4} = \\frac{12}{4} = 3$$\n\n**Step 4: 연속성 조건 적용**\n\n연속이려면 $a = \\lim_{x \\to 2} f(x) = 3$\n\n**[정답 확인]**\n$x=2$에서 연속이려면 극한값이 함수값과 같아야 하므로, 약분 후 극한을 구하면 $a = 3$입니다.\n\n**[오답 분석]**\n- **① 1**: 분자의 인수분해를 잘못하여 $x^2 + 2x + 4$ 대신 다른 식을 사용한 경우\n- **② $\\frac{3}{2}$**: 극한값 계산 중 분자나 분모를 잘못 계산한 경우\n- **③ 2**: 약분 전 $\\frac{4-8}{4-4}$ 같은 부정형으로 잘못 판단하거나 계산 실수\n- **④ $\\frac{5}{2}$**: 분자 계산에서 $4+4+3=11$처럼 오류를 범한 경우\n\n**[핵심 포인트]**\n연속성 문제에서는 **인수분해를 통해 부정형을 제거하고 약분**하는 것이 중요합니다. 특히 $(x-2)$ 인수를 찾아내어 약분해야 극한을 구할 수 있습니다.",
