    "explanation": "**[핵심 개념]**\n\n이 문제는 함수의 연속성과 관련된 중요한 정리들을 구별하는 문제입니다.\n\n- **중간값 정리**: 함수 $f(x)$가 폐구간 $[a,b]$에서 연속이고 $f(a) \\neq f(b)$일 때, $f(a)$와 $f(b)$ 사이의 모든 값이 개구간 $(a,b)$에서 적어도 한 번은 나타난다는 정리\n- **롤의 정리**: $f(a) = f(b)$일 때 $f'(c) = 0$인 점의 존재를 보장 (도함수 필요)\n- **평균값 정리**: 평균변화율과 같은 순간변화율을 갖는 점의 존재를 보장 (도함수 필요)\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- $f(x)$는 모든 실수에서 연속 (특히 $[0,3]$에서 연속)\n- $f(0) = -2 < 0$\n- $f(3) = 4 > 0$\n\n$f(0) = -2$와 $f(3) = 4$ 사이에 0이 존재합니다.\n$$f(0) = -2 < 0 < 4 = f(3)$$\n\n중간값 정리에 의해, $f(x)$가 $[0,3]$에서 연속이고 $f(0) < 0 < f(3)$이므로, 개구간 $(0,3)$에서 $f(x) = 0$을 만족하는 $x$가 적어도 하나 존재합니다.\n\n즉, 방정식 $f(x) = 0$이 $(0,3)$에서 적어도 하나의 실근을 가집니다.\n\n**[정답 확인]**\n\n중간값 정리는 함수값이 한 구간에서 음수에서 양수로 변할 때, 그 사이에 0이 되는 점이 반드시 존재함을 보장합니다.\n\n**[오답 분석]**\n\n① **롤의 정리**: $f(a) = f(b)$라는 조건이 필요한데, 여기서는 $f(0) \\neq f(3)$이므로 적용 불가\n\n② **평균값 정리**: $f(c) = \\frac{f(b)-f(a)}{b-a}$를 만족하는 점을 찾는 정리로, 방정식 $f(x)=0$의 해의 존재를 직접 보장하지 않음\n\n④ **극값 정리**: 연속함수가 폐구간에서 최댓값과 최솟값을 가진다는 정리로, 특정 함수값의 존재와 무관\n\n⑤ **샌드위치 정리**: 극한을 다루는 정리로, 방정식의 해와 관계없음\n\n**[핵심 포인트]**\n\n- 함수가 연속이고 한 끝점에서는 음수, 다른 끝점에서는 양수일 때 → **중간값 정리** 적용\n- \"적어도 하나의 실근 존재\" 또는 \"특정값을 지나감\" → 중간값 정리를 의심하기",
