    "explanation": "**[핵심 개념]**\n함수가 어떤 점에서 미분가능하려면 두 가지 조건을 만족해야 합니다.\n1. 연속성: $\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^+} f(x) = f(1)$\n2. 미분가능성: $\\lim_{x \\to 1^-} f'(x) = \\lim_{x \\to 1^+} f'(x)$ (좌미분계수 = 우미분계수)\n\n**[풀이]**\n\n**Step 1: 연속성 조건**\n\n$x = 1$에서 연속이려면 좌극한과 우극한이 같아야 합니다.\n\n좌극한: $\\lim_{x \\to 1^-} f(x) = 1^2 + 2(1) = 3$\n\n우극한: $\\lim_{x \\to 1^+} f(x) = a(1) + b = a + b$\n\n함수값: $f(1) = a + b$ (정의에 의해 $x \\geq 1$일 때)\n\n연속성 조건: $a + b = 3$ ... (1)\n\n**Step 2: 미분가능성 조건**\n\n좌미분계수 구하기:\n$x < 1$일 때 $f(x) = x^2 + 2x$이므로\n$$f'(x) = 2x + 2$$\n$$\\lim_{x \\to 1^-} f'(x) = 2(1) + 2 = 4$$\n\n우미분계수 구하기:\n$x \\geq 1$일 때 $f(x) = ax + b$이므로\n$$f'(x) = a$$\n$$\\lim_{x \\to 1^+} f'(x) = a$$\n\n미분가능성 조건: $a = 4$ ... (2)\n\n**Step 3: 미지수 구하기**\n\n식 (2)에서 $a = 4$\n\n식 (1)에 대입: $4 + b = 3$\n$$b = -1$$\n\n**Step 4: 답 구하기**\n\n$$a^2 + b^2 = 4^2 + (-1)^2 = 16 + 1 = 17$$\n\n**[정답 확인]**\n$x=1$에서 연속성($a+b=3$)과 미분가능성($a=4$)을 모두 만족하는 $a=4, b=-1$을 구했고, $a^2+b^2=17$이므로 정답은 ③입니다.\n\n**[오답 분석]**\n- ① 10: $a=3, b=0$으로 연속성만 만족하되 미분가능성을 무시한 경우\n- ② 13: $a=3, b=0$ 또는 다른 조합으로 계산 실수\n- ④ 20: $a=4, b=2$로 연속성 조건을 만족하지 않는 경우\n- ⑤ 25: $a=5, b=-2$ 등 두 조건을 모두 만족하지 않는 경우\n\n**[핵심 포인트]**\n구간별로 정의된 함수가 경계점에서 미분가능하려면 **연속성과 미분가능성 두 조건을 모두 확인**해야 합니다. 미분가능성은 좌미분계수와 우미분계수가 같다는 것을 의미합니다.",
