    "explanation": "**[핵심 개념]**\n함수가 특정 점에서 연속이기 위한 조건은 $\\lim_{x \\to a} f(x) = f(a)$를 만족해야 한다는 것입니다. 특히 $x=1$에서 연속이려면 $\\lim_{x \\to 1} \\frac{x^2 + ax + b}{x - 1} = 5$를 만족해야 합니다. 분모가 0으로 수렴하므로, 극한이 존재하려면 분자도 0으로 수렴해야 하며, 이를 통해 $a$, $b$의 조건을 찾을 수 있습니다.\n\n**[풀이]**\n\n$x = 1$에서 함수가 연속이려면:\n$$\\lim_{x \\to 1} f(x) = f(1) = 5$$\n\n$x \\neq 1$일 때 $f(x) = \\frac{x^2 + ax + b}{x - 1}$이므로:\n$$\\lim_{x \\to 1} \\frac{x^2 + ax + b}{x - 1} = 5$$\n\n$x \\to 1$일 때 분모 $(x-1) \\to 0$입니다. 극한이 유한한 값 5로 수렴하려면, 분자도 0으로 수렴해야 합니다 (0/0 꼴). 따라서:\n$$1^2 + a \\cdot 1 + b = 0$$\n$$1 + a + b = 0$$\n$$a + b = -1 \\cdots (1)$$\n\n이제 분자를 인수분해합니다. 분자가 $(x-1)$을 인수로 가지므로:\n$$x^2 + ax + b = (x - 1)(x - c)$$\n\n우변을 전개하면:\n$$x^2 + ax + b = x^2 - cx - x + c = x^2 - (c+1)x + c$$\n\n계수를 비교하면:\n- $a = -(c+1)$\n- $b = c$\n\n따라서:\n$$\\lim_{x \\to 1} \\frac{x^2 + ax + b}{x - 1} = \\lim_{x \\to 1} \\frac{(x-1)(x-c)}{x-1} = \\lim_{x \\to 1} (x - c) = 1 - c = 5$$\n\n이로부터:\n$$1 - c = 5$$\n$$c = -4$$\n\n따라서:\n- $b = c = -4$\n- $a = -(c + 1) = -(-4 + 1) = -(-3) = 3$\n\n검증: $a + b = 3 + (-4) = -1$ ✓\n\n**[정답 확인]**\n$a = 3$, $b = -4$이므로 $ab = 3 \\times (-4) = -12$\n\n**[오답 분석]**\n선택지가 제시되지 않았으므로, 흔한 실수를 언급하면:\n- $a + b = -1$만 구하고 마치면 안 됨\n- 극한값이 5라는 조건을 활용하지 않으면 $a$, $b$를 개별적으로 구할 수 없음\n- $1 - c = 5$에서 $c = 4$로 계산 실수하면 $ab = 12$ (부호 오류)\n\n**[핵심 포인트]**\n$x = a$에서 분모가 0이 되는 함수의 연속성을 판단할 때, 극한이 존재하려면 분자도 반드시 0이 되어야 한다 (인수정리 활용). 이를 이용해 미지수 조건을 먼저 찾고, 극한값을 이용해 최종 계산하는 것이 핵심입니다.",
