    "answer": 3,
    "explanation": "**[핵심 개념]**\n함수의 실근의 개수를 구하기 위해서는 함수의 극값을 조사해야 합니다. $f(x) = 0$의 실근의 개수는 $y = f(x)$ 그래프가 $x$축과 만나는 점의 개수와 같습니다. 3차 함수의 극값 위치와 극값의 부호를 조사하면 실근의 개수를 판정할 수 있습니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n**Step 2: 극값의 위치 찾기**\n$f'(x) = 0$에서 $x = -1$ 또는 $x = 1$\n\n**Step 3: 극값 계산**\n- $x = -1$일 때 (극대값):\n$$f(-1) = (-1)^3 - 3(-1) + 1 = -1 + 3 + 1 = 3 > 0$$\n\n- $x = 1$일 때 (극소값):\n$$f(1) = 1^3 - 3(1) + 1 = 1 - 3 + 1 = -1 < 0$$\n\n**Step 4: 함수의 개형 분석**\n- $x \\to -\\infty$일 때, $f(x) \\to -\\infty$\n- $x = -1$에서 극대값 $3 > 0$\n- $x = 1$에서 극소값 $-1 < 0$\n- $x \\to +\\infty$일 때, $f(x) \\to +\\infty$\n\n**Step 5: 실근의 개수**\n극대값이 양수이고 극소값이 음수이므로, $y = f(x)$ 그래프는:\n- $(-\\infty, -1)$ 구간에서 $x$축과 1번 만남\n- $(-1, 1)$ 구간에서 $x$축과 1번 만남\n- $(1, +\\infty)$ 구간에서 $x$축과 1번 만남\n\n따라서 실근의 개수는 **3개**입니다.\n\n**[정답 확인]**\n극대값 $f(-1) = 3 > 0$과 극소값 $f(1) = -1 < 0$의 부호가 반대이므로, 3차 함수는 세 구간에서 각각 $x$축과 만나 실근 3개를 가집니다.\n\n**[오답 분석]**\n- ① 0개: 극대값이 양수이고 극소값이 음수이므로 반드시 실근이 존재합니다.\n- ② 1개: 극값의 부호가 같은 경우에만 가능하므로 불가능합니다.\n- ③ 2개: 극값 중 하나가 0이거나, 극값의 부호가 같은 경우인데 현재 상황과 맞지 않습니다.\n- ⑤ 판별 불가: 도함수 계산과 극값 계산으로 충분히 판정 가능합니다.\n\n**[핵심 포인트]**\n3차 함수에서 극대값과 극소값의 부호가 반대이면 실근은 정확히 3개입니다. 극값의 위치와 부호를 조사하는 것이 근의 개수를 판정하는 가장 효율적인 방법입니다.",
