    "type": "연속성",
    "problem": "함수 $f(x) = \\begin{cases} \\dfrac{x^2 - 4x + 3}{x - 3} & (x \\neq 3) \\\\ a & (x = 3) \\end{cases}$이 $x = 3$에서 연속이고, $g(x) = f(x) \\cdot (x - 3)$일 때, $g'(3)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n1. **함수의 연속성**: 함수 $f$가 $x=a$에서 연속이려면 $\\lim_{x \\to a} f(x) = f(a)$를 만족해야 합니다.\n\n2. **인수분해와 약분**: $x \\neq 3$일 때 분자를 인수분해하여 분모와 약분할 수 있습니다.\n\n3. **미분의 정의**: $g'(3) = \\lim_{h \\to 0} \\frac{g(3+h) - g(3)}{h}$\n\n4. **곱의 미분법**: $(uv)' = u'v + uv'$\n\n**[풀이]**\n\n**Step 1: $f(x)$를 $x \\neq 3$일 때 정리**\n\n$$f(x) = \\frac{x^2 - 4x + 3}{x - 3} = \\frac{(x-1)(x-3)}{x-3} = x - 1 \\quad (x \\neq 3)$$\n\n**Step 2: 연속성 조건으로 $a$ 구하기**\n\n$f(x)$가 $x=3$에서 연속이므로:\n$$\\lim_{x \\to 3} f(x) = f(3) = a$$\n\n$$\\lim_{x \\to 3} (x-1) = 3 - 1 = 2$$\n\n따라서 $a = 2$\n\n**Step 3: $g(x)$ 정리**\n\n$$g(x) = f(x) \\cdot (x-3)$$\n\n$x \\neq 3$일 때:\n$$g(x) = (x-1)(x-3)$$\n\n$x = 3$일 때:\n$$g(3) = f(3) \\cdot (3-3) = 2 \\cdot 0 = 0$$\n\n**Step 4: 모든 $x$에서 $g(x)$의 명시적 형태**\n\n$$g(x) = (x-1)(x-3) = x^2 - 4x + 3 \\quad \\text{(모든 실수 $x$에서)}$$\n\n$x=3$일 때도 $g(3) = 9 - 12 + 3 = 0$ ✓\n\n**Step 5: $g'(3)$ 계산**\n\n$g(x) = x^2 - 4x + 3$은 모든 점에서 미분가능하므로:\n\n$$g'(x) = 2x - 4$$\n\n$$g'(3) = 2(3) - 4 = 6 - 4 = 2$$\n\n**[정답 확인]**\n\n$g(x)$가 다항식으로 표현되므로 $x=3$에서 미분가능하며, $g'(3) = 2$가 정답입니다.\n\n**[오답 분석]**\n\n- **0**: $g(3) = 0$과 혼동한 경우\n- **1**: 미분 계산 실수 ($g'(x) = 2x - 4$에서 계수를 잘못 적용)\n- **4**: $g'(3) = 2 \\times 3 - 1 = 5$처럼 상수항을 잘못 처리\n\n**[핵심 포인트]**\n\n1. **분자 인수분해 후 약분**: $\\frac{(x-1)(x-3)}{x-3} = x-1$로 정리하면 $f(x)$의 연속성 조건에서 $a$를 쉽게 구할 수 있습니다.\n\n2. **$g(x)$는 다항식**: $g(x) = (x-1)(x-3)$은 실제로 모든 점에서 다항식이므로, 미분은 표준 미분법칙을 그대로 적용합니다.",
