    "problem": "실수 전체에서 연속인 함수 $f(x)$가 $f(0) = 1$, $f(2) = -3$, $f(5) = 2$를 만족할 때, 방정식 $f(x) = 0$이 반드시 근을 가지는 열린구간을 모두 고르면?",
