    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n중간값 정리(Intermediate Value Theorem): 폐구간 $[a, b]$에서 연속인 함수 $f(x)$에 대해 $f(a)$와 $f(b)$의 부호가 다르면(즉, $f(a) \\cdot f(b) < 0$이면), 개구간 $(a, b)$ 내에 $f(c) = 0$을 만족하는 점 $c$가 반드시 존재한다.\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- $f(0) = 1$ (양수)\n- $f(2) = -3$ (음수)\n- $f(5) = 2$ (양수)\n- $f(x)$는 실수 전체에서 연속\n\n각 구간에서 중간값 정리를 적용한다.\n\n**구간 $(0, 2)$에서:**\n- $f(0) = 1 > 0$\n- $f(2) = -3 < 0$\n- $f(0) \\cdot f(2) = 1 \\times (-3) = -3 < 0$\n\n부호가 반대이고 $f(x)$가 연속이므로, 중간값 정리에 의해 $(0, 2)$ 내에 $f(x) = 0$을 만족하는 근이 **반드시 존재**한다.\n\n**구간 $(2, 5)$에서:**\n- $f(2) = -3 < 0$\n- $f(5) = 2 > 0$\n- $f(2) \\cdot f(5) = (-3) \\times 2 = -6 < 0$\n\n부호가 반대이고 $f(x)$가 연속이므로, 중간값 정리에 의해 $(2, 5)$ 내에 $f(x) = 0$을 만족하는 근이 **반드시 존재**한다.\n\n**구간 $(0, 5)$에서:**\n- $f(0) = 1 > 0$\n- $f(5) = 2 > 0$\n\n양 끝점의 함수값이 같은 부호이므로, 중간값 정리만으로는 $(0, 5)$ 내에 근이 있다고 보장할 수 없다. (실제로 근이 없을 수도 있고, 여러 개 있을 수도 있다.)\n\n**[정답 확인]**\n\n$(0, 2)$와 $(2, 5)$ 두 구간에서 함수값의 부호가 바뀌므로, 중간값 정리에 의해 각 구간에서 $f(x) = 0$의 근이 반드시 존재한다.\n\n**[오답 분석]**\n\n① $(0, 2)$만 - $(2, 5)$에서도 부호가 반대이므로 근이 존재한다.\n\n② $(2, 5)$만 - $(0, 2)$에서도 부호가 반대이므로 근이 존재한다.\n\n③ $(0, 5)$만 - $f(0) = 1 > 0$과 $f(5) = 2 > 0$으로 양 끝의 부호가 같아서 중간값 정리를 적용할 수 없다.\n\n⑤ 근의 존재를 보장할 수 없다 - 실제로 $(0, 2)$와 $(2, 5)$에서는 중간값 정리에 의해 근의 존재가 보장된다.\n\n**[핵심 포인트]**\n\n중간값 정리를 적용할 때는 **폐구간의 양 끝점에서 함수값의 부호를 비교**하여 부호가 반대면 그 개구간 내에 근이 반드시 존재한다는 것을 기억하자. 같은 부호면 근의 존재 여부를 판단할 수 없다.",
