    "explanation": "**[핵심 개념]**\n도함수는 함수의 순간변화율을 나타내며, 다항함수의 도함수는 멱의 법칙(power rule)을 이용하여 구합니다.\n- 멱의 법칙: $\\frac{d}{dx}(x^n) = nx^{n-1}$\n- 상수의 도함수: $\\frac{d}{dx}(c) = 0$\n- 선형성: $\\frac{d}{dx}[af(x) + bg(x)] = af'(x) + bg'(x)$\n\n**[풀이]**\n\n**1단계: 함수 $f(x)$의 도함수 구하기**\n\n$$f(x) = x^2 + 3x$$\n\n멱의 법칙을 각 항에 적용합니다.\n\n- $\\frac{d}{dx}(x^2) = 2x^{2-1} = 2x$\n- $\\frac{d}{dx}(3x) = 3 \\cdot \\frac{d}{dx}(x) = 3 \\cdot 1 = 3$\n\n따라서:\n$$f'(x) = 2x + 3$$\n\n**2단계: $x=1$일 때의 도함수 값 구하기**\n\n위에서 구한 $f'(x) = 2x + 3$에 $x=1$을 대입합니다.\n\n$$f'(1) = 2(1) + 3 = 2 + 3 = 5$$\n\n**[정답 확인]**\n$f'(x) = 2x + 3$에 $x=1$을 대입하면 $f'(1) = 5$가 되어 정답입니다.\n\n**[오답 분석]**\n객관식 문제가 아니므로 해당 사항 없습니다.\n\n**[핵심 포인트]**\n- 다항함수의 도함수는 각 항에 멱의 법칙을 독립적으로 적용하여 구합니다.\n- 도함수를 먼저 구한 후 주어진 점에서의 값을 구하는 것이 계산 실수를 줄이는 방법입니다.",
