    "problem": "$\\lim_{h \\to 0} \\dfrac{(2+h)^2 - 4}{h}$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n이 문제는 미분의 정의를 직접 계산하는 문제입니다. 함수 $f(x) = x^2$에 대해 $x = 2$에서의 미분계수를 구하는 것으로, 극한의 형태는 $\\lim_{h \\to 0} \\frac{f(2+h) - f(2)}{h}$ 입니다. 분자가 $h = 0$일 때 0이 되는 부정형 $\\frac{0}{0}$이므로, 인수분해나 전개를 통해 분자를 정리한 후 약분하여 극한을 구합니다.\n\n**[풀이]**\n\n**Step 1: 분자를 전개합니다.**\n\n$(2+h)^2 - 4$를 전개하면:\n$$\n(2+h)^2 - 4 = 4 + 4h + h^2 - 4 = 4h + h^2\n$$\n\n**Step 2: 분자를 인수분해합니다.**\n\n$$\n4h + h^2 = h(4 + h)\n$$\n\n**Step 3: 극한식에 대입합니다.**\n\n$$\n\\lim_{h \\to 0} \\frac{(2+h)^2 - 4}{h} = \\lim_{h \\to 0} \\frac{h(4+h)}{h}\n$$\n\n**Step 4: $h \\neq 0$일 때 약분합니다.**\n\n극한에서는 $h \\to 0$이지만 $h = 0$은 아니므로, $h$로 약분할 수 있습니다:\n$$\n\\lim_{h \\to 0} \\frac{h(4+h)}{h} = \\lim_{h \\to 0} (4+h)\n$$\n\n**Step 5: 극한값을 계산합니다.**\n\n$$\n\\lim_{h \\to 0} (4+h) = 4 + 0 = 4\n$$\n\n**[정답 확인]**\n$f(x) = x^2$의 $x=2$에서의 미분계수 $f'(2) = 2 \\times 2 = 4$로 확인되므로 정답은 **4**입니다.\n\n**[오답 분석]**\n(객관식 선택지가 제시되지 않아 생략)\n\n**[핵심 포인트]**\n- 미분계수 극한에서는 분자의 부정형 $\\frac{0}{0}$을 피하기 위해 **인수분해/전개 후 약분**이 필수입니다.\n- 극한 과정에서 $h \\neq 0$이므로 $h$로 약분할 수 있다는 점이 중요합니다.",
