    "answer": 2,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 기울기는 그 점에서의 도함수 값과 같습니다. 곡선 $y = f(x)$에서 점 $(a, f(a))$에서의 접선의 기울기는 $f'(a)$입니다. 따라서 먼저 주어진 곡선을 미분한 후, 주어진 점의 x좌표를 대입하면 됩니다.\n\n**[풀이]**\n\n**1단계: 주어진 점이 곡선 위에 있는지 확인**\n곡선: $y = x^2 - 2x + 3$\n점 $(1, 2)$를 대입하면:\n$$y = 1^2 - 2(1) + 3 = 1 - 2 + 3 = 2$$\n점 $(1, 2)$가 곡선 위에 있음을 확인했습니다.\n\n**2단계: 곡선을 미분**\n$$y = x^2 - 2x + 3$$\n$$\\frac{dy}{dx} = 2x - 2$$\n\n**3단계: x = 1에서의 도함수 값 구하기**\n점 $(1, 2)$에서의 접선의 기울기는:\n$$\\frac{dy}{dx}\\bigg|_{x=1} = 2(1) - 2 = 2 - 2 = 0$$\n\n따라서 접선의 기울기는 **0**입니다.\n\n**[정답 확인]**\n$x = 1$일 때 도함수 $f'(1) = 2(1) - 2 = 0$이므로, 점 $(1, 2)$에서의 접선의 기울기는 0입니다.\n\n**[오답 분석]**\n- ① -2: 도함수 $2x - 2$에서 $x = -1$을 잘못 대입한 경우\n- ② -1: 계산 실수로 $2x - 2 = -1$에서 $x = 1/2$일 때의 값으로 착각한 경우\n- ④ 1: 부호를 잘못 계산하거나, $2x - 2 = 1$에서 $x = 3/2$일 때의 값으로 착각한 경우\n- ⑤ 2: 원래 함수의 계수 2만을 떼어낸 경우\n\n**[핵심 포인트]**\n곡선 위의 점에서의 접선의 기울기 = 그 점에서의 도함수 값. 항상 먼저 미분한 후 주어진 x좌표를 대입하는 것이 중요합니다.",
