    "type": "미분계수",
    "problem": "$\\lim_{x \\to 3} \\dfrac{x^2 - 9}{x - 3}$을 미분계수로 해석할 때, $f(x) = x^2$에 대한 $f'(a)$ 형태로 나타내면 $a$의 값은?",
    "answerType": "choice",
    "choices": [
      "① 1",
      "② 2",
      "③ 3",
      "④ 6",
      "⑤ 9"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n미분계수의 정의: 함수 $f(x)$가 $x=a$에서 미분가능할 때, 미분계수 $f'(a)$는 다음과 같이 정의됩니다.\n\n$$f'(a) = \\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a}$$\n\n주어진 극한식을 이 형태와 비교하여 $f(x)$와 $a$의 값을 찾아야 합니다.\n\n**[풀이]**\n\n**Step 1: 주어진 극한식을 정리**\n\n$$\\lim_{x \\to 3} \\frac{x^2 - 9}{x - 3}$$\n\n분자를 인수분해하면:\n$$\\lim_{x \\to 3} \\frac{(x-3)(x+3)}{x - 3}$$\n\n**Step 2: 분자의 형태를 미분계수 정의와 비교**\n\n분자 $x^2 - 9$를 $f(x) - f(a)$ 형태로 해석합니다.\n\n$f(x) = x^2$라고 하면:\n- $f(x) - f(a) = x^2 - a^2$\n\n주어진 식의 분자는 $x^2 - 9$이므로:\n$$x^2 - 9 = x^2 - 3^2$$\n\n따라서 $a^2 = 9$, 즉 $a = 3$ (양수)\n\n**Step 3: 확인**\n\n극한식을 미분계수 형태로 쓰면:\n$$\\lim_{x \\to 3} \\frac{f(x) - f(3)}{x - 3} = \\lim_{x \\to 3} \\frac{x^2 - 3^2}{x - 3} = f'(3)$$\n\n이는 $f(x) = x^2$에 대한 $f'(3)$입니다.\n\n**Step 4: 검산**\n\n$f(x) = x^2$일 때, $f'(x) = 2x$이므로:\n$$f'(3) = 2 \\times 3 = 6$$\n\n실제로 극한값도:\n$$\\lim_{x \\to 3} \\frac{(x-3)(x+3)}{x-3} = \\lim_{x \\to 3} (x+3) = 6$$ ✓\n\n**[정답 확인]**\n\n$f(x) = x^2$에서 $x=3$일 때의 미분계수는 $f'(3)$이므로, $a = 3$이 정답입니다.\n\n**[오답 분석]**\n\n- **① 1**: 극한식을 $\\frac{x^2-1}{x-3}$ 형태로 잘못 해석한 경우\n- **② 2**: $a$를 극한점의 절반으로 오인한 경우\n- **④ 6**: $a$값과 미분계수값을 혼동한 경우 ($f'(3)=6$이지만 $a=3$)\n- **⑤ 9**: 분자의 상수항 9를 답으로 착각한 경우\n\n**[핵심 포인트]**\n\n- 극한식 $\\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a}$의 형태와 직접 비교하여 $a$값을 찾기\n- 분자와 분모의 영점이 같은 점이 바로 미분계수를 구하는 점 $x=a$입니다.",
