    "answer": 3,
    "explanation": "**[핵심 개념]**\n이 문제는 미분의 정의를 이용하는 극한 문제입니다. 함수 $f(x) = x^3$에 대해 $x=1$에서의 미분계수를 구하는 것과 같습니다. 미분계수의 정의는 $f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}$이며, 이를 직접 계산하거나 이항정리를 이용하여 풀 수 있습니다.\n\n**[풀이]**\n\n**방법 1: 이항정리 이용**\n\n$(1+h)^3$을 이항정리로 전개합니다.\n\n$$(1+h)^3 = 1 + 3h + 3h^2 + h^3$$\n\n따라서 분자는:\n$$(1+h)^3 - 1 = 1 + 3h + 3h^2 + h^3 - 1 = 3h + 3h^2 + h^3$$\n\n극한식에 대입하면:\n$$\\lim_{h \\to 0} \\frac{3h + 3h^2 + h^3}{h}$$\n\n분자를 $h$로 인수분해합니다:\n$$\\lim_{h \\to 0} \\frac{h(3 + 3h + h^2)}{h}$$\n\n$h \\neq 0$이므로 약분하면:\n$$\\lim_{h \\to 0} (3 + 3h + h^2)$$\n\n$h \\to 0$일 때:\n$$3 + 3(0) + 0^2 = 3$$\n\n**방법 2: 미분의 정의 이용**\n\n$f(x) = x^3$이라 하면, $f(1) = 1$이고, 주어진 극한은:\n$$\\lim_{h \\to 0} \\frac{f(1+h) - f(1)}{h} = f'(1)$$\n\n$f'(x) = 3x^2$이므로:\n$$f'(1) = 3(1)^2 = 3$$\n\n**[정답 확인]**\n분자를 $h$로 인수분해하여 약분한 후 극한을 계산하면 3이 나오므로, 정답은 **3**입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 일반적인 오답:\n- **1**: 분자를 잘못 전개하거나 $h$의 계수를 잘못 계산한 경우\n- **6**: $(1+h)^3 - 1 = h$로 잘못 계산한 경우\n- **0**: 극한을 제대로 계산하지 않고 $\\frac{0}{0}$ 꼴로 남긴 경우\n\n**[핵심 포인트]**\n- $\\frac{0}{0}$ 꼴의 부정형 극한은 **인수분해로 약분**하여 계산합니다.\n- 이 문제는 **$f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}$의 정의**를 직접 적용하는 미분계수 문제입니다.",
