    "answer": 2,
    "explanation": "**[핵심 개념]**\n미분의 정의와 다항함수의 미분법을 이용하여 도함수를 구하는 문제입니다.\n\n다항함수 $f(x) = x^n$의 도함수는 $f'(x) = nx^{n-1}$이고, 합의 미분법에 의해 각 항을 따로 미분하여 더합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n주어진 함수는 $f(x) = x^3 - 3x^2 + 2$입니다.\n\n각 항을 미분하면:\n- $(x^3)' = 3x^2$\n- $(-3x^2)' = -3 \\cdot 2x = -6x$\n- $(2)' = 0$ (상수의 미분은 0)\n\n따라서 도함수는:\n$$f'(x) = 3x^2 - 6x$$\n\n**2단계: $f'(2)$ 계산하기**\n\n$x = 2$를 도함수에 대입합니다:\n\n$$f'(2) = 3(2)^2 - 6(2)$$\n\n$$f'(2) = 3 \\cdot 4 - 12$$\n\n$$f'(2) = 12 - 12 = 0$$\n\n**[정답 확인]**\n$f'(2) = 0$이므로 정답은 **③번**입니다.\n\n**[오답 분석]**\n- ① -4: 계산 과정에서 음수를 잘못 처리한 경우\n- ② -2: 부분적으로만 계산하거나 미분을 잘못한 경우\n- ④ 2: $f'(2) = 12 - 12$에서 뺄셈을 덧셈으로 계산한 경우\n- ⑤ 4: 절댓값을 취하거나 계산 실수를 한 경우\n\n**[핵심 포인트]**\n다항함수의 미분은 각 항을 개별적으로 미분하는 것이 핵심입니다. 특히 도함수를 구한 후 주어진 $x$ 값을 정확히 대입하여 계산하는 과정에서 실수하지 않아야 합니다.",
