    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선을 구하는 문제입니다. 접선의 기울기는 그 점에서의 미분값(도함수)이고, 접선의 방정식은 점-기울기 형태로 구합니다.\n\n- 곡선 $y = f(x)$ 위의 점 $(a, f(a))$에서의 접선의 기울기: $f'(a)$\n- 접선의 방정식: $y - f(a) = f'(a)(x - a)$\n\n**[풀이]**\n\n**1단계: 주어진 점이 곡선 위에 있는지 확인**\n\n점 $(1, 2)$를 $y = x^3 + x$에 대입:\n$$y = 1^3 + 1 = 1 + 1 = 2 \\checkmark$$\n\n점 $(1, 2)$가 곡선 위에 있습니다.\n\n**2단계: 도함수 구하기**\n\n$$y = x^3 + x$$\n$$y' = 3x^2 + 1$$\n\n**3단계: $x = 1$에서의 접선의 기울기 구하기**\n\n$$m = y'(1) = 3(1)^2 + 1 = 3 + 1 = 4$$\n\n**4단계: 접선의 방정식 구하기**\n\n점 $(1, 2)$를 지나고 기울기가 $4$인 직선의 방정식:\n$$y - 2 = 4(x - 1)$$\n$$y - 2 = 4x - 4$$\n$$y = 4x - 2$$\n\n따라서 $y = mx + n$ 형태에서:\n$$m = 4, \\quad n = -2$$\n\n**5단계: $m + n$ 계산**\n\n$$m + n = 4 + (-2) = 2$$\n\n**[정답 확인]**\n접선의 기울기를 올바르게 구하고, 점-기울기 형태에서 기울기 절편 형태로 변환하여 $m = 4, n = -2$를 얻었으므로 $m + n = 2$가 정답입니다.\n\n**[오답 분석]**\n객관식이 아니므로 해당사항 없음\n\n**[핵심 포인트]**\n1. 접선의 기울기는 반드시 그 점에서의 도함수값이며, 점 $(a, f(a))$에서의 접선을 구할 때는 $f'(a)$를 계산해야 합니다.\n2. 접선의 방정식을 구한 후 $y = mx + n$ 형태로 정리할 때 계수를 정확히 읽어내야 합니다.",
