    "answer": 2,
    "explanation": "**[핵심 개념]**\n미분의 정의는 $f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}$ 입니다. 이 문제에서는 주어진 극한식의 형태가 미분의 정의와 다르므로, 식을 변형하여 미분의 정의 형태로 만들어야 합니다.\n\n**[풀이]**\n\n주어진 조건: $\\lim_{h \\to 0} \\dfrac{f(3+2h) - f(3)}{h} = 10$\n\n미분의 정의는 $f'(3) = \\lim_{h \\to 0} \\frac{f(3+h) - f(3)}{h}$ 입니다.\n\n주어진 극한식을 미분의 정의 형태로 변형하기 위해 분자와 분모를 정리합니다.\n\n$\\lim_{h \\to 0} \\dfrac{f(3+2h) - f(3)}{h}$에서 $u = 2h$로 치환하면:\n- $h \\to 0$일 때, $u \\to 0$\n- $h = \\dfrac{u}{2}$\n\n따라서:\n$$\\lim_{h \\to 0} \\dfrac{f(3+2h) - f(3)}{h} = \\lim_{u \\to 0} \\dfrac{f(3+u) - f(3)}{\\dfrac{u}{2}}$$\n\n$$= \\lim_{u \\to 0} \\dfrac{2[f(3+u) - f(3)]}{u}$$\n\n$$= 2 \\cdot \\lim_{u \\to 0} \\dfrac{f(3+u) - f(3)}{u}$$\n\n$$= 2 \\cdot f'(3)$$\n\n주어진 조건에서 이 값이 10이므로:\n$$2 \\cdot f'(3) = 10$$\n\n$$f'(3) = 5$$\n\n**[정답 확인]**\n주어진 극한식을 미분의 정의 형태로 변형하면 $2f'(3) = 10$이 되므로 $f'(3) = 5$입니다.\n\n**[오답 분석]**\n- ① 2: $f'(3)$의 값이 아니라 분자의 계수 2를 선택한 오류\n- ② 3: 특별한 계산 근거가 없는 임의의 선택\n- ④ 10: 주어진 극한값 자체를 $f'(3)$으로 착각한 오류\n- ⑤ 20: $10 \\times 2$를 계산한 역순 오류 (분자와 분모를 반대로 생각)\n\n**[핵심 포인트]**\n주어진 극한식이 미분의 정의와 계수가 다를 때는 $u = kh$ 형태로 치환하여 $\\lim_{u \\to 0} \\dfrac{f(a+u) - f(a)}{u} = f'(a)$ 형태로 변환하는 것이 핵심입니다. 이때 계수는 분모에 나타나므로 주의해야 합니다.",
