    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n도함수의 정의는 $f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}$ 입니다. 이 문제에서는 주어진 극한식이 도함수의 정의와 다른 형태이므로, 이를 표준 형태로 변환하는 과정이 중요합니다. 주어진 식을 분해하여 도함수 정의와의 관계를 찾아야 합니다.\n\n**[풀이]**\n\n주어진 극한식을 정리합니다:\n$$\\lim_{h \\to 0} \\frac{f(2+h) - f(2-h)}{h} = 8$$\n\n분자를 다시 쓰기 위해 $f(2)$를 더하고 빼면:\n$$\\lim_{h \\to 0} \\frac{f(2+h) - f(2) + f(2) - f(2-h)}{h} = 8$$\n\n이를 두 부분으로 분리합니다:\n$$\\lim_{h \\to 0} \\left\\{ \\frac{f(2+h) - f(2)}{h} + \\frac{f(2) - f(2-h)}{h} \\right\\} = 8$$\n\n첫 번째 항은 도함수의 정의 그대로입니다:\n$$\\lim_{h \\to 0} \\frac{f(2+h) - f(2)}{h} = f'(2)$$\n\n두 번째 항에서 $u = -h$로 치환하면 ($h \\to 0$일 때 $u \\to 0$):\n$$\\lim_{h \\to 0} \\frac{f(2) - f(2-h)}{h} = \\lim_{u \\to 0} \\frac{f(2) - f(2+u)}{-u} = \\lim_{u \\to 0} \\frac{f(2+u) - f(2)}{u} = f'(2)$$\n\n따라서:\n$$f'(2) + f'(2) = 8$$\n$$2f'(2) = 8$$\n$$f'(2) = 4$$\n\n**[정답 확인]**\n\n주어진 극한식이 $f'(2)$의 두 배와 같으므로, $f'(2) = 4$가 정답입니다.\n\n**[오답 분석]**\n\n- ① 2: $f'(2)$를 4로 나눈 값\n- ② 3: 특별한 의미 없는 오답\n- ④ 6: 주어진 극한값 8과 $f'(2)$의 관계를 잘못 이해한 경우\n- ⑤ 8: 주어진 극한값을 $f'(2)$로 착각한 오답 (극한값 = $2f'(2)$임을 간과)\n\n**[핵심 포인트]**\n\n$\\lim_{h \\to 0} \\frac{f(a+h) - f(a-h)}{h}$ 형태의 극한은 $2f'(a)$와 같습니다. 주어진 식을 항상 표준 도함수 형태로 변환하는 습관을 들이세요.",
