    "answer": 0,
    "explanation": "**[핵심 개념]**\n곡선 위의 점에서의 접선의 기울기는 그 점에서의 미분값(도함수)과 같습니다. 함수 $f(x)$에서 $x=a$인 점에서의 접선의 기울기는 $f'(a)$입니다. 따라서 기울기가 주어진 접선을 찾기 위해서는 $f'(x) = $(주어진 기울기) 방정식을 풀어야 합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = x^3 - 6x$를 미분하면:\n$$f'(x) = 3x^2 - 6$$\n\n**Step 2: 접선의 기울기가 6이 되는 조건**\n\n접선의 기울기가 6이라는 것은 $f'(x) = 6$을 만족하는 $x$를 찾는 것입니다.\n\n$$f'(x) = 6$$\n$$3x^2 - 6 = 6$$\n\n**Step 3: 방정식 풀기**\n\n$$3x^2 - 6 = 6$$\n$$3x^2 = 12$$\n$$x^2 = 4$$\n$$x = 2 \\text{ 또는 } x = -2$$\n\n**Step 4: 두 근의 합 구하기**\n\n접선의 기울기가 6인 두 점의 $x$ 좌표는 $x = 2$와 $x = -2$입니다.\n\n따라서 $x$ 좌표의 합은:\n$$2 + (-2) = 0$$\n\n**[정답 확인]**\n$f'(2) = 3(2)^2 - 6 = 12 - 6 = 6$ ✓, $f'(-2) = 3(-2)^2 - 6 = 12 - 6 = 6$ ✓이므로, 두 점 모두에서 접선의 기울기가 6이며, 합은 0입니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으나, 흔한 오류:\n- $x = 2$만 고려하여 답을 2로 하는 경우: 음수 해를 놓쳤음\n- $x = -2$만 고려하여 답을 -2로 하는 경우: 양수 해를 놓쳤음\n- 계산 실수로 $x^2 = 4$에서 양수 해만 취하는 경우: 이차방정식은 두 근을 모두 찾아야 함\n\n**[핵심 포인트]**\n- 접선의 기울기 조건 → $f'(x) = $ (주어진 기울기)\n- 이차방정식은 반드시 두 근을 모두 구해야 하며, 특히 \"근의 합\"을 구할 때는 비에타 공식($x_1 + x_2 = -\\frac{b}{a}$)이나 직접 계산을 통해 모든 근을 포함시켜야 합니다.",
