    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 방정식을 구하고, 그 접선이 주어진 점을 지날 조건을 이용합니다.\n- 곡선 $y = f(x)$ 위의 점 $(a, f(a))$에서의 접선의 기울기: $f'(a)$\n- 접선의 방정식: $y - f(a) = f'(a)(x - a)$\n- 접선이 특정 점을 지나면 그 점의 좌표를 접선의 방정식에 대입하면 성립\n\n**[풀이]**\n\n**1단계: 접선의 기울기 구하기**\n\n곡선 $y = x^3$을 미분하면:\n$$y' = 3x^2$$\n\n$x = a$에서의 접선의 기울기는:\n$$m = 3a^2$$\n\n**2단계: 접선의 방정식 세우기**\n\n점 $(a, a^3)$에서의 접선의 방정식은:\n$$y - a^3 = 3a^2(x - a)$$\n\n정리하면:\n$$y = 3a^2 x - 3a^3 + a^3$$\n$$y = 3a^2 x - 2a^3$$\n\n**3단계: 접선이 점 $(0, -2)$를 지나는 조건**\n\n점 $(0, -2)$를 접선의 방정식에 대입:\n$$-2 = 3a^2 \\cdot 0 - 2a^3$$\n$$-2 = -2a^3$$\n$$a^3 = 1$$\n$$a = 1$$\n\n**4단계: 검산**\n\n$a = 1$일 때, 접선의 방정식: $y = 3x - 2$\n- 점 $(0, -2)$를 지나는가? $-2 = 3(0) - 2 = -2$ ✓\n- 곡선 위의 점 $(1, 1)$을 지나는가? $1 = 3(1) - 2 = 1$ ✓\n\n**[정답 확인]**\n$a = 1$을 접선 방정식에 대입하면 $y = 3x - 2$이고, 이 직선이 점 $(0, -2)$를 정확히 지나므로 정답입니다.\n\n**[오답 분석]**\n선택지가 주어지지 않았으므로, 흔한 실수를 언급하면:\n- $a = -1$: $-2 = -2(-1)^3 = 2$ (거짓)\n- $a = 0$: $-2 = 0$ (거짓)\n- $a = 2$: $-2 = -2(8) = -16$ (거짓)\n\n**[핵심 포인트]**\n- 접선의 방정식을 구한 후, 주어진 점을 지나는 조건으로부터 방정식을 세운다.\n- 접선 방정식에서 상수항이 $-2a^3$인 점에 주목: 이것이 $y$절편이 되어 $(0, -2)$를 지나는 조건을 직접 줍니다.",
