    "explanation": "**[핵심 개념]**\n이 문제는 다항함수의 미분과 조건을 이용한 미지수 결정 문제입니다.\n- 주어진 함수를 미분하여 $f'(x)$를 구합니다.\n- $f'(1) = 0$과 $f(1) = 3$이라는 두 조건으로부터 $a$, $b$의 값을 구합니다.\n\n**[풀이]**\n\n**Step 1: 함수를 미분하기**\n\n$f(x) = x^2 + ax + b$에서\n\n$$f'(x) = 2x + a$$\n\n**Step 2: 첫 번째 조건 $f'(1) = 0$ 적용**\n\n$$f'(1) = 2(1) + a = 0$$\n$$2 + a = 0$$\n$$a = -2$$\n\n**Step 3: 두 번째 조건 $f(1) = 3$ 적용**\n\n$$f(1) = 1^2 + a(1) + b = 3$$\n$$1 + a + b = 3$$\n\n$a = -2$를 대입하면:\n\n$$1 + (-2) + b = 3$$\n$$-1 + b = 3$$\n$$b = 4$$\n\n**Step 4: $a + b$ 계산**\n\n$$a + b = -2 + 4 = 2$$\n\n**[정답 확인]**\n$a = -2$, $b = 4$일 때 $f(x) = x^2 - 2x + 4$이고, $f'(1) = 2 - 2 = 0$ ✓, $f(1) = 1 - 2 + 4 = 3$ ✓을 만족하므로 $a + b = 2$가 정답입니다.\n\n**[오답 분석]**\n- ① 0: $a + b = -2 + 4 = 2$가 아닌 0으로 계산 오류\n- ② 1: 두 조건 중 하나만 정확히 적용하거나 부분 계산 오류\n- ④ 3: $a = -2$에서 $b$를 5로 잘못 계산\n- ⑤ 4: $b$의 값만 선택하는 오류\n\n**[핵심 포인트]**\n- 다항함수는 항별로 미분: $x^2$ → $2x$, $ax$ → $a$, 상수 → $0$\n- 주어진 조건을 순서대로 적용하면 미지수를 체계적으로 구할 수 있습니다.",
