    "explanation": "**[핵심 개념]**\n미분의 정의: $f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}$\n\n주어진 극한식을 미분의 정의 형태로 변환하기 위해 분자를 적절히 분리하는 방법이 중요합니다. 분자에 $f(1)$을 더하고 빼서 두 개의 미분 형태를 만들 수 있습니다.\n\n**[풀이]**\n\n**Step 1: 분자를 전개하기**\n\n주어진 극한식의 분자를 다시 쓰면:\n$$f(1+3h) - f(1-2h)$$\n\n분자에 $f(1)$을 더하고 빼서 정리합니다:\n$$f(1+3h) - f(1-2h) = [f(1+3h) - f(1)] + [f(1) - f(1-2h)]$$\n\n**Step 2: 극한식 변형**\n\n$$\\lim_{h \\to 0} \\frac{f(1+3h) - f(1-2h)}{h} = \\lim_{h \\to 0} \\frac{[f(1+3h) - f(1)] + [f(1) - f(1-2h)]}{h}$$\n\n이를 두 개의 극한으로 분리합니다:\n$$= \\lim_{h \\to 0} \\frac{f(1+3h) - f(1)}{h} + \\lim_{h \\to 0} \\frac{f(1) - f(1-2h)}{h}$$\n\n**Step 3: 미분의 정의 형태로 변환**\n\n첫 번째 항:\n$$\\lim_{h \\to 0} \\frac{f(1+3h) - f(1)}{h} = \\lim_{h \\to 0} \\frac{f(1+3h) - f(1)}{3h} \\cdot 3 = 3f'(1)$$\n\n두 번째 항을 정리하기 위해 $f(1) - f(1-2h) = -[f(1-2h) - f(1)]$이므로:\n$$\\lim_{h \\to 0} \\frac{f(1) - f(1-2h)}{h} = \\lim_{h \\to 0} \\frac{-[f(1-2h) - f(1)]}{h}$$\n\n$h \\to 0$일 때 $-2h \\to 0$이므로:\n$$= \\lim_{h \\to 0} \\frac{-[f(1-2h) - f(1)]}{-2h} \\cdot 2 = 2f'(1)$$\n\n**Step 4: 결과 계산**\n\n$$3f'(1) + 2f'(1) = 25$$\n$$5f'(1) = 25$$\n$$f'(1) = 5$$\n\n**[정답 확인]**\n$5f'(1) = 25$에서 $f'(1) = 5$가 맞으므로 정답은 ③입니다.\n\n**[오답 분석]**\n- ① 3: $3f'(1) = 25$로 잘못 계산한 경우\n- ② 4: 계수를 잘못 처리한 경우\n- ④ 7: 극한 계산 과정에서 산술 오류\n- ⑤ 25: 극한값 자체를 $f'(1)$으로 착각한 경우\n\n**[핵심 포인트]**\n분자에 $f(a)$를 더하고 빼서 미분의 정의 형태를 만들고, 각 항의 계수(여기서는 3과 2)를 정확히 계산하는 것이 중요합니다.",
