    "explanation": "**[핵심 개념]**\n곡선 $y = f(x)$ 위의 점 $(a, f(a))$에서의 접선의 기울기는 $f'(a)$입니다. 주어진 기울기를 가진 접선을 찾기 위해서는 $f'(x) = $ (주어진 기울기)를 만족하는 $x$값을 구하면 됩니다. 이 방정식이 두 개 이상의 해를 가지면 여러 개의 접선이 존재합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 3x$$\n$$f'(x) = 3x^2 - 3$$\n\n**2단계: 기울기 조건 설정**\n기울기가 9인 접선이 존재하므로:\n$$f'(x) = 9$$\n$$3x^2 - 3 = 9$$\n$$3x^2 = 12$$\n$$x^2 = 4$$\n$$x = 2 \\text{ 또는 } x = -2$$\n\n두 접점의 $x$좌표가 $x_1 = -2$, $x_2 = 2$입니다.\n\n**3단계: 각 접점에서의 $y$좌표 구하기**\n\n$x = -2$일 때:\n$$f(-2) = (-2)^3 - 3(-2) = -8 + 6 = -2$$\n\n$x = 2$일 때:\n$$f(2) = (2)^3 - 3(2) = 8 - 6 = 2$$\n\n**4단계: $y$좌표의 합 계산**\n$$f(-2) + f(2) = -2 + 2 = 0$$\n\n**[정답 확인]**\n$f'(x) = 9$에서 $x = \\pm 2$를 얻고, 이 두 점의 $y$좌표는 각각 $-2$와 $2$이므로 합은 $0$입니다.\n\n**[오답 분석]**\n- ① $-2$: $x = -2$일 때의 $y$좌표만 구한 경우\n- ② $-1$: 계산 실수로 한 좌표값을 잘못 구한 경우\n- ④ $1$: 도함수 계산이나 대입 과정에서 실수\n- ⑤ $2$: $x = 2$일 때의 $y$좌표만 구한 경우\n\n**[핵심 포인트]**\n- 접선의 기울기 조건 $f'(x) = m$에서 나온 두 해가 대칭점($x = -2, 2$)일 때, 함수의 대칭성을 이용하면 $y$값의 합이 0이 됨을 빠르게 파악할 수 있습니다.\n- 항상 두 접점의 좌표를 모두 구한 후 합을 계산하는 것이 정확합니다.",
