    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 방정식을 구하기 위해서는 다음 두 가지를 알아야 합니다.\n1. 접선의 기울기 = 그 점에서의 미분값(도함수의 함숫값)\n2. 접선의 방정식: 점 $(x_0, y_0)$에서의 접선은 $y - y_0 = f'(x_0)(x - x_0)$\n\n**[풀이]**\n\n**Step 1: 주어진 점이 곡선 위에 있는지 확인**\n$y = x^3 - x$에 $x = 1$을 대입하면:\n$$y = 1^3 - 1 = 0$$\n따라서 점 $(1, 0)$은 곡선 위에 있습니다. ✓\n\n**Step 2: 도함수를 구하여 접선의 기울기 구하기**\n$$f(x) = x^3 - x$$\n$$f'(x) = 3x^2 - 1$$\n\n$x = 1$에서의 미분값:\n$$f'(1) = 3(1)^2 - 1 = 3 - 1 = 2$$\n\n따라서 접선의 기울기는 $m = 2$입니다.\n\n**Step 3: 접선의 방정식 구하기**\n점 $(1, 0)$을 지나고 기울기가 $2$인 직선의 방정식:\n$$y - 0 = 2(x - 1)$$\n$$y = 2x - 2$$\n\n따라서 $y = mx + n$ 형태로 나타내면:\n$$m = 2, \\quad n = -2$$\n\n**Step 4: $m - n$ 계산**\n$$m - n = 2 - (-2) = 2 + 2 = 4$$\n\n**[정답 확인]**\n접선의 기울기가 2, y절편이 -2이므로 $m - n = 2 - (-2) = 4$입니다.\n\n**[오답 분석]**\n- ① 1: 기울기와 y절편의 관계를 잘못 계산한 경우\n- ② 2: $m$의 값만 답으로 선택한 경우\n- ③ 3: $m - n = 2 - (-1)$로 잘못 계산한 경우\n- ⑤ 5: $m + n = 2 + (-2) = 0$을 계산하지 않고 다른 값으로 계산한 경우\n\n**[핵심 포인트]**\n1. 접선의 기울기는 **그 점에서의 도함수값**이며, 접선의 방정식은 **점-기울기 형태**로 구합니다.\n2. y절편 $n$이 음수일 수 있으므로 $m - n$을 계산할 때 **부호에 주의**해야 합니다.",
