    "answer": 1,
    "explanation": "**[핵심 개념]**\n곱의 미분법(Product Rule)을 이용하여 두 함수의 곱으로 표현된 함수를 미분합니다. 두 함수 $u(x)$와 $v(x)$가 미분가능할 때, $(u \\cdot v)' = u' \\cdot v + u \\cdot v'$입니다.\n\n**[풀이]**\n$g(x) = x^2 f(x)$를 미분하기 위해 곱의 미분법을 적용합니다.\n\n$u(x) = x^2$, $v(x) = f(x)$로 놓으면:\n- $u'(x) = 2x$\n- $v'(x) = f'(x)$\n\n곱의 미분법에 의해:\n$$g'(x) = (x^2)' \\cdot f(x) + x^2 \\cdot (f(x))'$$\n\n$$g'(x) = 2x \\cdot f(x) + x^2 \\cdot f'(x)$$\n\n이제 $x = 1$을 대입합니다:\n$$g'(1) = 2(1) \\cdot f(1) + 1^2 \\cdot f'(1)$$\n\n$$g'(1) = 2f(1) + f'(1)$$\n\n**[정답 확인]**\n곱의 미분법을 정확하게 적용하여 $g'(1) = 2f(1) + f'(1)$를 얻었으므로 정답은 **②**입니다.\n\n**[오답 분석]**\n- ① $f(1) + f'(1)$: $x^2$의 도함수인 $2x$에서 계수 2를 누락한 경우\n- ③ $f(1) + 2f'(1)$: 첫 번째 항과 두 번째 항의 계수를 바꾼 경우\n- ④ $2f(1) + 2f'(1)$: 두 항 모두에 계수 2를 곱한 잘못된 경우\n- ⑤ $f'(1)$: 첫 번째 항 $2f(1)$을 누락한 경우\n\n**[핵심 포인트]**\n곱의 미분법에서 $(x^2 \\cdot f(x))' = 2x \\cdot f(x) + x^2 \\cdot f'(x)$이며, $x=1$을 대입할 때 첫 번째 항에서 계수 2가 살아남는 점을 주의해야 합니다.",
