    "explanation": "**[핵심 개념]**\n- 극값의 조건: 함수 $f(x)$가 $x=c$에서 극값을 가지면 $f'(c) = 0$\n- 도함수: $f(x) = x^3 + ax^2 + bx + 1$이면 $f'(x) = 3x^2 + 2ax + b$\n- 주어진 두 조건을 연립하여 미지수 $a, b$를 구함\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 + ax^2 + bx + 1$$\n$$f'(x) = 3x^2 + 2ax + b$$\n\n**Step 2: 극값 조건 적용**\n\n$f(x)$가 $x=1$에서 극값을 가지므로:\n$$f'(1) = 0$$\n$$3(1)^2 + 2a(1) + b = 0$$\n$$3 + 2a + b = 0 \\quad \\cdots (1)$$\n\n**Step 3: $f'(-1) = 0$ 조건 적용**\n\n$$f'(-1) = 0$$\n$$3(-1)^2 + 2a(-1) + b = 0$$\n$$3 - 2a + b = 0 \\quad \\cdots (2)$$\n\n**Step 4: 연립방정식 풀이**\n\n식 (1)과 식 (2)를 더하면:\n$$(3 + 2a + b) + (3 - 2a + b) = 0$$\n$$6 + 2b = 0$$\n$$b = -3$$\n\n식 (1)에 $b = -3$을 대입:\n$$3 + 2a - 3 = 0$$\n$$2a = 0$$\n$$a = 0$$\n\n**Step 5: $a + b$ 계산**\n\n$$a + b = 0 + (-3) = -3$$\n\n**[정답 확인]**\n$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$이므로 $x=1$과 $x=-1$에서 극값을 가지며, 두 조건을 모두 만족합니다.\n\n**[오답 분석]**\n객관식 선택지가 주어지지 않았으나, 흔한 오답:\n- $a = 0, b = -3$을 잘못 계산하면 다른 값이 나옴\n- 식 (1)과 (2)를 빼기만 하면 $b$를 놓칠 수 있음\n\n**[핵심 포인트]**\n극값 조건에서 나오는 두 개의 선형 방정식 $f'(1) = 0$과 $f'(-1) = 0$을 연립하여 풀 때, 두 식을 더하면 $a$가 소거되고 $b$를 먼저 구할 수 있습니다.",
