    "problem": "$f(x) = x^4 - 2x^3 + x$의 도함수 $f'(x)$에서 $f'(1)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": -1,
    "explanation": "**[핵심 개념]**\n도함수는 함수의 순간변화율을 나타내며, 다항함수의 도함수는 멱의 법칙(power rule)을 이용하여 구합니다.\n멱의 법칙: $\\frac{d}{dx}(x^n) = nx^{n-1}$\n상수의 도함수는 0이고, 각 항의 도함수를 구한 후 더합니다.\n\n**[풀이]**\n주어진 함수: $f(x) = x^4 - 2x^3 + x$\n\n**Step 1: 각 항의 도함수 구하기**\n- $\\frac{d}{dx}(x^4) = 4x^3$\n- $\\frac{d}{dx}(-2x^3) = -2 \\cdot 3x^2 = -6x^2$\n- $\\frac{d}{dx}(x) = 1$\n\n**Step 2: 도함수 정리**\n$$f'(x) = 4x^3 - 6x^2 + 1$$\n\n**Step 3: $f'(1)$ 계산**\n$$f'(1) = 4(1)^3 - 6(1)^2 + 1$$\n$$f'(1) = 4 \\cdot 1 - 6 \\cdot 1 + 1$$\n$$f'(1) = 4 - 6 + 1$$\n$$f'(1) = -1$$\n\n**[정답 확인]**\n도함수 공식을 올바르게 적용하고 $x=1$을 대입하면 $4 - 6 + 1 = -1$이므로 정답입니다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 없음.\n\n**[핵심 포인트]**\n- 다항함수의 각 항에 멱의 법칙을 적용할 때, 계수와 지수를 정확히 곱하고 지수를 1씩 줄이기\n- 도함수를 구한 후 주어진 $x$ 값을 대입하여 최종 답을 구하기",
