    "explanation": "**[핵심 개념]**\n도함수를 구하는 방법은 두 가지가 있습니다.\n1) 전개한 후 미분: 함수를 전개하여 다항식 형태로 만든 후 미분\n2) 곱의 미분법: $(u \\cdot v)' = u'v + uv'$ 공식 사용\n\n다항식의 기본 미분법은 $\\frac{d}{dx}(x^n) = nx^{n-1}$이고, 상수의 미분은 0입니다.\n\n**[풀이]**\n\n**방법 1: 전개 후 미분**\n\n$f(x) = (x+1)(x-3)$을 먼저 전개합니다.\n\n$$f(x) = x^2 - 3x + x - 3 = x^2 - 2x - 3$$\n\n이제 각 항을 미분합니다.\n\n$$f'(x) = \\frac{d}{dx}(x^2) + \\frac{d}{dx}(-2x) + \\frac{d}{dx}(-3)$$\n\n$$f'(x) = 2x - 2 + 0 = 2x - 2$$\n\n**방법 2: 곱의 미분법**\n\n$u = x + 1$, $v = x - 3$로 놓으면, $u' = 1$, $v' = 1$입니다.\n\n곱의 미분법을 적용하면:\n\n$$f'(x) = u'v + uv' = 1 \\cdot (x-3) + (x+1) \\cdot 1$$\n\n$$= x - 3 + x + 1 = 2x - 2$$\n\n**[정답 확인]**\n$f(x) = x^2 - 2x - 3$을 미분하면 $f'(x) = 2x - 2$가 되므로 ②번이 정답입니다.\n\n**[오답 분석]**\n- ① $2x$: 상수항 $-3$을 미분할 때 나오는 $-2$를 빼먹은 경우\n- ③ $2x + 2$: 전개 후 부호를 잘못 처리하여 $x^2 + 2x - 3$으로 계산한 경우\n- ④ $x - 1$: $f'(x) = 2x - 2$를 2로 나눈 경우 (미분 규칙 오류)\n- ⑤ $2x - 3$: 원래 함수의 상수항 $-3$을 미분 결과로 잘못 옮긴 경우\n\n**[핵심 포인트]**\n곱셈 형태의 함수를 미분할 때는 **전개하여 정리한 후 미분하는 것**이 부호 실수를 줄일 수 있는 가장 확실한 방법입니다. 항상 계산 마지막에 상수항이 미분되어 0이 됨을 확인하세요.",
