    "explanation": "**[핵심 개념]**\n미분의 정의와 다항함수의 미분 공식을 이용하여 도함수를 구하고, 특정 점에서의 미분값을 구하는 문제입니다.\n\n다항함수 $f(x) = ax^n$의 도함수는 $f'(x) = nax^{n-1}$입니다.\n- 상수항의 도함수는 0입니다.\n- 각 항을 따로 미분한 후 더합니다.\n\n**[풀이]**\n\n**Step 1: 주어진 함수의 도함수 구하기**\n\n$f(x) = 5x^3 - x + 7$을 미분합니다.\n\n각 항을 따로 미분하면:\n- $\\frac{d}{dx}(5x^3) = 5 \\cdot 3x^2 = 15x^2$\n- $\\frac{d}{dx}(-x) = -1$\n- $\\frac{d}{dx}(7) = 0$ (상수항)\n\n따라서 도함수는:\n$$f'(x) = 15x^2 - 1$$\n\n**Step 2: $x = 0$을 대입하기**\n\n$$f'(0) = 15(0)^2 - 1 = 0 - 1 = -1$$\n\n**[정답 확인]**\n$f'(0) = -1$이므로 정답은 **①번**입니다.\n\n**[오답 분석]**\n- ② 0: $15(0)^2$의 값만 계산한 경우\n- ③ 1: 부호를 반대로 계산한 경우\n- ④ 5: 원함수 $f(x)$의 $x^3$의 계수를 잘못 선택한 경우\n- ⑤ 7: 원함수의 상수항을 선택한 경우\n\n**[핵심 포인트]**\n다항함수를 미분할 때는 각 항을 따로 미분하되, **상수항은 0**이 됨을 잊지 말아야 합니다. 도함수를 구한 후 주어진 $x$값을 대입하여 최종 답을 구합니다.",
