    "answer": 0,
    "explanation": "**[핵심 개념]**\n다항함수의 도함수는 멱의 법칙(power rule)을 이용하여 구합니다. $x^n$의 도함수는 $nx^{n-1}$이고, 상수의 도함수는 0입니다. 또한 도함수의 계수를 구하는 문제에서는 $f'(1)$의 값이 $a + b + c$와 같다는 성질을 활용할 수 있습니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$f(x) = -x^3 + 6x^2 - 9x + 2$에 멱의 법칙을 적용합니다.\n\n$$f'(x) = -3x^2 + 12x - 9$$\n\n**2단계: 계수 확인**\n\n$f'(x) = ax^2 + bx + c$ 형태와 비교하면:\n- $a = -3$\n- $b = 12$\n- $c = -9$\n\n**3단계: $a + b + c$ 계산**\n\n$$a + b + c = -3 + 12 + (-9) = -3 + 12 - 9 = 0$$\n\n또는 다음과 같이 확인할 수 있습니다:\n$$f'(1) = -3(1)^2 + 12(1) - 9 = -3 + 12 - 9 = 0$$\n\n따라서 $a + b + c = f'(1) = 0$\n\n**[정답 확인]**\n도함수의 계수를 정확히 구한 후 더하면 0이 되므로 정답은 0입니다.\n\n**[오답 분석]**\n주어진 문제가 객관식이 아니므로 오답 분석은 생략합니다. 다만 계산 실수가 발생할 수 있는 부분은:\n- 음수 계수에서 부호 실수 ($-3$을 $3$으로 계산)\n- 미분 과정에서 계수 계산 실수 ($6x^2$을 미분할 때 $12x$가 아닌 다른 값)\n- 덧셈 계산 실수\n\n**[핵심 포인트]**\n1. $f'(x) = ax^2 + bx + c$일 때, $a + b + c = f'(1)$입니다. 이를 이용하면 각 계수를 구한 후 더할 필요 없이 직접 $f'(1)$을 계산할 수 있습니다.\n2. 음수 계수의 부호에 항상 주의하며 도함수를 구해야 합니다.",
