    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. \n- 극값의 후보: $f'(x) = 0$인 점\n- 극대/극소 판정: 도함수의 부호 변화를 확인\n  - $f'(x)$가 양(+)에서 음(-)으로 변하면 극대\n  - $f'(x)$가 음(-)에서 양(+)으로 변하면 극소\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 - 3x + 2$$\n$$f'(x) = 3x^2 - 3$$\n\n**Step 2: 극값의 후보 찾기**\n\n$f'(x) = 0$인 점을 구합니다.\n\n$$3x^2 - 3 = 0$$\n$$3(x^2 - 1) = 0$$\n$$x^2 = 1$$\n$$x = \\pm 1$$\n\n극값의 후보는 $x = -1$과 $x = 1$입니다.\n\n**Step 3: 극대/극소 판정**\n\n도함수 $f'(x) = 3(x-1)(x+1)$의 부호를 구간별로 확인합니다.\n\n| 구간 | $x < -1$ | $-1 < x < 1$ | $x > 1$ |\n|------|----------|--------------|---------|\n| $(x+1)$ | $-$ | $+$ | $+$ |\n| $(x-1)$ | $-$ | $-$ | $+$ |\n| $f'(x)$ | $+$ | $-$ | $+$ |\n\n- $x = -1$에서: $f'(x)$가 $+$에서 $-$로 변함 → **극대**\n- $x = 1$에서: $f'(x)$가 $-$에서 $+$로 변함 → 극소\n\n따라서 극대가 되는 $x$의 값은 $\\boxed{-1}$입니다.\n\n**[정답 확인]**\n$x = -1$에서 도함수가 양에서 음으로 변하므로 극대이며, 이는 정답 ②와 일치합니다.\n\n**[오답 분석]**\n- ① $x = -2$: $f'(-2) = 12 - 3 = 9 \\neq 0$ (극값이 아님)\n- ③ $x = 0$: $f'(0) = -3 \\neq 0$ (극값이 아님)\n- ④ $x = 1$: $f'(1) = 0$이지만 극소 (극대가 아님)\n- ⑤ $x = 2$: $f'(2) = 12 - 3 = 9 \\neq 0$ (극값이 아님)\n\n**[핵심 포인트]**\n극값 판정은 $f'(x) = 0$인 점을 찾은 후, **그 점에서 도함수의 부호가 어떻게 변하는지** 확인하는 것이 가장 중요합니다. 극대는 $f'(x)$가 양에서 음으로 변하는 지점입니다.",
