    "answer": 0,
    "explanation": "**[핵심 개념]**\n함수 $f(x)$가 증가하는 구간을 구하기 위해서는 도함수 $f'(x)$를 구하고, $f'(x) > 0$인 $x$의 범위를 찾아야 합니다. \n- 함수의 증감: $f'(x) > 0$이면 증가, $f'(x) < 0$이면 감소\n- 도함수가 0이 되는 점들이 극값의 후보점이 됩니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 - 12x + 5$$\n$$f'(x) = 3x^2 - 12$$\n\n**Step 2: 도함수가 0이 되는 점 찾기**\n$$f'(x) = 0$$\n$$3x^2 - 12 = 0$$\n$$3(x^2 - 4) = 0$$\n$$x^2 = 4$$\n$$x = \\pm 2$$\n\n**Step 3: 도함수의 부호 판정**\n$f'(x) = 3(x^2 - 4) = 3(x-2)(x+2)$의 부호를 구간별로 조사합니다.\n\n- $x < -2$일 때: $(x-2) < 0$, $(x+2) < 0$ → $f'(x) = 3(-)(-) = 3(+) > 0$ ✓ **증가**\n- $-2 < x < 2$일 때: $(x-2) < 0$, $(x+2) > 0$ → $f'(x) = 3(-)(+) = 3(-) < 0$ ✓ **감소**\n- $x > 2$일 때: $(x-2) > 0$, $(x+2) > 0$ → $f'(x) = 3(+)(+) = 3(+) > 0$ ✓ **증가**\n\n**Step 4: 결론**\n$f(x)$가 증가하는 $x$의 범위는 $f'(x) > 0$인 구간이므로:\n$$x < -2 \\text{ 또는 } x > 2$$\n\n**[정답 확인]**\n도함수의 부호가 양수인 구간인 $x < -2$ 또는 $x > 2$에서 함수가 증가하므로 정답은 **①**입니다.\n\n**[오답 분석]**\n- **②** $-2 < x < 2$: 이 구간에서 $f'(x) < 0$이므로 함수는 **감소**합니다.\n- **③** $x > 0$: $0 < x < 2$에서는 감소하므로 전체 범위에서 증가하지 않습니다.\n- **④** $x < -2$: 맞지만 불완전한 답입니다. $x > 2$도 증가 구간입니다.\n- **⑤** $x > 2$: 맞지만 불완전한 답입니다. $x < -2$도 증가 구간입니다.\n\n**[핵심 포인트]**\n- 함수의 증감을 판정할 때는 도함수의 부호를 조사하는 것이 기본입니다.\n- 도함수가 인수분해될 때는 각 인수의 부호를 구간별로 판단하면 효율적입니다.",
