    "answer": -12,
    "explanation": "**[핵심 개념]**\n\n함수가 특정 점에서 극값을 가지려면 그 점에서 도함수가 0이 되어야 합니다. 즉, $f'(x) = 0$인 점이 극값의 후보점입니다. $f'(x) = 0$의 해가 $x = -1, 3$이면, $f'(x)$를 $(x+1)(x-3)$으로 인수분해할 수 있습니다. 또한 $x = -1$에서 극대, $x = 3$에서 극소를 가지려면 $x = -1$ 좌우에서 $f'(x)$의 부호가 양에서 음으로 바뀌고, $x = 3$ 좌우에서 음에서 양으로 바뀌어야 합니다.\n\n**[풀이]**\n\n주어진 함수는 $f(x) = x^3 + ax^2 + bx + 1$이므로 도함수는:\n$$f'(x) = 3x^2 + 2ax + b$$\n\n함수가 $x = -1$과 $x = 3$에서 극값을 가지므로, $f'(-1) = 0$과 $f'(3) = 0$을 만족합니다.\n\n$f'(-1) = 0$에서:\n$$3(-1)^2 + 2a(-1) + b = 0$$\n$$3 - 2a + b = 0$$\n$$b = 2a - 3 \\cdots (1)$$\n\n$f'(3) = 0$에서:\n$$3(3)^2 + 2a(3) + b = 0$$\n$$27 + 6a + b = 0$$\n$$b = -6a - 27 \\cdots (2)$$\n\n식 (1)과 (2)를 연립하면:\n$$2a - 3 = -6a - 27$$\n$$8a = -24$$\n$$a = -3$$\n\n식 (1)에 $a = -3$을 대입:\n$$b = 2(-3) - 3 = -6 - 3 = -9$$\n\n따라서:\n$$a + b = -3 + (-9) = -12$$\n\n**[검증]**\n$f'(x) = 3x^2 - 6x - 9 = 3(x^2 - 2x - 3) = 3(x+1)(x-3)$\n\n부호 변화: $x < -1$일 때 $f'(x) > 0$, $-1 < x < 3$일 때 $f'(x) < 0$, $x > 3$일 때 $f'(x) > 0$\n\n따라서 $x = -1$에서 극대, $x = 3$에서 극소를 가집니다. ✓\n\n**[정답 확인]**\n\n$a = -3, b = -9$일 때 도함수 $f'(x) = 3(x+1)(x-3)$이 되어 주어진 조건을 모두 만족하므로, $a + b = -12$가 정답입니다.\n\n**[오답 분석]**\n\n선택지가 없으므로 일반적인 오류를 제시합니다:\n- 극값의 조건을 무시하고 계산: 도함수가 0이 되는 조건을 놓치면 오답\n- 연립방정식을 잘못 풀어서: 식 (1)과 (2)를 잘못 연립하면 $a$, $b$ 값이 달라짐\n- 부호 변화를 확인하지 않아서: $x = -1$에서 극대, $x = 3$에서 극소라는 조건을 검증하지 않으면 부호를 반대로 잘못 설정\n\n**[핵심 포인트]**\n\n1. 극값의 위치 정보가 주어지면 도함수가 각 점에서 0이 되는 두 개의 식을 세워 연립방정식으로 계수를 구합니다.\n2. 도함수를 인수분해했을 때 이계 도함수를 이용하거나 부호 변화를 확인하여 극대/극소를 구분해야 합니다.",
