    "type": "도함수",
    "problem": "함수 $f(x) = 2x^3 - 9x^2 + 12x$의 극대값과 극소값의 합을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. 극값은 도함수가 0이 되는 점에서 나타나며, 도함수의 부호 변화를 조사하여 극대/극소를 판정합니다.\n\n- 극값의 조건: $f'(x) = 0$인 점에서 극값 발생\n- 극대값: $x$가 증가할 때 $f'(x)$의 부호가 $(+) \\to (-)$로 변할 때\n- 극소값: $x$가 증가할 때 $f'(x)$의 부호가 $(-) \\to (+)$로 변할 때\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = 2x^3 - 9x^2 + 12x$$\n\n$$f'(x) = 6x^2 - 18x + 12$$\n\n**2단계: 극값을 갖는 점 찾기 ($f'(x) = 0$)**\n\n$$6x^2 - 18x + 12 = 0$$\n\n양변을 6으로 나누면:\n$$x^2 - 3x + 2 = 0$$\n\n인수분해하면:\n$$(x-1)(x-2) = 0$$\n\n따라서 $x = 1$ 또는 $x = 2$\n\n**3단계: 극대/극소 판정 (도함수의 부호 조사)**\n\n$$f'(x) = 6(x-1)(x-2)$$\n\n- $x < 1$일 때: $f'(x) = 6(-)(-)  = (+)$ → 함수 증가\n- $1 < x < 2$일 때: $f'(x) = 6(+)(-) = (-)$ → 함수 감소\n- $x > 2$일 때: $f'(x) = 6(+)(+) = (+)$ → 함수 증가\n\n따라서 $x=1$에서 극대, $x=2$에서 극소\n\n**4단계: 극댓값과 극솟값 구하기**\n\n극댓값 ($x=1$):\n$$f(1) = 2(1)^3 - 9(1)^2 + 12(1) = 2 - 9 + 12 = 5$$\n\n극솟값 ($x=2$):\n$$f(2) = 2(2)^3 - 9(2)^2 + 12(2) = 16 - 36 + 24 = 4$$\n\n**5단계: 극대값과 극소값의 합**\n\n$$5 + 4 = 9$$\n\n**[정답 확인]**\n극댓값 5와 극솟값 4를 더하면 정확히 9가 되므로 정답입니다.\n\n**[오답 분석]**\n객관식이 없으므로 생략\n\n**[핵심 포인트]**\n1. 극값을 구할 때는 항상 도함수를 먼저 구하고 $f'(x)=0$을 풀기\n2. 도함수의 부호 변화로 극대/극소를 정확히 판정하는 것이 중요 (2차 미분이나 근처값 확인도 가능)",
