    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최댓값과 최솟값을 구하는 방법:\n1. 주어진 구간 내에서 함수의 극값(극댓값, 극솟값)을 찾기 위해 도함수를 구하고 $f'(x) = 0$의 해를 구한다.\n2. 구간의 끝점과 극값을 갖는 점에서의 함수값을 모두 계산한다.\n3. 이 중 가장 큰 값이 최댓값, 가장 작은 값이 최솟값이다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 6x^2 + 9x + 1$$\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**2단계: 극값을 갖는 점 찾기**\n$f'(x) = 0$에서:\n$$3(x-1)(x-3) = 0$$\n$$x = 1 \\text{ 또는 } x = 3$$\n\n두 점 모두 주어진 구간 $[0, 4]$에 포함된다.\n\n**3단계: 극값의 성질 확인**\n- $x < 1$일 때: $f'(x) > 0$ (증가)\n- $1 < x < 3$일 때: $f'(x) < 0$ (감소)\n- $x > 3$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = 1$에서 극댓값, $x = 3$에서 극솟값을 가진다.\n\n**4단계: 함수값 계산**\n구간의 끝점과 극값을 갖는 점에서의 함수값:\n\n$$f(0) = 0 - 0 + 0 + 1 = 1$$\n\n$$f(1) = 1 - 6 + 9 + 1 = 5$$\n\n$$f(3) = 27 - 6(9) + 9(3) + 1 = 27 - 54 + 27 + 1 = 1$$\n\n$$f(4) = 64 - 6(16) + 9(4) + 1 = 64 - 96 + 36 + 1 = 5$$\n\n**5단계: 최댓값과 최솟값 결정**\n- 최댓값: $\\max\\{1, 5, 1, 5\\} = 5$ (at $x=1$ 또는 $x=4$)\n- 최솟값: $\\min\\{1, 5, 1, 5\\} = 1$ (at $x=0$ 또는 $x=3$)\n\n**6단계: 최댓값과 최솟값의 차**\n$$\\text{최댓값} - \\text{최솟값} = 5 - 1 = 4$$\n\n**[정답 확인]**\n최댓값 5와 최솟값 1의 차이가 4이므로 정답은 ③이다.\n\n**[오답 분석]**\n- ①, ②, ⑤, ⑥: 극값이나 끝점에서의 함수값을 잘못 계산하거나, 계산 과정에서 산술 오류를 범한 경우이다. 특히 $f(1)$과 $f(4)$의 값이 같다는 것을 놓치면 오답이 될 수 있다.\n\n**[핵심 포인트]**\n- 폐구간에서의 최댓값·최솟값은 **도함수가 0인 점과 끝점** 모두에서 함수값을 확인해야 한다.\n- 극값 후보는 항상 구간 내에 있는지 확인하는 것이 중요하다.",
