    "explanation": "**[핵심 개념]**\n\n함수가 모든 실수에서 증가함수가 되기 위한 조건은 도함수가 모든 점에서 0 이상이어야 한다는 것입니다. 즉, $f'(x) \\geq 0$이 모든 실수 $x$에서 성립해야 합니다. 특히 증가함수 조건에서는 $f'(x) > 0$ (또는 $f'(x) \\geq 0$이되 $f'(x) = 0$인 점이 고립되어야 함)을 만족해야 합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = x^3 + ax$에서\n$$f'(x) = 3x^2 + a$$\n\n**Step 2: 증가함수 조건 적용**\n\n함수 $f(x)$가 모든 실수에서 증가함수이려면:\n$$f'(x) = 3x^2 + a \\geq 0 \\text{ (모든 실수 } x \\text{에 대해)}$$\n\n**Step 3: 부등식 분석**\n\n$3x^2 + a \\geq 0$이 모든 실수 $x$에서 성립하려면, $3x^2$의 최솟값을 고려해야 합니다.\n\n$3x^2$의 최솟값은 $x=0$일 때 $0$입니다.\n\n따라서 $3x^2 + a \\geq 0$이 모든 $x$에서 성립하려면:\n$$\\min(3x^2 + a) = 0 + a \\geq 0$$\n$$a \\geq 0$$\n\n**Step 4: 최솟값 결정**\n\n$a$의 범위는 $a \\geq 0$이므로, $a$의 최솟값은:\n$$a_{\\min} = 0$$\n\n**[정답 확인]**\n\n$a = 0$일 때 $f'(x) = 3x^2 \\geq 0$ (모든 $x$에서 성립)이고, $a < 0$이면 $x = 0$ 근처에서 $f'(x) < 0$이 되어 증가함수 조건을 위반하므로, 최솟값은 정확히 $0$입니다.\n\n**[오답 분석]**\n\n- ① $a = -3$: $f'(x) = 3x^2 - 3 = 3(x^2-1)$이므로 $-1 < x < 1$에서 $f'(x) < 0$ (감소) ✗\n\n- ② $a = -1$: $f'(x) = 3x^2 - 1 = 0$에서 $x = \\pm\\frac{1}{\\sqrt{3}}$이고, 이 구간에서 $f'(x) < 0$ (감소) ✗\n\n- ④ $a = 1$: $f'(x) = 3x^2 + 1 > 0$ (증가함수이지만 최솟값이 아님) ✗\n\n- ⑤ $a = 3$: $f'(x) = 3x^2 + 3 > 0$ (증가함수이지만 최솟값이 아님) ✗\n\n**[핵심 포인트]**\n\n다항함수가 증가함수가 되려면 도함수가 항상 0 이상이어야 하고, 최솟값은 도함수의 최솟값이 정확히 0이 되는 순간입니다. 이차식의 최솟값을 찾는 것이 핵심입니다.",
