    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n곱의 미분법(Product Rule): 두 함수의 곱으로 표현된 함수 $f(x) = u(x) \\cdot v(x)$의 도함수는 다음과 같습니다.\n\n$$f'(x) = u'(x) \\cdot v(x) + u(x) \\cdot v'(x)$$\n\n이 공식을 적용하려면 각 함수의 도함수를 먼저 구한 후, 곱의 미분법 공식에 대입합니다.\n\n**[풀이]**\n\n주어진 함수: $f(x) = (x^2 + 1)(x^3 - x)$\n\n$u(x) = x^2 + 1$, $v(x) = x^3 - x$로 놓으면,\n\n**Step 1: 각 함수의 도함수 구하기**\n\n$$u'(x) = 2x$$\n\n$$v'(x) = 3x^2 - 1$$\n\n**Step 2: 곱의 미분법 공식 적용**\n\n$$f'(x) = u'(x) \\cdot v(x) + u(x) \\cdot v'(x)$$\n\n$$f'(x) = 2x(x^3 - x) + (x^2 + 1)(3x^2 - 1)$$\n\n**Step 3: $x = 0$을 대입**\n\n$$f'(0) = 2(0)(0^3 - 0) + (0^2 + 1)(3(0)^2 - 1)$$\n\n$$f'(0) = 0 + (1)(-1)$$\n\n$$f'(0) = -1$$\n\n**[정답 확인]**\n\n$f'(0) = -1$이므로 정답은 **②번**입니다.\n\n**[오답 분석]**\n\n- ① $-2$: 곱의 미분법에서 두 번째 항만 고려하고 계수를 잘못 곱한 경우\n- ③ $0$: 첫 번째 항 $2x(x^3-x)$만 계산하고 두 번째 항을 누락한 경우\n- ④ $1$: 부호를 반대로 계산한 경우\n- ⑤ $2$: 절댓값을 취하거나 계산 실수\n\n**[핵심 포인트]**\n\n곱의 미분법을 사용할 때 **$(u \\cdot v)' = u' \\cdot v + u \\cdot v'$** 형태로 두 항을 모두 더해야 합니다. 특정 점에서의 함숫값을 구할 때는 마지막에 그 점의 $x$값을 대입하면 계산이 간단해집니다.",
