    "answer": 3,
    "explanation": "**[핵심 개념]**\n방정식 $f(x) = k$가 서로 다른 세 실근을 가진다는 것은 곡선 $y = f(x)$와 직선 $y = k$가 서로 다른 세 점에서 만난다는 의미입니다. 따라서 함수의 극값을 구하고, 직선이 지나가야 할 $k$의 범위를 결정해야 합니다.\n\n**[풀이]**\n\n**Step 1: 함수의 도함수 구하기**\n\n$$f(x) = x^3 - 3x$$\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n**Step 2: 극값 구하기**\n\n$f'(x) = 0$일 때: $x = -1$ 또는 $x = 1$\n\n- $x < -1$일 때: $f'(x) > 0$ (증가)\n- $-1 < x < 1$일 때: $f'(x) < 0$ (감소)\n- $x > 1$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -1$에서 극대, $x = 1$에서 극소\n\n**Step 3: 극값 계산**\n\n극대값: \n$$f(-1) = (-1)^3 - 3(-1) = -1 + 3 = 2$$\n\n극소값:\n$$f(1) = 1^3 - 3(1) = 1 - 3 = -2$$\n\n**Step 4: 서로 다른 세 실근을 가지는 조건**\n\n곡선 $y = f(x)$는 $x = -1$에서 극대값 2, $x = 1$에서 극소값 -2를 가집니다.\n\n직선 $y = k$가 곡선과 서로 다른 세 점에서 만나려면, $k$는 극소값보다 크고 극대값보다 작아야 합니다:\n\n$$-2 < k < 2$$\n\n**Step 5: 정수 $k$ 찾기**\n\n위 부등식을 만족하는 정수는:\n$$k \\in \\{-1, 0, 1\\}$$\n\n따라서 정수 $k$의 개수는 **3개**\n\n**[정답 확인]**\n극대값 2와 극소값 -2 사이의 $k$ 값에서만 곡선과 직선이 정확히 세 점에서 만나므로, 그 범위 내의 정수 $-1, 0, 1$이 답입니다.\n\n**[오답 분석]**\n- $k = 2$ 또는 $k = -2$: 극값과 같으므로 중근을 포함하여 세 개의 서로 다른 실근을 갖지 못함\n- $k > 2$ 또는 $k < -2$: 직선이 곡선과 한 점에서만 만남\n- $k = 3, 4, \\ldots$ 등: 범위를 벗어남\n\n**[핵심 포인트]**\n방정식이 서로 다른 세 실근을 가지려면 $y = k$가 극대값과 극소값 **사이**에 있어야 합니다(극값 자신은 제외). 극값에서의 $k$ 값을 정확히 계산하고 부등호 방향을 신중하게 확인하는 것이 중요합니다.",
