    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값을 가지며, 그 점에서 도함수의 부호가 음에서 양으로 변하면 극소, 양에서 음으로 변하면 극대입니다. 또는 이계 도함수 $f''(x)$를 이용하여 $f''(x) > 0$이면 극소, $f''(x) < 0$이면 극대입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = x^4 - 8x^2 + 12$\n\n$f'(x) = 4x^3 - 16x = 4x(x^2 - 4) = 4x(x-2)(x+2)$\n\n**Step 2: 극값을 갖는 점 찾기**\n\n$f'(x) = 0$일 때:\n$4x(x-2)(x+2) = 0$\n\n따라서 $x = -2, 0, 2$\n\n**Step 3: 각 점에서 극대/극소 판정**\n\n이계 도함수를 구합니다:\n$f''(x) = 12x^2 - 16$\n\n각 점에서 계산:\n- $x = -2$: $f''(-2) = 12(4) - 16 = 48 - 16 = 32 > 0$ → **극소**\n- $x = 0$: $f''(0) = 12(0) - 16 = -16 < 0$ → 극대\n- $x = 2$: $f''(2) = 12(4) - 16 = 48 - 16 = 32 > 0$ → **극소**\n\n또는 도함수의 부호 변화로 확인:\n- $x < -2$: $f'(x) < 0$ (감소)\n- $-2 < x < 0$: $f'(x) > 0$ (증가) → $x = -2$에서 극소\n- $0 < x < 2$: $f'(x) < 0$ (감소) → $x = 0$에서 극대\n- $x > 2$: $f'(x) > 0$ (증가) → $x = 2$에서 극소\n\n**Step 4: 극소가 되는 모든 x의 합**\n\n극소가 되는 $x$의 값: $x = -2, 2$\n\n합 = $-2 + 2 = 0$\n\n**[정답 확인]**\n극소점은 $x = -2$와 $x = 2$이고, 이들의 합은 $0$이므로 정답은 ③번입니다.\n\n**[오답 분석]**\n- ① $-4$: 극소점의 $x$ 값을 잘못 계산한 경우\n- ② $-2$: 극소점 중 하나만 선택한 경우\n- ④ $2$: 극소점 중 하나만 선택한 경우\n- ⑤ $4$: 극소점의 절댓값을 더한 경우\n\n**[핵심 포인트]**\n1. 도함수가 0이 되는 모든 점이 극값이 되는 것은 아니므로, 반드시 이계 도함수 또는 부호 변화로 극대/극소를 판정해야 합니다.\n2. 대칭적인 함수에서는 극값 점들의 합이 대칭축 위에 있음을 이용하면 빠르게 검증할 수 있습니다.",
