    "explanation": "**[핵심 개념]**\n\n삼차함수의 극값을 구하기 위해서는 도함수를 이용합니다. 함수 $f(x)$가 $x=c$에서 극값을 가지면 $f'(c) = 0$이고, 극소값의 정의에 따라 그 점에서의 함수값이 주어진 극소값과 같아야 합니다. 즉, 극값의 조건으로부터 $f'(x) = 0$과 $f(x) = \\text{극값}$이라는 두 개의 방정식을 세울 수 있습니다.\n\n**[풀이]**\n\n주어진 삼차함수는 $f(x) = x^3 + ax^2 + bx$입니다.\n\n**Step 1: 도함수 구하기**\n\n$$f'(x) = 3x^2 + 2ax + b$$\n\n**Step 2: 극값 조건 적용 (극소값은 $x=2$에서)**\n\n$x=2$에서 극소값을 가지므로 $f'(2) = 0$:\n\n$$f'(2) = 3(2)^2 + 2a(2) + b = 0$$\n$$12 + 4a + b = 0 \\quad \\cdots (1)$$\n\n**Step 3: 극소값 조건 적용**\n\n$x=2$에서의 함수값이 $-4$:\n\n$$f(2) = 2^3 + a(2)^2 + b(2) = -4$$\n$$8 + 4a + 2b = -4$$\n$$4a + 2b = -12$$\n$$2a + b = -6 \\quad \\cdots (2)$$\n\n**Step 4: 연립방정식 풀이**\n\n식 (1)에서: $4a + b = -12$\n\n식 (2)에서: $2a + b = -6$\n\n식 (1)에서 식 (2)를 빼면:\n\n$$2a = -6$$\n$$a = -3$$\n\n$a = -3$을 식 (2)에 대입:\n\n$$2(-3) + b = -6$$\n$$-6 + b = -6$$\n$$b = 0$$\n\n**Step 5: 답 구하기**\n\n$$a + b = -3 + 0 = -3$$\n\n**[정답 확인]**\n\n$a = -3, b = 0$일 때 $f(x) = x^3 - 3x^2$, $f'(x) = 3x^2 - 6x = 3x(x-2)$이므로 $x=2$에서 극값을 가지며, $f(2) = 8 - 12 = -4$로 조건을 만족합니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 일반적인 오답:\n- $a$값만 구해 $-3$으로 답한 경우\n- 식 (1)만 사용하여 부족한 조건으로 계산한 경우\n- 부호를 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n극값 조건은 **두 가지 정보**를 제공합니다: ① 극값을 가지는 점에서 $f'(x) = 0$ ② 그 점에서의 함수값이 주어진 극값과 같음. 이 두 식을 연립하면 미지수 $a, b$를 구할 수 있습니다.",
