    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수의 최솟값을 구하기 위해서는 먼저 도함수를 이용해 극값을 찾아야 합니다. $f'(x) = 0$이 되는 점과 정의역의 경계점에서 함수값을 비교하여 최솟값을 결정합니다. 주어진 정의역이 $x \\geq 0$인 경우, $x=0$에서의 함수값과 극값점에서의 함수값을 모두 확인해야 합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 6x^2 + 9x + a$$\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**2단계: 극값점 찾기**\n$f'(x) = 0$에서 $x = 1$ 또는 $x = 3$\n\n$f''(x) = 6x - 12$를 이용하여 극값 판정:\n- $f''(1) = 6 - 12 = -6 < 0$ → $x=1$에서 극대\n- $f''(3) = 18 - 12 = 6 > 0$ → $x=3$에서 극소\n\n**3단계: $x \\geq 0$ 범위에서 함수값 비교**\n\n$x=0$에서의 함수값:\n$$f(0) = 0 - 0 + 0 + a = a$$\n\n$x=1$에서의 함수값:\n$$f(1) = 1 - 6 + 9 + a = 4 + a$$\n\n$x=3$에서의 함수값:\n$$f(3) = 27 - 6(9) + 9(3) + a = 27 - 54 + 27 + a = a$$\n\n**4단계: 최솟값 결정**\n\n$x \\geq 0$에서 $f(0) = f(3) = a$이고, 극대값이 $f(1) = 4 + a$입니다.\n$x \\to \\infty$일 때 $f(x) \\to \\infty$이므로, 최솟값은 $x=0$ 또는 $x=3$에서 나타납니다.\n\n따라서 최솟값은:\n$$\\min f(x) = a = -3$$\n\n**[정답 확인]**\n$a = -3$일 때, $x \\geq 0$에서 최솟값은 $f(0) = f(3) = -3$이 되므로 조건을 만족합니다.\n\n**[오답 분석]**\n- ① $a = -7$: 최솟값이 $-7$이 되어 조건 위반\n- ② $a = -5$: 최솟값이 $-5$가 되어 조건 위반\n- ④ $a = -1$: 최솟값이 $-1$이 되어 조건 위반\n- ⑤ $a = 1$: 최솟값이 $1$이 되어 조건 위반\n\n**[핵심 포인트]**\n주어진 정의역에서 최솟값을 구할 때는 극값점뿐만 아니라 정의역의 경계점(여기서는 $x=0$)에서의 함수값도 반드시 확인해야 합니다. 이 문제에서는 $f(0) = f(3) = a$로 같은 값을 가지므로, 주어진 최솟값 조건으로부터 직접 $a$를 구할 수 있습니다.",
