    "problem": "함수 $f(x) = x^2 + 3x$에서 $x = 1$에서의 접선의 기울기를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 5,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 기울기는 그 점에서의 미분값(도함수의 함수값)과 같습니다. 함수 $f(x)$가 주어졌을 때, $x=a$에서의 접선의 기울기는 $f'(a)$입니다.\n\n**[풀이]**\n주어진 함수는 $f(x) = x^2 + 3x$입니다.\n\n**Step 1: 함수를 미분하여 도함수 구하기**\n\n$$f'(x) = \\frac{d}{dx}(x^2 + 3x) = 2x + 3$$\n\n**Step 2: $x=1$에서의 도함수 값 계산**\n\n$x=1$에서의 접선의 기울기는 $f'(1)$이므로:\n\n$$f'(1) = 2(1) + 3 = 2 + 3 = 5$$\n\n**정답 확인**\n$x=1$에서 함수의 순간변화율(기울기)은 5이므로, 그 점에서의 접선의 기울기도 5입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은:\n- **1**: 함수값 $f(1) = 1 + 3 = 4$와 혼동하는 경우\n- **2**: 도함수를 $f'(x) = 2x$로만 계산하고 $f'(1) = 2$라고 하는 경우 (상수항 미분 누락)\n- **4**: $f(1) = 4$를 기울기로 착각하는 경우\n\n**[핵심 포인트]**\n접선의 기울기 = 도함수값입니다. 미분할 때 모든 항을 빠짐없이 미분해야 하며, 함수값과 도함수값을 구별해야 합니다.",
