    "explanation": "**[핵심 개념]**\n곡선 위의 특정 점에서의 접선의 기울기는 그 점에서의 미분값(도함수의 값)과 같습니다. 함수 $f(x)$에서 $x=a$에서의 접선의 기울기는 $f'(a)$입니다.\n\n**[풀이]**\n주어진 함수: $f(x) = -x^2 + 4x$\n\n**1단계: 도함수 구하기**\n$$f'(x) = \\frac{d}{dx}(-x^2 + 4x) = -2x + 4$$\n\n**2단계: $x=3$에서의 도함수값 계산**\n$$f'(3) = -2(3) + 4 = -6 + 4 = -2$$\n\n따라서 $x=3$에서의 접선의 기울기는 $-2$입니다.\n\n**[정답 확인]**\n$x=3$에서 도함수값이 $-2$이므로, 이 점에서의 접선의 기울기는 $-2$이며, 정답은 ②번입니다.\n\n**[오답 분석]**\n- ① -4: $f'(3) = -2(3) + 4 = -2$를 계산할 때 $-2 \\times 3 = -6$만 고려하고 $+4$를 빠뜨린 경우\n- ③ 0: $-6 + 4 = -2$를 계산하지 않고 부호만 반대로 생각한 오류\n- ④ 2: 음수 기울기를 양수로 잘못 읽은 경우\n- ⑤ 4: 계수 4만 답으로 선택한 경우\n\n**[핵심 포인트]**\n접선의 기울기 = 그 점에서의 도함수값. 다항함수의 미분은 각 항을 개별적으로 미분한 후 모두 더하는 것을 잊지 말 것.",
