    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선을 구하기 위해서는 다음 두 가지가 필요합니다.\n1. 접점에서의 미분값(기울기): $f'(x_0)$\n2. 접선의 방정식: $y - y_0 = f'(x_0)(x - x_0)$\n3. $y$절편: 접선의 방정식에서 $x=0$일 때의 $y$값\n\n**[풀이]**\n\n**1단계: 주어진 점이 함수 위에 있는지 확인**\n$f(x) = x^3$에서 $x = -1$일 때\n$$f(-1) = (-1)^3 = -1$$\n따라서 점 $(-1, -1)$은 함수 위의 점입니다. ✓\n\n**2단계: 접점에서의 기울기 구하기**\n$$f'(x) = 3x^2$$\n$x = -1$에서의 미분값:\n$$f'(-1) = 3 \\times (-1)^2 = 3 \\times 1 = 3$$\n\n**3단계: 접선의 방정식 구하기**\n점 $(-1, -1)$을 지나고 기울기가 $3$인 직선의 방정식:\n$$y - (-1) = 3(x - (-1))$$\n$$y + 1 = 3(x + 1)$$\n$$y + 1 = 3x + 3$$\n$$y = 3x + 2$$\n\n**4단계: $y$절편 구하기**\n$x = 0$을 대입:\n$$y = 3(0) + 2 = 2$$\n\n따라서 $y$절편은 **2**입니다.\n\n**[정답 확인]**\n접선의 방정식 $y = 3x + 2$에서 $x=0$일 때 $y=2$이므로, $y$절편은 2가 맞습니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으나, 다음과 같은 오류가 가능합니다:\n- **-2**: 기울기는 구했으나 $y$절편 계산 실수\n- **3**: 기울기값을 $y$절편으로 착각\n- **-1**: 접점의 $y$좌표를 $y$절편으로 착각\n\n**[핵심 포인트]**\n곡선의 접선은 그 점에서의 도함수값을 기울기로 하는 직선이며, $y$절편은 접선의 방정식에 $x=0$을 대입하여 구합니다. 접점의 좌표와 기울기를 정확히 구하면 자동으로 답이 나옵니다.",
