    "answer": 2,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선을 구하기 위해서는 다음 두 가지가 필요합니다.\n- 접점의 좌표 (문제에서 주어짐)\n- 접점에서의 미분값(기울기): 함수를 미분하여 해당 점의 $x$좌표를 대입하면 그 점에서의 접선의 기울기를 구할 수 있습니다.\n\n접선의 방정식은 점-기울기 형태 $y - y_1 = m(x - x_1)$을 이용하여 구합니다.\n\n**[풀이]**\n\n**Step 1: 주어진 점이 곡선 위의 점인지 확인**\n\n$y = 3x^2 - 2$에서 $x = 1$일 때:\n$$y = 3(1)^2 - 2 = 3 - 2 = 1$$\n\n따라서 점 $(1, 1)$은 곡선 위의 점이 맞습니다.\n\n**Step 2: 접선의 기울기 구하기**\n\n곡선 $y = 3x^2 - 2$를 $x$에 대해 미분하면:\n$$\\frac{dy}{dx} = 6x$$\n\n$x = 1$에서의 기울기:\n$$m = 6(1) = 6$$\n\n따라서 $a = 6$\n\n**Step 3: 접선의 방정식 구하기**\n\n점 $(1, 1)$을 지나고 기울기가 $6$인 직선의 방정식:\n$$y - 1 = 6(x - 1)$$\n$$y - 1 = 6x - 6$$\n$$y = 6x - 5$$\n\n따라서 $a = 6$, $b = -5$\n\n**Step 4: $a - b$ 계산**\n\n$$a - b = 6 - (-5) = 6 + 5 = 11$$\n\n**[정답 확인]**\n접선의 방정식 $y = 6x - 5$가 점 $(1, 1)$을 지나는지 확인: $1 = 6(1) - 5 = 1$ ✓ 이므로 $a - b = 11$이 정답입니다.\n\n**[오답 분석]**\n- ① 9: $a + b = 6 + (-5) = 1$의 9배 값으로, 계산 과정에서 부호를 잘못 처리한 경우\n- ② 10: $a - b$를 계산할 때 $6 - 4 = 10$으로, $b$값을 잘못 구한 경우\n- ④ 12: $a + b$를 구해야 하는데 $a - b$로 착각한 후 계산 오류\n- ⑤ 13: 미분값을 $6x$가 아닌 다른 값으로 잘못 구한 경우\n\n**[핵심 포인트]**\n- 접선의 기울기 = 그 점에서의 도함수값\n- 접선의 방정식: 점 $(x_1, y_1)$을 지나고 기울기가 $m$일 때, $y - y_1 = m(x - x_1)$ 형태로 정리한 후 $y = mx + b$ 형태로 변환하기",
