    "explanation": "**[핵심 개념]**\n곡선 위의 점에서의 접선의 방정식을 구하는 문제입니다. 주어진 점이 곡선 위에 있을 때, 그 점에서의 접선의 기울기는 그 점에서의 미분값(도함수)과 같습니다. 접선의 방정식은 $y - y_1 = f'(x_1)(x - x_1)$ 형태로 구합니다.\n\n**[풀이]**\n\n**Step 1: 주어진 점이 함수 위에 있는지 확인**\n\n$f(x) = 2x^2 - x + 1$에서 $x = 2$일 때:\n$$f(2) = 2(2)^2 - 2 + 1 = 8 - 2 + 1 = 7$$\n\n따라서 점 $(2, 7)$은 함수 위의 점입니다. ✓\n\n**Step 2: 도함수 구하기**\n\n$$f'(x) = \\frac{d}{dx}(2x^2 - x + 1) = 4x - 1$$\n\n**Step 3: $x = 2$에서의 접선의 기울기 구하기**\n\n$$f'(2) = 4(2) - 1 = 8 - 1 = 7$$\n\n따라서 접선의 기울기 $a = 7$입니다.\n\n**Step 4: 접선의 방정식 구하기**\n\n점 $(2, 7)$을 지나고 기울기가 $7$인 직선의 방정식:\n$$y - 7 = 7(x - 2)$$\n$$y - 7 = 7x - 14$$\n$$y = 7x - 7$$\n\n따라서 $a = 7$, $b = -7$입니다.\n\n**Step 5: $a + b$ 계산**\n\n$$a + b = 7 + (-7) = 0$$\n\n**[정답 확인]**\n접선의 기울기는 도함수값 $f'(2) = 7$이고, 점 $(2, 7)$을 지나므로 $y = 7x - 7$이 맞으며, $a + b = 7 - 7 = 0$입니다.\n\n**[오답 분석]**\n- ① -2: $a + b$를 잘못 계산하거나 기울기를 음수로 착각한 경우\n- ③ 2: 기울기를 잘못 구하거나 부호 실수로 $y = 2x + 2$ 같은 형태를 얻은 경우\n- ④ 4: 도함수 계산 실수로 기울기를 $4$로 잘못 구한 경우\n- ⑤ 6: 계산 과정에서 여러 실수가 누적된 경우\n\n**[핵심 포인트]**\n1. 접선의 기울기 = 그 점에서의 도함수값\n2. 접선의 방정식을 구한 후 $y = ax + b$ 형태로 정리하여 $a$, $b$의 값을 정확히 파악해야 합니다.",
