    "explanation": "**[핵심 개념]**\n곡선 위의 점에서의 접선을 구하기 위해서는 다음 단계가 필요합니다.\n1) 곡선의 도함수를 구하여 주어진 점에서의 기울기를 구합니다.\n2) 점-기울기 형태의 직선 방정식을 세웁니다: $y - y_1 = m(x - x_1)$\n3) 접선이 $x$축과 만나는 점은 $y = 0$일 때이므로, 이를 이용하여 $x$좌표를 구합니다.\n\n**[풀이]**\n\n**1단계: 곡선의 도함수 구하기**\n\n곡선 $y = x^2$의 도함수는:\n$$\\frac{dy}{dx} = 2x$$\n\n**2단계: 점 $(2, 4)$에서의 기울기 구하기**\n\n$x = 2$일 때의 기울기는:\n$$m = 2 \\times 2 = 4$$\n\n**3단계: 점 $(2, 4)$를 지나는 접선의 방정식 구하기**\n\n점-기울기 형태를 사용하면:\n$$y - 4 = 4(x - 2)$$\n$$y - 4 = 4x - 8$$\n$$y = 4x - 4$$\n\n**4단계: 접선이 $x$축과 만나는 점의 $x$좌표 구하기**\n\n$x$축 위의 점은 $y = 0$이므로:\n$$0 = 4x - 4$$\n$$4x = 4$$\n$$x = 1$$\n\n**[정답 확인]**\n접선의 방정식 $y = 4x - 4$에 $y = 0$을 대입하면 $x = 1$을 얻으므로, 정답은 **1**입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답의 예시:\n- $x = 2$: 접선이 지나는 점의 $x$좌표를 실수로 선택한 경우\n- $x = 0$: 계산 과정에서 부호 실수가 있는 경우\n- $x = 4$: 기울기를 잘못 계산한 경우\n\n**[핵심 포인트]**\n곡선 위의 점에서의 접선을 구할 때는 **도함수로 기울기를 구하는 것**이 첫 단계입니다. 접선이 $x$축과 만나는 점을 구할 때는 **$y = 0$을 대입**하여 $x$좌표를 구합니다.",
