    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n곡선 위의 점에서 접선의 기울기는 그 점에서의 미분값(도함수)입니다. 접선의 기울기가 0이라는 것은 도함수가 0이 되는 점을 찾는 것이므로, $y' = 0$을 만족하는 $x$값을 구하는 문제입니다. 이러한 점들을 **극값(극대값 또는 극소값)**을 가지는 점이라고 하며, 함수의 증감을 판단하는 기준점이 됩니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n주어진 곡선 $y = x^3 - 3x^2 + 2$를 미분합니다.\n\n$$y' = 3x^2 - 6x$$\n\n**Step 2: 접선의 기울기가 0인 조건**\n\n접선의 기울기가 0이려면:\n\n$$y' = 0$$\n$$3x^2 - 6x = 0$$\n$$3x(x - 2) = 0$$\n\n**Step 3: 방정식 풀이**\n\n$$x = 0 \\text{ 또는 } x = 2$$\n\n**Step 4: 각 점이 곡선 위에 존재하는지 확인**\n\n- $x = 0$일 때: $y = 0^3 - 3(0)^2 + 2 = 2$ → 점 $(0, 2)$는 곡선 위의 점 ✓\n- $x = 2$일 때: $y = 2^3 - 3(2)^2 + 2 = 8 - 12 + 2 = -2$ → 점 $(2, -2)$는 곡선 위의 점 ✓\n\n**Step 5: 결론**\n\n접선의 기울기가 0인 점은 $(0, 2)$와 $(2, -2)$로 총 **2개**입니다.\n\n**[정답 확인]**\n\n도함수 $y' = 3x^2 - 6x = 0$은 서로 다른 두 개의 실근 $x = 0, 2$를 가지며, 이 두 점이 모두 원래 곡선 위에 존재하므로 정답은 ③번입니다.\n\n**[오답 분석]**\n\n- **① 0개**: 도함수가 0이 되는 점이 존재하지 않는다고 잘못 판단한 경우\n- **② 1개**: 한 근만 찾거나, 한 근이 곡선 위에 없다고 잘못 판단한 경우\n- **④ 3개, ⑤ 4개**: 도함수 계산 오류로 3개 이상의 근이 있다고 판단한 경우 또는 중근을 중복으로 센 경우\n\n**[핵심 포인트]**\n\n접선의 기울기가 0인 점 = 도함수가 0이 되는 점이며, 이를 찾기 위해 **$y' = 0$을 풀고 구한 $x$값이 원래 함수의 정의역에 속하는지 확인**해야 합니다.",
