    "explanation": "**[핵심 개념]**\n\n곡선 위의 한 점에서의 접선의 기울기는 그 점에서의 미분값이고, 접선의 방정식은 점-기울기 형태로 나타낼 수 있습니다. 접선이 특정 점을 지나간다는 조건을 이용하면 미지수를 구할 수 있습니다.\n\n- 곡선 $y = f(x)$ 위의 점 $(x_0, f(x_0))$에서의 접선: $y - f(x_0) = f'(x_0)(x - x_0)$\n- 접선이 원점을 지나면: $0 - f(x_0) = f'(x_0)(0 - x_0)$\n\n**[풀이]**\n\n**Step 1: 주어진 곡선의 미분**\n\n$$y = x^3 + ax^2$$\n\n$$y' = 3x^2 + 2ax$$\n\n**Step 2: $x=1$에서의 접선의 기울기와 점의 좌표**\n\n$x=1$에서의 기울기:\n$$m = y'(1) = 3(1)^2 + 2a(1) = 3 + 2a$$\n\n$x=1$에서의 점의 좌표:\n$$y(1) = 1^3 + a(1)^2 = 1 + a$$\n\n따라서 접점은 $(1, 1+a)$입니다.\n\n**Step 3: 접선의 방정식**\n\n점 $(1, 1+a)$에서의 접선의 방정식:\n$$y - (1+a) = (3+2a)(x-1)$$\n\n$$y = (3+2a)x - (3+2a) + 1 + a$$\n\n$$y = (3+2a)x - 2 - a$$\n\n**Step 4: 접선이 원점을 지나는 조건**\n\n접선이 원점 $(0, 0)$을 지나므로:\n$$0 = (3+2a)(0) - 2 - a$$\n\n$$0 = -2 - a$$\n\n$$a = -2$$\n\n**[정답 확인]**\n\n$a = -2$를 대입하면 접선의 방정식은 $y = -x$이고, 이는 원점을 지나갑니다. ✓\n\n**[오답 분석]**\n\n객관식이 아닌 단답형이므로 해당 없습니다.\n\n**[핵심 포인트]**\n\n1. 접선이 특정 점을 지난다는 조건은 그 점의 좌표를 접선의 방정식에 대입하는 것으로 처리합니다.\n2. 접선 방정식을 정리할 때 계수를 정확히 계산해야 하므로 전개 과정을 꼼꼼히 확인하세요.",
