    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 기울기는 그 점에서의 미분값(도함수)과 같습니다. 이차함수 $y = x^2 + ax + 1$을 미분하여 $x = 1$에서의 도함수값이 4라는 조건을 이용하면 상수 $a$를 구할 수 있습니다.\n\n**[풀이]**\n\n**Step 1: 주어진 곡선의 도함수 구하기**\n\n곡선 $y = x^2 + ax + 1$을 $x$에 대해 미분합니다.\n\n$$\\frac{dy}{dx} = 2x + a$$\n\n**Step 2: $x = 1$에서의 접선의 기울기 조건 적용**\n\n$x = 1$에서의 접선의 기울기가 4라는 조건에서:\n\n$$\\frac{dy}{dx}\\bigg|_{x=1} = 2(1) + a = 4$$\n\n**Step 3: 상수 $a$ 구하기**\n\n$$2 + a = 4$$\n$$a = 2$$\n\n**[정답 확인]**\n$a = 2$일 때, $x = 1$에서의 도함수값은 $2(1) + 2 = 4$로 주어진 조건을 만족합니다.\n\n**[오답 분석]**\n- ① $a = 0$: 도함수가 $2x$이므로 $x=1$에서 기울기는 2 (조건 불만족)\n- ② $a = 1$: 도함수가 $2x + 1$이므로 $x=1$에서 기울기는 3 (조건 불만족)\n- ④ $a = 3$: 도함수가 $2x + 3$이므로 $x=1$에서 기울기는 5 (조건 불만족)\n- ⑤ $a = 4$: 도함수가 $2x + 4$이므로 $x=1$에서 기울기는 6 (조건 불만족)\n\n**[핵심 포인트]**\n곡선 위의 점에서의 접선의 기울기 = 그 점에서의 도함수값. 도함수를 구한 후 주어진 $x$값을 대입하여 조건식을 세우면 됩니다.",
