    "answer": 5,
    "explanation": "**[핵심 개념]**\n곡선 위의 점에서의 접선을 구하기 위해서는 다음 과정이 필요합니다:\n1. 곡선의 도함수는 각 점에서의 접선의 기울기를 나타냅니다.\n2. 기울기가 $m$인 점을 찾기 위해 $f'(x) = m$을 풀어야 합니다.\n3. 접점 $(x_0, y_0)$에서의 접선의 방정식은 $y - y_0 = f'(x_0)(x - x_0)$입니다.\n4. $y$절편은 접선의 방정식에서 $x=0$일 때의 $y$ 값입니다.\n\n**[풀이]**\n\n**단계 1: 도함수 구하기**\n$$y = x^3 - 3x^2$$\n$$y' = 3x^2 - 6x$$\n\n**단계 2: 기울기가 9인 점 찾기**\n기울기가 9이므로 $y' = 9$를 풉니다:\n$$3x^2 - 6x = 9$$\n$$3x^2 - 6x - 9 = 0$$\n$$x^2 - 2x - 3 = 0$$\n$$(x-3)(x+1) = 0$$\n$$x = 3 \\text{ 또는 } x = -1$$\n\n**단계 3: 각 접점에서의 $y$ 좌표 구하기**\n\n$x = 3$일 때:\n$$y = 3^3 - 3(3)^2 = 27 - 27 = 0$$\n접점: $(3, 0)$\n\n$x = -1$일 때:\n$$y = (-1)^3 - 3(-1)^2 = -1 - 3 = -4$$\n접점: $(-1, -4)$\n\n**단계 4: 각 접선의 방정식 구하기**\n\n접점 $(3, 0)$에서의 접선:\n$$y - 0 = 9(x - 3)$$\n$$y = 9x - 27$$\n$y$절편: $-27$ (음수)\n\n접점 $(-1, -4)$에서의 접선:\n$$y - (-4) = 9(x - (-1))$$\n$$y + 4 = 9(x + 1)$$\n$$y + 4 = 9x + 9$$\n$$y = 9x + 5$$\n$y$절편: $5$ (양수) ✓\n\n**[정답 확인]**\n접점 $(-1, -4)$에서 기울기 9인 접선의 $y$절편이 5이며, 이는 양수이므로 정답입니다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 사항 없음. 단, 다른 접선의 $y$절편인 $-27$을 고르는 실수를 할 수 있습니다. 문제에서 \"양수인 것\"을 명시했으므로 이 값은 제외됩니다.\n\n**[핵심 포인트]**\n- 기울기가 주어진 접선 문제는 도함수를 이용해 접점을 먼저 찾아야 합니다.\n- 같은 기울기를 가진 여러 접선이 존재할 수 있으므로, 추가 조건(양수, 음수 등)을 꼼꼼히 확인해야 합니다.",
