    "explanation": "**[핵심 개념]**\n\n곡선 밖의 한 점에서 곡선에 그은 접선을 구하는 문제입니다. 핵심은:\n- 곡선 위의 점 $(a, f(a))$에서의 접선의 방정식: $y - f(a) = f'(a)(x - a)$\n- 이 접선이 주어진 점 $(0, 4)$를 지나야 한다는 조건을 이용합니다.\n\n**[풀이]**\n\n곡선 $y = x^3 - 3x + 2$ 위의 임의의 점을 $(t, t^3 - 3t + 2)$라 하겠습니다.\n\n**Step 1: 접선의 기울기 구하기**\n\n$f(x) = x^3 - 3x + 2$이므로\n$$f'(x) = 3x^2 - 3$$\n\n점 $(t, t^3 - 3t + 2)$에서의 접선의 기울기는 $f'(t) = 3t^2 - 3$입니다.\n\n**Step 2: 접선의 방정식 세우기**\n\n점 $(t, t^3 - 3t + 2)$에서의 접선의 방정식:\n$$y - (t^3 - 3t + 2) = (3t^2 - 3)(x - t)$$\n\n**Step 3: 점 $(0, 4)$가 접선 위에 있다는 조건 적용**\n\n접선이 점 $(0, 4)$를 지나므로 $x = 0, y = 4$를 대입:\n$$4 - (t^3 - 3t + 2) = (3t^2 - 3)(0 - t)$$\n\n$$4 - t^3 + 3t - 2 = -(3t^2 - 3)t$$\n\n$$2 - t^3 + 3t = -3t^3 + 3t$$\n\n$$2 - t^3 = -3t^3$$\n\n$$2 = -3t^3 + t^3$$\n\n$$2 = -2t^3$$\n\n$$t^3 = -1$$\n\n$$t = -1$$\n\n**Step 4: 접선의 기울기 계산**\n\n$t = -1$일 때 접선의 기울기는:\n$$f'(-1) = 3(-1)^2 - 3 = 3 - 3 = 0$$\n\n**정답 확인**\n\n접점이 $(-1, (-1)^3 - 3(-1) + 2) = (-1, 4)$이고, 이 점에서의 접선의 기울기는 0이므로 접선은 수평선 $y = 4$입니다. 이는 점 $(0, 4)$를 지나므로 조건을 만족합니다.\n\n**[오답 분석]**\n\n이 문제는 객관식이 아닌 단답형이므로 다른 값들이 오답입니다. \n- 계산 실수로 $t^3 = 1$ (즉, $t = 1$)을 구하면 기울기는 0이 아닌 다른 값이 됩니다.\n- 점 $(0, 4)$가 곡선 위의 점이라고 착각하면 잘못된 답을 얻습니다.\n\n**[핵심 포인트]**\n\n곡선 밖의 점에서 그은 접선 문제는 접점의 좌표를 미지수로 설정하고, 주어진 점을 지나는 조건으로 접점을 먼저 결정한 후 기울기를 구합니다. 이 문제에서 접선의 기울기가 0이 되는 것은 기울기가 수평인 접선이 주어진 점을 지난다는 특수한 기하학적 상황입니다.",
