    "problem": "곡선 $y = x^3$과 직선 $y = 3x + a$가 접할 때, 양수 $a$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n곡선과 직선이 접한다는 것은 교점에서 만나면서 동시에 접선의 기울기가 같다는 의미입니다. \n- 곡선 $y = f(x)$와 직선 $y = mx + b$가 점 $(x_0, y_0)$에서 접할 조건:\n  1. 교점 조건: $f(x_0) = mx_0 + b$\n  2. 기울기 조건: $f'(x_0) = m$\n\n이 두 조건을 동시에 만족하는 $x_0$과 $a$를 구해야 합니다.\n\n**[풀이]**\n\n곡선 $y = x^3$과 직선 $y = 3x + a$가 점 $(x_0, y_0)$에서 접한다고 하겠습니다.\n\n**1단계: 기울기 조건**\n곡선 $y = x^3$의 도함수는:\n$$\\frac{dy}{dx} = 3x^2$$\n\n접점에서 곡선의 기울기가 직선의 기울기 3과 같아야 하므로:\n$$3x_0^2 = 3$$\n$$x_0^2 = 1$$\n$$x_0 = 1 \\text{ 또는 } x_0 = -1$$\n\n**2단계: 교점 조건**\n접점 $(x_0, x_0^3)$이 직선 $y = 3x + a$ 위에 있어야 하므로:\n$$x_0^3 = 3x_0 + a$$\n$$a = x_0^3 - 3x_0$$\n\n**3단계: $a$ 값 구하기**\n\n$x_0 = 1$일 때:\n$$a = 1^3 - 3(1) = 1 - 3 = -2$$\n\n$x_0 = -1$일 때:\n$$a = (-1)^3 - 3(-1) = -1 + 3 = 2$$\n\n문제에서 양수 $a$를 구하라고 했으므로:\n$$a = 2$$\n\n**[정답 확인]**\n$a = 2$일 때, 접점은 $(-1, -1)$이고, 곡선의 기울기는 $3(-1)^2 = 3$, 직선의 기울기도 3으로 같으며, 점 $(-1, -1)$이 직선 $y = 3x + 2$ 위에 있음을 확인할 수 있습니다: $-1 = 3(-1) + 2 = -1$ ✓\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은:\n- $a = -2$: 문제에서 양수를 구하라고 했으므로 제외\n- $a = 4$: 기울기 조건을 간과하고 특정 $x$ 값만 대입한 경우\n- $a = 1$: 계산 실수로 $x_0^3 - 3x_0$를 잘못 계산한 경우\n\n**[핵심 포인트]**\n곡선과 직선의 접촉 조건은 **기울기가 같음**($f'(x_0) = m$)과 **교점이 존재**($f(x_0) = mx_0 + b$)을 동시에 만족해야 하며, 두 조건으로부터 얻은 방정식을 모두 활용해야 합니다.",
