    "problem": "두 곡선 $f(x) = x^2 + a$, $g(x) = -x^2 + bx$가 $x = 1$에서 공통접선을 가질 때, $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n\n두 곡선이 한 점에서 공통접선을 가진다는 것은:\n1. 그 점에서 두 곡선이 만난다 (함수값이 같음)\n2. 그 점에서 두 곡선의 접선의 기울기가 같다 (도함수값이 같음)\n\n공통접선의 조건: $f(x_0) = g(x_0)$이고 $f'(x_0) = g'(x_0)$\n\n**[풀이]**\n\n**Step 1: 주어진 함수의 도함수 구하기**\n\n$$f(x) = x^2 + a \\Rightarrow f'(x) = 2x$$\n\n$$g(x) = -x^2 + bx \\Rightarrow g'(x) = -2x + b$$\n\n**Step 2: $x=1$에서 기울기가 같다는 조건 적용**\n\n$x=1$에서 공통접선을 가지므로 $f'(1) = g'(1)$\n\n$$f'(1) = 2(1) = 2$$\n\n$$g'(1) = -2(1) + b = -2 + b$$\n\n따라서:\n$$2 = -2 + b$$\n$$b = 4$$\n\n**Step 3: $x=1$에서 함수값이 같다는 조건 적용**\n\n$x=1$에서 두 곡선이 만나므로 $f(1) = g(1)$\n\n$$f(1) = 1^2 + a = 1 + a$$\n\n$$g(1) = -(1)^2 + 4(1) = -1 + 4 = 3$$\n\n따라서:\n$$1 + a = 3$$\n$$a = 2$$\n\n**Step 4: $a + b$ 계산**\n\n$$a + b = 2 + 4 = 6$$\n\n**[정답 확인]**\n\n$a=2, b=4$일 때 $x=1$에서 $f(1)=3, g(1)=3$이고 $f'(1)=2, g'(1)=2$로 모든 조건을 만족하므로 정답은 6이 맞습니다.\n\n**[오답 분석]**\n\n객관식 선택지가 없으므로 일반적인 오류:\n- $b=4$만 구하고 $a$를 구하지 않은 경우: 4\n- 기울기 조건만 사용하고 함수값 조건을 무시한 경우: 잘못된 답\n- 함수값 조건만 사용하고 기울기 조건을 무시한 경우: 잘못된 답\n\n**[핵심 포인트]**\n\n공통접선 문제에서는 **반드시 두 조건을 모두 사용**해야 합니다: 함수값이 같고($f(x_0)=g(x_0)$) 도함수값도 같아야($f'(x_0)=g'(x_0)$) 합니다. 한 조건만 사용하면 미지수를 모두 구할 수 없습니다.",
