    "answer": -4,
    "explanation": "**[핵심 개념]**\n\n곡선 위의 한 점에서의 접선의 방정식을 구하기 위해서는 그 점에서의 미분값(기울기)을 이용합니다. 곡선 $y = f(x)$ 위의 점 $(a, f(a))$에서의 접선의 방정식은 $y - f(a) = f'(a)(x - a)$입니다. 접선이 곡선과 만나는 다른 점을 찾기 위해서는 접선의 방정식과 곡선의 방정식을 연립하여 풉니다.\n\n**[풀이]**\n\n**Step 1: 점 (2, 3)이 곡선 위의 점임을 확인**\n\n$x = 2$일 때, $y = 2^3 - 3(2) + 1 = 8 - 6 + 1 = 3$ ✓\n\n**Step 2: 접선의 기울기 구하기**\n\n곡선 $y = x^3 - 3x + 1$을 미분하면:\n$$y' = 3x^2 - 3$$\n\n$x = 2$에서의 기울기:\n$$y'(2) = 3(2)^2 - 3 = 12 - 3 = 9$$\n\n**Step 3: 접선의 방정식 구하기**\n\n점 $(2, 3)$을 지나고 기울기가 9인 직선의 방정식:\n$$y - 3 = 9(x - 2)$$\n$$y = 9x - 18 + 3$$\n$$y = 9x - 15$$\n\n**Step 4: 접선과 곡선의 교점 찾기**\n\n접선의 방정식과 곡선의 방정식을 연립합니다:\n$$x^3 - 3x + 1 = 9x - 15$$\n$$x^3 - 3x + 1 - 9x + 15 = 0$$\n$$x^3 - 12x + 16 = 0$$\n\n**Step 5: 3차 방정식 풀이**\n\n$x = 2$가 이 방정식의 해임을 알고 있으므로 (접점이므로), $(x - 2)$로 인수분해합니다:\n$$x^3 - 12x + 16 = (x - 2)(x^2 + 2x - 8)$$\n\n확인: $(x - 2)(x^2 + 2x - 8) = x^3 + 2x^2 - 8x - 2x^2 - 4x + 16 = x^3 - 12x + 16$ ✓\n\n**Step 6: 2차 방정식 풀이**\n\n$$x^2 + 2x - 8 = 0$$\n$$(x + 4)(x - 2) = 0$$\n$$x = -4 \\text{ 또는 } x = 2$$\n\n$x = 2$는 접점이므로, 접선이 곡선과 다시 만나는 점의 $x$좌표는 **$x = -4$**\n\n**[정답 확인]**\n\n$x = -4$를 곡선의 방정식에 대입하면 $y = (-4)^3 - 3(-4) + 1 = -64 + 12 + 1 = -51$이고, 접선 $y = 9x - 15$에 $x = -4$를 대입하면 $y = 9(-4) - 15 = -36 - 15 = -51$로 일치하므로 접선과 곡선이 $(-4, -51)$에서 만납니다.\n\n**[핵심 포인트]**\n\n곡선과 접선이 만나는 두 점 중 한 점이 접점일 때, 접점의 $x$좌표는 연립방정식에서 중근이 되며, 이를 이용해 $(x - a)^2$으로 인수분해할 수 있습니다.",
