    "explanation": "**[핵심 개념]**\n곡선 위의 점 $(a, f(a))$에서의 접선의 방정식은 $y - f(a) = f'(a)(x - a)$입니다. 곡선 밖의 점 $(0, -1)$을 지나는 접선을 구하려면, 접점을 $(a, f(a))$라 할 때 접선이 점 $(0, -1)$을 지나는 조건을 세워야 합니다. 이를 통해 접점의 $x$좌표 $a$를 구하는 방정식을 얻습니다.\n\n**[풀이]**\n먼저 $f(x) = x^3 - 3x^2 + 3x$의 도함수를 구합니다.\n$$f'(x) = 3x^2 - 6x + 3 = 3(x^2 - 2x + 1) = 3(x-1)^2$$\n\n접점을 $(a, f(a))$라 하면, 이 점에서의 접선의 방정식은:\n$$y - f(a) = f'(a)(x - a)$$\n$$y - (a^3 - 3a^2 + 3a) = 3(a-1)^2(x - a)$$\n\n이 접선이 점 $(0, -1)$을 지나므로:\n$$-1 - (a^3 - 3a^2 + 3a) = 3(a-1)^2(0 - a)$$\n$$-1 - a^3 + 3a^2 - 3a = -3a(a-1)^2$$\n\n우변을 전개합니다:\n$$-3a(a-1)^2 = -3a(a^2 - 2a + 1) = -3a^3 + 6a^2 - 3a$$\n\n따라서:\n$$-1 - a^3 + 3a^2 - 3a = -3a^3 + 6a^2 - 3a$$\n$$-1 - a^3 + 3a^2 - 3a + 3a^3 - 6a^2 + 3a = 0$$\n$$2a^3 - 3a^2 - 1 = 0$$\n\n이 3차 방정식의 해의 개수를 구합니다. $g(a) = 2a^3 - 3a^2 - 1$이라 하면:\n$$g'(a) = 6a^2 - 6a = 6a(a - 1)$$\n\n극값은 $a = 0$과 $a = 1$에서 발생합니다.\n- $g(0) = -1 < 0$\n- $g(1) = 2 - 3 - 1 = -2 < 0$\n- $a \\to \\infty$일 때 $g(a) \\to \\infty$\n- $a \\to -\\infty$일 때 $g(a) \\to -\\infty$\n\n$a = 0$에서 극대, $a = 1$에서 극소이고, 두 극값이 모두 음수이므로, $g(a) = 0$은 $a > 1$인 영역에서 정확히 한 개의 실근을 가집니다.\n\n확인: $g(2) = 16 - 12 - 1 = 3 > 0$이므로 $1 < a < 2$에서 근이 존재합니다.\n\n따라서 접선의 개수는 **1개**입니다.\n\n**[정답 확인]**\n3차 방정식 $2a^3 - 3a^2 - 1 = 0$이 정확히 하나의 실근을 가지므로, 곡선 밖의 점 $(0, -1)$에서 그을 수 있는 접선은 1개입니다.\n\n**[오답 분석]**\n- ② 2개: 3차 방정식이 3개의 실근을 가지는 경우를 잘못 선택\n- ③ 3개: 극값이 양수와 음수를 오가는 경우를 착각\n- ④ 0개: 판별식을 계산 실수한 경우\n- ⑤ 무한: 점이 곡선 위에 있는 경우인데, $(0, -1)$은 곡선 위의 점이 아님\n\n**[핵심 포인트]**\n곡선 밖의 점에서 그은 접선의 개수는 접점의 $x$좌표에 대한 방정식의 실근의 개수와 같습니다. 3차 방정식의 해의 개수는 극값의 부호를 이용해 판정합니다.",
