    "problem": "곡선 $y = x^3 - 12x$에 수평인 접선의 $y$절편 중 양수인 것을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 16,
    "explanation": "**[핵심 개념]**\n- **수평인 접선**: 기울기가 0인 접선을 의미합니다. 따라서 도함수 $f'(x) = 0$인 점에서의 접선입니다.\n- **접선의 방정식**: 점 $(a, f(a))$에서의 접선은 $y - f(a) = f'(a)(x - a)$\n- **y절편**: 접선이 y축과 만나는 점이므로 $x = 0$을 대입했을 때의 $y$ 값입니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$y = x^3 - 12x$$\n$$y' = 3x^2 - 12$$\n\n**2단계: 수평인 접선의 접점 찾기**\n수평인 접선의 조건: $y' = 0$\n$$3x^2 - 12 = 0$$\n$$x^2 = 4$$\n$$x = 2 \\text{ 또는 } x = -2$$\n\n**3단계: 각 접점에서의 y좌표 구하기**\n$x = 2$일 때:\n$$y = 2^3 - 12(2) = 8 - 24 = -16$$\n접점: $(2, -16)$\n\n$x = -2$일 때:\n$$y = (-2)^3 - 12(-2) = -8 + 24 = 16$$\n접점: $(-2, 16)$\n\n**4단계: 각 접점에서의 접선 방정식 구하기**\n기울기가 0이므로 접선은 수평선입니다.\n\n$x = 2$에서: $y = -16$ (y절편: $-16$)\n\n$x = -2$에서: $y = 16$ (y절편: $16$)\n\n**5단계: 양수인 y절편 선택**\ny절편 중 양수는 $\\boxed{16}$입니다.\n\n**[정답 확인]**\n$x = -2$에서의 수평 접선 $y = 16$의 y절편이 양수이며, 이것이 유일한 양수 y절편입니다.\n\n**[오답 분석]**\n- $-16$: 음수이므로 문제의 조건에 맞지 않습니다.\n- 도함수를 잘못 계산하거나 접점을 구하지 않으면 오답이 됩니다.\n\n**[핵심 포인트]**\n- 수평인 접선 찾기: $f'(x) = 0$을 풀어서 접점의 x좌표를 구합니다.\n- y절편은 접선의 방정식에 $x = 0$을 대입하거나, 수평선인 경우 직접 y좌표입니다.",
