    "answer": 0,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선을 구하기 위해서는:\n1. 주어진 점에서의 함수값을 구한다\n2. 그 점에서의 미분값(기울기)을 구한다\n3. 점-기울기 형태의 직선의 방정식을 세운다: $y - y_1 = m(x - x_1)$\n4. 이를 정리하여 $y$절편을 구한다\n\n**[풀이]**\n\n**Step 1: $x = 1$에서 함수값 구하기**\n\n$f(x) = x^4 - 4x^3$이므로\n$$f(1) = 1^4 - 4(1)^3 = 1 - 4 = -3$$\n\n따라서 접점은 $(1, -3)$이다.\n\n**Step 2: $x = 1$에서의 기울기 구하기**\n\n$f(x)$를 미분하면:\n$$f'(x) = 4x^3 - 12x^2$$\n\n$x = 1$일 때의 기울기는:\n$$f'(1) = 4(1)^3 - 12(1)^2 = 4 - 12 = -8$$\n\n**Step 3: 접선의 방정식 구하기**\n\n점 $(1, -3)$을 지나고 기울기가 $-8$인 직선의 방정식:\n$$y - (-3) = -8(x - 1)$$\n$$y + 3 = -8x + 8$$\n$$y = -8x + 5$$\n\n**Step 4: $y$절편 구하기**\n\n$x = 0$일 때: $y = -8(0) + 5 = 5$\n\n따라서 $y$절편은 **5**이다.\n\n**[정답 확인]**\n$x = 1$에서 함수값은 $-3$, 기울기는 $-8$이므로, 접선 방정식 $y = -8x + 5$의 $y$절편은 5이다.\n\n**[오답 분석]**\n- ② 3: 계산 실수로 부호를 잘못 처리한 경우\n- ③ 1: 기울기를 잘못 계산하거나 접점의 $y$좌표를 사용한 경우\n- ④ -1: 접점의 $y$좌표에서 기울기를 뺀 경우\n- ⑤ -3: 접점의 $y$좌표를 $y$절편으로 착각한 경우\n\n**[핵심 포인트]**\n접선의 $y$절편은 접점의 $y$좌표가 아니라, 접선의 방정식 $y = mx + b$에서 $x = 0$을 대입한 값이다. 반드시 완전한 접선의 방정식을 세워서 구해야 한다.",
