    "answer": -3,
    "explanation": "**[핵심 개념]**\n곡선 위의 점에서의 접선의 기울기는 그 점에서의 미분값(도함수)과 같습니다. 접선의 기울기가 음수라는 것은 도함수가 음수라는 의미이므로, 주어진 곡선에서 $y' < 0$인 $x$의 범위를 구하는 문제입니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$y = x^3 + 3x^2 - 9x + 2$$\n$$y' = 3x^2 + 6x - 9$$\n\n**2단계: 접선의 기울기가 음수인 조건**\n접선의 기울기가 음수이려면:\n$$y' < 0$$\n$$3x^2 + 6x - 9 < 0$$\n\n**3단계: 부등식 정리**\n양변을 3으로 나누면:\n$$x^2 + 2x - 3 < 0$$\n\n**4단계: 인수분해**\n$$x^2 + 2x - 3 = (x+3)(x-1)$$\n\n따라서:\n$$(x+3)(x-1) < 0$$\n\n**5단계: 부등식의 해**\n$(x+3)(x-1) < 0$을 만족하는 $x$의 범위는:\n$$-3 < x < 1$$\n\n**6단계: a, b 값 구하기**\n$a = -3$, $b = 1$이므로:\n$$ab = (-3) \\times 1 = -3$$\n\n**[정답 확인]**\n$y' = 3(x+3)(x-1)$이므로, $x = -3$과 $x = 1$에서 $y' = 0$이고, $-3 < x < 1$에서 $y' < 0$이 성립하므로 답은 $ab = -3$입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으므로 일반적인 오류를 언급하면:\n- 부등호 방향을 잘못 설정하여 $x < -3$ 또는 $x > 1$로 구한 경우: 기울기가 양수인 범위를 구하게 됩니다.\n- 인수분해 실수로 근을 잘못 구한 경우: 예를 들어 $(x-3)(x+1)$로 잘못 인수분해하면 $ab = -3$이 아닌 다른 값을 얻습니다.\n- $a + b$를 구하는 경우: $a + b = -3 + 1 = -2$이므로 다른 답이 됩니다.\n\n**[핵심 포인트]**\n- 접선의 기울기 = 도함수의 값이므로, 기울기가 음수 ⟺ 도함수 < 0\n- 이차부등식 $(x+3)(x-1) < 0$을 풀 때는 두 근 사이의 범위가 해가 됨을 기억할 것",
