    "answer": 2,
    "explanation": "**[핵심 개념]**\n이차함수의 증감을 판단하기 위해서는 도함수를 이용합니다. 이차함수 $f(x) = ax^2 + bx + c$ (단, $a > 0$)는 꼭짓점을 기준으로 왼쪽에서는 감소하고 오른쪽에서는 증가합니다. 도함수 $f'(x) > 0$인 구간에서 함수가 증가합니다.\n\n**[풀이]**\n\n주어진 함수는 $f(x) = x^2 - 4x + 3$입니다.\n\n**1단계: 도함수 구하기**\n\n$$f'(x) = \\frac{d}{dx}(x^2 - 4x + 3) = 2x - 4$$\n\n**2단계: 함수가 증가하는 조건**\n\n함수가 증가하는 구간은 $f'(x) > 0$인 구간입니다.\n\n$$f'(x) > 0$$\n$$2x - 4 > 0$$\n$$2x > 4$$\n$$x > 2$$\n\n**3단계: $a$의 값 결정**\n\n함수 $f(x)$가 증가하는 $x$의 범위가 $x > a$이므로:\n\n$$a = 2$$\n\n**[정답 확인]**\n도함수를 이용하여 $f'(x) = 2x - 4 > 0$에서 $x > 2$를 얻었으므로, $a = 2$입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은:\n- $a = 1$: 꼭짓점의 $x$좌표를 구할 때 $x = -\\frac{b}{2a} = \\frac{4}{2} = 2$임을 놓친 경우\n- $a = 3$: 함수값 $f(2) = 4 - 8 + 3 = -1$과 혼동한 경우\n- $a = 4$: 계산 실수로 $2x - 4 > 0$에서 $x > 4$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n이차함수의 증감 구간을 구할 때는 **도함수를 이용하여 $f'(x) > 0$인 구간**을 찾는 것이 가장 확실합니다. 또한 $f'(x) = 2x - 4 = 0$에서 나온 $x = 2$가 증가·감소의 경계점이 됩니다.",
