    "explanation": "**[핵심 개념]**\n이차함수의 증감 판정은 도함수를 이용합니다. $f'(x) > 0$일 때 함수는 증가하고, $f'(x) < 0$일 때 함수는 감소합니다. 또는 표준형 $f(x) = a(x-p)^2 + q$에서 $a < 0$이면 $x > p$에서 감소함을 알 수 있습니다.\n\n**[풀이]**\n\n**방법 1: 도함수 이용**\n\n$f(x) = -x^2 + 6x - 5$에서\n$$f'(x) = -2x + 6$$\n\n함수가 감소하는 구간은 $f'(x) < 0$인 구간입니다.\n$$f'(x) < 0$$\n$$-2x + 6 < 0$$\n$$-2x < -6$$\n$$x > 3$$\n\n**방법 2: 표준형으로 변환**\n\n$f(x) = -x^2 + 6x - 5$를 완전제곱식으로 변환합니다.\n$$f(x) = -(x^2 - 6x) - 5$$\n$$f(x) = -(x^2 - 6x + 9 - 9) - 5$$\n$$f(x) = -(x-3)^2 + 9 - 5$$\n$$f(x) = -(x-3)^2 + 4$$\n\n이 함수는 꼭짓점이 $(3, 4)$인 아래로 볼록한 포물선입니다. 최고점이 $x=3$이므로, $x > 3$일 때 함수값이 감소합니다.\n\n**[정답 확인]**\n$f'(x) = -2x + 6 < 0$을 풀면 $x > 3$이므로, 정답은 ④입니다.\n\n**[오답 분석]**\n- ① $x < -3$: 이 구간에서 $f'(x) = -2x + 6 > 0$이므로 함수는 증가합니다.\n- ② $x < 0$: 이 구간에서도 $f'(x) > 0$이므로 함수는 증가합니다.\n- ③ $x > 0$: $0 < x < 3$에서는 $f'(x) > 0$이므로 증가하고, $x > 3$에서만 감소합니다.\n- ⑤ $x > 6$: 맞는 범위이지만 감소하는 전체 범위를 나타내지 못합니다. 정답은 감소하는 범위의 시작점부터 표현해야 합니다.\n\n**[핵심 포인트]**\n이차함수 $f(x) = a(x-p)^2 + q$에서 최고점(또는 최저점)이 $x = p$이고, 최고점인 경우 $x > p$에서 감소, 최저점인 경우 $x > p$에서 증가합니다. 이 문제에서 $a = -1 < 0$이므로 $x = 3$에서 최고점이고, $x > 3$에서 감소합니다.",
