    "_type": "increasing_decreasing",
    "type": "함수증감",
    "problem": "함수 $f(x) = x^3 - 3x$가 감소하는 구간이 $a < x < b$일 때, $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n함수의 증감을 판정하기 위해서는 도함수를 이용합니다. 함수 $f(x)$가 어떤 구간에서 감소한다는 것은 그 구간에서 $f'(x) < 0$이라는 의미입니다. 따라서 먼저 도함수를 구하고, $f'(x) = 0$인 점들을 찾아 함수의 증감 구간을 판정합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 - 3x$$\n\n양변을 $x$로 미분하면:\n\n$$f'(x) = 3x^2 - 3$$\n\n**Step 2: 도함수가 0이 되는 점 찾기**\n\n함수가 증가에서 감소로(또는 감소에서 증가로) 바뀌는 지점은 $f'(x) = 0$일 때입니다.\n\n$$f'(x) = 3x^2 - 3 = 0$$\n\n$$3(x^2 - 1) = 0$$\n\n$$x^2 = 1$$\n\n$$x = \\pm 1$$\n\n**Step 3: 증감 판정**\n\n$f'(x) = 3(x^2 - 1) = 3(x-1)(x+1)$이므로, 부호를 분석하면:\n\n- $x < -1$일 때: $f'(x) = 3(-)(-)= 3(+) > 0$ → 증가\n- $-1 < x < 1$일 때: $f'(x) = 3(-)(+) = 3(-) < 0$ → **감소**\n- $x > 1$일 때: $f'(x) = 3(+)(+) = 3(+) > 0$ → 증가\n\n따라서 함수 $f(x)$는 $-1 < x < 1$에서 감소합니다.\n\n**Step 4: $a + b$ 구하기**\n\n문제에서 감소하는 구간이 $a < x < b$이므로:\n\n$$a = -1, \\quad b = 1$$\n\n$$a + b = -1 + 1 = 0$$\n\n**[정답 확인]**\n\n도함수 $f'(x) = 3(x+1)(x-1)$에서 $-1 < x < 1$일 때만 $f'(x) < 0$이므로, 감소 구간의 양 끝점이 $-1$과 $1$이며, 이들의 합은 $0$입니다.\n\n**[오답 분석]**\n\n선택지가 없으므로 흔한 오류를 언급하면:\n- $|a| + |b| = 2$로 계산하는 오류\n- 도함수 계산 실수로 다른 근을 구하는 오류\n- 증가 구간과 감소 구간을 혼동하는 오류\n\n**[핵심 포인트]**\n\n1. **함수의 증감 판정 = 도함수의 부호 판정**: $f'(x) > 0$이면 증가, $f'(x) < 0$이면 감소\n2. **대칭성 인식**: $f(x) = x^3 - 3x$는 기함수이므로 증감 구간의 끝점이 원점을 중심으로 대칭이라는 점이 검산에 도움이 됩니다.",
