    "problem": "함수 $f(x) = \\frac{1}{3}x^3 - x^2 + x + 2$가 항상 증가하는 함수인지 판별하시오. 항상 증가하면 1, 아니면 0을 답하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n함수가 항상 증가하는 함수인지 판별하기 위해서는 도함수를 이용합니다. 함수 $f(x)$가 정의역 전체에서 항상 증가하려면 $f'(x) \\geq 0$이어야 하며, 더 엄격하게는 $f'(x) > 0$이거나 $f'(x) = 0$인 점이 고립되어야 합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = \\frac{1}{3}x^3 - x^2 + x + 2$$\n\n$$f'(x) = x^2 - 2x + 1$$\n\n**Step 2: 도함수를 인수분해**\n\n$$f'(x) = x^2 - 2x + 1 = (x-1)^2$$\n\n**Step 3: 도함수의 부호 판정**\n\n$(x-1)^2$은 완전제곱식입니다.\n\n- 모든 실수 $x$에 대해 $(x-1)^2 \\geq 0$\n- 특히 $x = 1$일 때만 $f'(1) = 0$이고, 다른 모든 $x$에서 $f'(x) > 0$\n\n**Step 4: 증가함수 판정**\n\n도함수가 정의역 전체에서 0 이상이고, 0인 점이 고립된 점(한 점뿐)이므로, 함수 $f(x)$는 전체 실수에서 증가함수입니다.\n\n따라서 답은 **1**입니다.\n\n**[정답 확인]**\n\n$f'(x) = (x-1)^2 \\geq 0$이 모든 실수에서 성립하고 $f'(x) = 0$인 점이 $x=1$ 하나뿐이므로, 함수는 항상 증가합니다.\n\n**[오답 분석]**\n\n0을 선택하는 경우: $f'(x) = 0$인 점이 존재한다고 해서 증가함수가 아니라고 잘못 판단할 수 있습니다. 그러나 $f'(x) \\geq 0$이고 $f'(x) = 0$인 점이 고립된 점이면 여전히 증가함수입니다. (예: $f(x) = x^3$도 $f'(0) = 0$이지만 증가함수)\n\n**[핵심 포인트]**\n\n- 함수가 증가함수 ⟺ $f'(x) \\geq 0$ (단, $f'(x) = 0$인 구간이 없어야 함)\n- 완전제곱식 형태의 도함수는 항상 0 이상이므로 증가함수를 나타냅니다.",
