    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n함수의 증감을 판정하기 위해서는 도함수를 이용합니다. $f'(x) > 0$인 구간에서 함수 $f(x)$는 증가하고, $f'(x) < 0$인 구간에서는 감소합니다. 따라서 $f'(x) = 0$이 되는 점들을 찾아 부호를 조사하면 함수의 증감 구간을 결정할 수 있습니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = 2x^3 - 3x^2 - 12x + 5$를 미분하면:\n\n$$f'(x) = 6x^2 - 6x - 12$$\n\n**Step 2: 도함수가 0이 되는 점 찾기**\n\n$f'(x) = 0$일 때:\n\n$$6x^2 - 6x - 12 = 0$$\n\n양변을 6으로 나누면:\n\n$$x^2 - x - 2 = 0$$\n\n인수분해하면:\n\n$$(x - 2)(x + 1) = 0$$\n\n따라서 $x = -1$ 또는 $x = 2$\n\n**Step 3: 도함수의 부호 판정**\n\n$f'(x) = 6x^2 - 6x - 12 = 6(x+1)(x-2)$로 나타낼 수 있습니다.\n\n구간별로 부호를 확인합니다:\n\n- $x < -1$일 때: $(x+1) < 0$, $(x-2) < 0$ → $f'(x) = 6(-)(-)  = (+) > 0$ **(증가)**\n- $-1 < x < 2$일 때: $(x+1) > 0$, $(x-2) < 0$ → $f'(x) = 6(+)(-) = (-) < 0$ **(감소)**\n- $x > 2$일 때: $(x+1) > 0$, $(x-2) > 0$ → $f'(x) = 6(+)(+) = (+) > 0$ **(증가)**\n\n**Step 4: 결론**\n\n함수 $f(x)$는 $x < -1$ 또는 $x > 2$에서 증가합니다.\n\n**[정답 확인]**\n\n도함수 $f'(x) = 6(x+1)(x-2)$가 양수인 구간이 $x < -1$ 또는 $x > 2$이므로 ①번이 정답입니다.\n\n**[오답 분석]**\n\n- ② $-1 < x < 2$: 이 구간은 $f'(x) < 0$이므로 **감소 구간**입니다.\n- ③ $x < -2$ 또는 $x > 1$: 임의로 설정한 범위로, 실제 극값점과 맞지 않습니다.\n- ④ $x < 0$ 또는 $x > 3$: 극값점이 -1과 2인데, 이 선택지는 0과 3을 기준으로 하므로 틀렸습니다.\n- ⑤ $-2 < x < 1$: 이는 감소 구간의 부분 집합이므로 틀렸습니다.\n\n**[핵심 포인트]**\n\n- 함수의 증감을 판정할 때는 반드시 **도함수를 구하고** $f'(x) = 0$인 점을 찾아서 각 구간에서의 부호를 확인해야 합니다.\n- 극값점이 $x = -1, 2$이면, 증가-감소-증가의 패턴을 가지므로 양 끝 구간에서 증가합니다.",
