    "explanation": "**[핵심 개념]**\n함수가 모든 실수에서 증가하려면 도함수가 모든 실수에서 0 이상이어야 합니다. 즉, $f'(x) \\geq 0$이 모든 $x$에 대해 성립해야 합니다. 이차함수가 항상 0 이상이 되려면 판별식이 0 이하여야 합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 + ax^2 + 9x + 1$$\n\n$$f'(x) = 3x^2 + 2ax + 9$$\n\n**Step 2: 증가 조건 설정**\n\n함수 $f(x)$가 모든 실수에서 증가하려면:\n$$f'(x) = 3x^2 + 2ax + 9 \\geq 0 \\text{ (모든 실수 } x \\text{에 대해)}$$\n\n**Step 3: 판별식 조건**\n\n이차함수 $3x^2 + 2ax + 9$가 항상 0 이상이려면, 판별식이 0 이하여야 합니다.\n\n$$D = (2a)^2 - 4 \\cdot 3 \\cdot 9 \\leq 0$$\n\n$$4a^2 - 108 \\leq 0$$\n\n$$a^2 \\leq 27$$\n\n$$|a| \\leq \\sqrt{27} = 3\\sqrt{3}$$\n\n**Step 4: $\\sqrt{27}$의 값 확인**\n\n$$\\sqrt{27} = \\sqrt{9 \\times 3} = 3\\sqrt{3} \\approx 3 \\times 1.732 \\approx 5.196$$\n\n따라서:\n$$-5.196 \\leq a \\leq 5.196$$\n\n**Step 5: 최댓값 구하기**\n\n$a$는 정수이고 $a \\leq 5.196$이므로, $a$의 최댓값은 **5**입니다.\n\n**Step 6: 검증**\n\n- $a = 5$일 때: $D = 4(25) - 108 = 100 - 108 = -8 < 0$ ✓ (조건 만족)\n- $a = 6$일 때: $D = 4(36) - 108 = 144 - 108 = 36 > 0$ ✗ (조건 불만족)\n\n**[정답 확인]**\n$a = 5$일 때 판별식이 음수이므로 $f'(x) > 0$이 모든 실수에서 성립하고, $a = 6$일 때는 판별식이 양수가 되어 $f'(x) = 0$인 점이 존재하므로 정수 $a$의 최댓값은 5입니다.\n\n**[오답 분석]**\n- $a = 6$: 판별식 $D = 36 > 0$이므로 $f'(x) = 0$인 점이 2개 존재하여 극값을 가지므로 불가능\n- $a = 7$ 이상: 더욱 조건을 만족하지 않음\n\n**[핵심 포인트]**\n1. 함수의 증가 조건은 도함수의 비음성(非負性)을 통해 표현됩니다.\n2. 이차식이 항상 양수 또는 0이 되려면 판별식 $\\leq 0$이어야 합니다.",
