    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$이 되는 점에서 극값을 가지며, 도함수의 부호 변화로 극대/극소를 판단합니다. 극대에서 극소로 변할 때 극댓값, 극소에서 극대로 변할 때 극솟값입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = x^3 - 3x^2 - 9x + 11$에서\n\n$$f'(x) = 3x^2 - 6x - 9$$\n\n**Step 2: 극값의 위치 찾기** ($f'(x) = 0$)\n\n$$3x^2 - 6x - 9 = 0$$\n$$x^2 - 2x - 3 = 0$$\n$$(x - 3)(x + 1) = 0$$\n$$x = 3 \\text{ 또는 } x = -1$$\n\n**Step 3: 극대/극소 판정**\n\n$f'(x) = 3(x - 3)(x + 1)$로 나타낼 수 있습니다.\n\n- $x < -1$일 때: $f'(x) = 3(-)(-)= 3(+) > 0$ → 증가\n- $-1 < x < 3$일 때: $f'(x) = 3(-)(+) < 0$ → 감소\n- $x > 3$일 때: $f'(x) = 3(+)(+) > 0$ → 증가\n\n따라서 $x = -1$에서 **극댓값**, $x = 3$에서 **극솟값**을 갖습니다.\n\n**Step 4: 극댓값 구하기** ($x = -1$)\n\n$$f(-1) = (-1)^3 - 3(-1)^2 - 9(-1) + 11$$\n$$= -1 - 3 + 9 + 11 = 16$$\n\n**Step 5: 극솟값 구하기** ($x = 3$)\n\n$$f(3) = 3^3 - 3(3)^2 - 9(3) + 11$$\n$$= 27 - 27 - 27 + 11 = -16$$\n\n**Step 6: 극댓값과 극솟값의 합**\n\n$$16 + (-16) = 0$$\n\n**[정답 확인]**\n극댓값 16과 극솟값 -16의 합이 0이므로 정답은 ③입니다.\n\n**[오답 분석]**\n- ①, ②: 극값을 구할 때 계산 실수가 있거나, 부호를 잘못 처리한 경우\n- ④, ⑤: 극값의 절댓값만 더하거나, 한 극값만 계산한 경우\n\n**[핵심 포인트]**\n3차 함수의 극댓값과 극솟값은 변곡점을 중심으로 대칭이므로, 그 합은 변곡점의 함숫값의 2배입니다. 이 문제에서 변곡점의 $y$좌표가 0이므로 극값의 합도 0이 됩니다.",
