    "answer": 3,
    "explanation": "**[핵심 개념]**\n함수의 극값을 판정하기 위해서는 도함수를 구한 후 극값의 존재 여부를 조사합니다.\n- $f'(x) = 0$인 점을 찾기\n- $f'(x)$의 부호가 바뀌는지 확인하기 (부호가 바뀌어야 극값)\n- 극값은 도함수의 부호가 양(+)에서 음(-)으로 바뀌면 극댓값, 음(-)에서 양(+)으로 바뀌면 극솟값\n\n**[풀이]**\n\n**Step 1: 주어진 함수 인수분해**\n\n$f(x) = x^3 - 6x^2 + 12x - 8$을 살펴보면, 이는 $(x-2)^3$ 형태로 전개된 것입니다.\n\n확인: $(x-2)^3 = x^3 - 3 \\cdot x^2 \\cdot 2 + 3 \\cdot x \\cdot 4 - 8 = x^3 - 6x^2 + 12x - 8$ ✓\n\n따라서 $f(x) = (x-2)^3$\n\n**Step 2: 도함수 구하기**\n\n$$f'(x) = 3(x-2)^2$$\n\n**Step 3: 극값 판정**\n\n$f'(x) = 0$을 풀면:\n$$3(x-2)^2 = 0$$\n$$x = 2$$\n\n$x = 2$가 유일한 임계점입니다.\n\n**Step 4: 도함수의 부호 조사**\n\n$f'(x) = 3(x-2)^2$는 모든 $x$에 대해 $f'(x) \\geq 0$입니다.\n- $x < 2$일 때: $f'(x) = 3(음수)^2 > 0$ (양수)\n- $x = 2$일 때: $f'(x) = 0$\n- $x > 2$일 때: $f'(x) = 3(양수)^2 > 0$ (양수)\n\n도함수의 부호가 **양(+) → 0 → 양(+)**으로 변하므로, 부호가 바뀌지 않습니다.\n\n따라서 $x = 2$에서 극값을 가지지 않습니다.\n\n**[정답 확인]**\n$f'(x) = 3(x-2)^2 \\geq 0$이므로 함수는 항상 증가하고, 극값을 가지지 않습니다. 따라서 정답은 **④**입니다.\n\n**[오답 분석]**\n\n① **극댓값과 극솟값을 모두 가진다** - 도함수의 부호가 바뀌지 않으므로 극값이 없습니다.\n\n② **극댓값만 가진다** - 극댓값을 가지려면 $f'(x)$가 양(+)에서 음(-)으로 바뀌어야 하는데, 그렇지 않습니다.\n\n③ **극솟값만 가진다** - 극솟값을 가지려면 $f'(x)$가 음(-)에서 양(+)으로 바뀌어야 하는데, 그렇지 않습니다.\n\n⑤ **$x = 2$에서 감소에서 증가로 바뀐다** - $f'(2) = 0$이지만, $f'(x)$는 $x = 2$ 양쪽에서 모두 양수이므로 감소 구간이 없습니다.\n\n**[핵심 포인트]**\n극값 판정은 도함수의 **부호가 바뀌는지**를 확인하는 것이 핵심입니다. $f'(x) = 0$이어도 부호가 바뀌지 않으면 극값이 아니며, 이 경우 변곡점 또는 정체점이 됩니다.",
