    "_type": "increasing_decreasing",
    "type": "함수증감",
    "problem": "함수 $f(x) = x^3 - 12x + 16$이 감소하는 구간의 길이를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n함수가 감소하는 구간을 구하기 위해서는 도함수를 이용합니다. 함수 $f(x)$에서:\n- $f'(x) < 0$인 구간에서 함수는 감소합니다.\n- 도함수가 0이 되는 점은 극값을 가지는 점입니다.\n\n3차 함수의 도함수는 2차 함수이므로, $f'(x) = 0$의 두 해를 구하면 함수의 증감을 판단할 수 있습니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 - 12x + 16$$\n\n$$f'(x) = 3x^2 - 12$$\n\n**Step 2: 극값을 갖는 점 찾기 ($f'(x) = 0$)**\n\n$$3x^2 - 12 = 0$$\n\n$$3x^2 = 12$$\n\n$$x^2 = 4$$\n\n$$x = \\pm 2$$\n\n따라서 $x = -2$ 또는 $x = 2$\n\n**Step 3: 증감 판정**\n\n$f'(x) = 3x^2 - 12 = 3(x^2 - 4) = 3(x-2)(x+2)$\n\n- $x < -2$일 때: $(x-2) < 0$, $(x+2) < 0$ → $f'(x) = 3(-)(-) > 0$ (증가)\n- $-2 < x < 2$일 때: $(x-2) < 0$, $(x+2) > 0$ → $f'(x) = 3(-)(+) < 0$ (감소)\n- $x > 2$일 때: $(x-2) > 0$, $(x+2) > 0$ → $f'(x) = 3(+)(+) > 0$ (증가)\n\n**Step 4: 감소 구간과 그 길이**\n\n함수는 $-2 \\leq x \\leq 2$ 구간에서 감소합니다.\n\n감소 구간의 길이는:\n$$2 - (-2) = 4$$\n\n**[정답 확인]**\n$f'(x) < 0$인 구간은 $[-2, 2]$이고, 이 구간의 길이는 $2-(-2)=4$입니다.\n\n**[오답 분석]**\n객관식이 아닌 단답형이므로 대표적인 실수:\n- **2를 선택**: 극값의 한쪽 좌표값만 계산한 경우\n- **3을 선택**: 계산 실수로 도함수의 근을 잘못 구한 경우\n- **6을 선택**: 극값 위치의 절댓값을 더한 경우 ($|-2| + |2| = 4$이므로 같지만, 논리가 틀림)\n\n**[핵심 포인트]**\n3차 함수의 증감을 판정할 때는 반드시 도함수의 부호를 좌표축 상에서 명확히 파악하는 것이 중요합니다. 도함수가 0이 되는 두 점 사이의 거리가 감소 구간의 길이입니다.",
