    "answer": -3,
    "explanation": "**[핵심 개념]**\n\n함수가 증가하는 구간을 찾기 위해서는 도함수를 구하고, 도함수가 양수인 구간을 찾아야 합니다. \n- 함수 $f(x)$가 증가 ⟺ $f'(x) > 0$\n- 도함수가 0이 되는 점에서 함수의 극값이 발생하며, 이 점들이 증가/감소 구간의 경계가 됩니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = -x^3 + 3x^2 + 9x - 1$$\n\n$$f'(x) = -3x^2 + 6x + 9$$\n\n**2단계: 도함수가 0이 되는 점 찾기**\n\n$f'(x) = 0$일 때:\n$$-3x^2 + 6x + 9 = 0$$\n\n양변에 $-1$을 곱하면:\n$$3x^2 - 6x - 9 = 0$$\n\n양변을 3으로 나누면:\n$$x^2 - 2x - 3 = 0$$\n\n인수분해하면:\n$$(x - 3)(x + 1) = 0$$\n\n따라서 $x = 3$ 또는 $x = -1$\n\n**3단계: 도함수의 부호 결정**\n\n$f'(x) = -3x^2 + 6x + 9 = -3(x^2 - 2x - 3) = -3(x-3)(x+1)$\n\n각 구간에서 도함수의 부호를 확인:\n- $x < -1$: $f'(x) = -3(-)(-)  = -3(+) < 0$ (감소)\n- $-1 < x < 3$: $f'(x) = -3(-)(+) = -3(-) > 0$ (증가)\n- $x > 3$: $f'(x) = -3(+)(+) = -3(+) < 0$ (감소)\n\n**4단계: 증가 구간 확인 및 $ab$ 계산**\n\n함수가 증가하는 구간은 $-1 < x < 3$\n\n따라서 $a = -1$, $b = 3$\n\n$$ab = (-1) \\times 3 = -3$$\n\n**[정답 확인]**\n\n도함수 $f'(x) = -3(x-3)(x+1)$에서 $-1 < x < 3$일 때만 $f'(x) > 0$이므로, 증가 구간이 정확하고 $ab = -3$이 맞습니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오답으로는:\n- $a + b = 2$를 계산해서 구하는 경우\n- 극값만 구해서 $3 \\times (-1) = -3$을 우연히 맞추는 경우\n- 도함수를 잘못 계산하는 경우\n\n**[핵심 포인트]**\n\n1. **3차 함수의 증감**: 도함수가 2차이므로 최대 2개의 임계점을 가지며, 이들 사이에서 증가/감소가 결정됩니다.\n2. **부호 판정**: $f'(x) = -3(x-3)(x+1)$에서 음수 계수 $-3$이 전체 부호를 바꾸므로, 중간 구간 $-1 < x < 3$에서만 양수가 됩니다.",
