    "explanation": "**[핵심 개념]**\n\n함수의 극값은 도함수가 0이 되는 점에서 나타난다. 함수 $f(x)$가 $x = c$에서 극값을 가지려면:\n- $f'(c) = 0$ (필요조건)\n- $f'(x)$가 $x = c$에서 부호가 바뀌어야 함 (충분조건)\n\n특히 극대에서 극소로 변할 때, $f'(x) = 0$의 두 근에서 도함수의 부호는 양(+)에서 음(-)으로, 그 다음 다시 음(-)에서 양(+)으로 변한다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = x^3 + ax^2 + bx + 1$$\n$$f'(x) = 3x^2 + 2ax + b$$\n\n**2단계: 극값 조건 적용**\n\n$f(x)$가 $x = -1$에서 극대, $x = 3$에서 극소를 가지므로, $f'(x) = 0$의 두 근이 $x = -1$과 $x = 3$이다.\n\n따라서:\n$$f'(-1) = 0: \\quad 3(-1)^2 + 2a(-1) + b = 0$$\n$$3 - 2a + b = 0 \\quad \\cdots (1)$$\n\n$$f'(3) = 0: \\quad 3(3)^2 + 2a(3) + b = 0$$\n$$27 + 6a + b = 0 \\quad \\cdots (2)$$\n\n**3단계: 연립방정식 풀기**\n\n식 (2)에서 식 (1)을 빼면:\n$$(27 + 6a + b) - (3 - 2a + b) = 0$$\n$$24 + 8a = 0$$\n$$a = -3$$\n\n식 (1)에 $a = -3$을 대입:\n$$3 - 2(-3) + b = 0$$\n$$3 + 6 + b = 0$$\n$$b = -9$$\n\n**4단계: 답 구하기**\n\n$$a + b = -3 + (-9) = -12$$\n\n**[정답 확인]**\n\n$a = -3, b = -9$일 때 $f'(x) = 3x^2 - 6x - 9 = 3(x^2 - 2x - 3) = 3(x+1)(x-3)$이므로, $x = -1$에서 극대, $x = 3$에서 극소를 가진다. ✓\n\n**[오답 분석]**\n\n- ② -6: 계산 실수로 $a$와 $b$ 중 하나의 값을 잘못 구한 경우\n- ③ 0: $a = -3, b = 3$처럼 부호를 잘못 계산한 경우\n- ④ 6: $a + b = 3 + 3 = 6$처럼 $a, b$ 부호를 모두 반대로 한 경우\n- ⑤ 12: $a + b = 3 + 9 = 12$처럼 모든 계산에서 부호를 잘못한 경우\n\n**[핵심 포인트]**\n\n극값 조건에서 $f'(x) = 0$의 근이 극값을 갖는 점이라는 것을 정확히 이해하고, 극대·극소의 위치 정보를 이용하여 연립방정식을 세우는 것이 핵심이다. 구한 값을 대입하여 도함수의 인수분해 형태를 확인하는 검증 단계가 중요하다.",
