    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수의 극값은 도함수를 이용하여 구합니다. \n- $f'(x) = 0$이 되는 점에서 극값 후보가 발생합니다.\n- $f'(x)$의 부호가 양(+)에서 음(-)으로 변하면 극대, 음(-)에서 양(+)으로 변하면 극소입니다.\n- 또는 $f''(x)$를 이용하여 $f''(x) < 0$이면 극대, $f''(x) > 0$이면 극소입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = 2x^3 - 9x^2 + 12x - 4$\n\n$f'(x) = 6x^2 - 18x + 12$\n\n**Step 2: 극값 후보 찾기 ($f'(x) = 0$)**\n\n$6x^2 - 18x + 12 = 0$\n\n양변을 6으로 나누면:\n\n$x^2 - 3x + 2 = 0$\n\n$(x-1)(x-2) = 0$\n\n$x = 1$ 또는 $x = 2$\n\n**Step 3: 극대와 극소 판정**\n\n이계 도함수를 구합니다:\n\n$f''(x) = 12x - 18$\n\n$x = 1$일 때: $f''(1) = 12(1) - 18 = -6 < 0$ → **극대**\n\n$x = 2$일 때: $f''(2) = 12(2) - 18 = 6 > 0$ → **극소**\n\n또는 $f'(x) = 6(x-1)(x-2)$의 부호 변화로도 확인할 수 있습니다:\n- $x < 1$: $f'(x) > 0$ (증가)\n- $1 < x < 2$: $f'(x) < 0$ (감소)\n- $x > 2$: $f'(x) > 0$ (증가)\n\n따라서 $x=1$에서 극대, $x=2$에서 극소입니다.\n\n**Step 4: 극대값을 갖는 $x$와 극소값을 갖는 $x$의 곱**\n\n극대가 되는 $x$의 값: $1$\n\n극소가 되는 $x$의 값: $2$\n\n곱: $1 \\times 2 = 2$\n\n**[정답 확인]**\n극대와 극소의 위치를 올바르게 판정하고 두 $x$값의 곱을 구하면 $1 \\times 2 = 2$입니다.\n\n**[오답 분석]**\n- 극대, 극소를 반대로 구분한 경우: 결과는 같지만 개념이 틀림\n- 도함수를 잘못 계산한 경우: 인수분해 단계에서 실수\n- 극값을 갖는 $x$값만 찾고 함수값 $f(1), f(2)$를 구한 경우: 문제에서는 $x$값의 곱을 요구함\n\n**[핵심 포인트]**\n1. 도함수의 부호 변화 또는 이계 도함수를 이용하여 극대/극소를 판정하는 것이 중요합니다.\n2. 극값 자체가 아닌 극값을 갖는 $x$의 값을 구해야 한다는 점을 명확히 해야 합니다.",
