    "explanation": "**[핵심 개념]**\n극값을 구하기 위해서는 먼저 도함수를 구해 극값을 갖는 지점을 찾아야 합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호 변화를 조사하여 극대/극소를 판정합니다. 극댓값은 극대인 점에서의 함수값입니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 + 3x^2 - 9x + k$$\n$$f'(x) = 3x^2 + 6x - 9$$\n\n**2단계: 극값을 갖는 점 찾기**\n$f'(x) = 0$일 때:\n$$3x^2 + 6x - 9 = 0$$\n$$x^2 + 2x - 3 = 0$$\n$$(x+3)(x-1) = 0$$\n$$x = -3 \\text{ 또는 } x = 1$$\n\n**3단계: 극대/극소 판정**\n$f'(x) = 3(x+3)(x-1)$로 인수분해되므로:\n- $x < -3$일 때: $f'(x) > 0$ (증가)\n- $-3 < x < 1$일 때: $f'(x) < 0$ (감소)\n- $x > 1$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -3$에서 극댓값, $x = 1$에서 극솟값을 가집니다.\n\n**4단계: 극댓값이 27이 되는 조건**\n$x = -3$에서 극댓값이 27이므로:\n$$f(-3) = 27$$\n$$(-3)^3 + 3(-3)^2 - 9(-3) + k = 27$$\n$$-27 + 27 + 27 + k = 27$$\n$$27 + k = 27$$\n$$k = 0$$\n\n**[정답 확인]**\n$k = 0$일 때 $f(-3) = -27 + 27 + 27 + 0 = 27$이 되어 극댓값이 정확히 27이 됩니다.\n\n**[오답 분석]**\n- ① $k = -5$: $f(-3) = 27 - 5 = 22$ (극댓값이 22)\n- ③ $k = 5$: $f(-3) = 27 + 5 = 32$ (극댓값이 32)\n- ④ $k = 10$: $f(-3) = 27 + 10 = 37$ (극댓값이 37)\n- ⑤ $k = 22$: $f(-3) = 27 + 22 = 49$ (극댓값이 49)\n\n**[핵심 포인트]**\n극값 문제는 항상 $f'(x) = 0$으로 극값 위치를 찾고, 극댓값/극솟값을 판정한 후, 주어진 극값 조건을 대입하여 상수를 구합니다. 극대와 극소의 위치를 정확히 파악하는 것이 매우 중요합니다.",
