    "problem": "함수 $f(x) = x^3 - 6x^2 + 9x + a$의 극솟값이 양수가 되도록 하는 정수 $a$의 최솟값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f''(x)$의 부호로 극대/극소를 판정합니다. 극솟값이 양수라는 것은 극소점에서의 함수값이 0보다 커야 한다는 의미입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 - 6x^2 + 9x + a$$\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**Step 2: 극값의 위치 찾기**\n$f'(x) = 0$에서 $x = 1$ 또는 $x = 3$\n\n**Step 3: 극대/극소 판정**\n$$f''(x) = 6x - 12 = 6(x-2)$$\n\n- $x = 1$일 때: $f''(1) = 6(1-2) = -6 < 0$ → 극대\n- $x = 3$일 때: $f''(3) = 6(3-2) = 6 > 0$ → 극소\n\n따라서 극솟값은 $x = 3$에서 나타납니다.\n\n**Step 4: 극솟값 계산**\n$$f(3) = 3^3 - 6(3)^2 + 9(3) + a$$\n$$= 27 - 54 + 27 + a$$\n$$= a$$\n\n**Step 5: 극솟값이 양수 조건**\n극솟값이 양수가 되려면:\n$$f(3) = a > 0$$\n$$a > 0$$\n\n**Step 6: 정수 $a$의 최솟값**\n$a$가 양의 정수이면서 가장 작은 값은 $a = 1$입니다.\n\n**[정답 확인]**\n$a = 1$일 때 극솟값은 $f(3) = 1 > 0$이므로 조건을 만족하며, 이것이 조건을 만족하는 최소 정수값입니다.\n\n**[오답 분석]**\n- $a = 0$: 극솟값이 $f(3) = 0$이 되어 양수가 아니므로 조건 불만족\n- $a < 0$: 극솟값이 음수가 되므로 조건 불만족\n- $a \\geq 2$: 조건을 만족하지만 최솟값이 아님\n\n**[핵심 포인트]**\n극값 문제에서는 도함수를 통해 극값의 위치를 찾고, 이계 도함수로 극대/극소를 판정한 후, 해당 점의 함수값에 주어진 조건을 적용합니다. 이 문제에서 극솟값이 정확히 $a$와 같다는 점이 핵심입니다.",
