    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수가 극값을 가지지 않으려면 도함수가 항상 같은 부호를 유지하거나 0이 되어야 합니다. 즉, $f'(x) = 0$이 중근을 가지거나 실근을 갖지 않아야 합니다. 3차 함수의 경우, 도함수는 2차 함수이므로 판별식 $D \\leq 0$일 때 극값을 가지지 않습니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 - 3ax + 2$$\n$$f'(x) = 3x^2 - 3a$$\n\n**Step 2: 극값 조건 분석**\n함수가 극값을 가지려면 $f'(x) = 0$이 서로 다른 두 실근을 가져야 합니다.\n따라서 극값을 **가지지 않으려면** $f'(x) = 0$이 중근을 가지거나 실근을 갖지 않아야 합니다.\n\n**Step 3: 판별식 조건**\n$f'(x) = 3x^2 - 3a = 0$에서\n\n경우 1: $a < 0$일 때\n$$3x^2 - 3a = 0 \\Rightarrow x^2 = a < 0$$\n실근이 없으므로 $f'(x) > 0$ 항상 성립 → 극값 없음 ✓\n\n경우 2: $a = 0$일 때\n$$f'(x) = 3x^2 = 0 \\Rightarrow x = 0 \\text{ (중근)}$$\n$f'(x) \\geq 0$ 항상 성립 → 극값 없음 ✓\n\n경우 3: $a > 0$일 때\n$$3x^2 - 3a = 0 \\Rightarrow x = \\pm\\sqrt{a}$$\n서로 다른 두 실근을 가지므로 극값이 존재함 ✗\n\n**Step 4: 결론**\n극값을 가지지 않으려면 $a \\leq 0$\n\n**[정답 확인]**\n$a \\leq 0$일 때만 $f'(x) = 0$이 중근을 가지거나 실근을 갖지 않아 도함수가 항상 같은 부호를 유지하므로 극값이 없습니다.\n\n**[오답 분석]**\n- **①** $a > 0$: 극값을 **가지는** 조건으로 반대\n- **②** $a < 0$: $a = 0$인 경우를 제외하여 불완전\n- **④** $a \\geq 0$: $a > 0$일 때는 극값을 가지므로 틀림\n- **⑤** 모든 실수: $a > 0$일 때 극값을 가지므로 틀림\n\n**[핵심 포인트]**\n3차 함수가 극값을 가지지 않으려면 도함수(2차 함수)의 판별식이 음수 또는 0이어야 합니다. \"$a \\leq 0$\"에서 등호 조건($a = 0$, 중근)을 빼먹으면 안 됩니다.",
