    "answer": 3,
    "explanation": "**[핵심 개념]**\n함수의 실근의 개수를 구하기 위해서는 함수의 극값을 조사해야 합니다. 3차 함수 $f(x) = x^3 - 3x + 1$에서:\n- $f'(x) = 0$인 점에서 극값을 가집니다\n- 극대값과 극소값의 부호를 조사하면 실근의 개수를 판정할 수 있습니다\n- 극대값 > 0이고 극소값 < 0이면 실근이 3개입니다\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n**Step 2: 극값의 위치 찾기**\n$f'(x) = 0$에서 $x = -1$ 또는 $x = 1$\n\n**Step 3: 극값 판정**\n- $x < -1$일 때: $f'(x) > 0$ (증가)\n- $-1 < x < 1$일 때: $f'(x) < 0$ (감소)\n- $x > 1$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -1$에서 극대, $x = 1$에서 극소입니다.\n\n**Step 4: 극값 계산**\n$$f(-1) = (-1)^3 - 3(-1) + 1 = -1 + 3 + 1 = 3 > 0$$\n$$f(1) = 1^3 - 3(1) + 1 = 1 - 3 + 1 = -1 < 0$$\n\n**Step 5: 실근의 개수 판정**\n- 극대값 $f(-1) = 3 > 0$\n- 극소값 $f(1) = -1 < 0$\n- 극대값이 양수이고 극소값이 음수이므로 중간값 정리에 의해:\n  - $x < -1$ 구간에서 실근 1개\n  - $-1 < x < 1$ 구간에서 실근 1개\n  - $x > 1$ 구간에서 실근 1개\n\n따라서 서로 다른 실근의 개수는 **3개**입니다.\n\n**[정답 확인]**\n3차 함수에서 극대값과 극소값의 부호가 반대이면 3개의 서로 다른 실근을 가집니다. $f(-1) = 3 > 0$, $f(1) = -1 < 0$이므로 정답은 ④입니다.\n\n**[오답 분석]**\n- ① 0개: 실근이 완전히 없으려면 극값이 모두 같은 부호여야 하므로 틀림\n- ② 1개: 극값의 부호가 같거나 한 극값이 0인 경우인데, 계산 결과 부호가 반대이므로 틀림\n- ③ 2개: 3차 함수는 2개의 실근을 가질 수 없습니다 (3개 또는 1개만 가능)\n- ⑤ 판단할 수 없다: 극값을 통해 명확하게 판단 가능하므로 틀림\n\n**[핵심 포인트]**\n3차 함수의 실근 개수는 **극값의 부호**로 결정됩니다. 극대값 > 0이고 극소값 < 0이면 반드시 3개의 서로 다른 실근을 가집니다.",
