    "answer": 3,
    "explanation": "**[핵심 개념]**\n- 극값의 조건: $f'(x) = 0$인 점에서 $f'(x)$의 부호가 바뀌어야 함\n- 3차 함수의 극값: 극댓값과 극솟값은 $f'(x) = 0$의 두 근에서 발생\n- 두 수의 곱이 음수: 두 수의 부호가 반대여야 함 (한 개는 양수, 한 개는 음수)\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f'(x) = 3x^2 - 6x = 3x(x-2)$$\n\n따라서 $f'(x) = 0$일 때 $x = 0$ 또는 $x = 2$\n\n**Step 2: 극값 구하기**\n- $x = 0$에서 극댓값: $f(0) = a$\n- $x = 2$에서 극솟값: $f(2) = 8 - 12 + a = a - 4$\n\n($x < 0$에서 $f'(x) > 0$, $0 < x < 2$에서 $f'(x) < 0$, $x > 2$에서 $f'(x) > 0$이므로)\n\n**Step 3: 극댓값과 극솟값의 곱이 음수인 조건**\n$$f(0) \\cdot f(2) < 0$$\n$$a(a-4) < 0$$\n\n이 부등식이 성립하려면:\n$$0 < a < 4$$\n\n**Step 4: 정수 $a$의 개수**\n위 부등식을 만족하는 정수는:\n$$a \\in \\{1, 2, 3\\}$$\n\n따라서 정수 $a$의 개수는 **3개**\n\n**[정답 확인]**\n극댓값 $a$와 극솟값 $a-4$의 곱 $a(a-4) < 0$을 만족하는 정수는 1, 2, 3이므로 개수는 3개입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은:\n- 4: $0 < a < 4$에 포함된 정수를 $0, 1, 2, 3, 4$로 잘못 센 경우\n- 2: 부등식을 $0 < a \\leq 4$로 잘못 이해한 경우\n\n**[핵심 포인트]**\n- 3차 함수에서 극값은 $f'(x) = 0$의 근에서 발생하며, 곱이 음수 조건은 두 극값의 부호가 반대라는 뜻\n- 부등식 $a(a-4) < 0$의 해는 $0 < a < 4$이고, 이를 만족하는 정수의 개수를 세는 것이 핵심",
