    "problem": "함수 $f(x) = \\frac{1}{3}x^3 - \\frac{1}{2}x^2 - 2x + 1$의 극대가 되는 $x$의 값을 $\\alpha$, 극소가 되는 $x$의 값을 $\\beta$라 할 때, $\\alpha\\beta$의 값을 구하시오.",
