    "explanation": "**[핵심 개념]**\n함수의 극값은 도함수를 이용하여 구합니다. $f'(x) = 0$이 되는 점에서 극값을 가지며, $f'(x)$의 부호가 양에서 음으로 바뀌면 극대, 음에서 양으로 바뀌면 극소입니다. 또한 극대와 극소를 주는 $x$값들은 $f'(x) = 0$의 두 근이므로, 근과 계수의 관계를 이용할 수 있습니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = \\frac{1}{3}x^3 - \\frac{1}{2}x^2 - 2x + 1$$\n\n$$f'(x) = x^2 - x - 2$$\n\n**2단계: 극값을 갖는 점 찾기**\n\n극값을 갖는 $x$값은 $f'(x) = 0$의 해입니다.\n\n$$x^2 - x - 2 = 0$$\n\n인수분해하면:\n$$(x - 2)(x + 1) = 0$$\n\n따라서 $x = 2$ 또는 $x = -1$\n\n**3단계: 극대와 극소 판별**\n\n$f'(x) = (x-2)(x+1)$의 부호 변화를 조사합니다.\n\n- $x < -1$일 때: $f'(x) = (-)(-) = (+)$ → 증가\n- $-1 < x < 2$일 때: $f'(x) = (-)(+) = (-)$ → 감소\n- $x > 2$일 때: $f'(x) = (+)(+) = (+)$ → 증가\n\n따라서:\n- $x = -1$에서 극대 → $\\alpha = -1$\n- $x = 2$에서 극소 → $\\beta = 2$\n\n**4단계: $\\alpha\\beta$ 계산**\n\n$$\\alpha\\beta = (-1) \\times 2 = -2$$\n\n또는 근과 계수의 관계를 이용하면, $x^2 - x - 2 = 0$에서 두 근의 곱은 $\\frac{-2}{1} = -2$입니다.\n\n**[정답 확인]**\n$\\alpha = -1$(극대), $\\beta = 2$(극소)이므로 $\\alpha\\beta = -2$이 정답입니다.\n\n**[오답 분석]**\n- 극대와 극소를 반대로 판별한 경우 여전히 $-2$가 나오므로 이 문제에서는 순서가 중요하지 않습니다.\n- 근과 계수의 관계를 정확히 적용하지 않으면 오답이 나올 수 있습니다.\n\n**[핵심 포인트]**\n- 극값을 갖는 두 $x$값은 $f'(x) = 0$의 두 근이므로, 근과 계수의 관계 $\\alpha\\beta = \\frac{c}{a}$를 바로 적용할 수 있습니다.\n- 이 경우 $x^2 - x - 2 = 0$에서 두 근의 곱은 $-2$입니다.",
