    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n삼차함수가 서로 다른 세 실근을 가지려면 극댓값과 극솟값이 존재하고, 극댓값과 극솟값의 부호가 반대여야 합니다. 즉, (극댓값) × (극솟값) < 0 이어야 합니다.\n\n**[풀이]**\n\n**Step 1: 극값 구하기**\n\n$f(x) = x^3 + 3x^2 - 24x + a$에서\n\n$f'(x) = 3x^2 + 6x - 24 = 3(x^2 + 2x - 8) = 3(x+4)(x-2)$\n\n극값은 $x = -4$와 $x = 2$에서 발생합니다.\n\n**Step 2: 극댓값과 극솟값 계산**\n\n$x = -4$에서 극댓값:\n$$f(-4) = (-4)^3 + 3(-4)^2 - 24(-4) + a = -64 + 48 + 96 + a = 80 + a$$\n\n$x = 2$에서 극솟값:\n$$f(2) = 2^3 + 3(2)^2 - 24(2) + a = 8 + 12 - 48 + a = -28 + a$$\n\n**Step 3: 서로 다른 세 실근 조건**\n\n삼차함수가 서로 다른 세 실근을 가지려면:\n$$(극댓값) \\times (극솟값) < 0$$\n\n$$(80 + a)(-28 + a) < 0$$\n\n**Step 4: 부등식 풀기**\n\n$(80 + a)(-28 + a) < 0$에서\n\n이 식이 0이 되는 경우는 $a = -80$ 또는 $a = 28$\n\n포물선 $(80 + a)(-28 + a)$를 생각하면 (계수가 음수), \n\n$$-80 < a < 28$$\n\n**Step 5: 정수 개수 세기**\n\n정수 $a$는 $-79, -78, -77, \\ldots, 26, 27$\n\n$a = -79$부터 $a = 27$까지\n\n개수 = $27 - (-79) + 1 = 27 + 79 + 1 = 107$\n\n**[정답 확인]**\n\n$-80 < a < 28$을 만족하는 정수는 $-79$부터 $27$까지이므로 정확히 107개입니다.\n\n**[오답 분석]**\n\n- ① 56: 범위를 잘못 계산한 경우\n- ② 79: 한쪽 끝점만 포함하거나 범위를 축소한 경우\n- ③ 100: 부등호 조건을 잘못 적용한 경우\n- ④ 106: 경계값 하나를 제외한 경우 (예: $a = 28$ 또는 $a = -80$ 포함/제외 실수)\n\n**[핵심 포인트]**\n\n1. 삼차함수의 서로 다른 세 실근 ⟺ 극댓값 × 극솟값 < 0 (경계 제외)\n2. $-80 < a < 28$에서 정수의 개수는 양쪽 경계 모두 제외하여 계산: $27 - (-79) + 1 = 107$",
