    "problem": "함수 $f(x) = -x^2 + 4x - 1$의 최댓값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 3,
    "explanation": "**[핵심 개념]**\n이차함수 $f(x) = ax^2 + bx + c$ (단, $a \\neq 0$)의 최댓값과 최솟값을 구하는 방법은 다음과 같습니다.\n- $a > 0$이면 최솟값이 존재하고, $a < 0$이면 최댓값이 존재합니다.\n- 꼭짓점의 좌표는 $x = -\\frac{b}{2a}$일 때이며, 이 점에서 극값을 가집니다.\n- 완전제곱식으로 변형하거나 꼭짓점 공식을 사용할 수 있습니다.\n\n**[풀이]**\n\n**방법 1: 완전제곱식으로 변형**\n\n주어진 함수는 $f(x) = -x^2 + 4x - 1$입니다.\n\n$-x^2 + 4x - 1$을 완전제곱식으로 정리하면:\n\n$$f(x) = -(x^2 - 4x) - 1$$\n\n$$f(x) = -(x^2 - 4x + 4 - 4) - 1$$\n\n$$f(x) = -(x^2 - 4x + 4) + 4 - 1$$\n\n$$f(x) = -(x - 2)^2 + 3$$\n\n$-(x-2)^2 \\leq 0$이므로, $f(x) \\leq 3$입니다.\n\n등호는 $x = 2$일 때 성립하므로, 최댓값은 $\\boxed{3}$입니다.\n\n**방법 2: 꼭짓점 공식 사용**\n\n$f(x) = -x^2 + 4x - 1$에서 $a = -1, b = 4, c = -1$입니다.\n\n꼭짓점의 $x$좌표: $x = -\\frac{b}{2a} = -\\frac{4}{2(-1)} = 2$\n\n$x = 2$일 때의 함숫값:\n$$f(2) = -(2)^2 + 4(2) - 1 = -4 + 8 - 1 = 3$$\n\n따라서 최댓값은 $\\boxed{3}$입니다.\n\n**[정답 확인]**\n이차항의 계수가 음수($-1$)이므로 아래로 볼록한 포물선이며, 꼭짓점에서 최댓값 3을 가집니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 다음과 같은 실수가 가능합니다:\n- **4를 선택한 경우**: 완전제곱식 변형 시 $-(x-2)^2 + 4$로 잘못 계산\n- **2를 선택한 경우**: 최댓값을 구하는 $x$값과 혼동\n- **-1을 선택한 경우**: 상수항만 답으로 착각\n\n**[핵심 포인트]**\n- 이차함수의 최댓값/최솟값은 **완전제곱식 변형**으로 꼭짓점의 $y$좌표를 구하는 것이 가장 안정적입니다.\n- 계수가 음수인 이차함수는 위로 볼록하므로 **최댓값이 존재**합니다.",
