    "explanation": "**[핵심 개념]**\n이차함수 $f(x) = ax^2 + bx + c$ (단, $a > 0$)의 최솟값을 구하는 방법은 두 가지입니다.\n1) 완전제곱식으로 변형: $f(x) = a(x-p)^2 + q$ 형태로 만들면 $x=p$일 때 최솟값은 $q$\n2) 꼭짓점 공식: 꼭짓점의 $x$좌표는 $x = -\\frac{b}{2a}$이고, 이때의 함숫값이 최솟값\n\n**[풀이]**\n\n**방법 1: 완전제곱식으로 변형**\n\n주어진 함수를 완전제곱식으로 만들어봅시다.\n\n$$f(x) = x^2 - 6x + 10$$\n\n$x^2 - 6x$ 부분을 완전제곱식으로 변형합니다:\n\n$$f(x) = (x^2 - 6x + 9) - 9 + 10$$\n\n$$f(x) = (x-3)^2 + 1$$\n\n이 식에서 $(x-3)^2 \\geq 0$이므로, $f(x)$의 최솟값은 $(x-3)^2 = 0$일 때 달성됩니다.\n\n따라서 $x = 3$일 때 **최솟값은 1**입니다.\n\n**방법 2: 꼭짓점 공식 이용**\n\n$f(x) = x^2 - 6x + 10$에서 $a=1, b=-6, c=10$\n\n꼭짓점의 $x$좌표: $x = -\\frac{b}{2a} = -\\frac{(-6)}{2(1)} = 3$\n\n$x=3$을 대입하면:\n$$f(3) = 3^2 - 6(3) + 10 = 9 - 18 + 10 = 1$$\n\n**[정답 확인]**\n완전제곱식 $f(x) = (x-3)^2 + 1$에서 제곱항의 최솟값이 0이므로, 함수의 최솟값은 1입니다.\n\n**[오답 분석]**\n- ① -1: 계산 실수로 부호를 반대로 처리한 경우\n- ② 0: $f(x) = (x-3)^2$로 잘못 변형한 경우 (상수항 10을 누락)\n- ④ 2: 상수항 10을 제대로 처리하지 못한 경우\n- ⑤ 3: 꼭짓점의 $x$좌표인 3을 최솟값으로 잘못 선택한 경우\n\n**[핵심 포인트]**\n완전제곱식 변형 시 $x^2 - 6x$를 $(x-3)^2 - 9$로 만든 후, 전체 식에서 $-9+10=1$을 상수항으로 처리하는 것이 핵심입니다. 이차함수의 최솟값은 항상 완전제곱식의 상수항입니다.",
