    "problem": "닫힌구간 $[0,\\, 3]$에서 함수 $f(x) = x^2 - 2x + 3$의 최댓값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n닫힌구간에서 함수의 최댓값을 구하는 문제입니다. 이차함수는 포물선이므로, 주어진 구간 내에서의 최댓값은 다음 두 경우 중 하나입니다:\n1. 꼭짓점(극값)이 구간 내에 있으면 꼭짓점 또는 끝점\n2. 꼭짓점이 구간 밖에 있으면 끝점\n\n따라서 **함수의 도함수를 구해 극값을 찾고, 극값과 끝점의 함수값을 모두 비교**해야 합니다.\n\n**[풀이]**\n\n$f(x) = x^2 - 2x + 3$이 주어졌습니다.\n\n**Step 1: 극값 찾기**\n$$f'(x) = 2x - 2$$\n\n극값은 $f'(x) = 0$일 때:\n$$2x - 2 = 0 \\Rightarrow x = 1$$\n\n$x = 1$은 구간 $[0, 3]$에 포함됩니다.\n\n**Step 2: 극값의 성질 확인**\n$$f''(x) = 2 > 0$$\n따라서 $x = 1$에서 극솟값을 가집니다.\n\n**Step 3: 함수값 계산**\n이차함수의 최댓값은 아래로 볼록한 포물선이므로 끝점에서 나타납니다.\n\n- $x = 0$일 때: $f(0) = 0^2 - 2(0) + 3 = 3$\n- $x = 1$일 때: $f(1) = 1^2 - 2(1) + 3 = 1 - 2 + 3 = 2$ (극솟값)\n- $x = 3$일 때: $f(3) = 3^2 - 2(3) + 3 = 9 - 6 + 3 = 6$\n\n**Step 4: 최댓값 결정**\n세 값 중 비교: $f(0) = 3$, $f(1) = 2$, $f(3) = 6$\n\n따라서 최댓값은 $\\boxed{6}$입니다.\n\n**[정답 확인]**\n$f(x) = (x-1)^2 + 2$로 변형하면 꼭짓점이 $(1, 2)$인 아래로 볼록한 포물선이므로, 구간 $[0,3]$에서 0과 3 중 1에서 더 먼 끝점 $x=3$에서 최댓값 6을 가집니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으므로, 흔한 실수는:\n- **3을 선택**: 극솟값 2를 놓치고 $f(0)=3$만 고려\n- **2를 선택**: 극값이 최댓값이라고 착각 (실제로는 극솟값)\n- **9를 선택**: $f(3)$의 계산 실수 ($9-6+3=6$인데 9로 계산)\n\n**[핵심 포인트]**\n- 닫힌구간에서 연속함수의 최댓값은 **극값 또는 끝점**에서만 나타난다.\n- 아래로 볼록한 포물선($f''(x) > 0$)의 최댓값은 **끝점에서** 나타난다.",
