    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최솟값을 구하려면 다음 두 가지를 비교해야 합니다:\n1. 구간 내 극값(극소값): $f'(x) = 0$인 점에서의 함수값\n2. 구간의 끝점에서의 함수값\n\n폐구간 $[a, b]$에서 최솟값은 극값과 끝점 함수값 중 가장 작은 값입니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 3x$$\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n**2단계: 극값을 갖는 점 찾기**\n$f'(x) = 0$에서\n$$3(x-1)(x+1) = 0$$\n$$x = -1 \\text{ 또는 } x = 1$$\n\n두 점 모두 구간 $[-1, 2]$에 포함됩니다.\n\n**3단계: 각 점에서의 함수값 계산**\n\n$x = -1$일 때:\n$$f(-1) = (-1)^3 - 3(-1) = -1 + 3 = 2$$\n\n$x = 1$일 때:\n$$f(1) = 1^3 - 3(1) = 1 - 3 = -2$$\n\n$x = 2$일 때 (우측 끝점):\n$$f(2) = 2^3 - 3(2) = 8 - 6 = 2$$\n\n**4단계: 최솟값 결정**\n계산한 함수값들: $f(-1) = 2$, $f(1) = -2$, $f(2) = 2$\n\n따라서 최솟값은 $\\boxed{-2}$입니다.\n\n**[정답 확인]**\n구간 내 모든 임계점과 끝점에서 함수값을 비교한 결과, $f(1) = -2$가 가장 작으므로 정답은 ②번입니다.\n\n**[오답 분석]**\n- ① -4: 계산 오류로 인한 오답\n- ③ 0: $f(0) = 0$이지만 최솟값이 아님\n- ④ 2: $f(-1) = f(2) = 2$로 최댓값에 해당\n- ⑤ 4: 구간 내에서 나타나지 않는 값\n\n**[핵심 포인트]**\n폐구간에서의 최솟값은 **극값만이 아니라 끝점도 반드시 확인**해야 합니다. 특히 $x = -1$이 끝점이면서 동시에 극값이므로 놓치기 쉬운 부분입니다.",
