    "answer": 5,
    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. \n- 극값은 $f'(x) = 0$인 점에서 나타남\n- $f'(x) = 0$의 해를 구한 후, 그 점 좌우에서 도함수의 부호 변화를 확인\n- $f'(x)$가 양(+)에서 음(-)으로 변하면 극댓값, 음(-)에서 양(+)으로 변하면 극솟값\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 - 3x^2 + 5$$\n\n$$f'(x) = 3x^2 - 6x = 3x(x-2)$$\n\n**Step 2: 극값의 후보점 찾기**\n\n$f'(x) = 0$을 풀면:\n$$3x(x-2) = 0$$\n$$x = 0 \\text{ 또는 } x = 2$$\n\n**Step 3: 부호 변화 확인**\n\n도함수 $f'(x) = 3x(x-2)$의 부호를 수직선에 표시:\n\n- $x < 0$일 때: $f'(x) = 3(음)(음) = 양(+)$ → 함수 증가\n- $0 < x < 2$일 때: $f'(x) = 3(양)(음) = 음(-)$ → 함수 감소  \n- $x > 2$일 때: $f'(x) = 3(양)(양) = 양(+)$ → 함수 증가\n\n따라서:\n- $x = 0$에서 $f'(x)$가 $(+) \\to (-)$로 변하므로 **극댓값**\n- $x = 2$에서 $f'(x)$가 $(-) \\to (+)$로 변하므로 극솟값\n\n**Step 4: 극댓값 계산**\n\n$$f(0) = 0^3 - 3(0)^2 + 5 = 5$$\n\n**[정답 확인]**\n$x=0$에서 도함수의 부호가 양에서 음으로 바뀌므로 극댓값이며, $f(0) = 5$입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은:\n- $f(2) = 8 - 12 + 5 = 1$을 극댓값으로 잘못 선택 (이는 극솟값)\n- 미분을 잘못 계산하여 다른 값을 얻음\n\n**[핵심 포인트]**\n극값 판정은 **도함수의 부호 변화**로 결정됩니다. $(+) \\to (-)$는 극댓값, $(-) \\to (+)$는 극솟값이므로, 양쪽 부호를 반드시 확인하세요.",
