    "problem": "닫힌구간 $[-2,\\, 3]$에서 함수 $f(x) = x^3 - 3x + 1$의 최댓값과 최솟값의 차를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 20,
    "explanation": "**[핵심 개념]**\n\n폐구간에서 함수의 최댓값과 최솟값을 구하기 위해서는:\n1. 함수의 도함수를 구해 극값을 찾기 (임계점)\n2. 극값과 구간의 끝점에서의 함수값을 모두 비교\n3. 가장 큰 값과 가장 작은 값의 차를 구하기\n\n**[풀이]**\n\n**Step 1: 도함수를 구하고 극값 찾기**\n\n$f(x) = x^3 - 3x + 1$에서\n\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n$f'(x) = 0$일 때: $x = -1$ 또는 $x = 1$\n\n두 극값 모두 닫힌구간 $[-2, 3]$에 포함됨\n\n**Step 2: 극값의 성질 확인**\n\n$f''(x) = 6x$\n\n- $f''(-1) = -6 < 0$ → $x = -1$에서 극대\n- $f''(1) = 6 > 0$ → $x = 1$에서 극소\n\n**Step 3: 후보값 계산**\n\n구간 끝점과 극값에서의 함수값:\n\n$$f(-2) = (-2)^3 - 3(-2) + 1 = -8 + 6 + 1 = -1$$\n\n$$f(-1) = (-1)^3 - 3(-1) + 1 = -1 + 3 + 1 = 3$$\n\n$$f(1) = (1)^3 - 3(1) + 1 = 1 - 3 + 1 = -1$$\n\n$$f(3) = (3)^3 - 3(3) + 1 = 27 - 9 + 1 = 19$$\n\n**Step 4: 최댓값과 최솟값 결정**\n\n비교: $-1, 3, -1, 19$\n\n- 최댓값: $f(3) = 19$\n- 최솟값: $f(-2) = f(1) = -1$\n\n**Step 5: 차 계산**\n\n$$\\text{최댓값} - \\text{최솟값} = 19 - (-1) = 20$$\n\n**[정답 확인]**\n\n폐구간에서 모든 후보점(극값과 끝점)을 비교한 결과, 최댓값 19에서 최솟값 -1을 뺀 값이 20이므로 정답입니다.\n\n**[오답 분석]**\n\n객관식 선택지가 제시되지 않았으나, 흔한 오류:\n- 극값만 비교하고 끝점을 빠뜨린 경우\n- $f(-2)$를 잘못 계산한 경우\n- 극대값과 극소값의 차($3 - (-1) = 4$)로 답한 경우\n\n**[핵심 포인트]**\n\n**폐구간에서 최댓값·최솟값은 반드시 극값과 끝점을 모두 비교해야 하며**, 이 문제에서는 끝점 $x=3$에서 최댓값이 나타나는 점이 중요합니다.",
