    "answer": 2,
    "explanation": "**[핵심 개념]**\n산술-기하 평균 부등식(AM-GM inequality)을 이용하여 함수의 최솟값을 구하는 문제입니다.\n\n**산술-기하 평균 부등식**: 양수 $a, b$에 대하여 $\\frac{a+b}{2} \\geq \\sqrt{ab}$이며, 등호는 $a=b$일 때 성립합니다.\n\n이를 정리하면 $a + b \\geq 2\\sqrt{ab}$입니다.\n\n**[풀이]**\n\n주어진 함수는 $f(x) = x + \\frac{4}{x}$ (단, $x > 0$)입니다.\n\n**방법 1: 산술-기하 평균 부등식 이용**\n\n$x$와 $\\frac{4}{x}$는 모두 양수이므로 산술-기하 평균 부등식을 적용할 수 있습니다.\n\n$$x + \\frac{4}{x} \\geq 2\\sqrt{x \\cdot \\frac{4}{x}}$$\n\n$$x + \\frac{4}{x} \\geq 2\\sqrt{4}$$\n\n$$x + \\frac{4}{x} \\geq 2 \\times 2 = 4$$\n\n등호 조건: $x = \\frac{4}{x}$일 때 성립하므로 $x^2 = 4$, 즉 $x = 2$ (양수이므로)\n\n따라서 최솟값은 $f(2) = 2 + \\frac{4}{2} = 2 + 2 = 4$\n\n**방법 2: 미분을 이용한 검증**\n\n$$f'(x) = 1 - \\frac{4}{x^2}$$\n\n$f'(x) = 0$일 때: $1 - \\frac{4}{x^2} = 0$ ⟹ $x^2 = 4$ ⟹ $x = 2$ (양수)\n\n$f''(x) = \\frac{8}{x^3} > 0$ (모든 양수 $x$에 대해)이므로 $x=2$에서 최솟값을 가집니다.\n\n$$f(2) = 2 + \\frac{4}{2} = 4$$\n\n**[정답 확인]**\n산술-기하 평균 부등식을 적용하면 $x + \\frac{4}{x} \\geq 4$이고, $x=2$일 때 등호가 성립하므로 최솟값은 **4**입니다.\n\n**[오답 분석]**\n- ① 2: $x=1$일 때 $f(1)=5$, $x=2$일 때 $f(2)=4$로 최솟값이 아님\n- ② 3: 산술-기하 평균 부등식의 결과값을 잘못 계산한 경우\n- ④ 5: $x=1$일 때 $f(1)=1+4=5$이지만, 이는 최솟값이 아님\n- ⑤ 6: $x=3$일 때 $f(3)=3+\\frac{4}{3}≈4.33$으로 최솟값이 아님\n\n**[핵심 포인트]**\n$a + \\frac{k}{a}$ 형태의 함수는 산술-기하 평균 부등식을 적용하면 최솟값이 $2\\sqrt{k}$임을 기억하세요. 이 문제에서는 $k=4$이므로 최솟값은 $2\\sqrt{4}=4$입니다.",
