    "answer": 9,
    "explanation": "**[핵심 개념]**\n산술-기하 평균 부등식(AM-GM Inequality)을 사용합니다. 두 양수 $a, b$에 대해 $\\frac{a+b}{2} \\geq \\sqrt{ab}$이 성립하며, 등호는 $a=b$일 때 성립합니다. 이를 이용하면 합이 정해졌을 때 곱의 최댓값을 구할 수 있습니다.\n\n**[풀이]**\n\n주어진 조건: $x + y = 6$ (단, $x, y > 0$)\n\n산술-기하 평균 부등식을 적용하면:\n$$\\frac{x+y}{2} \\geq \\sqrt{xy}$$\n\n$x + y = 6$을 대입합니다:\n$$\\frac{6}{2} \\geq \\sqrt{xy}$$\n\n$$3 \\geq \\sqrt{xy}$$\n\n양변을 제곱하면:\n$$9 \\geq xy$$\n\n따라서 $xy \\leq 9$\n\n등호 조건은 $x = y$일 때 성립합니다.\n\n$x = y$이고 $x + y = 6$이므로:\n$$2x = 6$$\n$$x = 3, \\quad y = 3$$\n\n이때 $xy = 3 \\times 3 = 9$\n\n**[정답 확인]**\n$x = y = 3$일 때 조건 $x + y = 6$을 만족하고, $xy = 9$의 최댓값을 얻습니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으나, 학생들이 범할 수 있는 오류:\n- 다른 값들을 대입한 경우: 예를 들어 $x=1, y=5$일 때 $xy=5<9$, $x=2, y=4$일 때 $xy=8<9$로 모두 9보다 작습니다.\n- 미분을 사용한 경우: $y=6-x$로 놓으면 $f(x)=x(6-x)=6x-x^2$이고, $f'(x)=6-2x=0$에서 $x=3$을 얻어 같은 답입니다.\n\n**[핵심 포인트]**\n합이 일정할 때 곱의 최댓값은 산술-기하 평균 부등식으로 구하며, 최댓값은 두 수가 같을 때 달성됩니다. 즉, $x+y=6$일 때 $xy$는 $x=y=3$에서 최대값 9를 가집니다.",
