    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최솟값을 구하는 방법:\n1. 함수의 도함수를 구하여 극값(극대, 극소)을 찾기\n2. 구간 내의 극값과 양 끝점에서의 함숫값을 모두 비교\n3. 이 중 가장 작은 값이 최솟값\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 - 6x^2 + 9x + 1$$\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**Step 2: 극값을 갖는 점 찾기**\n$f'(x) = 0$일 때: $x = 1$ 또는 $x = 3$\n\n두 값 모두 주어진 구간 $[0, 4]$에 포함됨.\n\n**Step 3: 구간 끝점과 극값에서의 함숫값 계산**\n\n$x = 0$일 때:\n$$f(0) = 0 - 0 + 0 + 1 = 1$$\n\n$x = 1$일 때:\n$$f(1) = 1 - 6 + 9 + 1 = 5$$\n\n$x = 3$일 때:\n$$f(3) = 27 - 6(9) + 9(3) + 1 = 27 - 54 + 27 + 1 = 1$$\n\n$x = 4$일 때:\n$$f(4) = 64 - 6(16) + 9(4) + 1 = 64 - 96 + 36 + 1 = 5$$\n\n**Step 4: 최솟값 결정**\n\n비교: $f(0) = 1$, $f(1) = 5$, $f(3) = 1$, $f(4) = 5$\n\n따라서 최솟값은 $\\boxed{1}$\n\n**[정답 확인]**\n구간 $[0, 4]$에서 계산한 함숫값 중 $f(0) = 1$과 $f(3) = 1$이 최소이므로 정답은 ④번입니다.\n\n**[오답 분석]**\n- ① -3: 계산 오류. 주어진 함수는 구간 내에서 음수값을 갖지 않음\n- ② -1: 계산 실수로 인한 오답\n- ③ 0: 어느 점에서도 함숫값이 0이 되지 않음\n- ⑤ 5: 극댓값에 해당($x=1, x=4$에서) 하나 최솟값이 아님\n\n**[핵심 포인트]**\n폐구간에서의 최솟값은 반드시 극값과 끝점의 함숫값을 모두 구해 비교해야 함. 극값이 최솟값이 아닐 수도 있음을 주의할 것.",
