    "explanation": "**[핵심 개념]**\n\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$이 되는 점에서 극값을 가지며, $f'(x)$의 부호 변화를 조사하여 극대/극소를 판정합니다. 극댓값과 극솟값의 차는 두 극값의 절댓값 차이를 의미합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = x^3 - 6x^2 + 9x + 2$$\n\n$$f'(x) = 3x^2 - 12x + 9$$\n\n**2단계: 극값을 가지는 점 찾기 ($f'(x) = 0$)**\n\n$$3x^2 - 12x + 9 = 0$$\n\n양변을 3으로 나누면:\n$$x^2 - 4x + 3 = 0$$\n\n인수분해하면:\n$$(x - 1)(x - 3) = 0$$\n\n따라서 $x = 1$ 또는 $x = 3$\n\n**3단계: 극대/극소 판정 (2차 도함수 이용 또는 부호 변화)**\n\n$$f''(x) = 6x - 12$$\n\n- $x = 1$일 때: $f''(1) = 6(1) - 12 = -6 < 0$ → **극댓값**\n- $x = 3$일 때: $f''(3) = 6(3) - 12 = 6 > 0$ → **극솟값**\n\n**4단계: 극댓값과 극솟값 계산**\n\n$x = 1$에서의 극댓값:\n$$f(1) = 1^3 - 6(1)^2 + 9(1) + 2 = 1 - 6 + 9 + 2 = 6$$\n\n$x = 3$에서의 극솟값:\n$$f(3) = 3^3 - 6(3)^2 + 9(3) + 2 = 27 - 54 + 27 + 2 = 2$$\n\n**5단계: 극댓값과 극솟값의 차**\n\n$$\\text{극댓값} - \\text{극솟값} = 6 - 2 = 4$$\n\n**[정답 확인]**\n\n극댓값 6에서 극솟값 2를 뺀 값이 4이므로 정답이 맞습니다.\n\n**[오답 분석]**\n\n선택지가 없으므로 생략합니다.\n\n**[핵심 포인트]**\n\n1. 극값을 구할 때는 반드시 $f'(x) = 0$을 풀고 2차 도함수로 극대/극소를 판정해야 합니다.\n2. 극댓값과 극솟값의 \"차\"는 큰 값에서 작은 값을 뺀 양수이므로, 극댓값이 극솟값보다 크다는 것을 먼저 확인하는 것이 중요합니다.",
