    "problem": "둘레의 길이가 $20$인 직사각형의 넓이의 최댓값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 25,
    "explanation": "**[핵심 개념]**\n직사각형의 둘레와 넓이의 관계를 이용한 최댓값 문제입니다. 주어진 둘레 조건에서 넓이를 최대화하려면 산술-기하평균 부등식(AM-GM 부등식) 또는 미분을 활용할 수 있습니다. 일반적으로 둘레가 일정할 때, 정사각형일 때 넓이가 최대입니다.\n\n**[풀이]**\n\n**1단계: 변수 설정**\n직사각형의 가로 길이를 $a$, 세로 길이를 $b$라고 하겠습니다. (단, $a > 0, b > 0$)\n\n**2단계: 둘레 조건식**\n둘레의 길이가 20이므로:\n$$2a + 2b = 20$$\n$$a + b = 10$$\n$$b = 10 - a$$\n\n**3단계: 넓이를 $a$에 대한 함수로 표현**\n직사각형의 넓이는:\n$$S = a \\cdot b = a(10-a) = 10a - a^2$$\n\n**4단계: 최댓값 구하기 (미분 방법)**\n$S$를 $a$에 대해 미분하면:\n$$\\frac{dS}{da} = 10 - 2a$$\n\n최댓값을 구하기 위해 $\\frac{dS}{da} = 0$으로 놓으면:\n$$10 - 2a = 0$$\n$$a = 5$$\n\n$\\frac{d^2S}{da^2} = -2 < 0$이므로 $a = 5$에서 최댓값을 갖습니다.\n\n**5단계: 최댓값 계산**\n$a = 5$일 때, $b = 10 - 5 = 5$\n\n따라서 최대 넓이는:\n$$S_{\\max} = 5 \\times 5 = 25$$\n\n**[정답 확인]**\n둘레가 20일 때 가로와 세로의 합이 10이므로, 두 수의 합이 고정되면 두 수가 같을 때(정사각형일 때) 곱이 최대가 되며, 그 최댓값은 25입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답:\n- **20**: 둘레의 길이를 넓이로 착각한 경우\n- **50**: $10 \\times 5$로 계산하여 대칭성을 고려하지 못한 경우\n- **100**: $20^2$을 계산한 경우 (개념 오류)\n\n**[핵심 포인트]**\n- 둘레가 일정할 때는 **정사각형일 때 넓이가 최대**입니다.\n- 산술-기하평균 부등식: $\\frac{a+b}{2} \\geq \\sqrt{ab}$를 적용하면 $5 \\geq \\sqrt{ab}$이므로 $ab \\leq 25$입니다.",
