    "problem": "닫힌구간 $[0,\\, 2]$에서 함수 $f(x) = 2x^3 - 9x^2 + 12x$의 최댓값은?",
    "answerType": "choice",
    "choices": [
      "① 4",
      "② 5",
      "③ 8",
      "④ 12",
      "⑤ 16"
    ],
    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n닫힌구간에서 함수의 최댓값을 구하기 위해서는 다음 세 곳을 모두 확인해야 합니다:\n1. 구간 내 극값을 갖는 점들 (도함수 = 0인 점)\n2. 구간의 왼쪽 끝점\n3. 구간의 오른쪽 끝점\n\n그리고 이 모든 함숫값을 비교하여 가장 큰 값이 최댓값입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = 2x^3 - 9x^2 + 12x$에서\n\n$$f'(x) = 6x^2 - 18x + 12$$\n\n**Step 2: 극값을 갖는 점 찾기**\n\n$f'(x) = 0$인 점을 구합니다.\n\n$$6x^2 - 18x + 12 = 0$$\n$$x^2 - 3x + 2 = 0$$\n$$(x-1)(x-2) = 0$$\n\n따라서 $x = 1$ 또는 $x = 2$\n\n이 두 점 모두 닫힌구간 $[0, 2]$에 포함됩니다.\n\n**Step 3: 후보 지점들의 함숫값 계산**\n\n구간의 끝점과 극값을 갖는 점에서 함숫값을 구합니다.\n\n$x = 0$일 때:\n$$f(0) = 2(0)^3 - 9(0)^2 + 12(0) = 0$$\n\n$x = 1$일 때:\n$$f(1) = 2(1)^3 - 9(1)^2 + 12(1) = 2 - 9 + 12 = 5$$\n\n$x = 2$일 때:\n$$f(2) = 2(2)^3 - 9(2)^2 + 12(2) = 16 - 36 + 24 = 4$$\n\n**Step 4: 최댓값 결정**\n\n$$f(0) = 0, \\quad f(1) = 5, \\quad f(2) = 4$$\n\n비교하면 최댓값은 $\\boxed{5}$입니다.\n\n**[정답 확인]**\n\n닫힌구간 $[0, 2]$에서 함수값을 모두 비교한 결과 $f(1) = 5$가 최댓값입니다.\n\n**[오답 분석]**\n\n- ① 4: $f(2) = 4$이지만 이는 최댓값이 아닙니다.\n- ③ 8: 계산 오류로 발생하는 선택지\n- ④ 12: 계수를 잘못 계산하면 나올 수 있는 값\n- ⑤ 16: $2x^3$의 계수만 고려한 오류\n\n**[핵심 포인트]**\n\n닫힌구간에서의 최댓값/최솟값은 반드시 구간 내의 모든 극값과 양 끝점의 함숫값을 모두 비교해야 합니다. 극값만 구하고 끝점을 확인하지 않으면 틀립니다.",
