    "problem": "넓이가 $16$인 직사각형의 둘레의 길이의 최솟값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 16,
    "explanation": "**[핵심 개념]**\n직사각형의 넓이와 둘레의 관계를 다루는 문제입니다. 가로의 길이를 $x$, 세로의 길이를 $y$라 하면:\n- 넓이: $xy = 16$ (주어진 조건)\n- 둘레: $L = 2(x+y)$ (최솟값을 구해야 함)\n\n이는 제약 조건 하에서 최솟값을 구하는 문제로, **산술-기하 평균 부등식** 또는 **미분**을 이용하여 해결합니다.\n\n**[풀이]**\n\n**방법 1: 산술-기하 평균 부등식 이용**\n\n$xy = 16$일 때, 두 양수 $x$와 $y$에 대해 산술-기하 평균 부등식을 적용하면:\n\n$$\\frac{x+y}{2} \\geq \\sqrt{xy}$$\n\n양변에 2를 곱하면:\n\n$$x + y \\geq 2\\sqrt{xy} = 2\\sqrt{16} = 2 \\times 4 = 8$$\n\n따라서 둘레는:\n\n$$L = 2(x+y) \\geq 2 \\times 8 = 16$$\n\n등호는 $x = y$일 때 성립하므로, $x = y = 4$일 때 최솟값을 가집니다.\n\n**방법 2: 미분을 이용한 풀이**\n\n$xy = 16$에서 $y = \\frac{16}{x}$\n\n둘레 $L = 2(x+y) = 2\\left(x + \\frac{16}{x}\\right)$\n\n$\\frac{dL}{dx} = 2\\left(1 - \\frac{16}{x^2}\\right)$\n\n최솟값을 구하기 위해 $\\frac{dL}{dx} = 0$:\n\n$$1 - \\frac{16}{x^2} = 0$$\n\n$$x^2 = 16$$\n\n$$x = 4$$ (양수이므로)\n\n$x = 4$일 때 $y = \\frac{16}{4} = 4$\n\n따라서 둘레의 최솟값은: $L = 2(4+4) = 16$\n\n**[정답 확인]**\n직사각형의 넓이가 고정되어 있을 때, 둘레가 최소가 되는 경우는 정사각형(가로와 세로의 길이가 같을 때)이며, 이때 둘레는 16입니다.\n\n**[오답 분석]**\n선택지가 없어 오답 분석은 생략되지만, 흔한 오류는:\n- 넓이 16을 둘레로 착각하는 경우\n- 계산 과정에서 실수하여 8, 12 등의 값을 얻는 경우\n- 최댓값을 구하는 것으로 착각하는 경우\n\n**[핵심 포인트]**\n**일정한 넓이를 가진 직사각형의 둘레는 정사각형일 때 최소**입니다. 즉, $xy=$상수일 때 $x+y$의 최솟값은 $x=y$에서 달성되며, 이는 산술-기하 평균 부등식으로 항상 성립합니다.",
