    "answer": 0,
    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값 후보를 찾고, 2차 도함수 또는 부호 변화를 이용해 극대/극소를 판별합니다. 극솟값은 함수가 극소점에서 갖는 함숫값입니다.\n\n**[풀이]**\n\n**1단계: 1차 도함수 구하기**\n$$f(x) = x^4 - 8x^2 + 3$$\n$$f'(x) = 4x^3 - 16x = 4x(x^2 - 4) = 4x(x-2)(x+2)$$\n\n**2단계: 극값 후보점 찾기**\n$$f'(x) = 0 \\Rightarrow x = -2, 0, 2$$\n\n**3단계: 2차 도함수를 이용한 극대/극소 판별**\n$$f''(x) = 12x^2 - 16$$\n\n- $x = -2$일 때: $f''(-2) = 12(4) - 16 = 48 - 16 = 32 > 0$ → 극소\n- $x = 0$일 때: $f''(0) = -16 < 0$ → 극대\n- $x = 2$일 때: $f''(2) = 12(4) - 16 = 32 > 0$ → 극소\n\n**4단계: 극솟값 계산**\n\n$x = -2$에서의 극솟값:\n$$f(-2) = (-2)^4 - 8(-2)^2 + 3 = 16 - 32 + 3 = -13$$\n\n$x = 2$에서의 극솟값:\n$$f(2) = (2)^4 - 8(2)^2 + 3 = 16 - 32 + 3 = -13$$\n\n**5단계: 극솟값의 합**\n$$-13 + (-13) = -26$$\n\n**[정답 확인]**\n극솟값은 $x = -2$와 $x = 2$에서 각각 $-13$이므로, 모두 더한 값은 $-26$입니다.\n\n**[오답 분석]**\n- ② -13: 극솟값 하나만 계산한 경우\n- ③ 0: 극값이 0이라고 잘못 생각한 경우\n- ④ 3: 함수의 상수항만 선택한 경우\n- ⑤ 6: 극솟값의 절댓값을 더한 경우\n\n**[핵심 포인트]**\n4차 함수는 최대 3개의 극값을 가질 수 있으며, 이 문제에서는 극소가 2개입니다. 극값을 모두 더할 때는 **극값의 개수를 정확히 파악**하고 각각의 함숫값을 정확히 계산하는 것이 중요합니다.",
