    "explanation": "**[핵심 개념]**\n함수의 최솟값을 구하는 방법은 미분을 이용하는 것입니다. 양수 $x$에 대해 $f(x)$를 $x$로 미분하여 $f'(x) = 0$이 되는 점을 찾고, 그 점에서의 함수값을 계산합니다. 또한 산술-기하 평균 부등식을 활용하여 최솟값을 구할 수도 있습니다.\n\n**[풀이]**\n\n**방법 1: 미분을 이용한 풀이**\n\n주어진 함수는 $f(x) = x^2 + \\frac{2}{x}$ (단, $x > 0$)\n\n$f(x)$를 $x$로 미분하면:\n$$f'(x) = 2x - \\frac{2}{x^2}$$\n\n최솟값을 구하기 위해 $f'(x) = 0$으로 놓으면:\n$$2x - \\frac{2}{x^2} = 0$$\n\n$$2x = \\frac{2}{x^2}$$\n\n$$x^3 = 1$$\n\n$$x = 1$$\n\n$x = 1$에서 최솟값을 가지는지 확인하기 위해 이계 미분:\n$$f''(x) = 2 + \\frac{4}{x^3}$$\n\n$x = 1$일 때, $f''(1) = 2 + 4 = 6 > 0$ 이므로 $x = 1$에서 극소값(최솟값)을 가집니다.\n\n따라서 최솟값은:\n$$f(1) = 1^2 + \\frac{2}{1} = 1 + 2 = 3$$\n\n**방법 2: 산술-기하 평균 부등식**\n\n산술-기하 평균 부등식에 의해:\n$$\\frac{x^2 + \\frac{1}{x} + \\frac{1}{x}}{3} \\geq \\sqrt[3]{x^2 \\cdot \\frac{1}{x} \\cdot \\frac{1}{x}}$$\n\n$$\\frac{x^2 + \\frac{2}{x}}{3} \\geq \\sqrt[3]{1} = 1$$\n\n$$x^2 + \\frac{2}{x} \\geq 3$$\n\n등호 조건: $x^2 = \\frac{1}{x}$일 때, 즉 $x = 1$일 때 성립합니다.\n\n**[정답 확인]**\n$x = 1$을 $f(x) = x^2 + \\frac{2}{x}$에 대입하면 $f(1) = 1 + 2 = 3$이므로 정답은 ③입니다.\n\n**[오답 분석]**\n- ① 1: $f(x)$에서 $\\frac{2}{x}$ 항만 고려한 오답\n- ② 2: $x^2$ 항과 $\\frac{2}{x}$ 항을 잘못 계산한 오답\n- ④ 4: 계산 실수로 인한 오답\n- ⑤ 5: 부등식 부등호 방향을 잘못 이해한 오답\n\n**[핵심 포인트]**\n1. 양수 범위에서 함수의 최솟값은 $f'(x) = 0$이 되는 점에서 찾으면 됩니다.\n2. 산술-기하 평균 부등식을 적용할 때는 등호 조건이 성립하는 $x$값을 반드시 확인해야 합니다.",
