    "_type": "max_min",
    "type": "최대최소",
    "problem": "부피가 $16\\pi$인 원기둥의 겉넓이를 최소로 하는 밑면의 반지름을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n원기둥의 부피와 겉넓이 공식, 그리고 제약 조건 하에서 함수의 최솟값을 구하는 미분 활용입니다.\n\n원기둥에서 밑면의 반지름을 $r$, 높이를 $h$라 하면:\n- 부피: $V = \\pi r^2 h$\n- 겉넓이: $S = 2\\pi r^2 + 2\\pi rh$ (윗면과 밑면의 넓이 + 옆면의 넓이)\n\n**[풀이]**\n\n**Step 1: 부피 조건으로부터 높이를 반지름으로 표현**\n\n부피가 $16\\pi$이므로:\n$$\\pi r^2 h = 16\\pi$$\n$$h = \\frac{16}{r^2}$$\n\n**Step 2: 겉넓이를 반지름만의 함수로 표현**\n\n겉넓이 공식에 $h = \\frac{16}{r^2}$를 대입합니다:\n$$S(r) = 2\\pi r^2 + 2\\pi r \\cdot \\frac{16}{r^2}$$\n$$S(r) = 2\\pi r^2 + \\frac{32\\pi}{r}$$\n\n**Step 3: 최솟값을 구하기 위해 미분**\n\n$r > 0$에서 $S(r)$의 최솟값을 구하기 위해 도함수를 구합니다:\n$$S'(r) = 4\\pi r - \\frac{32\\pi}{r^2}$$\n\n**Step 4: 극값 찾기**\n\n$S'(r) = 0$일 때:\n$$4\\pi r - \\frac{32\\pi}{r^2} = 0$$\n$$4\\pi r = \\frac{32\\pi}{r^2}$$\n$$4r^3 = 32$$\n$$r^3 = 8$$\n$$r = 2$$\n\n**Step 5: 최솟값 확인**\n\n2차 도함수를 구합니다:\n$$S''(r) = 4\\pi + \\frac{64\\pi}{r^3}$$\n\n$r = 2$일 때:\n$$S''(2) = 4\\pi + \\frac{64\\pi}{8} = 4\\pi + 8\\pi = 12\\pi > 0$$\n\n2차 도함수가 양수이므로 $r = 2$에서 최솟값을 가집니다.\n\n**[정답 확인]**\n\n$r = 2$일 때 $h = \\frac{16}{4} = 4$이므로 겉넓이는 $S = 2\\pi(4) + 2\\pi(2)(4) = 8\\pi + 16\\pi = 24\\pi$로 최소값을 갖습니다.\n\n**[오답 분석]**\n\n객관식이 없으므로 해당 사항 없음\n\n**[핵심 포인트]**\n\n부피가 일정할 때 겉넓이를 최소화하는 문제는 제약 조건을 이용해 변수를 줄인 후 미분하는 전형적인 최적화 문제입니다. 미분 후 도함수가 0이 되는 점에서 극값을 가지며, 2차 도함수로 최댓값/최솟값을 판단합니다.",
