    "answer": 0,
    "explanation": "**[핵심 개념]**\n극값을 구하기 위해서는 먼저 도함수를 구하고 $f'(x) = 0$이 되는 점을 찾아야 합니다. 도함수의 부호 변화로 극댓값과 극솟값을 판별할 수 있습니다. 극댓값에서 극솟값으로 변할 때 $f'(x)$는 양에서 음으로 변하고, 극솟값에서 극댓값으로 변할 때는 음에서 양으로 변합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 3x^2 - 9x + a$$\n$$f'(x) = 3x^2 - 6x - 9 = 3(x^2 - 2x - 3) = 3(x-3)(x+1)$$\n\n**2단계: 극값을 갖는 점 찾기**\n$f'(x) = 0$에서 $x = -1$ 또는 $x = 3$\n\n**3단계: 극값의 종류 판별**\n- $x < -1$: $f'(x) = 3(x-3)(x+1) > 0$ (증가)\n- $-1 < x < 3$: $f'(x) = 3(x-3)(x+1) < 0$ (감소)\n- $x > 3$: $f'(x) = 3(x-3)(x+1) > 0$ (증가)\n\n따라서 $x = -1$에서 극댓값, $x = 3$에서 극솟값을 가집니다.\n\n**4단계: 극댓값을 이용하여 $a$ 구하기**\n$$f(-1) = (-1)^3 - 3(-1)^2 - 9(-1) + a = -1 - 3 + 9 + a = 5 + a$$\n\n극댓값이 $20$이므로:\n$$5 + a = 20$$\n$$a = 15$$\n\n**5단계: 극솟값 구하기**\n$$f(3) = 3^3 - 3(3)^2 - 9(3) + 15$$\n$$= 27 - 27 - 27 + 15$$\n$$= -12$$\n\n**[정답 확인]**\n$f'(x) = 0$의 근이 $x = -1, 3$이고, $x = -1$에서 극댓값 20을 가지므로 $a = 15$이며, $x = 3$에서의 함수값은 $-12$입니다.\n\n**[오답 분석]**\n- ② -7: $a$값을 잘못 구했을 때 나오는 값\n- ③ 0: 극값의 위치를 잘못 파악하거나 계산 실수로 발생\n- ④ 7: 극댓값과 극솟값을 혼동하거나 $a$ 값을 잘못 구한 경우\n- ⑤ 12: 극솟값의 절댓값을 선택한 오류\n\n**[핵심 포인트]**\n3차 함수에서 극값 문제는 ① 도함수를 구해 극값의 위치 찾기 → ② 주어진 극값으로 상수 구하기 → ③ 나머지 극값 계산하기의 순서로 진행합니다.",
