    "problem": "닫힌구간 $[-1,\\, 3]$에서 함수 $f(x) = (x^2 - 4)^2$의 최솟값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n닫힌구간에서 함수의 최솟값을 구하기 위해서는:\n1. 함수의 도함수를 구하여 극값(극대, 극소)을 찾기\n2. 극값과 구간의 양 끝점에서의 함수값을 모두 계산\n3. 이 중 가장 작은 값이 최솟값\n\n**[풀이]**\n\n$f(x) = (x^2 - 4)^2$의 최솟값을 $[-1, 3]$에서 구합니다.\n\n**Step 1: 도함수 구하기**\n\n$$f'(x) = 2(x^2 - 4) \\cdot 2x = 4x(x^2 - 4)$$\n\n**Step 2: 극값 찾기**\n\n$f'(x) = 0$일 때:\n$$4x(x^2 - 4) = 0$$\n$$x = 0 \\text{ 또는 } x^2 = 4$$\n$$x = 0, 2, -2$$\n\n주어진 구간 $[-1, 3]$에 포함되는 극값:\n- $x = 0$ ✓\n- $x = 2$ ✓\n- $x = -2$ ✗ (구간 밖)\n\n**Step 3: 함수값 계산**\n\n극값과 구간 끝점에서의 함수값:\n\n- $f(-1) = ((-1)^2 - 4)^2 = (1 - 4)^2 = (-3)^2 = 9$\n\n- $f(0) = (0^2 - 4)^2 = (-4)^2 = 16$\n\n- $f(2) = (2^2 - 4)^2 = (4 - 4)^2 = 0^2 = 0$\n\n- $f(3) = (3^2 - 4)^2 = (9 - 4)^2 = 5^2 = 25$\n\n**Step 4: 최솟값 결정**\n\n$$\\{9, 16, 0, 25\\} \\text{ 중 최솟값} = 0$$\n\n**[정답 확인]**\n\n$x = 2$일 때 $x^2 = 4$이므로 $(x^2 - 4)^2 = 0^2 = 0$이 되며, 이것이 구간 내에서 가장 작은 값입니다.\n\n**[오답 분석]**\n\n선택지가 주어지지 않았으므로, 흔한 오답들:\n- **9**: $x = -1$에서의 함수값을 최솟값으로 착각\n- **16**: $x = 0$에서의 함수값을 최솟값으로 착각\n- **25**: $x = 3$에서의 함수값을 최솟값으로 착각\n\n**[핵심 포인트]**\n\n극값이 0이 되는 경우를 놓치지 말 것. $(x^2 - 4)^2 \\geq 0$이므로 $x^2 = 4$, 즉 $x = \\pm 2$에서 최솟값이 0이 될 수 있다는 것을 빨리 인식하는 것이 중요합니다.",
