    "type": "방정식부등식",
    "problem": "방정식 $x^2 - 4x + 3 = 0$의 두 근의 합을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n이차방정식 $ax^2 + bx + c = 0$의 두 근을 $\\alpha, \\beta$라 할 때, 비에타의 정리(Vieta's formula)에 의해 두 근의 합은 $\\alpha + \\beta = -\\frac{b}{a}$입니다. 이를 이용하면 근의 공식을 사용하지 않고도 두 근의 합을 구할 수 있습니다.\n\n**[풀이]**\n주어진 방정식: $x^2 - 4x + 3 = 0$\n\n이 방정식을 표준형 $ax^2 + bx + c = 0$과 비교하면:\n- $a = 1$\n- $b = -4$\n- $c = 3$\n\n비에타의 정리를 적용하면, 두 근의 합은:\n$$\\alpha + \\beta = -\\frac{b}{a} = -\\frac{(-4)}{1} = 4$$\n\n**[검증 (인수분해를 통한 확인)]**\n$x^2 - 4x + 3 = 0$을 인수분해하면:\n$$(x - 1)(x - 3) = 0$$\n\n따라서 두 근은 $x = 1, 3$이고, 두 근의 합은 $1 + 3 = 4$\n\n**[정답 확인]**\n비에타의 정리에 의해 두 근의 합은 $-\\frac{b}{a} = 4$이며, 직접 인수분해를 통해 확인해도 $1 + 3 = 4$이므로 정답입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은:\n- **-4**: $b$ 값을 그대로 사용한 경우 (부호 실수)\n- **3**: 상수항 $c$ 값을 선택한 경우\n- **-3**: 두 근의 곱과 혼동한 경우 (실제로 두 근의 곱은 $1 \\times 3 = 3$)\n\n**[핵심 포인트]**\n이차방정식 $ax^2 + bx + c = 0$에서 **두 근의 합 = $-\\frac{b}{a}$**, **두 근의 곱 = $\\frac{c}{a}$**를 항상 기억하세요. 비에타의 정리를 이용하면 근을 구하지 않고도 근과 관련된 값을 빠르게 구할 수 있습니다.",
