    "explanation": "**[핵심 개념]**\n\n이차부등식을 풀기 위해서는 먼저 이차식을 인수분해하여 근을 찾은 후, 포물선의 개형을 이용해 부등호 방향에 따른 해의 범위를 결정합니다. $ax^2 + bx + c > 0$ (단, $a > 0$)의 해는 포물선이 $x$축 위에 있는 구간입니다.\n\n**[풀이]**\n\n**1단계: 이차식을 인수분해**\n\n$x^2 - 5x + 6 > 0$\n\n곱해서 6, 더해서 -5가 되는 두 수는 -2와 -3입니다.\n\n$$x^2 - 5x + 6 = (x-2)(x-3)$$\n\n따라서 부등식은:\n$$(x-2)(x-3) > 0$$\n\n**2단계: 근 찾기**\n\n$(x-2)(x-3) = 0$의 근은 $x = 2, x = 3$\n\n**3단계: 부호 판정**\n\n수직선에 근 2와 3을 표시하여 각 구간에서 $(x-2)(x-3)$의 부호를 확인합니다.\n\n- $x < 2$일 때: $(x-2) < 0$, $(x-3) < 0$ → $(x-2)(x-3) > 0$ ✓\n- $2 < x < 3$일 때: $(x-2) > 0$, $(x-3) < 0$ → $(x-2)(x-3) < 0$ ✗\n- $x > 3$일 때: $(x-2) > 0$, $(x-3) > 0$ → $(x-2)(x-3) > 0$ ✓\n\n**4단계: 해 결정**\n\n$$x < 2 \\text{ 또는 } x > 3$$\n\n**[정답 확인]**\n\n$(x-2)(x-3) > 0$은 두 인수가 같은 부호일 때 성립하므로, $x < 2$ 또는 $x > 3$이 정답입니다.\n\n**[오답 분석]**\n\n- ① $2 < x < 3$: 이 구간에서 $(x-2)(x-3) < 0$이므로 부등식을 만족하지 않습니다.\n- ③ $x < -3$ 또는 $x > -2$: 인수분해를 잘못 적용한 경우입니다.\n- ④ $-3 < x < -2$: 부호 판정을 반대로 한 경우입니다.\n- ⑤ 모든 실수: 근이 존재하므로 모든 실수는 아닙니다.\n\n**[핵심 포인트]**\n\n이차부등식 $> 0$의 해는 **두 근의 바깥쪽** 구간입니다. 수직선에 근을 표시하고 각 구간에서 부호를 확인하는 습관이 매우 중요합니다.",
