    "answer": 0,
    "explanation": "**[핵심 개념]**\n3차 방정식의 근과 계수의 관계를 이용하거나, 직접 인수분해하여 모든 근을 구한 후 곱을 계산할 수 있습니다. 특히 근 중 하나가 0인 경우, 모든 근의 곱은 0이 됩니다.\n\n**[풀이]**\n\n주어진 방정식: $x^3 - 4x = 0$\n\n**Step 1: 인수분해**\n$$x^3 - 4x = 0$$\n$$x(x^2 - 4) = 0$$\n$$x(x-2)(x+2) = 0$$\n\n**Step 2: 모든 실근 구하기**\n위 식으로부터:\n- $x = 0$\n- $x - 2 = 0$ → $x = 2$\n- $x + 2 = 0$ → $x = -2$\n\n따라서 모든 실근은 $0, 2, -2$입니다.\n\n**Step 3: 모든 실근의 곱 계산**\n$$0 \\times 2 \\times (-2) = 0$$\n\n**[정답 확인]**\n3차 방정식 $x^3 - 4x = 0$의 근과 계수의 관계에서 상수항이 0이므로, 근의 곱은 항상 0입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 만약 다른 숫자를 선택한다면:\n- 근 중 하나가 명백히 0이므로, 0이 아닌 답은 틀렸습니다.\n- 예: \"4\"를 선택하면 $2 \\times (-2) = -4$만 계산하여 0을 놓친 경우입니다.\n\n**[핵심 포인트]**\n방정식을 인수분해할 때 **공통인수를 빼먹지 말 것**. 한 근이 0이면 모든 근의 곱은 자동으로 0입니다.",
