    "answer": 2,
    "explanation": "**[핵심 개념]**\n이차부등식을 풀기 위해서는 먼저 이차방정식의 근을 구한 후, 이차함수의 부호를 판단해야 합니다. $ax^2 + bx + c \\leq 0$ 형태에서 $a > 0$일 때, 근과 근 사이의 $x$ 값들이 부등식을 만족합니다. 또한 정수의 개수를 구할 때는 구간에 포함된 모든 정수를 세어야 합니다.\n\n**[풀이]**\n\n**Step 1: 이차방정식의 근 구하기**\n\n$x^2 - 2x - 3 = 0$을 인수분해합니다.\n\n$$x^2 - 2x - 3 = (x-3)(x+1) = 0$$\n\n따라서 $x = 3$ 또는 $x = -1$\n\n**Step 2: 부등식의 해 구하기**\n\n이차함수 $f(x) = x^2 - 2x - 3$은 이차항의 계수가 양수이므로 아래로 볼록한 포물선입니다.\n\n따라서 $f(x) \\leq 0$을 만족하는 $x$의 범위는 두 근 사이입니다.\n\n$$-1 \\leq x \\leq 3$$\n\n**Step 3: 이 범위에 속하는 정수 찾기**\n\n$-1 \\leq x \\leq 3$을 만족하는 정수는:\n\n$$x = -1, 0, 1, 2, 3$$\n\n**Step 4: 정수의 개수 세기**\n\n정수의 개수는 **5개**입니다.\n\n**[정답 확인]**\n$x^2 - 2x - 3 = (x-3)(x+1) \\leq 0$의 해는 $-1 \\leq x \\leq 3$이고, 이 범위의 정수는 $-1, 0, 1, 2, 3$으로 총 5개입니다.\n\n**[오답 분석]**\n- ① 3개: 양 끝점을 제외하고 중간 정수($0, 1, 2$)만 센 경우\n- ② 4개: 한쪽 끝점만 포함하지 않은 경우\n- ④ 6개: 부등호 조건을 $-1 < x < 3$으로 잘못 이해한 경우\n- ⑤ 7개: 범위를 잘못 구한 경우\n\n**[핵심 포인트]**\n1. 부등식 $f(x) \\leq 0$은 등호를 포함하므로 경계값도 포함됨을 명시적으로 확인\n2. 폐구간 $[a, b]$의 정수 개수는 $b - a + 1$로 계산할 수 있음 (여기서 $3 - (-1) + 1 = 5$)",
