    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n비에타의 정리(Vieta's formulas)는 다항식의 근과 계수의 관계를 나타냅니다. 3차 방정식 $ax^3 + bx^2 + cx + d = 0$의 세 근을 $\\alpha, \\beta, \\gamma$라 할 때, 세 근의 합은 $\\alpha + \\beta + \\gamma = -\\frac{b}{a}$입니다.\n\n**[풀이]**\n주어진 방정식: $x^3 - 7x + 6 = 0$\n\n이를 표준형으로 정렬하면:\n$$x^3 + 0 \\cdot x^2 - 7x + 6 = 0$$\n\n비에타의 정리를 적용합니다. 여기서:\n- 3차 항의 계수 $a = 1$\n- 2차 항의 계수 $b = 0$\n- 1차 항의 계수 $c = -7$\n- 상수항 $d = 6$\n\n세 근을 $\\alpha, \\beta, \\gamma$라 하면, 근과 계수의 관계에 의해:\n$$\\alpha + \\beta + \\gamma = -\\frac{b}{a} = -\\frac{0}{1} = 0$$\n\n**[정답 확인]**\n3차 방정식에서 2차 항의 계수가 0이므로 비에타의 정리에 의해 세 근의 합은 항상 0입니다.\n\n**[오답 분석]**\n객관식 선지가 제시되지 않았으나, 다음과 같은 오류가 발생할 수 있습니다:\n- 1차 항의 계수인 $-7$을 잘못 사용하는 경우: 7이나 -7 등의 오답\n- 상수항 6을 사용하는 경우: 오답\n- 근의 공식으로 직접 계산하려는 경우: 계산 복잡도 증가\n\n**[핵심 포인트]**\n3차 방정식 $x^3 + bx^2 + cx + d = 0$의 세 근의 합은 $-b$이다. 이 문제에서 $x^2$ 항이 없으므로 (계수가 0) 세 근의 합은 즉시 0임을 알 수 있다.",
