    "problem": "방정식 $x^3 - 6x^2 + 11x - 6 = 0$의 세 근을 $\\alpha, \\beta, \\gamma$라 할 때, $\\alpha^2 + \\beta^2 + \\gamma^2$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 14,
    "explanation": "**[핵심 개념]**\n\n비에타의 정리(Vieta's formulas)는 다항식의 근과 계수의 관계를 나타냅니다. 3차 방정식 $x^3 + ax^2 + bx + c = 0$의 세 근을 $\\alpha, \\beta, \\gamma$라 할 때:\n- $\\alpha + \\beta + \\gamma = -a$\n- $\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha = b$\n- $\\alpha\\beta\\gamma = -c$\n\n또한 $(a+b+c)^2 = a^2 + b^2 + c^2 + 2(ab + bc + ca)$를 이용하여 제곱의 합을 구할 수 있습니다.\n\n**[풀이]**\n\n주어진 방정식: $x^3 - 6x^2 + 11x - 6 = 0$\n\n**Step 1: 비에타의 정리 적용**\n\n방정식을 $x^3 + (-6)x^2 + 11x + (-6) = 0$ 형태로 보면:\n- $\\alpha + \\beta + \\gamma = 6$\n- $\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha = 11$\n- $\\alpha\\beta\\gamma = 6$\n\n**Step 2: 제곱의 합 공식 사용**\n\n$$(\\alpha + \\beta + \\gamma)^2 = \\alpha^2 + \\beta^2 + \\gamma^2 + 2(\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha)$$\n\n**Step 3: 값 대입**\n\n$$6^2 = \\alpha^2 + \\beta^2 + \\gamma^2 + 2(11)$$\n\n$$36 = \\alpha^2 + \\beta^2 + \\gamma^2 + 22$$\n\n$$\\alpha^2 + \\beta^2 + \\gamma^2 = 36 - 22 = 14$$\n\n**[정답 확인]**\n\n$\\alpha^2 + \\beta^2 + \\gamma^2 = 14$로, 주어진 정답과 일치합니다.\n\n**[오답 분석]**\n\n객관식 선지가 제시되지 않았으나, 일반적인 오답의 경우:\n- **12**: $(\\alpha + \\beta + \\gamma)^2 - 2(\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha) = 36 - 22 = 14$에서 덧셈과 뺄셈을 잘못한 경우\n- **26**: $36 + 2(11) = 58$을 계산하거나 다른 공식을 잘못 적용한 경우\n- **22**: $2(\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha)$만 계산한 경우\n\n**[핵심 포인트]**\n\n비에타의 정리로부터 근과 계수의 관계를 파악한 후, $(\\alpha + \\beta + \\gamma)^2 = \\alpha^2 + \\beta^2 + \\gamma^2 + 2(\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha)$ 공식을 적용하는 것이 핵심입니다.",
