    "answer": 1,
    "explanation": "**[핵심 개념]**\n이차방정식 $ax^2 + bx + c = 0$이 중근을 가지려면 판별식 $D = b^2 - 4ac = 0$이어야 합니다. 중근은 두 근이 같은 값인 경우로, 이때 근의 공식에서 $\\pm\\sqrt{D}$ 부분이 0이 되어 중근 $x = -\\frac{b}{2a}$를 가집니다.\n\n**[풀이]**\n주어진 이차방정식: $x^2 - (a+1)x + a = 0$\n\n이 방정식에서:\n- 이차항의 계수: $1$\n- 일차항의 계수: $-(a+1)$\n- 상수항: $a$\n\n**판별식 계산:**\n$$D = [-(a+1)]^2 - 4 \\cdot 1 \\cdot a$$\n\n$$D = (a+1)^2 - 4a$$\n\n$$D = a^2 + 2a + 1 - 4a$$\n\n$$D = a^2 - 2a + 1$$\n\n$$D = (a-1)^2$$\n\n**중근 조건 적용:**\n중근을 가지려면 $D = 0$이어야 하므로:\n$$(a-1)^2 = 0$$\n\n$$a - 1 = 0$$\n\n$$a = 1$$\n\n양수 조건을 확인하면 $a = 1 > 0$이므로 조건을 만족합니다.\n\n**[정답 확인]**\n$a = 1$을 원래 방정식에 대입하면 $x^2 - 2x + 1 = 0$, 즉 $(x-1)^2 = 0$이 되어 $x = 1$ (중근)을 가지므로 정답입니다.\n\n**[오답 분석]**\n- **① 0**: 음수가 아니지만 양수도 아니므로 조건에 맞지 않음\n- **③ 2**: $a = 2$일 때 $D = (2-1)^2 = 1 \\neq 0$이므로 중근을 가지지 않음\n- **④ 3**: $a = 3$일 때 $D = (3-1)^2 = 4 \\neq 0$이므로 중근을 가지지 않음\n- **⑤ 4**: $a = 4$일 때 $D = (4-1)^2 = 9 \\neq 0$이므로 중근을 가지지 않음\n\n**[핵심 포인트]**\n- 판별식이 완전제곱식 $(a-1)^2$ 형태로 인수분해되면, $D = 0$의 해는 $a = 1$ 하나입니다.\n- 양수 조건에서 $a = 1$만이 유일한 답입니다.",
