    "explanation": "**[핵심 개념]**\n부등식을 풀기 위해서는 각 인수의 부호를 분석해야 합니다. $(x-1)(x^2 + x + 1) > 0$에서 두 인수의 부호를 각각 조사합니다. 특히 이차식 $x^2 + x + 1$의 판별식을 확인하여 이 식이 항상 양수인지 음수인지를 판단하는 것이 중요합니다.\n\n**[풀이]**\n주어진 부등식: $(x-1)(x^2 + x + 1) > 0$\n\n**Step 1: 이차식의 부호 결정**\n$x^2 + x + 1$의 판별식을 구합니다:\n$$D = 1^2 - 4(1)(1) = 1 - 4 = -3 < 0$$\n\n판별식이 음수이고 최고차 계수가 양수(1 > 0)이므로, 모든 실수 $x$에 대해:\n$$x^2 + x + 1 > 0 \\text{ (항상 양수)}$$\n\n**Step 2: 부등식 단순화**\n$(x-1)(x^2 + x + 1) > 0$에서 $x^2 + x + 1 > 0$이 항상 성립하므로, 양수인 수로 양변을 나누어도 부등호 방향이 바뀌지 않습니다:\n$$(x-1) > 0$$\n\n**Step 3: 일차부등식 풀이**\n$$x - 1 > 0$$\n$$x > 1$$\n\n**[정답 확인]**\n$x^2 + x + 1$이 항상 양수이므로, 전체 곱이 양수가 되는 조건은 $(x-1) > 0$이어야 하며, 따라서 $x > 1$입니다.\n\n**[오답 분석]**\n- **②** $x < 1$: 이는 $(x-1) < 0$일 때이므로 부등식을 만족하지 않습니다.\n- **③** $x > -1$: 필요조건이지만 충분하지 않습니다. $-1 < x < 1$일 때는 $(x-1) < 0$이므로 부등식을 만족하지 않습니다.\n- **④** $x > 0$: 마찬가지로 $0 < x < 1$에서는 $(x-1) < 0$이므로 부등식을 만족하지 않습니다.\n- **⑤** 모든 실수: $x < 1$일 때는 $(x-1) < 0$이고 $x^2 + x + 1 > 0$이므로 곱이 음수가 되어 부등식을 만족하지 않습니다.\n\n**[핵심 포인트]**\n판별식이 음수인 이차식의 부호는 최고차 계수의 부호로 결정됩니다. 이 경우 $x^2 + x + 1 > 0$이 항상 성립하므로, 전체 부등식의 해는 일차인수 $(x-1)$의 부호에만 좌우됩니다.",
