    "explanation": "**[핵심 개념]**\n3차 함수의 근의 위치를 판정하는 문제입니다. 함수 $f(x) = x^3 - 3x + k$가 양의 근과 음의 근을 모두 가지려면, 양수 구간에서 한 번 이상 $x$축을 지나고 음수 구간에서도 한 번 이상 $x$축을 지나야 합니다. 이를 판정하기 위해 함수의 극값을 구하고 조건을 세웁니다.\n\n**[풀이]**\n\n**1단계: 함수의 극값 구하기**\n\n$f(x) = x^3 - 3x + k$라 하면\n\n$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$\n\n$f'(x) = 0$일 때, $x = -1$ 또는 $x = 1$\n\n**2단계: 극값 계산**\n\n$x = -1$에서: $f(-1) = (-1)^3 - 3(-1) + k = -1 + 3 + k = k + 2$ (극대값)\n\n$x = 1$에서: $f(1) = 1^3 - 3(1) + k = 1 - 3 + k = k - 2$ (극소값)\n\n**3단계: 양의 근과 음의 근을 모두 가지기 위한 조건**\n\n함수가 양의 근과 음의 근을 모두 가지려면:\n- $x < -1$에서 한 근, $-1 < x < 1$에서 한 근, $x > 1$에서 한 근을 가져야 합니다.\n\n이는 다음 두 조건을 동시에 만족해야 합니다:\n- **극대값 $\\geq 0$**: $f(-1) = k + 2 \\geq 0$ → $k \\geq -2$\n- **극소값 $\\leq 0$**: $f(1) = k - 2 \\leq 0$ → $k \\leq 2$\n\n이 두 조건이 동시에 만족되면:\n- $f(-1) \\geq 0$이고 $x \\to -\\infty$일 때 $f(x) \\to -\\infty$이므로, $x < -1$ 구간에서 한 근 존재\n- $f(1) \\leq 0$이고 $x \\to +\\infty$일 때 $f(x) \\to +\\infty$이므로, $x > 1$ 구간에서 한 근 존재\n- $-1 < x < 1$ 구간에서 극대값에서 극소값으로 감소하므로, 극대값 $\\geq 0$이고 극소값 $\\leq 0$이면 음의 근이 존재\n\n따라서: **$-2 \\leq k \\leq 2$**\n\n**[정답 확인]**\n3차 함수가 양의 근과 음의 근을 모두 가지려면 극대값이 0 이상이고 극소값이 0 이하여야 하므로, $-2 \\leq k \\leq 2$입니다.\n\n**[오답 분석]**\n\n① $-2 < k < 2$: 극값이 0을 포함하지 않으므로, $k = -2, 2$일 때 중근이 생기는 경우를 제외했지만, 이 경우에도 양의 근과 음의 근이 모두 존재합니다. 범위가 너무 좁습니다.\n\n② $k < -2$ 또는 $k > 2$: 극대값이 음수이거나 극소값이 양수인 경우로, 근의 개수 또는 위치가 조건을 만족하지 않습니다.\n\n③ 모든 실수: 예를 들어 $k = 3$일 때, $f(1) = -2 + 3 = 0$을 초과하므로 양수가 되어 양의 근만 존재할 수 있습니다.\n\n④ $k = 0$: 조건을 만족하지만, $k = -2$나 $k = 2$일 때도 조건을 만족합니다.\n\n**[핵심 포인트]**\n3차 함수가 특정 부호의 근을 모두 가지려면 극값의 부호를 확인하는 것이 핵심입니다. 극대값 $\\geq 0$이고 극소값 $\\leq 0$일 때, 양의 근과 음의 근이 모두 존재합니다.",
