    "answer": 0,
    "explanation": "**[핵심 개념]**\n부등식을 풀기 위해서는 먼저 등식 $f(x) = 0$의 근을 구한 후, 함수의 부호 변화를 분석해야 합니다. 3차 함수는 인수분해를 통해 근을 찾고, 각 근 주변에서 함수의 부호가 어떻게 변하는지 파악하는 것이 중요합니다.\n\n**[풀이]**\n\n**Step 1: 주어진 부등식의 좌변을 인수분해**\n\n$$x^3 - x^2 - x + 1 > 0$$\n\n항들을 묶어서 인수분해합니다:\n$$x^2(x-1) - 1(x-1) > 0$$\n$$(x^2 - 1)(x - 1) > 0$$\n$$(x-1)(x+1)(x-1) > 0$$\n$$(x+1)(x-1)^2 > 0$$\n\n**Step 2: 각 근 분석**\n\n- $x = -1$ (단순근, 1중근)\n- $x = 1$ (중근, 2중근)\n\n**Step 3: 부호 변화 분석**\n\n$(x+1)(x-1)^2 > 0$에서:\n\n- $x < -1$: $(x+1) < 0$, $(x-1)^2 > 0$ → 음수 × 양수 = **음수** ✗\n- $-1 < x < 1$: $(x+1) > 0$, $(x-1)^2 > 0$ → 양수 × 양수 = **양수** ✓\n- $x = 1$: $(x+1)(x-1)^2 = 2 \\cdot 0 = 0$ → **0** ✗\n- $x > 1$: $(x+1) > 0$, $(x-1)^2 > 0$ → 양수 × 양수 = **양수** ✓\n\n**Step 4: 해집합 표현**\n\n부등식의 해는 $-1 < x < 1$ 또는 $x > 1$입니다.\n\n이를 $x > a$ ($x \\neq b$) 형태로 나타내면:\n- $a = -1$ (하한값)\n- $b = 1$ (제외되는 점)\n\n따라서:\n$$a + b = -1 + 1 = 0$$\n\n**[정답 확인]**\n$(x+1)(x-1)^2 > 0$의 해는 $x > -1$ (단, $x \\neq 1$)이므로, $a = -1$, $b = 1$이고 $a + b = 0$입니다.\n\n**[오답 분석]**\n- 중근인 $x=1$을 단순근으로 취급하거나 놓치는 경우 오류 발생\n- $x = 1$에서 함수값이 0이 되지만 불등호 방향이 바뀌지 않으므로 반드시 제외 조건에 포함시켜야 함\n- 인수분해 과정에서 $(x-1)^2$을 제대로 파악하지 못하면 해집합을 잘못 구함\n\n**[핵심 포인트]**\n- 중근에서는 부호가 바뀌지 않으므로 부등식의 해에 포함되지 않습니다.\n- 형태 \"$x > a$ ($x \\neq b$)\"는 $a$보다 큰 모든 수 중에서 $b$만 제외한다는 의미입니다.",
