    "explanation": "**[핵심 개념]**\n이차방정식 $x^2 + bx + c = 0$이 서로 다른 두 양의 실근을 가지기 위한 조건은 다음 세 가지를 모두 만족해야 합니다.\n\n1. **판별식 조건**: $D > 0$ (서로 다른 두 실근)\n2. **근과 계수의 관계 - 합**: 두 근의 합 $> 0$\n3. **근과 계수의 관계 - 곱**: 두 근의 곱 $> 0$\n\n두 근을 $\\alpha, \\beta$라 하면, 근과 계수의 관계에 의해:\n- $\\alpha + \\beta = 2a$\n- $\\alpha \\beta = a + 6$\n\n**[풀이]**\n\n주어진 이차방정식: $x^2 - 2ax + a + 6 = 0$\n\n이 방정식이 서로 다른 두 양의 실근을 가지려면 다음 세 조건을 만족해야 합니다.\n\n**조건 1: 판별식 > 0 (서로 다른 두 실근)**\n\n$$D = (-2a)^2 - 4(1)(a+6) > 0$$\n$$4a^2 - 4a - 24 > 0$$\n$$a^2 - a - 6 > 0$$\n$$(a-3)(a+2) > 0$$\n\n따라서 $a < -2$ 또는 $a > 3$\n\n**조건 2: 두 근의 합 > 0 (양수 조건)**\n\n근과 계수의 관계에서:\n$$\\alpha + \\beta = 2a > 0$$\n$$a > 0$$\n\n**조건 3: 두 근의 곱 > 0 (양수 조건)**\n\n근과 계수의 관계에서:\n$$\\alpha \\beta = a + 6 > 0$$\n$$a > -6$$\n\n**세 조건의 교집합:**\n\n조건 1: $a < -2$ 또는 $a > 3$\n조건 2: $a > 0$\n조건 3: $a > -6$\n\n조건 2와 조건 3의 교집합은 $a > 0$입니다.\n\n이를 조건 1과 교집합하면:\n- $a < -2$와 $a > 0$은 교집합이 없음\n- $a > 3$과 $a > 0$의 교집합은 $a > 3$\n\n따라서 **$a > 3$**\n\n정수 $a$의 최솟값은 **$a = 4$**\n\n**[정답 확인]**\n$a = 4$일 때 세 조건을 모두 만족: $D = 16 - 16 - 24 = -8 < 0$... 아니, 다시 확인하면 $D = 64 - 40 = 24 > 0$ ✓, 근의 합 $= 8 > 0$ ✓, 근의 곱 $= 10 > 0$ ✓. $a = 3$일 때는 $D = 36 - 36 = 0$이므로 같은 근을 가져 조건 불만족.\n\n**[오답 분석]**\n- $a = 3$: 판별식이 0이 되어 중근을 가지므로 \"서로 다른 두 양의 실근\" 조건 위반\n- $a = 2$: $a > 3$ 조건을 만족하지 않음\n- $a = 1, 0, -1$ 등: 모두 $a > 3$ 조건 불만족\n\n**[핵심 포인트]**\n이차방정식이 \"서로 다른 두 양의 실근\"을 가질 조건은 **판별식 > 0, 근의 합 > 0, 근의 곱 > 0** 세 가지를 모두 확인해야 하며, 특히 각 부등식의 교집합을 정확히 구하는 것이 중요합니다.",
