    "_type": "equation_ineq",
    "type": "방정식부등식",
    "problem": "모든 실수 $x$에 대하여 $x^2 + ax + a + 5 > 0$이 성립하도록 하는 정수 $a$의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[핵심 개념]**\n이차함수가 모든 실수에서 양수가 되려면, 이차항의 계수가 양수이면서 동시에 판별식이 음수여야 합니다. 즉, $f(x) = ax^2 + bx + c$에서 $a > 0$이고 $D = b^2 - 4ac < 0$일 때 모든 실수 $x$에 대해 $f(x) > 0$입니다.\n\n**[풀이]**\n\n주어진 부등식: $x^2 + ax + a + 5 > 0$ (모든 실수 $x$에 대해 성립)\n\n**Step 1: 이차항의 계수 확인**\n$x^2$의 계수가 1 > 0이므로, 포물선이 위로 볼록합니다.\n\n**Step 2: 판별식 조건**\n모든 실수 $x$에 대해 부등식이 성립하려면 판별식 $D < 0$이어야 합니다.\n\n$$D = a^2 - 4(1)(a+5) < 0$$\n\n**Step 3: 판별식 전개**\n$$a^2 - 4a - 20 < 0$$\n\n**Step 4: 이차부등식 풀이**\n$a^2 - 4a - 20 = 0$의 근을 구합니다.\n\n$$a = \\frac{4 \\pm \\sqrt{16 + 80}}{2} = \\frac{4 \\pm \\sqrt{96}}{2} = \\frac{4 \\pm 4\\sqrt{6}}{2} = 2 \\pm 2\\sqrt{6}$$\n\n$\\sqrt{6} \\approx 2.449$이므로:\n- $2 - 2\\sqrt{6} \\approx 2 - 4.898 = -2.898$\n- $2 + 2\\sqrt{6} \\approx 2 + 4.898 = 6.898$\n\n따라서: $2 - 2\\sqrt{6} < a < 2 + 2\\sqrt{6}$\n\n즉, $-2.898 < a < 6.898$\n\n**Step 5: 정수 $a$ 구하기**\n이 범위에 속하는 정수는:\n$$a \\in \\{-2, -1, 0, 1, 2, 3, 4, 5, 6\\}$$\n\n개수를 세면: $-2, -1, 0, 1, 2, 3, 4, 5, 6$ → **9개**\n\n**[정답 확인]**\n판별식이 음수가 되는 정수 $a$의 범위 $-2.898 < a < 6.898$에 정확히 9개의 정수가 포함되므로 정답입니다.\n\n**[오답 분석]**\n- 8개: $a = -2$를 제외하고 계산한 경우\n- 10개: $a = -3$ 또는 $a = 7$을 포함하여 계산한 경우\n- 7개: 범위를 잘못 계산한 경우\n\n**[핵심 포인트]**\n- 모든 실수에서 이차식 > 0 ⟺ 판별식 < 0 (이차항의 계수 > 0일 때)\n- $\\sqrt{6} \\approx 2.45$를 이용하여 정확한 범위 $2 \\pm 2\\sqrt{6}$를 소수로 변환하는 것이 중요합니다.",
