    "problem": "방정식 $x^4 - 5x^2 + 4 = 0$의 모든 실근의 합을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n이 문제는 고차방정식을 이차방정식으로 치환하여 푸는 문제입니다. \n- 치환을 통한 방정식의 차수 낮추기\n- 비에타 공식: 방정식의 근과 계수의 관계\n- 홀수 차수 항이 없는 방정식의 대칭성\n\n**[풀이]**\n\n**Step 1: 치환을 이용한 방정식 정리**\n\n주어진 방정식: $x^4 - 5x^2 + 4 = 0$\n\n$x^2 = t$로 치환하면:\n$$t^2 - 5t + 4 = 0$$\n\n**Step 2: 이차방정식 풀이**\n\n인수분해하면:\n$$(t-1)(t-4) = 0$$\n\n따라서 $t = 1$ 또는 $t = 4$\n\n**Step 3: 원래 변수 복원**\n\n$x^2 = 1$일 때: $x = 1$ 또는 $x = -1$\n\n$x^2 = 4$일 때: $x = 2$ 또는 $x = -2$\n\n**Step 4: 모든 실근의 합 계산**\n\n원래 방정식의 모든 실근: $x = -2, -1, 1, 2$\n\n모든 실근의 합:\n$$(-2) + (-1) + 1 + 2 = 0$$\n\n**[정답 확인]**\n원래 방정식 $x^4 - 5x^2 + 4 = 0$에서 3차 항의 계수가 0이므로 (즉, $x^3$ 항이 없으므로), 근과 계수의 관계에 의해 모든 근의 합은 자동으로 0입니다.\n\n**[오답 분석]**\n선택지가 주어지지 않았으므로 일반적인 오류:\n- 음수 근을 빠뜨린 경우: $1 + 2 = 3$ (틀림)\n- 양수 근만 더한 경우: $1 + 2 = 3$ (틀림)\n- 부호를 잘못 계산한 경우: $-1 - 2 = -3$ (틀림)\n\n**[핵심 포인트]**\n1. $x^n$ 형태의 짝수 차수 항들만 있는 방정식은 $x$를 $-x$로 바꿔도 같은 방정식이므로 근이 쌍을 이루어 합이 0입니다.\n2. 비에타 공식: $x^4$의 계수가 1이고 $x^3$의 계수가 0이면 모든 근의 합 = 0",
