    "type": "방정식부등식",
    "problem": "방정식 $|x^2 - 4| = x + 2$의 모든 실근의 합을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n절댓값 방정식을 풀기 위해서는 절댓값 안의 식이 0이 되는 지점을 기준으로 경우를 나누어야 합니다. $|f(x)| = g(x)$ 형태의 방정식은 $f(x) \\geq 0$일 때와 $f(x) < 0$일 때로 나누어 풀고, 각 경우의 해가 해당 조건을 만족하는지 검증해야 합니다.\n\n**[풀이]**\n\n**Step 1: 절댓값 안의 식 분석**\n$x^2 - 4 = 0$일 때 $x = \\pm 2$이므로, 다음과 같이 경우를 나눕니다.\n- $x^2 - 4 \\geq 0$ ⟹ $x \\leq -2$ 또는 $x \\geq 2$\n- $x^2 - 4 < 0$ ⟹ $-2 < x < 2$\n\n**Step 2: 경우 1 ($x^2 - 4 \\geq 0$일 때)**\n$$x^2 - 4 = x + 2$$\n$$x^2 - x - 6 = 0$$\n$$(x - 3)(x + 2) = 0$$\n$$x = 3 \\text{ 또는 } x = -2$$\n\n조건 확인:\n- $x = 3$: $3 \\geq 2$ ✓ (유효)\n- $x = -2$: $-2 \\leq -2$ ✓ (유효)\n\n**Step 3: 경우 2 ($x^2 - 4 < 0$일 때)**\n$$-(x^2 - 4) = x + 2$$\n$$-x^2 + 4 = x + 2$$\n$$-x^2 - x + 2 = 0$$\n$$x^2 + x - 2 = 0$$\n$$(x + 2)(x - 1) = 0$$\n$$x = -2 \\text{ 또는 } x = 1$$\n\n조건 확인:\n- $x = -2$: $-2 < -2$ ✗ (불유효)\n- $x = 1$: $-2 < 1 < 2$ ✓ (유효)\n\n**Step 4: 모든 실근과 합 계산**\n유효한 실근: $x = 3, -2, 1$\n\n모든 실근의 합: $3 + (-2) + 1 = 2$\n\n**[정답 확인]**\n절댓값 조건을 정확히 나누어 경우를 분석하고, 각 경우에서 얻은 해가 해당 구간 조건을 만족하는지 검증하면 실근 $3, -2, 1$을 얻고, 이들의 합은 2입니다.\n\n**[오답 분석]**\n객관식 선택지가 없으므로 생략되었습니다. 다만 흔한 오류는:\n- 경우를 나누지 않고 풀어서 잘못된 답을 얻는 경우\n- 조건 검증을 빠뜨려 $x = -2$를 경우 2에서 중복으로 세는 경우\n- 원래 방정식에 대입하여 검증하지 않아 허근을 포함시키는 경우\n\n**[핵심 포인트]**\n절댓값 방정식은 반드시 **경우를 나누어 풀고**, 각 경우의 해가 **그 경우의 조건을 만족하는지 확인**해야 합니다. 경계점 $x = \\pm 2$에서 특히 주의해서 검증해야 합니다.",
