    "explanation": "**[핵심 개념]**\n삼차방정식의 근과 계수의 관계를 이용하는 문제입니다. \n- 삼차방정식 $x^3 + bx^2 + cx + d = 0$의 세 근을 $\\alpha, \\beta, \\gamma$라 하면:\n  - 근과 계수의 관계: $\\alpha\\beta\\gamma = -d$\n- 어떤 수가 방정식의 근이면, 그 값을 방정식에 대입하면 0이 됩니다.\n- 방정식이 인수분해되면 $(x-1)(x^2 + px + q) = 0$ 형태로 쓸 수 있습니다.\n\n**[풀이]**\n\n**Step 1: $x=1$이 근이므로 $a$ 값 구하기**\n\n$x=1$을 방정식 $x^3 - 6x^2 + 11x + a = 0$에 대입합니다.\n\n$$1^3 - 6(1)^2 + 11(1) + a = 0$$\n$$1 - 6 + 11 + a = 0$$\n$$6 + a = 0$$\n$$a = -6$$\n\n**Step 2: 원래 방정식 확정**\n\n따라서 방정식은 $x^3 - 6x^2 + 11x - 6 = 0$입니다.\n\n**Step 3: 인수분해**\n\n$x=1$이 근이므로 $(x-1)$으로 인수분해됩니다.\n\n조립제법 또는 다항식 나눗셈을 사용합니다:\n\n$$x^3 - 6x^2 + 11x - 6 = (x-1)(x^2 - 5x + 6)$$\n\n**Step 4: 나머지 근 구하기**\n\n$x^2 - 5x + 6 = 0$을 풀면:\n$$(x-2)(x-3) = 0$$\n\n따라서 나머지 두 근은 $x=2, x=3$입니다.\n\n**Step 5: 나머지 두 근의 곱 계산**\n\n$$2 \\times 3 = 6$$\n\n**[정답 확인]**\n세 근이 1, 2, 3이고 이들의 곱은 $1 \\times 2 \\times 3 = 6 = -(-6)$으로 근과 계수의 관계를 만족하므로 정답입니다.\n\n**[오답 분석]**\n선택지가 없어 오답 분석이 불가능합니다. 다만 계산 실수로 인한 오류 가능성:\n- $a$ 값을 잘못 구하면 인수분해가 틀려집니다.\n- 인수분해 후 남은 이차방정식을 잘못 풀면 근을 잘못 구합니다.\n\n**[핵심 포인트]**\n1. **주어진 근을 이용해 미지수 구하기**: $x=1$을 대입하여 $a=-6$을 먼저 구합니다.\n2. **인수분해로 모든 근 찾기**: $(x-1)$로 인수분해하면 나머지 두 근을 쉽게 구할 수 있습니다.",
