    "answer": 3,
    "explanation": "**[핵심 개념]**\n연립부등식을 풀기 위해서는 각 부등식을 개별적으로 풀고, 두 해집합의 교집합을 구해야 합니다. 이차부등식을 풀 때는 먼저 인수분해하여 근을 구한 후, 포물선의 모양을 이용하여 부등호 방향에 맞는 범위를 결정합니다.\n\n**[풀이]**\n\n**1단계: 첫 번째 부등식 $x^2 - 3x - 4 \\leq 0$ 풀기**\n\n인수분해하면:\n$$x^2 - 3x - 4 = (x-4)(x+1) \\leq 0$$\n\n$(x-4)(x+1) = 0$의 근은 $x = -1, 4$\n\n포물선이 위로 볼록하므로 $\\leq 0$을 만족하는 범위는:\n$$-1 \\leq x \\leq 4$$\n\n**2단계: 두 번째 부등식 $x^2 - x - 6 > 0$ 풀기**\n\n인수분해하면:\n$$x^2 - x - 6 = (x-3)(x+2) > 0$$\n\n$(x-3)(x+2) = 0$의 근은 $x = -2, 3$\n\n포물선이 위로 볼록하므로 $> 0$을 만족하는 범위는:\n$$x < -2 \\text{ 또는 } x > 3$$\n\n**3단계: 두 해집합의 교집합 구하기**\n\n$$\\begin{cases} -1 \\leq x \\leq 4 \\\\ x < -2 \\text{ 또는 } x > 3 \\end{cases}$$\n\n- $x < -2$와 $-1 \\leq x \\leq 4$의 교집합: 공집합 (∵ $-2 < -1$)\n- $x > 3$와 $-1 \\leq x \\leq 4$의 교집합: $3 < x \\leq 4$\n\n따라서 해집합은: $3 < x \\leq 4$\n\n**4단계: 조건을 만족하는 정수 찾기**\n\n$3 < x \\leq 4$를 만족하는 정수는:\n$$x = 4$$\n\n(∵ $x = 3$은 $3 < x$를 만족하지 않음)\n\n**5단계: 정수의 합 계산**\n\n조건을 만족하는 정수는 $4$ 하나뿐이므로:\n$$\\text{합} = 4$$\n\n**[정답 확인]**\n첫 번째 부등식에서 $-1 \\leq x \\leq 4$, 두 번째 부등식에서 $x < -2$ 또는 $x > 3$의 교집합은 $3 < x \\leq 4$이고, 이를 만족하는 유일한 정수는 $4$이므로 합은 $4$입니다.\n\n**[오답 분석]**\n- ① -1: $x = -1$은 첫 번째 부등식은 만족하지만 두 번째 부등식 $x^2 - x - 6 > 0$을 만족하지 않음\n- ② 0: 0도 두 번째 부등식 $(0)^2 - 0 - 6 = -6 > 0$을 만족하지 않음\n- ③ 3: $x = 3$은 $3 < x \\leq 4$에서 $3 < 3$을 만족하지 않음\n- ⑤ 7: $x = 7$은 첫 번째 부등식 $x \\leq 4$를 만족하지 않음\n\n**[핵심 포인트]**\n연립부등식은 각 부등식의 해집합을 먼저 구한 후 교집합을 구해야 합니다. 특히 $3 < x \\leq 4$에서 경계값 $x=3$은 부등호 기호가 '$<$'이므로 포함되지 않는다는 점을 주의해야 합니다.",
