    "answer": 1,
    "explanation": "**[핵심 개념]**\n3차 방정식 $x^3 + ax^2 + bx + c = 0$의 세 근을 $\\alpha, \\beta, \\gamma$라 할 때, 비에타의 정리(근과 계수의 관계)를 적용합니다.\n- 근의 합: $\\alpha + \\beta + \\gamma = -a$\n- 근의 곱의 합: $\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha = b$\n- 근의 곱: $\\alpha\\beta\\gamma = -c$\n\n**[풀이]**\n주어진 방정식의 세 근이 $1, 2, 3$이므로, 비에타의 정리를 적용합니다.\n\n**Step 1: 근의 합으로부터 $a$ 구하기**\n$$1 + 2 + 3 = -a$$\n$$6 = -a$$\n$$a = -6$$\n\n**Step 2: 근의 곱으로부터 $c$ 구하기**\n$$1 \\times 2 \\times 3 = -c$$\n$$6 = -c$$\n$$c = -6$$\n\n**Step 3: $a + c$ 계산**\n$$a + c = -6 + (-6) = -12$$\n\n**[정답 확인]**\n비에타의 정리를 올바르게 적용하면 $a = -6$, $c = -6$이므로 $a + c = -12$입니다.\n\n**[오답 분석]**\n- ① -16: $a + c = -10 + (-6)$ 등으로 계산 오류\n- ③ -8: 근의 곱만 고려하거나 부호를 잘못 처리\n- ④ -4: $a$와 $c$ 값을 잘못 구한 경우\n- ⑤ 0: 근과 계수의 관계식을 제대로 적용하지 않은 경우\n\n**[핵심 포인트]**\n3차 방정식에서 비에타의 정리 적용 시, **근의 합은 $-a$**, **근의 곱은 $-c$**임을 정확히 기억해야 합니다. 특히 음수 부호를 놓치지 않는 것이 중요합니다.",
