    "answer": 3,
    "explanation": "**[핵심 개념]**\n수직선 위를 움직이는 점의 위치가 시각 $t$의 함수 $x(t)$로 주어질 때, 시각 $t$에서의 속도는 위치함수를 시간에 대해 미분한 도함수 $v(t) = x'(t)$이다. 즉, 속도는 위치의 순간변화율이다.\n\n**[풀이]**\n\n**1단계: 위치함수 확인**\n점 P의 위치함수가 $x(t) = t^3 - 3t$로 주어졌다.\n\n**2단계: 속도함수 구하기**\n속도는 위치를 시간으로 미분하여 구한다.\n$$v(t) = \\frac{dx}{dt} = \\frac{d}{dt}(t^3 - 3t)$$\n\n미분 공식을 적용하면:\n$$v(t) = 3t^2 - 3$$\n\n**3단계: $t=2$일 때의 속도 계산**\n$t = 2$를 속도함수에 대입한다.\n$$v(2) = 3(2)^2 - 3$$\n$$v(2) = 3 \\times 4 - 3$$\n$$v(2) = 12 - 3$$\n$$v(2) = 9$$\n\n**[정답 확인]**\n$t=2$에서의 속도는 $v(2) = 9$이므로 정답은 ④이다.\n\n**[오답 분석]**\n- ① 3: $v(t) = 3t^2 - 3$에서 상수항 3만 취한 경우\n- ② 5: 계산 과정에서 $3 \\times 4 = 12$를 잘못 계산한 경우\n- ③ 7: $12 - 3$을 계산하는 과정에서 실수한 경우\n- ⑤ 12: 도함수를 구하지 않고 $3(2)^2 = 12$만 계산한 경우\n\n**[핵심 포인트]**\n- 속도 = 위치함수의 도함수이므로 반드시 미분을 먼저 수행해야 한다.\n- 미분할 때 각 항을 정확하게 처리하는 것이 중요하다: $t^3 \\rightarrow 3t^2$, $-3t \\rightarrow -3$",
