    "problem": "수직선 위를 움직이는 점 P의 시각 $t$에서의 위치가 $x(t) = 2t^2 - 8t + 5$일 때, 점 P가 운동 방향을 바꾸는 시각을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n점이 운동 방향을 바꾸는 시각은 속도가 0이 되는 시각입니다. 위치 함수 $x(t)$에서 속도는 $v(t) = \\frac{dx}{dt}$이므로, $v(t) = 0$이 되는 시각을 구하면 됩니다. 이는 위치 함수를 시간으로 미분하여 속도 함수를 만들고, 이 속도 함수가 0이 되는 시점을 찾는 것입니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n위치 함수 $x(t) = 2t^2 - 8t + 5$를 시간 $t$로 미분하여 속도 함수를 구합니다.\n\n$$v(t) = \\frac{dx}{dt} = \\frac{d}{dt}(2t^2 - 8t + 5) = 4t - 8$$\n\n**2단계: 속도가 0이 되는 시각 구하기**\n\n운동 방향을 바꾸는 시각은 속도가 0이 되는 시각이므로:\n\n$$v(t) = 0$$\n$$4t - 8 = 0$$\n$$4t = 8$$\n$$t = 2$$\n\n**3단계: 검증**\n\n$t < 2$일 때: $v(t) = 4t - 8 < 0$ (음의 방향으로 이동)\n$t > 2$일 때: $v(t) = 4t - 8 > 0$ (양의 방향으로 이동)\n\n속도가 음에서 양으로 변하므로 $t=2$에서 확실히 운동 방향이 바뀝니다.\n\n**[정답 확인]**\n속도 함수 $v(t) = 4t - 8$이 0이 되는 시각은 $t = 2$이며, 이때 점 P의 운동 방향이 바뀌므로 정답은 2입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 만약 다른 값들이 있다면:\n- 위치가 0이 되는 시각을 구한 경우 ($2t^2 - 8t + 5 = 0$): 틀린 답\n- 미분을 잘못한 경우: 틀린 답\n- 가속도를 구한 경우 ($a(t) = 4$): 틀린 답 (가속도는 항상 4로 일정)\n\n**[핵심 포인트]**\n- **운동 방향 변화 = 속도가 0이 되는 시각** (위치가 0이 아님)\n- 위치 함수를 미분하면 속도, 속도를 미분하면 가속도임을 정확히 구분하기",
