    "explanation": "**[핵심 개념]**\n가속도는 속도를 시간에 대해 미분한 값입니다. 즉, $a(t) = \\frac{dv}{dt}$입니다. 속도 함수가 주어졌을 때, 미분하여 가속도 함수를 구한 후 특정 시각의 가속도를 구하는 문제입니다.\n\n**[풀이]**\n주어진 속도 함수는 $v(t) = 6t - 12$입니다.\n\n가속도는 속도를 시간으로 미분하여 구합니다:\n$$a(t) = \\frac{dv}{dt} = \\frac{d}{dt}(6t - 12)$$\n\n미분 계산:\n- $6t$를 미분하면 $6$\n- $-12$(상수)를 미분하면 $0$\n\n따라서:\n$$a(t) = 6$$\n\n$t = 3$에서의 가속도는:\n$$a(3) = 6$$\n\n**[정답 확인]**\n속도 함수 $v(t) = 6t - 12$를 미분하면 가속도 $a(t) = 6$이고, 이는 상수이므로 모든 시각에서 가속도는 6입니다.\n\n**[오답 분석]**\n- ① 2: $t = 3$을 식에 대입한 오류 $(\\frac{6+12}{9} \\neq 2)$\n- ② 4: 계산 실수로 인한 오답\n- ④ 8: $t=3$을 $v(t)$에 대입한 값 $v(3) = 18-12 = 6$을 잘못 해석\n- ⑤ 12: $t=3$일 때 $6 \\times 2 = 12$ 등 다른 계산 방식의 오류\n\n**[핵심 포인트]**\n- 가속도 = 속도를 시간으로 미분한 값 ($a = \\frac{dv}{dt}$)\n- 이 문제에서 $v(t) = 6t - 12$는 1차 함수이므로 미분하면 상수(6)가 되어, 시각에 관계없이 가속도는 항상 6으로 일정합니다.",
