    "explanation": "**[핵심 개념]**\n- **속도(velocity)**: $v(t) = \\frac{dx}{dt}$ (위치를 시간으로 미분)\n- **속력(speed)**: $|v(t)|$ (속도의 절댓값, 항상 0 이상)\n- 속력이 최소가 되려면 $|v(t)|$의 최솟값을 구해야 함\n- 속력의 최솟값은 속도가 0에 가장 가까울 때 발생\n\n**[풀이]**\n\n**Step 1: 속도 함수 구하기**\n\n위치함수 $x(t) = -t^2 + 6t$를 시간으로 미분하면:\n$$v(t) = \\frac{dx}{dt} = -2t + 6$$\n\n**Step 2: 속력 함수 정의하기**\n\n속력은 속도의 절댓값이므로:\n$$|v(t)| = |-2t + 6| = |6 - 2t|$$\n\n**Step 3: 속력이 최소가 되는 조건 분석**\n\n$t \\geq 0$일 때 속력 $|6-2t|$를 분석하면:\n- $6 - 2t = 0$일 때, 즉 $t = 3$일 때 $|v(t)| = 0$ (최솟값)\n- $t < 3$일 때: $6 - 2t > 0$이므로 $|v(t)| = 6 - 2t$ (감소)\n- $t > 3$일 때: $6 - 2t < 0$이므로 $|v(t)| = 2t - 6$ (증가)\n\n따라서 $t = 3$에서 속력이 최소가 됩니다.\n\n**Step 4: 검증**\n\n$t = 3$일 때: $v(3) = -2(3) + 6 = 0$ → 속력 = $|0| = 0$ ✓\n\n**[정답 확인]**\n$t=3$일 때 속도가 0이 되어 속력이 최솟값 0을 가지므로, 속력이 최소가 되는 시각은 $t=3$입니다.\n\n**[오답 분석]**\n- ① $t=1$: $v(1) = 4$ → 속력 = 4\n- ② $t=2$: $v(2) = 2$ → 속력 = 2\n- ④ $t=4$: $v(4) = -2$ → 속력 = 2\n- ⑤ $t=6$: $v(6) = -6$ → 속력 = 6\n\n모두 속력이 0이 아니므로 최솟값이 아닙니다.\n\n**[핵심 포인트]**\n- 속력의 최솟값은 속도가 부호를 바꾸는 지점(속도가 0인 지점)에서 발생합니다.\n- 절댓값 함수 $|f(t)|$의 최솟값은 $f(t) = 0$에서 달성됩니다.",
