    "problem": "수직선 위를 움직이는 점 P의 시각 $t \\geq 0$에서의 위치가 $x(t) = t^3 - 9t^2 + 24t$일 때, 점 P가 운동 방향을 바꾸는 모든 시각의 합을 구하시오.",
    "answerType": "short",
