    "answer": 6,
    "explanation": "**[핵심 개념]**\n점이 운동 방향을 바꾸는 시점은 속도가 0이 되는 시각입니다. 위치함수 $x(t)$가 주어졌을 때, 속도는 $v(t) = x'(t)$이고, 운동 방향이 바뀌려면 $v(t) = 0$이면서 그 전후로 속도의 부호가 바뀌어야 합니다. 즉, $x'(t) = 0$을 만족하고 극값을 가지는 시각을 모두 찾으면 됩니다.\n\n**[풀이]**\n\n**Step 1: 속도함수 구하기**\n\n위치함수 $x(t) = t^3 - 9t^2 + 24t$를 시간으로 미분하여 속도함수를 구합니다.\n\n$$v(t) = x'(t) = 3t^2 - 18t + 24$$\n\n**Step 2: 속도가 0인 시각 찾기**\n\n점이 운동 방향을 바꾸려면 $v(t) = 0$이어야 합니다.\n\n$$3t^2 - 18t + 24 = 0$$\n\n양변을 3으로 나누면:\n\n$$t^2 - 6t + 8 = 0$$\n\n**Step 3: 이차방정식 풀기**\n\n인수분해하면:\n\n$$(t - 2)(t - 4) = 0$$\n\n따라서 $t = 2$ 또는 $t = 4$\n\n**Step 4: 실제로 운동 방향이 바뀌는지 확인**\n\n$v(t) = 3t^2 - 18t + 24 = 3(t-2)(t-4)$\n\n- $0 \\leq t < 2$: $v(t) > 0$ (양의 방향)\n- $2 < t < 4$: $v(t) < 0$ (음의 방향)\n- $t > 4$: $v(t) > 0$ (양의 방향)\n\n$t = 2$에서 속도가 양에서 음으로 변하고, $t = 4$에서 음에서 양으로 변하므로, 둘 다 운동 방향이 바뀝니다.\n\n**Step 5: 모든 시각의 합 구하기**\n\n운동 방향을 바꾸는 모든 시각의 합:\n\n$$2 + 4 = 6$$\n\n**[정답 확인]**\n속도함수의 영점이 $t = 2, 4$이고, 각 점에서 부호가 변하므로 두 시각 모두 운동 방향이 바뀌며, 그 합은 6입니다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 없음. 다만 $x'(t) = 0$의 해를 구하지 않고 $x(t) = 0$의 해를 구하는 실수를 하면 틀린 답을 얻을 수 있습니다.\n\n**[핵심 포인트]**\n- 운동 방향이 바뀌는 시각 = 속도가 0이 되고 부호가 바뀌는 시각\n- 비에타 공식으로 근과 계수의 관계를 이용하면, $t^2 - 6t + 8 = 0$에서 두 근의 합은 6입니다.",
