    "explanation": "**[핵심 개념]**\n- **속도**: 위치의 시간에 대한 1차 도함수, $v(t) = x'(t)$\n- **가속도**: 속도의 시간에 대한 1차 도함수(또는 위치의 2차 도함수), $a(t) = v'(t) = x''(t)$\n- 문제에서 요구하는 것: 속도가 0인 시각들을 찾고, 그 시각에서의 가속도를 구하기\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n$$v(t) = x'(t) = \\frac{d}{dt}(t^3 - 3t^2 - 9t + 1) = 3t^2 - 6t - 9$$\n\n**2단계: 속도가 0인 시각 찾기**\n\n$v(t) = 0$일 때:\n$$3t^2 - 6t - 9 = 0$$\n\n양변을 3으로 나누면:\n$$t^2 - 2t - 3 = 0$$\n\n인수분해:\n$$(t - 3)(t + 1) = 0$$\n\n따라서 $t = 3$ 또는 $t = -1$\n\n$t \\geq 0$이라는 조건에서 **$t = 3$만 유효**\n\n**3단계: 가속도 함수 구하기**\n\n$$a(t) = v'(t) = \\frac{d}{dt}(3t^2 - 6t - 9) = 6t - 6$$\n\n**4단계: $t = 3$에서의 가속도 구하기**\n\n$$a(3) = 6(3) - 6 = 18 - 6 = 12$$\n\n**[정답 확인]**\n$t \\geq 0$에서 속도가 0인 유일한 시각은 $t = 3$이고, 이때의 가속도는 $12$이므로 정답은 ②번입니다.\n\n**[오답 분석]**\n- ①: $-12$만 → 계산 실수 또는 부호 오류\n- ③: $-12$와 $12$ → $t = -1$을 포함하려 했으나 $t \\geq 0$ 조건 미충족\n- ④: $-6$과 $6$ → 가속도를 구하는 과정에서 계산 오류\n- ⑤: $0$과 $12$ → 잘못된 시각을 선택하여 가속도값 추가\n\n**[핵심 포인트]**\n1. **정의역 확인**: $t \\geq 0$ 조건을 반드시 확인하여 유효한 시각만 선택\n2. **미분의 순서**: 속도 → 1차 미분, 가속도 → 2차 미분(또는 속도의 1차 미분)",
