    "explanation": "**[핵심 개념]**\n\n점이 움직인 거리는 속도의 절댓값을 적분한 값입니다. 속도 $v(t)$가 음수인 구간과 양수인 구간을 나누어 계산해야 합니다. 거리는 항상 양수이므로, 속도가 음수인 구간에서는 절댓값을 취해야 합니다.\n\n$$\\text{거리} = \\int_a^b |v(t)| dt$$\n\n**[풀이]**\n\n**1단계: 속도가 0이 되는 시점 찾기**\n\n$$v(t) = 3t^2 - 12t + 9 = 0$$\n$$3(t^2 - 4t + 3) = 0$$\n$$3(t-1)(t-3) = 0$$\n\n따라서 $t = 1, t = 3$에서 속도가 0입니다.\n\n**2단계: 각 구간에서 속도의 부호 결정**\n\n- $0 \\leq t < 1$: $v(0) = 9 > 0$ (양수)\n- $1 < t < 3$: $v(2) = 3(4) - 12(2) + 9 = 12 - 24 + 9 = -3 < 0$ (음수)\n- $3 < t \\leq 4$: $v(4) = 3(16) - 12(4) + 9 = 48 - 48 + 9 = 9 > 0$ (양수)\n\n**3단계: 각 구간별로 거리 계산**\n\n$$\\text{거리} = \\int_0^1 v(t) dt - \\int_1^3 v(t) dt + \\int_3^4 v(t) dt$$\n\n**적분 계산:**\n\n부정적분: $\\int v(t) dt = \\int (3t^2 - 12t + 9) dt = t^3 - 6t^2 + 9t + C$\n\n**첫 번째 구간** $[0, 1]$:\n$$\\int_0^1 v(t) dt = [t^3 - 6t^2 + 9t]_0^1 = (1 - 6 + 9) - 0 = 4$$\n\n**두 번째 구간** $[1, 3]$:\n$$\\int_1^3 v(t) dt = [t^3 - 6t^2 + 9t]_1^3 = (27 - 54 + 27) - (1 - 6 + 9)$$\n$$= 0 - 4 = -4$$\n\n**세 번째 구간** $[3, 4]$:\n$$\\int_3^4 v(t) dt = [t^3 - 6t^2 + 9t]_3^4 = (64 - 96 + 36) - (27 - 54 + 27)$$\n$$= 4 - 0 = 4$$\n\n**4단계: 총 거리**\n\n$$\\text{거리} = 4 - (-4) + 4 = 4 + 4 + 4 = 12$$\n\n**[정답 확인]**\n\n속도가 부호를 바꾸는 시점에서 구간을 나누고, 음수 구간의 적분값에 음수 부호를 붙여 절댓값으로 처리하면 총 거리는 12가 됩니다.\n\n**[오답 분석]**\n\n- **20**: 절댓값 처리 없이 단순 적분값을 구한 경우 ($\\int_0^4 v(t)dt = 12$이지만, 이는 변위)\n- **8**: 일부 구간의 거리를 잘못 계산하거나 음수 구간을 무시한 경우\n- **16**: 절댓값 처리 시 부호를 잘못 적용한 경우\n\n**[핵심 포인트]**\n\n- **거리 ≠ 변위**: 거리는 항상 양수이며 절댓값 적분이 필요하고, 변위는 부호를 포함합니다.\n- 속도가 0이 되는 점에서 반드시 구간을 나누어 각각 계산해야 합니다.",
