    "explanation": "**[핵심 개념]**\n\n위치 함수 $x(t)$가 주어졌을 때, 속도는 위치를 시간에 대해 미분한 것입니다. 즉, $v(t) = \\frac{dx}{dt}$입니다. 점 P의 속도가 양수라는 것은 $v(t) > 0$인 구간을 찾는 것을 의미합니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n위치 함수 $x(t) = t^3 - 12t$를 $t$에 대해 미분하여 속도 함수를 구합니다.\n\n$$v(t) = \\frac{dx}{dt} = 3t^2 - 12$$\n\n**2단계: 속도가 양수인 조건 찾기**\n\n속도가 양수인 경우를 구하기 위해 $v(t) > 0$을 풉니다.\n\n$$3t^2 - 12 > 0$$\n\n$$3t^2 > 12$$\n\n$$t^2 > 4$$\n\n**3단계: 부등식 풀이**\n\n$t^2 > 4$에서 $|t| > 2$입니다.\n\n$$t > 2 \\text{ 또는 } t < -2$$\n\n**4단계: 주어진 조건 적용**\n\n문제에서 $t \\geq 0$이라는 조건이 주어졌으므로, $t < -2$는 정의역에 포함되지 않습니다.\n\n따라서 구하는 범위는 $t > 2$입니다.\n\n**[정답 확인]**\n\n$v(t) = 3t^2 - 12 > 0$에서 $t^2 > 4$이고, $t \\geq 0$ 범위에서 이를 만족하는 것은 $t > 2$입니다.\n\n**[오답 분석]**\n\n- ① $t > 1$: $t = 1$일 때 $v(1) = 3 - 12 = -9 < 0$이므로 틀림\n- ③ $t > 3$: 조건을 만족하지만 필요 이상으로 제한적이며, $2 < t < 3$에서도 속도가 양수\n- ④ $t > 4$: ③과 동일한 이유로 과도하게 제한적\n- ⑤ $0 < t < 2$: 이 구간에서 $v(t) = 3t^2 - 12 < 0$이므로 속도가 음수 (예: $t = 1$일 때 $v(1) = -9$)\n\n**[핵심 포인트]**\n\n속도의 부호를 판정할 때는 미분해서 얻은 함수의 부등식을 풀고, 주어진 정의역 조건($t \\geq 0$)을 반드시 확인해야 합니다. $t^2 > 4$는 수치적으로 $|t| > 2$를 의미하며, 이를 정의역과 교집합하면 최종 답을 얻습니다.",
