    "explanation": "**[핵심 개념]**\n위치함수 $x(t)$에서 속도는 $v(t) = x'(t)$이고, 가속도는 $a(t) = v'(t) = x''(t)$입니다. 속도와 가속도가 모두 양수인 구간을 구하려면 $v(t) > 0$과 $a(t) > 0$을 동시에 만족하는 $t$의 범위를 찾아야 합니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n$$v(t) = x'(t) = 6t^2 - 18t + 12$$\n\n**2단계: 가속도 함수 구하기**\n$$a(t) = v'(t) = 12t - 18$$\n\n**3단계: 가속도가 양수인 조건**\n$$a(t) > 0$$\n$$12t - 18 > 0$$\n$$12t > 18$$\n$$t > \\frac{3}{2}$$\n\n**4단계: 속도가 양수인 조건**\n$$v(t) > 0$$\n$$6t^2 - 18t + 12 > 0$$\n$$t^2 - 3t + 2 > 0$$\n\n인수분해하면:\n$$(t-1)(t-2) > 0$$\n\n이 부등식의 해는:\n$$t < 1 \\text{ 또는 } t > 2$$\n\n**5단계: 두 조건을 동시에 만족하는 범위**\n\n- 조건 1: $t > \\frac{3}{2}$ (가속도 > 0)\n- 조건 2: $t < 1$ 또는 $t > 2$ (속도 > 0)\n\n$\\frac{3}{2} = 1.5$이고, 이를 수직선에 표시하면:\n- $t > \\frac{3}{2}$인 범위에서\n- $t < 1$인 부분은 없음 ($\\frac{3}{2} > 1$이므로 교집합 없음)\n- $t > 2$인 부분이 포함됨\n\n따라서 두 조건의 교집합은 $t > 2$입니다.\n\n**[정답 확인]**\n$t > 2$일 때 $v(t) = 6(t-1)(t-2) > 0$이고 $a(t) = 12(t - \\frac{3}{2}) > 0$이 동시에 만족되므로 ②번이 정답입니다.\n\n**[오답 분석]**\n- ① $t > \\frac{3}{2}$: 가속도 조건만 만족하고, $1 < t < 2$ 구간에서는 속도가 음수입니다.\n- ③ $t > 3$: 정답의 부분집합이므로 너무 좁은 범위입니다.\n- ④ $0 < t < 1$: 이 구간에서 가속도가 음수이므로 조건에 맞지 않습니다.\n- ⑤ $t < 1$ 또는 $t > 2$: 속도 조건만 만족하고, $t < 1$과 $1 < t < \\frac{3}{2}$ 구간에서는 가속도가 음수입니다.\n\n**[핵심 포인트]**\n속도와 가속도가 모두 양수인 조건을 구할 때는 각 부등식의 해를 정확히 구한 후, 두 범위의 교집합을 구하는 것이 중요합니다. 항상 수직선을 그려서 범위를 시각화하면 실수를 줄일 수 있습니다.",
