    "problem": "수직선 위를 움직이는 점 P의 시각 $t \\geq 0$에서의 위치가 $x(t) = t^4 - 8t^3 + 18t^2$일 때, 가속도가 0인 모든 시각에서의 속도의 곱을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n- **속도**: 위치의 시간에 대한 1계 도함수 $v(t) = \\frac{dx}{dt}$\n- **가속도**: 속도의 시간에 대한 1계 도함수, 즉 위치의 2계 도함수 $a(t) = \\frac{dv}{dt} = \\frac{d^2x}{dt^2}$\n- 가속도가 0인 시각을 찾기 위해 $a(t) = 0$을 풀고, 각 시각에서의 속도를 구한 후 모두 곱함\n\n**[풀이]**\n\n**Step 1: 속도 구하기**\n\n$$v(t) = \\frac{dx}{dt} = 4t^3 - 24t^2 + 36t$$\n\n**Step 2: 가속도 구하기**\n\n$$a(t) = \\frac{dv}{dt} = 12t^2 - 48t + 36$$\n\n**Step 3: 가속도가 0인 시각 찾기**\n\n$$a(t) = 0$$\n$$12t^2 - 48t + 36 = 0$$\n\n양변을 12로 나누면:\n$$t^2 - 4t + 3 = 0$$\n\n인수분해하면:\n$$(t-1)(t-3) = 0$$\n\n따라서 $t = 1$ 또는 $t = 3$\n\n**Step 4: 각 시각에서의 속도 계산**\n\n$t = 1$일 때:\n$$v(1) = 4(1)^3 - 24(1)^2 + 36(1) = 4 - 24 + 36 = 16$$\n\n$t = 3$일 때:\n$$v(3) = 4(3)^3 - 24(3)^2 + 36(3) = 4(27) - 24(9) + 108 = 108 - 216 + 108 = 0$$\n\n**Step 5: 속도의 곱 계산**\n\n$$v(1) \\times v(3) = 16 \\times 0 = 0$$\n\n**[정답 확인]**\n$t=3$에서 속도가 0이므로, 모든 가속도가 0인 시각의 속도의 곱은 0이다.\n\n**[오답 분석]**\n객관식 문제가 아니므로 해당 없음. 만약 학생이 $t=3$에서의 속도를 잘못 계산하거나 $t=1$에서의 속도만 구하면 오답이 될 수 있다.\n\n**[핵심 포인트]**\n- 가속도가 0인 시각을 모두 찾아야 하며, $a(t) = 0$을 이차방정식으로 풀어야 한다.\n- 곱셈에서 하나라도 0이면 전체 곱은 0이 되는 성질을 활용해야 한다.",
