    "problem": "수직선 위를 움직이는 두 점 P, Q의 시각 $t \\geq 0$에서의 위치가 각각 $x_P(t) = t^3 - 6t$, $x_Q(t) = 3t^2 - 6t$이다. $t > 0$에서 두 점의 속도가 같아지는 시각에서 점 P의 가속도를 구하시오.",
    "answerType": "short",
