    "explanation": "**[핵심 개념]**\n수직선 위의 점이 움직인 거리는 단순히 위치의 변화량이 아니라, 방향을 바꾸는 시점을 기준으로 각 구간의 이동 거리를 모두 더해야 한다. \n- 속도 $v(t) = x'(t)$가 0이 되는 시점에서 방향이 바뀐다.\n- 구간별 이동 거리 = $|x(t_2) - x(t_1)|$를 모두 합산한다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n$$v(t) = x'(t) = 3t^2 - 18t + 15$$\n\n**2단계: 속도가 0이 되는 시점 찾기 (방향 전환점)**\n$$3t^2 - 18t + 15 = 0$$\n$$t^2 - 6t + 5 = 0$$\n$$(t-1)(t-5) = 0$$\n$$t = 1 \\text{ 또는 } t = 5$$\n\n**3단계: 각 구간에서 속도의 부호 확인**\n- $t = 0$: $v(0) = 15 > 0$ (양의 방향)\n- $t = 1$: $v(1) = 0$ (방향 전환)\n- $t = 3$ (1과 5 사이): $v(3) = 27 - 54 + 15 = -12 < 0$ (음의 방향)\n- $t = 5$: $v(5) = 0$ (방향 전환)\n- $t = 6$: $v(6) = 108 - 108 + 15 = 15 > 0$ (양의 방향)\n\n**4단계: 각 시점에서의 위치 계산**\n$$x(0) = 0 - 0 + 0 + 3 = 3$$\n\n$$x(1) = 1 - 9 + 15 + 3 = 10$$\n\n$$x(5) = 125 - 9(25) + 15(5) + 3 = 125 - 225 + 75 + 3 = -22$$\n\n$$x(6) = 216 - 9(36) + 15(6) + 3 = 216 - 324 + 90 + 3 = -15$$\n\n**5단계: 각 구간에서의 이동 거리 계산**\n- $t = 0$에서 $t = 1$까지: $|x(1) - x(0)| = |10 - 3| = 7$\n- $t = 1$에서 $t = 5$까지: $|x(5) - x(1)| = |-22 - 10| = |-32| = 32$\n- $t = 5$에서 $t = 6$까지: $|x(6) - x(5)| = |-15 - (-22)| = |7| = 7$\n\n**6단계: 전체 이동 거리**\n$$\\text{총 거리} = 7 + 32 + 7 = 46$$\n\n**[정답 확인]**\n점 P는 $t=0$에서 $t=1$까지 3에서 10으로 이동하고(7), $t=1$에서 $t=5$까지 10에서 -22로 이동하며(32), $t=5$에서 $t=6$까지 -22에서 -15로 이동(7)하므로, 총 이동 거리는 46이다.\n\n**[오답 분석]**\n- ① 28: $|x(1)-x(0)| + |x(6)-x(5)|$만 계산한 경우 ($7+21=28$)\n- ② 32: $|x(5)-x(1)|$만 계산한 경우 (가장 큰 구간만 선택)\n- ③ 39: 계산 실수로 중간 값을 잘못 구한 경우\n- ⑤ 52: $|x(6)-x(0)|$처럼 시작점과 끝점의 거리만 구하거나 계산 실수\n\n**[핵심 포인트]**\n1. 움직인 거리는 속도의 부호가 바뀌는 지점에서 구간을 나누어 각 구간의 거리를 절댓값으로 더해야 한다.\n2. $v(t) = 0$인 점이 이동 거리를 계산하는 핵심이며, 각 구간에서 위치의 변화량의 절댓값을 모두 합산해야 한다.",
