    "answer": 3,
    "explanation": "**[핵심 개념]**\n위치 함수 $x(t)$에서 도함수를 이용하여 속도와 가속도를 구하는 미분의 응용입니다.\n- 속도: $v(t) = \\frac{dx}{dt} = x'(t)$\n- 가속도: $a(t) = \\frac{dv}{dt} = x''(t)$\n\n주어진 조건들을 식으로 나타내어 미지수를 구합니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n위치 함수 $x(t) = t^3 + at^2 + bt$를 $t$에 대해 미분하면:\n\n$$v(t) = x'(t) = 3t^2 + 2at + b$$\n\n**2단계: $t=1$에서 속도가 0이라는 조건 적용**\n\n$$v(1) = 3(1)^2 + 2a(1) + b = 0$$\n\n$$3 + 2a + b = 0 \\cdots (1)$$\n\n**3단계: 가속도 함수 구하기**\n\n속도 함수를 다시 미분하면:\n\n$$a(t) = v'(t) = 6t + 2a$$\n\n**4단계: $t=1$에서 가속도가 $-6$이라는 조건 적용**\n\n$$a(1) = 6(1) + 2a = -6$$\n\n$$6 + 2a = -6$$\n\n$$2a = -12$$\n\n$$a = -6 \\cdots (2)$$\n\n**5단계: $b$ 구하기**\n\n식 (2)의 $a = -6$을 식 (1)에 대입:\n\n$$3 + 2(-6) + b = 0$$\n\n$$3 - 12 + b = 0$$\n\n$$b = 9$$\n\n**6단계: $a + b$ 계산**\n\n$$a + b = -6 + 9 = 3$$\n\n**[정답 확인]**\n$a = -6$, $b = 9$를 원래 조건에 대입하면 $v(1) = 3 - 12 + 9 = 0$ ✓, $a(1) = 6 - 12 = -6$ ✓이므로 $a + b = 3$이 정답입니다.\n\n**[오답 분석]**\n- ① $-6$: $a$의 값만 선택한 경우\n- ② $-3$: 계산 실수로 $3 + 2a + b = 0$에서 잘못 정리한 경우\n- ③ $0$: $b$를 잘못 계산한 경우\n- ⑤ $6$: $a + b$를 계산할 때 절댓값으로 처리한 경우\n\n**[핵심 포인트]**\n- 위치 → 속도 → 가속도는 차례대로 미분하여 구합니다.\n- 주어진 조건(속도=0, 가속도=-6)을 식으로 바꾸어 연립방정식을 풀면 됩니다.",
