    "type": "속도·가속도",
    "problem": "수직선 위를 움직이는 점 P의 시각 $t \\geq 0$에서의 위치가 $x(t) = t^3 - 6t^2 + 9t + 2$이다. $t = 0$에서 $t = 5$까지 점 P의 변위(위치의 변화량)를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 20,
    "explanation": "**[핵심 개념]**\n\n변위(displacement)는 최종 위치에서 초기 위치를 뺀 값으로, 움직인 경로와 무관하게 시작점과 끝점의 위치 차이만으로 구합니다. 이는 거리(distance)와 다릅니다. 변위를 구하려면 단순히 $x(t_{\\text{끝}}) - x(t_{\\text{시작}})$을 계산하면 됩니다.\n\n**[풀이]**\n\n주어진 위치함수: $x(t) = t^3 - 6t^2 + 9t + 2$\n\n**Step 1: $t=0$일 때의 위치 구하기**\n\n$$x(0) = 0^3 - 6(0)^2 + 9(0) + 2 = 2$$\n\n**Step 2: $t=5$일 때의 위치 구하기**\n\n$$x(5) = 5^3 - 6(5)^2 + 9(5) + 2$$\n\n$$= 125 - 6(25) + 45 + 2$$\n\n$$= 125 - 150 + 45 + 2$$\n\n$$= 22$$\n\n**Step 3: 변위 계산**\n\n변위는 최종 위치에서 초기 위치를 뺀 값이므로:\n\n$$\\text{변위} = x(5) - x(0) = 22 - 2 = 20$$\n\n**[정답 확인]**\n\n$t=0$에서 $t=5$까지의 변위는 단순히 위치의 차이인 $22 - 2 = 20$이므로 정답이 맞습니다.\n\n**[오답 분석]**\n\n학생들이 범할 수 있는 실수:\n- 속도함수 $v(t) = 3t^2 - 12t + 9$에서 $v(t) = 0$인 시점($t=1, 3$)을 찾아 각 구간별로 이동거리를 계산하는 경우: 이는 거리(distance)를 구하는 것이지 변위를 구하는 것이 아닙니다.\n- 계산 실수로 $x(5) = 125 - 150 + 45 = 20$으로 잘못 계산한 후 상수항 2를 빠뜨리는 경우\n\n**[핵심 포인트]**\n\n**변위 = 최종 위치 - 초기 위치** (경로와 무관)\n변위는 벡터량이므로 음수가 될 수 있지만, 거리는 항상 양수입니다. 문제에서 \"변위\"를 명시했으므로 위치 함수의 끝값과 시작값의 차이만 구하면 됩니다.",
