    "answer": 2,
    "explanation": "**[핵심 개념]**\n- 위치함수 $x(t)$를 시간에 대해 미분하면 속도함수 $v(t) = x'(t)$\n- 함수의 최솟값을 구하기 위해 도함수를 0으로 놓고 임계점 찾기\n- 임계점과 경계에서의 함수값을 비교하여 최솟값 결정\n\n**[풀이]**\n\n**Step 1: 속도함수 구하기**\n\n위치함수 $x(t) = t^4 - 4t^3$를 시간에 대해 미분하면:\n$$v(t) = x'(t) = 4t^3 - 12t^2$$\n\n**Step 2: 속도함수의 최솟값을 구하기 위해 도함수 구하기**\n\n속도의 최솟값을 찾기 위해 $v(t)$를 다시 미분합니다:\n$$v'(t) = 12t^2 - 24t = 12t(t-2)$$\n\n**Step 3: 임계점 찾기**\n\n$v'(t) = 0$일 때:\n$$12t(t-2) = 0$$\n$$t = 0 \\text{ 또는 } t = 2$$\n\n**Step 4: 임계점에서 속도값 계산**\n\n$t = 0$일 때:\n$$v(0) = 4(0)^3 - 12(0)^2 = 0$$\n\n$t = 2$일 때:\n$$v(2) = 4(2)^3 - 12(2)^2 = 4 \\cdot 8 - 12 \\cdot 4 = 32 - 48 = -16$$\n\n**Step 5: 최솟값 결정**\n\n$v'(t) = 12t(t-2)$의 부호 변화:\n- $t < 0$: $v'(t) > 0$ (증가)\n- $0 < t < 2$: $v'(t) < 0$ (감소)\n- $t > 2$: $v'(t) > 0$ (증가)\n\n따라서 $t = 2$에서 속도는 최솟값을 가집니다.\n\n$$v(t)_{\\min} = -16$$\n\n**[정답 확인]**\n$t = 2$에서 $v(2) = -16$이 속도함수의 최솟값이며, 이는 정답 ③번입니다.\n\n**[오답 분석]**\n- ① $-32$: $v(2) = 4(8) - 12(4) = 32 - 48 = -16$이지 $-32$가 아님\n- ② $-24$: 계산 오류로 인한 선택지\n- ④ $-8$: $v(2)$를 잘못 계산한 경우\n- ⑤ $0$: $t = 0$에서의 속도값이지만, 이것은 최솟값이 아님 (극대값)\n\n**[핵심 포인트]**\n속도의 최솟값을 구할 때는 $v'(t) = 0$인 점에서 극값을 판정하고, 각 임계점에서의 함수값을 비교해야 합니다. $t = 0$과 $t = 2$ 중에서 실제 최솟값은 $v(2) = -16$입니다.",
