    "problem": "수직선 위를 움직이는 점 P의 시각 $t \\geq 0$에서의 위치가 $x(t) = t^3 - 3t^2 - t + 3$이다. 점 P가 원점을 처음으로 지나는 시각에서의 속도의 절댓값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n- 위치 함수 $x(t)$에서 속도는 $v(t) = \\frac{dx}{dt}$로 구함\n- 점이 원점을 지날 때는 $x(t) = 0$일 때\n- 속도의 절댓값은 $|v(t)|$로 구함\n\n**[풀이]**\n\n**1단계: 점 P가 원점을 지나는 시각 찾기**\n\n점 P가 원점을 지날 때 $x(t) = 0$이므로:\n$$t^3 - 3t^2 - t + 3 = 0$$\n\n인수분해를 위해 항을 묶으면:\n$$t^2(t-3) - 1(t-3) = 0$$\n$$(t^2-1)(t-3) = 0$$\n$$(t-1)(t+1)(t-3) = 0$$\n\n따라서 $t = -1, 1, 3$\n\n$t \\geq 0$이고 점 P가 **처음으로** 원점을 지나므로:\n$$t = 1$$\n\n**2단계: 속도 함수 구하기**\n\n$$v(t) = \\frac{dx}{dt} = 3t^2 - 6t - 1$$\n\n**3단계: $t=1$에서의 속도 계산**\n\n$$v(1) = 3(1)^2 - 6(1) - 1 = 3 - 6 - 1 = -4$$\n\n**4단계: 속도의 절댓값**\n\n$$|v(1)| = |-4| = 4$$\n\n**[정답 확인]**\n점 P는 $t=1$에서 처음 원점을 지나며, 이때의 속도는 $-4$이므로 속도의 절댓값은 4입니다.\n\n**[오답 분석]**\n- 만약 $t=3$을 사용하면: $v(3) = 3(9) - 6(3) - 1 = 8$이 되지만, 이는 세 번째 통과 시점\n- $v(t)$ 계산 실수: 미분을 잘못하면 다른 값이 나옴\n- 절댓값을 빼먹으면: $-4$라는 오답이 나옴\n\n**[핵심 포인트]**\n1. 원점을 \"처음으로\" 지나는 조건을 확인 - $t \\geq 0$ 범위에서 가장 작은 양수 해를 선택\n2. 속도의 절댓값은 반드시 절댓값 기호를 취해야 함",
