    "answer": 2,
    "explanation": "**[핵심 개념]**\n점의 운동에서 속도는 위치를 시간으로 미분한 것이고, 가속도는 속도를 시간으로 미분한 것입니다. 즉, $v(t) = x'(t)$, $a(t) = v'(t) = x''(t)$입니다. 문제에서 요구하는 것은 속도와 가속도가 모두 양수인 구간에서 $t$의 최솟값(하한)입니다.\n\n**[풀이]**\n\n**1단계: 속도와 가속도 구하기**\n\n주어진 위치: $x(t) = t^4 - 8t^2 + 12$\n\n속도를 구합니다:\n$$v(t) = x'(t) = 4t^3 - 16t = 4t(t^2 - 4) = 4t(t-2)(t+2)$$\n\n가속도를 구합니다:\n$$a(t) = v'(t) = 12t^2 - 16 = 4(3t^2 - 4)$$\n\n**2단계: 속도가 양수인 조건**\n\n$v(t) = 4t(t-2)(t+2) > 0$\n\n$t \\geq 0$인 범위에서 분석하면:\n- $t = 0$일 때: $v(0) = 0$\n- $0 < t < 2$일 때: $v(t) < 0$ (음수)\n- $t > 2$일 때: $v(t) > 0$ (양수)\n\n따라서 $v(t) > 0$ ⟹ $t > 2$\n\n**3단계: 가속도가 양수인 조건**\n\n$a(t) = 4(3t^2 - 4) > 0$\n\n$$3t^2 - 4 > 0$$\n$$t^2 > \\frac{4}{3}$$\n$$|t| > \\frac{2}{\\sqrt{3}} = \\frac{2\\sqrt{3}}{3}$$\n\n$t \\geq 0$이므로: $t > \\frac{2\\sqrt{3}}{3}$\n\n**4단계: 두 조건을 동시에 만족**\n\n속도가 양수: $t > 2$\n\n가속도가 양수: $t > \\frac{2\\sqrt{3}}{3}$\n\n$\\frac{2\\sqrt{3}}{3} \\approx 1.155 < 2$이므로, 두 조건을 모두 만족하려면:\n\n$$t > 2$$\n\n따라서 $t$의 하한(최솟값)은 $\\boxed{2}$입니다.\n\n**[정답 확인]**\n\n$t > 2$일 때 $v(t) > 0$이고 $a(t) > 0$이 동시에 성립하므로, $t$의 하한은 $2$입니다.\n\n**[오답 분석]**\n\n① $1$: $t=1$일 때 $v(1) = 4(1)(-1)(3) = -12 < 0$이므로 속도 조건 불만족\n\n② $\\frac{2\\sqrt{3}}{3}$: 가속도가 양수인 조건의 경계값이지만, 이 값에서 속도는 음수이므로 두 조건을 동시에 만족하지 않음\n\n④ $\\sqrt{3}$: $\\sqrt{3} \\approx 1.732 < 2$이므로 속도 조건을 만족하지 않음\n\n⑤ $\\frac{4}{3}$: $\\frac{4}{3} \\approx 1.333 < 2$이므로 속도 조건을 만족하지 않음\n\n**[핵심 포인트]**\n\n여러 조건을 동시에 만족해야 할 때는 각 조건의 범위를 구한 후 **교집합**을 취해야 합니다. 이 문제에서는 $t > 2$와 $t > \\frac{2\\sqrt{3}}{3}$의 교집합이 $t > 2$이므로, 하한은 더 큰 값인 $2$가 됩니다.",
