    "explanation": "**[핵심 개념]**\n\n점이 운동 방향을 바꾼다는 것은 속도가 0이 되는 순간을 의미합니다. 위치 함수 $x(t)$의 도함수인 속도 $v(t) = x'(t)$가 0이 되는 시각을 찾아야 합니다. 속도가 양수에서 음수로, 또는 음수에서 양수로 변할 때 운동 방향이 바뀝니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n위치 함수가 $x(t) = t^3 - 3t^2 + 2$이므로, 속도는:\n$$v(t) = \\frac{dx}{dt} = 3t^2 - 6t$$\n\n**2단계: 운동 방향을 바꾸는 시각 찾기**\n\n운동 방향을 바꾸는 것은 속도가 0이 되는 시각입니다:\n$$v(t) = 0$$\n$$3t^2 - 6t = 0$$\n$$3t(t - 2) = 0$$\n$$t = 0 \\text{ 또는 } t = 2$$\n\n**3단계: 양의 시각 선택**\n\n문제에서 \"양의 시각\"을 구하라고 했으므로:\n$$t = 2$$\n\n**4단계: 그 순간의 위치 구하기**\n\n$t = 2$일 때 점 P의 위치:\n$$x(2) = (2)^3 - 3(2)^2 + 2$$\n$$= 8 - 12 + 2$$\n$$= -2$$\n\n**[정답 확인]**\n\n$t=2$에서 속도가 0이 되고, 가속도 $a(t) = 6t - 6$에 대해 $a(2) = 6 > 0$이므로 실제로 운동 방향이 바뀌며, 이 순간의 위치는 $-2$입니다.\n\n**[오답 분석]**\n\n- $t=0$을 선택하는 경우: $t \\geq 0$의 범위 시작점이지만, 문제에서 \"양의 시각\"(positive time)을 명시했으므로 $t=0$은 제외됩니다.\n- 다른 값들: 속도가 0이 아닌 시각에서의 위치이거나, 계산 오류로 인한 결과입니다.\n\n**[핵심 포인트]**\n\n1. **운동 방향 변화 = 속도 0**: $v(t) = x'(t) = 0$을 풀어 운동 방향을 바꾸는 시각을 찾습니다.\n2. **\"양의 시각\" 주의**: $t > 0$ 범위에서 원하는 값을 선택해야 합니다.",
