    "problem": "수직선 위를 움직이는 점 P의 시각 $t \\geq 0$에서의 위치가 $x(t) = t^3 - 6t^2 + 9t + 5$이다. $t = 0$에서 $t = 5$까지 (이동 거리) $-$ (변위)의 값은?",
