    "explanation": "**[핵심 개념]**\n\n수직선 위의 점의 운동에서:\n- **변위(displacement)**: 시작점에서 끝점까지의 위치 변화 = $x(t_f) - x(t_i)$\n- **이동 거리(distance)**: 실제로 움직인 경로의 길이 (항상 양수)\n- 속도 $v(t) = x'(t)$의 부호가 바뀌는 시점에서 점이 방향을 바꿈\n- 이동 거리는 각 구간에서 $|v(t)|$를 적분한 값의 합\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n$$v(t) = x'(t) = 3t^2 - 12t + 9 = 3(t^2 - 4t + 3) = 3(t-1)(t-3)$$\n\n**2단계: 속도가 0인 시점 찾기**\n$$v(t) = 0 \\text{일 때: } t = 1 \\text{ 또는 } t = 3$$\n\n**3단계: 각 시점에서의 위치 계산**\n- $x(0) = 0 - 0 + 0 + 5 = 5$\n- $x(1) = 1 - 6 + 9 + 5 = 9$\n- $x(3) = 27 - 54 + 27 + 5 = 5$\n- $x(5) = 125 - 150 + 45 + 5 = 25$\n\n**4단계: 속도의 부호 결정**\n- $0 < t < 1$: $v(t) > 0$ (양의 방향)\n- $1 < t < 3$: $v(t) < 0$ (음의 방향)\n- $3 < t < 5$: $v(t) > 0$ (양의 방향)\n\n**5단계: 이동 거리 계산**\n$$\\text{이동 거리} = |x(1) - x(0)| + |x(3) - x(1)| + |x(5) - x(3)|$$\n$$= |9 - 5| + |5 - 9| + |25 - 5|$$\n$$= 4 + 4 + 20 = 28$$\n\n**6단계: 변위 계산**\n$$\\text{변위} = x(5) - x(0) = 25 - 5 = 20$$\n\n**7단계: 최종 답 계산**\n$$\\text{(이동 거리)} - \\text{(변위)} = 28 - 20 = 8$$\n\n**[정답 확인]**\n\n이동 거리 28에서 변위 20을 빼면 8이므로, 정답은 ③번입니다.\n\n**[오답 분석]**\n\n- ① 4: 한 구간의 이동만 계산한 경우\n- ② 6: 계산 오류로 이동 거리를 잘못 구한 경우\n- ④ 10: 변위를 잘못 계산하거나 부호를 놓친 경우\n- ⑤ 12: 이동 거리 계산에서 절댓값을 제대로 처리하지 않은 경우\n\n**[핵심 포인트]**\n\n- 속도가 0인 모든 점을 찾아야 하며, 각 구간별로 이동 거리를 계산할 때 항상 절댓값을 취한다.\n- 이동 거리는 항상 변위 이상이며, 방향 전환이 있을수록 둘의 차이가 커진다.",
