    "explanation": "**[핵심 개념]**\n이 문제는 도함수가 주어졌을 때 원래 함수를 구하는 부정적분(역미분) 문제입니다.\n- 도함수 $f'(x)$가 주어지면, $f(x) = \\int f'(x)dx$ 형태로 원함수를 구합니다.\n- 초기조건 $f(0) = 2$를 이용하여 적분상수를 결정합니다.\n- 다항함수의 부정적분: $\\int x^n dx = \\frac{x^{n+1}}{n+1} + C$ (단, $n \\neq -1$)\n\n**[풀이]**\n\n**Step 1: 도함수로부터 원함수 구하기**\n\n$f'(x) = 3x^2 - 6x$이므로, 양변을 적분합니다.\n\n$$f(x) = \\int (3x^2 - 6x)dx$$\n\n**Step 2: 항별로 적분 계산**\n\n$$f(x) = \\int 3x^2 dx - \\int 6x dx$$\n\n$$f(x) = 3 \\cdot \\frac{x^3}{3} - 6 \\cdot \\frac{x^2}{2} + C$$\n\n$$f(x) = x^3 - 3x^2 + C$$\n\n여기서 $C$는 적분상수입니다.\n\n**Step 3: 초기조건을 이용하여 적분상수 결정**\n\n$f(0) = 2$를 대입합니다.\n\n$$f(0) = 0^3 - 3(0)^2 + C = 2$$\n\n$$C = 2$$\n\n**Step 4: 최종 함수식**\n\n$$f(x) = x^3 - 3x^2 + 2$$\n\n**Step 5: $f(3)$ 계산**\n\n$$f(3) = 3^3 - 3(3)^2 + 2$$\n\n$$f(3) = 27 - 27 + 2$$\n\n$$f(3) = 2$$\n\n**[정답 확인]**\n$f(3) = 27 - 27 + 2 = 2$이므로 정답은 **③번**입니다.\n\n**[오답 분석]**\n- ① $-2$: 적분상수를 $C = -2$로 잘못 설정한 경우\n- ② $0$: 적분 계산 과정에서 상수항을 누락한 경우\n- ④ $4$: 적분상수를 $C = 4$로 잘못 설정한 경우\n- ⑤ $8$: 적분 계산 또는 함숫값 계산 실수\n\n**[핵심 포인트]**\n1. 도함수가 주어질 때는 **부정적분**을 이용하여 원함수를 구하고, 반드시 **적분상수 $C$를 포함**시켜야 합니다.\n2. 초기조건(경계조건)을 활용하여 적분상수를 **유일하게 결정**하는 것이 핵심입니다.",
