    "problem": "함수 $f(x) = x^3 - 3x + 1$의 극댓값과 극솟값의 합을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수의 극값은 도함수가 0이 되는 점에서 나타납니다. $f'(x) = 0$인 점을 찾고, 그 점에서의 함수값을 구하면 됩니다. 극댓값은 $f'(x)$가 양에서 음으로 변하는 점에서, 극솟값은 $f'(x)$가 음에서 양으로 변하는 점에서 나타납니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = x^3 - 3x + 1$$\n\n$$f'(x) = 3x^2 - 3$$\n\n**2단계: 극값을 갖는 점 찾기**\n\n극값은 $f'(x) = 0$인 점에서 나타나므로:\n\n$$3x^2 - 3 = 0$$\n\n$$3(x^2 - 1) = 0$$\n\n$$x^2 = 1$$\n\n$$x = -1 \\text{ 또는 } x = 1$$\n\n**3단계: 극값의 종류 판별**\n\n$f'(x) = 3(x-1)(x+1)$이므로:\n- $x < -1$일 때: $f'(x) > 0$ (증가)\n- $-1 < x < 1$일 때: $f'(x) < 0$ (감소)\n- $x > 1$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -1$에서 극댓값, $x = 1$에서 극솟값을 가집니다.\n\n**4단계: 극댓값과 극솟값 계산**\n\n극댓값 ($x = -1$에서):\n$$f(-1) = (-1)^3 - 3(-1) + 1 = -1 + 3 + 1 = 3$$\n\n극솟값 ($x = 1$에서):\n$$f(1) = 1^3 - 3(1) + 1 = 1 - 3 + 1 = -1$$\n\n**5단계: 극댓값과 극솟값의 합**\n\n$$3 + (-1) = 2$$\n\n**[정답 확인]**\n극댓값 3과 극솟값 -1의 합이 2이므로 정답입니다.\n\n**[오답 분석]**\n객관식이 없으므로 해당사항 없음. 다만 계산 실수로 $f(-1) = 1$ 또는 $f(1) = 3$으로 잘못 계산하면 다른 값이 나올 수 있습니다.\n\n**[핵심 포인트]**\n- 극값을 구할 때는 $f'(x) = 0$의 해를 구한 후, 그 점에서 함수값 $f(x)$를 계산합니다.\n- 부호 판정법으로 극대/극소를 구분하는 것이 중요합니다.",
