    "answer": 1,
    "explanation": "**[핵심 개념]**\n함수의 극값(극대, 극소)을 구하기 위해서는 도함수를 이용합니다. \n- $f'(x) = 0$인 점에서 극값 후보를 찾습니다.\n- $f'(x)$의 부호가 양(+)에서 음(-)으로 변하면 그 점에서 극대\n- $f'(x)$의 부호가 음(-)에서 양(+)으로 변하면 그 점에서 극소\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = x^3 - 6x^2 + 9x + 2$$\n\n$$f'(x) = 3x^2 - 12x + 9$$\n\n**2단계: 극값 후보 찾기 ($f'(x) = 0$)**\n\n$$3x^2 - 12x + 9 = 0$$\n\n$$x^2 - 4x + 3 = 0$$\n\n$$(x-1)(x-3) = 0$$\n\n$$x = 1 \\text{ 또는 } x = 3$$\n\n**3단계: 각 점에서의 극대/극소 판별**\n\n$f'(x) = 3x^2 - 12x + 9 = 3(x-1)(x-3)$로 인수분해되므로:\n\n- $x < 1$일 때: $(x-1) < 0$, $(x-3) < 0$ → $f'(x) = 3(-)(-) > 0$ (증가)\n- $1 < x < 3$일 때: $(x-1) > 0$, $(x-3) < 0$ → $f'(x) = 3(+)(-) < 0$ (감소)\n- $x > 3$일 때: $(x-1) > 0$, $(x-3) > 0$ → $f'(x) = 3(+)(+) > 0$ (증가)\n\n따라서:\n- $x = 1$에서 $f'(x)$가 양(+)에서 음(-)으로 변함 → **극대**\n- $x = 3$에서 $f'(x)$가 음(-)에서 양(+)으로 변함 → 극소\n\n**[정답 확인]**\n$x = 1$에서 도함수의 부호가 양에서 음으로 변하므로 극대이며, 선택지 ②가 정답입니다.\n\n**[오답 분석]**\n- ① $x = 0$: 극값 후보가 아님 ($f'(0) = 9 \\neq 0$)\n- ③ $x = 3$: 극소점입니다 (도함수 부호가 음에서 양으로 변함)\n- ④ $x = 4$: 극값 후보가 아님 ($f'(4) = 9 \\neq 0$)\n- ⑤ $x = 4$: 극값 후보가 아님\n\n**[핵심 포인트]**\n1. 극대/극소는 $f'(x) = 0$인 점에서만 발생하므로, 먼저 도함수를 구하고 영점을 찾아야 합니다.\n2. 도함수의 부호 변화를 확인하는 것이 극대인지 극소인지 판별하는 가장 확실한 방법입니다.",
