    "explanation": "**[핵심 개념]**\n곡선 위의 특정 점에서의 접선의 기울기는 그 점에서의 미분값(도함수의 함숫값)과 같습니다. \n- 함수 $y = f(x)$의 점 $(a, f(a))$에서의 접선의 기울기 = $f'(a)$\n- 접선의 기울기를 구하려면 먼저 도함수를 구한 후, 주어진 점의 $x$좌표를 대입합니다.\n\n**[풀이]**\n\n**1단계: 주어진 점이 곡선 위의 점임을 확인**\n\n$y = x^3 - 3x^2 + 2$에 $x = 1$을 대입:\n$$y = 1^3 - 3(1)^2 + 2 = 1 - 3 + 2 = 0$$\n\n점 $(1, 0)$은 실제로 곡선 위의 점입니다. ✓\n\n**2단계: 도함수 구하기**\n\n$$y = x^3 - 3x^2 + 2$$\n$$y' = 3x^2 - 6x$$\n\n**3단계: $x = 1$에서의 도함수값 계산**\n\n점 $(1, 0)$에서의 접선의 기울기는:\n$$y'(1) = 3(1)^2 - 6(1) = 3 - 6 = -3$$\n\n따라서 접선의 기울기는 **$-3$**입니다.\n\n**[정답 확인]**\n점 $(1, 0)$에서의 도함수값 $y'(1) = 3 - 6 = -3$이 바로 그 점에서의 접선의 기울기이므로 정답은 ②번입니다.\n\n**[오답 분석]**\n- **①번 ($-6$)**: $y' = 3x^2 - 6x$를 $-6x$만 계산한 경우\n- **③번 ($-1$)**: 계산 오류로 나타날 수 있는 값\n- **④번 ($0$)**: $y'(1) = 0$이라고 잘못 계산한 경우 (실제로는 $-3$)\n- **⑤번 ($3$)**: 부호를 반대로 구한 경우\n\n**[핵심 포인트]**\n✓ **곡선 위의 점에서의 접선의 기울기 = 그 점에서의 도함수값**\n✓ 먼저 도함수를 구한 후, 주어진 점의 $x$좌표를 도함수에 대입하는 것이 핵심",
