    "explanation": "**[핵심 개념]**\n- 극값의 조건: $f'(x) = 0$인 점에서 극값을 가짐\n- 극솟값 판정: $f'(x) = 0$이고 $x$를 기준으로 $f'(x)$의 부호가 음에서 양으로 변할 때 극솟값\n- 함수값 조건: 극솟값이 특정 값이면 그 점에서의 함수값이 그 값과 같아야 함\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 + ax^2 + bx + 1$$\n$$f'(x) = 3x^2 + 2ax + b$$\n\n**2단계: 극솟값 조건 적용 - 도함수가 0**\n\n$x = 1$에서 극솟값을 가지므로 $f'(1) = 0$:\n$$f'(1) = 3(1)^2 + 2a(1) + b = 0$$\n$$3 + 2a + b = 0$$\n$$2a + b = -3 \\cdots (1)$$\n\n**3단계: 극솟값 조건 적용 - 함수값이 -1**\n\n$x = 1$에서 극솟값이 $-1$이므로 $f(1) = -1$:\n$$f(1) = 1^3 + a(1)^2 + b(1) + 1 = -1$$\n$$1 + a + b + 1 = -1$$\n$$a + b = -3 \\cdots (2)$$\n\n**4단계: 연립방정식 풀기**\n\n식 (1)과 식 (2)에서:\n- $(1): 2a + b = -3$\n- $(2): a + b = -3$\n\n$(1) - (2)$를 계산하면:\n$$2a + b - (a + b) = -3 - (-3)$$\n$$a = 0$$\n\n식 (2)에 $a = 0$을 대입:\n$$0 + b = -3$$\n$$b = -3$$\n\n**5단계: 극솟값 확인**\n\n$f'(x) = 3x^2 + 0 \\cdot x - 3 = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$\n\n- $x < -1$일 때: $f'(x) > 0$ (증가)\n- $-1 < x < 1$일 때: $f'(x) < 0$ (감소)\n- $x > 1$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = 1$에서 극솟값을 가짐 ✓\n\n**6단계: 답 구하기**\n$$a + b = 0 + (-3) = -3$$\n\n**[정답 확인]**\n$a = 0, b = -3$일 때 $f(1) = 1 + 0 - 3 + 1 = -1$(극솟값 조건 만족)이고 $f'(1) = 0$(극값 조건 만족)이므로 $a + b = -3$이 정답\n\n**[오답 분석]**\n- ① $-5$: $2a + b = -3$만 사용하여 잘못 계산한 경우\n- ② $-4$: 계산 실수로 $a + b$ 값을 잘못 구한 경우\n- ④ $-2$: 극솟값 조건 중 하나를 빠뜨린 경우\n- ⑤ $-1$: 함수값 조건을 제대로 적용하지 않은 경우\n\n**[핵심 포인트]**\n- 극값 문제는 **두 가지 조건**을 동시에 만족해야 함: ① $f'(x) = 0$ ② $f(x) = $ (극값)\n- 극값 조건 하나만으로는 상수를 결정할 수 없으므로 반드시 함수값 조건도 활용",
