    "answer": 2,
    "explanation": "**[핵심 개념]**\n극값을 구하기 위해 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호 변화를 통해 극대/극소를 판정합니다. 극댓값과 극솟값의 부호가 서로 다르다는 것은 하나는 양수, 하나는 음수라는 의미입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f'(x) = 3x^2 - 6x = 3x(x-2)$$\n\n**Step 2: 극값의 위치 찾기**\n$f'(x) = 0$에서 $x = 0$ 또는 $x = 2$\n\n- $x < 0$: $f'(x) > 0$ (증가)\n- $0 < x < 2$: $f'(x) < 0$ (감소)\n- $x > 2$: $f'(x) > 0$ (증가)\n\n따라서 $x = 0$에서 극댓값, $x = 2$에서 극솟값을 가집니다.\n\n**Step 3: 극댓값과 극솟값 계산**\n$$f(0) = 0 - 0 + k = k$$\n$$f(2) = 8 - 12 + k = k - 4$$\n\n극댓값: $f(0) = k$\n극솟값: $f(2) = k - 4$\n\n**Step 4: 부호가 서로 다른 조건**\n극댓값과 극솟값의 부호가 서로 다르려면, 한 값은 양수, 다른 하나는 음수여야 합니다.\n\n$$f(0) \\cdot f(2) < 0$$\n$$k(k-4) < 0$$\n\n이는 $0 < k < 4$를 의미합니다.\n\n**Step 5: 정수 k의 개수**\n$0 < k < 4$를 만족하는 정수는 $k = 1, 2, 3$\n\n따라서 정수 $k$의 개수는 **3개**입니다.\n\n**정답 확인**\n$k \\in \\{1, 2, 3\\}$일 때 극댓값 $k > 0$이고 극솟값 $k-4 < 0$이므로 부호가 서로 다릅니다.\n\n**오답 분석**\n- ① 1개: 한 개의 $k$ 값만 세운 경우\n- ② 2개: 조건을 잘못 해석하거나 경계값을 포함시킨 경우\n- ④ 4개: $0 \\leq k \\leq 4$ 범위로 잘못 계산한 경우\n- ⑤ 5개: 경계값을 모두 포함하거나 범위를 과대계산한 경우\n\n**[핵심 포인트]**\n두 수의 곱이 음수 ⟺ 두 수의 부호가 반대 ($a \\cdot b < 0$). 부등식 $k(k-4) < 0$을 풀 때 $0 < k < 4$이며, 정수는 1, 2, 3이라는 점을 정확히 파악하는 것이 중요합니다.",
