    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$이 되는 점에서 극값을 가지며, 그 점 전후로 도함수의 부호가 바뀌어야 합니다. 극댓값과 극솟값의 차이는 두 극값을 각각 구한 후 그 차를 계산합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 3ax$$\n$$f'(x) = 3x^2 - 3a$$\n\n**2단계: 극값을 갖는 점 찾기**\n$f'(x) = 0$에서:\n$$3x^2 - 3a = 0$$\n$$x^2 = a$$\n$$x = \\pm\\sqrt{a}$$ (단, $a > 0$)\n\n**3단계: 극값의 성질 판정**\n$f'(x) = 3(x^2 - a) = 3(x-\\sqrt{a})(x+\\sqrt{a})$\n\n- $x < -\\sqrt{a}$일 때: $f'(x) > 0$ (증가)\n- $-\\sqrt{a} < x < \\sqrt{a}$일 때: $f'(x) < 0$ (감소)\n- $x > \\sqrt{a}$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -\\sqrt{a}$에서 극댓값, $x = \\sqrt{a}$에서 극솟값을 가집니다.\n\n**4단계: 극댓값 계산**\n$$f(-\\sqrt{a}) = (-\\sqrt{a})^3 - 3a(-\\sqrt{a})$$\n$$= -a\\sqrt{a} + 3a\\sqrt{a} = 2a\\sqrt{a}$$\n\n**5단계: 극솟값 계산**\n$$f(\\sqrt{a}) = (\\sqrt{a})^3 - 3a(\\sqrt{a})$$\n$$= a\\sqrt{a} - 3a\\sqrt{a} = -2a\\sqrt{a}$$\n\n**6단계: 극댓값과 극솟값의 차이**\n$$\\text{극댓값} - \\text{극솟값} = 2a\\sqrt{a} - (-2a\\sqrt{a})$$\n$$= 2a\\sqrt{a} + 2a\\sqrt{a} = 4a\\sqrt{a}$$\n\n**[정답 확인]**\n극댓값 $2a\\sqrt{a}$에서 극솟값 $-2a\\sqrt{a}$를 빼면 $4a\\sqrt{a}$이므로 정답은 **②번**입니다.\n\n**[오답 분석]**\n- ① $2a\\sqrt{a}$: 극댓값만 구한 경우\n- ③ $6a\\sqrt{a}$: 계산 실수로 극값을 잘못 구한 경우\n- ④ $4a^2$: $a\\sqrt{a}$를 $a^2$로 잘못 계산한 경우\n- ⑤ $8a\\sqrt{a}$: 극값을 2배로 잘못 계산한 경우\n\n**[핵심 포인트]**\n대칭 함수는 극댓값과 극솟값이 부호가 반대이고 크기가 같습니다. 따라서 차이는 극값의 2배입니다. 도함수의 부호 변화를 정확히 파악하여 어느 점이 극댓값이고 어느 점이 극솟값인지 구분하는 것이 중요합니다.",
