    "answer": 2,
    "explanation": "**[핵심 개념]**\n$f(x) = 0$이 서로 다른 세 개의 실근을 가지려면, $f(x)$가 극댓값과 극솟값을 가져야 하고, 이 두 극값이 서로 다른 부호를 가져야 합니다. 즉, $f'(x) = 0$의 판별식 > 0이고, 극댓값 × 극솟값 < 0이어야 합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n$f'(x) = 0$일 때, $x = 1$ 또는 $x = 3$\n\n**2단계: 극값 구하기**\n\n극댓값 (at $x=1$):\n$$f(1) = 1 - 6 + 9 + a = 4 + a$$\n\n극솟값 (at $x=3$):\n$$f(3) = 27 - 54 + 27 + a = a$$\n\n**3단계: 서로 다른 세 근을 가질 조건**\n\n$f(x)$가 $x$축과 서로 다른 세 점에서 만나려면:\n- 극댓값 > 0 이고 극솟값 < 0\n- 또는 극댓값 < 0 이고 극솟값 > 0\n\n$f(1) = 4 + a$, $f(3) = a$이므로:\n\n$$f(1) > 0 \\text{ and } f(3) < 0$$\n$$4 + a > 0 \\text{ and } a < 0$$\n$$a > -4 \\text{ and } a < 0$$\n$$-4 < a < 0$$\n\n또는\n\n$$f(1) < 0 \\text{ and } f(3) > 0$$\n$$4 + a < 0 \\text{ and } a > 0$$\n\n이는 모순입니다. ($a < -4$이면서 $a > 0$일 수 없음)\n\n**4단계: 정수 $a$의 개수**\n\n$-4 < a < 0$을 만족하는 정수는:\n$$a \\in \\{-3, -2, -1\\}$$\n\n따라서 정수 $a$의 개수는 **3개**\n\n**[정답 확인]**\n$-4 < a < 0$ 범위에서 정수 $a$는 $-3, -2, -1$ 3개이고, 이들 값에서 극댓값과 극솟값의 부호가 반대이므로 $x$축과 서로 다른 세 점에서 만납니다.\n\n**[오답 분석]**\n- ① 1개: 범위 계산 실수 (한 개의 정수만 세는 경우)\n- ② 2개: $a = 0$ 또는 $a = -4$를 포함하는 실수 (경계값은 극값이 0이 되어 중근 발생)\n- ④ 4개: $a = 0$ 또는 $a = -4$를 경계값으로 포함하는 실수\n- ⑤ 5개: 범위를 너무 넓게 해석한 경우\n\n**[핵심 포인트]**\n극값의 부호 조건은 \"극댓값 × 극솟값 < 0\"이며, 경계값 $a = -4, 0$에서는 중근이 생기므로 **제외**해야 합니다. 부등호의 방향(< 또는 >)을 명확히 구분하는 것이 중요합니다.",
