    "problem": "곡선 $y = x^3 - 3x$ 위의 점 $(2, 2)$에서의 접선이 이 곡선과 만나는 다른 점의 $x$ 좌표를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": -4,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 방정식을 구하기 위해서는 그 점에서의 미분값(기울기)을 이용합니다. 곡선 $y = f(x)$의 점 $(a, f(a))$에서의 접선의 방정식은 $y - f(a) = f'(a)(x - a)$입니다. 이 접선이 원래 곡선과 만나는 점들은 접선의 방정식과 곡선의 방정식을 연립하여 구합니다.\n\n**[풀이]**\n\n**1단계: 점 (2, 2)가 곡선 위에 있는지 확인**\n$y = x^3 - 3x$에 $x = 2$를 대입하면:\n$$y = 2^3 - 3(2) = 8 - 6 = 2$$\n따라서 점 $(2, 2)$는 곡선 위의 점입니다.\n\n**2단계: 점 (2, 2)에서의 접선의 기울기 구하기**\n$$y' = 3x^2 - 3$$\n$x = 2$일 때:\n$$y'(2) = 3(2)^2 - 3 = 12 - 3 = 9$$\n\n**3단계: 접선의 방정식 구하기**\n점 $(2, 2)$를 지나고 기울기가 9인 직선의 방정식:\n$$y - 2 = 9(x - 2)$$\n$$y = 9x - 18 + 2$$\n$$y = 9x - 16$$\n\n**4단계: 접선과 곡선의 교점 구하기**\n곡선의 방정식 $y = x^3 - 3x$와 접선의 방정식 $y = 9x - 16$을 연립:\n$$x^3 - 3x = 9x - 16$$\n$$x^3 - 3x - 9x + 16 = 0$$\n$$x^3 - 12x + 16 = 0$$\n\n**5단계: 3차 방정식 풀기**\n$x = 2$는 접점이므로 이 방정식의 한 근입니다. 확인해보면:\n$$2^3 - 12(2) + 16 = 8 - 24 + 16 = 0$$ ✓\n\n$(x - 2)$로 인수분해:\n$$x^3 - 12x + 16 = (x - 2)(x^2 + 2x - 8)$$\n\n$x^2 + 2x - 8 = 0$을 풀기:\n$$x^2 + 2x - 8 = (x + 4)(x - 2) = 0$$\n$$x = -4 \\text{ 또는 } x = 2$$\n\n따라서:\n$$x^3 - 12x + 16 = (x - 2)^2(x + 4) = 0$$\n\n**6단계: 다른 교점의 x좌표**\n$x = 2$는 접점(중근)이고, 다른 교점의 $x$좌표는 $x = -4$입니다.\n\n**[정답 확인]**\n$x = -4$를 원래 곡선에 대입하면 $y = (-4)^3 - 3(-4) = -64 + 12 = -52$이고, 접선에 대입하면 $y = 9(-4) - 16 = -36 - 16 = -52$로 같으므로 올바른 교점입니다.\n\n**[오답 분석]**\n문제에서 선택지가 제시되지 않았으나, 흔한 오답으로는:\n- $x = 2$ : 접점을 구하는 것으로, 문제에서 요구하는 \"다른 점\"이 아님\n- $x = 4$ : 계산 실수로 인수분해를 잘못한 경우\n\n**[핵심 포인트]**\n접선이 곡선과 만나는 점 중 접점은 중근이 되므로, 3차 방정식은 $(x - a)^2(x - b) = 0$ 형태로 인수분해됩니다. 접점이 아닌 \"다른 점\"의 좌표를 구할 때는 중근이 아닌 단순근을 찾아야 합니다.",
