    "answer": 2,
    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최댓값과 최솟값을 구하는 방법:\n1. 함수 $f(x)$의 도함수 $f'(x)$를 구한다.\n2. $f'(x) = 0$인 임계점을 찾는다.\n3. 임계점과 구간의 양 끝점에서 함수값을 계산한다.\n4. 계산된 값들 중 최댓값과 최솟값을 찾는다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = 2x^3 - 9x^2 + 12x$$\n$$f'(x) = 6x^2 - 18x + 12$$\n\n**Step 2: 임계점 찾기**\n$f'(x) = 0$이 되는 점을 구한다.\n$$6x^2 - 18x + 12 = 0$$\n$$x^2 - 3x + 2 = 0$$\n$$(x - 1)(x - 2) = 0$$\n$$x = 1 \\text{ 또는 } x = 2$$\n\n두 임계점 모두 구간 $[0, 3]$ 내에 있다.\n\n**Step 3: 함수값 계산**\n구간 양 끝점과 임계점에서 함수값을 계산한다.\n\n$x = 0$일 때:\n$$f(0) = 2(0)^3 - 9(0)^2 + 12(0) = 0$$\n\n$x = 1$일 때:\n$$f(1) = 2(1)^3 - 9(1)^2 + 12(1) = 2 - 9 + 12 = 5$$\n\n$x = 2$일 때:\n$$f(2) = 2(2)^3 - 9(2)^2 + 12(2) = 16 - 36 + 24 = 4$$\n\n$x = 3$일 때:\n$$f(3) = 2(3)^3 - 9(3)^2 + 12(3) = 54 - 81 + 36 = 9$$\n\n**Step 4: 최댓값과 최솟값 찾기**\n계산된 함수값: $f(0) = 0$, $f(1) = 5$, $f(2) = 4$, $f(3) = 9$\n\n- 최댓값: $f(3) = 9$\n- 최솟값: $f(0) = 0$\n\n**Step 5: 합 구하기**\n$$\\text{최댓값} + \\text{최솟값} = 9 + 0 = 9$$\n\n**[정답 확인]**\n구간 $[0, 3]$에서 함수의 모든 임계점과 끝점을 비교하여 최댓값 9, 최솟값 0을 구했으므로 합은 9이다.\n\n**[오답 분석]**\n- ① 5: 임계점 $x=1$에서의 함수값만 선택한 경우\n- ② 7: 계산 과정에서 함수값을 잘못 구한 경우\n- ④ 13: $f(1) + f(3) = 5 + 9 = 14$의 오타 또는 $f(0) + f(3)$에서 실수한 경우\n- ⑤ 14: $f(1) + f(3) = 5 + 9 = 14$로 임계점에서의 값만 더한 경우\n\n**[핵심 포인트]**\n폐구간에서 최댓값·최솟값을 구할 때는 반드시 **임계점뿐 아니라 구간의 양 끝점도 확인**해야 한다. 이 문제에서 최솟값은 끝점 $x=0$에서 나타났다.",
