    "answer": 32,
    "explanation": "**[핵심 개념]**\n\n삼차함수의 극값 조건을 이용한 문제입니다.\n- 최고차항의 계수가 1인 삼차함수: $f(x) = x^3 + ax^2 + bx + c$ 형태\n- $f(1) = f(3) = 0$: $x = 1, 3$이 근\n- $x = 1$에서 극대: $f'(1) = 0$이고, $x = 1$ 좌측에서 $f'(x) > 0$, 우측에서 $f'(x) < 0$\n- 삼차함수가 두 개의 근을 가지면, 극값은 두 근 사이에 위치\n\n**[풀이]**\n\n**Step 1: 함수의 형태 결정**\n\n$f(1) = f(3) = 0$이므로, $f(x) = (x-1)(x-3)(x-r)$ 형태입니다.\n\n최고차항의 계수가 1이므로:\n$$f(x) = (x-1)(x-3)(x-r)$$\n\n**Step 2: 극대 조건 적용**\n\n$f(x)$를 전개하면:\n$$f(x) = (x-1)(x-3)(x-r) = (x^2 - 4x + 3)(x-r)$$\n$$f(x) = x^3 - rx^2 - 4x^2 + 4rx + 3x - 3r$$\n$$f(x) = x^3 - (r+4)x^2 + (4r+3)x - 3r$$\n\n도함수:\n$$f'(x) = 3x^2 - 2(r+4)x + (4r+3)$$\n\n$x = 1$에서 극대이므로 $f'(1) = 0$:\n$$f'(1) = 3 - 2(r+4) + (4r+3) = 0$$\n$$3 - 2r - 8 + 4r + 3 = 0$$\n$$2r - 2 = 0$$\n$$r = 1$$\n\n**Step 3: 극대 조건 확인**\n\n$r = 1$이면 $f(x) = (x-1)^2(x-3)$\n\n$f'(x) = 2(x-1)(x-3) + (x-1)^2 = (x-1)[2(x-3) + (x-1)]$\n$$f'(x) = (x-1)(3x-7)$$\n\n극값은 $x = 1, x = \\frac{7}{3}$에서 발생합니다.\n\n- $x < 1$: $f'(x) > 0$ (증가)\n- $1 < x < \\frac{7}{3}$: $f'(x) < 0$ (감소)\n- $x > \\frac{7}{3}$: $f'(x) > 0$ (증가)\n\n따라서 $x = 1$에서 극대 ✓\n\n**Step 4: $f(5)$ 계산**\n\n$$f(x) = (x-1)^2(x-3)$$\n\n$$f(5) = (5-1)^2(5-3) = 4^2 \\times 2 = 16 \\times 2 = 32$$\n\n**[정답 확인]**\n\n$f(x) = (x-1)^2(x-3)$이 모든 조건(최고차 계수 1, $f(1) = f(3) = 0$, $x=1$에서 극대)을 만족하며, $f(5) = 32$입니다.\n\n**[오답 분석]**\n\n객관식 선택지가 제시되지 않았으므로, 흔한 계산 실수:\n- $r = 3$으로 잘못 설정: $f(x) = (x-1)(x-3)^2$ → $x = 3$에서 극대 (오류)\n- 극대 조건을 극소로 혼동하거나 미분 계산 오류 발생 가능\n\n**[핵심 포인트]**\n\n1. 삼차함수가 두 근을 가질 때, 중근과 단순근의 위치에 따라 극값의 위치가 결정된다.\n2. 극대/극소 조건은 도함수의 부호 변화를 통해 반드시 확인해야 한다.",
