    "explanation": "**[핵심 개념]**\n극값을 가지는 조건: 함수 $f(x)$가 $x = p$에서 극값을 가지려면 $f'(p) = 0$이어야 한다.\n- $x = -1$에서 극댓값 5: $f'(-1) = 0$이고 $f(-1) = 5$\n- $x = 1$에서 극솟값 1: $f'(1) = 0$이고 $f(1) = 1$\n\n도함수의 성질: $f'(x) = 3x^2 + 2ax + b$\n\n**[풀이]**\n\n**Step 1: 극값 조건에서 $a, b$ 구하기**\n\n$f'(x) = 3x^2 + 2ax + b$\n\n극댓값과 극솟값 조건에서:\n$$f'(-1) = 3 - 2a + b = 0 \\cdots (1)$$\n$$f'(1) = 3 + 2a + b = 0 \\cdots (2)$$\n\n식 $(1)$과 $(2)$를 더하면:\n$$6 + 2b = 0$$\n$$b = -3$$\n\n식 $(2) - (1)$을 계산하면:\n$$4a = 0$$\n$$a = 0$$\n\n**Step 2: 극값 조건에서 $c$ 구하기**\n\n$f(-1) = 5$:\n$$(-1)^3 + 0 \\cdot (-1)^2 + (-3)(-1) + c = 5$$\n$$-1 + 3 + c = 5$$\n$$c = 3$$\n\n검증: $f(1) = 1^3 + 0 \\cdot 1^2 + (-3) \\cdot 1 + 3 = 1 - 3 + 3 = 1$ ✓\n\n**Step 3: $a + b + c$ 계산**\n\n$$a + b + c = 0 + (-3) + 3 = 0$$\n\n**[정답 확인]**\n$a = 0, b = -3, c = 3$을 모두 조건식에 대입하면 극댓값과 극솟값 조건을 완벽히 만족하므로 $a + b + c = 0$이 정답이다.\n\n**[오답 분석]**\n- ① $-1$: $c$ 값을 잘못 계산하거나 부호 오류\n- ③ $1$: $b$ 값을 잘못 계산 (예: $b = -2$로 오류)\n- ④ $2$: 극값 조건을 하나만 사용하거나 불완전한 계산\n- ⑤ $3$: $a$ 값을 무시하고 $b + c$만 더함\n\n**[핵심 포인트]**\n극값 조건에서 나오는 연립방정식 $f'(p) = 0$들을 연립하여 계수를 구하는 것이 핵심이며, 반드시 극값의 함숫값 조건 $f(p) = $ (극값)을 함께 사용하여 상수항을 결정해야 한다.",
