    "explanation": "**[핵심 개념]**\n곡선 위의 점에서의 접선을 구하기 위해서는 다음 세 가지를 이용합니다:\n1. 접점에서의 미분값(도함수)이 접선의 기울기입니다\n2. 접선의 방정식: $y - y_1 = m(x - x_1)$ (기울기 $m$, 접점 $(x_1, y_1)$)\n3. $y$절편은 $x=0$을 접선의 방정식에 대입하여 구합니다\n\n**[풀이]**\n\n**Step 1: 접점의 $x$좌표 구하기**\n\n곡선 $y = x^3 - 3x^2$를 미분하면:\n$$y' = 3x^2 - 6x$$\n\n기울기가 9인 접선이 있으므로, 접점에서:\n$$3x^2 - 6x = 9$$\n$$3x^2 - 6x - 9 = 0$$\n$$x^2 - 2x - 3 = 0$$\n$$(x-3)(x+1) = 0$$\n\n따라서 $x = 3$ 또는 $x = -1$\n\n**Step 2: 각 접점의 $y$좌표 구하기**\n\n$x = 3$일 때:\n$$y = 3^3 - 3(3)^2 = 27 - 27 = 0$$\n접점: $(3, 0)$\n\n$x = -1$일 때:\n$$y = (-1)^3 - 3(-1)^2 = -1 - 3 = -4$$\n접점: $(-1, -4)$\n\n**Step 3: 각 접선의 방정식 구하기**\n\n접점 $(3, 0)$에서의 접선:\n$$y - 0 = 9(x - 3)$$\n$$y = 9x - 27$$\n$y$절편: $-27$\n\n접점 $(-1, -4)$에서의 접선:\n$$y - (-4) = 9(x - (-1))$$\n$$y + 4 = 9(x + 1)$$\n$$y = 9x + 9 - 4$$\n$$y = 9x + 5$$\n$y$절편: $5$\n\n**Step 4: $y$절편의 합 구하기**\n\n$$(-27) + 5 = -22$$\n\n**[정답 확인]**\n기울기 9인 접선은 2개이며, 각각의 $y$절편 $-27$과 $5$의 합이 $-22$이므로 정답입니다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 없음\n\n**[핵심 포인트]**\n- 주어진 기울기를 가진 접선은 여러 개일 수 있으므로, 도함수를 설정한 방정식에서 나오는 **모든 해를 구해야** 합니다\n- 각각의 접점에 대응하는 $y$절편을 모두 구한 후 합하는 것이 이 문제의 핵심입니다",
