    "explanation": "**[핵심 개념]**\n합성함수 방정식 $f(f(x)) = 0$을 풀기 위해서는 단계적 접근이 필요합니다.\n- 먼저 $f(t) = 0$의 근을 구합니다.\n- 그 다음 각 근에 대해 $f(x) = $(그 근)의 해를 구합니다.\n- 3차 함수의 그래프 개형을 이용하여 교점의 개수를 파악합니다.\n\n**[풀이]**\n\n**Step 1: $f(x) = x^3 - 3x$의 기본 성질 파악**\n\n$f(x) = x^3 - 3x = x(x^2 - 3) = x(x-\\sqrt{3})(x+\\sqrt{3})$\n\n$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$\n\n극값: $f(-1) = -1 + 3 = 2$ (극대), $f(1) = 1 - 3 = -2$ (극소)\n\n**Step 2: $f(f(x)) = 0$을 $f(t) = 0$으로 변환**\n\n$f(f(x)) = 0$은 $f(t) = 0$을 만족하는 $t$에 대해 $f(x) = t$를 푸는 것과 같습니다.\n\n$f(t) = 0$의 해: $t = 0, \\sqrt{3}, -\\sqrt{3}$\n\n**Step 3: 각각의 방정식 $f(x) = t$의 실근 개수 파악**\n\n$y = f(x)$의 그래프에서:\n- 극댓값: $f(-1) = 2$\n- 극솟값: $f(1) = -2$\n- $0 < \\sqrt{3} < 2$이므로 $\\sqrt{3} \\approx 1.732$\n\n**Case 1: $f(x) = 0$**\n$x = 0, \\sqrt{3}, -\\sqrt{3}$ → **3개의 실근**\n\n**Case 2: $f(x) = \\sqrt{3}$**\n$0 < \\sqrt{3} < 2$이고, $\\sqrt{3}$은 극댓값 2와 극솟값 -2 사이에 있으므로:\n- $x < -1$ 구간에서 1개\n- $-1 < x < 1$ 구간에서 1개  \n- $x > 1$ 구간에서 1개\n→ **3개의 실근**\n\n**Case 3: $f(x) = -\\sqrt{3}$**\n$-2 < -\\sqrt{3} < 0$이므로:\n- $x < -1$ 구간에서 1개\n- $-1 < x < 1$ 구간에서 1개\n- $x > 1$ 구간에서 1개\n→ **3개의 실근**\n\n**Step 4: 중복 확인**\n\n세 방정식 $f(x) = 0$, $f(x) = \\sqrt{3}$, $f(x) = -\\sqrt{3}$의 근들이 서로 다른지 확인해야 합니다.\n\n$f(x) = 0$의 근인 $x = 0, \\pm\\sqrt{3}$에 대해:\n- $f(0) = 0 \\neq \\sqrt{3}, -\\sqrt{3}$\n- $f(\\sqrt{3}) = 3\\sqrt{3} - 3\\sqrt{3} = 0 \\neq \\sqrt{3}, -\\sqrt{3}$\n- $f(-\\sqrt{3}) = 0 \\neq \\sqrt{3}, -\\sqrt{3}$\n\n따라서 모든 근이 서로 다릅니다.\n\n**총 실근의 개수: $3 + 3 + 3 = 9$개**\n\n**[정답 확인]**\n3차 함수의 세 근 각각에 대해 $f(x) = t$ 형태의 방정식이 일반적으로 3개씩의 실근을 가지며, 이들이 중복되지 않으므로 총 9개입니다.\n\n**[오답 분석]**\n- ① 3개: $f(x) = 0$의 근의 개수만 센 경우\n- ② 5개: 일부 경우만 고려하거나 계산 실수가 있는 경우\n- ③ 7개: 중복을 잘못 처리한 경우\n- ⑤ 11개: 존재하지 않는 근을 추가로 센 경우\n\n**[핵심 포인트]**\n합성함수 방정식은 **단계적으로 내부 방정식의 근을 먼저 구하고**, 각 근에 대해 외부 방정식의 해의 개수를 세어야 합니다. 3차 함수의 극값이 중요한 역할을 합니다.",
