    "explanation": "**[핵심 개념]**\n절댓값 함수의 그래프를 그리기 위해서는 먼저 절댓값 안의 식이 0이 되는 지점을 찾아 함수의 부호를 결정해야 합니다. $f(x) = |g(x)|$ 형태에서 $y = k$ (수평선)와의 교점의 개수는 그래프를 그려서 시각적으로 파악합니다. 특히 극값과 부호가 바뀌는 지점이 중요합니다.\n\n**[풀이]**\n\n**1단계: $g(x) = x^3 - 3x$의 성질 파악**\n\n$g(x) = x^3 - 3x = x(x^2 - 3) = x(x-\\sqrt{3})(x+\\sqrt{3})$\n\n$g'(x) = 3x^2 - 3 = 3(x^2-1) = 3(x-1)(x+1)$\n\n극값: $x = -1$일 때 $g(-1) = -1 + 3 = 2$ (극대)\n       $x = 1$일 때 $g(1) = 1 - 3 = -2$ (극소)\n\n**2단계: $g(x) = 0$인 점**\n\n$x = -\\sqrt{3}, 0, \\sqrt{3}$에서 0\n\n**3단계: $f(x) = |x^3 - 3x|$의 그래프 특성**\n\n- $x < -\\sqrt{3}$: $g(x) < 0$ → $f(x) = -g(x)$\n- $-\\sqrt{3} < x < 0$: $g(x) > 0$ → $f(x) = g(x)$\n- $0 < x < \\sqrt{3}$: $g(x) < 0$ → $f(x) = -g(x)$\n- $x > \\sqrt{3}$: $g(x) > 0$ → $f(x) = g(x)$\n\n**4단계: $f(x)$의 주요값**\n\n- $f(-1) = |2| = 2$ (극대값)\n- $f(0) = 0$\n- $f(1) = |-2| = 2$ (극대값)\n- $f(-\\sqrt{3}) = f(\\sqrt{3}) = 0$\n\n**5단계: 근의 개수 판단**\n\n$f(x) = k$의 근의 개수는:\n- $k = 0$: 3개의 근\n- $0 < k < 2$: 6개의 근\n- $k = 2$: **5개의 근** ← 극댓값에서 수평선이 그래프에 접함\n- $k > 2$: 2개의 근\n\n$k = 2$일 때, $y = 2$ 직선이 $x = -1$과 $x = 1$에서 극댓값을 지나고, 이 외에도 3개의 점에서 만나므로 총 5개의 서로 다른 실근을 가집니다.\n\n**[정답 확인]**\n\n$k = 2$는 $f(x)$의 극댓값이므로, 이 높이의 수평선이 정확히 5개의 점에서 그래프와 만나게 됩니다.\n\n**[오답 분석]**\n\n- ① $k=1$: $0 < 1 < 2$ 범위에서 6개의 근을 가짐\n- ③ $k=3$: $3 > 2$ 범위에서 2개의 근을 가짐\n- ④ $k=4$: $4 > 2$ 범위에서 2개의 근을 가짐\n- ⑤ $k=5$: $5 > 2$ 범위에서 2개의 근을 가짐\n\n**[핵심 포인트]**\n\n절댓값 함수 $f(x) = |g(x)|$에서 근의 개수가 최대 또는 특정값이 되려면 **극값 위치**에서의 $k$값을 확인해야 합니다. 특히 극댓값 $k = 2$에서 수평선이 그래프의 극대점에 접하면서 추가 교점이 생겨 5개의 근이 됩니다.",
