    "answer": 10,
    "explanation": "**[핵심 개념]**\n- 사차함수의 일반형: $f(x) = x^4 + ax^3 + bx^2 + cx + d$ (최고차항의 계수가 1)\n- 도함수: $f'(x) = 4x^3 + 3ax^2 + 2bx + c$\n- 주어진 조건들(함수값, 도함수값)을 연립하여 미지수를 결정하는 방법\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n\n$f(x) = x^4 + ax^3 + bx^2 + cx + d$로 놓으면\n$f'(x) = 4x^3 + 3ax^2 + 2bx + c$\n\n주어진 조건:\n- $f'(0) = 0 \\Rightarrow c = 0$\n- $f'(2) = 0 \\Rightarrow 4(8) + 3a(4) + 2b(2) = 0 \\Rightarrow 32 + 12a + 4b = 0$\n- $f(0) = 1 \\Rightarrow d = 1$\n- $f(2) = 1 \\Rightarrow 16 + 8a + 4b + 2c + d = 1$\n\n**Step 2: $c = 0$, $d = 1$ 대입**\n\n$f(x) = x^4 + ax^3 + bx^2 + 1$\n\n$f'(2) = 0$에서:\n$$32 + 12a + 4b = 0$$\n$$8 + 3a + b = 0 \\quad \\cdots (1)$$\n\n$f(2) = 1$에서:\n$$16 + 8a + 4b + 1 = 1$$\n$$16 + 8a + 4b = 0$$\n$$4 + 2a + b = 0 \\quad \\cdots (2)$$\n\n**Step 3: 연립방정식 풀이**\n\n식 (1)에서: $b = -8 - 3a$\n\n이를 식 (2)에 대입:\n$$4 + 2a + (-8 - 3a) = 0$$\n$$4 + 2a - 8 - 3a = 0$$\n$$-4 - a = 0$$\n$$a = -4$$\n\n따라서:\n$$b = -8 - 3(-4) = -8 + 12 = 4$$\n\n**Step 4: 함수 결정 및 $f(3)$ 계산**\n\n$$f(x) = x^4 - 4x^3 + 4x^2 + 1$$\n\n검증:\n- $f(0) = 1$ ✓\n- $f(2) = 16 - 32 + 16 + 1 = 1$ ✓\n- $f'(x) = 4x^3 - 12x^2 + 8x = 4x(x^2 - 3x + 2) = 4x(x-1)(x-2)$\n- $f'(0) = 0$, $f'(2) = 0$ ✓\n\n$$f(3) = 81 - 4(27) + 4(9) + 1 = 81 - 108 + 36 + 1 = 10$$\n\n**[정답 확인]**\n모든 조건을 만족하는 사차함수 $f(x) = x^4 - 4x^3 + 4x^2 + 1$에서 $f(3) = 10$이 유일하게 결정된다.\n\n**[오답 분석]**\n객관식이 아니므로 생략 (단답형)\n\n**[핵심 포인트]**\n- 주어진 조건을 이용해 단계적으로 미지수를 소거하는 것이 핵심\n- $f'(0) = 0$에서 즉시 $c = 0$을 얻을 수 있으므로 계산을 간소화할 수 있음을 놓치지 말기",
