    "type": "복합킬러",
    "problem": "최고차항의 계수가 1인 삼차함수 $f(x)$가 $f(0) = 0$, $f(2) = 0$, $f'(0) = 0$을 만족시킬 때, $f(4)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 32,
    "explanation": "**[핵심 개념]**\n- 최고차항의 계수가 1인 삼차함수는 $f(x) = x^3 + ax^2 + bx + c$ 형태\n- 함수의 영점(근)이 주어지면, 인수분해 형태로 표현 가능: $f(x) = (x - \\alpha)(x - \\beta)(x - \\gamma)$\n- 도함수 $f'(x)$를 이용하여 조건을 만족하는 계수 결정\n- 주어진 조건들을 연립하여 미지수 해결\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n- 최고차항의 계수가 1인 삼차함수: $f(x) = x^3 + ax^2 + bx + c$\n- $f(0) = 0$ → $c = 0$\n- $f(2) = 0$ → $8 + 4a + 2b = 0$ ... (1)\n- $f'(0) = 0$ → $b = 0$\n\n**Step 2: 조건으로부터 미지수 구하기**\n\n$f'(x) = 3x^2 + 2ax + b$이므로\n$f'(0) = b = 0$\n\n식 (1)에 $b = 0$을 대입:\n$$8 + 4a = 0$$\n$$a = -2$$\n\n따라서 $f(x) = x^3 - 2x^2$\n\n**Step 3: 함수 재표현**\n\n$f(x) = x^3 - 2x^2 = x^2(x - 2)$\n\n이는 $x = 0$ (중근)과 $x = 2$를 근으로 가지므로 조건 $f(0) = 0$, $f(2) = 0$을 만족합니다.\n\n**Step 4: 도함수 확인**\n\n$f'(x) = 3x^2 - 4x = x(3x - 4)$\n\n$f'(0) = 0$ ✓\n\n**Step 5: $f(4)$ 계산**\n\n$$f(4) = 4^3 - 2 \\cdot 4^2 = 64 - 32 = 32$$\n\n**[정답 확인]**\n\n$f(x) = x^3 - 2x^2$는 모든 조건 $f(0) = 0$, $f(2) = 0$, $f'(0) = 0$을 만족하며, $f(4) = 32$이다.\n\n**[오답 분석]**\n\n객관식이 아니므로 해당 없음 (단답형 문제)\n\n**[핵심 포인트]**\n- 삼차함수의 두 근 조건($f(0) = 0$, $f(2) = 0$)과 도함수 조건($f'(0) = 0$)을 결합하면 함수가 유일하게 결정된다.\n- $f'(0) = 0$은 $x = 0$에서 극값을 가지며, $f(0) = 0$과 함께 $x = 0$이 중근임을 시사한다.",
