    "problem": "최고차항의 계수가 1인 삼차함수 $f(x)$와 일차함수 $g(x) = 2x - 1$에 대하여 $h(x) = f(x) - g(x)$가 $x = 1$에서 극솟값 0을 가지고 $x = -1$에서 극대일 때, $f(5)$의 값을 구하시오.",
    "answerType": "short",
