    "answer": 121,
    "explanation": "**[핵심 개념]**\n\n1. 삼차함수의 극값: 함수 $f(x)$가 $x=a$에서 극값을 가지면 $f'(a)=0$\n2. 극솟값과 극대값의 조건: $h(x)$가 $x=1$에서 극솟값, $x=-1$에서 극대값을 가지면 $h'(x)$는 $x=-1, 1$을 근으로 가지고, $x=1$ 근처에서 부호가 음→양, $x=-1$ 근처에서 양→음으로 변함\n3. 최고차항의 계수가 1인 삼차함수: $f(x) = x^3 + ax^2 + bx + c$ 형태\n\n**[풀이]**\n\n**Step 1: $h(x)$의 도함수 설정**\n\n$f(x) = x^3 + ax^2 + bx + c$ (최고차항의 계수가 1)\n\n$g(x) = 2x - 1$\n\n$h(x) = f(x) - g(x) = x^3 + ax^2 + bx + c - 2x + 1 = x^3 + ax^2 + (b-2)x + (c+1)$\n\n$h'(x) = 3x^2 + 2ax + (b-2)$\n\n**Step 2: 극값 조건 활용**\n\n$h(x)$가 $x=-1$과 $x=1$에서 극값을 가지므로:\n$$h'(-1) = 0, \\quad h'(1) = 0$$\n\n$h'(-1) = 3 - 2a + (b-2) = 0$\n$$-2a + b + 1 = 0 \\quad \\cdots (1)$$\n\n$h'(1) = 3 + 2a + (b-2) = 0$\n$$2a + b + 1 = 0 \\quad \\cdots (2)$$\n\n**Step 3: 연립방정식 풀이**\n\n(1)에서: $b = 2a - 1$\n\n(2)에 대입: $2a + (2a-1) + 1 = 0$\n$$4a = 0 \\quad \\Rightarrow \\quad a = 0$$\n\n따라서 $b = -1$\n\n**Step 4: 극솟값 조건 활용**\n\n$h(x)$가 $x=1$에서 극솟값 0을 가지므로:\n$$h(1) = 0$$\n\n$$h(1) = 1 + 0 - 1 + (c+1) = 0$$\n$$c + 1 = 0 \\quad \\Rightarrow \\quad c = -1$$\n\n**Step 5: $f(x)$ 결정**\n\n$$f(x) = x^3 - x - 1$$\n\n검증: $h(x) = x^3 - 3x$, $h'(x) = 3x^2 - 3 = 3(x^2-1)$\n- $x=1$에서 극솟값: $h(1) = 1 - 3 = -2$ (극솟값 확인) ✓\n- 실제로 $h(1) = 0$이려면 다시 확인\n\n재계산: $h(x) = x^3 - x - 1 - (2x-1) = x^3 - 3x$, $h(1) = -2$ ≠ 0\n\n다시: $h(1) = 1 + a + (b-2) + (c+1) = a + b + c = 0$에서 $0 - 1 + c = 0$, $c=1$\n\n$$f(x) = x^3 - x + 1$$\n\n**Step 6: $f(5)$ 계산**\n\n$$f(5) = 5^3 - 5 + 1 = 125 - 5 + 1 = 121$$\n\n**[정답 확인]**\n\n$f(x) = x^3 - x + 1$일 때 $h'(x) = 3(x^2-1)$로 $x=\\pm 1$에서 극값을 가지며, $h(1) = 1-1-1+2 = 1-3 = 0$이므로 조건을 만족합니다.\n\n**[핵심 포인트]**\n\n극값의 위치 $x=-1, 1$로부터 $h'(x) = 3(x+1)(x-1)$ 형태를 얻고, 극솟값이 0이라는 조건으로 상수항을 결정하는 것이 핵심입니다.",
