    "explanation": "**[핵심 개념]**\n이 문제는 $x = -1$을 직접 대입하면 $\\frac{0}{0}$ 꼴의 부정형이 되므로, 인수분해를 이용하여 식을 간단히 한 후 극한값을 구하는 문제입니다. \n\n핵심 공식: $a^3 + b^3 = (a+b)(a^2 - ab + b^2)$ (합의 세제곱 공식)\n\n**[풀이]**\n\n**Step 1: 부정형 확인**\n$x = -1$을 직접 대입하면:\n$$\\frac{(-1)^3 + 1}{-1 + 1} = \\frac{-1 + 1}{0} = \\frac{0}{0}$$\n$\\frac{0}{0}$ 꼴의 부정형이므로 인수분해가 필요합니다.\n\n**Step 2: 분자를 인수분해**\n분자를 합의 세제곱 공식으로 인수분해합니다:\n$$x^3 + 1 = x^3 + 1^3 = (x+1)(x^2 - x + 1)$$\n\n검증: $(x+1)(x^2 - x + 1) = x^3 - x^2 + x + x^2 - x + 1 = x^3 + 1$ ✓\n\n**Step 3: 약분**\n$$\\frac{x^3 + 1}{x + 1} = \\frac{(x+1)(x^2 - x + 1)}{x + 1}$$\n\n$x \\to -1$일 때 $x \\neq -1$이므로 $(x+1)$으로 약분 가능:\n$$= x^2 - x + 1 \\quad (x \\neq -1)$$\n\n**Step 4: 극한값 계산**\n$$\\lim_{x \\to -1} \\frac{x^3 + 1}{x + 1} = \\lim_{x \\to -1} (x^2 - x + 1)$$\n\n$x = -1$을 대입:\n$$= (-1)^2 - (-1) + 1 = 1 + 1 + 1 = 3$$\n\n**[정답 확인]**\n인수분해를 통해 분자와 분모의 공통인수 $(x+1)$을 약분한 후, $x = -1$을 대입하면 정확히 3이 나옵니다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 실수 패턴:\n- **1**: $x^2$ 항만 계산한 경우 ($(-1)^2 = 1$)\n- **2**: $x^2 - x$ 항만 계산한 경우 ($1 + 1 = 2$)\n- **-3**: 부호 계산 실수로 $-1 - (-1) + 1$ 같은 잘못된 계산\n- **0**: 극한이 존재하지 않는다고 판단한 경우\n\n**[핵심 포인트]**\n$\\frac{0}{0}$ 꼴의 부정형은 **인수분해**나 **유리화** 등으로 공통인수를 제거한 후 극한을 구합니다. 특히 $x^3 + a^3 = (x+a)(x^2 - ax + a^2)$ 공식은 자주 나오므로 반드시 암기하세요.",
