    "answer": 1,
    "explanation": "**[핵심 개념]**\n$x \\to \\infty$일 때 유리함수의 극한을 구할 때는 분자와 분모의 최고차항만 비교하면 된다. 분자와 분모를 최고차항으로 나누어 극한을 계산하면, 분자와 분모의 최고차 계수의 비가 극한값이 된다.\n\n**[풀이]**\n\n주어진 극한식: $\\lim_{x \\to \\infty} \\dfrac{5x^3 - 2x}{3x^3 + x^2 + 1}$\n\n**Step 1: 분자와 분모의 최고차항 확인**\n- 분자의 최고차항: $5x^3$\n- 분모의 최고차항: $3x^3$\n- 둘 다 3차이므로 극한값이 존재한다.\n\n**Step 2: 분자와 분모를 최고차항 $x^3$으로 나누기**\n\n$$\\lim_{x \\to \\infty} \\dfrac{5x^3 - 2x}{3x^3 + x^2 + 1} = \\lim_{x \\to \\infty} \\dfrac{\\dfrac{5x^3 - 2x}{x^3}}{\\dfrac{3x^3 + x^2 + 1}{x^3}}$$\n\n**Step 3: 각 항을 $x^3$으로 나누기**\n\n분자: $\\dfrac{5x^3 - 2x}{x^3} = \\dfrac{5x^3}{x^3} - \\dfrac{2x}{x^3} = 5 - \\dfrac{2}{x^2}$\n\n분모: $\\dfrac{3x^3 + x^2 + 1}{x^3} = \\dfrac{3x^3}{x^3} + \\dfrac{x^2}{x^3} + \\dfrac{1}{x^3} = 3 + \\dfrac{1}{x} + \\dfrac{1}{x^3}$\n\n**Step 4: $x \\to \\infty$일 때 극한 계산**\n\n$$\\lim_{x \\to \\infty} \\dfrac{5 - \\dfrac{2}{x^2}}{3 + \\dfrac{1}{x} + \\dfrac{1}{x^3}} = \\dfrac{5 - 0}{3 + 0 + 0} = \\dfrac{5}{3}$$\n\n**[정답 확인]**\n분자와 분모가 같은 차수(3차)이므로 극한값은 최고차 계수의 비인 $\\frac{5}{3}$이다.\n\n**[오답 분석]**\n- ① $\\frac{2}{3}$: 분자의 계수 2와 분모의 계수 3을 비교하는 오류\n- ③ $\\frac{3}{5}$: 최고차 계수를 역순으로 나눈 경우\n- ④ 5: 분자의 최고차 계수만 고려한 경우\n- ⑤ 발산: 차수가 다를 때의 경우. 이 문제는 차수가 같으므로 수렴한다.\n\n**[핵심 포인트]**\n$x \\to \\infty$에서 유리함수의 극한은 **최고차 계수의 비**로 결정된다. 분자와 분모를 최고차항으로 나누어 1 + (0으로 가는 항)의 형태로 만드는 것이 핵심이다.",
