    "problem": "$\\lim_{x \\to 0} \\dfrac{(1+x)^2 - 1}{x}$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n이 문제는 극한의 정의와 미분의 정의를 이용하는 문제입니다. $\\lim_{x \\to 0} \\frac{f(x) - f(0)}{x}$의 형태는 $f'(0)$의 정의와 같으며, 또한 $\\frac{0}{0}$ 꼴의 부정형이므로 인수분해나 로피탈의 정리를 사용하여 해결할 수 있습니다.\n\n**[풀이]**\n\n**방법 1: 인수분해를 이용한 풀이**\n\n주어진 극한은 $\\lim_{x \\to 0} \\frac{(1+x)^2 - 1}{x}$ 입니다.\n\n먼저 분자를 전개합니다:\n$$(1+x)^2 - 1 = 1 + 2x + x^2 - 1 = 2x + x^2$$\n\n따라서:\n$$\\lim_{x \\to 0} \\frac{2x + x^2}{x}$$\n\n$x \\neq 0$ 범위에서 분자를 인수분해합니다:\n$$\\lim_{x \\to 0} \\frac{x(2 + x)}{x}$$\n\n$x \\neq 0$이므로 $x$로 약분합니다:\n$$\\lim_{x \\to 0} (2 + x)$$\n\n$x \\to 0$일 때:\n$$2 + 0 = 2$$\n\n**방법 2: 미분의 정의를 이용한 풀이**\n\n주어진 식을 다시 쓰면:\n$$\\lim_{x \\to 0} \\frac{(1+x)^2 - 1^2}{x}$$\n\n이는 $f(x) = x^2$에서 $f(1+x) - f(1)$ 형태이므로, 미분의 정의에 의해 $f'(1)$을 구하는 것입니다.\n\n$f(x) = x^2$이면 $f'(x) = 2x$이므로:\n$$f'(1) = 2 \\cdot 1 = 2$$\n\n**[정답 확인]**\n분자 $2x + x^2$를 $x$로 약분하여 $2 + x$를 얻고, $x \\to 0$을 대입하면 2가 되므로 정답입니다.\n\n**[오답 분석]**\n객관식 선지가 제시되지 않았으므로 흔한 오답을 분석하면:\n- **0**: 분자와 분모를 약분하지 않고 직접 $\\frac{0}{0}$라고 계산하는 경우\n- **1**: 분자를 $(1+x)^2 - 1 = (1+x-1)(1+x+1) = x(2+x)$로 인수분해할 때 계산 실수로 $(2+x)$를 잘못 계산\n- **4**: $(1+x)^2 = 1 + 2x$로 잘못 전개하거나, $x$를 두 번 약분하는 실수\n\n**[핵심 포인트]**\n$\\frac{0}{0}$ 꼴의 부정형 극한은 **인수분해를 통해 약분하거나 미분의 정의를 인식**하여 해결합니다. 특히 분자를 정확히 전개/인수분해하는 것이 중요합니다.",
