    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n$x \\to \\infty$일 때 유리함수의 극한을 구하는 문제입니다. 분자와 분모의 차수를 비교하여 극한값을 결정합니다.\n\n**유리함수의 극한 공식:**\n$$\\lim_{x \\to \\infty} \\frac{a_m x^m + \\cdots}{b_n x^n + \\cdots} = \\begin{cases} 0 & \\text{if } m < n \\\\ \\frac{a_m}{b_n} & \\text{if } m = n \\\\ \\pm\\infty & \\text{if } m > n \\end{cases}$$\n\n여기서 $m$은 분자의 최고차수, $n$은 분모의 최고차수입니다.\n\n**[풀이]**\n\n주어진 극한식을 분석합니다.\n\n$$\\lim_{x \\to \\infty} \\frac{x^2 + 1}{x^3 - x}$$\n\n**Step 1: 분자와 분모의 최고차수 확인**\n- 분자: $x^2 + 1$의 최고차수는 $2$\n- 분모: $x^3 - x$의 최고차수는 $3$\n\n**Step 2: 차수 비교**\n분자의 차수(2) < 분모의 차수(3)이므로, $x \\to \\infty$일 때 극한값은 $0$입니다.\n\n**Step 3: 대수적 계산으로 확인**\n\n분자와 분모를 분모의 최고차수인 $x^3$으로 나눕니다.\n\n$$\\lim_{x \\to \\infty} \\frac{x^2 + 1}{x^3 - x} = \\lim_{x \\to \\infty} \\frac{\\frac{x^2}{x^3} + \\frac{1}{x^3}}{\\frac{x^3}{x^3} - \\frac{x}{x^3}}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{\\frac{1}{x} + \\frac{1}{x^3}}{1 - \\frac{1}{x^2}}$$\n\n**Step 4: 각 항의 극한 계산**\n\n$x \\to \\infty$일 때:\n- $\\frac{1}{x} \\to 0$\n- $\\frac{1}{x^3} \\to 0$\n- $\\frac{1}{x^2} \\to 0$\n\n따라서:\n$$\\lim_{x \\to \\infty} \\frac{\\frac{1}{x} + \\frac{1}{x^3}}{1 - \\frac{1}{x^2}} = \\frac{0 + 0}{1 - 0} = \\frac{0}{1} = 0$$\n\n**[정답 확인]**\n\n분자의 차수가 분모의 차수보다 작으므로 극한값은 0입니다.\n\n**[오답 분석]**\n\n- **② 1**: 분자와 분모의 차수가 같을 때 최고차 계수의 비가 극한값인데, 여기서는 차수가 다릅니다.\n- **③ -1**: 극한값이 음수가 될 이유가 없으며, 실제로는 양의 무한대에서 양의 값입니다.\n- **④ $\\frac{1}{2}$**: 임의의 상수값이 나올 수 없습니다. 분자가 분모보다 낮은 차수이므로 0으로 수렴합니다.\n- **⑤ 발산**: 분자의 차수가 낮으므로 수렴하며 발산하지 않습니다.\n\n**[핵심 포인트]**\n\n유리함수의 극한에서는 **분자와 분모의 최고차수를 비교**하는 것이 가장 빠른 풀이 방법입니다. 분자의 차수가 작으면 극한값은 항상 **0**입니다.",
