    "type": "극한",
    "problem": "$\\lim_{x \\to \\infty} (\\sqrt{4x^2 + 6x + 1} - 2x)$의 값을 구하시오. (답은 기약분수의 분자와 분모의 합으로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 5,
    "explanation": "**[핵심 개념]**\n$\\infty - \\infty$ 꼴의 부정형 극한을 계산하기 위해 유리화(분모의 유리화)를 사용합니다. $\\sqrt{A} - B$ 꼴일 때, $\\frac{(\\sqrt{A} - B)(\\sqrt{A} + B)}{\\sqrt{A} + B} = \\frac{A - B^2}{\\sqrt{A} + B}$로 변형하여 계산합니다.\n\n**[풀이]**\n\n주어진 극한: $\\lim_{x \\to \\infty} (\\sqrt{4x^2 + 6x + 1} - 2x)$\n\n**Step 1: 유리화를 위해 분자와 분모에 $\\sqrt{4x^2 + 6x + 1} + 2x$를 곱합니다.**\n\n$$\\sqrt{4x^2 + 6x + 1} - 2x = \\frac{(\\sqrt{4x^2 + 6x + 1} - 2x)(\\sqrt{4x^2 + 6x + 1} + 2x)}{\\sqrt{4x^2 + 6x + 1} + 2x}$$\n\n**Step 2: 분자를 $(A-B)(A+B) = A^2 - B^2$ 형태로 정리합니다.**\n\n$$= \\frac{(4x^2 + 6x + 1) - (2x)^2}{\\sqrt{4x^2 + 6x + 1} + 2x}$$\n\n$$= \\frac{4x^2 + 6x + 1 - 4x^2}{\\sqrt{4x^2 + 6x + 1} + 2x}$$\n\n$$= \\frac{6x + 1}{\\sqrt{4x^2 + 6x + 1} + 2x}$$\n\n**Step 3: $x \\to \\infty$일 때 극한을 구합니다.**\n\n분자와 분모를 $x$로 나눕니다:\n\n$$= \\lim_{x \\to \\infty} \\frac{6 + \\frac{1}{x}}{\\frac{\\sqrt{4x^2 + 6x + 1}}{x} + 2}$$\n\n**Step 4: 분모의 $\\sqrt{4x^2 + 6x + 1}$을 정리합니다.**\n\n$x > 0$일 때:\n$$\\frac{\\sqrt{4x^2 + 6x + 1}}{x} = \\sqrt{\\frac{4x^2 + 6x + 1}{x^2}} = \\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}}$$\n\n**Step 5: $x \\to \\infty$일 때 극한값을 계산합니다.**\n\n$$\\lim_{x \\to \\infty} \\frac{6 + \\frac{1}{x}}{\\sqrt{4 + \\frac{6}{x} + \\frac{1}{x^2}} + 2}$$\n\n$$= \\frac{6 + 0}{\\sqrt{4 + 0 + 0} + 2} = \\frac{6}{2 + 2} = \\frac{6}{4} = \\frac{3}{2}$$\n\n**Step 6: 기약분수의 분자와 분모의 합을 구합니다.**\n\n$\\frac{3}{2}$는 이미 기약분수이므로, 분자 $3$과 분모 $2$의 합은:\n\n$$3 + 2 = 5$$\n\n**[정답 확인]**\n유리화를 통해 $\\infty - \\infty$ 꼴을 $\\frac{6x+1}{\\sqrt{4x^2+6x+1}+2x}$ 꼴로 변형한 후, 분자와 분모를 $x$로 나누어 $\\frac{3}{2}$를 얻었으며, 분자와 분모의 합이 5입니다.\n\n**[오답 분석]**\n- 유리화 과정을 생략하고 직접 대입하면 $\\infty - \\infty$ 꼴로 계산 불가능\n- 분모를 $\\sqrt{4x^2+6x+1} - 2x$로 잘못 곱하면 부호가 반대가 되어 오류 발생\n- 극한값과 기약분수 변환 과정을 혼동하면 잘못된 답 도출\n\n**[핵심 포인트]**\n$\\infty - \\infty$ 꼴에서는 유리화를 통해 분수 형태로 만들어야 합니다. 또한 제곱근이 있을 때 $x \\to \\infty$에서 $\\sqrt{ax^2 + bx + c} = |x|\\sqrt{a + \\frac{b}{x} + \\frac{c}{x^2}}$ 형태로 정리하는 것이 중요합니다.",
