    "explanation": "**[핵심 개념]**\n극한값을 구할 때 $x \\to a$일 때 분자와 분모가 모두 0으로 수렴하는 $\\frac{0}{0}$ 꼴의 부정형이 나타나면, 인수분해를 이용하여 공통인수를 약분한 후 극한을 구해야 합니다. 이때 사용하는 인수분해 공식은 $a^2 - b^2 = (a-b)(a+b)$와 $a^4 - b^4 = (a^2-b^2)(a^2+b^2)$ 등입니다.\n\n**[풀이]**\n\n$x = 1$을 직접 대입하면:\n$$\\frac{1^4 - 1}{1^2 - 1} = \\frac{0}{0}$$\n\n$\\frac{0}{0}$ 꼴의 부정형이므로 인수분해를 통해 정리합니다.\n\n**분자를 인수분해합니다:**\n$$x^4 - 1 = (x^2)^2 - 1^2 = (x^2 - 1)(x^2 + 1)$$\n\n**분모를 인수분해합니다:**\n$$x^2 - 1 = (x-1)(x+1)$$\n\n**원래의 식에 대입합니다:**\n$$\\frac{x^4 - 1}{x^2 - 1} = \\frac{(x^2-1)(x^2+1)}{x^2-1}$$\n\n**공통인수 $(x^2-1)$을 약분합니다** ($x \\to 1$이므로 $x \\neq 1$):\n$$= \\frac{(x^2-1)(x^2+1)}{x^2-1} = x^2 + 1$$\n\n**극한값을 구합니다:**\n$$\\lim_{x \\to 1} (x^2 + 1) = 1^2 + 1 = 2$$\n\n**[정답 확인]**\n인수분해로 부정형을 제거한 후 $x = 1$을 대입하면 $1^2 + 1 = 2$이므로 정답은 ②입니다.\n\n**[오답 분석]**\n- ① 1: 분자를 $(x^2-1)(x^2+1)$로만 인수분해하고 약분하지 않은 경우\n- ③ 3: 계산 실수로 $x^2 - 1$을 잘못 계산한 경우\n- ④ 4: 분모를 약분하지 않고 원래 식에 $x=1$을 대입하려고 한 경우\n- ⑤ 0: 부정형을 제거하지 않고 $\\frac{0}{0} = 0$이라고 잘못 생각한 경우\n\n**[핵심 포인트]**\n- $\\frac{0}{0}$ 꼴의 부정형이 나타나면 반드시 인수분해를 통해 공통인수를 약분해야 합니다.\n- 약분 후 원래 변수의 극한값을 대입하여 최종 답을 구합니다.",
