    "_type": "limit",
    "type": "극한",
    "problem": "$\\lim_{x \\to 0} \\dfrac{\\sqrt{1+x} - \\sqrt{1-x}}{x}$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n이 문제는 $\\frac{0}{0}$ 꼴의 부정형 극한으로, 직접 대입하면 정의되지 않는 형태입니다. 이를 해결하기 위해 **분자의 유리화(켤레식 곱하기)** 또는 **미분의 정의**를 이용할 수 있습니다.\n\n**[풀이]**\n\n**방법 1: 유리화**\n\n$x \\to 0$일 때 분자와 분모가 모두 0으로 수렴하므로 ($\\sqrt{1+0} - \\sqrt{1-0} = 0$), 직접 대입이 불가능합니다.\n\n분자를 유리화하기 위해 켤레식 $\\sqrt{1+x} + \\sqrt{1-x}$를 분자와 분모에 곱합니다:\n\n$$\\lim_{x \\to 0} \\frac{\\sqrt{1+x} - \\sqrt{1-x}}{x} = \\lim_{x \\to 0} \\frac{(\\sqrt{1+x} - \\sqrt{1-x})(\\sqrt{1+x} + \\sqrt{1-x})}{x(\\sqrt{1+x} + \\sqrt{1-x})}$$\n\n분자에 $(a-b)(a+b) = a^2 - b^2$ 공식을 적용하면:\n\n$$= \\lim_{x \\to 0} \\frac{(1+x) - (1-x)}{x(\\sqrt{1+x} + \\sqrt{1-x})}$$\n\n$$= \\lim_{x \\to 0} \\frac{1+x - 1 + x}{x(\\sqrt{1+x} + \\sqrt{1-x})}$$\n\n$$= \\lim_{x \\to 0} \\frac{2x}{x(\\sqrt{1+x} + \\sqrt{1-x})}$$\n\n$x \\neq 0$이므로 $x$로 약분:\n\n$$= \\lim_{x \\to 0} \\frac{2}{\\sqrt{1+x} + \\sqrt{1-x}}$$\n\n이제 직접 대입 가능:\n\n$$= \\frac{2}{\\sqrt{1+0} + \\sqrt{1-0}} = \\frac{2}{\\sqrt{1} + \\sqrt{1}} = \\frac{2}{1+1} = \\frac{2}{2} = 1$$\n\n**방법 2: 미분의 정의 (선택 사항)**\n\n원래 식을 다시 정리하면:\n$$\\lim_{x \\to 0} \\frac{\\sqrt{1+x} - \\sqrt{1-x}}{x} = \\lim_{x \\to 0} \\frac{\\sqrt{1+x} - \\sqrt{1}}{x} - \\lim_{x \\to 0} \\frac{\\sqrt{1-x} - \\sqrt{1}}{-x}$$\n\n이는 $f(x) = \\sqrt{1+x}$에서 $f'(0) + f'(0)$ (두 미분의 합)으로 해석할 수 있습니다.\n\n$f'(x) = \\frac{1}{2\\sqrt{1+x}}$이므로 $f'(0) = \\frac{1}{2}$\n\n따라서 극한값 = $\\frac{1}{2} + \\frac{1}{2} = 1$\n\n**[정답 확인]**\n$x=0$ 근처에서 분자를 유리화하여 $\\frac{0}{0}$ 꼴을 해소한 후 직접 대입하면 정확히 1이 나옵니다.\n\n**[오답 분석]**\n선택지가 없어 구체적인 오답 분석은 불가능하나, 흔한 실수는:\n- 유리화를 하지 않고 무리함수 전개를 잘못 적용하면 $\\frac{1}{2}$나 $2$ 같은 잘못된 답이 나올 수 있습니다.\n- 분자의 유리화 과정에서 $(1+x)-(1-x) = 2x$를 실수하면 틀린 답이 나옵니다.\n\n**[핵심 포인트]**\n$\\frac{0}{0}$ 꼴의 무리함수 극한은 **분자를 켤레식으로 곱하여 유리화**하는 것이 가장 확실한 방법입니다. 이를 통해 분모의 $x$와 약분할 수 있는 인수를 만들 수 있습니다.",
