    "_type": "limit",
    "type": "극한",
    "problem": "다항함수 $f(x)$가 $\\lim_{x \\to 1} \\dfrac{f(x)}{x-1} = 5$를 만족할 때, $f(1)$의 값은?",
    "answerType": "choice",
    "choices": [
      "① $-5$",
      "② $-1$",
      "③ 0",
      "④ 1",
      "⑤ 5"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n극한이 수렴하는 조건을 이용하여 다항함수의 성질을 파악하는 문제입니다.\n- 분자가 0으로 수렴하지 않으면 분모가 0으로 수렴할 때 극한값이 무한대 또는 존재하지 않음\n- 극한값이 유한한 값 5로 수렴하려면 분자도 0으로 수렴해야 함 (0/0 꼴)\n- 로피탈의 정리 또는 인수분해를 이용한 풀이\n\n**[풀이]**\n\n$\\lim_{x \\to 1} \\dfrac{f(x)}{x-1} = 5$가 유한한 값으로 수렴합니다.\n\n분모 $(x-1) \\to 0$ (as $x \\to 1$)이므로, 극한이 유한값으로 수렴하려면 분자도 0으로 수렴해야 합니다.\n\n즉, $\\lim_{x \\to 1} f(x) = 0$이어야 하므로:\n$$f(1) = 0$$\n\n**검증:** $f(1) = 0$이면 $\\dfrac{f(x)}{x-1}$은 0/0 꼴이 되어 극한이 존재할 수 있습니다.\n\n다항함수 $f(x)$를 $f(1) = 0$을 만족하도록 인수분해하면:\n$$f(x) = (x-1) \\cdot g(x)$$\n\n여기서 $g(x)$는 다항함수입니다.\n\n따라서:\n$$\\lim_{x \\to 1} \\dfrac{f(x)}{x-1} = \\lim_{x \\to 1} \\dfrac{(x-1) \\cdot g(x)}{x-1} = \\lim_{x \\to 1} g(x) = g(1) = 5$$\n\n이는 주어진 조건을 만족합니다.\n\n**[정답 확인]**\n극한값이 유한하려면 반드시 분자가 0으로 수렴해야 하므로 $f(1) = 0$입니다.\n\n**[오답 분석]**\n- ① $f(1) = -5$: 분자가 -5로 수렴하면 $\\dfrac{-5}{0}$ 형태가 되어 극한이 무한대 또는 존재하지 않음\n- ② $f(1) = -1$: 마찬가지로 분자가 -1로 수렴하므로 극한이 존재하지 않음\n- ④ $f(1) = 1$: 분자가 1로 수렴하므로 극한이 존재하지 않음\n- ⑤ $f(1) = 5$: 분자가 5로 수렴하므로 극한이 존재하지 않음\n\n**[핵심 포인트]**\n극한 $\\lim_{x \\to a} \\dfrac{f(x)}{x-a}$가 유한값으로 수렴하면 반드시 $f(a) = 0$이어야 합니다. 이는 0/0 꼴의 부정형이어야만 로피탈의 정리나 인수분해가 의미가 있기 때문입니다.",
