    "type": "극한",
    "problem": "$\\lim_{x \\to 0} \\dfrac{\\sqrt{1+2x} - 1}{\\sqrt{1+3x} - 1}$의 값을 구하시오. (답은 기약분수의 분자와 분모의 합으로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 5,
    "explanation": "**[핵심 개념]**\n$x \\to 0$일 때 $\\frac{0}{0}$ 꼴의 부정형 극한을 구하는 문제입니다. 이러한 경우 다음의 방법들을 사용할 수 있습니다:\n1. 분자와 분모의 켤레식을 곱하기 (유리화)\n2. 로피탈의 정리 사용\n3. 테일러 급수 이용\n\n이 문제에서는 켤레식을 곱하는 방법이 가장 효율적입니다.\n\n**[풀이]**\n\n주어진 극한: $\\lim_{x \\to 0} \\dfrac{\\sqrt{1+2x} - 1}{\\sqrt{1+3x} - 1}$\n\n먼저 $x \\to 0$일 때 분자와 분모의 극한값을 확인하면:\n- 분자: $\\sqrt{1+0} - 1 = 0$\n- 분모: $\\sqrt{1+0} - 1 = 0$\n\n따라서 $\\frac{0}{0}$ 꼴의 부정형이므로 유리화를 진행합니다.\n\n**분자를 유리화:**\n\n$\\sqrt{1+2x} - 1$에 켤레식 $\\sqrt{1+2x} + 1$을 곱하면:\n\n$$\\sqrt{1+2x} - 1 = \\frac{(\\sqrt{1+2x} - 1)(\\sqrt{1+2x} + 1)}{\\sqrt{1+2x} + 1} = \\frac{(1+2x) - 1}{\\sqrt{1+2x} + 1} = \\frac{2x}{\\sqrt{1+2x} + 1}$$\n\n**분모를 유리화:**\n\n$\\sqrt{1+3x} - 1$에 켤레식 $\\sqrt{1+3x} + 1$을 곱하면:\n\n$$\\sqrt{1+3x} - 1 = \\frac{(\\sqrt{1+3x} - 1)(\\sqrt{1+3x} + 1)}{\\sqrt{1+3x} + 1} = \\frac{(1+3x) - 1}{\\sqrt{1+3x} + 1} = \\frac{3x}{\\sqrt{1+3x} + 1}$$\n\n**극한 계산:**\n\n$$\\lim_{x \\to 0} \\dfrac{\\sqrt{1+2x} - 1}{\\sqrt{1+3x} - 1} = \\lim_{x \\to 0} \\dfrac{\\dfrac{2x}{\\sqrt{1+2x} + 1}}{\\dfrac{3x}{\\sqrt{1+3x} + 1}}$$\n\n$$= \\lim_{x \\to 0} \\dfrac{2x}{\\sqrt{1+2x} + 1} \\cdot \\dfrac{\\sqrt{1+3x} + 1}{3x}$$\n\n$$= \\lim_{x \\to 0} \\dfrac{2(\\sqrt{1+3x} + 1)}{3(\\sqrt{1+2x} + 1)}$$\n\n$$= \\dfrac{2(\\sqrt{1+0} + 1)}{3(\\sqrt{1+0} + 1)} = \\dfrac{2(1 + 1)}{3(1 + 1)} = \\dfrac{2 \\cdot 2}{3 \\cdot 2} = \\dfrac{4}{6} = \\dfrac{2}{3}$$\n\n**기약분수로 표현하면** $\\dfrac{2}{3}$\n\n따라서 분자와 분모의 합 = $2 + 3 = 5$\n\n**[정답 확인]**\n유리화를 통해 부정형을 해결한 후 극한값 $\\dfrac{2}{3}$을 구했고, 분자 2와 분모 3의 합이 5가 되어 정답이 맞습니다.\n\n**[오답 분석]**\n- 유리화 과정에서 분자나 분모의 켤레식을 잘못 적용한 경우\n- 극한값을 구한 후 기약분수로 약분하지 않은 경우\n- 계산 실수로 인해 다른 비율($\\dfrac{3}{2}$ 등)을 구한 경우\n\n**[핵심 포인트]**\n$\\frac{0}{0}$ 꼴의 부정형 극한에서는 분자와 분모를 각각 켤레식으로 곱하여 유리화하면, 공통 인수 $x$가 약분되어 극한값을 쉽게 구할 수 있습니다.",
