    "type": "극한",
    "problem": "$\\lim_{x \\to \\infty} \\left(\\sqrt{x^2 + ax + 3} - \\sqrt{x^2 - 2x + 1}\\right) = 4$일 때, 상수 $a$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n\n$\\infty - \\infty$ 꼴의 극한을 계산할 때는 분자를 유리화하는 방법을 사용합니다. $\\sqrt{A} - \\sqrt{B}$ 형태에서 $\\frac{(\\sqrt{A} - \\sqrt{B})(\\sqrt{A} + \\sqrt{B})}{\\sqrt{A} + \\sqrt{B}} = \\frac{A - B}{\\sqrt{A} + \\sqrt{B}}$로 변형합니다. 또한 $x \\to \\infty$일 때 $\\sqrt{x^2 + bx + c} \\sim |x|\\sqrt{1 + \\frac{b}{x} + \\frac{c}{x^2}} \\sim |x|(1 + \\frac{b}{2x})$로 근사합니다.\n\n**[풀이]**\n\n주어진 극한식을 정리하기 위해 분자를 유리화합니다.\n\n$$\\lim_{x \\to \\infty} \\left(\\sqrt{x^2 + ax + 3} - \\sqrt{x^2 - 2x + 1}\\right)$$\n\n분자와 분모에 $\\sqrt{x^2 + ax + 3} + \\sqrt{x^2 - 2x + 1}$를 곱합니다.\n\n$$= \\lim_{x \\to \\infty} \\frac{(x^2 + ax + 3) - (x^2 - 2x + 1)}{\\sqrt{x^2 + ax + 3} + \\sqrt{x^2 - 2x + 1}}$$\n\n분자를 정리하면:\n$$= \\lim_{x \\to \\infty} \\frac{ax + 3 + 2x - 1}{\\sqrt{x^2 + ax + 3} + \\sqrt{x^2 - 2x + 1}}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{(a+2)x + 2}{\\sqrt{x^2 + ax + 3} + \\sqrt{x^2 - 2x + 1}}$$\n\n$x \\to \\infty$일 때, 분모를 정리합니다:\n$$\\sqrt{x^2 + ax + 3} \\sim x\\sqrt{1 + \\frac{a}{x}} \\sim x\\left(1 + \\frac{a}{2x}\\right)$$\n\n$$\\sqrt{x^2 - 2x + 1} \\sim x\\sqrt{1 - \\frac{2}{x}} \\sim x\\left(1 - \\frac{1}{x}\\right)$$\n\n따라서 분모는:\n$$\\sqrt{x^2 + ax + 3} + \\sqrt{x^2 - 2x + 1} \\sim 2x$$\n\n극한값이 수렴하려면 분자의 일차항 계수가 0이어야 합니다.\n\n$$a + 2 = 0 \\implies a = -2$$\n\n이 경우 분자는 상수항만 남으므로:\n$$\\lim_{x \\to \\infty} \\frac{2}{2x} = 0$$\n\n이는 조건을 만족하지 않습니다. 다시 검토하면, 분자가 $(a+2)x$이고 분모가 $2x$이므로:\n\n$$\\lim_{x \\to \\infty} \\frac{(a+2)x + 2}{2x} = \\frac{a+2}{2} = 4$$\n\n따라서:\n$$a + 2 = 8$$\n\n$$a = 6$$\n\n**[정답 확인]**\n\n$a = 6$일 때: $\\lim_{x \\to \\infty} \\frac{(6+2)x + 2}{2x} = \\lim_{x \\to \\infty} \\frac{8x + 2}{2x} = 4$ ✓\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오답은:\n- $a = -2$: 분자가 0이 되어 극한값이 0이 됨\n- $a = 4$: $\\frac{a+2}{2} = 3$이 되어 조건 불만족\n- $a = 8$: 분자의 계수만 계산하여 $a+2=8$을 $a=8$로 착각\n\n**[핵심 포인트]**\n\n$\\infty - \\infty$ 꼴에서는 **유리화 후 분모의 주도항을 파악**하는 것이 중요하며, 극한값이 유한하려면 **분자의 최고차 계수와 분모의 최고차 계수의 비**를 계산해야 합니다.",
