    "explanation": "**[핵심 개념]**\n\n다항함수에서 극한값이 유한한 값으로 수렴할 때의 조건을 이해해야 합니다.\n\n$\\lim_{x \\to a} \\dfrac{f(x)}{(x-a)^n} = k$ (단, $k$는 0이 아닌 상수)가 성립하려면:\n- $f(a) = 0$, $f'(a) = 0$, $\\cdots$, $f^{(n-1)}(a) = 0$이어야 하고\n- $f^{(n)}(a) = n! \\cdot k$를 만족해야 합니다.\n\n즉, $f(x)$가 $x=a$에서 $(x-a)^n$의 인수를 가져야 극한이 수렴합니다.\n\n**[풀이]**\n\n**Step 1: 극한 조건 분석**\n\n$\\lim_{x \\to 1} \\dfrac{f(x)}{(x-1)^2} = 3$이 0이 아닌 유한값이므로:\n- $f(1) = 0$ (분자가 0으로 수렴해야 함)\n- $f'(1) = 0$ (분자가 $(x-1)^2$으로 나누어지려면)\n- $f''(1) = 2! \\times 3 = 6$\n\n**Step 2: $f(x)$의 형태 결정**\n\n$f(x)$는 다항함수이고 $f(1) = 0$, $f'(1) = 0$이므로:\n$$f(x) = (x-1)^2 \\cdot g(x)$$\n\n여기서 $g(x)$는 다항함수입니다.\n\n극한 조건에서:\n$$\\lim_{x \\to 1} \\dfrac{(x-1)^2 \\cdot g(x)}{(x-1)^2} = \\lim_{x \\to 1} g(x) = 3$$\n\n따라서 $g(1) = 3$입니다.\n\n**Step 3: $g(x)$의 형태 결정**\n\n$g(x)$가 다항함수이고 $g(1) = 3$이므로, 가장 간단한 경우:\n$$g(x) = 3 \\text{ (상수함수)}$$\n\n따라서:\n$$f(x) = 3(x-1)^2$$\n\n**Step 4: $f(0) = 4$ 조건 확인**\n\n$f(x) = 3(x-1)^2$일 때:\n$$f(0) = 3(0-1)^2 = 3 \\cdot 1 = 3$$\n\n이는 $f(0) = 4$와 맞지 않으므로, $g(x)$는 상수가 아닙니다.\n\n**Step 5: 일차함수 $g(x)$ 시도**\n\n$$g(x) = ax + b \\text{ (단, } g(1) = 3\\text{)}$$\n\n따라서 $a + b = 3$이고:\n$$f(x) = (x-1)^2(ax + b)$$\n\n$f(0) = 4$ 조건 적용:\n$$f(0) = (0-1)^2(a \\cdot 0 + b) = 1 \\cdot b = 4$$\n\n따라서 $b = 4$\n\n$a + b = 3$에서:\n$$a + 4 = 3 \\Rightarrow a = -1$$\n\n**Step 6: $f(x)$ 확정**\n\n$$f(x) = (x-1)^2(-x + 4)$$\n\n**Step 7: $f(2)$ 계산**\n\n$$f(2) = (2-1)^2(-2 + 4) = 1^2 \\cdot 2 = 2$$\n\n**[정답 확인]**\n\n$f(x) = (x-1)^2(-x+4)$가 모든 조건을 만족하므로: $\\lim_{x \\to 1} \\dfrac{f(x)}{(x-1)^2} = -1+4 = 3$ ✓, $f(0) = 1 \\cdot 4 = 4$ ✓, $f(2) = 1 \\cdot 2 = 2$ ✓\n\n**[핵심 포인트]**\n\n극한이 유한값으로 수렴 $\\Rightarrow$ 분자가 분모의 인수를 가져야 하고, 이를 통해 $f(x)$의 형태를 $(x-1)^2 \\cdot g(x)$ 형태로 결정한 후 나머지 조건으로 구체적인 함수를 찾는 것이 핵심입니다.",
