    "problem": "$\\lim_{x \\to \\infty} \\left(\\sqrt[3]{x^3 + 3x^2} - x\\right)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n$\\infty - \\infty$ 꼴의 극한을 계산할 때는 유리화(또는 인수분해)를 이용하여 부정형을 해결해야 합니다. 세제곱근의 경우 $a^3 - b^3 = (a-b)(a^2+ab+b^2)$ 공식을 변형하여 사용합니다.\n\n즉, $a - b = \\frac{a^3 - b^3}{a^2 + ab + b^2}$ 형태로 바꾸어 계산합니다.\n\n**[풀이]**\n\n$\\lim_{x \\to \\infty} \\left(\\sqrt[3]{x^3 + 3x^2} - x\\right)$\n\n$a = \\sqrt[3]{x^3 + 3x^2}$, $b = x$로 놓으면, $a^3 = x^3 + 3x^2$, $b^3 = x^3$입니다.\n\n세제곱 차 공식을 이용하면:\n$$a - b = \\frac{a^3 - b^3}{a^2 + ab + b^2}$$\n\n따라서:\n$$\\sqrt[3]{x^3 + 3x^2} - x = \\frac{(x^3 + 3x^2) - x^3}{(\\sqrt[3]{x^3 + 3x^2})^2 + \\sqrt[3]{x^3 + 3x^2} \\cdot x + x^2}$$\n\n$$= \\frac{3x^2}{(\\sqrt[3]{x^3 + 3x^2})^2 + x\\sqrt[3]{x^3 + 3x^2} + x^2}$$\n\n$x \\to \\infty$일 때 분자와 분모의 최고차항을 비교합니다.\n\n$\\sqrt[3]{x^3 + 3x^2} = x\\sqrt[3]{1 + \\frac{3}{x}} \\approx x \\cdot 1 = x$ (주요항)\n\n따라서:\n- 분모의 최고차항: $x^2 + x \\cdot x + x^2 = 3x^2$\n\n극한을 계산하면:\n$$\\lim_{x \\to \\infty} \\frac{3x^2}{3x^2} = 1$$\n\n더 정확히 하기 위해 분모를 $x^2$으로 인수분해하면:\n$$\\lim_{x \\to \\infty} \\frac{3x^2}{x^2\\left[\\left(\\sqrt[3]{1+\\frac{3}{x}}\\right)^2 + \\sqrt[3]{1+\\frac{3}{x}} + 1\\right]}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{3}{(1)^2 + 1 + 1} = \\frac{3}{3} = 1$$\n\n**[정답 확인]**\n\n세제곱 차 공식으로 유리화하여 $\\frac{3x^2}{3x^2}$ 꼴이 되므로 극한값은 1입니다.\n\n**[오답 분석]**\n\n객관식이 아니므로 해당 사항 없습니다.\n\n**[핵심 포인트]**\n\n1. $\\infty - \\infty$ 꼴에서는 **$a^3 - b^3 = (a-b)(a^2+ab+b^2)$을 이용하여 유리화**합니다.\n2. 극한 계산 시 **분자와 분모의 최고차항**을 비교하여 답을 구합니다.",
