    "type": "극한",
    "problem": "$\\lim_{x \\to 0} \\dfrac{\\sqrt{4+x} - \\sqrt{4-x}}{\\sqrt[3]{8+x} - 2}$의 값은?",
    "answerType": "choice",
    "choices": [
      "① 1",
      "② 2",
      "③ 3",
      "④ 4",
      "⑤ 6"
    ],
    "answer": 4,
    "explanation": "**[핵심 개념]**\n$x \\to 0$일 때 $\\frac{0}{0}$ 꼴의 부정형이므로, 분자와 분모를 유리화(또는 근호 처리)하여 정리해야 합니다. \n- 제곱근 유리화: $\\sqrt{a} - \\sqrt{b} = \\frac{a-b}{\\sqrt{a}+\\sqrt{b}}$\n- 세제곱근 처리: $\\sqrt[3]{a} - \\sqrt[3]{b} = \\frac{a-b}{(\\sqrt[3]{a})^2 + \\sqrt[3]{a}\\sqrt[3]{b} + (\\sqrt[3]{b})^2}$\n\n**[풀이]**\n\n$x \\to 0$일 때 분자: $\\sqrt{4+0} - \\sqrt{4-0} = 2 - 2 = 0$\n$x \\to 0$일 때 분모: $\\sqrt[3]{8+0} - 2 = 2 - 2 = 0$\n\n$\\frac{0}{0}$ 꼴이므로 분자와 분모를 정리합니다.\n\n**[분자 유리화]**\n$$\\sqrt{4+x} - \\sqrt{4-x} = \\frac{(4+x)-(4-x)}{\\sqrt{4+x}+\\sqrt{4-x}} = \\frac{2x}{\\sqrt{4+x}+\\sqrt{4-x}}$$\n\n**[분모 정리]**\n$\\sqrt[3]{8+x} - 2$에서 $a = \\sqrt[3]{8+x}$, $b = 2$로 놓으면:\n$$a^3 - b^3 = (8+x) - 8 = x$$\n\n$$a^3 - b^3 = (a-b)(a^2 + ab + b^2)$$\n\n따라서:\n$$x = (\\sqrt[3]{8+x} - 2)[(\\sqrt[3]{8+x})^2 + 2\\sqrt[3]{8+x} + 4]$$\n\n$$\\sqrt[3]{8+x} - 2 = \\frac{x}{(\\sqrt[3]{8+x})^2 + 2\\sqrt[3]{8+x} + 4}$$\n\n**[극한값 계산]**\n$$\\lim_{x \\to 0} \\frac{\\sqrt{4+x} - \\sqrt{4-x}}{\\sqrt[3]{8+x} - 2} = \\lim_{x \\to 0} \\frac{\\frac{2x}{\\sqrt{4+x}+\\sqrt{4-x}}}{\\frac{x}{(\\sqrt[3]{8+x})^2 + 2\\sqrt[3]{8+x} + 4}}$$\n\n$$= \\lim_{x \\to 0} \\frac{2x}{\\sqrt{4+x}+\\sqrt{4-x}} \\cdot \\frac{(\\sqrt[3]{8+x})^2 + 2\\sqrt[3]{8+x} + 4}{x}$$\n\n$$= \\lim_{x \\to 0} \\frac{2[(\\sqrt[3]{8+x})^2 + 2\\sqrt[3]{8+x} + 4]}{\\sqrt{4+x}+\\sqrt{4-x}}$$\n\n$x \\to 0$일 때:\n- 분자: $2[(2)^2 + 2(2) + 4] = 2[4 + 4 + 4] = 2 \\times 12 = 24$\n- 분모: $\\sqrt{4} + \\sqrt{4} = 2 + 2 = 4$\n\n$$\\lim_{x \\to 0} = \\frac{24}{4} = 6$$\n\n**[정답 확인]**\n분자를 유리화하고 분모를 세제곱근 공식으로 정리한 후, $x$로 약분하여 극한을 계산하면 정확히 $6$을 얻습니다.\n\n**[오답 분석]**\n- ① 1: 분모의 세제곱근 인수분해를 놓친 경우\n- ② 2: 분자의 유리화만 하고 계산을 덜한 경우\n- ③ 3: 분자와 분모의 계수를 잘못 계산한 경우\n- ④ 4: 분모의 극한값만 취한 경우\n\n**[핵심 포인트]**\n- 제곱근과 세제곱근이 섞여 있을 때는 각각을 유리화/인수분해하여 $x$로 약분 가능하게 만들어야 합니다.\n- 세제곱근의 차: $a^3 - b^3 = (a-b)(a^2+ab+b^2)$ 공식을 정확히 적용하는 것이 핵심입니다.",
