    "problem": "$\\lim_{x \\to \\infty} x\\left(\\sqrt{x^2+3} - \\sqrt{x^2+1}\\right)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n$\\infty \\cdot 0$ 꼴의 부정형 극한을 다루기 위해 유리화(분자의 켤레식 곱하기)를 사용합니다. $\\sqrt{A} - \\sqrt{B}$ 형태는 $\\frac{A-B}{\\sqrt{A}+\\sqrt{B}}$로 변환할 수 있습니다. 또한 $x \\to \\infty$일 때 $\\sqrt{x^2+a} \\approx |x| + \\frac{a}{2|x|}$ 근사를 활용할 수 있습니다.\n\n**[풀이]**\n\n주어진 극한식을 정리하면:\n$$\\lim_{x \\to \\infty} x\\left(\\sqrt{x^2+3} - \\sqrt{x^2+1}\\right)$$\n\n**Step 1: 유리화 (켤레식 곱하기)**\n\n분자와 분모에 $\\sqrt{x^2+3} + \\sqrt{x^2+1}$을 곱합니다:\n\n$$x\\left(\\sqrt{x^2+3} - \\sqrt{x^2+1}\\right) = x \\cdot \\frac{(\\sqrt{x^2+3} - \\sqrt{x^2+1})(\\sqrt{x^2+3} + \\sqrt{x^2+1})}{\\sqrt{x^2+3} + \\sqrt{x^2+1}}$$\n\n**Step 2: 분자 계산**\n\n$$= x \\cdot \\frac{(x^2+3) - (x^2+1)}{\\sqrt{x^2+3} + \\sqrt{x^2+1}} = x \\cdot \\frac{2}{\\sqrt{x^2+3} + \\sqrt{x^2+1}}$$\n\n$$= \\frac{2x}{\\sqrt{x^2+3} + \\sqrt{x^2+1}}$$\n\n**Step 3: 극한 계산**\n\n$x \\to \\infty$일 때, 분자와 분모를 $x$로 나눕니다 ($x > 0$이므로 $\\sqrt{x^2} = x$):\n\n$$= \\lim_{x \\to \\infty} \\frac{2x}{x\\left(\\sqrt{1+\\frac{3}{x^2}} + \\sqrt{1+\\frac{1}{x^2}}\\right)}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{2}{\\sqrt{1+\\frac{3}{x^2}} + \\sqrt{1+\\frac{1}{x^2}}}$$\n\n**Step 4: 극한값 계산**\n\n$x \\to \\infty$일 때, $\\frac{3}{x^2} \\to 0$, $\\frac{1}{x^2} \\to 0$이므로:\n\n$$= \\frac{2}{\\sqrt{1+0} + \\sqrt{1+0}} = \\frac{2}{1+1} = \\frac{2}{2} = 1$$\n\n**[정답 확인]**\n유리화를 통해 부정형을 제거하고, $x \\to \\infty$에서의 근사를 이용하면 분자는 2로, 분모는 2로 수렴하여 극한값이 1이 됩니다.\n\n**[오답 분석]**\n- **0**: 유리화 후 분자를 계산하지 않고 0이라고 착각한 경우\n- **2**: 분모에서 양쪽 루트를 더하는 과정을 빠뜨리고 분자만 2라고 한 경우\n- **$\\infty$**: 유리화하지 않고 직접 극한을 구하려던 경우\n\n**[핵심 포인트]**\n1. $\\infty \\cdot 0$ 꼴은 반드시 **유리화를 통해 부정형을 제거**해야 함\n2. $\\sqrt{x^2+a} - \\sqrt{x^2+b}$는 항상 유리화하면 분자가 $a-b$ 형태로 간단해짐",
