    "answer": 3,
    "explanation": "**[핵심 개념]**\n이 문제는 $\\frac{0}{0}$ 꼴의 부정형 극한입니다. $x \\to 2$일 때 분자와 분모가 모두 0으로 수렴하므로, 직접 대입으로는 계산할 수 없습니다. 이런 경우 인수분해나 분모의 유리화를 이용하여 부정형을 해결해야 합니다.\n\n**[풀이]**\n\n**Step 1: 부정형 확인**\n\n$x = 2$를 직접 대입하면:\n- 분자: $2^2 - 4 = 0$\n- 분모: $\\sqrt{3(2) + 3} - 3 = \\sqrt{9} - 3 = 0$\n\n$\\frac{0}{0}$ 꼴이므로 변형이 필요합니다.\n\n**Step 2: 분자 인수분해**\n\n$$x^2 - 4 = (x-2)(x+2)$$\n\n**Step 3: 분모 유리화**\n\n분모에 무리식이 있으므로 켤레식을 곱합니다:\n\n$$\\sqrt{3x + 3} - 3 = \\frac{(\\sqrt{3x+3}-3)(\\sqrt{3x+3}+3)}{\\sqrt{3x+3}+3}$$\n\n$$= \\frac{(3x+3) - 9}{\\sqrt{3x+3}+3} = \\frac{3x - 6}{\\sqrt{3x+3}+3}$$\n\n$$= \\frac{3(x-2)}{\\sqrt{3x+3}+3}$$\n\n**Step 4: 극한값 계산**\n\n$$\\lim_{x \\to 2} \\frac{x^2 - 4}{\\sqrt{3x + 3} - 3} = \\lim_{x \\to 2} \\frac{(x-2)(x+2)}{\\frac{3(x-2)}{\\sqrt{3x+3}+3}}$$\n\n$$= \\lim_{x \\to 2} \\frac{(x-2)(x+2) \\cdot (\\sqrt{3x+3}+3)}{3(x-2)}$$\n\n$(x-2)$로 약분하면:\n\n$$= \\lim_{x \\to 2} \\frac{(x+2)(\\sqrt{3x+3}+3)}{3}$$\n\n**Step 5: 직접 대입**\n\n$$= \\frac{(2+2)(\\sqrt{9}+3)}{3} = \\frac{4 \\cdot 6}{3} = \\frac{24}{3} = 8$$\n\n**[정답 확인]**\n분자와 분모를 각각 $(x-2)$로 인수분해한 후 약분하고 극한값을 구하면 8이 나옵니다.\n\n**[오답 분석]**\n- ① 2: 분모 유리화를 하지 않거나 불완전하게 계산한 경우\n- ② 4: 분모의 켤레식 덧셈 결과를 잘못 계산한 경우\n- ③ 6: 분자의 $(x+2)$와 분모의 $(\\sqrt{3x+3}+3)|_{x=2}=6$만 곱한 경우\n- ⑤ 12: 분모의 3으로 나누지 않은 경우\n\n**[핵심 포인트]**\n분모에 무리식이 있을 때는 **켤레식을 이용한 유리화**를 먼저 진행하고, $(x-a)$ 인수로 약분하여 부정형을 해결합니다. 유리화 공식 $\\sqrt{A} - B \\to \\frac{A-B^2}{\\sqrt{A}+B}$ 를 정확히 적용하는 것이 중요합니다.",
