    "explanation": "**[핵심 개념]**\n극한이 존재하기 위한 조건을 이해해야 합니다. 분모가 0으로 수렴할 때 극한값이 유한한 값으로 존재하려면, 분자도 같은 점에서 0으로 수렴해야 합니다. 이를 부정형 $\\frac{0}{0}$의 해소라고 하며, 이 경우 분자를 인수분해하여 공통인수를 약분할 수 있습니다.\n\n**[풀이]**\n\n**Step 1: 극한이 존재하기 위한 필요조건**\n\n$x \\to 2$일 때 분모 $x - 2 \\to 0$입니다.\n\n극한값이 7(유한한 값)로 존재하려면, 분자도 $x = 2$에서 0이 되어야 합니다. 즉:\n$$2^2 + a(2) + b = 0$$\n$$4 + 2a + b = 0$$\n$$2a + b = -4 \\cdots (1)$$\n\n**Step 2: 분자를 인수분해**\n\n분자가 $x = 2$를 근으로 가지므로:\n$$x^2 + ax + b = (x-2)(x-c)$$\n\n우변을 전개하면:\n$$(x-2)(x-c) = x^2 - (2+c)x + 2c$$\n\n계수를 비교하면:\n- $a = -(2+c)$ 즉, $c = -a-2$\n- $b = 2c = 2(-a-2) = -2a-4$\n\n식 (1)에 대입하면:\n$$2a + (-2a-4) = -4$$\n$$-4 = -4$$ ✓ (일치 확인)\n\n**Step 3: 극한값 계산**\n\n$$\\lim_{x \\to 2} f(x) = \\lim_{x \\to 2} \\frac{(x-2)(x-c)}{x-2} = \\lim_{x \\to 2} (x-c) = 2-c$$\n\n주어진 조건에서:\n$$2 - c = 7$$\n$$c = -5$$\n\n**Step 4: $a$, $b$ 구하기**\n\n$c = -a - 2 = -5$에서:\n$$-a - 2 = -5$$\n$$a = 3$$\n\n$b = 2c = 2(-5) = -10$\n\n**Step 5: $a + b$ 계산**\n\n$$a + b = 3 + (-10) = -7$$\n\n**[정답 확인]**\n검증: $f(x) = \\frac{x^2 + 3x - 10}{x-2} = \\frac{(x-2)(x+5)}{x-2} = x+5$ (단, $x \\neq 2$)이므로 $\\lim_{x \\to 2} f(x) = 2+5 = 7$ ✓\n\n**[오답 분석]**\n- ① $-10$: $b$의 값만 구한 경우\n- ③ $-3$: 계산 실수로 $a = 2, b = -5$ 등으로 잘못 구한 경우\n- ④ $3$: $a$의 값만 구한 경우\n- ⑤ $7$: 극한값 자체를 $a+b$로 착각한 경우\n\n**[핵심 포인트]**\n분모가 0으로 가는 극한이 존재하면 분자도 반드시 0이 되어야 합니다. 이 조건으로부터 미지수 사이의 관계식을 먼저 세우는 것이 해결의 핵심입니다.",
