    "_type": "limit",
    "type": "극한",
    "problem": "$\\lim_{x \\to \\infty} \\left(\\sqrt{x^2 + 5x + 2} - \\sqrt{x^2 + x - 1}\\right)$의 값을 구하시오.",
    "answerType": "short",
