    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n$\\infty - \\infty$ 꼴의 극한을 계산할 때는 유리화(분자의 유리화)를 사용합니다. $\\sqrt{A} - \\sqrt{B}$ 형태일 때, $\\frac{(\\sqrt{A} - \\sqrt{B})(\\sqrt{A} + \\sqrt{B})}{\\sqrt{A} + \\sqrt{B}} = \\frac{A - B}{\\sqrt{A} + \\sqrt{B}}$로 변형하여 계산합니다. 또한 $x \\to \\infty$일 때 $\\sqrt{x^2 + ax + b} \\approx |x|\\sqrt{1 + \\frac{a}{x} + \\frac{b}{x^2}} \\approx |x|(1 + \\frac{a}{2x})$로 근사할 수 있습니다.\n\n**[풀이]**\n\n주어진 극한은 $\\infty - \\infty$ 꼴이므로 분자를 유리화합니다.\n\n$$\\lim_{x \\to \\infty} \\left(\\sqrt{x^2 + 5x + 2} - \\sqrt{x^2 + x - 1}\\right)$$\n\n분자와 분모에 $\\sqrt{x^2 + 5x + 2} + \\sqrt{x^2 + x - 1}$를 곱합니다:\n\n$$= \\lim_{x \\to \\infty} \\frac{(\\sqrt{x^2 + 5x + 2} - \\sqrt{x^2 + x - 1})(\\sqrt{x^2 + 5x + 2} + \\sqrt{x^2 + x - 1})}{\\sqrt{x^2 + 5x + 2} + \\sqrt{x^2 + x - 1}}$$\n\n분자를 전개하면:\n\n$$= \\lim_{x \\to \\infty} \\frac{(x^2 + 5x + 2) - (x^2 + x - 1)}{\\sqrt{x^2 + 5x + 2} + \\sqrt{x^2 + x - 1}}$$\n\n$$= \\lim_{x \\to \\infty} \\frac{4x + 3}{\\sqrt{x^2 + 5x + 2} + \\sqrt{x^2 + x - 1}}$$\n\n$x \\to \\infty$일 때, 분모를 정리합니다. 분모와 분자를 $x$로 나누면:\n\n$$= \\lim_{x \\to \\infty} \\frac{4 + \\frac{3}{x}}{\\frac{\\sqrt{x^2 + 5x + 2}}{x} + \\frac{\\sqrt{x^2 + x - 1}}{x}}$$\n\n$x > 0$이므로 $\\sqrt{x^2 + 5x + 2} = x\\sqrt{1 + \\frac{5}{x} + \\frac{2}{x^2}}$이고, $x \\to \\infty$일 때 $\\sqrt{1 + \\frac{5}{x} + \\frac{2}{x^2}} \\to 1$\n\n마찬가지로 $\\sqrt{1 + \\frac{1}{x} - \\frac{1}{x^2}} \\to 1$\n\n따라서:\n\n$$= \\lim_{x \\to \\infty} \\frac{4 + \\frac{3}{x}}{1 + 1} = \\frac{4}{2} = 2$$\n\n**[정답 확인]**\n\n유리화를 통해 $\\frac{4x + 3}{2x}$ 형태가 되며, $x \\to \\infty$일 때 $\\frac{4x}{2x} = 2$로 수렴합니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으므로 가능한 오답을 분석하면:\n- **4**: 유리화 후 분자 $4x + 3$만 고려하고 분모를 $2x$로 계산하지 않은 경우\n- **0**: 분자의 최고차항 차이를 무시한 경우\n- **1**: 분모를 $2x$ 대신 $4x$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n1. **$\\infty - \\infty$ 꼴 극한은 유리화가 필수**: $\\sqrt{A} - \\sqrt{B} = \\frac{A-B}{\\sqrt{A}+\\sqrt{B}}$ 형태로 변형\n2. **$x \\to \\infty$에서 $\\sqrt{x^2 + ax + b} \\sim x$**: 분자를 $x$로 나누고 분모도 맞춰서 계산하면 간단히 정리됨",
