    "problem": "함수 $f(x) = \\begin{cases} x^2 + 1 & (x < 1) \\\\ 3x - k & (x \\geq 1) \\end{cases}$이 $x = 1$에서 연속일 때, 상수 $k$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n함수가 특정 점에서 연속이기 위한 조건은 다음 세 가지를 모두 만족해야 합니다:\n1. $f(a)$가 정의되어 있다\n2. $\\lim_{x \\to a} f(x)$가 존재한다\n3. $\\lim_{x \\to a} f(x) = f(a)$\n\n특히 $x = a$에서 연속이려면, 좌극한과 우극한이 같아야 하고, 함수값과도 같아야 합니다.\n$$\\lim_{x \\to a^-} f(x) = \\lim_{x \\to a^+} f(x) = f(a)$$\n\n**[풀이]**\n\n**Step 1: 함수값 $f(1)$ 구하기**\n\n$x = 1$에서는 $x \\geq 1$인 경우에 해당하므로:\n$$f(1) = 3(1) - k = 3 - k$$\n\n**Step 2: 좌극한 $\\lim_{x \\to 1^-} f(x)$ 구하기**\n\n$x < 1$일 때 $f(x) = x^2 + 1$이므로:\n$$\\lim_{x \\to 1^-} f(x) = 1^2 + 1 = 2$$\n\n**Step 3: 우극한 $\\lim_{x \\to 1^+} f(x)$ 구하기**\n\n$x \\geq 1$일 때 $f(x) = 3x - k$이므로:\n$$\\lim_{x \\to 1^+} f(x) = 3(1) - k = 3 - k$$\n\n**Step 4: 연속 조건 적용**\n\n$x = 1$에서 연속이려면 좌극한 = 우극한 = 함수값이어야 합니다:\n$$\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^+} f(x) = f(1)$$\n\n$$2 = 3 - k = 3 - k$$\n\n따라서:\n$$2 = 3 - k$$\n$$k = 3 - 2 = 1$$\n\n**[정답 확인]**\n$k = 1$일 때, 좌극한 = 2, 우극한 = $3-1=2$, 함수값 = 2로 모두 같아서 $x=1$에서 연속입니다.\n\n**[오답 분석]**\n객관식이 아니라 서술형 문제이므로, 만약 학생이 자주 하는 실수는:\n- $x=1$일 때 왼쪽 식 $x^2+1$을 사용해서 $k=0$으로 답하는 경우 (정의역 확인 부족)\n- 우극한만 고려하고 좌극한을 빠뜨리는 경우\n- 연속 조건의 의미를 잘못 이해하는 경우\n\n**[핵심 포인트]**\n구간별로 정의된 함수가 경계점에서 연속이려면, **좌극한 = 우극한 = 함수값**이 모두 같아야 합니다. 특히 함수값은 그 점에서 정의된 식을 사용해야 한다는 점을 잊지 마세요.",
