    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n함수의 연속성 조건: 함수 $f(x)$가 $x = c$에서 연속이려면 다음 세 조건을 모두 만족해야 합니다.\n1. $f(c)$가 정의되어 있다\n2. $\\lim_{x \\to c} f(x)$가 존재한다\n3. $\\lim_{x \\to c} f(x) = f(c)$\n\n특히, $x = 3$에서 연속이려면 $\\lim_{x \\to 3} f(x) = f(3) = a$이어야 합니다.\n\n**[풀이]**\n\n$x \\neq 3$일 때 $f(x) = \\dfrac{x^2 - 9}{x - 3}$를 먼저 정리합니다.\n\n분자를 인수분해하면:\n$$f(x) = \\dfrac{x^2 - 9}{x - 3} = \\dfrac{(x-3)(x+3)}{x - 3}$$\n\n$x \\neq 3$이므로 $(x-3)$으로 약분할 수 있습니다:\n$$f(x) = x + 3 \\quad (x \\neq 3)$$\n\n이제 $x = 3$에서의 극한값을 구합니다:\n$$\\lim_{x \\to 3} f(x) = \\lim_{x \\to 3} (x + 3) = 3 + 3 = 6$$\n\n함수가 $x = 3$에서 연속이려면:\n$$\\lim_{x \\to 3} f(x) = f(3) = a$$\n\n따라서:\n$$a = 6$$\n\n**[정답 확인]**\n\n$a = 6$일 때, $\\lim_{x \\to 3} f(x) = 6 = f(3)$이므로 연속의 정의를 만족합니다.\n\n**[오답 분석]**\n\n- **① 3**: $\\lim_{x \\to 3} f(x)$를 구하지 못하고 $f(3)$의 정의역 조건만 본 경우\n- **③ 9**: 분자의 $x^2 - 9$에서 $x = 3$을 대입한 값으로 착각\n- **④ 0**: 분모가 0이 되는 것에만 초점을 맞춘 경우\n- **⑤ -6**: 부호를 잘못 계산하거나 $3 - 3 = 0$으로 잘못 생각한 경우\n\n**[핵심 포인트]**\n\n분수 함수에서 분자와 분모의 공통인수를 약분한 후 극한값을 구해야 합니다. 불연속점에서 함수를 연속으로 만드는 값은 그 점에서의 극한값과 같다는 것을 기억하세요.",
