    "answer": 4,
    "explanation": "**[핵심 개념]**\n함수가 어떤 점에서 연속이기 위한 조건은 다음 세 가지를 모두 만족해야 합니다.\n1. $f(c)$가 정의되어 있음\n2. $\\lim_{x \\to c} f(x)$가 존재함\n3. $\\lim_{x \\to c} f(x) = f(c)$\n\n특히 $x = 2$에서 연속이려면 $\\lim_{x \\to 2} f(x) = f(2) = a$를 만족해야 합니다.\n\n**[풀이]**\n\n$x = 2$에서 함수 $f(x)$가 연속이려면:\n$$\\lim_{x \\to 2} f(x) = f(2)$$\n\n먼저 $f(2) = a$입니다.\n\n이제 $\\lim_{x \\to 2} f(x)$를 구합니다. $x \\neq 2$일 때 $f(x) = \\dfrac{x^2 - 4}{x - 2}$이므로:\n\n$$\\lim_{x \\to 2} f(x) = \\lim_{x \\to 2} \\frac{x^2 - 4}{x - 2}$$\n\n분자를 인수분해하면:\n$$= \\lim_{x \\to 2} \\frac{(x-2)(x+2)}{x - 2}$$\n\n$x \\to 2$일 때 $x \\neq 2$이므로 $(x-2)$로 약분 가능합니다:\n$$= \\lim_{x \\to 2} (x + 2)$$\n\n$$= 2 + 2 = 4$$\n\n연속 조건에 의해:\n$$\\lim_{x \\to 2} f(x) = f(2)$$\n$$4 = a$$\n\n따라서 $a = 4$\n\n**[정답 확인]**\n$a = 4$일 때 $\\lim_{x \\to 2} f(x) = 4 = f(2)$이므로 $x = 2$에서 연속입니다.\n\n**[오답 분석]**\n객관식이 아닌 단답형이지만, 흔한 오류는:\n- $a = 0$: 분자를 $x^2 - 4$로만 생각하고 약분을 놓친 경우\n- $a = 2$: $x = 2$를 직접 대입한 경우 (0/0 꼴이므로 불가)\n- 극한을 계산하지 않고 정의역 밖의 함숫값으로 생각한 경우\n\n**[핵심 포인트]**\n불연속점에서 함수를 연속으로 만드는 문제는 **극한값을 구해서 그 값에 함숫값을 맞추는 것**이 핵심입니다. 분자/분모가 모두 0이 되는 꼴(0/0)에서는 반드시 인수분해 후 약분해야 합니다.",
