    "type": "연속",
    "problem": "함수 $f(x) = \\begin{cases} 2x + a & (x < 1) \\\\ x^2 + bx & (x \\geq 1) \\end{cases}$이 $x = 1$에서 연속이고 미분가능할 때, $a + b$의 값을 구하시오.",
    "answerType": "short",
