    "answer": -1,
    "explanation": "**[핵심 개념]**\n구간별로 정의된 함수가 특정 점에서 연속이고 미분가능하기 위한 조건:\n- **연속성**: $\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^+} f(x) = f(1)$\n- **미분가능성**: $f'(1^-) = f'(1^+)$ (좌미분계수 = 우미분계수)\n\n연속이어야 미분가능하므로, 먼저 연속 조건을 적용한 후 미분가능 조건을 적용합니다.\n\n**[풀이]**\n\n**Step 1: 연속성 조건 적용**\n\n$x = 1$에서 연속이려면 좌극한 = 우극한 = 함수값이어야 합니다.\n\n좌극한: $\\lim_{x \\to 1^-} f(x) = 2(1) + a = 2 + a$\n\n우극한 (함수값): $f(1) = 1^2 + b \\cdot 1 = 1 + b$\n\n연속성 조건:\n$$2 + a = 1 + b$$\n$$a - b = -1 \\cdots (1)$$\n\n**Step 2: 미분가능성 조건 적용**\n\n좌미분계수: $x < 1$일 때 $f(x) = 2x + a$이므로\n$$f'(1^-) = 2$$\n\n우미분계수: $x \\geq 1$일 때 $f(x) = x^2 + bx$이므로\n$$f'(1^+) = 2x + b\\big|_{x=1} = 2(1) + b = 2 + b$$\n\n미분가능성 조건:\n$$2 = 2 + b$$\n$$b = 0 \\cdots (2)$$\n\n**Step 3: $a$ 구하기**\n\n식 (2)에서 $b = 0$을 식 (1)에 대입:\n$$a - 0 = -1$$\n$$a = -1$$\n\n**Step 4: 답 계산**\n\n$$a + b = -1 + 0 = -1$$\n\n**[정답 확인]**\n연속성 조건 ($2 + (-1) = 1 + 0 = 1$ ✓)과 미분가능성 조건 ($f'(1^-) = 2 = f'(1^+)$ ✓)을 모두 만족하므로 $a + b = -1$이 정답입니다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 오류를 언급하면:\n- **연속성만 고려하는 경우**: $a - b = -1$만 얻어서 유일한 답을 구하지 못함\n- **미분가능성만 고려하는 경우**: $b = 0$만 얻어서 $a$를 구하지 못함\n- **두 조건을 모두 적용하지 않는 경우**: 부정확한 답 도출\n\n**[핵심 포인트]**\n구간별 함수의 특정점에서 미분가능 $\\Rightarrow$ 먼저 연속 조건으로 한 개의 방정식, 그 다음 미분계수 조건으로 또 다른 방정식을 세워 미지수 2개를 동시에 해결해야 합니다.",
