    "problem": "함수 $f(x) = \\begin{cases} \\dfrac{\\sqrt{x+1} - 1}{x} & (x \\neq 0) \\\\ k & (x = 0) \\end{cases}$이 $x = 0$에서 연속일 때, $2k$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n함수가 특정 점에서 연속이기 위한 조건은 $\\lim_{x \\to a} f(x) = f(a)$를 만족해야 합니다. 이 문제에서는 $x=0$에서 연속이므로 $\\lim_{x \\to 0} f(x) = f(0) = k$이어야 합니다. \n\n$x \\neq 0$일 때 극한값을 구하기 위해 분자의 무리식을 유리화하는 기법을 사용합니다.\n\n**[풀이]**\n\n$x=0$에서 연속이려면:\n$$\\lim_{x \\to 0} f(x) = f(0) = k$$\n\n$x \\neq 0$일 때의 극한값을 구하기 위해 분자를 유리화합니다.\n\n$$\\lim_{x \\to 0} \\frac{\\sqrt{x+1} - 1}{x}$$\n\n분자와 분모에 $\\sqrt{x+1} + 1$을 곱합니다:\n\n$$\\lim_{x \\to 0} \\frac{\\sqrt{x+1} - 1}{x} \\cdot \\frac{\\sqrt{x+1} + 1}{\\sqrt{x+1} + 1}$$\n\n$$= \\lim_{x \\to 0} \\frac{(\\sqrt{x+1})^2 - 1^2}{x(\\sqrt{x+1} + 1)}$$\n\n$$= \\lim_{x \\to 0} \\frac{x+1 - 1}{x(\\sqrt{x+1} + 1)}$$\n\n$$= \\lim_{x \\to 0} \\frac{x}{x(\\sqrt{x+1} + 1)}$$\n\n$x \\neq 0$이므로 약분하면:\n\n$$= \\lim_{x \\to 0} \\frac{1}{\\sqrt{x+1} + 1}$$\n\n$x \\to 0$일 때:\n\n$$= \\frac{1}{\\sqrt{0+1} + 1} = \\frac{1}{1 + 1} = \\frac{1}{2}$$\n\n따라서 $k = \\dfrac{1}{2}$\n\n$$2k = 2 \\times \\frac{1}{2} = 1$$\n\n**[정답 확인]**\n\n연속성 조건에서 $\\lim_{x \\to 0} f(x) = \\frac{1}{2}$이므로 $k = \\frac{1}{2}$, 따라서 $2k = 1$입니다.\n\n**[오답 분석]**\n\n객관식 선택지가 주어지지 않았으므로 일반적인 오류를 설명하면:\n- 유리화를 하지 않고 직접 대입하려 하면 $\\frac{0}{0}$ 꼴의 부정형이 되어 계산 불가\n- 유리화 후 약분을 놓치면 극한값을 구할 수 없음\n- $k$ 값 자체를 답으로 착각하면 $\\frac{1}{2}$이 답이 됨\n\n**[핵심 포인트]**\n\n무리식이 포함된 극한에서는 **분자의 유리화**를 먼저 시도하세요. 분자와 분모에 켤레식을 곱하여 분자의 무리식을 제거하는 것이 표준 풀이법입니다.",
