    "problem": "함수 $f(x) = (x - 1)(x - 2)$에 대해 $g(x) = \\dfrac{f(x)}{|x - 1|}$이 연속이 아닌 점의 개수는?",
    "answerType": "choice",
    "choices": [
      "① 0개",
      "② 1개",
      "③ 2개",
      "④ 3개",
      "⑤ 무한개"
    ],
    "answer": 1,
    "explanation": "**[핵심 개념]**\n함수의 연속성을 판정하기 위해서는 다음을 확인해야 합니다:\n- 함수가 정의되지 않는 점 (정의역 밖)\n- 함수의 극한이 존재하지 않는 점\n- 극한값과 함수값이 다른 점\n\n절댓값 함수는 $|x-a| = 0$인 점에서 미분불가능하거나 정의에 문제가 생길 수 있으므로 주의깊게 살펴야 합니다.\n\n**[풀이]**\n\n$f(x) = (x-1)(x-2)$이고, $g(x) = \\dfrac{f(x)}{|x-1|}$입니다.\n\n**Step 1: 함수 정의역 확인**\n\n분모가 0이 되면 함수가 정의되지 않으므로, $|x-1| = 0$ 즉, $x = 1$에서 $g(x)$는 정의되지 않습니다.\n\n따라서 $x = 1$은 정의역에 포함되지 않습니다.\n\n**Step 2: $x \\neq 1$일 때 $g(x)$ 정리**\n\n$x \\neq 1$일 때, 절댓값을 풀어서 정리합니다.\n\n$|x-1| = \\begin{cases} x-1 & \\text{if } x > 1 \\\\ -(x-1) & \\text{if } x < 1 \\end{cases}$\n\n따라서:\n\n$$g(x) = \\begin{cases} \\dfrac{(x-1)(x-2)}{x-1} = x-2 & \\text{if } x > 1 \\\\ \\dfrac{(x-1)(x-2)}{-(x-1)} = -(x-2) & \\text{if } x < 1 \\end{cases}$$\n\n$$g(x) = \\begin{cases} x-2 & \\text{if } x > 1 \\\\ -x+2 & \\text{if } x < 1 \\end{cases}$$\n\n**Step 3: $x = 1$에서의 연속성 검토**\n\n$x = 1$에서 좌극한과 우극한을 계산합니다:\n\n$$\\lim_{x \\to 1^+} g(x) = \\lim_{x \\to 1^+} (x-2) = 1-2 = -1$$\n\n$$\\lim_{x \\to 1^-} g(x) = \\lim_{x \\to 1^-} (-x+2) = -1+2 = 1$$\n\n좌극한 $1$과 우극한 $-1$이 다르므로, $\\lim_{x \\to 1} g(x)$는 존재하지 않습니다.\n\n또한 $g(1)$은 정의되지 않습니다.\n\n따라서 $x = 1$에서 $g(x)$는 연속이 아닙니다.\n\n**Step 4: 다른 점에서의 연속성**\n\n- $x > 1$일 때: $g(x) = x-2$는 다항함수이므로 연속\n- $x < 1$일 때: $g(x) = -x+2$는 다항함수이므로 연속\n\n따라서 $x = 1$을 제외한 모든 점에서 $g(x)$는 연속입니다.\n\n**정답 확인**\n\n$g(x)$가 연속이 아닌 점은 $x = 1$ 하나뿐입니다. **1개**\n\n**[오답 분석]**\n\n- ① 0개: $x=1$에서 정의되지 않으며 좌극한과 우극한이 다르므로 불연속점이 존재합니다.\n- ③ 2개: $x=1$만이 불연속점입니다. $x > 1$과 $x < 1$에서는 각각 일차함수로 정의되어 연속입니다.\n- ④ 3개: 불연속점이 3개 이상인 경우는 없습니다.\n- ⑤ 무한개: 절댓값이 있더라도 절댓값이 0인 한 점에서만 불연속입니다.\n\n**[핵심 포인트]**\n\n1. $\\dfrac{f(x)}{|x-a|}$ 형태의 함수는 $x=a$에서 분모가 0이 되므로, 그 점에서의 좌극한과 우극한을 반드시 확인해야 합니다.\n2. 좌극한과 우극한이 다르면 불연속이며, 만약 같으면 그 값으로 함수를 재정의하여 연속으로 만들 수 있는지 판단합니다.",
