    "type": "연속",
    "problem": "함수 $f(x) = [x] + [-x]$ (단, $[x]$는 가우스 함수)가 연속인 점의 집합을 구하면?",
    "answerType": "choice",
    "choices": [
      "① 모든 실수",
      "② 모든 정수",
      "③ 정수가 아닌 모든 실수",
      "④ $x > 0$",
      "⑤ 공집합"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n가우스 함수 $[x]$는 $x$보다 작거나 같은 최대 정수이며, 모든 정수에서 불연속이고 정수가 아닌 점에서 연속입니다. 함수의 연속성은 $\\lim_{x \\to a^-} f(x) = \\lim_{x \\to a^+} f(x) = f(a)$를 만족할 때 $x=a$에서 연속입니다.\n\n**[풀이]**\n\n**1단계: $f(x) = [x] + [-x]$의 성질 파악**\n\n정수가 아닌 실수 $x$에 대해, $x = n + \\alpha$ (단, $n$은 정수, $0 < \\alpha < 1$)로 나타내면:\n- $[x] = n$\n- $[-x] = [-(n+\\alpha)] = [-n-\\alpha] = -n-1$\n- $f(x) = n + (-n-1) = -1$\n\n정수 $x = n$에 대해:\n- $[x] = n$\n- $[-x] = -n$\n- $f(x) = n + (-n) = 0$\n\n따라서 $f(x) = \\begin{cases} -1 & \\text{if } x \\notin \\mathbb{Z} \\\\ 0 & \\text{if } x \\in \\mathbb{Z} \\end{cases}$\n\n**2단계: 정수가 아닌 점에서의 연속성 검증**\n\n$x = c$ (정수 아님)인 점에서, $c$ 근처의 충분히 작은 구간에서는 $f(x) = -1$입니다.\n\n$$\\lim_{x \\to c^-} f(x) = -1, \\quad \\lim_{x \\to c^+} f(x) = -1, \\quad f(c) = -1$$\n\n따라서 모든 정수가 아닌 점에서 연속입니다.\n\n**3단계: 정수 점에서의 연속성 검증**\n\n$x = n$ (정수)인 점에서:\n\n$$\\lim_{x \\to n^-} f(x) = \\lim_{x \\to n^-} (-1) = -1$$\n$$\\lim_{x \\to n^+} f(x) = \\lim_{x \\to n^+} (-1) = -1$$\n$$f(n) = 0$$\n\n$-1 \\neq 0$이므로 모든 정수에서 불연속입니다.\n\n**4단계: 연속인 점의 집합**\n\n위의 분석에서 $f(x)$는 정수가 아닌 모든 실수에서 연속이고, 모든 정수에서 불연속입니다.\n\n**[정답 확인]**\n\n$f(x)$는 정수 점에서 점프 불연속을 가지며, 정수가 아닌 모든 점에서 연속이므로 정답은 **③**입니다.\n\n**[오답 분석]**\n\n- **①**: 모든 정수에서 불연속이므로 틀림\n- **②**: 정수 점에서 불연속이므로 틀림  \n- **④**: 음수 영역도 정수가 아니면 연속이므로 틀림\n- **⑤**: 정수가 아닌 무한히 많은 점에서 연속이므로 틀림\n\n**[핵심 포인트]**\n\n1. 가우스 함수 성질: 정수가 아닌 $x$에 대해 $[x] + [-x] = -1$이고, 정수 $x$에 대해 $[x] + [-x] = 0$\n2. 정수에서의 좌극한과 우극한은 같지만 함숫값과 다르므로 불연속, 정수가 아닌 점에서는 근처에서 함숫값이 일정하므로 연속",
