    "problem": "함수 $f(x) = \\begin{cases} x^2 + ax + b & (x \\leq 0) \\\\ \\dfrac{\\sin x}{x} & (x > 0) \\end{cases}$이 $x = 0$에서 연속이고 미분가능할 때, $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n함수가 어떤 점에서 연속이고 미분가능하기 위한 조건:\n- **연속성**: $\\lim_{x \\to 0^-} f(x) = \\lim_{x \\to 0^+} f(x) = f(0)$\n- **미분가능성**: $\\lim_{x \\to 0^-} f'(x) = \\lim_{x \\to 0^+} f'(x)$ (좌미분계수 = 우미분계수)\n\n또한 $\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1$이라는 중요한 극한값을 사용합니다.\n\n**[풀이]**\n\n**Step 1: 연속성 조건 적용**\n\n$x = 0$에서 연속이려면:\n$$f(0) = \\lim_{x \\to 0^-} f(x) = \\lim_{x \\to 0^+} f(x)$$\n\n좌극한: $\\lim_{x \\to 0^-} f(x) = \\lim_{x \\to 0^-} (x^2 + ax + b) = b$\n\n우극한: $\\lim_{x \\to 0^+} f(x) = \\lim_{x \\to 0^+} \\frac{\\sin x}{x} = 1$\n\n함수값: $f(0) = 0^2 + a \\cdot 0 + b = b$\n\n따라서 $b = 1$\n\n**Step 2: 미분가능성 조건 적용**\n\n각 구간에서 도함수를 구합니다.\n\n$x < 0$일 때: $f'(x) = 2x + a$\n\n$x > 0$일 때: $f'(x) = \\frac{d}{dx}\\left(\\frac{\\sin x}{x}\\right) = \\frac{x\\cos x - \\sin x}{x^2}$\n\n좌미분계수: $\\lim_{x \\to 0^-} f'(x) = \\lim_{x \\to 0^-} (2x + a) = a$\n\n우미분계수: $\\lim_{x \\to 0^+} \\frac{x\\cos x - \\sin x}{x^2}$\n\n우미분계수를 계산하기 위해 로피탈의 정리를 적용합니다:\n$$\\lim_{x \\to 0^+} \\frac{x\\cos x - \\sin x}{x^2} = \\lim_{x \\to 0^+} \\frac{\\cos x - x\\sin x - \\cos x}{2x} = \\lim_{x \\to 0^+} \\frac{-x\\sin x}{2x} = \\lim_{x \\to 0^+} \\frac{-\\sin x}{2}$$\n\n다시 로피탈의 정리를 적용하면:\n$$\\lim_{x \\to 0^+} \\frac{-\\sin x}{2} = \\frac{0}{2} = 0$$\n\n미분가능 조건에서: $a = 0$\n\n**Step 3: 답 구하기**\n\n$$a + b = 0 + 1 = 1$$\n\n**[정답 확인]**\n\n$a = 0, b = 1$일 때 $x = 0$에서 함수는 연속이고(양쪽 극한값이 1), 좌미분계수와 우미분계수가 모두 0으로 같아 미분가능합니다.\n\n**[오답 분석]**\n\n이 문제는 선택지가 없으므로 계산 오류 가능성:\n- 우미분계수 계산에서 로피탈의 정리를 잘못 적용하면 다른 값 도출\n- 연속성 조건을 놓쳐 $b = 1$을 구하지 못하면 오류 발생\n\n**[핵심 포인트]**\n\n1. **연속성이 먼저**: 함수의 연속성 조건으로 $b$값 결정, 이를 통해 우극한이 1임을 알 수 있습니다.\n2. **로피탈의 정리 활용**: 우미분계수 계산 시 $\\frac{0}{0}$ 꼴의 부정형에서 로피탈을 정확히 적용하는 것이 핵심입니다.",
