    "explanation": "**[핵심 개념]**\n함수의 연속성과 불연속점을 판별하기 위해서는 좌극한과 우극한을 각각 구해야 합니다. 절댓값이 포함된 함수는 절댓값 내부가 0이 되는 점에서 함수의 정의가 달라지므로, 그 점 전후로 나누어 생각해야 합니다. 좌극한은 $\\lim_{x \\to a^-}$, 우극한은 $\\lim_{x \\to a^+}$ 기호로 표현하며, 두 극한값이 다르면 그 점에서 불연속입니다.\n\n**[풀이]**\n\n**1단계: 불연속인 점 찾기**\n\n$f(x) = \\dfrac{x^2 - 1}{|x - 1|}$에서 절댓값 $|x - 1|$이 0이 되는 점은 $x = 1$입니다.\n\n따라서 $x = 1$에서 함수가 불연속일 가능성이 있습니다.\n\n**2단계: 절댓값을 풀어서 표현하기**\n\n$|x - 1| = \\begin{cases} x - 1 & \\text{if } x > 1 \\\\ -(x-1) & \\text{if } x < 1 \\end{cases}$\n\n따라서:\n$$f(x) = \\begin{cases} \\dfrac{x^2 - 1}{x - 1} & \\text{if } x > 1 \\\\ \\dfrac{x^2 - 1}{-(x-1)} & \\text{if } x < 1 \\end{cases}$$\n\n**3단계: 우극한 구하기 ($x \\to 1^+$)**\n\n$x > 1$일 때, $f(x) = \\dfrac{x^2 - 1}{x - 1}$\n\n분자를 인수분해하면:\n$$f(x) = \\dfrac{(x-1)(x+1)}{x - 1} = x + 1 \\quad (x \\neq 1)$$\n\n따라서:\n$$\\lim_{x \\to 1^+} f(x) = \\lim_{x \\to 1^+} (x + 1) = 1 + 1 = 2$$\n\n**4단계: 좌극한 구하기 ($x \\to 1^-$)**\n\n$x < 1$일 때, $f(x) = \\dfrac{x^2 - 1}{-(x-1)}$\n\n분자를 인수분해하면:\n$$f(x) = \\dfrac{(x-1)(x+1)}{-(x - 1)} = \\dfrac{x+1}{-1} = -(x + 1) \\quad (x \\neq 1)$$\n\n따라서:\n$$\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^-} (-(x + 1)) = -(1 + 1) = -2$$\n\n**5단계: 좌극한과 우극한의 합**\n\n$$\\lim_{x \\to 1^-} f(x) + \\lim_{x \\to 1^+} f(x) = -2 + 2 = 0$$\n\n**[정답 확인]**\n\n$x = 1$에서 좌극한은 $-2$, 우극한은 $2$이므로 두 극한값이 다르며, 따라서 $x = 1$에서 불연속이고, 그들의 합은 $0$입니다.\n\n**[오답 분석]**\n\n- ①, ② (음수): 우극한의 부호를 잘못 계산했거나, 하나의 극한값만 더한 경우\n- ④, ⑤ (양수): 좌극한의 부호를 잘못 계산했거나, 절댓값 처리 시 $x < 1$일 때 $|x-1| = x-1$로 잘못 적용한 경우\n\n**[핵심 포인트]**\n\n절댓값이 있는 함수에서 불연속점은 절댓값 내부가 0이 되는 점이며, 이 점에서 반드시 좌극한과 우극한을 분리하여 계산해야 합니다. $x < a$일 때와 $x > a$일 때 절댓값의 부호가 반대이므로 각각 다른 식으로 표현됩니다.",
