    "type": "연속",
    "problem": "함수 $f(x) = \\begin{cases} \\dfrac{x^3 - 8}{x^2 - 4} & (x \\neq 2, x \\neq -2) \\\\ a & (x = 2) \\\\ b & (x = -2) \\end{cases}$이 $x = 2$에서 연속일 때, $4a$의 값을 구하시오.",
    "answerType": "short",
