    "problem": "함수 $f(x) = x^3 - 3x + 1$에 대해 구간 $[0, 1]$에서 중간값 정리에 의해 $f(c) = 0$인 $c$가 존재함을 보일 수 있다. $f(0)$과 $f(1)$의 곱의 값은?",
    "answerType": "choice",
