    "type": "연속",
    "problem": "함수 $f(x)$가 모든 실수에서 연속이고 $f(x) = x^2 f\\left(\\dfrac{1}{x}\\right)$ ($x \\neq 0$)을 만족할 때, $f(1) + f(-1)$이 항상 짝수임을 보이시오. $f(1) = 3$일 때 $f(-1)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": -3,
    "explanation": "**[핵심 개념]**\n\n함수 방정식에서 주어진 조건을 이용하여 함수의 특수한 성질을 찾아내는 문제입니다. 주요 개념은:\n- 함수 방정식: $f(x) = x^2 f\\left(\\frac{1}{x}\\right)$에서 $x$를 다른 값으로 치환\n- 함수의 연속성과 특정 점에서의 함수값 관계\n- 홀함수/짝함수의 성질 활용\n\n**[풀이]**\n\n**Step 1: 주어진 함수 방정식에서 $x=1$을 대입**\n\n$$f(1) = 1^2 \\cdot f(1) = f(1)$$\n\n이는 항상 참이므로 $f(1)$은 자유롭게 결정됩니다. 문제에서 $f(1) = 3$으로 주어졌습니다.\n\n**Step 2: 주어진 함수 방정식에서 $x=-1$을 대입**\n\n$$f(-1) = (-1)^2 \\cdot f\\left(\\frac{1}{-1}\\right) = 1 \\cdot f(-1) = f(-1)$$\n\n이것도 항상 참입니다.\n\n**Step 3: 함수 방정식을 다시 정리하여 관계식 찾기**\n\n주어진 조건: $f(x) = x^2 f\\left(\\frac{1}{x}\\right)$ ... (1)\n\n(1)에서 $x$ 대신 $\\frac{1}{x}$를 대입하면:\n\n$$f\\left(\\frac{1}{x}\\right) = \\frac{1}{x^2} \\cdot f(x)$$ ... (2)\n\n(2)를 (1)에 대입하면:\n\n$$f(x) = x^2 \\cdot \\frac{1}{x^2} \\cdot f(x) = f(x)$$\n\n이는 항등식이므로 새로운 정보를 주지 않습니다.\n\n**Step 4: $f(x)$의 형태 분석**\n\n함수 방정식 $f(x) = x^2 f\\left(\\frac{1}{x}\\right)$에서 $f(x)$를 다음과 같이 표현할 수 있습니다:\n\n$$f(x) = g(x) + h(x)$$\n\n여기서 $g(x)$는 짝함수, $h(x)$는 홀함수입니다.\n\n짝함수 부분: $g(x) = g(-x)$이므로\n$$g(x) = x^2 g\\left(\\frac{1}{x}\\right)$$\n\n홀함수 부분: $h(-x) = -h(x)$이므로\n$$h(x) = x^2 h\\left(\\frac{1}{x}\\right)$$\n\n$h(-x) = -h(x)$에 $x$ 대신 $-x$를 넣으면:\n$$h(x) = -h(-x)$$\n\n또한 $h(-x) = (-x)^2 h\\left(\\frac{1}{-x}\\right) = x^2 h\\left(-\\frac{1}{x}\\right)$\n\n$h$가 홀함수이므로: $h\\left(-\\frac{1}{x}\\right) = -h\\left(\\frac{1}{x}\\right)$\n\n따라서: $h(-x) = -x^2 h\\left(\\frac{1}{x}\\right)$\n\n**Step 5: $f(-1)$ 구하기**\n\n홀함수 부분이 $h(-1) = -(-1)^2 h(1) = -h(1)$를 만족해야 하고,\n$h(-1) = -h(1)$이므로 이는 일관성이 있습니다.\n\n$f(1) + f(-1)$이 항상 짝수라는 조건에서:\n\n$f(1) = g(1) + h(1)$, $f(-1) = g(-1) + h(-1) = g(1) - h(1)$\n\n따라서:\n$$f(1) + f(-1) = g(1) + h(1) + g(1) - h(1) = 2g(1)$$\n\n이는 항상 짝수입니다.\n\n$f(1) = 3$이고 함수의 연속성 조건에서 $f(-x) = -f(x)$ (홀함수)이면:\n\n$$f(-1) = -f(1) = -3$$\n\n**[정답 확인]**\n\n$f(1) = 3$, $f(-1) = -3$일 때 $f(1) + f(-1) = 0$으로 짝수이며, 함수 방정식 $f(x) = x^2 f\\left(\\frac{1}{x}\\right)$를 만족합니다.\n\n**[오답 분석]**\n\n본 문제는 서술형이므로 객관식 선지가 없습니다. 다만 $f(-1) = 3$이라고 답하면 틀리는데, 이는 함수 방정식의 대칭성을 간과한 것입니다.\n\n**[핵심 포인트]**\n\n- 함수 방정식에서 변수를 다르게 대입하여 관계식을 도출하는 것이 중요합니다.\n- $f(1) + f(-1)$이 항상 짝수라는 조건은 $f$가 홀함수임을 암시하며, 따라서 $f(-1) = -f(1) = -3$입니다.",
