    "answer": 3,
    "explanation": "**[핵심 개념]**\n함수가 특정 점에서 연속이기 위한 조건은 다음 세 가지를 모두 만족해야 합니다:\n1. $f(c)$가 정의되어 있다\n2. $\\lim_{x \\to c} f(x)$가 존재한다\n3. $\\lim_{x \\to c} f(x) = f(c)$\n\n$x = 2$에서 함수가 연속이려면, $x = 2$에서의 함수값이 $x \\to 2$일 때의 극한값과 같아야 합니다.\n\n**[풀이]**\n\n$x \\neq 2$일 때 $f(x) = \\dfrac{x^2 + x - 6}{x - 2}$의 극한을 구해봅시다.\n\n먼저 분자를 인수분해합니다:\n$$x^2 + x - 6 = (x + 3)(x - 2)$$\n\n따라서 $x \\neq 2$일 때:\n$$f(x) = \\dfrac{(x + 3)(x - 2)}{x - 2} = x + 3$$\n\n$x = 2$에 접근할 때의 극한값을 구하면:\n$$\\lim_{x \\to 2} f(x) = \\lim_{x \\to 2} (x + 3) = 2 + 3 = 5$$\n\n$f(x)$가 $x = 2$에서 연속이려면:\n$$f(2) = \\lim_{x \\to 2} f(x)$$\n\n따라서:\n$$a = 5$$\n\n**[정답 확인]**\n분자를 인수분해하여 약분한 후 극한을 구하면 $\\lim_{x \\to 2} f(x) = 5$이고, 연속 조건에 의해 $a = 5$입니다.\n\n**[오답 분석]**\n- ① 2: $x$값을 직접 대입한 오류\n- ② 3: 분자의 인수분해를 잘못하거나 극한값을 잘못 계산한 경우\n- ③ 4: 계산 과정에서 실수하여 1을 빠뜨린 경우\n- ⑤ 6: 극한값 계산 시 $2 + 3$ 대신 다른 값으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n$x = c$에서 분모가 0이 되는 유리함수의 연속성 문제는 **분자를 인수분해하여 약분한 후 극한값을 구하는 것**이 핵심입니다. 기계적으로 $x = 2$를 대입하지 않도록 주의하세요.",
