    "explanation": "**[핵심 개념]**\n\n중간값 정리(Intermediate Value Theorem)는 연속함수의 가장 기본적인 성질 중 하나입니다. 폐구간 $[a, b]$에서 연속인 함수 $f(x)$가 $f(a)$와 $f(b)$ 사이의 임의의 값 $k$에 대해, $f(c) = k$를 만족하는 $c \\in (a, b)$가 존재한다는 정리입니다. 특히 $f(a)$와 $f(b)$의 부호가 반대일 때, 구간 내에 근이 존재함을 보장합니다.\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- $f(x)$는 연속함수\n- $f(0) = -2 < 0$\n- $f(3) = 5 > 0$\n\n중간값 정리를 적용합니다.\n\n$f(x)$가 폐구간 $[0, 3]$에서 연속이고, $f(0) = -2$와 $f(3) = 5$입니다.\n\n우리가 찾는 값은 $k = 0$입니다. $-2 < 0 < 5$이므로, 0은 $f(0)$과 $f(3)$ 사이의 값입니다.\n\n중간값 정리에 의해, $f(c) = 0$을 만족하는 $c \\in (0, 3)$이 반드시 존재합니다.\n\n따라서 방정식 $f(x) = 0$은 구간 $(0, 3)$에서 적어도 하나의 실근을 가집니다.\n\n**[정답 확인]**\n\n함수값의 부호가 반대로 변할 때 연속함수가 그 사이에 0을 반드시 지나가는 성질을 보장하는 정리는 중간값 정리입니다.\n\n**[오답 분석]**\n\n① **롤의 정리**: $f(a) = f(b)$일 때 $f'(c) = 0$인 점이 존재함을 보장합니다. 여기서는 양 끝값이 같지 않으므로 적용 불가능합니다.\n\n② **평균값 정리**: $\\frac{f(b)-f(a)}{b-a} = f'(c)$인 점의 존재를 보장합니다. 함수값이 0이 되는 점의 존재가 아닌 미분계수에 관한 정리입니다.\n\n④ **최대·최소 정리**: 폐구간에서 연속인 함수는 최댓값과 최솟값을 가진다는 정리로, 구체적인 함수값이 존재함을 보장하지만 특정 값에서의 근의 존재를 직접 보장하지 않습니다.\n\n⑤ **라이프니츠 정리**: 미적분학의 기본정리와 관련된 정리로, 이 문제와 무관합니다.\n\n**[핵심 포인트]**\n\n함수값이 서로 다른 부호를 가질 때, 연속함수는 반드시 그 사이에 0을 지나갑니다. 이것이 중간값 정리의 핵심이며, 방정식의 근의 존재성을 판정하는 가장 직접적인 정리입니다.",
