    "answer": 1,
    "explanation": "**[핵심 개념]**\n함수가 특정 점에서 연속이려면 다음 세 조건을 모두 만족해야 합니다:\n1. $f(a)$가 정의되어 있다\n2. $\\lim_{x \\to a} f(x)$가 존재한다\n3. $\\lim_{x \\to a} f(x) = f(a)$\n\n특히 구간별로 정의된 함수에서 경계점 $x=a$에서의 연속성은 좌극한과 우극한이 같아야 하고, 함숫값과도 같아야 합니다.\n\n**[풀이]**\n\n$x=3$에서 함수 $f(x)$가 연속이 되려면:\n$$\\lim_{x \\to 3^-} f(x) = \\lim_{x \\to 3^+} f(x) = f(3)$$\n\n**1단계: 우극한과 함숫값 구하기**\n$x \\geq 3$일 때 $f(x) = 2x + 1$이므로:\n$$\\lim_{x \\to 3^+} f(x) = f(3) = 2(3) + 1 = 7$$\n\n**2단계: 좌극한 구하기**\n$x < 3$일 때 $f(x) = x^2 - 2x + k$이므로:\n$$\\lim_{x \\to 3^-} f(x) = 3^2 - 2(3) + k = 9 - 6 + k = 3 + k$$\n\n**3단계: 연속 조건 적용**\n연속성을 위해:\n$$\\lim_{x \\to 3^-} f(x) = \\lim_{x \\to 3^+} f(x)$$\n$$3 + k = 7$$\n$$k = 4$$\n\n**[정답 확인]**\n$k=4$일 때, $x=3$에서 좌극한 = $3+4=7$ = 우극한이므로 함수가 연속입니다.\n\n**[오답 분석]**\n- ① $k=2$: 좌극한 = $3+2=5$ ≠ $7$ (우극한)\n- ③ $k=6$: 좌극한 = $3+6=9$ ≠ $7$ (우극한)\n- ④ $k=7$: 좌극한 = $3+7=10$ ≠ $7$ (우극한)\n- ⑤ $k=10$: 좌극한 = $3+10=13$ ≠ $7$ (우극한)\n\n**[핵심 포인트]**\n구간별 함수의 경계점에서의 연속성은 **좌극한 = 우극한 = 함숫값**이어야 하며, 우극한/함숫값을 먼저 구한 후 좌극한을 그에 맞춰 설정하면 미지수를 쉽게 구할 수 있습니다.",
