    "problem": "함수 $f(x) = \\begin{cases} \\dfrac{x^3 - x}{x + 1} & (x \\neq -1) \\\\ a & (x = -1) \\end{cases}$이 $x = -1$에서 연속일 때, $a$의 값을 구하시오.",
