    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n함수가 특정 점에서 연속이기 위한 조건은 다음 세 가지를 모두 만족해야 합니다:\n1. $f(c)$가 정의되어 있다\n2. $\\lim_{x \\to c} f(x)$가 존재한다\n3. $\\lim_{x \\to c} f(x) = f(c)$\n\n이 문제에서는 $x = -1$에서 함수의 극한값이 $a$와 같아야 합니다. $x \\neq -1$일 때 함수가 복잡한 형태이므로, 먼저 분자를 인수분해하여 극한값을 구합니다.\n\n**[풀이]**\n\n$x = -1$에서 연속이려면:\n$$\\lim_{x \\to -1} f(x) = f(-1) = a$$\n\n먼저 $x \\neq -1$일 때 $f(x) = \\dfrac{x^3 - x}{x + 1}$의 극한을 구합니다.\n\n**Step 1: 분자를 인수분해**\n\n$$x^3 - x = x(x^2 - 1) = x(x+1)(x-1)$$\n\n**Step 2: 약분하기**\n\n$x \\neq -1$일 때:\n$$f(x) = \\dfrac{x(x+1)(x-1)}{x+1} = x(x-1)$$\n\n여기서 $x \\neq -1$이므로 $(x+1)$로 약분할 수 있습니다.\n\n**Step 3: 극한값 계산**\n\n$$\\lim_{x \\to -1} f(x) = \\lim_{x \\to -1} x(x-1)$$\n\n$x(x-1)$은 $x = -1$에서 연속함수이므로:\n$$\\lim_{x \\to -1} x(x-1) = (-1)((-1)-1) = (-1)(-2) = 2$$\n\n**Step 4: 연속 조건 적용**\n\n연속성 조건에 의해:\n$$a = 2$$\n\n**[정답 확인]**\n\n$a = 2$일 때, $\\lim_{x \\to -1} f(x) = 2 = f(-1)$이므로 $x = -1$에서 연속 조건을 만족합니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 일반적인 오답은:\n- $a = -2$: 극한값을 $(-1)(1)$로 잘못 계산한 경우\n- $a = 0$: 분자 $x^3 - x = 0$을 $x = -1$에 대입한 경우 (분자만 계산)\n- $a = 1$: 약분 후 $x - 1$만 계산한 경우\n\n**[핵심 포인트]**\n\n분자를 인수분해하여 $(x+1)$을 약분하면 극한값을 쉽게 구할 수 있습니다. 불연속점에서의 연속성 문제는 항상 **인수분해 → 약분 → 극한값 계산** 순서로 접근하세요.",
