    "problem": "다항함수 $f(x)$가 모든 실수에서 연속이고 $f(x) = (x-1)g(x) + 5$를 만족한다. $g(x)$도 연속이고 $g(1) = 3$일 때, $\\lim_{x \\to 1} \\dfrac{f(x) - 5}{x - 1}$의 값은?",
