    "explanation": "**[핵심 개념]**\n\n이 문제는 주어진 함수의 관계식을 이용하여 극한값을 구하는 문제입니다. 핵심은 다음과 같습니다:\n\n1. **미분의 정의**: $\\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a} = f'(a)$\n2. **연속함수의 성질**: $f(x)$가 연속이면 $\\lim_{x \\to a} f(x) = f(a)$\n3. **함수 관계식 활용**: 주어진 조건들을 정리하여 극한값을 계산\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n\n- $f(x) = (x-1)g(x) + 5$\n- $f(x)$와 $g(x)$는 모두 연속함수\n- $g(1) = 3$\n\n**Step 2: $f(1)$의 값 구하기**\n\n$f(x) = (x-1)g(x) + 5$에 $x = 1$을 대입하면:\n\n$$f(1) = (1-1)g(1) + 5 = 0 \\cdot 3 + 5 = 5$$\n\n**Step 3: 극한값 계산**\n\n구하는 극한식을 정리하면:\n\n$$\\lim_{x \\to 1} \\frac{f(x) - 5}{x - 1}$$\n\n$f(1) = 5$이므로 $f(x) - 5 = f(x) - f(1)$이고:\n\n$$\\lim_{x \\to 1} \\frac{f(x) - 5}{x - 1} = \\lim_{x \\to 1} \\frac{f(x) - f(1)}{x - 1} = f'(1)$$\n\n**Step 4: $f'(1)$ 구하기**\n\n$f(x) = (x-1)g(x) + 5$를 미분하면 (곱의 미분법):\n\n$$f'(x) = 1 \\cdot g(x) + (x-1) \\cdot g'(x) = g(x) + (x-1)g'(x)$$\n\n따라서:\n\n$$f'(1) = g(1) + (1-1)g'(1) = g(1) + 0 = g(1) = 3$$\n\n**Step 5: 극한값**\n\n$$\\lim_{x \\to 1} \\frac{f(x) - 5}{x - 1} = f'(1) = 3$$\n\n**[정답 확인]**\n\n$f(1) = 5$이고 미분의 정의에 따라 극한값은 $f'(1) = g(1) = 3$이므로 정답은 ②입니다.\n\n**[오답 분석]**\n\n- ① 1: $g(1)$의 값을 잘못 계산하거나 계수를 무시한 경우\n- ③ 5: $f(1) = 5$의 값을 극한값으로 착각한 경우\n- ④ 8: $g(1) + $ 다른 값을 더한 경우 (계산 실수)\n- ⑤ 15: $3 \\times 5$ 등 무관한 값들을 곱한 경우\n\n**[핵심 포인트]**\n\n극한 $\\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a}$의 형태는 **미분의 정의**이며, $f'(a)$와 같습니다. 주어진 함수 관계식에서 $f(1) = 5$임을 파악하고, 미분을 이용하여 $f'(1) = g(1)$로 직접 계산하는 것이 효율적입니다.",
