    "explanation": "**[핵심 개념]**\n함수의 함수값을 구하기 위해서는 주어진 함수 관계식에서 구하고자 하는 값에 해당하는 입력값을 찾아야 합니다. 주어진 조건식 $f(x^2 - 1) = 2x^2 + 3$에서 $f(3)$을 구하려면, $x^2 - 1 = 3$을 만족하는 $x$의 값을 찾아 우변을 계산하면 됩니다.\n\n**[풀이]**\n\n**Step 1: $f(3)$을 구하기 위한 $x$ 값 찾기**\n\n주어진 조건식은 $f(x^2 - 1) = 2x^2 + 3$입니다.\n\n$f(3)$을 구하려면 함수의 입력값이 3이 되어야 하므로:\n$$x^2 - 1 = 3$$\n\n**Step 2: 방정식 풀이**\n\n$$x^2 = 4$$\n$$x = \\pm 2$$\n\n**Step 3: 함수값 계산**\n\n$x = 2$ 또는 $x = -2$일 때, 우변의 값을 계산합니다.\n\n$x = 2$일 때:\n$$f(3) = 2(2)^2 + 3 = 2 \\cdot 4 + 3 = 8 + 3 = 11$$\n\n$x = -2$일 때:\n$$f(3) = 2(-2)^2 + 3 = 2 \\cdot 4 + 3 = 8 + 3 = 11$$\n\n**Step 4: 일관성 확인**\n\n$x = 2$일 때와 $x = -2$일 때 모두 같은 값 11을 얻습니다. 이는 $f(x^2-1) = 2x^2 + 3$에서 $x^2$만 포함되어 있고 $x$는 1차 항이 없기 때문입니다. 함수가 실수 전체에서 연속이므로 이 결과는 일관성이 있습니다.\n\n따라서 $f(3) = 11$\n\n**[정답 확인]**\n$x^2 - 1 = 3$에서 $x^2 = 4$이므로, $f(3) = 2 \\cdot 4 + 3 = 11$이 되어 정답이 ③입니다.\n\n**[오답 분석]**\n- ① 7: $f(3) = 2 \\cdot 2 + 3 = 7$로 계산하면 $x^2 = 2$인 경우인데, 이는 주어진 조건을 만족하지 않음\n- ② 9: $f(3) = 2 \\cdot 3 + 3 = 9$로 계산하면 $x^2 = 3$인 경우인데, $x^2 - 1 = 3$에서 나오지 않음\n- ④ 13: $f(3) = 2 \\cdot 5 + 3 = 13$으로 계산하면 $x^2 = 5$인 경우인데, $x^2 - 1 = 3$에서 나오지 않음\n- ⑤ 15: $f(3) = 2 \\cdot 6 + 3 = 15$로 계산하면 $x^2 = 6$인 경우인데, $x^2 - 1 = 3$에서 나오지 않음\n\n**[핵심 포인트]**\n합성함수 형태의 조건식에서 특정 함수값을 구할 때는 **입력값을 일치시키는 변수값을 먼저 찾는 것**이 핵심입니다. 이 문제에서는 $x^2 - 1 = 3$의 해를 구한 후, 그 값을 우변에 대입하여 답을 얻습니다.",
