    "answer": 8,
    "explanation": "**[핵심 개념]**\n\n도함수는 함수의 순간변화율을 나타내며, 다항함수의 도함수는 멱의 법칙(power rule)을 이용하여 구합니다.\n\n멱의 법칙: $\\frac{d}{dx}(x^n) = nx^{n-1}$\n\n상수의 도함수는 0입니다: $\\frac{d}{dx}(c) = 0$\n\n**[풀이]**\n\n**1단계: 주어진 함수의 도함수 구하기**\n\n$f(x) = 3x^2 - 4x + 1$\n\n각 항에 멱의 법칙을 적용합니다.\n\n$f'(x) = \\frac{d}{dx}(3x^2) - \\frac{d}{dx}(4x) + \\frac{d}{dx}(1)$\n\n$f'(x) = 3 \\cdot 2x^{2-1} - 4 \\cdot 1 \\cdot x^{1-1} + 0$\n\n$f'(x) = 6x - 4$\n\n**2단계: $f'(2)$ 계산하기**\n\n구한 도함수에 $x=2$를 대입합니다.\n\n$f'(2) = 6(2) - 4$\n\n$f'(2) = 12 - 4$\n\n$f'(2) = 8$\n\n**[정답 확인]**\n\n도함수 $f'(x) = 6x - 4$에 $x=2$를 대입하면 $f'(2) = 12 - 4 = 8$이므로 정답입니다.\n\n**[오답 분석]**\n\n선택지가 없으므로 계산 실수 가능성을 분석합니다.\n- 도함수를 $6x - 4$로 잘못 구한 경우 (예: 부호 실수)\n- $x=2$를 대입할 때 계산 실수 (예: $6 \\times 2 = 12$를 다르게 계산)\n- 원함수에 직접 $x=2$를 대입하는 오류 ($f(2) = 3(4) - 4(2) + 1 = 5$ ≠ $f'(2)$)\n\n**[핵심 포인트]**\n\n다항함수의 도함수는 **각 항에 멱의 법칙을 독립적으로 적용**하고, 도함수를 구한 후에 **구체적인 $x$값을 대입**하는 두 단계로 진행됩니다.",
