    "answer": 2,
    "explanation": "**[핵심 개념]**\n곱의 미분법을 이용하여 함수의 도함수를 구하는 문제입니다.\n- 곱의 미분법: $(u \\cdot v)' = u' \\cdot v + u \\cdot v'$\n- 다항함수의 미분: $(x^n)' = nx^{n-1}$, $(c)' = 0$ (상수)\n\n**[풀이]**\n\n**방법 1: 곱의 미분법 적용**\n\n$f(x) = (x^2 + 1)(x - 3)$에서 $u(x) = x^2 + 1$, $v(x) = x - 3$으로 놓으면:\n\n$$u'(x) = 2x$$\n$$v'(x) = 1$$\n\n곱의 미분법에 의해:\n$$f'(x) = u'(x) \\cdot v(x) + u(x) \\cdot v'(x)$$\n$$f'(x) = 2x(x-3) + (x^2+1) \\cdot 1$$\n$$f'(x) = 2x^2 - 6x + x^2 + 1$$\n$$f'(x) = 3x^2 - 6x + 1$$\n\n따라서:\n$$f'(1) = 3(1)^2 - 6(1) + 1 = 3 - 6 + 1 = -2$$\n\n**방법 2: 전개 후 미분 (검증)**\n\n먼저 $f(x)$를 전개하면:\n$$f(x) = (x^2 + 1)(x - 3) = x^3 - 3x^2 + x - 3$$\n\n미분하면:\n$$f'(x) = 3x^2 - 6x + 1$$\n\n$x = 1$을 대입:\n$$f'(1) = 3 - 6 + 1 = -2$$\n\n**[정답 확인]**\n$f'(1) = 3(1)^2 - 6(1) + 1 = -2$이므로 정답은 **③번**입니다.\n\n**[오답 분석]**\n- ① $-6$: $2x(x-3)$만 계산한 경우 ($2 \\times (-2) = -4$의 오류)\n- ② $-4$: $u'v$ 항만 계산했거나 부분적 계산 오류\n- ④ $0$: 부호 실수로 $-6 + 6 = 0$으로 잘못 계산\n- ⑤ $2$: 절댓값 실수 또는 계산 부호 오류\n\n**[핵심 포인트]**\n곱의 미분법에서는 **각 함수를 미분한 후 다른 함수를 곱하고, 두 항을 모두 더해야** 합니다. 한 항만 계산하거나 빠뜨리면 틀립니다.",
