    "problem": "$\\lim_{h \\to 0} \\dfrac{(2+h)^3 - 8}{h}$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 12,
    "explanation": "**[핵심 개념]**\n\n이 문제는 미분의 정의와 관련된 극한 문제입니다. 함수 $f(x) = x^3$에 대해 $x=2$에서의 미분계수를 구하는 것과 같습니다.\n\n$$f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}$$\n\n이 극한식에서 분자의 $0/0$ 꼴의 부정형을 해결하기 위해 인수분해나 다항식 전개를 사용합니다.\n\n**[풀이]**\n\n**Step 1: 분자 전개**\n\n$(2+h)^3$을 이항정리로 전개합니다.\n\n$$(2+h)^3 = 2^3 + 3 \\cdot 2^2 \\cdot h + 3 \\cdot 2 \\cdot h^2 + h^3 = 8 + 12h + 6h^2 + h^3$$\n\n**Step 2: 분자 정리**\n\n$$(2+h)^3 - 8 = 8 + 12h + 6h^2 + h^3 - 8 = 12h + 6h^2 + h^3$$\n\n**Step 3: 분수 정리**\n\n$$\\frac{(2+h)^3 - 8}{h} = \\frac{12h + 6h^2 + h^3}{h} = \\frac{h(12 + 6h + h^2)}{h}$$\n\n$h \\neq 0$일 때 $h$로 약분:\n\n$$= 12 + 6h + h^2$$\n\n**Step 4: 극한 계산**\n\n$$\\lim_{h \\to 0} (12 + 6h + h^2) = 12 + 6(0) + 0^2 = 12$$\n\n**[정답 확인]**\n\n분자를 인수분해하여 $h$로 약분 후 극한을 취하면 $0/0$ 꼴의 부정형이 해결되고, $h \\to 0$일 때 상수항인 12로 수렴합니다.\n\n**[오답 분석]**\n\n- **0**: 극한값을 구하지 않고 분자에 $h=0$을 대입하여 발생하는 오답\n- **6**: $6h$ 항만 고려하는 실수\n- **8**: $(2+h)^3 = 8$인 경우만 고려한 오답\n- **24**: 미분계수를 2배로 계산한 오답 (예: $2 \\times 12$)\n\n**[핵심 포인트]**\n\n- 극한에서 $0/0$ 꼴이 나타나면 인수분해나 전개를 통해 분자와 분모의 공통인수를 제거해야 합니다.\n- 이 문제는 $f(x) = x^3$일 때 $f'(2) = 3 \\cdot 2^2 = 12$와 같은 결과입니다.",
