    "answer": 2,
    "explanation": "**[핵심 개념]**\n이 문제는 미분의 정의를 묻는 문제입니다. 극한 $\\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a}$는 $x = a$에서의 미분계수 $f'(a)$를 의미합니다. 따라서 주어진 극한값은 $f'(1)$을 구하는 것과 같습니다.\n\n**[풀이]**\n\n**방법 1: 미분의 정의 이용**\n\n주어진 극한식은 미분의 정의에 따라:\n$$\\lim_{x \\to 1} \\frac{f(x) - f(1)}{x - 1} = f'(1)$$\n\n먼저 $f(x) = x^3 - 2x$를 미분합니다:\n$$f'(x) = 3x^2 - 2$$\n\n$x = 1$에서의 미분계수는:\n$$f'(1) = 3(1)^2 - 2 = 3 - 2 = 1$$\n\n**방법 2: 직접 계산으로 확인**\n\n$f(1) = 1^3 - 2(1) = 1 - 2 = -1$\n\n분자를 인수분해합니다:\n$$f(x) - f(1) = x^3 - 2x - (-1) = x^3 - 2x + 1$$\n\n$x = 1$을 대입하면 $1 - 2 + 1 = 0$이므로 $(x-1)$이 인수입니다.\n\n조립제법으로 인수분해하면:\n$$x^3 - 2x + 1 = (x-1)(x^2 + x - 1)$$\n\n따라서:\n$$\\lim_{x \\to 1} \\frac{f(x) - f(1)}{x - 1} = \\lim_{x \\to 1} \\frac{(x-1)(x^2 + x - 1)}{x - 1}$$\n\n$$= \\lim_{x \\to 1} (x^2 + x - 1) = 1^2 + 1 - 1 = 1$$\n\n**[정답 확인]**\n미분계수 공식을 적용하면 $f'(1) = 3(1)^2 - 2 = 1$이므로 정답은 **③번**입니다.\n\n**[오답 분석]**\n- ① $-1$: $f(1)$의 값을 잘못 선택한 경우\n- ② $0$: 극한을 잘못 계산하거나 $f'(x) = 0$인 다른 점과 혼동\n- ④ $2$: 미분할 때 상수항을 잘못 처리하거나 계산 오류\n- ⑤ $3$: 최고차 계수만 취한 경우\n\n**[핵심 포인트]**\n- 극한식 $\\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a}$는 항상 **미분계수 $f'(a)$**를 의미합니다.\n- 이 문제는 미분의 정의를 명확히 이해하고 있는지 확인하는 기본 문제입니다.",
