    "explanation": "**[핵심 개념]**\n\n이 문제는 미분의 정의와 극한을 이용하는 문제입니다. 주어진 극한식은 도함수의 정의와 유사한 형태이지만, 분자에 $f(1+3h) - f(1-h)$라는 비대칭적 형태가 있습니다. 이를 풀기 위해서는:\n- 함수값을 직접 계산하여 대입\n- 극한을 계산하는 기본 방법\n\n을 활용합니다.\n\n**[풀이]**\n\n**Step 1: $f(1+3h)$와 $f(1-h)$ 계산**\n\n$f(x) = x^2 + 3x$이므로:\n\n$$f(1+3h) = (1+3h)^2 + 3(1+3h)$$\n$$= 1 + 6h + 9h^2 + 3 + 9h$$\n$$= 4 + 15h + 9h^2$$\n\n$$f(1-h) = (1-h)^2 + 3(1-h)$$\n$$= 1 - 2h + h^2 + 3 - 3h$$\n$$= 4 - 5h + h^2$$\n\n**Step 2: 분자 계산**\n\n$$f(1+3h) - f(1-h) = (4 + 15h + 9h^2) - (4 - 5h + h^2)$$\n$$= 4 + 15h + 9h^2 - 4 + 5h - h^2$$\n$$= 20h + 8h^2$$\n\n**Step 3: 극한 계산**\n\n$$\\lim_{h \\to 0} \\frac{f(1+3h) - f(1-h)}{h} = \\lim_{h \\to 0} \\frac{20h + 8h^2}{h}$$\n\n$h \\neq 0$에서 $h$로 약분:\n\n$$= \\lim_{h \\to 0} (20 + 8h)$$\n\n$$= 20 + 8(0) = 20$$\n\n**[정답 확인]**\n\n분자를 정리한 후 $h$로 약분하면 $20 + 8h$가 되고, $h \\to 0$일 때의 극한값은 $20$이 됩니다.\n\n**[오답 분석]**\n\n선택지가 없으므로 일반적인 오류를 제시합니다:\n- **15** 또는 **25**: $f(1+3h)$와 $f(1-h)$를 계산할 때 전개 과정에서 실수\n- **8h**: 극한을 계산하지 않고 계수만 취함\n- **0**: $f(1+3h) - f(1-h)$를 잘못 계산하여 $h$의 배수가 없다고 판단\n\n**[핵심 포인트]**\n\n1. 극한 문제에서는 먼저 함수값을 정확하게 계산한 후, 분자를 인수분해하여 분모의 $h$와 약분하는 것이 중요합니다.\n2. 비대칭적 형태 $f(1+3h) - f(1-h)$도 각각 전개한 후 뺄셈을 정확하게 수행하면 어렵지 않게 풀 수 있습니다.",
