    "explanation": "**[핵심 개념]**\n함수가 $x = c$에서 극값을 가지려면 $f'(c) = 0$이어야 합니다. 또한 극값 조건을 만족하는 도함수 $f'(x)$를 구하고, 주어진 조건들을 연립하여 미지수를 구하는 문제입니다.\n\n**[풀이]**\n\n$f(x) = x^3 + ax^2 + bx + 1$이 주어졌으므로, 먼저 도함수를 구합니다.\n\n$$f'(x) = 3x^2 + 2ax + b$$\n\n**조건 1: $x = 1$에서 극값을 가짐**\n\n극값을 가지려면 $f'(1) = 0$이어야 합니다.\n\n$$f'(1) = 3(1)^2 + 2a(1) + b = 0$$\n$$3 + 2a + b = 0 \\cdots (1)$$\n\n**조건 2: $f'(-1) = 0$**\n\n$$f'(-1) = 3(-1)^2 + 2a(-1) + b = 0$$\n$$3 - 2a + b = 0 \\cdots (2)$$\n\n**연립방정식 풀이**\n\n식 (1)과 식 (2)를 연립하여 풀어봅시다.\n\n식 (1): $3 + 2a + b = 0$\n식 (2): $3 - 2a + b = 0$\n\n식 (1) - 식 (2):\n$$(3 + 2a + b) - (3 - 2a + b) = 0$$\n$$4a = 0$$\n$$a = 0$$\n\n$a = 0$을 식 (1)에 대입:\n$$3 + 2(0) + b = 0$$\n$$b = -3$$\n\n**따라서 $a + b$의 값**\n\n$$a + b = 0 + (-3) = -3$$\n\n**[정답 확인]**\n$a = 0, b = -3$을 원래 조건에 대입하면 $f'(x) = 3x^2 - 3 = 3(x^2 - 1)$이므로 $f'(1) = 0$, $f'(-1) = 0$을 모두 만족합니다.\n\n**[오답 분석]**\n선택지가 제시되지 않아 객관식 오답 분석은 불가능하지만, 일반적인 오류:\n- $f'(x) = 0$의 두 조건을 하나만 사용하는 경우\n- 도함수를 잘못 계산하는 경우\n- 연립방정식을 풀 때 계산 실수를 하는 경우\n\n**[핵심 포인트]**\n극값 조건에서 $f'(x) = 0$을 만족하는 점이 여러 개 주어질 때는, 각각의 조건을 식으로 세워 연립방정식을 풀어야 합니다. 이 문제에서는 두 근 $x = 1, -1$이 주어진 것으로 보아 $f'(x) = 3(x-1)(x+1)$ 형태임을 직관적으로 파악할 수도 있습니다.",
