    "answer": 2,
    "explanation": "**[핵심 개념]**\n곱의 미분법(Product Rule)은 두 함수의 곱으로 표현된 함수를 미분할 때 사용됩니다. $h(x) = u(x) \\cdot v(x)$일 때, $h'(x) = u'(x)v(x) + u(x)v'(x)$입니다. 이 문제에서는 $g(x) = x^2 \\cdot f(x)$이므로 곱의 미분법을 적용해야 합니다.\n\n**[풀이]**\n\n**Step 1: 곱의 미분법 적용**\n\n$g(x) = x^2 f(x)$에서 $u(x) = x^2$, $v(x) = f(x)$로 놓으면:\n\n$$g'(x) = (x^2)' \\cdot f(x) + x^2 \\cdot f'(x)$$\n\n$$g'(x) = 2x \\cdot f(x) + x^2 \\cdot f'(x)$$\n\n**Step 2: $x=1$을 대입**\n\n$$g'(1) = 2(1) \\cdot f(1) + 1^2 \\cdot f'(1)$$\n\n$$g'(1) = 2f(1) + f'(1)$$\n\n**Step 3: 주어진 값 대입**\n\n주어진 조건: $f(1) = 2$, $f'(1) = -3$\n\n$$g'(1) = 2(2) + (-3)$$\n\n$$g'(1) = 4 - 3 = 1$$\n\n**[정답 확인]**\n곱의 미분법을 올바르게 적용하여 $g'(1) = 2f(1) + f'(1) = 4 - 3 = 1$이므로 정답은 ③입니다.\n\n**[오답 분석]**\n- ① $-7$: $f'(1) - 2f(1) = -3 - 4 = -7$로 계산한 경우 (곱의 미분법을 뺄셈으로 잘못 적용)\n- ② $-3$: $f'(1)$의 값만 선택한 경우 (미분을 하지 않음)\n- ④ $4$: $2f(1)$의 값만 선택한 경우 (일부만 계산)\n- ⑤ $7$: $2f(1) - f'(1) = 4 - (-3) = 7$로 계산한 경우 (부호를 잘못 처리)\n\n**[핵심 포인트]**\n곱의 미분법에서는 각 함수를 순서대로 미분하되, **\"앞을 미분 × 뒤 + 앞 × 뒤를 미분\"** 구조를 정확히 적용하고, 주어진 조건의 부호(특히 $f'(1) = -3$)를 정확히 반영해야 합니다.",
