    "explanation": "**[핵심 개념]**\n합성함수의 미분법(연쇄법칙)을 이용하여 도함수를 구하는 문제입니다.\n- 연쇄법칙: $\\frac{d}{dx}[g(h(x))] = g'(h(x)) \\cdot h'(x)$\n- 거듭제곱의 미분: $\\frac{d}{dx}[u^n] = nu^{n-1} \\cdot \\frac{du}{dx}$\n\n**[풀이]**\n\n**Step 1: 함수 설정**\n$$f(x) = (x^2 - 1)^3$$\n\n**Step 2: 연쇄법칙을 이용하여 미분**\n$u = x^2 - 1$로 놓으면 $f(x) = u^3$\n\n$$f'(x) = \\frac{d}{dx}[u^3] = 3u^2 \\cdot \\frac{du}{dx}$$\n\n**Step 3: 각 항 계산**\n- $\\frac{du}{dx} = \\frac{d}{dx}(x^2 - 1) = 2x$\n- $u^2 = (x^2 - 1)^2$\n\n따라서:\n$$f'(x) = 3(x^2 - 1)^2 \\cdot 2x = 6x(x^2 - 1)^2$$\n\n**Step 4: $f'(0)$ 계산**\n$$f'(0) = 6 \\cdot 0 \\cdot (0^2 - 1)^2 = 0 \\cdot (1) = 0$$\n\n**[정답 확인]**\n$f'(0) = 6 \\cdot 0 \\cdot (0^2-1)^2 = 0$이므로 정답은 **0**입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오류는:\n- $f'(x) = 3(x^2-1)^2$로 계산하여 $f'(0) = 3$이라 하는 경우: 연쇄법칙에서 $(x^2-1)$의 미분값인 $2x$를 빠뜨린 실수\n- $f'(x) = 3x^2$로 계산하는 경우: 합성함수 미분을 제대로 적용하지 않은 실수\n\n**[핵심 포인트]**\n합성함수 미분 시 반드시 내부 함수의 도함수를 곱해야 합니다. $x=0$을 대입하기 전에 $2x$ 인수가 포함되어 있으므로 자동으로 0이 됩니다.",
