    "answer": 2,
    "explanation": "**[핵심 개념]**\n이 문제는 미분의 정의와 극한의 성질을 이용한 문제입니다.\n\n- 미분의 정의: $f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}$\n- 대칭 미분 공식: $\\lim_{h \\to 0} \\frac{f(a+h) - f(a-h)}{2h} = f'(a)$\n\n주어진 극한식은 $a=2$에서의 미분값을 나타내는 형태입니다.\n\n**[풀이]**\n\n**방법 1: 대칭 미분 공식 이용**\n\n주어진 극한식을 정리하면:\n$$\\lim_{h \\to 0} \\frac{f(2+h) - f(2-h)}{2h} = f'(2)$$\n\n이것은 미분의 정의에서 나오는 대칭형 극한으로, $f'(2)$와 같습니다.\n\n$f(x) = x^3 - 3x + 5$를 미분하면:\n$$f'(x) = 3x^2 - 3$$\n\n$x=2$일 때:\n$$f'(2) = 3(2)^2 - 3 = 3 \\cdot 4 - 3 = 12 - 3 = 9$$\n\n**방법 2: 직접 계산으로 검증**\n\n$f(2+h) = (2+h)^3 - 3(2+h) + 5$\n$= 8 + 12h + 6h^2 + h^3 - 6 - 3h + 5$\n$= 7 + 9h + 6h^2 + h^3$\n\n$f(2-h) = (2-h)^3 - 3(2-h) + 5$\n$= 8 - 12h + 6h^2 - h^3 - 6 + 3h + 5$\n$= 7 - 9h + 6h^2 - h^3$\n\n$f(2+h) - f(2-h) = (7 + 9h + 6h^2 + h^3) - (7 - 9h + 6h^2 - h^3)$\n$= 18h + 2h^3$\n\n따라서:\n$$\\lim_{h \\to 0} \\frac{18h + 2h^3}{2h} = \\lim_{h \\to 0} \\frac{2h(9 + h^2)}{2h} = \\lim_{h \\to 0} (9 + h^2) = 9$$\n\n**[정답 확인]**\n극한식은 $f'(2)$를 나타내고, $f'(2) = 3(2)^2 - 3 = 9$이므로 정답은 ③입니다.\n\n**[오답 분석]**\n- ① 3: $f'(x) = 3x^2 - 3$에서 상수항인 $-3$만 선택한 경우\n- ② 6: 계산 실수로 $3 \\times 2 = 6$을 답으로 선택한 경우\n- ④ 12: $3(2)^2 = 12$만 계산하고 $-3$을 빼먹은 경우\n- ⑤ 15: $12 + 3$으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n- 대칭 미분 공식 $\\lim_{h \\to 0} \\frac{f(a+h) - f(a-h)}{2h} = f'(a)$를 바로 적용하면 간단하게 풀 수 있습니다.\n- 미분을 먼저 계산한 후 $x=2$를 대입하는 방법이 가장 빠르고 실수가 적습니다.",
