    "explanation": "**[핵심 개념]**\n다항식의 미분은 각 항을 독립적으로 미분하여 더하는 것입니다. 기본 미분 공식은 $\\frac{d}{dx}(x^n) = nx^{n-1}$이고, 상수항의 미분은 0입니다.\n\n**[풀이]**\n주어진 함수 $f(x) = 5x^4 - 3x^2 + 7$을 각 항별로 미분합니다.\n\n**첫 번째 항:** $5x^4$를 미분하면\n$$\\frac{d}{dx}(5x^4) = 5 \\cdot 4x^{4-1} = 20x^3$$\n\n**두 번째 항:** $-3x^2$를 미분하면\n$$\\frac{d}{dx}(-3x^2) = -3 \\cdot 2x^{2-1} = -6x$$\n\n**세 번째 항:** $7$ (상수)을 미분하면\n$$\\frac{d}{dx}(7) = 0$$\n\n**따라서:**\n$$f'(x) = 20x^3 - 6x + 0 = 20x^3 - 6x$$\n\n**[정답 확인]**\n미분 공식을 정확히 적용하여 각 항을 계산하면 $f'(x) = 20x^3 - 6x$이므로 ①번이 정답입니다.\n\n**[오답 분석]**\n- **②번** ($20x^3 - 3x$): $-3x^2$를 미분할 때 계수인 2를 곱하지 않고 3만 사용한 오류\n- **③번** ($5x^3 - 6x$): $5x^4$를 미분할 때 계수 5를 지수 4와 곱하지 않은 오류\n- **④번** ($20x^4 - 6x^2$): 지수를 1씩 감소시키지 않고 그대로 유지한 오류\n- **⑤번** ($20x^3 - 6x + 7$): 상수항 7의 도함수가 0임을 간과한 오류\n\n**[핵심 포인트]**\n- 다항식 미분: 각 항에 $\\frac{d}{dx}(x^n) = nx^{n-1}$ 적용\n- 상수항은 항상 미분하면 0이 되므로 최종 답에서 제거됨",
