    "answer": 1,
    "explanation": "**[핵심 개념]**\n곱의 미분법(product rule)을 이용하여 두 함수의 곱으로 표현된 함수를 미분합니다.\n- 곱의 미분법: $(u \\cdot v)' = u'v + uv'$\n- 일차함수의 미분: $(ax + b)' = a$\n\n**[풀이]**\n$f(x) = (2x + 1)(3x - 2)$를 미분하기 위해 곱의 미분법을 적용합니다.\n\n$u = 2x + 1$, $v = 3x - 2$로 놓으면:\n- $u' = 2$\n- $v' = 3$\n\n곱의 미분법에 의해:\n$$f'(x) = u'v + uv'$$\n$$= 2(3x - 2) + (2x + 1) \\cdot 3$$\n$$= 6x - 4 + 6x + 3$$\n$$= 12x - 1$$\n\n**[정답 확인]**\n$f'(x) = 12x - 1$이므로 정답은 **②번**입니다.\n\n**[오답 분석]**\n- ① $6x + 1$: 전개 후 미분할 때 계산 실수\n- ③ $6x - 1$: 곱의 미분법에서 한 항만 미분한 경우\n- ④ $12x + 1$: 상수항의 부호를 잘못 계산\n- ⑤ $12x$: 상수항을 누락한 경우\n\n**[핵심 포인트]**\n곱의 미분법은 $(u \\cdot v)' = u'v + uv'$ 형태로, 두 항을 모두 계산해야 합니다. 또는 먼저 전개하여 $f(x) = 6x^2 - x - 2$로 만든 후 $f'(x) = 12x - 1$로 미분해도 같은 결과를 얻습니다.",
