    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n미분의 기본 공식을 이용하여 함수의 도함수를 구하는 문제입니다.\n- 거듭제곱의 미분: $(x^n)' = nx^{n-1}$\n- 역함수의 미분: $\\left(\\dfrac{1}{x}\\right)' = \\left(x^{-1}\\right)' = -x^{-2} = -\\dfrac{1}{x^2}$\n- 합의 미분: $(u + v)' = u' + v'$\n\n**[풀이]**\n\n$f(x) = x^5 + \\dfrac{1}{x}$의 도함수를 구합니다.\n\n각 항을 미분하면:\n- $(x^5)' = 5x^4$\n- $\\left(\\dfrac{1}{x}\\right)' = -\\dfrac{1}{x^2}$\n\n따라서:\n$$f'(x) = 5x^4 - \\dfrac{1}{x^2}$$\n\n$x = 1$을 대입하면:\n$$f'(1) = 5(1)^4 - \\dfrac{1}{(1)^2}$$\n\n$$f'(1) = 5 \\cdot 1 - 1$$\n\n$$f'(1) = 5 - 1 = 4$$\n\n**[정답 확인]**\n\n$f'(1) = 5 - 1 = 4$로 정답과 일치합니다.\n\n**[오답 분석]**\n\n객관식 선지가 제시되지 않았으나, 흔한 오류는 다음과 같습니다:\n- **5**: $-\\dfrac{1}{x^2}$ 항을 미분에서 빠뜨린 경우\n- **6**: $\\dfrac{1}{x}$를 $\\dfrac{1}{x^2}$로 잘못 미분한 경우\n- **3**: 계산 실수로 $5 - 2 = 3$으로 계산한 경우\n\n**[핵심 포인트]**\n\n$\\dfrac{1}{x} = x^{-1}$로 변형하여 거듭제곱 미분 공식을 적용하면 일관되게 풀 수 있습니다. 각 항을 정확히 미분한 후 주어진 점에서의 값을 계산하는 것이 중요합니다.",
