    "explanation": "**[핵심 개념]**\n다항함수의 미분: $f(x) = x^n$일 때, $f'(x) = nx^{n-1}$\n이차방정식의 근과 계수의 관계: $ax^2 + bx + c = 0$의 두 근을 $\\alpha, \\beta$라 하면, $\\alpha \\cdot \\beta = \\frac{c}{a}$\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$f(x) = x^3 - 6x + 2$를 미분하면:\n$$f'(x) = 3x^2 - 6$$\n\n**2단계: $f'(x) = 0$의 해 구하기**\n\n$$3x^2 - 6 = 0$$\n$$3x^2 = 6$$\n$$x^2 = 2$$\n$$x = \\pm\\sqrt{2}$$\n\n따라서 $f'(x) = 0$의 두 해는 $x = \\sqrt{2}$와 $x = -\\sqrt{2}$입니다.\n\n**3단계: 두 해의 곱 구하기**\n\n$$(\\sqrt{2}) \\times (-\\sqrt{2}) = -(\\sqrt{2})^2 = -2$$\n\n또는 근과 계수의 관계를 이용하면:\n$f'(x) = 3x^2 - 6 = 0$을 $3x^2 + 0x - 6 = 0$으로 보면,\n두 근의 곱 = $\\frac{-6}{3} = -2$\n\n**[정답 확인]**\n$f'(x) = 3x^2 - 6 = 0$에서 두 해 $\\sqrt{2}$와 $-\\sqrt{2}$의 곱은 $-2$입니다.\n\n**[오답 분석]**\n객관식이 아닌 단답형 문제이므로 해당 없음\n\n**[핵심 포인트]**\n- 다항함수의 도함수는 각 항을 미분하여 구한다. ($x^3$의 미분 = $3x^2$, 상수항의 미분 = $0$)\n- 이차방정식에서 근과 계수의 관계($\\alpha\\beta = \\frac{c}{a}$)를 알면 굳이 근을 구하지 않고도 두 근의 곱을 빠르게 구할 수 있다.",
