    "problem": "$f(x) = (x-1)(x-2)(x-3)$일 때, $f'(2)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": -1,
    "explanation": "**[핵심 개념]**\n곱의 미분법을 이용하여 도함수를 구하는 문제입니다. 세 개 이상의 함수의 곱을 미분할 때는 한 번에 하나씩 미분하는 방식을 사용합니다. $(uvw)' = u'vw + uv'w + uvw'$ 공식을 적용하거나, 전개한 후 항별 미분을 할 수 있습니다.\n\n**[풀이]**\n\n**방법 1: 곱의 미분법 이용**\n\n$f(x) = (x-1)(x-2)(x-3)$에 대해 곱의 미분법을 적용합니다.\n\n$(uvw)' = u'vw + uv'w + uvw'$를 사용하면:\n\n$$f'(x) = (x-2)(x-3) + (x-1)(x-3) + (x-1)(x-2)$$\n\n$x=2$를 대입합니다:\n\n$$f'(2) = (2-2)(2-3) + (2-1)(2-3) + (2-1)(2-2)$$\n\n$$f'(2) = (0)(-1) + (1)(-1) + (1)(0)$$\n\n$$f'(2) = 0 - 1 + 0 = -1$$\n\n**방법 2: 전개 후 미분**\n\n$f(x) = (x-1)(x-2)(x-3)$을 전개하면:\n\n$(x-1)(x-2) = x^2 - 3x + 2$\n\n$f(x) = (x^2-3x+2)(x-3) = x^3 - 3x^2 - 3x^2 + 9x + 2x - 6$\n\n$$f(x) = x^3 - 6x^2 + 11x - 6$$\n\n따라서:\n$$f'(x) = 3x^2 - 12x + 11$$\n\n$x=2$를 대입:\n$$f'(2) = 3(4) - 12(2) + 11 = 12 - 24 + 11 = -1$$\n\n**[정답 확인]**\n두 방법 모두 $f'(2) = -1$을 얻으므로, 정답은 **-1**입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 일반적인 오답으로는:\n- **0**: $x=2$를 원함수에 대입하는 실수 (미분이 아닌 함수값 계산)\n- **1**: 부호를 잘못 계산한 경우\n- **-2**: 곱의 미분법에서 항을 누락한 경우\n\n**[핵심 포인트]**\n$x=a$에서 함수가 0이 되는 경우, 곱의 미분법을 사용하면 많은 항이 자동으로 소거되어 계산이 간단해집니다. 이 문제에서는 $f(2)=0$이므로 $(2-2)$를 포함하는 항들이 0이 되어 중간 계산이 단순화됩니다.",
