    "problem": "$f(x) = \\dfrac{x^3 - 1}{x - 1}$ ($x \\neq 1$)일 때, $f'(2)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 5,
    "explanation": "**[핵심 개념]**\n이 문제는 먼저 주어진 함수를 간단히 정리한 후 미분하는 것이 핵심입니다. $x \\neq 1$일 때 $\\frac{x^3-1}{x-1}$은 인수분해를 이용해 간단히 할 수 있습니다. 3차 다항식의 미분과 함수값을 구하는 능력이 필요합니다.\n\n**[풀이]**\n\n**Step 1: 함수 정리하기**\n\n$x \\neq 1$일 때, 분자를 인수분해합니다.\n\n$$x^3 - 1 = (x-1)(x^2 + x + 1)$$\n\n따라서:\n$$f(x) = \\frac{(x-1)(x^2 + x + 1)}{x - 1} = x^2 + x + 1$$\n\n**Step 2: 도함수 구하기**\n\n정리된 함수를 미분합니다.\n\n$$f'(x) = \\frac{d}{dx}(x^2 + x + 1) = 2x + 1$$\n\n**Step 3: $f'(2)$ 계산하기**\n\n$$f'(2) = 2(2) + 1 = 4 + 1 = 5$$\n\n**[정답 확인]**\n\n$f(x) = x^2 + x + 1$에서 $f'(x) = 2x + 1$이고, $x=2$를 대입하면 $f'(2) = 5$가 되어 정답이 맞습니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오답은:\n- **3**: 미분 후 계산 실수 ($2 \\times 2 = 4$를 $3$으로 잘못 계산)\n- **4**: $x=2$를 대입할 때 상수항 1을 빠뜨린 경우\n- **6**: 미분하지 않고 $f(2) = 4 + 2 + 1 = 7$을 구한 후 계산 오류\n\n**[핵심 포인트]**\n\n1. **복잡한 분수 함수는 먼저 간단히 정리하기**: 인수분해를 통해 $\\frac{x^3-1}{x-1} = x^2 + x + 1$로 단순화하는 것이 미분을 쉽게 만듭니다.\n\n2. **정의역 확인**: $x \\neq 1$이지만, 정리된 함수는 모든 $x$에서 미분 가능하므로 $f'(2)$를 자유롭게 구할 수 있습니다.",
