    "explanation": "**[핵심 개념]**\n- 곱의 미분법: $(u \\cdot v)' = u'v + uv'$\n- 다항식의 미분: $(x^n)' = nx^{n-1}$\n- 함수를 먼저 전개한 후 미분하는 방법과 곱의 미분법을 직접 적용하는 방법 모두 가능\n\n**[풀이]**\n\n**방법 1: 함수를 전개한 후 미분**\n\n$f(x) = (x^2 + x)(x^2 - x)$를 전개합니다.\n\n$$f(x) = x^2(x^2 - x) + x(x^2 - x)$$\n$$= x^4 - x^3 + x^3 - x^2$$\n$$= x^4 - x^2$$\n\n이제 미분합니다:\n$$f'(x) = 4x^3 - 2x$$\n\n$x = 1$을 대입:\n$$f'(1) = 4(1)^3 - 2(1) = 4 - 2 = 2$$\n\n**방법 2: 곱의 미분법 직접 적용**\n\n$u = x^2 + x$, $v = x^2 - x$로 놓으면:\n- $u' = 2x + 1$\n- $v' = 2x - 1$\n\n곱의 미분법을 적용:\n$$f'(x) = u'v + uv'$$\n$$= (2x + 1)(x^2 - x) + (x^2 + x)(2x - 1)$$\n\n$x = 1$을 대입:\n$$f'(1) = (2 \\cdot 1 + 1)(1 - 1) + (1 + 1)(2 \\cdot 1 - 1)$$\n$$= (3)(0) + (2)(1)$$\n$$= 0 + 2 = 2$$\n\n**[정답 확인]**\n$f'(x) = 4x^3 - 2x$에서 $f'(1) = 4 - 2 = 2$이므로 정답은 **2**입니다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 계산 실수:\n- $f'(1) = 4$: 미분 후 $-2x$ 항을 빠뜨린 경우\n- $f'(1) = 0$: 곱의 미분법에서 첫 번째 항만 계산한 경우\n- $f'(1) = 6$: 전개 과정에서 계산 실수\n\n**[핵심 포인트]**\n- 곱 형태의 함수는 **전개 후 미분하는 것이 간단**할 수 있습니다.\n- 곱의 미분법을 사용할 때는 **양쪽 항 모두 계산**해야 합니다.",
