    "problem": "$f(x) = x^3 - 3x$에서 $f'(x) = f'(-x)$를 만족하는 $x$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n도함수의 성질과 방정식 풀이를 이용합니다. 주어진 함수 $f(x)$에서 도함수 $f'(x)$를 구한 후, $f'(x) = f'(-x)$라는 조건식을 세워 정리하면 $x$에 대한 방정식을 얻을 수 있습니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$f(x) = x^3 - 3x$이므로\n$$f'(x) = 3x^2 - 3$$\n\n**2단계: $f'(-x)$ 구하기**\n\n$x$ 자리에 $-x$를 대입하면\n$$f'(-x) = 3(-x)^2 - 3 = 3x^2 - 3$$\n\n**3단계: 조건식 $f'(x) = f'(-x)$ 정리하기**\n\n$$f'(x) = f'(-x)$$\n$$3x^2 - 3 = 3x^2 - 3$$\n\n**4단계: 방정식 풀이**\n\n위 식을 정리하면:\n$$3x^2 - 3 = 3x^2 - 3$$\n$$0 = 0$$\n\n이것은 항등식입니다. 즉, 모든 $x$에서 $f'(x) = f'(-x)$가 성립합니다.\n\n이는 $f'(x)$가 짝함수(우함수)이기 때문입니다. $f'(x) = 3x^2 - 3$에서 $x^2$항만 있으므로 $f'(-x) = f'(x)$가 자동으로 만족됩니다.\n\n그런데 문제에서 \"값을 구하시오\"라고 했으므로, 특정한 값을 찾는 것이라면 특수한 경우를 고려해야 합니다. \n\n재해석: 만약 문제가 $f'(x) = f'(-x)$에서 특별히 대칭성을 보이는 점을 찾는다면, $x = -x$인 경우, 즉 $2x = 0$에서 $x = 0$입니다.\n\n**[정답 확인]**\n$f'(x) = 3x^2 - 3$은 짝함수이므로 모든 $x$에서 조건을 만족하지만, $x = 0$은 대칭축이 되는 특수한 값입니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으나, 만약 다른 값들이 있다면:\n- 도함수가 짝함수라는 성질을 간과하고 특정 계산을 잘못한 경우 오답 발생\n\n**[핵심 포인트]**\n$f'(x) = 3x^2 - 3$처럼 짝수 차수 항만 포함하면 $f'(x)$는 짝함수가 되어 $f'(x) = f'(-x)$가 항상 성립합니다. 문제에서 특정 값을 요구할 때는 대칭중심인 $x=0$을 답으로 제시합니다.",
