    "problem": "$f(x) = x(x-1)(x+2)$에서 $f'(x)$의 $x^2$의 계수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 3,
    "explanation": "**[핵심 개념]**\n다항함수의 미분은 각 항을 개별적으로 미분하는 성질을 이용합니다. 특히 곱셈 형태의 함수를 미분할 때는 먼저 전개한 후 미분하거나, 곱의 미분법을 적용할 수 있습니다. 이 문제에서는 $f(x)$를 다항식으로 전개한 후 미분하여 $f'(x)$의 계수를 구합니다.\n\n**[풀이]**\n\n$f(x) = x(x-1)(x+2)$를 전개합니다.\n\n먼저 $(x-1)(x+2)$를 계산합니다:\n$$f(x) = x[(x-1)(x+2)] = x[x^2 + 2x - x - 2] = x[x^2 + x - 2]$$\n\n$x$를 분배합니다:\n$$f(x) = x^3 + x^2 - 2x$$\n\n$f(x)$를 미분합니다:\n$$f'(x) = \\frac{d}{dx}(x^3 + x^2 - 2x)$$\n\n각 항을 미분하면:\n$$f'(x) = 3x^2 + 2x - 2$$\n\n$f'(x) = 3x^2 + 2x - 2$에서 $x^2$의 계수는 $\\boxed{3}$입니다.\n\n**[정답 확인]**\n$f(x) = x^3 + x^2 - 2x$를 미분하면 $f'(x) = 3x^2 + 2x - 2$이므로, $x^2$의 계수는 3입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으므로 일반적인 오류를 언급하면:\n- **1**: $f'(x)$의 $x$ 계수와 혼동\n- **2**: 원래 함수 $f(x)$의 $x^2$ 계수와 혼동\n- **-2**: 원래 함수 $f(x)$의 상수항과 혼동\n\n**[핵심 포인트]**\n곱셈 형태의 다항함수는 먼저 완전히 전개한 후 각 항을 미분하는 것이 계산 실수를 줄이는 가장 안전한 방법입니다. $x^n$을 미분하면 $nx^{n-1}$이므로, $x^3$을 미분하면 $3x^2$가 됩니다.",
