    "answer": 1,
    "explanation": "**[핵심 개념]**\n합성함수의 미분법(Chain Rule)을 이용하여 문제를 풀어야 합니다.\n- 합성함수 $g(x) = \\{f(x)\\}^2$의 도함수는 $g'(x) = 2f(x) \\cdot f'(x)$입니다.\n- 이는 미분의 연쇄법칙: $\\frac{d}{dx}[f(x)]^2 = 2f(x) \\cdot \\frac{d}{dx}f(x)$를 적용한 것입니다.\n\n**[풀이]**\n\n**1단계: $f(x)$와 $f'(x)$ 구하기**\n\n주어진 조건에서 $f(x) = x^2 + 1$이므로:\n$$f'(x) = 2x$$\n\n**2단계: 합성함수의 미분법 적용**\n\n$g(x) = \\{f(x)\\}^2$를 미분하면, 연쇄법칙에 의해:\n$$g'(x) = 2f(x) \\cdot f'(x)$$\n\n**3단계: $x=1$에서의 함숫값과 도함숫값 구하기**\n\n$x=1$일 때:\n- $f(1) = 1^2 + 1 = 2$\n- $f'(1) = 2(1) = 2$\n\n**4단계: $g'(1)$ 계산**\n\n$$g'(1) = 2f(1) \\cdot f'(1) = 2 \\times 2 \\times 2 = 8$$\n\n**[정답 확인]**\n$g'(1) = 2 \\times 2 \\times 2 = 8$이므로 정답은 ②번입니다.\n\n**[오답 분석]**\n- ① 4: $f(1) \\times f'(1) = 2 \\times 2$를 계산하고 2를 곱하지 않은 경우\n- ③ 12: $2f(1) + f'(1) = 2(2) + 2$와 같이 곱셈 대신 덧셈을 한 경우\n- ④ 16: $\\{f(1)\\}^2 \\times 2 = 4 \\times 4$로 잘못 계산한 경우\n- ⑤ 20: 계산 과정에서 실수를 한 경우\n\n**[핵심 포인트]**\n합성함수 미분의 핵심은 \"바깥함수 미분 × 안함수 미분\"입니다. $g(x) = \\{f(x)\\}^2$에서 바깥함수는 제곱이고 안함수는 $f(x)$이므로, $g'(x) = 2f(x) \\cdot f'(x)$를 정확히 적용하는 것이 중요합니다.",
