    "problem": "$f(x) = (x^3 + 2)^2$을 전개한 후 미분하여 $f'(-1)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n이 문제를 풀기 위해 필요한 개념은 다항식의 전개와 미분이다.\n- 다항식을 전개할 때는 이항정리나 직접 곱셈을 이용한다.\n- 전개한 다항식을 미분할 때는 항별로 미분하는 멱의 법칙을 적용한다: $\\frac{d}{dx}x^n = nx^{n-1}$\n\n**[풀이]**\n\n**1단계: $f(x) = (x^3 + 2)^2$ 전개하기**\n\n$(x^3 + 2)^2$을 완전제곱식으로 전개한다:\n$$f(x) = (x^3 + 2)^2 = (x^3)^2 + 2 \\cdot x^3 \\cdot 2 + 2^2$$\n\n$$f(x) = x^6 + 4x^3 + 4$$\n\n**2단계: $f'(x)$ 구하기**\n\n전개한 식을 항별로 미분한다:\n$$f'(x) = \\frac{d}{dx}(x^6 + 4x^3 + 4)$$\n\n$$f'(x) = 6x^5 + 12x^2 + 0$$\n\n$$f'(x) = 6x^5 + 12x^2$$\n\n**3단계: $f'(-1)$ 계산하기**\n\n$x = -1$을 $f'(x)$에 대입한다:\n$$f'(-1) = 6(-1)^5 + 12(-1)^2$$\n\n$$f'(-1) = 6 \\cdot (-1) + 12 \\cdot 1$$\n\n$$f'(-1) = -6 + 12 = 6$$\n\n**[정답 확인]**\n전개한 후 미분하여 $x=-1$을 대입했을 때 $-6 + 12 = 6$이 나오므로 정답이 맞다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오류는:\n- $f'(-1) = -6$: $(-1)^2 = 1$임을 간과하고 음수로 계산하는 경우\n- $f'(-1) = 12$: 첫 번째 항을 계산하지 않는 경우\n- $f'(-1) = 18$: 부호를 잘못 계산하는 경우\n\n**[핵심 포인트]**\n- $(x^3 + 2)^2 = x^6 + 4x^3 + 4$로 전개하는 것이 핵심이다.\n- 음수의 거듭제곱에서 짝수 제곱은 양수, 홀수 제곱은 음수임을 정확히 계산해야 한다: $(-1)^5 = -1$, $(-1)^2 = 1$",
