    "problem": "최고차항의 계수가 1인 삼차함수 $f(x)$에 대해 $f'(x) = 3(x-1)(x-3)$일 때, $f(0) - f(4)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": -4,
    "explanation": "**[핵심 개념]**\n- 도함수와 원함수의 관계: $f'(x)$가 주어졌을 때, $f(x) = \\int f'(x)dx + C$\n- 최고차항의 계수가 1인 삼차함수: $f(x) = x^3 + ax^2 + bx + c$ 형태\n- 도함수의 최고차항의 계수: 삼차함수를 미분하면 이차함수가 되고, 최고차항의 계수는 $3 \\times 1 = 3$\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- $f'(x) = 3(x-1)(x-3)$\n- $f(x)$의 최고차항의 계수가 1\n\n**Step 2: $f'(x)$ 전개**\n$$f'(x) = 3(x-1)(x-3) = 3(x^2 - 4x + 3) = 3x^2 - 12x + 9$$\n\n**Step 3: $f(x)$ 구하기**\n$$f(x) = \\int (3x^2 - 12x + 9)dx = x^3 - 6x^2 + 9x + C$$\n\n최고차항의 계수가 1이므로 위 형태가 맞습니다. (상수 $C$는 $f(0) - f(4)$를 계산할 때 소거됨)\n\n**Step 4: $f(0)$ 계산**\n$$f(0) = 0^3 - 6(0)^2 + 9(0) + C = C$$\n\n**Step 5: $f(4)$ 계산**\n$$f(4) = 4^3 - 6(4)^2 + 9(4) + C$$\n$$= 64 - 6(16) + 36 + C$$\n$$= 64 - 96 + 36 + C$$\n$$= 4 + C$$\n\n**Step 6: $f(0) - f(4)$ 계산**\n$$f(0) - f(4) = C - (4 + C) = C - 4 - C = -4$$\n\n**[정답 확인]**\n$f(0) - f(4) = -4$이므로 정답은 **-4**입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 상수항을 실수로 계산하거나 부호를 잘못하면:\n- 4: $f(4) - f(0)$을 구한 경우\n- 0: 상수항이 소거된다는 것을 인식하지 못한 경우\n- 다른 값: 도함수를 잘못 전개하거나 적분을 잘못한 경우\n\n**[핵심 포인트]**\n1. 두 함수값의 차를 구할 때는 상수항이 자동으로 소거되므로, 굳이 초기조건을 구하지 않아도 계산 가능합니다.\n2. $f'(x)$의 형태에서 최고차항의 계수를 통해 원함수의 최고차항 계수를 확인하는 것이 중요합니다.",
