    "problem": "곡선 $y = x^2 - 3x + 1$ 위의 점 $(2, -1)$에서의 접선의 기울기를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n곡선 위의 특정 점에서의 접선의 기울기는 그 점에서의 미분값(도함수)과 같습니다. 함수 $y = f(x)$가 주어질 때, 점 $(a, f(a))$에서의 접선의 기울기는 $f'(a)$입니다.\n\n**[풀이]**\n주어진 곡선: $y = x^2 - 3x + 1$\n\n**1단계: 점 (2, -1)이 곡선 위의 점인지 확인**\n$$y = 2^2 - 3(2) + 1 = 4 - 6 + 1 = -1$$ ✓\n\n**2단계: 도함수 구하기**\n$$\\frac{dy}{dx} = \\frac{d}{dx}(x^2 - 3x + 1) = 2x - 3$$\n\n**3단계: $x = 2$에서의 도함수값 계산**\n$$\\frac{dy}{dx}\\bigg|_{x=2} = 2(2) - 3 = 4 - 3 = 1$$\n\n따라서 점 $(2, -1)$에서의 접선의 기울기는 **1**입니다.\n\n**[정답 확인]**\n도함수 $f'(x) = 2x - 3$에 $x = 2$를 대입하면 $f'(2) = 1$이므로, 접선의 기울기는 1입니다.\n\n**[오답 분석]**\n- **0**: $2x - 3 = 0$에서 $x = \\frac{3}{2}$일 때의 기울기를 잘못 구한 경우\n- **-1**: 점의 $y$좌표 값을 기울기로 착각한 경우\n- **2**: $x = 2$일 때 도함수를 $2x$만 계산하거나 계산 실수를 한 경우\n- **4**: $2x$ 항만 계산한 경우\n\n**[핵심 포인트]**\n- 곡선 위의 점에서의 접선의 기울기 = 그 점에서의 도함수값\n- 주어진 점이 곡선 위에 있는지 먼저 확인한 후 미분하여 도함수를 구하고, 주어진 $x$값을 대입하면 됩니다.",
