    "answer": 2,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 방정식을 구하기 위해서는:\n1. 주어진 점에서의 접선의 기울기를 구해야 합니다.\n2. 곡선 $y = f(x)$에서 점 $(a, f(a))$에서의 접선의 기울기는 $f'(a)$입니다.\n3. 접선의 방정식: $y - y_1 = m(x - x_1)$ (점-기울기 형태)\n\n**[풀이]**\n\n**Step 1: 미분하여 도함수 구하기**\n\n곡선 $y = x^3$을 $x$에 대해 미분합니다.\n\n$$\\frac{dy}{dx} = 3x^2$$\n\n**Step 2: 주어진 점에서의 접선의 기울기 구하기**\n\n점 $(1, 1)$에서의 접선의 기울기는 $x = 1$일 때의 도함수값입니다.\n\n$$m = 3(1)^2 = 3 \\times 1 = 3$$\n\n**Step 3: 접선의 방정식 구하기**\n\n점 $(1, 1)$을 지나고 기울기가 $m = 3$인 직선의 방정식입니다.\n\n$$y - 1 = 3(x - 1)$$\n\n$$y - 1 = 3x - 3$$\n\n$$y = 3x - 2$$\n\n**[정답 확인]**\n접선의 기울기 $m = 3$과 점 $(1, 1)$을 이용하여 $y = 3x - 2$를 얻으므로, 검증: $x = 1$일 때 $y = 3(1) - 2 = 1$ ✓\n\n**[오답 분석]**\n- **①** $y = x$: 기울기가 1이므로 틀림. 도함수값을 구하지 않음\n- **②** $y = 2x - 1$: 기울기가 2이므로 틀림. 미분을 잘못 계산함\n- **④** $y = 3x + 1$: 기울기는 맞으나 점 $(1, 1)$을 지나지 않음 ($1 ≠ 3 + 1$)\n- **⑤** $y = x + 1$: 기울기가 1이므로 틀림. 점도 지나지 않음\n\n**[핵심 포인트]**\n곡선의 접선 문제는 **도함수 = 접선의 기울기**임을 기억하고, 구한 기울기로 점-기울기 형태의 직선 방정식을 세우면 됩니다. 특히 주어진 점이 곡선 위의 점임을 확인하는 것이 중요합니다.",
