    "explanation": "**[핵심 개념]**\n\n곡선 위의 한 점에서의 접선을 구하는 문제입니다. 필요한 개념은:\n- 도함수를 이용한 접선의 기울기: 곡선 $y = f(x)$ 위의 점 $(a, f(a))$에서의 접선의 기울기는 $f'(a)$\n- 접선의 방정식: 점 $(x_0, y_0)$을 지나고 기울기가 $m$인 직선의 방정식은 $y - y_0 = m(x - x_0)$\n- $y$절편: 직선이 $y$축과 만나는 점의 $y$좌표 (즉, $x = 0$일 때의 $y$값)\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n곡선 $y = x^2 + 2x$를 미분합니다.\n$$y' = 2x + 2$$\n\n**Step 2: 접점의 $x$좌표 구하기**\n\n기울기가 6인 접선이므로, 접점에서:\n$$y' = 6$$\n$$2x + 2 = 6$$\n$$2x = 4$$\n$$x = 2$$\n\n**Step 3: 접점의 좌표 구하기**\n\n$x = 2$일 때 곡선 위의 점의 $y$좌표:\n$$y = 2^2 + 2(2) = 4 + 4 = 8$$\n\n따라서 접점은 $(2, 8)$입니다.\n\n**Step 4: 접선의 방정식 구하기**\n\n점 $(2, 8)$을 지나고 기울기가 6인 직선의 방정식:\n$$y - 8 = 6(x - 2)$$\n$$y - 8 = 6x - 12$$\n$$y = 6x - 4$$\n\n**Step 5: $y$절편 구하기**\n\n$y$절편은 $x = 0$일 때의 $y$값:\n$$y = 6(0) - 4 = -4$$\n\n**[정답 확인]**\n\n접선의 방정식 $y = 6x - 4$가 점 $(2, 8)$을 지나고(대입하면 $8 = 12 - 4$ ✓), 기울기가 6이며($y' = 2x + 2 = 6$ at $x=2$ ✓), 원래 곡선에 접하므로 $y$절편은 **-4**입니다.\n\n**[오답 분석]**\n\n객관식 선택지가 제시되지 않았으나, 흔한 오답들:\n- **0**: $y$절편을 구하지 않고 접점의 $x$좌표를 답한 경우\n- **8**: $y$절편을 구하지 않고 접점의 $y$좌표를 답한 경우\n- **-12**: 접선의 방정식에서 상수항을 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n1. 기울기가 주어졌을 때는 **도함수를 그 기울기값과 같다고 놓아** 접점의 $x$좌표를 먼저 구합니다.\n2. $y$절편은 항상 **$x = 0$을 대입**하여 구합니다.",
