    "explanation": "**[핵심 개념]**\n\n곡선 위의 한 점에서의 접선 방정식을 구하려면 다음 두 가지가 필요합니다.\n1. 접점의 좌표: $(x_0, y_0)$ (문제에서 주어짐)\n2. 접선의 기울기: $f'(x_0)$ (도함수를 이용하여 구함)\n\n접선의 방정식은 점-기울기 형태: $y - y_0 = f'(x_0)(x - x_0)$\n\n**[풀이]**\n\n**Step 1: 주어진 점이 곡선 위의 점임을 확인**\n\n$y = x^3 - 3x + 2$에 $x = 1$을 대입하면:\n$$y = 1^3 - 3(1) + 2 = 1 - 3 + 2 = 0$$\n\n따라서 점 $(1, 0)$은 곡선 위의 점입니다. ✓\n\n**Step 2: 도함수 구하기**\n\n$$f(x) = x^3 - 3x + 2$$\n$$f'(x) = 3x^2 - 3$$\n\n**Step 3: $x = 1$에서의 기울기 구하기**\n\n$$f'(1) = 3(1)^2 - 3 = 3 - 3 = 0$$\n\n접선의 기울기는 $0$입니다.\n\n**Step 4: 접선의 방정식 구하기**\n\n점 $(1, 0)$을 지나고 기울기가 $0$인 직선의 방정식:\n$$y - 0 = 0(x - 1)$$\n$$y = 0$$\n\n**[정답 확인]**\n\n기울기가 $0$인 직선은 $x$축에 평행한 수평선이므로 $y = 0$이 맞습니다.\n\n**[오답 분석]**\n\n- **② $y = -x + 1$**: 기울기가 $-1$인 경우로, $f'(1) = -1$이라는 잘못된 계산에서 나온 답\n- **③ $y = x - 1$**: 기울기가 $1$인 경우로, $f'(1) = 1$이라는 잘못된 계산에서 나온 답\n- **④ $y = 3x - 3$**: 기울기가 $3$인 경우로, $f'(1) = 3$이라는 잘못된 계산에서 나온 답\n- **⑤ $y = -3x + 3$**: 기울기가 $-3$인 경우로, $f'(1) = -3$이라는 잘못된 계산에서 나온 답\n\n**[핵심 포인트]**\n\n접선의 기울기는 **그 점에서의 도함수 값**입니다. 특히 도함수 값이 $0$이면 접선은 수평선($y = \\text{상수}$)이 됩니다. 도함수 계산을 정확히 하는 것이 가장 중요합니다.",
