    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n곡선 위의 한 점에서의 접선을 구하는 문제입니다. 필요한 개념은:\n- 접선의 기울기: 그 점에서의 미분값\n- 직선의 방정식: 기울기와 한 점을 알면 직선 방정식을 세울 수 있음\n- 직선이 특정 점을 지난다는 조건을 이용하여 미지수를 구하는 방정식\n\n**[풀이]**\n\n**1단계: 점 $(a, a^2)$에서의 접선의 기울기 구하기**\n\n곡선 $y = x^2$을 미분하면:\n$$\\frac{dy}{dx} = 2x$$\n\n따라서 점 $(a, a^2)$에서의 접선의 기울기는 $2a$입니다.\n\n**2단계: 접선의 방정식 세우기**\n\n점-기울기 형태의 직선 방정식을 사용하면:\n$$y - a^2 = 2a(x - a)$$\n\n정리하면:\n$$y = 2ax - 2a^2 + a^2$$\n$$y = 2ax - a^2$$\n\n**3단계: 접선이 점 $(0, -1)$을 지나는 조건 적용**\n\n점 $(0, -1)$을 위 접선의 방정식에 대입:\n$$-1 = 2a(0) - a^2$$\n$$-1 = -a^2$$\n$$a^2 = 1$$\n\n**4단계: 검증**\n\n- $a^2 = 1$이면 $a = 1$ 또는 $a = -1$\n- $a = 1$일 때: 점 $(1, 1)$에서의 접선은 $y = 2x - 1$ → $(0, -1)$을 지남 ✓\n- $a = -1$일 때: 점 $(-1, 1)$에서의 접선은 $y = -2x - 1$ → $(0, -1)$을 지남 ✓\n\n**[정답 확인]**\n\n$a = \\pm 1$일 때 모두 조건을 만족하므로 $a^2 = 1$입니다.\n\n**[오답 분석]**\n\n객관식이 아니라 서술형이므로 다른 오답이 없습니다. 다만 계산 실수로 $a^2 = 2$ 또는 다른 값을 얻을 수 있는데, 이는 접선의 기울기를 잘못 구하거나 점 $(0, -1)$을 대입할 때 실수한 경우입니다.\n\n**[핵심 포인트]**\n\n- 곡선 위의 점에서 접선의 기울기는 그 점에서의 미분값\n- 접선이 주어진 점을 지난다는 조건으로 방정식을 세워 미지수를 구하는 것이 핵심",
