    "explanation": "**[핵심 개념]**\n곡선 위의 점에서 그은 접선의 기울기는 그 점에서의 도함수 값과 같습니다. \n- 곡선 $y = f(x)$에서 점 $(a, f(a))$에서의 접선의 기울기는 $f'(a)$\n- 접선의 방정식: $y - f(a) = f'(a)(x - a)$\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n곡선 $y = x^3 - 2x$를 미분하면:\n$$y' = 3x^2 - 2$$\n\n**Step 2: 기울기가 1인 조건 설정**\n\n기울기가 1인 접선이 존재하려면, 접점에서의 미분값이 1이어야 합니다:\n$$3x^2 - 2 = 1$$\n\n**Step 3: 방정식 풀이**\n\n$$3x^2 - 2 = 1$$\n$$3x^2 = 3$$\n$$x^2 = 1$$\n$$x = 1 \\text{ 또는 } x = -1$$\n\n**Step 4: 접점 확인**\n\n$x = 1$일 때: $y = 1^3 - 2(1) = 1 - 2 = -1$ → 접점: $(1, -1)$\n\n$x = -1$일 때: $y = (-1)^3 - 2(-1) = -1 + 2 = 1$ → 접점: $(-1, 1)$\n\n**Step 5: 접선의 방정식 확인**\n\n$x = 1$에서: $y - (-1) = 1(x - 1)$ → $y = x - 2$\n\n$x = -1$에서: $y - 1 = 1(x - (-1))$ → $y = x + 2$\n\n두 접선은 서로 다르므로 기울기가 1인 접선은 **2개**입니다.\n\n**[정답 확인]**\n$3x^2 - 2 = 1$이라는 이차방정식이 서로 다른 두 실근을 가지므로, 기울기가 1인 접선은 정확히 2개입니다.\n\n**[오답 분석]**\n- ① 0개: 이차방정식의 판별식이 양수(∆ = 12 > 0)이므로 실근이 존재합니다.\n- ② 1개: 중근을 가져야 하는데, 이 방정식은 서로 다른 두 실근을 갖습니다.\n- ④ 3개: 이차방정식은 최대 2개의 실근만 가집니다.\n- ⑤ 무한개: 기울기 조건을 만족하는 점은 유한개입니다.\n\n**[핵심 포인트]**\n접선의 기울기 문제는 도함수를 특정 값과 같다고 놓고 푸는 것이 핵심입니다. 특히 접점의 개수는 도함수 방정식의 근의 개수와 같다는 점을 기억하세요.",
