    "answer": -1,
    "explanation": "**[핵심 개념]**\n곡선의 접선이 $x$축에 평행하다는 것은 접선의 기울기가 0이라는 의미입니다. 곡선 $y = f(x)$에서 접선의 기울기는 도함수 $f'(x)$로 구하므로, $f'(x) = 0$인 점에서의 접선을 찾으면 됩니다. 접선의 방정식은 $y = mx + b$ 형태이고, $y$절편은 $b$값입니다.\n\n**[풀이]**\n\n주어진 곡선: $y = x^2 - 4x + 3$\n\n**Step 1: 도함수 구하기**\n$$y' = 2x - 4$$\n\n**Step 2: $x$축에 평행한 접선의 조건**\n$x$축에 평행한 직선의 기울기는 0이므로:\n$$y' = 0$$\n$$2x - 4 = 0$$\n$$x = 2$$\n\n**Step 3: 접점의 $y$좌표 구하기**\n$x = 2$일 때, 곡선 위의 점의 $y$좌표는:\n$$y = (2)^2 - 4(2) + 3 = 4 - 8 + 3 = -1$$\n\n접점은 $(2, -1)$입니다.\n\n**Step 4: 접선의 방정식**\n기울기가 0이고 점 $(2, -1)$을 지나는 직선:\n$$y - (-1) = 0(x - 2)$$\n$$y = -1$$\n\n따라서 $y$절편은 $\\boxed{-1}$입니다.\n\n**[정답 확인]**\n$y = -1$은 수평선이므로 $x$축에 평행하며, 곡선 $y = x^2 - 4x + 3$의 최솟값이 되는 점에서의 접선입니다. $y$절편은 $-1$입니다.\n\n**[오답 분석]**\n객관식 선지가 제시되지 않았으나, 흔한 오답으로는:\n- **3**: 곡선의 $y$절편과 혼동 ($x=0$일 때 $y=3$)\n- **-4**: 기울기와 혼동\n- **2**: 접점의 $x$좌표와 혼동\n\n**[핵심 포인트]**\n- $x$축에 평행한 접선 ⟹ 기울기가 0 ⟹ $f'(x) = 0$으로부터 접점을 찾기\n- 이차함수의 경우 $x$축에 평행한 접선은 꼭짓점에서의 접선이며, 유일합니다.",
