    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n곡선 위의 한 점에서의 접선을 구하기 위해서는 도함수를 이용하여 그 점에서의 기울기를 구해야 합니다. 도함수 $f'(x)$는 $x$에서의 접선의 기울기를 나타냅니다. 접선의 방정식은 점-기울기 형태 $y - y_0 = m(x - x_0)$으로 나타낼 수 있습니다. 접선과 곡선의 교점을 구할 때는 접선의 방정식과 곡선의 방정식을 연립하여 풉니다.\n\n**[풀이]**\n\n**Step 1: 점 $(-1, 0)$에서의 접선의 기울기 구하기**\n\n곡선 $y = x^3 - x$에서 도함수는:\n$$f'(x) = 3x^2 - 1$$\n\n$x = -1$에서의 기울기는:\n$$f'(-1) = 3(-1)^2 - 1 = 3 - 1 = 2$$\n\n**Step 2: 점 $(-1, 0)$에서의 접선의 방정식 구하기**\n\n점-기울기 형태를 사용하면:\n$$y - 0 = 2(x - (-1))$$\n$$y = 2(x + 1)$$\n$$y = 2x + 2$$\n\n**Step 3: 접선과 곡선의 교점 구하기**\n\n접선의 방정식 $y = 2x + 2$를 곡선 $y = x^3 - x$에 대입:\n$$x^3 - x = 2x + 2$$\n$$x^3 - x - 2x - 2 = 0$$\n$$x^3 - 3x - 2 = 0$$\n\n**Step 4: 3차 방정식 풀이**\n\n$x = -1$이 해임을 알고 있으므로 (접점이기 때문), $(x + 1)$로 인수분해:\n$$x^3 - 3x - 2 = (x + 1)(x^2 - x - 2)$$\n\n$x^2 - x - 2$를 인수분해하면:\n$$x^2 - x - 2 = (x - 2)(x + 1)$$\n\n따라서:\n$$x^3 - 3x - 2 = (x + 1)^2(x - 2) = 0$$\n\n이 방정식의 해는 $x = -1$ (중근), $x = 2$\n\n$x = -1$은 접점이므로, 곡선과 접선의 다른 교점의 $x$ 좌표는 $x = 2$입니다.\n\n**[정답 확인]**\n\n3차 방정식을 $(x+1)^2(x-2)=0$으로 인수분해하여 $x=-1$ (중근, 접점)과 $x=2$ (단순교점)을 얻었으므로, 다른 교점의 $x$ 좌표는 **2**입니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오답은:\n- $x = -1$: 접점이므로 \"다른 교점\"의 조건을 만족하지 않음\n- $x = 0$: 인수분해 과정에서 계산 실수로 나올 수 있음\n- $x = 1$: 3차 방정식의 해가 아님\n\n**[핵심 포인트]**\n\n접선과 곡선의 교점 중 접점은 중근으로 나타나고, \"다른 교점\"을 구할 때는 접점을 제외한 단순근을 찾아야 합니다. 3차 방정식이 인수분해될 때 접점이 중근으로 포함되는 점을 항상 확인하세요.",
