    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선의 기울기는 그 점에서의 미분값입니다. 곡선 외부의 한 점에서 곡선에 그은 접선을 구할 때는, 접점을 미지수로 설정하여 접선의 방정식을 세우고, 주어진 점을 지나는 조건을 이용합니다.\n\n**[풀이]**\n\n곡선 $y = x^2$의 접점을 $(a, a^2)$이라 하겠습니다.\n\n**Step 1: 접선의 기울기 구하기**\n$y = x^2$를 미분하면 $y' = 2x$이므로, 접점 $(a, a^2)$에서의 접선의 기울기는 $2a$입니다.\n\n**Step 2: 접선의 방정식 세우기**\n접점 $(a, a^2)$을 지나고 기울기가 $2a$인 접선의 방정식은:\n$$y - a^2 = 2a(x - a)$$\n$$y = 2ax - 2a^2 + a^2$$\n$$y = 2ax - a^2$$\n\n**Step 3: 점 $(0, -4)$를 지나는 조건 적용**\n접선이 점 $(0, -4)$를 지나므로:\n$$-4 = 2a(0) - a^2$$\n$$-4 = -a^2$$\n$$a^2 = 4$$\n$$a = 2 \\text{ 또는 } a = -2$$\n\n**Step 4: 각 접점에서의 기울기 구하기**\n- $a = 2$일 때: 기울기 $= 2a = 2(2) = 4$\n- $a = -2$일 때: 기울기 $= 2a = 2(-2) = -4$\n\n**Step 5: 기울기의 합**\n$$4 + (-4) = 0$$\n\n**[정답 확인]**\n점 $(0, -4)$에서 곡선 $y = x^2$에 그을 수 있는 접선은 2개이며, 두 접선의 기울기는 $4$와 $-4$이므로 합은 $0$입니다.\n\n**[오답 분석]**\n- **②, ③**: 한 개의 접선의 기울기만 구하거나 절댓값으로 더한 경우\n- **④, ⑤**: 부호를 잘못 계산하거나 하나의 기울기만 답으로 제시한 경우\n\n**[핵심 포인트]**\n외부 점에서 곡선에 그은 접선은 여러 개일 수 있으므로, 접점을 미지수로 설정하여 모든 경우를 찾아야 합니다. 기울기의 합을 구할 때는 구한 모든 기울기를 더해야 합니다.",
