    "explanation": "**[핵심 개념]**\n곡선과 직선이 접한다는 것은 두 그래프가 한 점에서만 만나고 그 점에서 같은 기울기를 가진다는 의미입니다. 곡선 $y = f(x)$와 직선 $y = mx + n$이 접할 때:\n1) 교점에서 $f(x) = mx + n$\n2) 접점에서 $f'(x) = m$ (같은 기울기)\n\n이 두 조건을 동시에 만족하는 $x$ 값이 존재해야 합니다.\n\n**[풀이]**\n\n**Step 1: 접촉 조건 설정**\n\n곡선 $y = x^3 - 3x^2$와 직선 $y = -3x + a$가 접하는 점을 $x = t$라고 하면:\n- 함수값이 같음: $t^3 - 3t^2 = -3t + a$ ... (1)\n- 미분값이 같음: $f'(t) = -3$ ... (2)\n\n**Step 2: 미분하여 접점의 x좌표 구하기**\n\n$f(x) = x^3 - 3x^2$이므로\n$$f'(x) = 3x^2 - 6x$$\n\n조건 (2)에서:\n$$3t^2 - 6t = -3$$\n$$3t^2 - 6t + 3 = 0$$\n$$t^2 - 2t + 1 = 0$$\n$$(t-1)^2 = 0$$\n$$t = 1$$\n\n**Step 3: 접점의 y좌표와 a 값 구하기**\n\n$t = 1$을 곡선의 방정식에 대입:\n$$y = 1^3 - 3(1)^2 = 1 - 3 = -2$$\n\n접점은 $(1, -2)$입니다.\n\n이 점이 직선 $y = -3x + a$ 위에 있으므로:\n$$-2 = -3(1) + a$$\n$$-2 = -3 + a$$\n$$a = 1$$\n\n**Step 4: 검증**\n\n$a = 1$일 때, 교점을 구하면:\n$$x^3 - 3x^2 = -3x + 1$$\n$$x^3 - 3x^2 + 3x - 1 = 0$$\n$$(x-1)^3 = 0$$\n\n$x = 1$ (중근)에서만 만나므로 접한다는 조건을 만족합니다. ✓\n\n**[정답 확인]**\n$a = 1$은 양수이며, $(1, -2)$에서 곡선과 직선이 중근을 가지므로 접하는 조건을 완벽하게 만족합니다.\n\n**[오답 분석]**\n객관식이 아니라 단답형이므로 해당 없습니다.\n\n**[핵심 포인트]**\n곡선과 직선이 접할 조건은 **기울기가 같다**는 조건($f'(x) = m$)부터 시작하는 것이 효율적입니다. 이를 통해 접점의 x좌표를 먼저 구한 후 나머지 미지수를 결정할 수 있습니다.",
