    "problem": "곡선 $y = x^3 - 6x^2 + 12x - 8$ 위의 변곡점에서의 접선의 방정식의 $y$절편을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n변곡점은 곡선의 볼록성이 바뀌는 점으로, 이계 도함수가 0이 되고 부호가 바뀌는 점입니다. 변곡점에서의 접선의 방정식은 일반적인 접선 공식을 이용하여 $y - y_1 = f'(x_1)(x - x_1)$ 형태로 구합니다.\n\n**[풀이]**\n\n**1단계: 주어진 함수를 정리**\n\n$y = x^3 - 6x^2 + 12x - 8$\n\n먼저 이 함수를 인수분해하면:\n$$y = (x-2)^3$$\n\n**2단계: 일계 도함수 구하기**\n\n$$f'(x) = 3x^2 - 12x + 12 = 3(x^2 - 4x + 4) = 3(x-2)^2$$\n\n**3단계: 이계 도함수 구하기**\n\n$$f''(x) = 6x - 12 = 6(x-2)$$\n\n**4단계: 변곡점 찾기**\n\n변곡점에서 $f''(x) = 0$:\n$$6(x-2) = 0$$\n$$x = 2$$\n\n$x < 2$일 때 $f''(x) < 0$ (위로 볼록)\n$x > 2$일 때 $f''(x) > 0$ (아래로 볼록)\n\n따라서 이계 도함수의 부호가 바뀌므로 $x = 2$에서 변곡점입니다.\n\n**5단계: 변곡점의 좌표 구하기**\n\n$x = 2$일 때:\n$$y = (2-2)^3 = 0$$\n\n변곡점: $(2, 0)$\n\n**6단계: 변곡점에서의 접선의 기울기**\n\n$$f'(2) = 3(2-2)^2 = 0$$\n\n**7단계: 접선의 방정식**\n\n점 $(2, 0)$에서 기울기가 $0$인 접선:\n$$y - 0 = 0 \\cdot (x - 2)$$\n$$y = 0$$\n\n**8단계: y절편 구하기**\n\n접선 $y = 0$의 $y$절편은 $x = 0$일 때의 $y$ 값:\n$$y\\text{절편} = 0$$\n\n**[정답 확인]**\n\n변곡점이 $(2, 0)$이고 그 점에서의 접선의 기울기가 0이므로 접선은 $x$축 자체인 $y = 0$이며, 따라서 $y$절편은 0입니다.\n\n**[오답 분석]**\n\n객관식이 없으므로 해당 사항 없음.\n\n**[핵심 포인트]**\n\n1. 변곡점은 $f''(x) = 0$이고 그 점에서 이계 도함수의 부호가 바뀌어야 합니다.\n2. 함수를 인수분해하면 $(x-2)^3$ 형태로 계산이 간단해지며, 변곡점에서 기울기가 0이 되는 특수한 경우를 주의해서 봐야 합니다.",
