    "problem": "두 곡선 $y = x^2$과 $y = -x^2 + 4x - 2$의 공통접선의 기울기를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n공통접선이란 두 곡선 모두에 접하는 직선을 의미합니다. 곡선 $y = f(x)$ 위의 점 $(a, f(a))$에서의 접선의 방정식은 $y - f(a) = f'(a)(x - a)$입니다. 공통접선을 구하려면 각 곡선에서의 접점을 설정하고, 같은 직선이 되는 조건을 찾아야 합니다.\n\n**[풀이]**\n\n**1단계: 각 곡선에서의 접선 설정**\n\n첫 번째 곡선 $y = x^2$에서 접점을 $(a, a^2)$이라 하면:\n- 도함수: $f'(x) = 2x$이므로 $f'(a) = 2a$\n- 접선의 방정식: $y - a^2 = 2a(x - a)$\n- 정리하면: $y = 2ax - a^2$ ... ①\n\n두 번째 곡선 $y = -x^2 + 4x - 2$에서 접점을 $(b, -b^2 + 4b - 2)$라 하면:\n- 도함수: $g'(x) = -2x + 4$이므로 $g'(b) = -2b + 4$\n- 접선의 방정식: $y - (-b^2 + 4b - 2) = (-2b + 4)(x - b)$\n- 정리하면: $y = (-2b + 4)x - b^2 + 2b - 2$ ... ②\n\n**2단계: 공통접선 조건**\n\n①과 ②가 같은 직선이므로 기울기와 상수항이 같아야 합니다.\n\n기울기가 같으므로:\n$$2a = -2b + 4$$\n$$a = -b + 2$$ ... (i)\n\n상수항이 같으므로:\n$$-a^2 = -b^2 + 2b - 2$$\n$$a^2 = b^2 - 2b + 2$$ ... (ii)\n\n**3단계: 연립방정식 풀이**\n\n(i)에서 $a = 2 - b$를 (ii)에 대입:\n$$(2-b)^2 = b^2 - 2b + 2$$\n$$4 - 4b + b^2 = b^2 - 2b + 2$$\n$$4 - 4b = -2b + 2$$\n$$2 = 2b$$\n$$b = 1$$\n\n(i)에서: $a = 2 - 1 = 1$\n\n**4단계: 공통접선의 기울기**\n\n$$\\text{기울기} = 2a = 2(1) = 2$$\n\n**[정답 확인]**\n$a = 1, b = 1$일 때 첫 번째 곡선의 접선은 $y = 2x - 1$이고, 두 번째 곡선의 접선도 $y = 2x - 1$으로 동일하므로 공통접선의 기울기는 **2**입니다.\n\n**[오답 분석]**\n객관식이 아닌 단답형이므로 해당 사항 없음.\n\n**[핵심 포인트]**\n공통접선 문제는 각 곡선에서의 접선을 일반적으로 설정한 후, 기울기와 절편이 같다는 두 조건을 동시에 만족하는 접점을 찾는 것이 핵심입니다.",
