    "answer": 1,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서 그은 법선(normal line)은 그 점에서의 접선에 수직인 직선입니다.\n- 접선의 기울기를 $m$이라 하면, 법선의 기울기는 $-\\frac{1}{m}$입니다.\n- 곡선 $y = f(x)$에서 $x = a$일 때의 접선의 기울기는 $f'(a)$입니다.\n- $x$절편은 직선이 $x$축과 만나는 점의 $x$좌표(즉, $y = 0$일 때의 $x$값)입니다.\n\n**[풀이]**\n\n**1단계: 주어진 점에서의 접선의 기울기 구하기**\n\n곡선: $y = x^2 - 2x + 3$\n\n도함수를 구하면:\n$$\\frac{dy}{dx} = 2x - 2$$\n\n점 $(0, 3)$에서의 접선의 기울기:\n$$m = 2(0) - 2 = -2$$\n\n**2단계: 법선의 기울기 구하기**\n\n접선의 기울기가 $-2$이므로, 법선의 기울기는:\n$$m_{\\text{법선}} = -\\frac{1}{-2} = \\frac{1}{2}$$\n\n**3단계: 법선의 방정식 구하기**\n\n점 $(0, 3)$을 지나고 기울기가 $\\frac{1}{2}$인 직선의 방정식:\n$$y - 3 = \\frac{1}{2}(x - 0)$$\n$$y = \\frac{1}{2}x + 3$$\n\n**4단계: $x$절편 구하기**\n\n$x$절편은 $y = 0$일 때의 $x$값:\n$$0 = \\frac{1}{2}x + 3$$\n$$-\\frac{1}{2}x = 3$$\n$$x = -6$$\n\n**[정답 확인]**\n법선의 방정식 $y = \\frac{1}{2}x + 3$에서 $y = 0$을 대입하면 $x = -6$이므로 정답입니다.\n\n**[오답 분석]**\n- ① $-3$: 접선의 기울기 $-2$를 그대로 사용한 경우\n- ③ $3$: $y$절편을 답으로 착각한 경우\n- ④ $6$: 부호를 반대로 계산한 경우\n- ⑤ $\\frac{3}{2}$: 계산 실수로 $\\frac{1}{2}x = 3$에서 $x = \\frac{3}{2}$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n- **법선의 기울기 = $-\\frac{1}{\\text{접선의 기울기}}$** (수직 관계)\n- 법선의 방정식을 구한 후 $y = 0$을 대입하여 $x$절편을 구합니다.",
