    "explanation": "**[핵심 개념]**\n함수가 증가하는 구간을 찾기 위해서는 도함수를 이용합니다. 함수 $f(x)$에서:\n- $f'(x) > 0$인 구간에서 $f(x)$는 증가\n- $f'(x) < 0$인 구간에서 $f(x)$는 감소\n- $f'(x) = 0$인 점은 극값의 후보\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 3x + 2$$\n$$f'(x) = 3x^2 - 3$$\n\n**2단계: $f'(x) = 0$인 점 찾기**\n$$f'(x) = 3x^2 - 3 = 0$$\n$$3(x^2 - 1) = 0$$\n$$x^2 = 1$$\n$$x = -1 \\text{ 또는 } x = 1$$\n\n**3단계: 도함수의 부호 판정**\n\n$f'(x) = 3(x-1)(x+1)$로 인수분해되므로, 각 구간에서 부호를 확인합니다.\n\n- $x < -1$일 때: $(x-1) < 0$, $(x+1) < 0$ → $f'(x) = 3 \\times (-) \\times (-) > 0$ ✓ **증가**\n- $-1 < x < 1$일 때: $(x-1) < 0$, $(x+1) > 0$ → $f'(x) = 3 \\times (-) \\times (+) < 0$ ✗ 감소\n- $x > 1$일 때: $(x-1) > 0$, $(x+1) > 0$ → $f'(x) = 3 \\times (+) \\times (+) > 0$ ✓ **증가**\n\n**4단계: 결론**\n따라서 함수 $f(x)$는 $x < -1$ 또는 $x > 1$에서 증가합니다.\n\n**[정답 확인]**\n$f'(x) > 0$인 구간이 $x < -1$ 또는 $x > 1$이므로 정답은 ①번입니다.\n\n**[오답 분석]**\n- ② $-1 < x < 1$: 이 구간에서는 $f'(x) < 0$이므로 감소 구간입니다.\n- ③ $x > 0$: $0 < x < 1$에서는 감소하므로 틀렸습니다.\n- ④ $x < 0$: $-1 < x < 0$에서는 감소하므로 틀렸습니다.\n- ⑤ 모든 실수: $-1 < x < 1$에서는 감소하므로 틀렸습니다.\n\n**[핵심 포인트]**\n1. 함수의 증감을 판정할 때는 반드시 도함수의 부호를 확인해야 합니다.\n2. 도함수를 인수분해하면 각 구간에서의 부호 변화를 빠르게 파악할 수 있습니다.",
