    "explanation": "**[핵심 개념]**\n함수의 증감을 판정하기 위해서는 도함수를 이용합니다.\n- $f'(x) > 0$인 구간에서 함수는 증가\n- $f'(x) < 0$인 구간에서 함수는 감소\n- $f'(x) = 0$인 점은 극값을 가지는 지점\n\n따라서 함수가 감소하는 구간을 찾으려면 $f'(x) < 0$인 구간을 구해야 합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = -x^3 + 12x - 5$$\n\n양변을 $x$에 대해 미분하면:\n\n$$f'(x) = -3x^2 + 12$$\n\n**2단계: 극값 찾기 ($f'(x) = 0$인 점)**\n\n$$f'(x) = 0$$\n$$-3x^2 + 12 = 0$$\n$$-3x^2 = -12$$\n$$x^2 = 4$$\n$$x = \\pm 2$$\n\n**3단계: 도함수의 부호 판정**\n\n$f'(x) = -3x^2 + 12 = -3(x^2 - 4) = -3(x-2)(x+2)$\n\n각 구간에서 $f'(x)$의 부호를 확인:\n\n- $x < -2$일 때: $(x-2) < 0$, $(x+2) < 0$이므로 $-3(x-2)(x+2) = -3 \\times (-) \\times (-) < 0$ ✓\n- $-2 < x < 2$일 때: $(x-2) < 0$, $(x+2) > 0$이므로 $-3(x-2)(x+2) = -3 \\times (-) \\times (+) > 0$ \n- $x > 2$일 때: $(x-2) > 0$, $(x+2) > 0$이므로 $-3(x-2)(x+2) = -3 \\times (+) \\times (+) < 0$ ✓\n\n**4단계: 감소 구간 결정**\n\n$f'(x) < 0$인 구간은 $x < -2$ 또는 $x > 2$\n\n**[정답 확인]**\n도함수 $f'(x) = -3(x-2)(x+2)$는 $x < -2$ 또는 $x > 2$에서 음수이므로, 함수는 이 구간에서 감소합니다.\n\n**[오답 분석]**\n- ① $-2 < x < 2$: 이 구간에서 $f'(x) > 0$이므로 함수는 **증가**합니다.\n- ③ $x > 0$: $0 < x < 2$에서는 증가하므로 틀렸습니다.\n- ④ $x < 0$: $-2 < x < 0$에서는 증가하므로 틀렸습니다.\n- ⑤ 모든 실수: $-2 < x < 2$에서 증가하므로 틀렸습니다.\n\n**[핵심 포인트]**\n3차 함수에서 증감을 판정할 때는 반드시 도함수를 구한 후, 도함수의 부호를 구간별로 나누어 확인하세요. 극값의 위치($x = \\pm 2$)를 경계로 구간을 나눕니다.",
