    "problem": "함수 $f(x) = x^3 + 3x^2 + 3x + 1$이 항상 증가하는 함수인지 판별하시오. 증가하면 1, 아니면 0으로 답하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n함수가 항상 증가하는지 판별하려면 도함수를 이용합니다. 함수 $f(x)$가 정의역 전체에서 증가함수이려면 $f'(x) \\geq 0$이어야 하고, 특히 $f'(x) = 0$인 점이 고립된 점이어야 합니다. 또한 주어진 함수 $f(x) = x^3 + 3x^2 + 3x + 1$은 $(x+1)^3$ 형태로 인수분해될 수 있다는 점을 인식하면 더 쉽게 풀 수 있습니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f'(x) = 3x^2 + 6x + 3$$\n\n**2단계: 도함수를 인수분해**\n$$f'(x) = 3(x^2 + 2x + 1) = 3(x+1)^2$$\n\n**3단계: 도함수의 부호 판정**\n$(x+1)^2 \\geq 0$이므로 $f'(x) = 3(x+1)^2 \\geq 0$ (모든 실수 $x$에 대해)\n\n$f'(x) = 0$이 되는 점은 $x = -1$이 유일한 점입니다.\n\n**4단계: 증가함수 판정**\n- $x < -1$일 때: $f'(x) > 0$ (증가)\n- $x = -1$일 때: $f'(x) = 0$ (변곡점)\n- $x > -1$일 때: $f'(x) > 0$ (증가)\n\n$f'(x) = 0$인 점이 고립된 점이므로, 함수는 전체 구간에서 **증가함수**입니다.\n\n**참고: 함수의 인수분해**\n$$f(x) = x^3 + 3x^2 + 3x + 1 = (x+1)^3$$\n이는 이항정리의 $(x+1)^3 = x^3 + 3x^2 + 3x + 1$에 의해 확인됩니다.\n\n**[정답 확인]**\n도함수 $f'(x) = 3(x+1)^2 \\geq 0$이 모든 구간에서 성립하고, $f'(x)=0$인 점이 고립된 점이므로 함수는 항상 증가하여 정답은 **1**입니다.\n\n**[오답 분석]**\n- **0을 선택한 경우**: 도함수가 0이 되는 점이 존재한다고 해서 증가함수가 아니라고 판단한 오류. $f'(x) = 0$인 점이 고립된 한 점이면 여전히 증가함수입니다. 감소하는 구간이 존재해야만 증가함수가 아닙니다.\n\n**[핵심 포인트]**\n- 도함수의 부호로 증가/감소를 판정하되, $f'(x) = 0$인 점이 **고립된 점**이면 증가함수입니다.\n- 주어진 식이 완전세제곱 $(x+1)^3$ 형태임을 인식하면 도함수 계산이 더 명확해집니다.",
