    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n함수가 감소하는 구간을 찾기 위해서는 도함수를 이용합니다. 함수 $f(x)$에 대해:\n- $f'(x) > 0$인 구간: 함수가 증가\n- $f'(x) < 0$인 구간: 함수가 감소\n- $f'(x) = 0$인 점: 극값을 가지는 지점\n\n따라서 감소 구간을 구하려면 $f'(x) < 0$을 만족하는 $x$의 범위를 찾아야 합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = 2x^3 - 9x^2 + 12x - 4$$\n\n$$f'(x) = 6x^2 - 18x + 12$$\n\n**2단계: 도함수를 인수분해**\n\n$$f'(x) = 6x^2 - 18x + 12 = 6(x^2 - 3x + 2)$$\n\n$$= 6(x-1)(x-2)$$\n\n**3단계: 극값의 위치 파악**\n\n$f'(x) = 0$일 때: $x = 1$ 또는 $x = 2$\n\n**4단계: 부호 판정 (수직선 이용)**\n\n$f'(x) = 6(x-1)(x-2)$의 부호를 각 구간에서 판정합니다.\n\n- $x < 1$일 때: $(x-1) < 0, (x-2) < 0$ → $f'(x) = 6(-)(-) > 0$ ✓ (증가)\n- $1 < x < 2$일 때: $(x-1) > 0, (x-2) < 0$ → $f'(x) = 6(+)(-) < 0$ ✓ (감소)\n- $x > 2$일 때: $(x-1) > 0, (x-2) > 0$ → $f'(x) = 6(+)(+) > 0$ ✓ (증가)\n\n따라서 **감소 구간은 $1 < x < 2$** 입니다.\n\n**[정답 확인]**\n\n$f'(x) < 0$인 구간이 $1 < x < 2$이므로, 이 구간에서 함수 $f(x)$는 감소합니다.\n\n**[오답 분석]**\n\n- **②**: $x < 1$ 또는 $x > 2$에서는 $f'(x) > 0$이므로 함수가 증가합니다. (반대)\n- **③**: $0 < x < 3$은 증가와 감소 구간을 모두 포함하므로 부정확합니다.\n- **④**: $x < 0$에서도 $f'(x) > 0$이므로 함수가 증가합니다.\n- **⑤**: 명백히 감소하는 구간이 존재합니다.\n\n**[핵심 포인트]**\n\n도함수의 부호로 증감을 판정할 때, $f'(x) = 0$의 근을 기준으로 각 구간의 부호를 체계적으로 확인하는 것이 중요합니다. 특히 인수분해된 형태에서 각 인수의 부호를 따로 판정하면 실수를 줄일 수 있습니다.",
