    "explanation": "**[핵심 개념]**\n함수의 증가·감소 구간을 판정하기 위해서는 도함수를 이용합니다.\n- $f'(x) > 0$인 구간에서 함수는 증가\n- $f'(x) < 0$인 구간에서 함수는 감소\n- $f'(x) = 0$인 점은 극값의 후보\n\n도함수를 구하고 부호를 분석하여 증가 구간을 찾은 후, 유한 구간의 길이만 합합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 - 3x^2 + 5$$\n\n$$f'(x) = 3x^2 - 6x = 3x(x - 2)$$\n\n**Step 2: 도함수의 부호 분석**\n\n$f'(x) = 3x(x-2) = 0$에서 $x = 0$ 또는 $x = 2$\n\n구간별 부호를 조사합니다:\n- $x < 0$일 때: $f'(x) = 3(\\text{음})(\\text{음}) = \\text{양}$ → 증가\n- $0 < x < 2$일 때: $f'(x) = 3(\\text{양})(\\text{음}) = \\text{음}$ → 감소\n- $x > 2$일 때: $f'(x) = 3(\\text{양})(\\text{양}) = \\text{양}$ → 증가\n\n**Step 3: 증가 구간 정리**\n\n증가 구간:\n- $(-\\infty, 0)$: 무한 구간 (제외)\n- $(2, \\infty)$: 무한 구간 (제외)\n\n유한 구간에서의 증가 구간은 없습니다.\n\n**Step 4: 유한 구간의 길이 합**\n\n유한 구간의 증가 구간이 없으므로, 길이의 합은 **0**입니다.\n\n**[정답 확인]**\n문제에서 \"유한 구간의 길이만\" 구하도록 명시했으며, 이 함수의 증가 구간이 모두 무한 구간이므로 정답은 0입니다.\n\n**[오답 분석]**\n만약 다른 선택지가 있다면:\n- 2: 감소 구간 $(0, 2)$의 길이를 잘못 계산한 경우\n- 4: 두 무한 구간의 \"길이\"를 의도적으로 계산한 경우 (문제 조건 위반)\n- 음수: 도함수 부호를 잘못 판단한 경우\n\n**[핵심 포인트]**\n- 도함수의 부호 변화로 증가/감소 구간을 판정합니다.\n- **무한 구간은 길이를 계산할 수 없으므로 반드시 제외**해야 합니다.",
