    "explanation": "**[핵심 개념]**\n함수가 모든 실수에서 증가하려면 도함수가 모든 실수에서 0 이상이어야 합니다. 즉, $f'(x) \\geq 0$이 모든 $x$에 대해 성립해야 합니다. 이차함수의 판별식을 이용하여 항상 음이 아닌 조건을 구할 수 있습니다.\n\n**[풀이]**\n\n$f(x) = x^3 + ax$의 도함수를 구합니다.\n$$f'(x) = 3x^2 + a$$\n\n함수 $f(x)$가 모든 실수에서 증가하려면:\n$$f'(x) = 3x^2 + a \\geq 0 \\text{ (모든 실수 } x \\text{에 대해)}$$\n\n이 부등식이 모든 실수 $x$에서 성립하려면, $3x^2 + a$의 최솟값이 0 이상이어야 합니다.\n\n$3x^2$는 $x=0$일 때 최솟값 0을 가지므로, $3x^2 + a$의 최솟값은:\n$$\\min(3x^2 + a) = 0 + a = a$$\n\n따라서 조건은:\n$$a \\geq 0$$\n\n$a$의 최솟값은 $\\boxed{0}$입니다.\n\n**[정답 확인]**\n$a = 0$일 때 $f'(x) = 3x^2 \\geq 0$이 모든 $x$에서 성립하므로, $a$의 최솟값은 0입니다.\n\n**[오답 분석]**\n- ① $-3$, ② $-1$: 음수를 대입하면 $f'(x) = 3x^2 + a$가 음수가 되는 $x$값이 존재합니다. 예를 들어 $a=-1$이면 $x=0$에서 $f'(0)=-1<0$이므로 감소 구간이 생깁니다.\n- ④ $1$, ⑤ $3$: 이들은 조건을 만족하지만, 최솟값보다 큰 값들입니다.\n\n**[핵심 포인트]**\n함수가 항상 증가하는 조건은 $f'(x) \\geq 0$ (모든 $x$)이며, 이차식의 경우 최솟값이 0 이상이어야 합니다. 도함수가 0이 되는 점이 변곡점이 되는 경우도 증가함수에 포함됩니다.",
