    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해 도함수를 이용합니다. $f(x) = ax^3 + bx^2 + cx + d$ 형태의 3차 함수에서 $f'(x) = 0$이 되는 두 근을 $\\alpha, \\beta$라 할 때, 근과 계수의 관계를 이용하여 두 근의 합을 구할 수 있습니다. 도함수 $f'(x) = 3ax^2 + 2bx + c$에서 $ax^2 + bx + c = 0$의 두 근의 합은 $-\\frac{b}{a}$입니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = \\frac{1}{3}x^3 - x^2 - 3x + 5$$\n\n$$f'(x) = \\frac{1}{3} \\cdot 3x^2 - 2x - 3 = x^2 - 2x - 3$$\n\n**2단계: $f'(x) = 0$의 두 근의 합 구하기**\n\n$f'(x) = 0$에서:\n$$x^2 - 2x - 3 = 0$$\n\n이는 $ax^2 + bx + c = 0$ 형태에서 $a = 1, b = -2, c = -3$입니다.\n\n근과 계수의 관계에 의해 두 근의 합은:\n$$\\text{(두 근의 합)} = -\\frac{b}{a} = -\\frac{(-2)}{1} = 2$$\n\n**3단계: 검증 (필요시)**\n\n실제로 인수분해하면:\n$$x^2 - 2x - 3 = (x-3)(x+1) = 0$$\n\n따라서 두 근은 $x = 3, -1$이고, 두 근의 합은 $3 + (-1) = 2$\n\n**[정답 확인]**\n도함수 $f'(x) = x^2 - 2x - 3$에서 근과 계수의 관계를 적용하면 두 근의 합이 2가 되므로 정답입니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으므로 일반적인 오답을 설명하면:\n- **0**: $f'(x)$의 상수항을 실수로 이용한 경우\n- **-2**: 근과 계수의 관계에서 $\\frac{b}{a}$를 잘못 계산한 경우\n- **4**: 두 근을 잘못 구한 경우\n\n**[핵심 포인트]**\n- 3차 함수 $f(x) = \\frac{1}{3}x^3 - x^2 - 3x + 5$의 도함수는 2차 함수: $f'(x) = x^2 - 2x - 3$\n- 이차방정식 $ax^2 + bx + c = 0$의 두 근의 합은 **근과 계수의 관계**로 $-\\frac{b}{a}$임을 바로 적용하는 것이 가장 빠르고 효율적입니다.",
