    "explanation": "**[핵심 개념]**\n함수가 감소하는 구간을 찾기 위해서는 도함수를 이용합니다. 함수 $f(x)$에서:\n- $f'(x) < 0$인 구간에서 $f(x)$는 감소\n- $f'(x) > 0$인 구간에서 $f(x)$는 증가\n- $f'(x) = 0$인 점은 극값을 가지는 지점\n\n따라서 도함수를 구하고 부호를 조사하면 됩니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$f(x) = x^4 - 4x^3 + 6$\n\n$f'(x) = 4x^3 - 12x^2 = 4x^2(x - 3)$\n\n**2단계: 도함수가 0이 되는 점 찾기**\n\n$f'(x) = 0$일 때:\n$$4x^2(x - 3) = 0$$\n\n$x = 0$ (중근) 또는 $x = 3$\n\n**3단계: 도함수의 부호 조사**\n\n$f'(x) = 4x^2(x-3)$에서:\n- $4x^2 \\geq 0$ (항상 음이 아님)\n- $(x-3)$의 부호에 따라 전체 부호 결정\n\n| 구간 | $x < 0$ | $x = 0$ | $0 < x < 3$ | $x = 3$ | $x > 3$ |\n|------|---------|---------|-------------|---------|---------|\n| $4x^2$ | $+$ | $0$ | $+$ | $+$ | $+$ |\n| $x-3$ | $-$ | $-$ | $-$ | $0$ | $+$ |\n| $f'(x)$ | $-$ | $0$ | $-$ | $0$ | $+$ |\n\n**4단계: 결론**\n\n$f'(x) < 0$인 구간은 $x < 0$과 $0 < x < 3$입니다.\n이를 합치면 **$x < 3$**에서 감소합니다.\n\n**[정답 확인]**\n$f'(x) = 4x^2(x-3) \\leq 0$은 $x < 3$일 때 성립하므로, 함수는 $x < 3$에서 감소합니다.\n\n**[오답 분석]**\n- **①** $x < 0$: 부분적으로 맞지만, $0 < x < 3$에서도 감소하므로 불완전\n- **②** $0 < x < 3$: 부분적으로 맞지만, $x < 0$에서도 감소하므로 불완전\n- **④** $x > 3$: $f'(x) > 0$이므로 증가하는 구간 (틀림)\n- **⑤** $x > 0$: $x > 3$에서 증가하므로 틀림\n\n**[핵심 포인트]**\n- 도함수의 부호를 조사할 때 **중근을 주의**해야 합니다. $x=0$은 중근이므로 $4x^2$는 항상 0 이상이고, $(x-3)$의 부호에만 영향을 받습니다.\n- 최종 답은 여러 감소 구간을 합친 **최대 범위**로 표현합니다.",
