    "problem": "함수 $f(x) = x^3 - 6x^2 + 9x + 1$에 대해 $f$가 감소하는 구간에서 $f$의 최댓값과 최솟값의 차를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n함수의 증감을 판정하기 위해 도함수를 이용합니다. $f'(x) > 0$인 구간에서는 증가, $f'(x) < 0$인 구간에서는 감소합니다. 감소하는 구간에서 함수의 최댓값은 구간의 왼쪽 끝점에서, 최솟값은 구간의 오른쪽 끝점에서 나타납니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 6x^2 + 9x + 1$$\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**2단계: 함수의 증감 구간 판정**\n$f'(x) = 0$일 때: $x = 1$ 또는 $x = 3$\n\n부호 변화를 조사하면:\n- $x < 1$: $f'(x) = 3(-)(-) = (+)$ → 증가\n- $1 < x < 3$: $f'(x) = 3(+)(-) = (-)$ → **감소**\n- $x > 3$: $f'(x) = 3(+)(+) = (+)$ → 증가\n\n따라서 $f$가 감소하는 구간은 $[1, 3]$입니다.\n\n**3단계: 감소 구간에서 최댓값과 최솟값 구하기**\n\n감소 구간 $[1, 3]$에서:\n- 최댓값: $f(1) = 1^3 - 6(1)^2 + 9(1) + 1 = 1 - 6 + 9 + 1 = 5$\n- 최솟값: $f(3) = 3^3 - 6(3)^2 + 9(3) + 1 = 27 - 54 + 27 + 1 = 1$\n\n**4단계: 최댓값과 최솟값의 차 구하기**\n$$f(1) - f(3) = 5 - 1 = 4$$\n\n**[정답 확인]**\n감소 구간 $[1, 3]$에서 최댓값 5와 최솟값 1의 차는 4이므로 정답입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 다음과 같은 오류가 발생할 수 있습니다:\n- 도함수를 잘못 계산하면 증감 구간을 잘못 판정\n- $f(1)$과 $f(3)$만 계산하지 않고 극값이라고 착각\n- 전체 함수의 최댓값/최솟값을 구하는 오류\n\n**[핵심 포인트]**\n1. 감소 구간을 정확히 찾기 위해 도함수의 부호 변화를 체계적으로 확인하는 것이 필수입니다.\n2. 감소 구간 내에서는 왼쪽 끝이 최대, 오른쪽 끝이 최소입니다.",
