    "problem": "함수 $f(x) = \\frac{1}{3}x^3 - 2x^2 + 3x + 1$의 극대점의 $x$ 좌표를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n함수의 극대점을 찾기 위해서는 다음 단계를 따릅니다:\n1. 주어진 함수를 미분하여 도함수 $f'(x)$를 구합니다.\n2. 도함수가 0이 되는 점을 찾습니다 ($f'(x) = 0$).\n3. 그 점 전후에서 도함수의 부호 변화를 조사합니다.\n   - $f'(x)$가 양에서 음으로 변하면 극대점\n   - $f'(x)$가 음에서 양으로 변하면 극소점\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = \\frac{1}{3}x^3 - 2x^2 + 3x + 1$에서\n\n$$f'(x) = x^2 - 4x + 3$$\n\n**Step 2: 극값을 갖는 점 찾기 ($f'(x) = 0$)**\n\n$$x^2 - 4x + 3 = 0$$\n\n이 식을 인수분해하면:\n\n$$(x-1)(x-3) = 0$$\n\n따라서 $x = 1$ 또는 $x = 3$\n\n**Step 3: 각 점에서 극대/극소 판정**\n\n도함수 $f'(x) = (x-1)(x-3)$의 부호를 조사합니다:\n\n- $x < 1$일 때: $(x-1) < 0$, $(x-3) < 0$ → $f'(x) > 0$ (증가)\n- $1 < x < 3$일 때: $(x-1) > 0$, $(x-3) < 0$ → $f'(x) < 0$ (감소)\n- $x > 3$일 때: $(x-1) > 0$, $(x-3) > 0$ → $f'(x) > 0$ (증가)\n\n$x = 1$에서 $f'(x)$가 양(+)에서 음(-)으로 변하므로 **극대점**입니다.\n\n$x = 3$에서 $f'(x)$가 음(-)에서 양(+)으로 변하므로 극소점입니다.\n\n따라서 극대점의 $x$ 좌표는 **1**입니다.\n\n**[정답 확인]**\n$x=1$ 전후에서 도함수가 양에서 음으로 변하므로 극대점이며, 따라서 답은 1입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 만약 3이 선지에 있다면 이는 극소점의 $x$ 좌표이므로 오답입니다. 부호 변화를 정확히 확인하지 않으면 극대와 극소를 혼동할 수 있습니다.\n\n**[핵심 포인트]**\n- 극대/극소 판정은 도함수의 **부호 변화**를 확인하는 것이 핵심입니다.\n- 양→음 변화가 극대, 음→양 변화가 극소입니다.",
