    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수가 특정 점에서 극값을 가지려면 그 점에서 도함수가 0이어야 합니다. 또한 극솟값을 판별하기 위해 이계 도함수를 사용하거나 도함수의 부호 변화를 확인합니다.\n- 극값의 조건: $f'(x) = 0$\n- 극솟값 판별: $f''(x) > 0$ (또는 $f'(x)$가 음에서 양으로 변할 때)\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = x^3 - 3bx + 2$$\n\n$$f'(x) = 3x^2 - 3b$$\n\n**2단계: $x=1$에서 극값을 가지는 조건**\n\n$x=1$에서 극값을 가지려면 $f'(1) = 0$이어야 합니다.\n\n$$f'(1) = 3(1)^2 - 3b = 0$$\n\n$$3 - 3b = 0$$\n\n$$b = 1$$\n\n**3단계: $x=1$에서 극솟값인지 확인**\n\n이계 도함수를 구합니다:\n$$f''(x) = 6x$$\n\n$$f''(1) = 6 > 0$$\n\n$f''(1) > 0$이므로 $x=1$에서 극솟값을 가집니다. ✓\n\n따라서 $b = 1$\n\n**[정답 확인]**\n$b=1$일 때 $f'(1)=0$이고 $f''(1)=6>0$이므로 $x=1$에서 극솟값을 가집니다.\n\n**[오답 분석]**\n\n① $b=-1$: $f'(1) = 3-3(-1) = 6 \\neq 0$ → 극값 조건 불만족\n\n② $b=0$: $f'(1) = 3-0 = 3 \\neq 0$ → 극값 조건 불만족\n\n④ $b=2$: $f'(1) = 3-3(2) = -3 \\neq 0$ → 극값 조건 불만족\n\n⑤ $b=3$: $f'(1) = 3-3(3) = -6 \\neq 0$ → 극값 조건 불만족\n\n**[핵심 포인트]**\n극값의 필요조건은 도함수가 0이 되는 것입니다. 극솟값인지 극댓값인지 판별하려면 이계 도함수를 확인하거나 도함수의 부호 변화를 살펴야 합니다.",
