    "answer": 2,
    "explanation": "**[핵심 개념]**\n삼차함수가 극값을 가지려면 도함수가 서로 다른 두 실근을 가져야 합니다. 즉, $f'(x) = 0$이 서로 다른 두 실근을 가져야 극대값과 극소값이 모두 존재합니다. 도함수가 중근을 가지거나 실근이 없으면 극값이 없습니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f'(x) = 3x^2 - 6ax$$\n\n**2단계: 극값 존재 조건**\n삼차함수가 극값을 가지려면 $f'(x) = 0$이 서로 다른 두 실근을 가져야 합니다.\n\n$$f'(x) = 3x^2 - 6ax = 3x(x - 2a) = 0$$\n\n이 방정식의 해는 $x = 0$ 또는 $x = 2a$입니다.\n\n**3단계: 서로 다른 두 실근 조건**\n극값이 존재하려면 두 근이 서로 달라야 하므로:\n$$0 \\neq 2a$$\n$$a \\neq 0$$\n\n**4단계: 검증**\n- $a \\neq 0$일 때: $f'(x) = 3x(x - 2a) = 0$의 두 근 $x = 0, x = 2a$가 서로 다르므로, $f'(x)$의 부호가 바뀌어 극값이 존재합니다.\n\n- $a = 0$일 때: $f'(x) = 3x^2 \\geq 0$ (항상 0 이상)이므로 $f'(x)$의 부호가 바뀌지 않아 극값이 없습니다.\n\n**[정답 확인]**\n도함수 $f'(x) = 3x(x-2a)$가 부호를 바꾸며 지나가는 서로 다른 두 실근을 가지려면 $a \\neq 0$이어야 합니다.\n\n**[오답 분석]**\n- ① $a > 0$: $a < 0$인 경우도 극값을 가지므로 충분조건이 아닙니다.\n- ② $a < 0$: $a > 0$인 경우도 극값을 가지므로 충분조건이 아닙니다.\n- ④ $a > 1$: $0 < a < 1$인 경우도 극값을 가지므로 과도한 조건입니다.\n- ⑤ 모든 실수: $a = 0$일 때 극값이 없으므로 거짓입니다.\n\n**[핵심 포인트]**\n삼차함수가 극값을 가지는 필요충분조건은 도함수가 서로 다른 두 실근을 가지는 것입니다. 이 문제에서는 $f'(x) = 3x(x-2a)$의 두 근이 $0$과 $2a$이므로, 이들이 같지 않으려면 반드시 $a \\neq 0$이어야 합니다.",
