    "_type": "increasing_decreasing",
    "type": "증감",
    "problem": "함수 $f(x) = x^3 - 3x^2 - 9x + k$의 극댓값이 양수이고 극솟값이 음수일 때, 정수 $k$의 개수는?",
    "answerType": "short",
    "choices": null,
    "answer": 31,
    "explanation": "**[핵심 개념]**\n\n극값을 구하기 위해 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호 변화로 극대/극소를 판단합니다. 극댓값과 극솟값의 조건을 이용하여 매개변수 $k$의 범위를 구하는 문제입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f'(x) = 3x^2 - 6x - 9 = 3(x^2 - 2x - 3) = 3(x+1)(x-3)$$\n\n따라서 $f'(x) = 0$일 때 $x = -1$ 또는 $x = 3$\n\n**Step 2: 극값의 위치 결정**\n\n- $x < -1$: $f'(x) > 0$ (증가)\n- $-1 < x < 3$: $f'(x) < 0$ (감소)\n- $x > 3$: $f'(x) > 0$ (증가)\n\n따라서 $x = -1$에서 극댓값, $x = 3$에서 극솟값을 가집니다.\n\n**Step 3: 극값 계산**\n\n극댓값: \n$$f(-1) = (-1)^3 - 3(-1)^2 - 9(-1) + k = -1 - 3 + 9 + k = 5 + k$$\n\n극솟값:\n$$f(3) = 3^3 - 3(3)^2 - 9(3) + k = 27 - 27 - 27 + k = -27 + k$$\n\n**Step 4: 조건 적용**\n\n극댓값이 양수: $5 + k > 0$ → $k > -5$\n\n극솟값이 음수: $-27 + k < 0$ → $k < 27$\n\n따라서 $-5 < k < 27$\n\n**Step 5: 정수 $k$의 개수**\n\n$k$는 정수이고 $-5 < k < 27$을 만족하므로:\n$$k \\in \\{-4, -3, -2, -1, 0, 1, 2, \\cdots, 25, 26\\}$$\n\n개수는 $26 - (-4) + 1 = 31$\n\n또는 $-4$부터 $26$까지의 정수: $26 - (-4) + 1 = 31$개\n\n**[정답 확인]**\n\n극댓값 $5 + k > 0$과 극솟값 $-27 + k < 0$의 두 조건을 동시에 만족하는 정수 $k$는 $-4$부터 $26$까지 총 31개입니다.\n\n**[오답 분석]**\n\n- **30개**: 경계값을 포함하지 않는 경우 ($k > -5$를 $k \\geq -5$로 잘못 계산)\n- **32개**: 경계값을 포함하는 경우 ($k = -5$ 또는 $k = 27$을 포함)\n- **27개**: 범위를 $0 \\leq k < 27$로 잘못 설정\n- **26개**: 경계값을 모두 제외하는 경우\n\n**[핵심 포인트]**\n\n1. 부등호가 엄격한 부등호($<, >$)이므로 경계값은 제외됩니다. $-5 < k < 27$에서 정수 $k$는 $-4, -3, \\cdots, 26$입니다.\n\n2. 극값의 위치를 정확히 파악한 후($x=-1$에서 극대, $x=3$에서 극소) 조건식을 세워야 합니다.",
