    "problem": "함수 $f(x) = 2x^3 - 3x^2 - 12x + 7$의 극댓값과 극솟값의 합을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n극값을 구하기 위해서는 먼저 도함수를 구하고 $f'(x) = 0$인 점을 찾아야 합니다. 도함수의 부호 변화를 조사하여 극댓값과 극솟값을 판정합니다. 극댓값은 $f'(x)$가 양에서 음으로 변할 때, 극솟값은 $f'(x)$가 음에서 양으로 변할 때 나타납니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = 2x^3 - 3x^2 - 12x + 7$$\n\n$$f'(x) = 6x^2 - 6x - 12$$\n\n**2단계: 극값을 갖는 점 찾기**\n\n$f'(x) = 0$인 점을 구합니다.\n\n$$6x^2 - 6x - 12 = 0$$\n\n$$x^2 - x - 2 = 0$$\n\n$$(x - 2)(x + 1) = 0$$\n\n$$x = 2 \\text{ 또는 } x = -1$$\n\n**3단계: 극값 판정 (도함수 부호 조사)**\n\n$f'(x) = 6(x - 2)(x + 1)$\n\n- $x < -1$일 때: $f'(x) = 6(-)(-)= (+)$ → 증가\n- $-1 < x < 2$일 때: $f'(x) = 6(-)(+)= (-)$ → 감소\n- $x > 2$일 때: $f'(x) = 6(+)(+)= (+)$ → 증가\n\n따라서 $x = -1$에서 극댓값, $x = 2$에서 극솟값을 가집니다.\n\n**4단계: 극댓값과 극솟값 계산**\n\n극댓값 ($x = -1$일 때):\n$$f(-1) = 2(-1)^3 - 3(-1)^2 - 12(-1) + 7$$\n$$= 2(-1) - 3(1) + 12 + 7$$\n$$= -2 - 3 + 12 + 7 = 14$$\n\n극솟값 ($x = 2$일 때):\n$$f(2) = 2(2)^3 - 3(2)^2 - 12(2) + 7$$\n$$= 2(8) - 3(4) - 24 + 7$$\n$$= 16 - 12 - 24 + 7 = -13$$\n\n**5단계: 극댓값과 극솟값의 합**\n\n$$\\text{극댓값} + \\text{극솟값} = 14 + (-13) = 1$$\n\n**[정답 확인]**\n극댓값 14와 극솟값 -13을 더하면 1이므로 정답입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 일반적인 오류는:\n- 극값을 구하지 않고 함수값만 계산한 경우\n- $f'(x) = 0$의 해를 잘못 구한 경우\n- 극댓값과 극솟값을 반대로 구한 경우 (결과는 같지만 과정에서 오류)\n- 극값의 합이 아닌 다른 값(곱, 차)을 구한 경우\n\n**[핵심 포인트]**\n1. 3차 함수의 극값은 $f'(x) = 0$의 두 근에서 나타나며, 도함수의 부호 변화로 극댓값과 극솟값을 판정합니다.\n2. 극값의 합을 구할 때는 개별 극값을 정확히 계산한 후 더해야 합니다.",
