    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수의 증감을 조사하기 위해서는 먼저 도함수를 구해야 합니다. 도함수 $f'(x) = 0$인 점은 함수의 극값(극대값 또는 극소값)을 가지는 지점입니다. 다항함수의 도함수를 구할 때는 거듭제곱 미분법 $\\frac{d}{dx}x^n = nx^{n-1}$을 사용합니다.\n\n**[풀이]**\n\n**단계 1: 주어진 함수의 도함수 구하기**\n\n주어진 함수는 $f(x) = x^3 - 6x^2 + 12x - 1$입니다.\n\n거듭제곱 미분법을 적용하면:\n$$f'(x) = 3x^2 - 12x + 12$$\n\n**단계 2: $f'(x) = 0$인 $x$ 값 구하기**\n\n$f'(x) = 0$을 풀기 위해 방정식을 정리합니다:\n$$3x^2 - 12x + 12 = 0$$\n\n양변을 3으로 나누면:\n$$x^2 - 4x + 4 = 0$$\n\n**단계 3: 인수분해**\n\n이 식을 인수분해하면:\n$$(x - 2)^2 = 0$$\n\n따라서:\n$$x = 2 \\text{ (중근)}$$\n\n**[정답 확인]**\n$f'(x) = 3(x-2)^2$이므로 $f'(x) = 0$의 유일한 해는 $x = 2$이며, 중근이므로 이 점에서 함수의 극값이 아닌 변곡점이 됩니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 학생들이 흔히 하는 실수:\n- $-12x$를 미분할 때 $-12$가 아닌 다른 값을 적용하는 경우\n- 인수분해 과정에서 계산 오류로 다른 값을 얻는 경우\n- $3x^2 - 12x + 12 = 0$을 근의 공식으로 풀 때 계산 실수\n\n**[핵심 포인트]**\n- 도함수의 계산을 정확히 해야 합니다. 특히 상수항 $-1$은 미분하면 0이 됩니다.\n- $f'(x) = 3(x-2)^2$는 항상 0 이상이므로, 함수 $f(x)$는 $x=2$를 제외하고 항상 증가함수입니다.",
