    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n함수의 증감을 판정하기 위해서는 도함수를 이용합니다. 함수 $f(x)$에서:\n- $f'(x) > 0$인 구간에서 함수는 증가\n- $f'(x) < 0$인 구간에서 함수는 감소\n- $f'(x) = 0$인 점은 극값을 가지는 지점\n\n따라서 먼저 도함수를 구하고, $f'(x) = 0$인 점을 찾아 증가 구간을 결정합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = -x^3 + 3x^2 + 9x - 2$$\n\n미분하면:\n$$f'(x) = -3x^2 + 6x + 9$$\n\n**Step 2: 도함수의 부호 결정하기**\n\n$f'(x) = 0$이 되는 점을 찾습니다:\n$$-3x^2 + 6x + 9 = 0$$\n\n양변을 $-3$으로 나누면:\n$$x^2 - 2x - 3 = 0$$\n\n인수분해하면:\n$$(x - 3)(x + 1) = 0$$\n\n따라서 $x = 3$ 또는 $x = -1$\n\n**Step 3: 증가 구간 판정**\n\n$f'(x) = -3(x^2 - 2x - 3) = -3(x - 3)(x + 1)$\n\n부호 판정표를 만들면:\n- $x < -1$: $(x - 3) < 0$, $(x + 1) < 0$ → $f'(x) = -3 \\cdot (-) \\cdot (-) = -3 \\cdot (+) < 0$ (감소)\n- $-1 < x < 3$: $(x - 3) < 0$, $(x + 1) > 0$ → $f'(x) = -3 \\cdot (-) \\cdot (+) = -3 \\cdot (-) > 0$ (증가)\n- $x > 3$: $(x - 3) > 0$, $(x + 1) > 0$ → $f'(x) = -3 \\cdot (+) \\cdot (+) = -3 \\cdot (+) < 0$ (감소)\n\n따라서 함수는 $-1 < x < 3$에서 증가합니다.\n\n**Step 4: 증가 구간의 길이 계산**\n\n$$\\text{길이} = 3 - (-1) = 3 + 1 = 4$$\n\n**[정답 확인]**\n\n도함수 $f'(x) = -3(x+1)(x-3)$에서 $-1 < x < 3$ 구간에서만 양수이므로, 증가 구간의 길이는 $3-(-1)=4$입니다.\n\n**[오답 분석]**\n\n객관식 선택지가 없으므로 일반적인 오답 사례:\n- **2**: 극값점들의 차이를 절반으로 계산한 경우\n- **6**: 극값점의 절댓값 합을 구한 경우 ($|-1| + |3| = 4$는 맞지만 헷갈릴 수 있음)\n- **3**: 한쪽 극값점만을 기준으로 계산한 경우\n\n**[핵심 포인트]**\n\n1. **도함수의 영점**: 함수의 증감 판정은 $f'(x) = 0$인 점에서 도함수의 부호가 바뀌는 것을 기준으로 합니다.\n2. **구간의 길이**: 증가 구간 $[a, b]$의 길이는 단순히 $b - a$이므로, 두 극값점의 차를 계산하면 됩니다.",
