    "explanation": "**[핵심 개념]**\n\n극값을 가지는 조건: 함수 $f(x)$가 $x = c$에서 극값을 가지려면 $f'(c) = 0$이고 그 점에서 도함수의 부호가 바뀌어야 한다. 특히 극대에서 극소로 변하면, 극대점과 극소점 사이의 도함수는 항상 음수이다. 3차 함수의 도함수는 2차 함수이므로, 극값을 2개 가질 때 $f'(x) = 0$은 서로 다른 2개의 실근을 가진다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = x^3 + ax^2 + bx + 1$$\n\n$$f'(x) = 3x^2 + 2ax + b$$\n\n**2단계: 극값 조건 적용**\n\n$x = -1$에서 극대, $x = 3$에서 극소를 가지므로, 이 두 점에서 도함수가 0이 된다.\n\n$$f'(-1) = 0 \\Rightarrow 3(-1)^2 + 2a(-1) + b = 0$$\n$$3 - 2a + b = 0 \\cdots (1)$$\n\n$$f'(3) = 0 \\Rightarrow 3(3)^2 + 2a(3) + b = 0$$\n$$27 + 6a + b = 0 \\cdots (2)$$\n\n**3단계: 연립방정식 풀기**\n\n식 (2)에서 식 (1)을 빼면:\n\n$$(27 + 6a + b) - (3 - 2a + b) = 0$$\n$$24 + 8a = 0$$\n$$a = -3$$\n\n$a = -3$을 식 (1)에 대입:\n\n$$3 - 2(-3) + b = 0$$\n$$3 + 6 + b = 0$$\n$$b = -9$$\n\n**4단계: 검증**\n\n$f'(x) = 3x^2 - 6x - 9 = 3(x^2 - 2x - 3) = 3(x+1)(x-3)$\n\n- $x < -1$일 때: $f'(x) > 0$ (증가)\n- $-1 < x < 3$일 때: $f'(x) < 0$ (감소)\n- $x > 3$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -1$에서 극대, $x = 3$에서 극소 ✓\n\n**5단계: 답 구하기**\n\n$$a + b = -3 + (-9) = -12$$\n\n**[정답 확인]**\n\n$a = -3, b = -9$일 때 도함수 $f'(x) = 3(x+1)(x-3)$의 부호 변화가 극대($x=-1$)에서 극소($x=3$)로 정확히 일치하므로 $a+b = -12$가 정답이다.\n\n**[오답 분석]**\n\n- **② $-6$**: 식 (1)과 (2)를 더하거나 잘못 계산한 경우\n- **③ $0$**: $a$와 $b$의 부호를 잘못 판단한 경우\n- **④ $6$**: 연립방정식 풀이 중 계산 실수 (예: $a = 3$으로 잘못 구한 경우)\n- **⑤ $12$**: $a + b$의 값을 양수로 잘못 구한 경우\n\n**[핵심 포인트]**\n\n극값 조건에서 $f'(c) = 0$을 이용하여 미지수 방정식을 세운다. 구한 값이 실제로 극대/극소 조건을 만족하는지 도함수의 부호 변화로 **반드시 검증**해야 한다.",
