    "problem": "함수 $f(x) = x^4 - 8x^2 + 3$이 감소하는 구간을 모두 구하면 $(-\\infty, a) \\cup (0, b)$이다. $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n함수가 감소하는 구간을 구하려면 도함수를 이용합니다. $f'(x) < 0$인 구간이 함수가 감소하는 구간입니다. \n- 도함수를 구한 후 $f'(x) = 0$의 근을 찾습니다.\n- 근을 기준으로 도함수의 부호를 판정하여 감소 구간을 결정합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = x^4 - 8x^2 + 3$$\n\n$$f'(x) = 4x^3 - 16x = 4x(x^2 - 4) = 4x(x-2)(x+2)$$\n\n**2단계: 도함수가 0이 되는 점 찾기**\n\n$$f'(x) = 0$$\n$$4x(x-2)(x+2) = 0$$\n\n근은 $x = -2, 0, 2$입니다.\n\n**3단계: 부호 판정표 작성**\n\n구간을 나누어 $f'(x)$의 부호를 확인합니다.\n\n| 구간 | $x < -2$ | $-2 < x < 0$ | $0 < x < 2$ | $x > 2$ |\n|------|----------|-------------|-----------|---------|\n| $4x$ | $-$ | $-$ | $+$ | $+$ |\n| $x+2$ | $-$ | $+$ | $+$ | $+$ |\n| $x-2$ | $-$ | $-$ | $-$ | $+$ |\n| $f'(x)$ | $-$ | $+$ | $-$ | $+$ |\n\n**4단계: 감소 구간 결정**\n\n$f'(x) < 0$인 구간은:\n- $x < -2$\n- $0 < x < 2$\n\n따라서 감소하는 구간은 $(-\\infty, -2) \\cup (0, 2)$\n\n**5단계: $a + b$ 계산**\n\n주어진 형태와 비교하면:\n$$(-\\infty, a) \\cup (0, b) = (-\\infty, -2) \\cup (0, 2)$$\n\n따라서 $a = -2$, $b = 2$\n\n$$a + b = -2 + 2 = 0$$\n\n**[정답 확인]**\n부호 판정표를 통해 도함수가 $x < -2$와 $0 < x < 2$에서 음수임을 확인했으므로 $a = -2, b = 2$이고, $a + b = 0$이 정답입니다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 사항 없음.\n\n**[핵심 포인트]**\n- 도함수의 부호 판정은 **인수분해된 형태**에서 각 인수의 부호를 구간별로 확인하는 것이 가장 효율적입니다.\n- 음의 인수 개수가 **홀수**일 때 $f'(x) < 0$ (감소), **짝수**일 때 $f'(x) > 0$ (증가)입니다.",
