    "_type": "max_min",
    "type": "최대최소",
    "problem": "함수 $f(x) = x^3 - 3x + 2$의 구간 $[-2, 2]$에서의 최댓값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최댓값을 구하기 위해서는 다음 세 가지를 비교해야 합니다:\n1. 구간 내 극값(극댓값, 극솟값)\n2. 구간의 양 끝점에서의 함수값\n\n극값을 찾기 위해 도함수를 구하고 $f'(x) = 0$인 점을 찾습니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 3x + 2$$\n$$f'(x) = 3x^2 - 3$$\n\n**2단계: 극값을 찾기 위해 $f'(x) = 0$인 점 찾기**\n$$f'(x) = 3x^2 - 3 = 0$$\n$$3(x^2 - 1) = 0$$\n$$x^2 = 1$$\n$$x = 1 \\text{ 또는 } x = -1$$\n\n두 극값 모두 구간 $[-2, 2]$에 포함됩니다.\n\n**3단계: 극값의 성질 판정**\n$$f''(x) = 6x$$\n- $x = -1$일 때: $f''(-1) = -6 < 0$ → 극댓값\n- $x = 1$일 때: $f''(1) = 6 > 0$ → 극솟값\n\n**4단계: 함수값 계산**\n\n극값에서의 함수값:\n$$f(-1) = (-1)^3 - 3(-1) + 2 = -1 + 3 + 2 = 4$$\n$$f(1) = 1^3 - 3(1) + 2 = 1 - 3 + 2 = 0$$\n\n구간 끝점에서의 함수값:\n$$f(-2) = (-2)^3 - 3(-2) + 2 = -8 + 6 + 2 = 0$$\n$$f(2) = 2^3 - 3(2) + 2 = 8 - 6 + 2 = 4$$\n\n**5단계: 비교**\n$$f(-2) = 0, \\quad f(-1) = 4, \\quad f(1) = 0, \\quad f(2) = 4$$\n\n따라서 최댓값은 $\\boxed{4}$입니다.\n\n**[정답 확인]**\n구간 $[-2, 2]$에서 계산한 모든 함수값($0, 4, 0, 4$) 중 가장 큰 값은 $4$이므로, 이것이 최댓값입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답 유형:\n- $f(1) = 0$을 선택: 극솟값을 극댓값으로 착각\n- $f(-2) = 0$을 선택: 극값만 고려하고 끝점 확인 누락\n- $f(0) = 2$를 선택: 극값이 아닌 임의의 점에서의 값 계산\n\n**[핵심 포인트]**\n폐구간에서의 최댓값은 **극값과 끝점 함수값을 모두 계산하여 비교**해야 합니다. 이 문제에서는 극댓값 $f(-1) = 4$와 끝점 $f(2) = 4$가 같으므로 둘 다 최댓값입니다.",
