    "answer": 2,
    "explanation": "**[핵심 개념]**\n이차함수 $f(x) = ax^2 + bx + c$ (단, $a \\neq 0$)의 최댓값 또는 최솟값은 꼭짓점에서 나타난다. $a > 0$이면 최솟값, $a < 0$이면 최댓값을 가진다. 꼭짓점의 $x$좌표는 $x = -\\frac{b}{2a}$이고, 이를 함수에 대입하면 최댓값 또는 최솟값을 구할 수 있다. 또는 완전제곱식으로 변형하여 직접 최댓값을 읽을 수 있다.\n\n**[풀이]**\n주어진 함수: $f(x) = -x^2 + 4x + 1$\n\n**방법 1: 완전제곱식으로 변형**\n\n$f(x) = -x^2 + 4x + 1$\n\n$= -(x^2 - 4x) + 1$\n\n$= -(x^2 - 4x + 4 - 4) + 1$\n\n$= -(x^2 - 4x + 4) + 4 + 1$\n\n$= -(x - 2)^2 + 5$\n\n$a = -1 < 0$이므로 이차함수는 아래로 볼록한 포물선이다.\n\n$(x - 2)^2 \\geq 0$이므로 $-(x - 2)^2 \\leq 0$\n\n따라서 $f(x) = -(x - 2)^2 + 5 \\leq 5$\n\n최댓값은 $(x - 2)^2 = 0$, 즉 $x = 2$일 때 $f(2) = 5$\n\n**방법 2: 꼭짓점 공식 이용**\n\n$f(x) = -x^2 + 4x + 1$에서 $a = -1$, $b = 4$, $c = 1$\n\n꼭짓점의 $x$좌표: $x = -\\frac{b}{2a} = -\\frac{4}{2(-1)} = -\\frac{4}{-2} = 2$\n\n$f(2) = -(2)^2 + 4(2) + 1 = -4 + 8 + 1 = 5$\n\n**[정답 확인]**\n$f(x) = -(x-2)^2 + 5$의 형태에서 $(x-2)^2 \\geq 0$이므로 최댓값은 $x=2$일 때 5이다.\n\n**[오답 분석]**\n- ① 3: 계산 실수로 $f(x)$를 잘못 전개한 경우\n- ② 4: 완전제곱식 변형 시 상수항을 잘못 계산한 경우\n- ④ 6: $-x^2$ 항의 부호를 무시하고 계산한 경우\n- ⑤ 7: 원래 상수항인 1만 더한 경우\n\n**[핵심 포인트]**\n이차함수의 최댓값/최솟값은 **완전제곱식으로 변형하면 직관적으로 읽을 수 있다**. 음수 계수가 있을 때는 부호 변환에 주의하고, 최종적으로 $(x-p)^2$ 형태의 계수 부호를 확인하여 최댓값인지 최솟값인지 판단하자.",
