    "answer": -16,
    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최솟값을 구하기 위해서는 다음 세 위치를 모두 비교해야 합니다:\n1) 구간 내 극값을 갖는 점 (도함수 = 0인 점)\n2) 구간의 왼쪽 끝점\n3) 구간의 오른쪽 끝점\n\n함수의 극값은 $f'(x) = 0$을 풀어서 찾으며, 해당 점이 구간 내에 있을 때만 비교 대상이 됩니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 - 12x$$\n$$f'(x) = 3x^2 - 12$$\n\n**Step 2: 극값 찾기**\n$f'(x) = 0$을 풀면:\n$$3x^2 - 12 = 0$$\n$$x^2 = 4$$\n$$x = \\pm 2$$\n\n구간 $[0, 3]$ 내에 있는 극값은 $x = 2$입니다.\n\n**Step 3: 세 점에서의 함수값 계산**\n\n구간의 끝점과 극값을 갖는 점에서 함수값을 계산합니다.\n\n$x = 0$일 때:\n$$f(0) = 0^3 - 12(0) = 0$$\n\n$x = 2$일 때:\n$$f(2) = 2^3 - 12(2) = 8 - 24 = -16$$\n\n$x = 3$일 때:\n$$f(3) = 3^3 - 12(3) = 27 - 36 = -9$$\n\n**Step 4: 최솟값 결정**\n$$f(0) = 0, \\quad f(2) = -16, \\quad f(3) = -9$$\n\n세 값을 비교하면 $-16 < -9 < 0$이므로, 최솟값은 $\\boxed{-16}$입니다.\n\n**[정답 확인]**\n구간 $[0, 3]$ 내의 모든 후보 지점(끝점 2개, 극값 지점 1개)에서 함수값을 비교했을 때 가장 작은 값이 $-16$입니다.\n\n**[오답 분석]**\n- **0**: 구간의 좌측 끝점 값이지만 최솟값이 아님\n- **-9**: 구간의 우측 끝점 값이지만 극값인 $x=2$에서의 값이 더 작음\n- **-15, -17 등**: 계산 오류 (특히 $f(2) = 8 - 24 = -16$을 잘못 계산)\n\n**[핵심 포인트]**\n폐구간에서 최솟값을 구할 때는 반드시 **구간의 끝점과 구간 내의 극값을 갖는 점 모두**에서 함수값을 계산하여 비교해야 합니다. 극값만 찾는 것으로는 부족합니다.",
