    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. \n- $f'(x) = 0$인 점에서 극값 후보를 찾습니다.\n- $f'(x)$의 부호 변화를 조사하여 극대/극소를 판정합니다.\n- $f'(x)$가 양에서 음으로 변할 때 극댓값, 음에서 양으로 변할 때 극솟값입니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = 2x^3 - 3x^2 - 12x + 5$$\n\n$$f'(x) = 6x^2 - 6x - 12$$\n\n**2단계: 극값 후보점 찾기**\n\n$f'(x) = 0$을 풀어봅시다.\n\n$$6x^2 - 6x - 12 = 0$$\n\n$$x^2 - x - 2 = 0$$\n\n$$(x-2)(x+1) = 0$$\n\n$$x = 2 \\text{ 또는 } x = -1$$\n\n**3단계: 극대/극소 판정**\n\n$f'(x) = 6(x-2)(x+1)$로 인수분해되므로 부호를 조사합니다.\n\n- $x < -1$일 때: $f'(x) = 6(-)(-) = (+)$ → 증가\n- $-1 < x < 2$일 때: $f'(x) = 6(-)(+) = (-)$ → 감소  \n- $x > 2$일 때: $f'(x) = 6(+)(+) = (+)$ → 증가\n\n따라서 $x = -1$에서 극댓값, $x = 2$에서 극솟값을 가집니다.\n\n**4단계: 극댓값 계산**\n\n$$f(-1) = 2(-1)^3 - 3(-1)^2 - 12(-1) + 5$$\n\n$$= 2(-1) - 3(1) + 12 + 5$$\n\n$$= -2 - 3 + 12 + 5$$\n\n$$= 12$$\n\n**[정답 확인]**\n$x = -1$에서 도함수의 부호가 양에서 음으로 변하므로 극댓값이며, $f(-1) = 12$입니다.\n\n**[오답 분석]**\n- ① 5: $f(0) = 5$이지만 이는 극값이 아닙니다.\n- ② 10: 계산 실수로 나올 수 있는 값입니다.\n- ④ 15: 극솟값 $f(2) = 16 - 12 - 24 + 5 = -15$와 혼동하거나 계산 실수입니다.\n- ⑤ 20: 특별한 의미 없이 큰 값을 선택한 경우입니다.\n\n**[핵심 포인트]**\n극값을 구할 때는 ① $f'(x) = 0$의 해를 정확히 구하고, ② $f'(x)$의 부호 변화로 극대/극소를 판정한 후, ③ 극댓값의 후보점에서만 함수값을 계산하는 것이 중요합니다.",
