    "problem": "함수 $f(x) = x^3 - 6x^2 + 9x + 2$의 구간 $[0, 4]$에서의 최댓값과 최솟값의 차를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최댓값과 최솟값을 구하기 위해서는:\n1. 구간 내에서 함수의 극값을 찾기 위해 도함수를 구하고 $f'(x) = 0$인 점을 찾는다\n2. 극값 후보점과 구간의 양 끝점에서 함수값을 비교한다\n3. 최댓값과 최솟값의 차를 구한다\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 - 6x^2 + 9x + 2$$\n\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**Step 2: 극값 후보점 찾기**\n\n$f'(x) = 0$일 때: $x = 1$ 또는 $x = 3$\n\n두 점 모두 구간 $[0, 4]$ 내에 포함된다.\n\n**Step 3: 부호 분석 (극값 판정)**\n\n- $x < 1$: $f'(x) > 0$ (증가)\n- $1 < x < 3$: $f'(x) < 0$ (감소)\n- $x > 3$: $f'(x) > 0$ (증가)\n\n따라서 $x=1$에서 극대, $x=3$에서 극소\n\n**Step 4: 함수값 계산**\n\n구간 끝점과 극값점에서 함수값을 구한다:\n\n$$f(0) = 0 - 0 + 0 + 2 = 2$$\n\n$$f(1) = 1 - 6 + 9 + 2 = 6$$\n\n$$f(3) = 27 - 54 + 27 + 2 = 2$$\n\n$$f(4) = 64 - 96 + 36 + 2 = 6$$\n\n**Step 5: 최댓값과 최솟값 결정**\n\n- 최댓값: $\\max\\{2, 6, 2, 6\\} = 6$ ($x=1$ 또는 $x=4$에서)\n- 최솟값: $\\min\\{2, 6, 2, 6\\} = 2$ ($x=0$ 또는 $x=3$에서)\n\n**Step 6: 최댓값과 최솟값의 차**\n\n$$\\text{최댓값} - \\text{최솟값} = 6 - 2 = 4$$\n\n**[정답 확인]**\n구간 $[0, 4]$에서 함수의 모든 중요한 점(극값점과 끝점)을 확인하면 최댓값은 6, 최솟값은 2이므로 그 차는 4이다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 만약 다른 답이 나왔다면:\n- 극값을 놓쳤거나 (예: 3만 고려)\n- 끝점값을 계산하지 않았거나\n- 함수값 계산 실수가 있을 가능성\n\n**[핵심 포인트]**\n**폐구간에서의 최댓값/최솟값은 반드시 극값점과 끝점을 모두 비교해야 한다. 극값점에서 최댓값이 나오지 않을 수도 있다.**",
    "difficulty": "lv2",
