    "explanation": "**[핵심 개념]**\n산술-기하 평균 부등식(AM-GM 부등식)을 이용하여 최솟값을 구하는 문제입니다.\n\n산술-기하 평균 부등식: 양수 $a, b$에 대해 $\\dfrac{a+b}{2} \\geq \\sqrt{ab}$이며, 등호는 $a=b$일 때 성립합니다.\n\n이를 정리하면 $a + b \\geq 2\\sqrt{ab}$입니다.\n\n**[풀이]**\n\n주어진 함수는 $f(x) = x + \\dfrac{4}{x}$ (단, $x > 0$)입니다.\n\n산술-기하 평균 부등식을 적용하면:\n\n$$x + \\dfrac{4}{x} \\geq 2\\sqrt{x \\cdot \\dfrac{4}{x}}$$\n\n우변을 계산하면:\n\n$$2\\sqrt{x \\cdot \\dfrac{4}{x}} = 2\\sqrt{4} = 2 \\times 2 = 4$$\n\n따라서:\n\n$$f(x) = x + \\dfrac{4}{x} \\geq 4$$\n\n등호 조건을 확인하면, $x = \\dfrac{4}{x}$일 때 최솟값을 가집니다.\n\n$$x^2 = 4$$\n\n$x > 0$이므로 $x = 2$\n\n검증: $f(2) = 2 + \\dfrac{4}{2} = 2 + 2 = 4$ ✓\n\n따라서 최솟값은 **4**입니다.\n\n**[정답 확인]**\n산술-기하 평균 부등식을 적용하여 $f(x) \\geq 4$임을 보였고, $x=2$에서 등호가 성립하므로 최솟값은 4입니다.\n\n**[오답 분석]**\n- ① 2: $f(2) = 4$이지 2가 아닙니다. 산술-기하 평균 계산 오류.\n- ② 3: AM-GM 부등식 적용 시 $2\\sqrt{4} = 4$인데 3으로 잘못 계산한 경우.\n- ④ 5: 최솟값보다 큰 값으로, 특정 $x$값에서의 함숫값이지 최솟값이 아닙니다.\n- ⑤ 8: 상수항 4를 잘못 이해하여 오류가 발생한 경우.\n\n**[핵심 포인트]**\n$a + \\dfrac{k}{a}$ 형태의 함수는 산술-기하 평균 부등식으로 최솟값 $2\\sqrt{k}$를 가지며, $a = \\sqrt{k}$일 때 최솟값에 도달합니다.",
