    "answer": 25,
    "explanation": "**[핵심 개념]**\n직사각형의 둘레와 넓이의 관계를 이용한 최댓값 문제입니다. 둘레가 고정되어 있을 때, 직사각형의 넓이는 정사각형일 때 최대가 됩니다. 이는 산술-기하평균 부등식 또는 미분을 이용해 증명할 수 있습니다.\n\n**[풀이]**\n\n직사각형의 가로 길이를 $x$, 세로 길이를 $y$라고 하겠습니다.\n\n**1단계: 조건식 세우기**\n둘레의 길이가 20이므로:\n$$2(x+y) = 20$$\n$$x + y = 10$$\n\n**2단계: 넓이를 한 변수로 표현**\n넓이 $S = xy$이고, $y = 10-x$이므로:\n$$S(x) = x(10-x) = 10x - x^2$$\n\n**3단계: 최댓값 구하기 (미분 이용)**\n$$\\frac{dS}{dx} = 10 - 2x$$\n\n최댓값에서 $\\frac{dS}{dx} = 0$:\n$$10 - 2x = 0$$\n$$x = 5$$\n\n따라서 $y = 10 - 5 = 5$\n\n**4단계: 최댓값 계산**\n$$S_{max} = 5 \\times 5 = 25$$\n\n**다른 방법: 산술-기하평균 부등식**\n$$\\frac{x+y}{2} \\geq \\sqrt{xy}$$\n$$\\frac{10}{2} \\geq \\sqrt{xy}$$\n$$5 \\geq \\sqrt{xy}$$\n$$25 \\geq xy$$\n\n등호는 $x = y$일 때 성립하므로, $x = y = 5$일 때 최댓값 $xy = 25$\n\n**[정답 확인]**\n둘레가 고정된 직사각형에서 가로와 세로가 같은 정사각형(5×5)일 때 넓이가 최대이며, 그 값은 정확히 25입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으므로 일반적인 오류:\n- **24**: 4×6의 직사각형으로 계산한 경우 (둘레 조건은 맞지만 최댓값 아님)\n- **20**: 둘레를 넓이로 잘못 계산한 경우\n- **50**: 계산 실수로 $10 \\times 5$를 두 번 곱한 경우\n\n**[핵심 포인트]**\n둘레가 고정되어 있을 때, 직사각형의 넓이는 **정사각형일 때 최대**입니다. 이는 $x=y=\\frac{\\text{둘레}}{4}$일 때 성립합니다.",
