    "answer": 1,
    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최솟값을 구하려면 다음 세 가지를 비교해야 합니다:\n1) 극값(극소값): $f'(x) = 0$을 만족하는 구간 내의 점\n2) 경계값: 구간의 양 끝점 $f(-2)$, $f(2)$\n\n4차 함수는 극값 판정을 위해 도함수를 이용합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^4 - 2x^2 + 3$$\n$$f'(x) = 4x^3 - 4x = 4x(x^2 - 1) = 4x(x-1)(x+1)$$\n\n**Step 2: 극값의 위치 찾기**\n$f'(x) = 0$일 때:\n$$4x(x-1)(x+1) = 0$$\n$$x = -1, 0, 1$$\n\n모두 $[-2, 2]$ 구간 내에 있습니다.\n\n**Step 3: 각 극값과 경계값 계산**\n\n$f(-2) = (-2)^4 - 2(-2)^2 + 3 = 16 - 8 + 3 = 11$\n\n$f(-1) = (-1)^4 - 2(-1)^2 + 3 = 1 - 2 + 3 = 2$\n\n$f(0) = 0^4 - 2(0)^2 + 3 = 3$\n\n$f(1) = 1^4 - 2(1)^2 + 3 = 1 - 2 + 3 = 2$\n\n$f(2) = 2^4 - 2(2)^2 + 3 = 16 - 8 + 3 = 11$\n\n**Step 4: 최솟값 비교**\n계산한 값들: $11, 2, 3, 2, 11$\n\n따라서 최솟값은 $\\boxed{2}$입니다.\n\n**[정답 확인]**\n$x = -1, 1$에서 함수값이 2로 가장 작으며, 이는 극소값이자 구간 $[-2, 2]$에서의 최솟값입니다.\n\n**[오답 분석]**\n- ① 1: 함수값 중 1은 나타나지 않음\n- ③ 3: $f(0) = 3$이지만 이는 극대값이므로 최솟값이 아님\n- ④ 4: 계산 오류로 인한 선택\n- ⑤ 5: 계산 오류로 인한 선택\n\n**[핵심 포인트]**\n폐구간 $[a, b]$에서 최솟값은 **극값의 후보점과 경계점 모두를 비교**해야 하며, 특히 4차 함수는 극대·극소가 모두 존재할 수 있으므로 주의깊게 확인해야 합니다.",
