    "problem": "양수 $x$에 대해 $f(x) = x + \\dfrac{9}{x}$의 최솟값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n\n이 문제는 산술-기하 평균 부등식(AM-GM Inequality)을 이용하는 최솟값 문제입니다. 양수 $a, b$에 대해 $\\frac{a+b}{2} \\geq \\sqrt{ab}$이며, 등호는 $a=b$일 때 성립합니다. 이를 변형하면 $a+b \\geq 2\\sqrt{ab}$입니다. 또한 미분을 이용한 풀이도 가능합니다.\n\n**[풀이]**\n\n**방법 1: 산술-기하 평균 부등식**\n\n$f(x) = x + \\dfrac{9}{x}$에서 $x > 0$이고 $\\dfrac{9}{x} > 0$입니다.\n\n산술-기하 평균 부등식을 적용하면:\n\n$$x + \\dfrac{9}{x} \\geq 2\\sqrt{x \\cdot \\dfrac{9}{x}} = 2\\sqrt{9} = 2 \\times 3 = 6$$\n\n등호 조건: $x = \\dfrac{9}{x}$\n\n$$x^2 = 9$$\n\n$x > 0$이므로 $x = 3$\n\n따라서 $x=3$일 때 최솟값은 $f(3) = 3 + \\dfrac{9}{3} = 3 + 3 = 6$\n\n**방법 2: 미분을 이용한 풀이**\n\n$$f'(x) = 1 - \\dfrac{9}{x^2}$$\n\n최솟값을 구하기 위해 $f'(x) = 0$:\n\n$$1 - \\dfrac{9}{x^2} = 0$$\n\n$$x^2 = 9$$\n\n$x > 0$이므로 $x = 3$\n\n2차 미분: $f''(x) = \\dfrac{18}{x^3} > 0$ (모든 $x > 0$에서)\n\n따라서 $x=3$에서 극솟값(=최솟값)을 가집니다.\n\n$$f(3) = 3 + \\dfrac{9}{3} = 6$$\n\n**[정답 확인]**\n\n$x=3$에서 산술-기하 평균 부등식의 등호 조건이 만족되므로 최솟값 6이 올바른 답입니다.\n\n**[오답 분석]**\n\n이 문제는 객관식이 아니라 단답형이므로 다른 오답이 나타날 수 있는 경우를 분석하면:\n- 계산 실수로 $x + \\dfrac{9}{x} = 12$ 등으로 잘못 계산하는 경우\n- $x=1, 2, 4$ 등 임의의 값을 대입하여 잘못된 답을 얻는 경우\n- 부등식 적용 시 $2\\sqrt{9} = 6$이 아닌 다른 값으로 계산하는 경우\n\n**[핵심 포인트]**\n\n- **산술-기하 평균 부등식**: $a + b \\geq 2\\sqrt{ab}$ (등호 조건: $a=b$)\n- $x + \\dfrac{k}{x}$ 형태의 함수는 $x = \\sqrt{k}$에서 최솟값 $2\\sqrt{k}$를 가집니다. (이 문제에서는 $k=9$이므로 최솟값은 $2\\sqrt{9}=6$)",
