    "problem": "함수 $f(x) = x^3 - 3x^2 - 9x + 2$의 극대점과 극소점의 $y$좌표의 차를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 32,
    "explanation": "**[핵심 개념]**\n극값(극대·극소)을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호 변화를 통해 극대/극소를 판단합니다. 극대점에서는 $f'(x)$가 양에서 음으로 변하고, 극소점에서는 음에서 양으로 변합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = x^3 - 3x^2 - 9x + 2$$\n$$f'(x) = 3x^2 - 6x - 9$$\n\n**2단계: 극값을 갖는 점 찾기**\n$f'(x) = 0$을 풀면:\n$$3x^2 - 6x - 9 = 0$$\n$$x^2 - 2x - 3 = 0$$\n$$(x - 3)(x + 1) = 0$$\n$$x = 3 \\text{ 또는 } x = -1$$\n\n**3단계: 극대·극소 판정**\n$f'(x) = 3(x-3)(x+1)$이므로:\n- $x < -1$: $f'(x) > 0$ (증가)\n- $-1 < x < 3$: $f'(x) < 0$ (감소)\n- $x > 3$: $f'(x) > 0$ (증가)\n\n따라서:\n- $x = -1$에서 극대\n- $x = 3$에서 극소\n\n**4단계: 극값 구하기**\n\n극대값 (at $x = -1$):\n$$f(-1) = (-1)^3 - 3(-1)^2 - 9(-1) + 2$$\n$$= -1 - 3 + 9 + 2 = 7$$\n\n극소값 (at $x = 3$):\n$$f(3) = 3^3 - 3(3)^2 - 9(3) + 2$$\n$$= 27 - 27 - 27 + 2 = -25$$\n\n**5단계: 극값의 차 구하기**\n$$\\text{극대값} - \\text{극소값} = 7 - (-25) = 7 + 25 = 32$$\n\n**[정답 확인]**\n극대값 7에서 극소값 -25를 빼면 32이므로, 정답은 **32**입니다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 오류:\n- $f'(x) = 0$을 잘못 푸는 경우: 근의 공식 실수로 $x = -1, 3$ 외의 값을 구함\n- 극대·극소를 반대로 판정하는 경우: 도함수의 부호 변화를 정확히 확인해야 함\n- 함수값 계산 오류: $f(-1)$ 또는 $f(3)$ 계산 실수\n\n**[핵심 포인트]**\n1. 도함수의 부호 변화를 통해 극대/극소를 정확히 판정하는 것이 중요합니다.\n2. 극값의 차를 구할 때는 (극대값) - (극소값) 순서를 명확히 하여 양수 답을 얻어야 합니다.",
