    "explanation": "**[핵심 개념]**\n두 점 사이의 거리 공식과 함수의 최솟값을 구하는 미분을 이용합니다. 점 $(x_1, y_1)$과 $(x_2, y_2)$ 사이의 거리는 $\\sqrt{(x_2-x_1)^2 + (y_2-y_1)^2}$이고, 거리의 제곱은 루트를 제거하여 계산을 단순화할 수 있습니다. 함수의 최솟값은 도함수가 0이 되는 점에서 찾습니다.\n\n**[풀이]**\n\n곡선 위의 점 $(t, t^3)$과 점 $(2, 0)$ 사이의 거리의 제곱을 구하면:\n\n$$D(t) = (t-2)^2 + (t^3-0)^2 = (t-2)^2 + t^6$$\n\n전개하면:\n$$D(t) = t^2 - 4t + 4 + t^6$$\n\n$D(t)$의 최솟값을 구하기 위해 $t$로 미분합니다:\n\n$$D'(t) = 2t - 4 + 6t^5 = 6t^5 + 2t - 4$$\n\n최솟값에서 $D'(t) = 0$이므로:\n$$6t^5 + 2t - 4 = 0$$\n\n양변을 2로 나누면:\n$$3t^5 + t - 2 = 0$$\n\n각 선택지를 대입하여 확인합니다.\n\n$t = 1$일 때:\n$$3(1)^5 + 1 - 2 = 3 + 1 - 2 = 0$$ ✓\n\n따라서 $t = 1$에서 $D'(t) = 0$입니다.\n\n이것이 최솟값인지 확인하기 위해 2차 도함수를 구합니다:\n$$D''(t) = 30t^4 + 2$$\n\n$t = 1$에서:\n$$D''(1) = 30(1)^4 + 2 = 32 > 0$$\n\n2차 도함수가 양수이므로 $t = 1$에서 최솟값을 가집니다.\n\n**[정답 확인]**\n$3t^5 + t - 2 = 0$에 $t = 1$을 대입하면 정확히 0이 되고, $D''(1) > 0$이므로 최솟값입니다.\n\n**[오답 분석]**\n- ① $t=0$: $D'(0) = -4 \\neq 0$ (극값 아님)\n- ② $t=\\frac{1}{2}$: $3(\\frac{1}{32}) + \\frac{1}{2} - 2 = \\frac{3}{32} - \\frac{3}{2} \\neq 0$\n- ④ $t=\\frac{3}{2}$: $3(\\frac{243}{32}) + \\frac{3}{2} - 2 \\neq 0$\n- ⑤ $t=2$: $D'(2) = 6(32) + 4 - 4 = 192 \\neq 0$\n\n**[핵심 포인트]**\n거리의 제곱으로 설정하면 루트를 제거하여 미분이 쉬워집니다. 도함수 = 0의 방정식을 풀 때는 각 선택지를 대입하여 검증하는 것이 효율적입니다.",
