    "answer": 3,
    "explanation": "**[핵심 개념]**\n절댓값 함수의 최댓값을 구하기 위해서는:\n1. 절댓값 내부의 식을 0으로 만드는 점들을 찾기\n2. 절댓값을 제거하여 구간별 함수 표현하기\n3. 구간 내 모든 임계점과 끝점에서의 함수값을 비교하기\n\n**[풀이]**\n\n**Step 1: 절댓값 내부식 분석**\n\n$x^2 - 4x + 3 = (x-1)(x-3)$ 로 인수분해됩니다.\n\n$x^2 - 4x + 3 = 0$일 때, $x = 1$ 또는 $x = 3$\n\n**Step 2: 구간별 함수 표현**\n\n구간 $[0, 5]$에서 절댓값 내부식의 부호를 파악하면:\n- $x \\in [0, 1]$: $x^2 - 4x + 3 \\geq 0$ → $f(x) = x^2 - 4x + 3$\n- $x \\in [1, 3]$: $x^2 - 4x + 3 \\leq 0$ → $f(x) = -(x^2 - 4x + 3) = -x^2 + 4x - 3$\n- $x \\in [3, 5]$: $x^2 - 4x + 3 \\geq 0$ → $f(x) = x^2 - 4x + 3$\n\n**Step 3: 각 구간에서 최댓값 구하기**\n\n**구간 $[0, 1]$:** $f(x) = x^2 - 4x + 3$\n- 도함수: $f'(x) = 2x - 4 < 0$ (이 구간에서)\n- 감소함수이므로 최댓값은 $x=0$에서: $f(0) = 3$\n\n**구간 $[1, 3]$:** $f(x) = -x^2 + 4x - 3$\n- 도함수: $f'(x) = -2x + 4 = 0$ → $x = 2$\n- $x = 2$에서: $f(2) = -(4) + 8 - 3 = 1$\n- 끝점: $f(1) = 0$, $f(3) = 0$\n- 이 구간에서 최댓값은 $f(2) = 1$\n\n**구간 $[3, 5]$:** $f(x) = x^2 - 4x + 3$\n- 도함수: $f'(x) = 2x - 4 > 0$ (이 구간에서)\n- 증가함수이므로 최댓값은 $x=5$에서: $f(5) = 25 - 20 + 3 = 8$\n\n**Step 4: 전체 최댓값**\n\n모든 임계점과 끝점에서의 함수값:\n- $f(0) = 3$\n- $f(1) = 0$\n- $f(2) = 1$\n- $f(3) = 0$\n- $f(5) = 8$\n\n따라서 구간 $[0, 5]$에서의 최댓값은 $\\boxed{8}$\n\n**[정답 확인]**\n구간 끝점 $x=5$에서 절댓값 내부식이 최대값을 가지며, 이때 $f(5) = |25-20+3| = 8$입니다.\n\n**[오답 분석]**\n- ① 1: 구간 $[1,3]$ 내부에서의 최댓값이지만, 전체 구간에서의 최댓값이 아님\n- ② 3: 구간 시작점 $x=0$에서의 함수값이지만, 전체 최댓값이 아님\n- ③ 4: 계산 오류로 인한 선택지 (절댓값 내부 최댓값과 혼동)\n- ⑤ 10: 끝점에서의 계산 실수\n\n**[핵심 포인트]**\n절댓값 함수의 최댓값은 절댓값을 제거한 후 각 구간별로 함수를 분석하고, 모든 임계점(도함수=0인 점)과 구간 끝점에서의 함수값을 비교하여 구합니다.",
