    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최솟값을 구하기 위해서는 다음 세 가지를 비교해야 합니다:\n1. 구간 내 극값 (도함수 = 0인 점)\n2. 구간의 양 끝점에서의 함수값\n\n미분을 이용하여 극값을 찾고, 모든 후보 중에서 최솟값을 결정합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f(x) = 3x^4 - 4x^3$$\n\n$$f'(x) = 12x^3 - 12x^2 = 12x^2(x-1)$$\n\n**2단계: 극값 찾기 (임계점)**\n\n$f'(x) = 0$에서:\n$$12x^2(x-1) = 0$$\n\n따라서 $x = 0$ 또는 $x = 1$\n\n**3단계: 이계 도함수로 극값 판정 (선택사항)**\n\n$$f''(x) = 36x^2 - 24x = 12x(3x-2)$$\n\n- $f''(0) = 0$ (판정 불가, 하지만 $x=0$ 전후로 $f'(x)$의 부호가 바뀌지 않음)\n- $f''(1) = 36 - 24 = 12 > 0$ (극소)\n\n**4단계: 구간 $[-1, 2]$에서 함수값 계산**\n\n구간의 끝점과 극값 후보점에서 함수값을 구합니다:\n\n- $f(-1) = 3(-1)^4 - 4(-1)^3 = 3 \\cdot 1 - 4 \\cdot (-1) = 3 + 4 = 7$\n\n- $f(0) = 3(0)^4 - 4(0)^3 = 0$\n\n- $f(1) = 3(1)^4 - 4(1)^3 = 3 - 4 = -1$\n\n- $f(2) = 3(2)^4 - 4(2)^3 = 3 \\cdot 16 - 4 \\cdot 8 = 48 - 32 = 16$\n\n**5단계: 최솟값 결정**\n\n$$\\min\\{7, 0, -1, 16\\} = -1$$\n\n구간 $[-1, 2]$에서의 최솟값은 $\\boxed{-1}$이며, 이는 $x=1$에서 달성됩니다.\n\n**[정답 확인]**\n네 개의 후보값 중 $f(1) = -1$이 가장 작으므로 최솟값은 -1입니다.\n\n**[오답 분석]**\n- **0**: $f(0) = 0$을 선택한 경우, 극값을 찾았지만 모든 후보를 비교하지 않음\n- **7**: $f(-1) = 7$을 선택한 경우, 왼쪽 끝점의 값만 고려\n- **16**: $f(2) = 16$을 선택한 경우, 오른쪽 끝점의 값만 고려\n\n**[핵심 포인트]**\n폐구간에서 최솟값(최댓값)을 구할 때는 **반드시 극값과 끝점 모두**를 비교해야 합니다. 극값만 찾거나 끝점만 확인하면 오답이 나올 수 있습니다.",
