    "answer": 2,
    "explanation": "**[핵심 개념]**\n산술-기하 평균 부등식(AM-GM 부등식)을 이용하여 최댓값을 구하는 문제입니다. 제약 조건이 있을 때 특정 식의 최댓값을 구할 때는 AM-GM 부등식을 적용하되, 등호 조건을 만족하는 변수값을 찾아야 합니다.\n\n**[풀이]**\n\n**1단계: 조건 정리**\n주어진 조건: $x + y = 6$ (단, $x, y > 0$)\n목표: $xy^2$의 최댓값 구하기\n\n**2단계: AM-GM 부등식 적용**\n$xy^2$의 최댓값을 구하기 위해 $x + y + y = 6$으로 다시 쓸 수 있습니다.\n($y$를 두 번 더하는 이유는 $xy^2 = x \\cdot y \\cdot y$의 형태이기 때문)\n\nAM-GM 부등식을 적용하면:\n$$\\frac{x + y + y}{3} \\geq \\sqrt[3]{x \\cdot y \\cdot y}$$\n\n$$\\frac{6}{3} \\geq \\sqrt[3]{xy^2}$$\n\n$$2 \\geq \\sqrt[3]{xy^2}$$\n\n양변에 세제곱을 취하면:\n$$8 \\geq xy^2$$\n\n아, 이것은 최솟값입니다. 다시 접근하겠습니다.\n\n**2단계: 미분을 이용한 풀이 (권장)**\n$x + y = 6$에서 $x = 6 - y$\n\n$xy^2 = (6-y)y^2 = 6y^2 - y^3$\n\n$f(y) = 6y^2 - y^3$로 놓고 미분:\n$$f'(y) = 12y - 3y^2 = 3y(4 - y)$$\n\n$f'(y) = 0$일 때: $y = 0$ 또는 $y = 4$\n\n$y > 0$이므로 $y = 4$\n\n따라서 $x = 6 - 4 = 2$\n\n**3단계: 최댓값 계산**\n$$xy^2 = 2 \\cdot 4^2 = 2 \\cdot 16 = 32$$\n\n**4단계: 이계 도함수로 최댓값 확인**\n$$f''(y) = 12 - 6y$$\n$$f''(4) = 12 - 24 = -12 < 0$$\n\n따라서 $y = 4$에서 최댓값을 가집니다.\n\n**[정답 확인]**\n$x = 2, y = 4$일 때 $x + y = 6$을 만족하고, $xy^2 = 2 \\times 16 = 32$이므로 정답은 **③번**입니다.\n\n**[오답 분석]**\n- **①번 (16)**: $x = 4, y = 2$일 때의 $xy^2 = 4 \\times 4 = 16$ (변수 위치를 바꾼 경우)\n- **②번 (24)**: 계산 실수로 인한 오답\n- **④번 (36)**: $x = 6, y = 0$ 또는 다른 경계값에서의 값 (조건 위반)\n- **⑤번 (48)**: 과도하게 큰 값으로 선택한 오답\n\n**[핵심 포인트]**\n- 제약 조건 하에서 함수의 최댓값을 구할 때는 **미분을 이용**하여 임계점을 찾고, 이계 도함수로 최댓값 여부를 확인합니다.\n- AM-GM 부등식을 쓸 때는 **등호 조건**(모든 항이 같을 때)을 정확히 맞춰야 하므로, 이 경우는 미분법이 더 직관적입니다.",
