    "answer": -6,
    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최솟값을 구하기 위해서는 다음을 확인해야 합니다:\n1. 도함수를 구해 극값을 찾기\n2. 극값이 주어진 구간에 포함되는지 확인\n3. 구간의 끝점에서의 함수값과 구간 내 극값을 비교하여 최솟값 결정\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 - 3x^2 + a$$\n$$f'(x) = 3x^2 - 6x = 3x(x-2)$$\n\n**Step 2: 극값의 위치 찾기**\n$f'(x) = 0$일 때: $3x(x-2) = 0$\n$$x = 0 \\text{ 또는 } x = 2$$\n\n두 극값 모두 구간 $[-1, 4]$에 포함됩니다.\n\n**Step 3: 각 지점에서의 함수값 계산**\n\n$x = -1$일 때:\n$$f(-1) = (-1)^3 - 3(-1)^2 + a = -1 - 3 + a = -4 + a$$\n\n$x = 0$일 때:\n$$f(0) = 0 - 0 + a = a$$\n\n$x = 2$일 때:\n$$f(2) = 2^3 - 3(2)^2 + a = 8 - 12 + a = -4 + a$$\n\n$x = 4$일 때:\n$$f(4) = 4^3 - 3(4)^2 + a = 64 - 48 + a = 16 + a$$\n\n**Step 4: 최솟값 비교**\n\n극값들: $f(-1) = -4 + a$, $f(0) = a$, $f(2) = -4 + a$, $f(4) = 16 + a$\n\n$f'(x) = 3x(x-2)$의 부호:\n- $x < 0$: 양수 (증가)\n- $0 < x < 2$: 음수 (감소)\n- $x > 2$: 양수 (증가)\n\n따라서 $x=0$에서 극대, $x=2$에서 극소입니다.\n\n최솟값 후보는 $f(2) = -4 + a$입니다.\n\n**Step 5: 최솟값 조건 적용**\n\n최솟값이 $-10$이므로:\n$$-4 + a = -10$$\n$$a = -6$$\n\n**정답 확인**\n$a = -6$일 때, $f(2) = -4 + (-6) = -10$이고, 다른 모든 점에서의 값($f(-1) = -10$, $f(0) = -6$, $f(4) = 10$)과 비교하여 최솟값이 $-10$입니다.\n\n**[오답 분석]**\n선택지가 없으므로, 실수하기 쉬운 경우들:\n- 극값만 구하고 끝점을 확인하지 않는 경우\n- $f'(x) = 0$의 해를 잘못 구하는 경우\n- 극대와 극소를 헷갈리는 경우\n- $f(-1) = f(2) = -4 + a$임을 놓치는 경우\n\n**[핵심 포인트]**\n폐구간에서 최솟값은 반드시 **극값 또는 끝점에서의 함수값 중 하나**입니다. 극값을 구한 후 모든 후보값을 비교하는 것이 필수입니다.",
