    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호 변화를 조사하여 극대/극소를 판정합니다. 극대에서 극소로 변하거나 그 반대로 변할 때 극값을 가집니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 + ax^2$$\n$$f'(x) = 3x^2 + 2ax$$\n\n**Step 2: $x = -2$에서 극대 조건 이용**\n극값을 가지려면 $f'(x) = 0$이어야 하므로:\n$$f'(-2) = 3(-2)^2 + 2a(-2) = 0$$\n$$12 - 4a = 0$$\n$$a = 3$$\n\n**Step 3: $a = 3$일 때 극값의 위치 확인**\n$$f'(x) = 3x^2 + 6x = 3x(x+2)$$\n\n$f'(x) = 0$의 해: $x = 0$ 또는 $x = -2$\n\n**Step 4: 극대/극소 판정**\n$f'(x) = 3x(x+2)$의 부호를 조사:\n- $x < -2$: $f'(x) = 3(음수)(음수) > 0$ (증가)\n- $-2 < x < 0$: $f'(x) = 3(음수)(양수) < 0$ (감소)\n- $x > 0$: $f'(x) = 3(양수)(양수) > 0$ (증가)\n\n따라서 $x = -2$에서 극대, $x = 0$에서 극소입니다.\n\n**Step 5: 극솟값 계산**\n$$f(x) = x^3 + 3x^2$$\n$$f(0) = 0^3 + 3(0)^2 = 0$$\n\n**[정답 확인]**\n$x = 0$에서 도함수의 부호가 음에서 양으로 변하므로 극솟값이고, 그 값은 $f(0) = 0$입니다.\n\n**[오답 분석]**\n선택지가 없으므로 답이 0임을 확인하는 것이 목표입니다. 만약 다른 값을 선택했다면:\n- $f(-2) = -8 + 12 = 4$를 극솟값으로 착각한 경우\n- $x = -2$가 극소라고 잘못 판정한 경우\n\n**[핵심 포인트]**\n극값의 위치는 $f'(x) = 0$의 근이고, 극대/극소는 그 점 양쪽에서 도함수의 부호 변화로 판정합니다. 주어진 조건(극대 위치)에서 미지수 $a$를 먼저 결정하는 것이 핵심입니다.",
