    "type": "최대최소",
    "problem": "함수 $f(x) = x^3 - 6x^2 + 9x$의 구간 $[0, 5]$에서의 최댓값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 20,
    "explanation": "**[핵심 개념]**\n폐구간에서 함수의 최댓값을 구하기 위해서는 다음을 확인해야 합니다:\n1. 도함수를 구해 극값을 찾기 (극값이 존재하는 구간 내 점)\n2. 극값과 양 끝점의 함숫값을 모두 비교하기\n3. 이 중 가장 큰 값이 최댓값입니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f(x) = x^3 - 6x^2 + 9x$$\n\n$$f'(x) = 3x^2 - 12x + 9$$\n\n**Step 2: 극값 찾기**\n\n$f'(x) = 0$을 풀어봅시다.\n\n$$3x^2 - 12x + 9 = 0$$\n\n$$x^2 - 4x + 3 = 0$$\n\n$$(x-1)(x-3) = 0$$\n\n따라서 $x = 1$ 또는 $x = 3$\n\n두 값 모두 구간 $[0, 5]$에 포함됩니다.\n\n**Step 3: 이계 도함수로 극값의 성질 판정**\n\n$$f''(x) = 6x - 12$$\n\n- $f''(1) = 6 - 12 = -6 < 0$ → $x = 1$에서 극대\n- $f''(3) = 18 - 12 = 6 > 0$ → $x = 3$에서 극소\n\n**Step 4: 함숫값 계산**\n\n각 점에서의 함숫값을 구합니다:\n\n$$f(0) = 0 - 0 + 0 = 0$$\n\n$$f(1) = 1 - 6 + 9 = 4$$\n\n$$f(3) = 27 - 6(9) + 9(3) = 27 - 54 + 27 = 0$$\n\n$$f(5) = 125 - 6(25) + 9(5) = 125 - 150 + 45 = 20$$\n\n**Step 5: 최댓값 결정**\n\n비교: $f(0) = 0$, $f(1) = 4$, $f(3) = 0$, $f(5) = 20$\n\n따라서 최댓값은 $\\boxed{20}$입니다.\n\n**[정답 확인]**\n구간 $[0, 5]$에서 극값 $x=1, 3$과 양 끝점 $x=0, 5$의 함숫값을 모두 비교하면, $f(5) = 20$이 가장 크므로 최댓값은 20입니다.\n\n**[오답 분석]**\n- **4**: 극댓값 $f(1) = 4$를 최댓값으로 착각한 경우\n- **0**: 극솟값 $f(3) = 0$이나 끝점값 $f(0) = 0$을 최댓값으로 잘못 선택\n- **기타**: 계산 실수로 $f(5)$를 잘못 구한 경우\n\n**[핵심 포인트]**\n폐구간에서의 최댓값은 **극값과 끝점의 함숫값을 모두 비교**해야 합니다. 극댓값이 구간 전체의 최댓값은 아닐 수 있습니다.",
