    "type": "최대최소",
    "problem": "삼차함수 $f(x) = x^3 - 3x + a$가 서로 다른 세 실근을 가지기 위한 $a$의 범위에서 정수의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n삼차함수가 서로 다른 세 실근을 가지려면 극값을 가져야 하고, 극댓값과 극솟값이 서로 다른 부호를 가져야 합니다. 즉, $f'(x) = 0$에서 극값을 구한 후, 극댓값 × 극솟값 < 0 조건을 적용합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n$f'(x) = 0$에서 $x = -1$ 또는 $x = 1$\n\n**Step 2: 극값 판정**\n\n- $x < -1$일 때: $f'(x) > 0$ (증가)\n- $-1 < x < 1$일 때: $f'(x) < 0$ (감소)\n- $x > 1$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -1$에서 극댓값, $x = 1$에서 극솟값을 가집니다.\n\n**Step 3: 극값 계산**\n\n극댓값: $f(-1) = (-1)^3 - 3(-1) + a = -1 + 3 + a = 2 + a$\n\n극솟값: $f(1) = 1^3 - 3(1) + a = 1 - 3 + a = a - 2$\n\n**Step 4: 세 실근 조건**\n\n서로 다른 세 실근을 가지려면 극댓값과 극솟값이 서로 다른 부호여야 합니다.\n\n$$f(-1) \\cdot f(1) < 0$$\n\n$$(2+a)(a-2) < 0$$\n\n$$a^2 - 4 < 0$$\n\n$$(a-2)(a+2) < 0$$\n\n$$-2 < a < 2$$\n\n**Step 5: 정수의 개수**\n\n$-2 < a < 2$를 만족하는 정수는:\n\n$$a = -1, 0, 1$$\n\n따라서 정수의 개수는 **3개**입니다.\n\n**[정답 확인]**\n\n$a = -1, 0, 1$일 때 극댓값과 극솟값이 부호가 반대이므로 중간값 정리에 의해 정확히 세 개의 실근이 존재합니다.\n\n**[오답 분석]**\n\n- 극값 조건을 $f(-1) > 0$, $f(1) < 0$으로만 잘못 이해하면 부등호 방향을 놓칠 수 있습니다.\n- $a = -2$ 또는 $a = 2$를 포함하면 정수가 4개 또는 5개가 되는 오류를 범할 수 있습니다.\n- $a^2 - 4 < 0$을 $a^2 > 4$로 잘못 풀면 범위를 반대로 얻게 됩니다.\n\n**[핵심 포인트]**\n\n삼차함수가 세 실근을 가지는 조건은 **극댓값 × 극솟값 < 0**이며, 부등호 해때는 반드시 $a = \\pm 2$가 제외되어야 합니다(등호가 아니므로).",
