    "answer": 3,
    "explanation": "**[핵심 개념]**\n3차 함수의 실근 개수를 판정하기 위해서는 함수의 극값을 조사해야 합니다. $f(x) = x^3 - 3x + 1$이라 할 때, $f'(x) = 0$인 점에서의 극댓값과 극솟값의 부호를 확인하면 됩니다. 극댓값과 극솟값의 부호가 반대면 x축과 3번 만나 실근이 3개이고, 같은 부호면 x축과 1번만 만나 실근이 1개입니다.\n\n**[풀이]**\n\n$f(x) = x^3 - 3x + 1$이라 하겠습니다.\n\n**1단계: 도함수 구하기**\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n**2단계: 극값의 위치 찾기**\n$f'(x) = 0$일 때: $x = -1$ 또는 $x = 1$\n\n**3단계: 극값 계산**\n- $x = -1$일 때: $f(-1) = (-1)^3 - 3(-1) + 1 = -1 + 3 + 1 = 3$\n- $x = 1$일 때: $f(1) = 1^3 - 3(1) + 1 = 1 - 3 + 1 = -1$\n\n**4단계: 함수의 개형 파악**\n- $x < -1$: $f'(x) > 0$ (증가)\n- $-1 < x < 1$: $f'(x) < 0$ (감소)\n- $x > 1$: $f'(x) > 0$ (증가)\n\n따라서 $x = -1$에서 극댓값 $3$, $x = 1$에서 극솟값 $-1$을 가집니다.\n\n**5단계: 실근 개수 판정**\n- 극댓값: $f(-1) = 3 > 0$\n- 극솟값: $f(1) = -1 < 0$\n\n극댓값과 극솟값의 부호가 반대이고, 3차 함수는 $x \\to -\\infty$일 때 $-\\infty$로, $x \\to \\infty$일 때 $\\infty$로 가므로:\n- 첫 번째 근: $x < -1$ 구간에서 한 개\n- 두 번째 근: $-1 < x < 1$ 구간에서 한 개\n- 세 번째 근: $x > 1$ 구간에서 한 개\n\n따라서 서로 다른 실근이 **3개** 존재합니다.\n\n**[정답 확인]**\n극댓값과 극솟값의 부호가 반대(양수와 음수)이므로 3차 함수는 x축과 정확히 3번 만나 실근이 3개입니다.\n\n**[오답 분석]**\n- ① 0개: 3차 함수가 항상 어떤 실근을 가지므로 불가능\n- ② 1개: 극댓값과 극솟값이 같은 부호일 때만 가능 (이 문제에서는 부호가 반대)\n- ③ 2개: 3차 방정식은 1개 또는 3개의 실근을 가짐 (2개는 불가능)\n- ⑤ 알 수 없다: 극값 계산으로 확정 가능\n\n**[핵심 포인트]**\n3차 함수 $f(x) = ax^3 + \\cdots$의 극값에서 극댓값 × 극솟값 < 0이면 실근이 3개, > 0이면 실근이 1개입니다. 이 문제에서는 $3 \\times (-1) = -3 < 0$이므로 실근이 3개입니다.",
