    "problem": "방정식 $x^3 - 3x^2 + 4 = 0$의 실근 중 정수인 것을 모두 구하시오. 그 합은?",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n정수근을 찾기 위해 유리근 정리(Rational Root Theorem)를 사용합니다. 정수 계수를 가진 다항식 $a_nx^n + \\cdots + a_1x + a_0 = 0$의 정수근은 상수항 $a_0$의 약수여야 합니다. 따라서 $x^3 - 3x^2 + 4 = 0$의 정수근 후보는 $\\pm 1, \\pm 2, \\pm 4$입니다.\n\n**[풀이]**\n\n**1단계: 정수근 후보 찾기**\n상수항이 4이므로, 정수근 후보는 4의 약수: $\\pm 1, \\pm 2, \\pm 4$\n\n**2단계: 각 후보를 방정식에 대입**\n\n$x = 1$일 때:\n$$1^3 - 3(1)^2 + 4 = 1 - 3 + 4 = 2 \\neq 0$$\n\n$x = -1$일 때:\n$$(-1)^3 - 3(-1)^2 + 4 = -1 - 3 + 4 = 0 \\,\\checkmark$$\n\n$x = 2$일 때:\n$$2^3 - 3(2)^2 + 4 = 8 - 12 + 4 = 0 \\,\\checkmark$$\n\n$x = -2$일 때:\n$$(-2)^3 - 3(-2)^2 + 4 = -8 - 12 + 4 = -16 \\neq 0$$\n\n$x = 4$일 때:\n$$4^3 - 3(4)^2 + 4 = 64 - 48 + 4 = 20 \\neq 0$$\n\n$x = -4$일 때:\n$$(-4)^3 - 3(-4)^2 + 4 = -64 - 48 + 4 = -108 \\neq 0$$\n\n**3단계: 정수근 확인**\n정수근은 $x = -1$과 $x = 2$입니다.\n\n**4단계: 합 계산**\n$$(-1) + 2 = 1$$\n\n**[정답 확인]**\n$x = -1$과 $x = 2$를 원래 방정식에 대입하면 모두 0이 되므로, 정수근의 합은 $-1 + 2 = 1$입니다.\n\n**[오답 분석]**\n- **-1만 고르는 경우**: $x = 2$도 근이므로 불완전\n- **2만 고르는 경우**: $x = -1$도 근이므로 불완전\n- **다른 값들**: 유리근 정리를 적용하지 않고 임의로 선택한 경우\n\n**[핵심 포인트]**\n정수근을 찾을 때는 항상 **유리근 정리**를 사용하여 상수항의 약수만 확인하면 됩니다. 3개 이상의 근을 가질 수 있으므로 모든 후보를 체크해야 합니다.",
