    "explanation": "**[핵심 개념]**\n부등식을 풀기 위해서는 먼저 등식을 만족하는 근을 찾고, 인수분해하여 각 구간에서 식의 부호를 판정하는 부호 판정법(Sign Analysis)을 사용합니다. 3차 함수의 부호는 근의 개수와 위치에 따라 결정되며, $x \\to \\infty$일 때와 $x \\to -\\infty$일 때의 극한값을 고려하여 각 구간의 부호를 판정합니다.\n\n**[풀이]**\n\n**Step 1: 부등식 정리 및 근 찾기**\n\n$x^3 - 3x > 0$을 인수분해합니다.\n\n$$x^3 - 3x = x(x^2 - 3) = x(x-\\sqrt{3})(x+\\sqrt{3})$$\n\n따라서 부등식은 $x(x-\\sqrt{3})(x+\\sqrt{3}) > 0$\n\n**Step 2: 근 정리**\n\n이 식의 근은 $x = -\\sqrt{3}, 0, \\sqrt{3}$입니다.\n\n이들을 수직선에 표시하면: $-\\sqrt{3} < 0 < \\sqrt{3}$\n\n**Step 3: 부호 판정법 적용**\n\n각 구간에서 $x(x-\\sqrt{3})(x+\\sqrt{3})$의 부호를 판정합니다.\n\n| 구간 | $x < -\\sqrt{3}$ | $-\\sqrt{3} < x < 0$ | $0 < x < \\sqrt{3}$ | $x > \\sqrt{3}$ |\n|------|---|---|---|---|\n| $x$ | $-$ | $-$ | $+$ | $+$ |\n| $x+\\sqrt{3}$ | $-$ | $+$ | $+$ | $+$ |\n| $x-\\sqrt{3}$ | $-$ | $-$ | $-$ | $+$ |\n| 곱 | $-$ | $+$ | $-$ | $+$ |\n\n**Step 4: 해집합 결정**\n\n부등식 $x^3 - 3x > 0$의 해는 곱이 양수인 구간입니다.\n\n$$-\\sqrt{3} < x < 0 \\text{ 또는 } x > \\sqrt{3}$$\n\n**[정답 확인]**\n각 구간의 부호 판정 결과, 식이 양수인 구간은 $-\\sqrt{3} < x < 0$ 또는 $x > \\sqrt{3}$이므로 정답은 ②입니다.\n\n**[오답 분석]**\n\n① $x > \\sqrt{3}$: 부등식의 해의 일부만 포함하고, $-\\sqrt{3} < x < 0$ 구간을 누락했습니다.\n\n③ $x > 0$: $0 < x < \\sqrt{3}$ 구간에서 식의 값이 음수이므로 틀렸습니다. (검증: $x=1$일 때 $1-3=-2<0$)\n\n④ $0 < x < \\sqrt{3}$: 이 구간에서 식이 음수이므로 부등식을 만족하지 않습니다.\n\n⑤ $x < -\\sqrt{3}$ 또는 $0 < x < \\sqrt{3}$: $x < -\\sqrt{3}$ 구간에서 식이 음수이고, $0 < x < \\sqrt{3}$ 구간도 음수이므로 틀렸습니다.\n\n**[핵심 포인트]**\n- 3차 부등식은 인수분해 후 **부호 판정법**으로 각 구간의 부호를 확인하는 것이 핵심입니다.\n- 근이 $-\\sqrt{3}, 0, \\sqrt{3}$ 세 개일 때, 4개의 구간 각각에서 반드시 부호를 확인해야 합니다.",
