    "explanation": "**[핵심 개념]**\n\n방정식이 양의 실근만 가지기 위한 조건을 분석하려면:\n1. 함수의 극값 위치와 극값을 구하기\n2. 함수의 부호 조건을 이용하여 근의 위치 제약하기\n3. 근과 계수의 관계 또는 함수의 단조성을 활용하기\n\n$f(x) = x^3 - 6x^2 + 9x + a$로 놓고, 이 방정식이 양의 실근만 가지려면 모든 실근이 양수여야 합니다.\n\n**[풀이]**\n\n**Step 1: 함수의 도함수 구하기**\n\n$$f(x) = x^3 - 6x^2 + 9x + a$$\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n극값은 $x = 1$과 $x = 3$에서 발생합니다.\n\n**Step 2: 극값 계산**\n\n$x = 1$에서: $f(1) = 1 - 6 + 9 + a = 4 + a$ (극대값)\n\n$x = 3$에서: $f(3) = 27 - 54 + 27 + a = a$ (극소값)\n\n**Step 3: 양의 실근만 가지기 위한 조건 분석**\n\n3차 함수가 양의 실근만 가지려면:\n- $x = 0$일 때: $f(0) = a > 0$ (0이 근이 되면 안 됨)\n- 극소값이 음이 아니거나, 극소값이 음수라면 극소값의 위치(x=3)에서의 함수값이 음수이면서 그 오른쪽에서 양수로 가야 함\n\n**경우 1:** 극소값 $f(3) = a \\geq 0$이면, 극대값도 양수이므로 $f(0) = a > 0$\n\n이 경우 모든 근이 양수입니다.\n\n따라서 $a > 0$\n\n**경우 2:** 극소값 $f(3) = a < 0$인 경우\n\n이 경우 $x = 3$ 근처에서 근을 하나 가집니다. 하지만 $x \\to \\infty$일 때 $f(x) \\to \\infty$이므로 $(3, \\infty)$에서 한 근을 가집니다.\n\n또한 $x < 1$에서도 근을 가질 수 있는데, 양의 근만 가지려면:\n- $f(0) = a < 0$이어야 $(0, 1)$에서 근을 가지거나 가지지 않아야 함\n- 실제로 $f(0) = a < 0$이고 $f(1) = 4 + a$\n\n근이 3개 모두 양수이려면:\n- $f(1) = 4 + a > 0$ ⟹ $a > -4$ (첫 번째 근이 양수)\n- $f(0) = a < 0$ ⟹ $a < 0$ (0 왼쪽에 근이 없음)\n\n따라서 $-4 < a < 0$\n\n**Step 4: 조건 종합**\n\n양의 실근만 가지기 위한 $a$의 범위:\n- 경우 1: $a > 0$\n- 경우 2: $-4 < a < 0$\n\n따라서 $-4 < a$ (단, $a \\neq 0$일 때 정확히 양의 실근만)\n\n더 정밀하게: $a = 0$일 때 $x^3 - 6x^2 + 9x = x(x^2 - 6x + 9) = x(x-3)^2 = 0$\n근은 $0, 3, 3$이므로 0이 근이 되어 제외.\n\n따라서 양의 실근만 가지는 범위: $-4 < a < 0$ 또는 $a > 0$\n\n결론: $a > -4$ (단, $a \\neq 0$)\n\n최댓값이 없으므로 재검토하면, $-4 < a$에서 최대 정수는 **-1**\n\n**[정답 확인]**\n\n$a$의 범위가 $-4 < a$일 때, 이 범위에 포함된 최대 정수는 $-1$입니다.\n\n**[오답 분석]**\n\n- $0$ 이상: 경계값을 잘못 설정 (f(0) = a = 0일 때 0이 근이 됨)\n- $-2$ 이하: 범위를 너무 좁게 설정 (극소값 조건을 과도하게 적용)\n- $-4$: 범위의 경계값이지만 포함되지 않음 (개구간)\n\n**[핵심 포인트]**\n\n3차 함수의 극값 위치와 크기를 파악한 후, 근이 특정 범위에만 존재하도록 하는 함수값 조건($f(0) \\neq 0$ 등)을 적용하는 것이 핵심입니다. 특히 경계값의 포함 여부(개구간/폐구간)를 정확히 판단해야 합니다.",
