    "explanation": "**[핵심 개념]**\n3차 방정식을 정리할 때는 모든 항을 한쪽으로 이항하여 표준형으로 만든다. 3차 방정식 $ax^3 + bx^2 + cx + d = 0$의 모든 근을 $\\alpha, \\beta, \\gamma$라 하면, 비에타 공식에 의해 근과 계수의 관계는 $\\alpha \\beta \\gamma = -\\frac{d}{a}$이다.\n\n**[풀이]**\n\n주어진 방정식을 정리합니다.\n\n$$x^3 - 3x^2 = x - 3$$\n\n모든 항을 좌변으로 이항합니다.\n\n$$x^3 - 3x^2 - x + 3 = 0$$\n\n이 3차식을 인수분해합니다. 첫 두 항과 뒤의 두 항으로 묶으면:\n\n$$x^2(x - 3) - 1(x - 3) = 0$$\n\n공통인수 $(x-3)$으로 인수분해합니다.\n\n$$(x^2 - 1)(x - 3) = 0$$\n\n$x^2 - 1$을 다시 인수분해하면:\n\n$$(x-1)(x+1)(x-3) = 0$$\n\n따라서 세 근은 $x = 1, x = -1, x = 3$입니다.\n\n모든 실근의 곱은:\n\n$$1 \\times (-1) \\times 3 = -3$$\n\n**[정답 확인]**\n세 근 1, -1, 3의 곱이 -3이며, 비에타 공식 $-\\frac{d}{a} = -\\frac{3}{1} = -3$과도 일치한다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은:\n- 3: 절댓값만 계산한 경우\n- -1: 음수 근만 곱한 경우\n- 1: 양수 근만 곱한 경우\n\n**[핵심 포인트]**\n3차 방정식의 모든 근의 곱은 비에타 공식 $-\\frac{d}{a}$로 즉시 구할 수 있으므로, 근을 모두 구하지 않아도 답을 빠르게 얻을 수 있다. 다만 이 문제는 인수분해가 깔끔하므로 근을 직접 구하는 것도 효율적이다.",
