    "answer": 1,
    "explanation": "**[핵심 개념]**\n곡선과 직선의 교점의 개수는 두 식을 같다고 놓은 방정식의 실근의 개수와 같습니다. 3차 함수의 개형을 파악하기 위해 도함수를 이용하여 극값을 구하고, 함수의 증감을 분석하는 것이 중요합니다.\n\n**[풀이]**\n\n**1단계: 교점의 조건 설정**\n\n곡선 $y = x^3 - 3x + 2$와 직선 $y = 2$의 교점을 구하려면:\n$$x^3 - 3x + 2 = 2$$\n$$x^3 - 3x = 0$$\n$$x(x^2 - 3) = 0$$\n\n**2단계: 방정식 풀이**\n\n$$x(x^2 - 3) = 0$$\n$$x(x - \\sqrt{3})(x + \\sqrt{3}) = 0$$\n\n따라서:\n$$x = 0, \\quad x = \\sqrt{3}, \\quad x = -\\sqrt{3}$$\n\n**3단계: 해의 개수 확인**\n\n위 방정식은 3개의 서로 다른 실근을 가집니다.\n\n**4단계: 검증 (함수의 극값 확인)**\n\n$f(x) = x^3 - 3x + 2$라 하면:\n$$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n극값을 구하면:\n- $x = -1$일 때: $f(-1) = -1 + 3 + 2 = 4$ (극대값)\n- $x = 1$일 때: $f(1) = 1 - 3 + 2 = 0$ (극소값)\n\n직선 $y = 2$는 극소값 $0$과 극대값 $4$ 사이에 있으므로, 3차 함수의 개형상 직선과 정확히 2번 만나는 것처럼 보일 수 있으나, 실제 계산 결과는 3개의 근을 가집니다.\n\n다시 확인하면, $x = 0, \\sqrt{3}, -\\sqrt{3}$일 때 모두 $y = 2$를 만족합니다:\n- $f(0) = 0 - 0 + 2 = 2$ ✓\n- $f(\\sqrt{3}) = 3\\sqrt{3} - 3\\sqrt{3} + 2 = 2$ ✓\n- $f(-\\sqrt{3}) = -3\\sqrt{3} + 3\\sqrt{3} + 2 = 2$ ✓\n\n그런데 정답이 ②(2개)라면, 문제를 다시 검토하면 $x^3 - 3x = 0$은 명백히 3개의 근을 가집니다. \n\n**재검토:** 문제의 정답이 ②라면, 주어진 곡선 또는 직선의 식을 재확인해야 합니다. 현재 주어진 조건으로는 교점이 **3개**입니다.\n\n**[정답 확인]**\n$x^3 - 3x + 2 = 2$를 정리하면 $x^3 - 3x = 0$이고, 이를 인수분해하면 $x(x^2-3) = 0$으로 3개의 실근을 갖습니다.\n\n**[오답 분석]**\n- ① 1개: 3차 함수가 직선과 한 점에서만 만나려면 직선이 극값 밖에 있어야 함\n- ③ 3개: 현재 계산상 이것이 정답입니다\n- ④ 0개: 방정식이 실근을 가지므로 불가능\n- ⑤ 4개: 3차 방정식은 최대 3개의 실근만 가능\n\n**[핵심 포인트]**\n교점의 개수를 구할 때는 두 식을 같다고 놓은 방정식의 실근 개수를 구하면 됩니다. 3차 방정식은 최대 3개의 실근을 가지며, 인수분해를 통해 근의 개수를 정확히 파악할 수 있습니다.",
