    "explanation": "**[핵심 개념]**\n\n방정식 $f(x) = k$가 서로 다른 두 실근을 가진다는 것은 함수 $y = f(x)$의 그래프와 직선 $y = k$가 정확히 두 점에서 만난다는 의미입니다. 이를 판단하기 위해서는:\n1. 함수 $f(x) = x^3 - 3x^2 + 4$의 극값을 구해야 합니다.\n2. 함수의 극대값과 극소값을 찾고, 이들이 직선 $y = k$와 어떻게 만나는지 분석합니다.\n\n**[풀이]**\n\n**Step 1: 함수의 도함수 구하기**\n\n$f(x) = x^3 - 3x^2 + 4$에서\n\n$$f'(x) = 3x^2 - 6x = 3x(x-2)$$\n\n**Step 2: 극값의 위치 찾기**\n\n$f'(x) = 0$일 때: $x = 0$ 또는 $x = 2$\n\n- $x < 0$: $f'(x) > 0$ (증가)\n- $0 < x < 2$: $f'(x) < 0$ (감소)\n- $x > 2$: $f'(x) > 0$ (증가)\n\n따라서 $x = 0$에서 극대, $x = 2$에서 극소입니다.\n\n**Step 3: 극값 계산**\n\n극대값: $f(0) = 0 - 0 + 4 = 4$\n\n극소값: $f(2) = 8 - 12 + 4 = 0$\n\n**Step 4: 그래프 분석**\n\n$f(x)$의 개형:\n- $x = 0$에서 극대값 $4$\n- $x = 2$에서 극소값 $0$\n- $x \\to -\\infty$일 때 $f(x) \\to -\\infty$\n- $x \\to \\infty$일 때 $f(x) \\to \\infty$\n\n**Step 5: 두 개의 실근을 갖는 조건**\n\n직선 $y = k$가 곡선과 정확히 두 점에서 만나려면:\n- $k = 4$ (극대값): 극대점에서 한 번 접하고, 우측 증가 구간에서 한 번 더 만남\n- $k = 0$ (극소값): 극소점에서 한 번 접하고, 좌측 증가 구간에서 한 번 더 만남\n\n다른 경우들:\n- $0 < k < 4$: 세 개의 서로 다른 실근\n- $k > 4$ 또는 $k < 0$: 한 개의 실근\n\n따라서 **$k = 0$ 또는 $k = 4$**\n\n**[정답 확인]**\n\n$k = 0$ 또는 $k = 4$일 때만 직선이 곡선의 극값을 지나가면서 정확히 두 점에서 만나므로, 방정식이 서로 다른 두 실근을 갖습니다.\n\n**[오답 분석]**\n\n- ② $k = 0$만: $k = 4$일 때도 두 실근을 가짐\n- ③ $k = 4$만: $k = 0$일 때도 두 실근을 가짐\n- ④ $k = 2$: $0 < 2 < 4$이므로 세 개의 서로 다른 실근을 가짐\n- ⑤ $k = 0$ 또는 $k = 8$: $k = 8$일 때는 한 개의 실근만 가짐\n\n**[핵심 포인트]**\n\n3차 함수가 **정확히 2개의 서로 다른 실근**을 가지려면 직선이 극값을 지나야 합니다. 즉, $k$가 극대값 또는 극소값과 같아야 하는 경우를 찾아야 합니다.",
