    "type": "속도와 가속도",
    "problem": "직선 위를 움직이는 점의 시각 $t$에서의 위치가 $x(t) = t^3 - 6t^2 + 9t$일 때, $t = 1$에서의 속도를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n속도는 위치를 시간에 대해 미분한 것입니다. 즉, 위치 함수 $x(t)$가 주어졌을 때, 속도 함수는 $v(t) = \\frac{dx}{dt} = x'(t)$입니다. 특정 시각에서의 속도는 그 순간에 속도 함수의 값을 구하면 됩니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n위치 함수 $x(t) = t^3 - 6t^2 + 9t$를 $t$에 대해 미분하여 속도 함수를 구합니다.\n\n$$v(t) = \\frac{dx}{dt} = \\frac{d}{dt}(t^3 - 6t^2 + 9t)$$\n\n각 항을 미분하면:\n$$v(t) = 3t^2 - 12t + 9$$\n\n**2단계: $t=1$에서의 속도 구하기**\n\n속도 함수에 $t=1$을 대입합니다.\n\n$$v(1) = 3(1)^2 - 12(1) + 9$$\n$$v(1) = 3 - 12 + 9$$\n$$v(1) = 0$$\n\n**[정답 확인]**\n$t=1$에서 속도 함수값 $v(1) = 3 - 12 + 9 = 0$이므로, 정답은 **0**입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 일반적인 오답의 예:\n- $x(1) = 1 - 6 + 9 = 4$를 구한 경우: 위치와 속도를 혼동\n- $v(t) = 3t^2 - 12t + 9$에서 $t=0$을 대입하여 9를 구한 경우: 시각 $t=1$을 놓친 경우\n- 미분을 잘못 계산한 경우: 예를 들어 $v(t) = 3t^3 - 12t^2 + 9$로 계산\n\n**[핵심 포인트]**\n- 위치 함수를 미분하면 속도 함수를 얻습니다. 이는 미적분학의 가장 기본적이고 중요한 응용입니다.\n- $t=1$에서 속도가 0이라는 것은 그 순간 점이 움직이지 않고 있다는 의미이며, 이는 점의 운동 방향이 바뀌는 순간일 가능성이 있습니다.",
