    "answer": 2,
    "explanation": "**[핵심 개념]**\n위치 함수 $x(t)$에서 속도는 1차 도함수 $v(t) = x'(t)$이고, 가속도는 2차 도함수 $a(t) = x''(t)$입니다. 가속도가 0이 되는 시각을 구하려면 위치 함수를 두 번 미분하여 0이 되는 $t$값을 찾으면 됩니다.\n\n**[풀이]**\n\n**1단계: 속도 구하기 (1차 도함수)**\n\n주어진 위치함수: $x(t) = 2t^3 - 9t^2 + 12t + 1$\n\n속도는 위치의 1차 도함수이므로:\n$$v(t) = x'(t) = 6t^2 - 18t + 12$$\n\n**2단계: 가속도 구하기 (2차 도함수)**\n\n가속도는 속도의 도함수(위치의 2차 도함수)이므로:\n$$a(t) = v'(t) = x''(t) = 12t - 18$$\n\n**3단계: 가속도가 0인 시각 구하기**\n\n$a(t) = 0$이 되는 $t$를 구합니다:\n$$12t - 18 = 0$$\n\n$$12t = 18$$\n\n$$t = \\frac{18}{12} = \\frac{3}{2}$$\n\n**[정답 확인]**\n$t = \\frac{3}{2}$일 때 $a\\left(\\frac{3}{2}\\right) = 12 \\times \\frac{3}{2} - 18 = 18 - 18 = 0$ ✓\n\n**[오답 분석]**\n- ① $t = \\frac{1}{2}$: $a\\left(\\frac{1}{2}\\right) = 6 - 18 = -12 \\neq 0$\n- ② $t = 1$: $a(1) = 12 - 18 = -6 \\neq 0$\n- ④ $t = 2$: $a(2) = 24 - 18 = 6 \\neq 0$\n- ⑤ $t = 3$: $a(3) = 36 - 18 = 18 \\neq 0$\n\n**[핵심 포인트]**\n가속도가 0 ⟹ 2차 도함수 = 0. 미분을 정확히 두 번 수행하는 것이 핵심이며, 1차 도함수(속도)와 2차 도함수(가속도)를 혼동하지 않아야 합니다.",
