    "explanation": "**[핵심 개념]**\n점이 운동 방향을 바꾸는 시각은 속도가 0이 되는 시각입니다. 위치함수 $x(t)$가 주어졌을 때, 속도는 $v(t) = \\frac{dx}{dt}$이므로, 운동 방향을 바꾸는 시각은 $v(t) = 0$을 만족하는 $t$값입니다.\n\n**[풀이]**\n\n**Step 1: 속도함수 구하기**\n위치함수가 $x(t) = t^3 - 3t$이므로, 속도함수는:\n$$v(t) = \\frac{dx}{dt} = 3t^2 - 3$$\n\n**Step 2: 속도가 0이 되는 시각 찾기**\n운동 방향을 바꾸는 시각은 $v(t) = 0$일 때입니다:\n$$3t^2 - 3 = 0$$\n$$3(t^2 - 1) = 0$$\n$$t^2 = 1$$\n$$t = 1 \\text{ 또는 } t = -1$$\n\n**Step 3: 실제로 방향이 바뀌는지 확인**\n속도의 부호가 바뀌는지 확인해야 합니다.\n\n- $t < -1$일 때: $v(t) = 3(t^2 - 1) > 0$ (양수)\n- $-1 < t < 1$일 때: $v(t) = 3(t^2 - 1) < 0$ (음수)\n- $t > 1$일 때: $v(t) = 3(t^2 - 1) > 0$ (양수)\n\n따라서 $t = -1$과 $t = 1$에서 모두 운동 방향이 바뀝니다.\n\n**Step 4: 방향을 바꾸는 시각의 합**\n$$t_1 + t_2 = -1 + 1 = 0$$\n\n**[정답 확인]**\n속도가 0이 되는 두 시각 $t = -1$과 $t = 1$에서 모두 속도의 부호가 바뀌므로 운동 방향이 바뀌며, 이 두 시각의 합은 $0$입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으므로, 흔한 오답은 다음과 같습니다:\n- **1 또는 -1**: 하나의 시각만 구한 경우\n- **2**: 두 시각의 절댓값을 더한 경우\n- **$\\sqrt{3}$ 등**: 계산 실수로 다른 방정식을 푼 경우\n\n**[핵심 포인트]**\n1. 운동 방향의 변화는 속도가 0이 되고 부호가 바뀌는 지점에서 일어난다.\n2. 대칭적인 위치의 두 근이 주어진 경우, 근과 계수의 관계를 이용하면 빠르게 합을 구할 수 있다: $t = 1, -1$의 합은 항상 0이다.",
