    "problem": "위치 $x(t) = t^4 - 8t^2 + 16$인 점의 $t = 1$에서의 속력 $|v(1)|$을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 12,
    "explanation": "**[핵심 개념]**\n속도는 위치를 시간에 대해 미분한 값이고, 속력은 속도의 절댓값입니다.\n- 속도: $v(t) = \\frac{dx}{dt}$\n- 속력: $|v(t)| = |v(t)|$\n\n위치 함수가 주어졌을 때, 먼저 도함수를 구한 후 특정 시점에서의 속도를 구하고, 그 절댓값을 계산합니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n위치 함수 $x(t) = t^4 - 8t^2 + 16$을 $t$에 대해 미분하여 속도 함수를 구합니다.\n\n$$v(t) = \\frac{dx}{dt} = 4t^3 - 16t$$\n\n**2단계: $t=1$에서의 속도 구하기**\n\n$v(t) = 4t^3 - 16t$에 $t=1$을 대입합니다.\n\n$$v(1) = 4(1)^3 - 16(1) = 4 - 16 = -12$$\n\n**3단계: 속력 구하기**\n\n속력은 속도의 절댓값이므로:\n\n$$|v(1)| = |-12| = 12$$\n\n**[정답 확인]**\n$t=1$에서 속도가 $-12$이므로 속력은 그 절댓값인 $12$입니다.\n\n**[오답 분석]**\n선택지가 주어지지 않았으나, 흔한 오류는:\n- 속력을 구하지 않고 속도 값 $-12$를 답하는 경우\n- 미분을 잘못하여 계산 실수하는 경우\n- 절댓값 기호를 무시하는 경우\n\n**[핵심 포인트]**\n**속도와 속력의 차이**: 속도는 음수가 될 수 있지만, 속력은 항상 0 이상의 값입니다. 문제에서 \"속력\"을 명시했으므로 반드시 절댓값을 취해야 합니다.",
