    "answer": 0,
    "explanation": "**[핵심 개념]**\n위치 함수 $x(t)$에서:\n- 속도: $v(t) = \\frac{dx}{dt}$ (위치를 시간으로 미분)\n- 가속도: $a(t) = \\frac{dv}{dt}$ (속도를 시간으로 미분)\n\n속도와 가속도가 모두 양수라는 것은 $v(t) > 0$이고 $a(t) > 0$을 동시에 만족해야 함을 의미합니다.\n\n**[풀이]**\n\n**Step 1: 속도 구하기**\n\n주어진 위치함수 $x(t) = t^3 - 6t^2 + 9t + 2$를 미분하면:\n\n$$v(t) = \\frac{dx}{dt} = 3t^2 - 12t + 9 = 3(t^2 - 4t + 3) = 3(t-1)(t-3)$$\n\n**Step 2: 속도의 부호 결정**\n\n$v(t) = 3(t-1)(t-3) > 0$이 되는 범위:\n- $t < 1$일 때: $(-)(-) = (+)$ → $v > 0$\n- $1 < t < 3$일 때: $(+)(-) = (-)$ → $v < 0$\n- $t > 3$일 때: $(+)(+) = (+)$ → $v > 0$\n\n따라서 $v(t) > 0$ ⟹ $t < 1$ 또는 $t > 3$\n\n**Step 3: 가속도 구하기**\n\n속도를 다시 미분하면:\n\n$$a(t) = \\frac{dv}{dt} = 6t - 12 = 6(t-2)$$\n\n**Step 4: 가속도의 부호 결정**\n\n$a(t) = 6(t-2) > 0$이 되는 범위:\n- $t > 2$일 때: $a(t) > 0$\n\n**Step 5: 두 조건의 교집합**\n\n속도와 가속도가 모두 양수인 범위:\n- 조건 1: $v(t) > 0$ ⟹ $t < 1$ 또는 $t > 3$\n- 조건 2: $a(t) > 0$ ⟹ $t > 2$\n\n두 조건의 교집합: $(t < 1 \\text{ 또는 } t > 3) \\cap (t > 2) = t > 3$\n\n**[정답 확인]**\n$t > 3$일 때 $v(t) > 0$이고 $a(t) > 0$을 동시에 만족하므로 정답은 ①입니다.\n\n**[오답 분석]**\n\n**②** $t > 2$: 가속도는 양수이지만, $2 < t < 3$에서 속도가 음수이므로 틀림\n\n**③** $t > 1$: $1 < t < 3$에서 속도가 음수이고, $1 < t < 2$에서 가속도도 음수이므로 틀림\n\n**④** $0 < t < 1$: 이 구간에서 속도는 양수이지만 가속도는 음수 ($a < 0$)이므로 틀림\n\n**⑤** $t > 4$: 가속도 조건은 만족하지만 이는 ①의 부분집합이므로 가장 넓은 범위가 아님\n\n**[핵심 포인트]**\n- 속도와 가속도 조건을 각각 구한 후, 두 조건을 **동시에** 만족하는 교집합을 구하는 것이 핵심입니다.\n- 부호 판정은 인수분해 형태에서 수직선을 이용하여 각 구간별로 체계적으로 판단하세요.",
