    "explanation": "**[핵심 개념]**\n이차함수의 최댓값을 구하는 문제입니다. $f(t) = at^2 + bt + c$ 형태의 이차함수에서 $a < 0$일 때 최댓값은 꼭짓점에서 나타납니다. 꼭짓점의 $t$좌표는 $t = -\\frac{b}{2a}$이고, 이 값을 함수에 대입하면 최댓값을 구할 수 있습니다.\n\n**[풀이]**\n\n주어진 높이 함수: $h(t) = -5t^2 + 30t + 10$\n\n**Step 1: 함수의 형태 확인**\n- 이차함수 $h(t) = -5t^2 + 30t + 10$에서 $a = -5 < 0$\n- 따라서 아래로 볼록한 포물선이므로 최댓값이 존재합니다.\n\n**Step 2: 최댓값을 갖는 시간 $t$ 구하기**\n\n꼭짓점의 $t$좌표 공식: $t = -\\frac{b}{2a}$\n\n여기서 $a = -5$, $b = 30$이므로:\n\n$$t = -\\frac{30}{2 \\times (-5)} = -\\frac{30}{-10} = 3$$\n\n**Step 3: $t = 3$일 때 높이 계산**\n\n$$h(3) = -5(3)^2 + 30(3) + 10$$\n\n$$= -5 \\times 9 + 90 + 10$$\n\n$$= -45 + 90 + 10$$\n\n$$= 55 \\text{ (m)}$$\n\n**[정답 확인]**\n$t = 3$초일 때 물체의 높이가 55m으로 최대가 되므로, 최고 높이는 **55m**입니다.\n\n**[오답 분석]**\n- **45m**: $-45 + 90$만 계산하고 상수항 10을 빠뜨린 경우\n- **50m**: 계산 과정에서 산술 실수를 한 경우\n- **60m**: 최댓값 공식을 잘못 적용하거나 대입 시 부호 실수를 한 경우\n\n**[핵심 포인트]**\n이차함수 $f(t) = at^2 + bt + c$의 최댓값(또는 최솟값)은 **$t = -\\frac{b}{2a}$에서 발생**합니다. 이를 미분으로도 확인할 수 있습니다: $h'(t) = -10t + 30 = 0$에서 $t = 3$.",
