    "answer": 1,
    "explanation": "**[핵심 개념]**\n속도는 위치를 시간으로 미분한 값이며, 속도가 최소인 시각을 찾기 위해서는 속도 함수를 다시 미분하여 가속도를 구하고, 가속도가 0이 되는 점에서 속도의 극값을 판단해야 합니다.\n\n- 속도: $v(t) = \\frac{dx}{dt}$\n- 가속도: $a(t) = \\frac{dv}{dt} = \\frac{d^2x}{dt^2}$\n- 속도가 최소 ⟹ 가속도 = 0이고, 가속도가 음에서 양으로 변할 때\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n\n위치 함수를 $t$로 미분하여 속도를 구합니다.\n\n$$v(t) = \\frac{dx}{dt} = \\frac{d}{dt}(t^3 - 3t^2 - 9t + 5)$$\n\n$$v(t) = 3t^2 - 6t - 9$$\n\n**2단계: 가속도 함수 구하기**\n\n속도 함수를 $t$로 미분하여 가속도를 구합니다.\n\n$$a(t) = \\frac{dv}{dt} = \\frac{d}{dt}(3t^2 - 6t - 9)$$\n\n$$a(t) = 6t - 6$$\n\n**3단계: 가속도가 0인 시각 찾기**\n\n속도의 극값을 갖는 시각에서 가속도는 0입니다.\n\n$$a(t) = 0$$\n$$6t - 6 = 0$$\n$$t = 1$$\n\n**4단계: 속도가 최소인지 확인하기**\n\n$t = 1$ 전후에서 가속도의 부호 변화를 확인합니다.\n\n- $t < 1$일 때: $a(t) = 6t - 6 < 0$ (음수)\n- $t > 1$일 때: $a(t) = 6t - 6 > 0$ (양수)\n\n가속도가 음에서 양으로 변하므로, $t = 1$에서 속도는 **최솟값**을 갖습니다.\n\n**5단계: 검산**\n\n$t = 1$일 때의 속도값:\n$$v(1) = 3(1)^2 - 6(1) - 9 = 3 - 6 - 9 = -12$$\n\n근처 값과 비교:\n- $v(0) = 0 - 0 - 9 = -9 > -12$\n- $v(2) = 3(4) - 6(2) - 9 = 12 - 12 - 9 = -9 > -12$\n\n따라서 $t = 1$에서 속도가 최소입니다.\n\n**[정답 확인]**\n\n$t = 1$에서 가속도가 0이고 음에서 양으로 변하므로 속도가 최소입니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 일반적인 오답 패턴:\n- **$t = -1$**: 가속도 = $-12 \\neq 0$ (극값이 아님)\n- **$t = 3$**: 이 값에서는 $a(3) = 12 > 0$이므로 속도의 극값이 아님\n- **$t = 0$**: $a(0) = -6 \\neq 0$ (극값이 아님)\n\n**[핵심 포인트]**\n\n1. **속도의 극값은 가속도 = 0인 점**에서 나타나며, 부호 변화로 최대/최소를 판단합니다.\n2. 가속도가 **음 → 양으로 변하면 속도 최소**, **양 → 음으로 변하면 속도 최대**입니다.",
