    "answer": 1,
    "explanation": "**[핵심 개념]**\n점이 멈춘다는 것은 속도가 0이 된다는 의미입니다. 위치함수 $x(t)$의 도함수가 속도함수 $v(t) = \\frac{dx}{dt}$이므로, 점이 멈추는 시각은 $v(t) = 0$을 만족하는 시각입니다. \"처음으로 멈추는 시각\"은 $t > 0$인 범위에서 $v(t) = 0$을 만족하는 가장 작은 $t$ 값입니다.\n\n**[풀이]**\n**1단계: 속도함수 구하기**\n\n위치함수가 $x(t) = 2t^3 - 15t^2 + 36t$이므로, 속도함수는:\n$$v(t) = \\frac{dx}{dt} = 6t^2 - 30t + 36$$\n\n**2단계: 속도가 0이 되는 시각 찾기**\n\n점이 멈추는 시각은 $v(t) = 0$을 만족할 때입니다:\n$$6t^2 - 30t + 36 = 0$$\n\n양변을 6으로 나누면:\n$$t^2 - 5t + 6 = 0$$\n\n**3단계: 이차방정식 인수분해**\n\n$$t^2 - 5t + 6 = (t-2)(t-3) = 0$$\n\n따라서:\n$$t = 2 \\text{ 또는 } t = 3$$\n\n**4단계: 출발 후 처음으로 멈추는 시각**\n\n두 해 중에서 더 작은 값이 처음으로 멈추는 시각입니다:\n$$t = 2$$\n\n**[정답 확인]**\n$v(2) = 6(2)^2 - 30(2) + 36 = 24 - 60 + 36 = 0$이고, $t = 2$가 $v(t) = 0$의 두 해 중 더 작은 값이므로 출발 후 처음으로 멈추는 시각은 $t=2$입니다.\n\n**[오답 분석]**\n- ① $t=1$: $v(1) = 6 - 30 + 36 = 12 \\neq 0$ (속도가 0이 아님)\n- ③ $t=3$: $v(3) = 0$이지만, 이는 두 번째로 멈추는 시각 (처음이 아님)\n- ④ $t=4$: $v(4) = 6(16) - 30(4) + 36 = 96 - 120 + 36 = 12 \\neq 0$ (속도가 0이 아님)\n- ⑤ $t=5$: $v(5) = 6(25) - 30(5) + 36 = 150 - 150 + 36 = 36 \\neq 0$ (속도가 0이 아님)\n\n**[핵심 포인트]**\n- 점이 \"멈춘다\" = 속도 $v(t) = 0$ (위치가 0이 아님을 주의)\n- \"처음으로 멈추는 시각\" = $v(t) = 0$의 해 중 가장 작은 양수값",
