    "problem": "위치 $x(t) = t^3 - 3t^2 + 2$인 점에서 $t = 0$에서 $t = 2$까지의 평균 속도를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": -2,
    "explanation": "**[핵심 개념]**\n평균 속도는 일정한 시간 구간에서 위치 변화량을 시간 변화량으로 나눈 값입니다.\n\n$$\\text{평균 속도} = \\frac{\\Delta x}{\\Delta t} = \\frac{x(t_2) - x(t_1)}{t_2 - t_1}$$\n\n이는 위치-시간 그래프에서 두 점을 잇는 할선(secant line)의 기울기와 같습니다. 순간 속도(미분)와는 다른 개념입니다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 위치 함수: $x(t) = t^3 - 3t^2 + 2$\n- 시간 구간: $t = 0$에서 $t = 2$까지\n- 구하는 값: 평균 속도\n\n**2단계: 초기 위치 계산 ($t = 0$)**\n$$x(0) = 0^3 - 3(0)^2 + 2 = 2$$\n\n**3단계: 최종 위치 계산 ($t = 2$)**\n$$x(2) = 2^3 - 3(2)^2 + 2 = 8 - 12 + 2 = -2$$\n\n**4단계: 위치 변화량 계산**\n$$\\Delta x = x(2) - x(0) = -2 - 2 = -4$$\n\n**5단계: 시간 변화량**\n$$\\Delta t = 2 - 0 = 2$$\n\n**6단계: 평균 속도 계산**\n$$\\text{평균 속도} = \\frac{\\Delta x}{\\Delta t} = \\frac{-4}{2} = -2$$\n\n**[정답 확인]**\n$t = 0$에서 $t = 2$까지 점의 위치가 $2$에서 $-2$로 $4$만큼 감소했고, 이를 $2$초의 시간으로 나누면 평균 속도는 $-2$ m/s입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 실수는:\n- **0**: 순간 속도 $v(t) = 3t^2 - 6t$에서 $t=0$일 때의 값을 구한 경우\n- **-1**: 평균값을 구할 때 계산 실수\n- **2**: 부호를 무시한 경우\n- **-6**: $x(2)$의 값만 평균 속도로 착각한 경우\n\n**[핵심 포인트]**\n평균 속도는 **전체 위치 변화량을 전체 시간으로 나눈 값**이며, 이는 순간 속도(미분값)와 구별되어야 합니다. 음수 평균 속도는 입자가 음의 방향으로 이동함을 의미합니다.",
