    "explanation": "**[핵심 개념]**\n점의 위치를 나타내는 위치함수 $x(t)$에서 \"원점으로 돌아온다\"는 것은 $x(t) = 0$을 만족하는 시각을 찾는 것입니다. 이는 이차방정식을 풀어 근을 구하는 문제입니다.\n\n**[풀이]**\n점이 원점으로 돌아오려면 위치함수가 0이 되어야 합니다.\n\n$$x(t) = 0$$\n\n주어진 위치함수를 대입하면:\n$$4t - t^2 = 0$$\n\n좌변을 인수분해합니다:\n$$t(4 - t) = 0$$\n\n따라서:\n$$t = 0 \\text{ 또는 } t = 4$$\n\n$t = 0$일 때는 초기 위치(출발 시점)에서 원점에 있고, $t = 4$일 때는 점이 원점으로 **돌아오는** 시각입니다.\n\n문제에서 \"돌아오는 시각\"은 처음이 아닌 나중의 시각을 의미하므로:\n\n$$t = 4$$\n\n**[정답 확인]**\n$x(4) = 4(4) - 4^2 = 16 - 16 = 0$이므로 $t=4$일 때 점이 원점에 위치합니다.\n\n**[오답 분석]**\n- ① $t = 1$: $x(1) = 4(1) - 1^2 = 3 \\neq 0$ (원점 아님)\n- ② $t = 2$: $x(2) = 4(2) - 2^2 = 8 - 4 = 4 \\neq 0$ (원점 아님)\n- ③ $t = 3$: $x(3) = 4(3) - 3^2 = 12 - 9 = 3 \\neq 0$ (원점 아님)\n- ⑤ $t = 5$: $x(5) = 4(5) - 5^2 = 20 - 25 = -5 \\neq 0$ (원점 아님)\n\n**[핵심 포인트]**\n위치함수가 0이 되는 모든 시각을 구한 후, 초기 시점을 제외한 나중의 근을 선택해야 합니다. 인수분해를 통해 이차방정식의 두 근 중 구하는 값을 정확히 판단하세요.",
