    "explanation": "**[핵심 개념]**\n점이 운동 방향을 바꾼다는 것은 속도가 0이 되었다는 의미입니다. 위치함수 $x(t)$에서 속도는 $v(t) = \\frac{dx}{dt}$이므로, 운동 방향을 바꾸는 시점에서는 $v(t) = 0$이 됩니다. 따라서 주어진 시점에서 도함수 값이 0이 되는 조건을 이용합니다.\n\n**[풀이]**\n\n**1단계: 속도함수 구하기**\n\n위치함수 $x(t) = t^3 - at^2 + 4t$의 도함수(속도)를 구합니다.\n\n$$v(t) = \\frac{dx}{dt} = 3t^2 - 2at + 4$$\n\n**2단계: 운동 방향이 바뀌는 조건 적용**\n\n점이 $t = 2$에서 운동 방향을 바꾸므로, $t = 2$에서 속도가 0입니다.\n\n$$v(2) = 0$$\n\n**3단계: $t = 2$를 속도함수에 대입**\n\n$$3(2)^2 - 2a(2) + 4 = 0$$\n\n$$3 \\cdot 4 - 4a + 4 = 0$$\n\n$$12 - 4a + 4 = 0$$\n\n$$16 - 4a = 0$$\n\n$$4a = 16$$\n\n$$a = 4$$\n\n**[정답 확인]**\n\n$a = 4$일 때 $v(t) = 3t^2 - 8t + 4 = (3t-2)(t-2)$이므로 $t = 2$에서 속도가 0이 되어 운동 방향이 바뀝니다.\n\n**[오답 분석]**\n\n- ① $a = 2$: $v(2) = 12 - 8 + 4 = 8 \\neq 0$ (운동 방향 변화 없음)\n- ② $a = 3$: $v(2) = 12 - 12 + 4 = 4 \\neq 0$ (운동 방향 변화 없음)\n- ④ $a = 5$: $v(2) = 12 - 20 + 4 = -4 \\neq 0$ (운동 방향 변화 없음)\n- ⑤ $a = 6$: $v(2) = 12 - 24 + 4 = -8 \\neq 0$ (운동 방향 변화 없음)\n\n**[핵심 포인트]**\n\n운동 방향이 바뀐다 = 속도가 0이다 = $v(t) = \\frac{dx}{dt} = 0$\n\n이것이 이 문제의 핵심 해석입니다.",
