    "answer": 1,
    "explanation": "**[핵심 개념]**\n물체의 높이 함수가 주어졌을 때, 지면에 도달하는 시각은 $h(t) = 0$일 때이고, 속력은 속도의 절댓값입니다. 속도는 높이 함수를 시간으로 미분한 도함수 $v(t) = h'(t)$입니다.\n\n**[풀이]**\n\n**1단계: 지면에 도달하는 시각 구하기**\n\n물체가 지면에 도달할 때 높이는 0이므로:\n$$h(t) = -5t^2 + 20t = 0$$\n\n$$t(-5t + 20) = 0$$\n\n$$t = 0 \\text{ 또는 } t = 4$$\n\n$t = 0$은 출발 시각이고, $t = 4$가 지면에 도달하는 시각입니다.\n\n**2단계: 속도 함수 구하기**\n\n높이 함수를 시간으로 미분하여 속도를 구합니다:\n$$v(t) = h'(t) = \\frac{d}{dt}(-5t^2 + 20t) = -10t + 20$$\n\n**3단계: 지면 도달 시각의 속도 구하기**\n\n$t = 4$일 때 속도:\n$$v(4) = -10(4) + 20 = -40 + 20 = -20 \\text{ (m/s)}$$\n\n음수는 하강 방향을 의미합니다.\n\n**4단계: 속력 구하기**\n\n속력은 속도의 절댓값이므로:\n$$|v(4)| = |-20| = 20 \\text{ (m/s)}$$\n\n**5단계: 시각과 속력의 합**\n\n$$t + |v(t)| = 4 + 20 = 24$$\n\n**[정답 확인]**\n지면 도달 시각 4초에서의 속력 20 m/s의 합이 24이므로 정답은 ②입니다.\n\n**[오답 분석]**\n- ① 20: 속력만 계산한 경우\n- ③ 28: 계산 과정에서 실수 (예: 속도의 절댓값을 취하지 않음)\n- ④ 32: $t=4$와 속도 $-20$을 그대로 더한 경우 ($4 + (-20) = -16$이 아닌 다른 방식의 오류)\n- ⑤ 36: 초기 높이나 다른 값을 잘못 활용한 경우\n\n**[핵심 포인트]**\n- 지면 도달: $h(t) = 0$을 풀어 시각 구하기\n- 속력은 속도의 절댓값이므로 음수 부호 제거 필수",
