    "type": "속도와 가속도",
    "problem": "위치 $x(t) = t^4 - 4t^3$인 점의 $t > 0$에서 속도가 최소인 시각을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n- 속도는 위치를 시간으로 미분한 것: $v(t) = \\frac{dx}{dt}$\n- 속도가 최소/최대인 시각을 구하려면 속도 함수를 미분한 가속도 $a(t) = \\frac{dv}{dt}$를 이용\n- 속도의 극값은 $a(t) = 0$일 때 발생하며, 2계 도함수로 극소/극대를 판정\n\n**[풀이]**\n\n**Step 1: 속도 함수 구하기**\n\n위치 함수 $x(t) = t^4 - 4t^3$를 $t$에 대해 미분하면:\n\n$$v(t) = \\frac{dx}{dt} = 4t^3 - 12t^2$$\n\n**Step 2: 가속도 함수 구하기**\n\n속도 함수를 $t$에 대해 다시 미분하면:\n\n$$a(t) = \\frac{dv}{dt} = 12t^2 - 24t = 12t(t - 2)$$\n\n**Step 3: 속도가 극값을 갖는 시각 찾기**\n\n$a(t) = 0$일 때:\n$$12t(t - 2) = 0$$\n$$t = 0 \\text{ 또는 } t = 2$$\n\n$t > 0$이므로 $t = 2$만 해당\n\n**Step 4: 극소인지 극대인지 판정**\n\n2계 도함수를 이용하거나 $a(t)$의 부호 변화를 확인:\n\n- $0 < t < 2$일 때: $a(t) = 12t(t-2) < 0$ (음수)\n- $t > 2$일 때: $a(t) = 12t(t-2) > 0$ (양수)\n\n$a(t)$가 음에서 양으로 변하므로 $t = 2$에서 $v(t)$는 **극소값**을 가짐\n\n**Step 5: 속도값 확인**\n\n$$v(2) = 4(2)^3 - 12(2)^2 = 32 - 48 = -16$$\n\n**[정답 확인]**\n$t = 2$에서 가속도가 음에서 양으로 변하므로 속도가 최솟값을 가지므로 정답은 **2**\n\n**[오답 분석]**\n- 선지가 제시되지 않았으나, $v(t) = 0$인 점인 $t = 0, 3$을 고르는 실수가 가능\n- $a(t) = 0$의 다른 해인 $t = 0$을 선택하면 안 됨 ($t > 0$이고, $t=0$에서는 극값이 아님)\n\n**[핵심 포인트]**\n- 속도의 극값 위치는 가속도가 0인 지점에서 찾고, 가속도의 부호 변화로 극소/극대를 판정\n- \"최소\"라는 조건에서 극소값을 찾는 것이 중요하며, 이는 $a(t)$의 음→양 변화로 확인",
