    "problem": "위치 $x(t) = t^3 - 6t^2 + 9t$인 점의 $t = 0$에서 $t = 4$까지의 변위(displacement)를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n변위(displacement)는 시작점과 끝점의 위치 차이로, $x(t_f) - x(t_i)$ 형태로 구합니다. 변위는 이동 거리와 다르게 방향을 고려한 순 이동량입니다. 움직임의 과정 중 방향이 바뀌더라도, 최종 위치에서 초기 위치를 뺀 값이 변위입니다.\n\n**[풀이]**\n\n$t = 0$에서 $t = 4$까지의 변위를 구하기 위해, 각 시점의 위치값을 계산합니다.\n\n$x(t) = t^3 - 6t^2 + 9t$\n\n**$t = 0$일 때:**\n$$x(0) = 0^3 - 6(0)^2 + 9(0) = 0$$\n\n**$t = 4$일 때:**\n$$x(4) = 4^3 - 6(4)^2 + 9(4)$$\n$$= 64 - 6 \\times 16 + 36$$\n$$= 64 - 96 + 36$$\n$$= 4$$\n\n**변위 계산:**\n$$\\text{변위} = x(4) - x(0) = 4 - 0 = 4$$\n\n**[정답 확인]**\n\n$t=0$에서의 위치가 0, $t=4$에서의 위치가 4이므로, 변위는 순수하게 4입니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오류는:\n- 변위 대신 이동 거리를 구하는 경우: 속도가 0이 되는 점($t=1, t=3$)을 찾아 구간을 나누어 거리를 더할 때 다른 값이 나옴\n- 계산 실수: $x(4)$ 계산에서 음수 부호를 잘못 처리하는 경우\n\n**[핵심 포인트]**\n\n**변위는 단순히 최종 위치 - 초기 위치이며, 중간에 방향이 바뀌어도 상관없습니다.** 변위와 이동거리는 서로 다른 개념이므로 문제에서 명시한 \"변위\"를 구해야 합니다.",
