    "answer": 2,
    "explanation": "**[핵심 개념]**\n점이 원점을 지나간다는 것은 위치 $x(t) = 0$이 되는 시각을 찾는 것입니다. 주어진 위치 함수를 0으로 놓고 방정식을 풀어서 $t > 0$인 모든 해를 구한 후, 그 합을 구하는 문제입니다.\n\n**[풀이]**\n\n점이 원점을 지나갈 조건은 $x(t) = 0$입니다.\n\n$$x(t) = t^3 - 3t^2 + 2t = 0$$\n\n공통인수 $t$로 인수분해합니다:\n\n$$t(t^2 - 3t + 2) = 0$$\n\n이차식을 인수분해합니다:\n\n$$t(t - 1)(t - 2) = 0$$\n\n따라서 해는:\n$$t = 0, \\quad t = 1, \\quad t = 2$$\n\n문제에서 $t > 0$인 시각만 구하므로, $t = 0$은 제외합니다.\n\n$$t > 0 \\text{인 시각: } t = 1, \\quad t = 2$$\n\n따라서 구하는 합은:\n\n$$1 + 2 = 3$$\n\n**[정답 확인]**\n$t > 0$ 범위에서 원점을 지나는 시각은 $t = 1$과 $t = 2$이고, 이들의 합은 3입니다.\n\n**[오답 분석]**\n- ① 1: 한 개의 시각($t=1$)만 더한 경우\n- ② 2: 한 개의 시각($t=2$)만 더한 경우 또는 계산 실수\n- ④ 4: $t = 0$을 포함하여 $0 + 1 + 2 = 3$이 아닌 $1 + 2 + 1 = 4$로 잘못 계산한 경우\n- ⑤ 5: $t = 0$을 포함하여 모두 더한 경우 ($0 + 1 + 2 = 3$이므로 틀림) 또는 다른 계산 실수\n\n**[핵심 포인트]**\n- 위치가 0이 되는 조건 $x(t) = 0$을 세우고 인수분해하여 모든 근을 구합니다.\n- 문제의 범위 조건 **$t > 0$을 반드시 확인**하여 제외할 해($t=0$)를 빼야 합니다.",
