    "type": "킬러",
    "problem": "최고차항의 계수가 1인 삼차함수 $f(x)$가 $f'(1) = 0$, $f'(3) = 0$이고 $f(1) - f(3) = 4$일 때, $f(0)$의 값을 구하시오.",
    "answerType": "short",
