    "answer": 2,
    "explanation": "**[핵심 개념]**\n절댓값 함수 $|g(x)|$가 미분불가능한 점은:\n1) $g(x) = 0$인 점에서 $g(x)$가 부호를 바꾸는 경우\n2) $g(x)$가 원래 미분불가능한 점\n\n절댓값 함수는 내부 함수가 0이 되는 점을 기준으로 부호가 바뀔 때, 그 점에서 좌미분과 우미분의 부호가 반대가 되어 미분불가능해진다.\n\n**[풀이]**\n\n**1단계: 내부 함수 분석**\n$f(x) = |x^3 - 3x|$에서 $g(x) = x^3 - 3x$로 놓자.\n\n$g(x) = x^3 - 3x = x(x^2 - 3) = x(x-\\sqrt{3})(x+\\sqrt{3})$\n\n$g(x) = 0$의 해: $x = -\\sqrt{3}, 0, \\sqrt{3}$\n\n**2단계: $g(x)$의 부호 결정**\n$g'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$\n\n부호 변화를 조사하면:\n- $x < -\\sqrt{3}$: $g(x) < 0$\n- $-\\sqrt{3} < x < 0$: $g(x) > 0$\n- $0 < x < \\sqrt{3}$: $g(x) < 0$\n- $x > \\sqrt{3}$: $g(x) > 0$\n\n**3단계: $g(x) = 0$인 점에서의 미분가능성**\n\n각 영점 $x = -\\sqrt{3}, 0, \\sqrt{3}$에서 $g(x)$는 부호를 바꾸므로, $|g(x)|$는 이 세 점에서 모두 미분불가능하다.\n\n점 $(x_0, 0)$을 지나며 부호가 바뀌면, $|g(x)|$의 좌미분과 우미분이 반대 부호를 가지기 때문이다.\n\n**4단계: $g(x)$가 미분불가능한 점 확인**\n\n$g(x) = x^3 - 3x$는 다항식이므로 모든 점에서 미분가능하다.\n따라서 $f(x) = |g(x)|$가 미분불가능한 점은 $g(x) = 0$인 점뿐이다.\n\n**5단계: 결론**\n\n미분불가능한 점: $x = -\\sqrt{3}, 0, \\sqrt{3}$ → **3개**\n\n**[정답 확인]**\n절댓값 함수는 내부가 0이 되면서 부호를 바꾸는 점에서 미분불가능하고, $x^3 - 3x = 0$의 해가 정확히 3개이므로 답은 ③이다.\n\n**[오답 분석]**\n- ① 1개: $g(x) = 0$의 해를 1개만 센 경우\n- ② 2개: $g(x) = 0$의 해를 2개만 센 경우 (예: $x = 0, \\sqrt{3}$만)\n- ④ 4개: 극값점까지 포함시킨 경우 ($g'(x) = 0$인 $x = \\pm 1$을 실수로 더한 경우)\n- ⑤ 5개: 영점과 극값점을 모두 센 경우\n\n**[핵심 포인트]**\n$|g(x)|$가 미분불가능한 점은 \"$g(x) = 0$이면서 부호가 바뀌는 점\"이다. 단순히 영점의 개수를 세되, 각 영점에서 실제로 부호 변화가 일어나는지 확인해야 한다.",
