    "type": "킬러",
    "problem": "함수 $f(x) = x^3 + ax^2 + bx + c$에 대해 $f(0) = 2$, $f'(0) = -3$, $f''(0) = 6$일 때, $a + b + c$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n주어진 함수의 조건들로부터 미지수를 구하기 위해 다음을 활용합니다.\n- $f(0)$: 함수에 $x=0$을 대입하면 상수항을 구할 수 있습니다.\n- $f'(x)$: 함수를 미분하여 1차 도함수를 구하고, $f'(0)$을 이용해 $b$를 구합니다.\n- $f''(x)$: 1차 도함수를 다시 미분하여 2차 도함수를 구하고, $f''(0)$을 이용해 $a$를 구합니다.\n\n**[풀이]**\n\n**Step 1: 주어진 함수와 도함수 구하기**\n\n$f(x) = x^3 + ax^2 + bx + c$\n\n1차 도함수:\n$$f'(x) = 3x^2 + 2ax + b$$\n\n2차 도함수:\n$$f''(x) = 6x + 2a$$\n\n**Step 2: 주어진 조건들로부터 계수 구하기**\n\n조건 1: $f(0) = 2$\n$$f(0) = 0 + 0 + 0 + c = 2$$\n$$\\therefore c = 2$$\n\n조건 2: $f'(0) = -3$\n$$f'(0) = 0 + 0 + b = -3$$\n$$\\therefore b = -3$$\n\n조건 3: $f''(0) = 6$\n$$f''(0) = 0 + 2a = 6$$\n$$\\therefore a = 3$$\n\n**Step 3: $a + b + c$ 계산**\n\n$$a + b + c = 3 + (-3) + 2 = 2$$\n\n**[정답 확인]**\n구한 계수들 $a=3, b=-3, c=2$를 원래 조건들에 대입하면 $f(0)=2, f'(0)=-3, f''(0)=6$을 모두 만족하므로 정답은 $2$입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 다음과 같은 실수가 가능합니다:\n- $a+b+c = 3-3+2 = 2$를 계산할 때 부호를 잘못 처리하면 다른 값이 나옵니다.\n- 각 조건을 적용할 때 도함수를 잘못 구하거나 $x=0$을 잘못 대입하면 계수값이 달라집니다.\n\n**[핵심 포인트]**\n- 함수값과 도함수 조건들은 계수를 직접 구하는 효율적인 방법입니다: $f(0) \\rightarrow c$, $f'(0) \\rightarrow b$, $f''(0) \\rightarrow a$\n- 다항함수에서 $x=0$을 대입하면 상수항 관련 정보를 빠르게 얻을 수 있습니다.",
