    "answer": 0,
    "explanation": "**[핵심 개념]**\n두 곡선의 교점은 두 식을 같다고 놓아 얻은 방정식의 해입니다. 곡선 $y = x^3 - 3x$와 직선 $y = mx$가 원점 이외의 두 점에서 만난다는 것은 교점 방정식이 $x = 0$을 중근으로 가지면서 다른 두 개의 실근을 가져야 한다는 의미입니다. 이차방정식이 서로 다른 두 실근을 가지는 조건은 판별식 $D > 0$입니다.\n\n**[풀이]**\n\n**1단계: 교점 방정식 세우기**\n\n곡선과 직선의 교점을 구하기 위해 두 식을 같다고 놓습니다:\n$$x^3 - 3x = mx$$\n\n**2단계: 방정식 정리하기**\n\n$$x^3 - 3x - mx = 0$$\n$$x^3 - (3+m)x = 0$$\n$$x(x^2 - (3+m)) = 0$$\n\n**3단계: 해 분석하기**\n\n이 방정식의 해는:\n- $x = 0$ (원점)\n- $x^2 - (3+m) = 0$에서 $x^2 = 3 + m$\n\n**4단계: 원점 이외의 두 점에서 만나는 조건**\n\n원점 이외의 두 점에서 만나려면, $x^2 = 3 + m$이 서로 다른 두 개의 실근을 가져야 합니다.\n\n$$x = \\pm\\sqrt{3+m}$$\n\n이 두 개의 실근이 존재하고 서로 다르려면:\n$$3 + m > 0$$\n$$m > -3$$\n\n**5단계: 문제 조건 재확인**\n\n문제에서 \"원점 이외의 두 점에서 만나기 위한 $m$의 범위를 구하면 $m < a$\"라고 했으므로, 이는 위 조건의 상한을 찾는 것입니다. \n\n$m > -3$은 $-3$보다 커야 한다는 조건이고, 이를 \"$m < a$\" 형태로 나타내면 $m$의 범위는 $-3 < m$이므로 $a = -3$입니다.\n\n**[정답 확인]**\n$m > -3$이므로 범위를 $m < a$ 형태로 쓰면 이의 여집합이 되는데, 문제에서 요구하는 원점 이외의 두 점에서 만나는 조건은 $m > -3$이고, 따라서 $a = -3$입니다.\n\n**[오답 분석]**\n- ② $-1$: $m > -3$의 범위 내에 포함되지만, 경계값이 아닙니다.\n- ③ $0$: 마찬가지로 경계값이 아닙니다.\n- ④ $1$: $m > -3$의 범위 내에서 충분히 큰 값이지만 경계값이 아닙니다.\n- ⑤ $3$: 경계값과 관계없는 임의의 값입니다.\n\n**[핵심 포인트]**\n두 곡선의 교점 개수를 구할 때는 교점 방정식을 인수분해하여 각 인수가 나타내는 근의 개수를 파악해야 합니다. 특히 원점을 지나는 곡선과 직선의 교점 문제에서는 $x$를 인수로 빼낸 후 나머지 방정식의 근의 조건을 분석하는 것이 효율적입니다.",
