    "answer": -1,
    "explanation": "**[핵심 개념]**\n- 함수의 극값: $f'(x) = 0$인 점에서 극대, 극소 판정\n- 같은 함수값을 갖는 두 점의 관계: $f(a) = f(b)$ (단, $a < b$)일 때, 이 두 점은 극값을 기준으로 대칭적 성질을 가짐\n- 제약조건이 있는 식의 최솟값: 라그랑주 승수법 또는 매개변수를 이용한 최솟값 탐색\n\n**[풀이]**\n\n**Step 1: 함수의 극값 찾기**\n\n$f(x) = x^3 - 3x^2 + 4$에서\n\n$$f'(x) = 3x^2 - 6x = 3x(x-2)$$\n\n$f'(x) = 0$일 때: $x = 0$ 또는 $x = 2$\n\n$$f(0) = 4, \\quad f(2) = 8 - 12 + 4 = 0$$\n\n따라서 $x = 0$에서 극대값 4, $x = 2$에서 극소값 0을 가짐\n\n**Step 2: $f(a) = f(b)$ 조건 분석** ($a < b$)\n\n$f(a) = f(b)$이면:\n$$a^3 - 3a^2 + 4 = b^3 - 3b^2 + 4$$\n$$a^3 - b^3 - 3a^2 + 3b^2 = 0$$\n$$(a-b)(a^2 + ab + b^2) - 3(a-b)(a+b) = 0$$\n$$(a-b)(a^2 + ab + b^2 - 3a - 3b) = 0$$\n\n$a \\neq b$이므로:\n$$a^2 + ab + b^2 - 3a - 3b = 0 \\quad \\cdots (*)$$\n\n**Step 3: 조건 $(*)$에서 $b$를 $a$의 함수로 표현**\n\n$(*)$을 $b$에 대한 이차방정식으로 정리:\n$$b^2 + (a-3)b + (a^2 - 3a) = 0$$\n\n근의 공식:\n$$b = \\frac{-(a-3) \\pm \\sqrt{(a-3)^2 - 4(a^2-3a)}}{2}$$\n$$b = \\frac{3-a \\pm \\sqrt{a^2 - 6a + 9 - 4a^2 + 12a}}{2}$$\n$$b = \\frac{3-a \\pm \\sqrt{-3a^2 + 6a + 9}}{2}$$\n$$b = \\frac{3-a \\pm \\sqrt{-3(a^2 - 2a - 3)}}{2}$$\n$$b = \\frac{3-a \\pm \\sqrt{-3(a-3)(a+1)}}{2}$$\n\n$a < b$이고 실근 조건을 위해: $-1 \\leq a \\leq 3$이고\n$$b = \\frac{3-a + \\sqrt{-3(a-3)(a+1)}}{2}$$\n\n**Step 4: $3a + b$의 최솟값 구하기**\n\n$$3a + b = 3a + \\frac{3-a + \\sqrt{-3(a-3)(a+1)}}{2}$$\n$$= \\frac{6a + 3 - a + \\sqrt{-3(a-3)(a+1)}}{2}$$\n$$= \\frac{5a + 3 + \\sqrt{-3(a-3)(a+1)}}{2}$$\n\n$g(a) = -3(a-3)(a+1) = -3(a^2 - 2a - 3) = -3a^2 + 6a + 9$라 하면:\n\n$$3a + b = \\frac{5a + 3 + \\sqrt{g(a)}}{2}$$\n\n최솟값을 구하기 위해 미분하거나, $a = -1$을 시도:\n\n$a = -1$일 때: $g(-1) = -3 - 6 + 9 = 0$\n\n$$b = \\frac{3-(-1) + 0}{2} = \\frac{4}{2} = 2$$\n\n$$3a + b = 3(-1) + 2 = -3 + 2 = -1$$\n\n**[정답 확인]**\n$a = -1, b = 2$일 때 $f(-1) = -1 - 3 + 4 = 0 = f(2)$이고, 조건을 만족하며 $3a + b = -1$이 최솟값이다.\n\n**[오답 분석]**\n극값의 $x$좌표인 0, 2만 고려하거나 잘못된 미분 계산을 하면 오답이 나옴\n\n**[핵심 포인트]**\n- 같은 함수값을 갖는 조건을 식으로 세우고 제약조건으로 사용\n- 경계값($a = -1$ 또는 $a = 3$)에서 최솟값이 나타날 수 있음을 확인",
