    "problem": "곡선 $y = x^3 - 3x + 2$ 위의 점 중 원점까지의 거리가 최소인 점의 $x$ 좌표가 양수일 때, 그 $x$ 좌표의 정수 부분은?",
    "answerType": "choice",
