    "type": "킬러",
    "problem": "삼차함수 $f(x) = x^3 + ax^2 + bx$가 $x = 1$에서 극솟값 $-1$을 가질 때, $a^2 + b^2$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n삼차함수의 극값 조건을 활용하는 문제입니다. 극값을 가지려면 도함수가 0이 되어야 하고, 극솟값을 가지려면 그 점에서 함수값이 주어진 값과 같아야 합니다.\n\n- 극값 조건: $f'(x) = 0$인 점에서 극값을 가짐\n- 극솟값/극댓값 판별: $f''(x) > 0$이면 극솟값, $f''(x) < 0$이면 극댓값\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$f(x) = x^3 + ax^2 + bx$에서\n\n$$f'(x) = 3x^2 + 2ax + b$$\n\n**Step 2: 극솟값 조건 적용**\n\n$x = 1$에서 극솟값을 가지므로 $f'(1) = 0$:\n\n$$f'(1) = 3(1)^2 + 2a(1) + b = 0$$\n$$3 + 2a + b = 0$$\n$$2a + b = -3 \\cdots (1)$$\n\n**Step 3: 함수값 조건 적용**\n\n$x = 1$에서 극솟값이 $-1$이므로 $f(1) = -1$:\n\n$$f(1) = 1^3 + a(1)^2 + b(1) = -1$$\n$$1 + a + b = -1$$\n$$a + b = -2 \\cdots (2)$$\n\n**Step 4: 연립방정식 풀기**\n\n식 (1)과 식 (2)를 연립하면:\n- $2a + b = -3$ ··· (1)\n- $a + b = -2$ ··· (2)\n\n(1) - (2):\n$$a = -1$$\n\n식 (2)에 대입:\n$$-1 + b = -2$$\n$$b = -1$$\n\n**Step 5: 극솟값 확인**\n\n$x = 1$에서 극솟값인지 확인하기 위해 $f''(x)$를 구합니다:\n\n$$f''(x) = 6x + 2a = 6x + 2(-1) = 6x - 2$$\n$$f''(1) = 6 - 2 = 4 > 0$$\n\n따라서 $x = 1$에서 극솟값을 가집니다. ✓\n\n**Step 6: 답 구하기**\n\n$$a^2 + b^2 = (-1)^2 + (-1)^2 = 1 + 1 = 2$$\n\n**[정답 확인]**\n\n$a = -1, b = -1$일 때 $f'(1) = 0$, $f(1) = -1$, $f''(1) > 0$을 모두 만족하므로 조건을 완벽히 충족합니다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오답으로는:\n- **10**: $a^2 + b^2 - 8 = 10$ 같은 계산 실수\n- **5**: $|a| + |b|$를 계산한 경우\n- **1**: $a^2$ 또는 $b^2$ 중 하나만 계산한 경우\n\n**[핵심 포인트]**\n\n1. **극값 조건 두 가지**를 모두 사용: 도함수가 0이 되는 조건과 함수값이 주어진 값이 되는 조건\n2. **극솟값/극댓값 판별**은 이계 도함수로 확인하되, 이 문제에서는 연립방정식의 유일해가 나오므로 필수는 아닙니다.",
