    "answer": 190,
    "explanation": "**[핵심 개념]**\n\n1. **함수의 연속성**: 함수 $h(x)$가 $x=2$에서 연속이려면 $\\lim_{x \\to 2} h(x) = h(2)$이어야 합니다.\n\n2. **극한의 성질**: $\\lim_{x \\to 2} h(x) = \\lim_{x \\to 2} f(x) \\cdot g(x) = \\lim_{x \\to 2} f(x) \\cdot \\lim_{x \\to 2} g(x)$ (각 극한이 존재할 때)\n\n3. **인수분해와 약분**: $0/0$ 꼴의 극한을 구할 때는 인수분해하여 약분합니다.\n\n**[풀이]**\n\n**Step 1: $f(x)$의 극한 구하기**\n\n$x \\neq 2$일 때, $f(x) = \\dfrac{x^3 - 8}{x^2 - 4}$\n\n분자와 분모를 인수분해합니다:\n- 분자: $x^3 - 8 = (x-2)(x^2 + 2x + 4)$\n- 분모: $x^2 - 4 = (x-2)(x+2)$\n\n$$\\lim_{x \\to 2} f(x) = \\lim_{x \\to 2} \\dfrac{(x-2)(x^2 + 2x + 4)}{(x-2)(x+2)} = \\lim_{x \\to 2} \\dfrac{x^2 + 2x + 4}{x+2}$$\n\n$$= \\dfrac{4 + 4 + 4}{4} = \\dfrac{12}{4} = 3$$\n\n따라서 $a = 3$\n\n**Step 2: $g(x)$의 극한 구하기**\n\n$x \\neq 2$일 때, $g(x) = \\dfrac{\\sqrt{x+7} - 3}{x - 2}$\n\n분자를 유리화합니다:\n\n$$g(x) = \\dfrac{\\sqrt{x+7} - 3}{x - 2} \\cdot \\dfrac{\\sqrt{x+7} + 3}{\\sqrt{x+7} + 3} = \\dfrac{(x+7) - 9}{(x-2)(\\sqrt{x+7} + 3)}$$\n\n$$= \\dfrac{x - 2}{(x-2)(\\sqrt{x+7} + 3)} = \\dfrac{1}{\\sqrt{x+7} + 3}$$\n\n$$\\lim_{x \\to 2} g(x) = \\dfrac{1}{\\sqrt{9} + 3} = \\dfrac{1}{6}$$\n\n따라서 $b = \\dfrac{1}{6}$\n\n**Step 3: $h(x)$의 연속성 확인**\n\n$h(x) = f(x) \\cdot g(x)$가 $x=2$에서 연속이려면:\n\n$$h(2) = \\lim_{x \\to 2} h(x) = \\lim_{x \\to 2} f(x) \\cdot \\lim_{x \\to 2} g(x) = 3 \\cdot \\dfrac{1}{6} = \\dfrac{1}{2}$$\n\n**Step 4: $60(a+b)$ 계산**\n\n$$a + b = 3 + \\dfrac{1}{6} = \\dfrac{18 + 1}{6} = \\dfrac{19}{6}$$\n\n$$60(a+b) = 60 \\cdot \\dfrac{19}{6} = 10 \\cdot 19 = 190$$\n\n**[정답 확인]**\n\n$f(x)$와 $g(x)$의 극한값을 각각 구하여 $a=3$, $b=\\frac{1}{6}$을 얻고, 이를 더한 후 60을 곱하면 190이 됩니다.\n\n**[오답 분석]**\n\n- **180**: $b = \\frac{1}{6}$을 계산할 때 실수하거나, 유리화 과정에서 오류가 있을 수 있습니다.\n- **200**: $a$나 $b$의 값을 잘못 계산했을 가능성이 있습니다.\n- **185**: 중간 계산에서 소수점 오류가 발생한 경우입니다.\n\n**[핵심 포인트]**\n\n1. **$0/0$ 꼴의 극한**: 인수분해 또는 유리화를 통해 약분한 후 극한값을 구합니다.\n\n2. **곱의 연속성**: $h(x) = f(x) \\cdot g(x)$가 연속이려면 $\\lim_{x \\to a} h(x) = \\lim_{x \\to a} f(x) \\times \\lim_{x \\to a} g(x)$로 계산할 수 있습니다.",
