    "problem": "연속함수 $f(x)$가 $f(0) = 0$이고 $\\lim_{h \\to 0} \\dfrac{f(2h)}{h} = 6$을 만족한다. $g(x) = \\begin{cases} \\dfrac{f(x^2 - 1)}{x - 1} & (x \\neq 1) \\\\\\\\ c & (x = 1) \\end{cases}$가 $x = 1$에서 연속일 때, $c$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n1. 연속함수의 성질: 함수 $f$가 $x=a$에서 연속이면 $\\lim_{x \\to a} f(x) = f(a)$\n2. 미분의 정의: $\\lim_{h \\to 0} \\frac{f(h)}{h} = f'(0)$ (단, $f(0)=0$일 때)\n3. 함수의 연속성 조건: $g(x)$가 $x=1$에서 연속 $\\Leftrightarrow \\lim_{x \\to 1} g(x) = g(1) = c$\n\n**[풀이]**\n\n**Step 1: 주어진 조건에서 $f'(0)$ 구하기**\n\n$\\lim_{h \\to 0} \\dfrac{f(2h)}{h} = 6$이 주어졌다.\n\n$h \\to 0$일 때, $2h \\to 0$이므로 치환하면:\n$$\\lim_{h \\to 0} \\dfrac{f(2h)}{h} = \\lim_{h \\to 0} \\dfrac{f(2h)}{2h} \\cdot 2 = 2 \\lim_{h \\to 0} \\dfrac{f(2h)}{2h} = 6$$\n\n$2h = t$로 놓으면:\n$$2 \\lim_{t \\to 0} \\dfrac{f(t)}{t} = 6$$\n\n따라서:\n$$\\lim_{t \\to 0} \\dfrac{f(t)}{t} = 3$$\n\n$f(0) = 0$이므로 미분의 정의에 의해 $f'(0) = 3$\n\n**Step 2: $g(x)$가 $x=1$에서 연속이기 위한 조건**\n\n$g(x)$가 $x=1$에서 연속이려면:\n$$\\lim_{x \\to 1} g(x) = g(1) = c$$\n\n따라서:\n$$c = \\lim_{x \\to 1} \\dfrac{f(x^2-1)}{x-1}$$\n\n**Step 3: 극한값 계산**\n\n$x \\to 1$일 때, $x^2 - 1 \\to 0$이고 $x - 1 \\to 0$이므로 $\\dfrac{0}{0}$ 꼴이다.\n\n분자를 정리하면:\n$$f(x^2-1) = f((x-1)(x+1))$$\n\n$u = x-1$로 놓으면 $x \\to 1$일 때 $u \\to 0$이고, $x^2-1 = (x-1)(x+1) = u(u+2)$\n\n$$c = \\lim_{u \\to 0} \\dfrac{f(u(u+2))}{u}$$\n\n$f(0) = 0$이므로:\n$$c = \\lim_{u \\to 0} \\dfrac{f(u(u+2)) - f(0)}{u}$$\n\n$$= \\lim_{u \\to 0} \\dfrac{f(u(u+2)) - f(0)}{u(u+2)} \\cdot (u+2)$$\n\n$$= \\lim_{u \\to 0} \\dfrac{f(u(u+2)) - f(0)}{u(u+2)} \\cdot \\lim_{u \\to 0}(u+2)$$\n\n$v = u(u+2)$로 놓으면 $u \\to 0$일 때 $v \\to 0$:\n$$= f'(0) \\cdot 2 = 3 \\cdot 2 = 6$$\n\n**[정답 확인]**\n$g(x)$가 $x=1$에서 연속이려면 $c = \\lim_{x \\to 1} \\dfrac{f(x^2-1)}{x-1} = f'(0) \\cdot 2 = 3 \\cdot 2 = 6$이므로 정답은 **6**이다.\n\n**[오답 분석]**\n- **3**: $f'(0) = 3$만 구하고 극한 계산에서 $(x+1) \\to 2$ 인수를 놓친 경우\n- **2**: 미분값을 잘못 계산하거나 계산 과정에서 실수한 경우\n- **12**: $(x+1)$의 극한값을 두 번 곱한 경우\n\n**[핵심 포인트]**\n1. 주어진 극한 조건 $\\lim_{h \\to 0} \\dfrac{f(2h)}{h} = 6$에서 미분계수 $f'(0) = 3$을 올바르게 추출하는 것이 핵심\n2. 극한 계산 시 $\\dfrac{f(x^2-1)}{x-1} = \\dfrac{f(x^2-1)}{x^2-1} \\cdot \\dfrac{x^2-1}{x-1}$로 분해하면 $f'(0) \\cdot (x+1)$의 형태가 된다.",
