    "problem": "최고차항의 계수가 1인 이차함수 $f(x)$가 $\\lim_{x \\to 2} \\dfrac{f(x)}{x - 2} = -1$이고 $f(0) = 6$을 만족한다. $g(x) = \\begin{cases} \\dfrac{f(x)}{x^2 - 5x + 6} & (x \\neq 3) \\\\\\\\ k & (x = 3) \\end{cases}$가 $x = 3$에서 연속일 때, $k$의 값은?",
