    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n1. **극한과 미분의 관계**: $\\lim_{x \\to a} \\frac{f(x)}{x-a} = L$이면 $f(a) = 0$이고 $f'(a) = L$\n2. **함수의 연속성**: 함수 $g(x)$가 $x=a$에서 연속 ⟺ $\\lim_{x \\to a} g(x) = g(a)$\n3. **인수분해**: $x^2 - 5x + 6 = (x-2)(x-3)$\n\n**[풀이]**\n\n**Step 1: 함수 $f(x)$ 결정**\n\n$f(x) = x^2 + bx + c$ (최고차항의 계수가 1)\n\n$\\lim_{x \\to 2} \\frac{f(x)}{x-2} = -1$이므로, 분자가 0으로 수렴해야 함:\n$$f(2) = 0$$\n\n따라서 $4 + 2b + c = 0$ ... (1)\n\n또한 극한값이 $-1$이므로 (로피탈 정리 또는 미분의 정의):\n$$f'(2) = 2(2) + b = 4 + b = -1$$\n$$b = -5$$ ... (2)\n\n$f(0) = 6$에서:\n$$c = 6$$ ... (3)\n\n(2)와 (3)을 (1)에 대입하여 검증:\n$$4 + 2(-5) + 6 = 4 - 10 + 6 = 0$$ ✓\n\n따라서 $f(x) = x^2 - 5x + 6 = (x-2)(x-3)$\n\n**Step 2: $g(x)$의 극한값 구하기**\n\n$x \\neq 3$일 때:\n$$g(x) = \\frac{f(x)}{x^2 - 5x + 6} = \\frac{(x-2)(x-3)}{(x-2)(x-3)} = \\frac{(x-2)(x-3)}{(x-2)(x-3)}$$\n\n분자를 다시 정리하면:\n$$g(x) = \\frac{x^2 - 5x + 6}{(x-2)(x-3)} = \\frac{(x-2)(x-3)}{(x-2)(x-3)} = 1$$\n\n아니, 다시 계산합니다:\n\n$f(x) = x^2 - 5x + 6 = (x-2)(x-3)$이고 분모 $x^2 - 5x + 6 = (x-2)(x-3)$이므로:\n\n$$g(x) = \\frac{(x-2)(x-3)}{(x-2)(x-3)} = 1 \\quad (x \\neq 2, 3)$$\n\n그런데 $x=3$에서 $0/0$ 꼴이므로, $x \\to 3$일 때:\n$$\\lim_{x \\to 3} g(x) = \\lim_{x \\to 3} \\frac{(x-2)(x-3)}{(x-2)(x-3)}$$\n\n$x \\neq 3$에서 $(x-3)$이 약분되지 않으므로 직접 계산:\n$$\\lim_{x \\to 3} \\frac{x^2-5x+6}{(x-2)(x-3)} = \\lim_{x \\to 3} \\frac{(x-2)(x-3)}{(x-2)(x-3)} = \\lim_{x \\to 3} 1 = 1$$\n\n실제로는:\n$$\\lim_{x \\to 3} g(x) = \\lim_{x \\to 3} \\frac{x^2-5x+6}{x^2-5x+6} = \\lim_{x \\to 3} 1 = 1$$\n\n아닙니다. 로피탈 정리 적용:\n$$\\lim_{x \\to 3} \\frac{x^2-5x+6}{(x-2)(x-3)} = \\lim_{x \\to 3} \\frac{2x-5}{(x-3)+(x-2)} = \\lim_{x \\to 3} \\frac{2x-5}{2x-5} = 1$$\n\n**Step 3: 연속성 조건**\n\n$g(x)$가 $x=3$에서 연속이려면:\n$$\\lim_{x \\to 3} g(x) = g(3) = k$$\n$$k = 1$$\n\n**[정답 확인]**\n\n$f(x) = x^2 - 5x + 6 = (x-2)(x-3)$일 때, $g(x) = 1$ (단, $x \\neq 2, 3$)의 극한이 $x=3$에서 1이므로 $k=1$.\n\n**[오답 분석]**\n\n- ① $-2$, ② $-1$: 극한값 계산 오류\n- ③ $0$: 분자/분모 약분 실수\n- ⑤ $2$: 계산 과정에서 계수 오류\n\n**[핵심 포인트]**\n\n$\\lim_{x \\to a} \\frac{f(x)}{x-a}$ 형태의 극한은 $f(a)=0$을 암시하며, 함수의 연속성을 위해서는 극한값이 함수값과 같아야 함.",
