    "problem": "미분가능한 함수 $f(x)$가 $f(1) = 2$, $f'(1) = 3$을 만족한다. $g(x) = \\{f(x)\\}^3 - x \\cdot f(x^2)$일 때, $g'(1)$의 값은?",
