    "explanation": "**[핵심 개념]**\n- 도함수의 정의: $f'(x)$는 $f(x)$를 $x$에 대해 미분한 함수\n- 주어진 식에서 $f'(1)$은 상수이므로, 도함수 식을 정리할 때 이를 미지수로 취급\n- 부정적분(역미분)을 이용하여 원래 함수를 구하기\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n\n$f'(x) = 3x^2 + 2xf'(1)$이 모든 실수 $x$에 대해 성립합니다.\n\n$f'(1)$의 값을 구하기 위해 $x=1$을 대입합니다:\n$$f'(1) = 3(1)^2 + 2(1)f'(1)$$\n$$f'(1) = 3 + 2f'(1)$$\n$$-f'(1) = 3$$\n$$f'(1) = -3$$\n\n**Step 2: $f'(x)$ 결정**\n\n$f'(1) = -3$을 원래 식에 대입:\n$$f'(x) = 3x^2 + 2x(-3)$$\n$$f'(x) = 3x^2 - 6x$$\n\n**Step 3: $f(x)$ 구하기 (부정적분)**\n\n$f'(x) = 3x^2 - 6x$를 적분합니다:\n$$f(x) = \\int (3x^2 - 6x) dx$$\n$$f(x) = x^3 - 3x^2 + C$$\n\n초기조건 $f(0) = 1$을 이용하여 적분상수 $C$를 구합니다:\n$$f(0) = 0^3 - 3(0)^2 + C = 1$$\n$$C = 1$$\n\n따라서:\n$$f(x) = x^3 - 3x^2 + 1$$\n\n**Step 4: $f(2)$ 계산**\n\n$$f(2) = 2^3 - 3(2)^2 + 1$$\n$$f(2) = 8 - 12 + 1$$\n$$f(2) = -3$$\n\n**[정답 확인]**\n$f'(1) = -3$으로부터 $f(x) = x^3 - 3x^2 + 1$이 유일하게 결정되며, $f(0) = 1$ 조건도 만족하고 $f(2) = -3$입니다.\n\n**[오답 분석]**\n선택지가 없으므로 오답 분석은 생략합니다. 단, 계산 실수로 가능한 오류:\n- $f'(1)$을 구할 때 부호 실수로 $f'(1) = 3$ 오계산 → $f(2) = 5$ 등 틀린 값\n- 적분 시 지수 계산 실수 → 잘못된 함수식\n- 초기조건 미적용 → 적분상수 미결정\n\n**[핵심 포인트]**\n1. 도함수 식에서 $f'(1)$이 나타나면, $x=1$을 대입하여 이 상수값을 먼저 구하는 것이 핵심\n2. 도함수를 구한 후 적분하고 초기조건으로 적분상수를 결정하는 일련의 과정",
