    "problem": "함수 $f(x) = x^3 - 3ax^2 + 3(a^2 + a)x + 1$이 모든 실수에서 증가하도록 하는 정수 $a$의 개수를 구하시오. (단, $|a| \\leq 5$)",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n\n함수가 모든 실수에서 증가하기 위한 필요충분조건은 도함수가 모든 점에서 0 이상이어야 한다는 것입니다. 즉, $f'(x) \\geq 0$이 모든 실수 $x$에서 성립해야 합니다. 특히 이차함수 $f'(x) \\geq 0$이 항상 성립하려면, $f'(x)$의 판별식이 0 이하여야 합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$$f'(x) = 3x^2 - 6ax + 3(a^2 + a)$$\n\n$$f'(x) = 3[x^2 - 2ax + (a^2 + a)]$$\n\n**Step 2: 함수가 모든 실수에서 증가하는 조건**\n\n$f(x)$가 모든 실수에서 증가하려면:\n$$f'(x) \\geq 0 \\text{ (모든 실수 } x \\text{에서)}$$\n\n3을 곱한 것이므로:\n$$x^2 - 2ax + (a^2 + a) \\geq 0 \\text{ (모든 실수 } x \\text{에서)}$$\n\n**Step 3: 판별식 조건**\n\n이차식이 항상 0 이상이려면 판별식 $D \\leq 0$이어야 합니다:\n\n$$D = (-2a)^2 - 4 \\cdot 1 \\cdot (a^2 + a) \\leq 0$$\n\n$$4a^2 - 4a^2 - 4a \\leq 0$$\n\n$$-4a \\leq 0$$\n\n$$a \\geq 0$$\n\n**Step 4: 조건 정리**\n\n- $a \\geq 0$\n- $|a| \\leq 5$이므로 $-5 \\leq a \\leq 5$\n\n따라서: $0 \\leq a \\leq 5$\n\n**Step 5: 정수 개수 세기**\n\n이 범위에서의 정수: $a = 0, 1, 2, 3, 4, 5$\n\n정수의 개수: **6개**\n\n**[정답 확인]**\n\n$a \\geq 0$과 $|a| \\leq 5$를 동시에 만족하는 정수는 0부터 5까지이므로 정확히 6개입니다.\n\n**[오답 분석]**\n\n- **5개**: $a = 1, 2, 3, 4, 5$로 세어 $a=0$을 빠뜨린 경우\n- **7개**: $a = -1, 0, 1, 2, 3, 4, 5$로 세어 $a < 0$인 음수까지 포함한 경우\n- **11개**: $|a| \\leq 5$인 모든 정수를 센 경우 (조건 $a \\geq 0$을 무시)\n\n**[핵심 포인트]**\n\n1. 함수의 증감 판정은 **도함수의 부호**로 결정되며, \"항상 증가\" 조건은 $f'(x) \\geq 0$이 모든 $x$에서 성립해야 한다는 점\n2. 이차식이 항상 음이 아니려면 **판별식 $D \\leq 0$**이 필수 조건이며, 이를 통해 $a$의 범위를 정확히 구할 수 있다는 점",
