    "answer": 2,
    "explanation": "**[핵심 개념]**\n함수가 구간에서 감소하려면 그 구간에서 도함수가 항상 0 이하여야 합니다. 즉, $[a, a+2]$에서 $f(x)$가 감소하려면 $f'(x) \\leq 0$이 이 구간의 모든 $x$에 대해 성립해야 합니다. 3차 함수의 도함수는 2차 함수이므로, 도함수의 근을 구하여 함수의 증감을 판단할 수 있습니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**2단계: 함수의 증감 판정**\n\n$f'(x) = 3(x-1)(x-3)$의 부호를 조사합니다.\n- $x < 1$일 때: $f'(x) > 0$ (증가)\n- $1 < x < 3$일 때: $f'(x) < 0$ (감소)\n- $x > 3$일 때: $f'(x) > 0$ (증가)\n\n따라서 $f(x)$는 $[1, 3]$에서 감소합니다.\n\n**3단계: 조건 설정**\n\n길이 2인 닫힌 구간 $[a, a+2]$에서 $f(x)$가 감소하려면, 이 구간이 $f(x)$의 감소 구간 $[1, 3]$에 완전히 포함되어야 합니다.\n\n$$1 \\leq a \\text{ 이고 } a+2 \\leq 3$$\n\n**4단계: 부등식 풀이**\n\n첫 번째 조건: $a \\geq 1$\n두 번째 조건: $a \\leq 1$\n\n이 두 조건을 동시에 만족하려면:\n$$a = 1$$\n\n**[정답 확인]**\n$a = 1$일 때 $[1, 3]$은 정확히 $f(x)$의 감소 구간이므로, 이 구간에서 $f'(x) \\leq 0$이 성립합니다.\n\n**[오답 분석]**\n\n① $a = -1$: 구간은 $[-1, 1]$인데, $x < 1$에서 $f'(x) > 0$이므로 증가하는 부분이 포함됩니다.\n\n② $a = 0$: 구간은 $[0, 2]$인데, $x \\in [0, 1)$에서 $f'(x) > 0$이므로 증가하는 부분이 포함됩니다.\n\n④ $a = 2$: 구간은 $[2, 4]$인데, $x \\in (3, 4]$에서 $f'(x) > 0$이므로 증가하는 부분이 포함됩니다.\n\n⑤ $a = 3$: 구간은 $[3, 5]$인데, $x > 3$에서 $f'(x) > 0$이므로 증가하는 부분만 포함됩니다.\n\n**[핵심 포인트]**\n구간에서 함수가 감소하려면 그 구간이 도함수가 음수 또는 0인 구간에 **완전히 포함**되어야 합니다. 경계값도 정확히 일치해야 하므로 부등식 조건을 등호까지 정확히 적용해야 합니다.",
