    "problem": "삼차함수 $f(x) = x^3 + ax^2 + bx + c$가 $x = -1$에서 극대, $x = 3$에서 극소를 가진다. $f(-1) - f(3)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 32,
    "explanation": "**[핵심 개념]**\n\n삼차함수의 극값 조건을 이용한 문제입니다. 함수 $f(x)$가 $x=p$에서 극값을 가지면 $f'(p)=0$입니다. 삼차함수는 도함수가 이차함수이므로, 극대와 극소를 가지는 조건은 도함수가 서로 다른 두 실근을 가져야 합니다. 또한 극값의 차를 구할 때는 도함수의 근과 근과 계수의 관계를 활용합니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n\n$$f'(x) = 3x^2 + 2ax + b$$\n\n$f(x)$가 $x=-1$에서 극대, $x=3$에서 극소를 가지므로:\n$$f'(-1) = 0, \\quad f'(3) = 0$$\n\n**2단계: 조건식 세우기**\n\n$f'(-1) = 0$에서:\n$$3(-1)^2 + 2a(-1) + b = 0$$\n$$3 - 2a + b = 0$$\n$$b = 2a - 3 \\cdots (1)$$\n\n$f'(3) = 0$에서:\n$$3(3)^2 + 2a(3) + b = 0$$\n$$27 + 6a + b = 0$$\n$$b = -6a - 27 \\cdots (2)$$\n\n**3단계: $a$, $b$ 구하기**\n\n(1)과 (2)를 연립하면:\n$$2a - 3 = -6a - 27$$\n$$8a = -24$$\n$$a = -3$$\n\n(1)에 대입하면:\n$$b = 2(-3) - 3 = -9$$\n\n**4단계: $f(-1)$과 $f(3)$ 계산하기**\n\n$f(x) = x^3 - 3x^2 - 9x + c$\n\n$$f(-1) = (-1)^3 - 3(-1)^2 - 9(-1) + c = -1 - 3 + 9 + c = 5 + c$$\n\n$$f(3) = (3)^3 - 3(3)^2 - 9(3) + c = 27 - 27 - 27 + c = -27 + c$$\n\n**5단계: $f(-1) - f(3)$ 계산**\n\n$$f(-1) - f(3) = (5 + c) - (-27 + c) = 5 + c + 27 - c = 32$$\n\n**[정답 확인]**\n\n$c$값에 관계없이 $f(-1) - f(3) = 32$이므로, 극대값과 극소값의 차는 주어진 조건만으로 유일하게 결정됩니다.\n\n**[오답 분석]**\n\n객관식 선지가 없으므로 생략합니다.\n\n**[핵심 포인트]**\n\n- 삼차함수가 극대와 극소를 가지는 조건 $\\Rightarrow$ $f'(x)=0$이 서로 다른 두 실근을 가짐\n- 극값의 차를 구할 때 상수항 $c$는 소거되므로, $a, b$를 구한 후 직접 계산할 수 있습니다.",
