    "_type": "max_min",
    "type": "최대와 최소",
    "problem": "곡선 $y = x^3 - 3x + 5$에서 $-1 \\leq x \\leq 3$일 때, $y$의 최댓값을 $M$, 최솟값을 $m$이라 하자. $M - m$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 20,
    "explanation": "**[핵심 개념]**\n\n폐구간에서 함수의 최댓값과 최솟값을 구하는 방법:\n1. 주어진 구간 $[a, b]$에서 함수 $f(x)$의 최댓값과 최솟값은 극값 또는 끝점에서 나타남\n2. $f'(x) = 0$인 점(극값)과 구간의 양 끝점 $x = a, b$에서의 함수값을 모두 구해 비교\n3. 가장 큰 값이 최댓값 $M$, 가장 작은 값이 최솟값 $m$\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n\n$y = x^3 - 3x + 5$에서\n$$y' = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$$\n\n**Step 2: 극값을 찾기 위해 $y' = 0$인 점 찾기**\n\n$$y' = 0 \\Rightarrow 3(x-1)(x+1) = 0$$\n$$x = 1 \\text{ 또는 } x = -1$$\n\n두 극값 후보 $x = -1, 1$이 모두 주어진 구간 $[-1, 3]$에 포함됨\n\n**Step 3: 극값과 끝점에서 함수값 계산**\n\n$x = -1$일 때:\n$$y = (-1)^3 - 3(-1) + 5 = -1 + 3 + 5 = 7$$\n\n$x = 1$일 때:\n$$y = (1)^3 - 3(1) + 5 = 1 - 3 + 5 = 3$$\n\n$x = 3$일 때:\n$$y = (3)^3 - 3(3) + 5 = 27 - 9 + 5 = 23$$\n\n**Step 4: 최댓값과 최솟값 결정**\n\n계산한 함수값들: $y(-1) = 7$, $y(1) = 3$, $y(3) = 23$\n\n- 최댓값: $M = 23$ (at $x = 3$)\n- 최솟값: $m = 3$ (at $x = 1$)\n\n**Step 5: $M - m$ 계산**\n\n$$M - m = 23 - 3 = 20$$\n\n**[정답 확인]**\n\n구간 $[-1, 3]$에서 세 지점 중 최댓값 23, 최솟값 3이므로 그 차이는 20입니다.\n\n**[오답 분석]**\n\n객관식이 아니므로 해당 없음\n\n**[핵심 포인트]**\n\n폐구간에서의 최댓값과 최솟값은 반드시 **극값 후보(도함수 = 0인 점)와 끝점**에서만 나타난다는 것을 기억하고, 모든 후보점에서의 함수값을 계산하여 비교해야 합니다.",
