    "problem": "수직선 위를 움직이는 점 P의 시각 $t$에서의 위치가 $x(t) = t^3 - 6t^2 + 9t + 1$이다. 점 P의 속도가 처음으로 0이 되는 시각부터 다시 0이 되는 시각까지 점 P가 움직인 거리를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n1. **속도와 위치의 관계**: 위치함수 $x(t)$의 도함수가 속도 $v(t) = x'(t)$\n2. **속도가 0인 시각**: $v(t) = 0$을 풀어서 구함\n3. **움직인 거리**: 속도의 부호가 바뀔 때마다 구간을 나누어 각 구간에서의 변위의 절댓값을 합산\n\n**[풀이]**\n\n**1단계: 속도함수 구하기**\n\n$$v(t) = x'(t) = 3t^2 - 12t + 9$$\n\n**2단계: 속도가 0인 시각 구하기**\n\n$$v(t) = 0$$\n$$3t^2 - 12t + 9 = 0$$\n$$t^2 - 4t + 3 = 0$$\n$$(t-1)(t-3) = 0$$\n\n따라서 $t = 1$ 또는 $t = 3$\n\n**3단계: 속도의 부호 변화 확인**\n\n- $t < 1$일 때: $v(t) = 3(t-1)(t-3) > 0$ (양수)\n- $1 < t < 3$일 때: $v(t) = 3(t-1)(t-3) < 0$ (음수)\n- $t > 3$일 때: $v(t) = 3(t-1)(t-3) > 0$ (양수)\n\n따라서 $t=1$에서 $t=3$으로 가는 동안 속도의 부호가 바뀜\n\n**4단계: 각 시각에서의 위치 계산**\n\n$t=1$일 때:\n$$x(1) = 1 - 6 + 9 + 1 = 5$$\n\n$t=3$일 때:\n$$x(3) = 27 - 54 + 27 + 1 = 1$$\n\n**5단계: 움직인 거리 계산**\n\n$t=1$부터 $t=3$까지 점 P가 움직인 거리는:\n$$\\text{거리} = |x(3) - x(1)| = |1 - 5| = |-4| = 4$$\n\n**[정답 확인]**\n\n$t=1$에서 $t=3$ 사이에서 속도가 항상 음수이므로 점 P는 한 방향으로만 움직이며, 이동 거리는 두 위치의 차이의 절댓값인 4이다.\n\n**[오답 분석]**\n\n객관식이 아니므로 해당 없음\n\n**[핵심 포인트]**\n\n1. **속도가 0인 두 시각 사이의 거리를 구할 때**, 그 구간 내에서 속도의 부호가 바뀌는지 확인해야 한다.\n2. **이 문제에서는 $t=1$부터 $t=3$ 사이에서 속도가 항상 음수**이므로, 단순히 위치 값의 차이를 구하면 된다.",
