    "problem": "수직선 위를 움직이는 두 점 P, Q의 시각 $t$ ($t \\geq 0$)에서의 위치가 $x_P = t^3 - 3t$, $x_Q = 3t^2 - 3t$이다. 두 점의 속도가 같아지는 모든 시각 $t$의 합을 구하시오.",
    "answerType": "short",
