    "answer": 2,
    "explanation": "**[핵심 개념]**\n- **속도**는 위치를 시간으로 미분한 값: $v = \\frac{dx}{dt}$\n- 두 점의 속도가 같다는 것은 $v_P = v_Q$를 의미\n- 주어진 조건을 만족하는 모든 $t$ 값을 구해서 합산\n\n**[풀이]**\n\n**Step 1: 각 점의 속도 함수 구하기**\n\n점 P의 위치: $x_P = t^3 - 3t$\n점 P의 속도: $v_P = \\frac{dx_P}{dt} = 3t^2 - 3$\n\n점 Q의 위치: $x_Q = 3t^2 - 3t$\n점 Q의 속도: $v_Q = \\frac{dx_Q}{dt} = 6t - 3$\n\n**Step 2: 두 점의 속도가 같아지는 조건**\n\n$v_P = v_Q$일 때:\n$$3t^2 - 3 = 6t - 3$$\n\n**Step 3: 방정식 풀기**\n\n$$3t^2 - 3 = 6t - 3$$\n$$3t^2 - 6t - 3 + 3 = 0$$\n$$3t^2 - 6t = 0$$\n$$3t(t - 2) = 0$$\n\n따라서 $t = 0$ 또는 $t = 2$\n\n**Step 4: 조건 확인**\n\n문제에서 $t \\geq 0$이므로 두 해 모두 유효합니다.\n- $t = 0$일 때: $v_P = 3(0)^2 - 3 = -3$, $v_Q = 6(0) - 3 = -3$ ✓\n- $t = 2$일 때: $v_P = 3(2)^2 - 3 = 12 - 3 = 9$, $v_Q = 6(2) - 3 = 12 - 3 = 9$ ✓\n\n**Step 5: 모든 시각의 합**\n\n$$t_1 + t_2 = 0 + 2 = 2$$\n\n**[정답 확인]**\n두 점의 속도가 같아지는 시각은 $t=0$과 $t=2$이며, 이들의 합은 $2$입니다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 오류를 제시:\n- $3t^2 - 6t = 0$에서 $t = 2$만 구하면 오답 (음수 아닌 조건을 잘못 해석)\n- 미분을 잘못하면 다른 방정식을 얻어 오답\n- 방정식을 정확히 세우지 못하고 위치가 같은 조건으로 풀면 오답\n\n**[핵심 포인트]**\n- **속도는 위치의 1차 미분**: 위치 함수가 주어질 때 먼저 미분하여 속도 함수를 구한다.\n- **$t \\geq 0$ 조건 확인**: 인수분해로 얻은 모든 근이 조건을 만족하는지 반드시 검증한다.",
