    "explanation": "**[핵심 개념]**\n위치 함수 $x(t)$에서 속도는 $v(t) = \\frac{dx}{dt}$이고, 가속도는 $a(t) = \\frac{dv}{dt} = \\frac{d^2x}{dt^2}$입니다. 가속도가 0인 순간을 찾으려면 $a(t) = 0$을 풀어야 하고, 그 시각의 속도를 구한 후 2배를 계산합니다.\n\n**[풀이]**\n\n**1단계: 속도 함수 구하기**\n$$v(t) = \\frac{dx}{dt} = \\frac{d}{dt}(2t^3 - 9t^2 + 12t) = 6t^2 - 18t + 12$$\n\n**2단계: 가속도 함수 구하기**\n$$a(t) = \\frac{dv}{dt} = \\frac{d}{dt}(6t^2 - 18t + 12) = 12t - 18$$\n\n**3단계: 가속도가 0인 시각 찾기**\n$$a(t) = 0$$\n$$12t - 18 = 0$$\n$$t = \\frac{18}{12} = \\frac{3}{2}$$\n\n**4단계: 그 시각의 속도 구하기**\n$$v\\left(\\frac{3}{2}\\right) = 6\\left(\\frac{3}{2}\\right)^2 - 18\\left(\\frac{3}{2}\\right) + 12$$\n$$= 6 \\cdot \\frac{9}{4} - 27 + 12$$\n$$= \\frac{54}{4} - 15$$\n$$= \\frac{27}{2} - 15$$\n$$= \\frac{27}{2} - \\frac{30}{2}$$\n$$= -\\frac{3}{2}$$\n\n**5단계: 속도의 2배 계산**\n$$2 \\times v\\left(\\frac{3}{2}\\right) = 2 \\times \\left(-\\frac{3}{2}\\right) = -3$$\n\n**[정답 확인]**\n가속도가 0일 때 $t = \\frac{3}{2}$이고, 이 시각의 속도는 $-\\frac{3}{2}$이므로 2배는 $-3$입니다.\n\n**[오답 분석]**\n- 속도를 2배 하지 않고 $-\\frac{3}{2}$를 답으로 하는 실수\n- 가속도의 정의를 잘못 이해하여 1차 도함수만 구하는 경우\n- 계산 과정에서 부호를 잘못 다루는 경우\n\n**[핵심 포인트]**\n위치 → (미분) → 속도 → (미분) → 가속도의 순서를 명확히 하고, $a(t)=0$일 때의 $t$값을 정확히 구한 후 그 순간의 속도를 구해야 합니다.",
