    "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\dfrac{f(x) - 2x^3}{x^2} = 3$이고 $\\lim_{x \\to 0} \\dfrac{f(x)}{x} = -1$을 만족할 때, $f(1)$의 값은?",
