    "answer": 2,
    "explanation": "**[핵심 개념]**\n방정식 $f(x) = k$가 서로 다른 세 실근을 가지려면, 함수 $y = f(x)$의 그래프와 직선 $y = k$가 서로 다른 세 점에서 만나야 합니다. 이를 위해서는 함수 $f(x)$의 극값을 구하고, 직선 $y = k$가 극댓값과 극솟값 사이에 있어야 합니다.\n\n**[풀이]**\n\n$f(x) = x^3 - 3x$라고 하면, 방정식 $x^3 - 3x = k$는 $f(x) = k$의 형태입니다.\n\n**Step 1: 함수의 극값 구하기**\n\n$f'(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$\n\n극값을 가지는 점: $f'(x) = 0$에서 $x = -1$ 또는 $x = 1$\n\n**Step 2: 극댓값과 극솟값 계산**\n\n$x = -1$에서: $f(-1) = (-1)^3 - 3(-1) = -1 + 3 = 2$ (극댓값)\n\n$x = 1$에서: $f(1) = 1^3 - 3(1) = 1 - 3 = -2$ (극솟값)\n\n**Step 3: 이계 도함수로 확인**\n\n$f''(x) = 6x$\n\n- $f''(-1) = -6 < 0$ → $x = -1$에서 극대\n- $f''(1) = 6 > 0$ → $x = 1$에서 극소\n\n**Step 4: 서로 다른 세 실근의 조건**\n\n방정식이 서로 다른 세 실근을 가지려면, 직선 $y = k$가 극솟값과 극댓값 사이에 있어야 합니다.\n\n$$-2 < k < 2$$\n\n**Step 5: 이 범위의 정수 찾기**\n\n$-2 < k < 2$를 만족하는 정수 $k$는:\n$$k = -1, 0, 1$$\n\n따라서 정수 $k$의 개수는 **3개**입니다.\n\n**[정답 확인]**\n$f(x) = x^3 - 3x$는 $x = -1$에서 극댓값 2, $x = 1$에서 극솟값 -2를 가지므로, 직선 $y = k$가 이 두 극값 사이에 있을 때($-2 < k < 2$) 정확히 세 개의 교점을 가지며, 이 범위의 정수는 $-1, 0, 1$로 3개입니다.\n\n**[오답 분석]**\n- ① 1개: 극값이 정수가 아니므로 범위 내 정수가 1개뿐이라고 잘못 판단\n- ② 2개: 극값을 포함해야 한다고 착각하여 $-2 \\leq k \\leq 2$로 계산\n- ④ 4개: 범위를 $-2 \\leq k \\leq 2$로 잘못 설정\n- ⑤ 5개: 범위를 더 넓게 설정하는 오류\n\n**[핵심 포인트]**\n극값이 정확히 정수일 때, \"서로 다른 세 실근\"을 위해서는 **극값을 제외한 구간** $-2 < k < 2$에서 정수를 찾아야 합니다. 부등호의 등호 포함 여부가 답을 결정하는 핵심입니다.",
