    "problem": "함수 $f(x) = x^3 - 12x + a$가 서로 다른 두 개의 실근을 가지도록 하는 양수 $a$의 값은?",
    "answerType": "choice",
    "choices": [
      "① 4",
      "② 8",
      "③ 12",
      "④ 16",
      "⑤ 20"
    ],
    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n3차 함수가 특정 개수의 실근을 가지려면 극값을 이용한 분석이 필요합니다. 함수 $f(x) = x^3 - 12x + a$가 서로 다른 두 개의 실근을 가진다는 것은 $f(x) = 0$의 그래프가 x축과 정확히 두 점에서 만난다는 의미입니다. 이는 함수가 극댓값과 극솟값을 가질 때, 그 중 하나가 0이 되어야 합니다.\n\n**[풀이]**\n\n**1단계: 도함수를 구하여 극값을 찾기**\n\n$$f'(x) = 3x^2 - 12 = 3(x^2 - 4) = 3(x-2)(x+2)$$\n\n극값은 $f'(x) = 0$일 때이므로 $x = -2$ 또는 $x = 2$\n\n**2단계: 극값 계산**\n\n$x = -2$에서: \n$$f(-2) = (-2)^3 - 12(-2) + a = -8 + 24 + a = 16 + a$$\n\n$x = 2$에서:\n$$f(2) = (2)^3 - 12(2) + a = 8 - 24 + a = -16 + a$$\n\n**3단계: 함수의 개형 파악**\n\n$f'(x) = 3(x-2)(x+2)$의 부호를 분석하면:\n- $x < -2$: $f'(x) > 0$ (증가)\n- $-2 < x < 2$: $f'(x) < 0$ (감소)\n- $x > 2$: $f'(x) > 0$ (증가)\n\n따라서 $x = -2$에서 극댓값 $16 + a$, $x = 2$에서 극솟값 $-16 + a$를 갖습니다.\n\n**4단계: 서로 다른 두 실근 조건**\n\n3차 함수가 서로 다른 두 개의 실근을 가지려면, 극댓값과 극솟값의 부호가 반대이고 하나는 0이어야 합니다(중근이 생기는 경우).\n\n극솟값이 0이 되는 경우:\n$$-16 + a = 0 \\Rightarrow a = 16$$\n\n이때 극댓값은 $16 + 16 = 32 > 0$\n\n**5단계: 검증**\n\n$a = 16$일 때 $f(x) = x^3 - 12x + 16$\n- 극댓값: $f(-2) = 32 > 0$\n- 극솟값: $f(2) = 0$\n\n극솟값이 0이므로 $x = 2$에서 중근을 가지고, 극댓값이 양수이므로 $x < -2$ 구간에서 한 번 더 x축과 만납니다. 따라서 정확히 두 개의 서로 다른 실근을 가집니다.\n\n**[정답 확인]**\n\n극솟값이 0이 될 때 $a = 16$이므로, 함수는 중근과 단순근 두 개의 서로 다른 실근을 가집니다.\n\n**[오답 분석]**\n\n- **① 4**: $a = 4$일 때 극솟값 = $-12$, 극댓값 = $20$ → 극값이 모두 0이 아니므로 3개의 서로 다른 실근을 가짐\n- **② 8**: $a = 8$일 때 극솟값 = $-8$, 극댓값 = $24$ → 3개의 서로 다른 실근을 가짐\n- **③ 12**: $a = 12$일 때 극솟값 = $-4$, 극댓값 = $28$ → 3개의 서로 다른 실근을 가짐\n- **⑤ 20**: $a = 20$일 때 극솟값 = $4 > 0$ → 1개의 실근만 가짐\n\n**[핵심 포인트]**\n\n3차 함수가 정확히 2개의 서로 다른 실근을 가지려면 극값 중 하나가 정확히 0이어야 합니다. 극댓값과 극솟값의 크기를 비교하여 어느 것이 0이 될 조건을 찾으면 됩니다.",
