    "explanation": "**[핵심 개념]**\n삼차함수가 서로 다른 세 실근을 가지려면 극값이 존재해야 하고, 극댓값과 극솟값이 부호가 반대여야 한다. 즉, 극댓값 > 0이고 극솟값 < 0이어야 한다. 이를 판정하기 위해 도함수를 이용해 극값을 구한다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f'(x) = 3x^2 - 12x + 9 = 3(x^2 - 4x + 3) = 3(x-1)(x-3)$$\n\n**Step 2: 극값의 위치 결정**\n$f'(x) = 0$에서 $x = 1$ 또는 $x = 3$\n\n- $x < 1$: $f'(x) > 0$ (증가)\n- $1 < x < 3$: $f'(x) < 0$ (감소)\n- $x > 3$: $f'(x) > 0$ (증가)\n\n따라서 $x=1$에서 극댓값, $x=3$에서 극솟값을 가진다.\n\n**Step 3: 극값 계산**\n\n극댓값: \n$$f(1) = 1 - 6 + 9 + a = 4 + a$$\n\n극솟값:\n$$f(3) = 27 - 54 + 27 + a = a$$\n\n**Step 4: 서로 다른 세 실근 조건**\n\n방정식 $f(x) = 0$이 서로 다른 세 실근을 가지려면:\n$$f(1) > 0 \\text{ and } f(3) < 0$$\n\n$$4 + a > 0 \\text{ and } a < 0$$\n\n$$a > -4 \\text{ and } a < 0$$\n\n$$-4 < a < 0$$\n\n**Step 5: 정수 개수 구하기**\n\n$-4 < a < 0$을 만족하는 정수는:\n$$a \\in \\{-3, -2, -1\\}$$\n\n따라서 정수 $a$의 개수는 **3개**이다.\n\n**[정답 확인]**\n극댓값이 양수, 극솟값이 음수일 때만 $x$축과 세 점에서 만나므로, $-4 < a < 0$을 만족하는 정수는 $-3, -2, -1$로 3개이다.\n\n**[오답 분석]**\n- ① 1개: 조건을 너무 좁게 해석한 경우\n- ② 2개: 경계값을 포함하거나 부등호 방향을 잘못 이해한 경우\n- ④ 4개: $a=-4$나 $a=0$을 포함하려 한 경우 (등호 포함하면 중근 생김)\n- ⑤ 5개: 범위를 잘못 설정한 경우\n\n**[핵심 포인트]**\n삼차함수가 세 실근을 가지는 조건: **극댓값 · 극솟값 < 0** (부호가 반대)\n부등호는 등호를 포함하지 않음을 주의 (등호이면 중근이 됨)",
