    "explanation": "**[핵심 개념]**\n극한의 성질과 무한대로 발산하는 경우의 극한 계산을 다룹니다. $n \\to \\infty$일 때, $\\frac{1}{n} \\to 0$, $\\frac{1}{n^2} \\to 0$ 등의 성질을 이용하여 분자와 분모의 극한값을 각각 구한 후, 극한값의 몫을 구하는 문제입니다.\n\n**[풀이]**\n\n주어진 극한식을 정리합니다:\n$$\\lim_{n \\to \\infty} \\frac{\\frac{5}{n} + \\frac{3}{n^2}}{\\frac{1}{n} - \\frac{2}{n^3}}$$\n\n**Step 1: 분자와 분모의 극한을 각각 계산**\n\n$n \\to \\infty$일 때:\n- $\\frac{5}{n} \\to 0$\n- $\\frac{3}{n^2} \\to 0$\n- $\\frac{1}{n} \\to 0$\n- $\\frac{2}{n^3} \\to 0$\n\n따라서 분자 $\\to 0 + 0 = 0$, 분모 $\\to 0 - 0 = 0$\n\n**Step 2: $\\frac{0}{0}$ 꼴이므로 변형이 필요**\n\n분자와 분모에서 가장 낮은 차수인 $\\frac{1}{n}$을 인수로 빼냅니다:\n\n$$\\lim_{n \\to \\infty} \\frac{\\frac{1}{n}(5 + \\frac{3}{n})}{\\frac{1}{n}(1 - \\frac{2}{n^2})}$$\n\n**Step 3: $\\frac{1}{n}$을 약분**\n\n$$\\lim_{n \\to \\infty} \\frac{5 + \\frac{3}{n}}{1 - \\frac{2}{n^2}}$$\n\n**Step 4: 극한값 계산**\n\n$n \\to \\infty$일 때, $\\frac{3}{n} \\to 0$, $\\frac{2}{n^2} \\to 0$이므로:\n\n$$\\lim_{n \\to \\infty} \\frac{5 + \\frac{3}{n}}{1 - \\frac{2}{n^2}} = \\frac{5 + 0}{1 - 0} = \\frac{5}{1} = 5$$\n\n**[정답 확인]**\n분자와 분모의 최저차 항으로 정리하면 분자는 $\\frac{5}{n}$, 분모는 $\\frac{1}{n}$이므로, 극한값은 $\\frac{5}{1} = 5$입니다.\n\n**[오답 분석]**\n- ① 1: 분자의 모든 항을 무시하고 계산한 경우\n- ② 2: 계산 오류로 $\\frac{5}{n}$과 다른 항을 잘못 비교한 경우\n- ③ 3: 분자의 계수를 잘못 읽거나 계산 실수\n- ④ 4: 분자와 분모의 차수를 잘못 파악한 경우\n\n**[핵심 포인트]**\n$\\frac{0}{0}$ 꼴의 극한에서는 분자와 분모의 최저차 항으로 먼저 정리한 후, 공통인수로 약분하여 계산하면 됩니다. 이 문제에서는 분자의 $\\frac{5}{n}$과 분모의 $\\frac{1}{n}$의 비율이 극한값을 결정합니다.",
