    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n이 문제는 $\\frac{0}{0}$ 꼴의 부정형 극한입니다. 다음 두 가지 방법으로 해결할 수 있습니다.\n\n1) **로피탈의 정리**: $\\lim_{x \\to a} \\frac{f(x)}{g(x)} = \\frac{0}{0}$ 꼴일 때, $\\lim_{x \\to a} \\frac{f'(x)}{g'(x)}$로 계산\n2) **테일러 급수**: $\\ln(1+x) \\approx x - \\frac{x^2}{2} + \\cdots$, $\\sqrt{1+x} \\approx 1 + \\frac{x}{2} - \\frac{x^2}{8} + \\cdots$\n\n**[풀이]**\n\n**방법 1: 로피탈의 정리 이용**\n\n먼저 $x \\to 0$일 때 극한의 형태를 확인합니다.\n- 분자: $\\ln(0+1) = \\ln 1 = 0$\n- 분모: $\\sqrt{0+4} - 2 = 2 - 2 = 0$\n\n$\\frac{0}{0}$ 꼴이므로 로피탈의 정리를 적용합니다.\n\n$$\\lim_{x \\to 0} \\frac{\\ln(x+1)}{\\sqrt{x+4} - 2} = \\lim_{x \\to 0} \\frac{\\frac{d}{dx}[\\ln(x+1)]}{\\frac{d}{dx}[\\sqrt{x+4} - 2]}$$\n\n분자의 도함수: $\\frac{d}{dx}[\\ln(x+1)] = \\frac{1}{x+1}$\n\n분모의 도함수: $\\frac{d}{dx}[\\sqrt{x+4} - 2] = \\frac{1}{2\\sqrt{x+4}}$\n\n따라서:\n$$\\lim_{x \\to 0} \\frac{\\frac{1}{x+1}}{\\frac{1}{2\\sqrt{x+4}}} = \\lim_{x \\to 0} \\frac{1}{x+1} \\cdot 2\\sqrt{x+4}$$\n\n$$= \\lim_{x \\to 0} \\frac{2\\sqrt{x+4}}{x+1}$$\n\n$x \\to 0$을 대입하면:\n$$= \\frac{2\\sqrt{0+4}}{0+1} = \\frac{2 \\cdot 2}{1} = 4$$\n\n**[정답 확인]**\n\n로피탈의 정리를 정확하게 적용하여 $x=0$을 대입하면 $\\frac{2\\sqrt{4}}{1} = 4$가 나옵니다.\n\n**[오답 분석]**\n\n- **① 1**: 분모를 유리화 후 계산 실수 시 도출 가능\n- **② 2**: 로피탈 적용 중 분모의 도함수를 $\\frac{1}{\\sqrt{x+4}}$로 잘못 계산한 경우\n- **③ 3**: 극한값 계산 과정에서 계수 실수\n- **⑤ 5**: 분자의 극한값 $\\ln(1)=0$을 고려하지 않고 계산\n\n**[핵심 포인트]**\n\n$\\frac{0}{0}$ 부정형에서는 로피탈의 정리를 적용하기 전에 **반드시 극한의 형태를 확인**해야 합니다. 분모를 유리화하는 방법도 있지만, 로피탈의 정리가 더 빠르고 안전합니다.",
