    "answer": 2,
    "explanation": "**[핵심 개념]**\n이 문제는 **리만 합(Riemann Sum)**을 이용한 정적분 계산입니다. \n\n$\\displaystyle\\lim_{n \\to \\infty} \\frac{1}{n} \\sum_{k=1}^{n} f\\left(\\frac{k}{n}\\right) = \\int_{0}^{1} f(x) dx$ \n\n형태의 극한은 정적분으로 변환할 수 있습니다. 이 공식을 적용하기 위해 주어진 식을 적절히 변형해야 합니다.\n\n**[풀이]**\n\n**Step 1: 리만 합 형태로 변형**\n\n주어진 극한식을 다시 정리하면:\n$$\\lim_{n \\to \\infty} \\frac{1}{n} \\sum_{k=1}^{n} \\sqrt{1 + \\frac{3k}{n}}$$\n\n$x_k = \\frac{k}{n}$으로 놓으면, $\\frac{1}{n}$은 $\\Delta x$에 해당하고:\n$$\\lim_{n \\to \\infty} \\sum_{k=1}^{n} \\sqrt{1 + 3 \\cdot \\frac{k}{n}} \\cdot \\frac{1}{n}$$\n\n**Step 2: 적분으로 변환**\n\n리만 합의 정의에 의해, $x = \\frac{k}{n}$일 때 $k$가 1부터 $n$까지 변하면 $x$는 $\\frac{1}{n}$부터 1까지 변합니다.\n\n$n \\to \\infty$일 때 $\\frac{1}{n} \\to 0$이므로:\n$$\\lim_{n \\to \\infty} \\frac{1}{n} \\sum_{k=1}^{n} \\sqrt{1 + 3 \\cdot \\frac{k}{n}} = \\int_{0}^{1} \\sqrt{1 + 3x} \\, dx$$\n\n**Step 3: 정적분 계산**\n\n$\\int_{0}^{1} \\sqrt{1 + 3x} \\, dx$를 계산합니다.\n\n$u = 1 + 3x$로 치환하면:\n- $du = 3dx$ → $dx = \\frac{1}{3}du$\n- $x = 0$일 때 $u = 1$\n- $x = 1$일 때 $u = 4$\n\n$$\\int_{0}^{1} \\sqrt{1 + 3x} \\, dx = \\int_{1}^{4} \\sqrt{u} \\cdot \\frac{1}{3} du$$\n\n$$= \\frac{1}{3} \\int_{1}^{4} u^{1/2} \\, du$$\n\n$$= \\frac{1}{3} \\left[ \\frac{2}{3}u^{3/2} \\right]_{1}^{4}$$\n\n$$= \\frac{2}{9} \\left[ u^{3/2} \\right]_{1}^{4}$$\n\n**Step 4: 대입하여 계산**\n\n$$= \\frac{2}{9} \\left( 4^{3/2} - 1^{3/2} \\right)$$\n\n$$= \\frac{2}{9} (8 - 1)$$\n\n$$= \\frac{2}{9} \\cdot 7$$\n\n$$= \\frac{14}{9}$$\n\n**[정답 확인]**\n치환적분을 통해 $\\int_{0}^{1} \\sqrt{1 + 3x} \\, dx = \\frac{14}{9}$를 얻었으므로 정답은 **③**입니다.\n\n**[오답 분석]**\n- ① $\\frac{10}{9}$: 치환 후 적분 계산에서 계수 실수\n- ② $\\frac{12}{9}$: 상한값 계산 오류 ($4^{3/2} = 8$을 $6$으로 계산)\n- ④ $\\frac{16}{9}$: 상한값을 초과로 계산\n- ⑤ $\\frac{18}{9} = 2$: 계수 $\\frac{2}{9}$를 누락하고 계산\n\n**[핵심 포인트]**\n1. **리만 합 → 정적분 변환**: $\\frac{1}{n}\\sum f(\\frac{k}{n}) \\to \\int_0^1 f(x)dx$ 형태 인식\n2. **치환적분 정확성**: $u = 1+3x$ 치환 후 계수 $\\frac{1}{3}$를 빠뜨리지 않기",
