    "explanation": "**[핵심 개념]**\n이 문제는 극한의 기본 공식 $\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1$을 이용하는 문제입니다. 이 공식의 역수 형태인 $\\lim_{x \\to 0} \\frac{x}{\\sin x} = 1$도 함께 알아야 하며, 이를 확장하여 분자와 분모에 동시에 같은 차수의 식이 있을 때 어떻게 처리하는지 이해해야 합니다.\n\n**[풀이]**\n\n주어진 극한을 정리하겠습니다.\n\n$$\\lim_{x \\to 0} \\frac{3x^2}{\\sin^2 x}$$\n\n분자와 분모를 다시 쓰면:\n\n$$\\lim_{x \\to 0} \\frac{3x^2}{\\sin^2 x} = \\lim_{x \\to 0} \\frac{3x^2}{(\\sin x)^2}$$\n\n이를 다음과 같이 변형합니다:\n\n$$= \\lim_{x \\to 0} 3 \\cdot \\frac{x^2}{\\sin^2 x} = 3 \\cdot \\lim_{x \\to 0} \\frac{x^2}{\\sin^2 x}$$\n\n이제 $\\frac{x^2}{\\sin^2 x}$를 정리하기 위해 다음과 같이 표현합니다:\n\n$$= 3 \\cdot \\lim_{x \\to 0} \\left(\\frac{x}{\\sin x}\\right)^2$$\n\n극한의 성질에 의해:\n\n$$= 3 \\cdot \\left(\\lim_{x \\to 0} \\frac{x}{\\sin x}\\right)^2$$\n\n기본 공식 $\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1$의 역수를 취하면:\n\n$$\\lim_{x \\to 0} \\frac{x}{\\sin x} = 1$$\n\n따라서:\n\n$$= 3 \\cdot (1)^2 = 3 \\cdot 1 = 3$$\n\n**[정답 확인]**\n극한값이 3이므로 정답은 ③번입니다. 기본 공식을 정확하게 적용했으므로 이 답이 맞습니다.\n\n**[오답 분석]**\n- ① 1: $\\lim_{x \\to 0} \\frac{x}{\\sin x} = 1$만 계산한 경우\n- ② 2: 제곱을 처리하지 않거나 계산 실수가 있는 경우\n- ④ 4: 분자의 3을 중복으로 계산한 경우\n- ⑤ 5: 무관한 수를 선택한 경우\n\n**[핵심 포인트]**\n$\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1$ (또는 그 역수 형태)을 이용하되, 분자와 분모의 차수가 같을 때는 **제곱** 또는 **거듭제곱**을 정확하게 처리해야 합니다. $\\left(\\frac{x}{\\sin x}\\right)^2 = \\frac{x^2}{\\sin^2 x}$임을 활용하는 것이 핵심입니다.",
