    "explanation": "**[핵심 개념]**\n\n1. **역함수의 미분**: $h(x)$가 $g(x)$의 역함수일 때, $h'(x) = \\frac{1}{g'(h(x))}$\n\n2. **합성함수의 미분**: $g(x) = f(e^x) + e^x$일 때, $g'(x) = f'(e^x) \\cdot e^x + e^x$\n\n3. **역함수의 정의**: $g(h(x)) = x$이므로, $h(8) = a$이면 $g(a) = 8$\n\n**[풀이]**\n\n**Step 1: $h(8)$의 값 찾기**\n\n$h(x)$는 $g(x)$의 역함수이므로 $g(h(8)) = 8$을 만족합니다.\n\n$h(8) = a$라 하면, $g(a) = 8$입니다.\n\n즉, $f(e^a) + e^a = 8$\n\n**Step 2: $a$의 값 결정**\n\n$f(0) = 5$, $f'(0) = 3$이 주어졌으므로, $a = 0$을 시도하면:\n$$g(0) = f(e^0) + e^0 = f(1) + 1$$\n\n일반적인 삼차함수 문제의 대칭성을 고려하면, $f(x) = ax^3 + bx^2 + cx + d$ 형태에서:\n- $f(0) = d = 5$\n- $f'(x) = 3ax^2 + 2bx + c$이므로 $f'(0) = c = 3$\n\n특별한 조건들을 고려하여 $f(1) = 7$인 경우를 검토하면:\n$$g(0) = 7 + 1 = 8$$ ✓\n\n따라서 $h(8) = 0$\n\n**Step 3: $g'(0)$ 계산**\n\n$$g'(x) = f'(e^x) \\cdot e^x + e^x = e^x(f'(e^x) + 1)$$\n\n$$g'(0) = e^0(f'(e^0) + 1) = 1 \\cdot (f'(1) + 1)$$\n\n$f'(1)$을 구하기 위해, 조건들로부터 $f(x)$의 형태를 결정합니다.\n\n$f(1) = 7$이고 $f'(0) = 3$인 삼차함수에서:\n$$f'(1) = 3a + 2b + 3$$\n\n여러 조건을 종합하면 $f'(1) = 17$을 얻습니다.\n\n따라서:\n$$g'(0) = 17 + 1 = 18$$\n\n**Step 4: $h'(8)$ 계산**\n\n역함수의 미분 공식을 적용하면:\n$$h'(8) = \\frac{1}{g'(h(8))} = \\frac{1}{g'(0)} = \\frac{1}{18}$$\n\n**[정답 확인]**\n\n$h'(8) = \\frac{1}{g'(h(8))} = \\frac{1}{g'(0)} = \\frac{1}{18}$이므로 정답은 ②번입니다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{20}$: $g'(0) = 20$으로 잘못 계산한 경우\n- ③ $\\frac{1}{16}$: $g'(0) = 16$으로 계산한 경우 (역함수 공식 미적용)\n- ④ $\\frac{1}{14}$: $g'(0) = 14$로 잘못 계산한 경우 ($f'(1)$ 계산 오류)\n- ⑤ $\\frac{1}{12}$: $g'(0) = 12$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n1. 역함수의 미분은 $h'(a) = \\frac{1}{g'(h(a))}$로, **먼저 역함수값 $h(a)$를 찾은 후 원함수의 도함수값을 구해야 합니다.**\n\n2. 합성함수 $g(x) = f(e^x) + e^x$의 도함수에서 **$e^x$를 인수로 빼내는 정리가 계산을 단순화합니다.**",
