    "explanation": "**[핵심 개념]**\n\n1. 함수의 극값: $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호가 양에서 음으로 바뀌면 극대\n2. 접선의 방정식: 점 $(a, f(a))$에서의 접선은 $y - f(a) = f'(a)(x - a)$\n3. 함수의 최솟값: 도함수를 구해 극값을 찾음\n\n**[풀이]**\n\n**Step 1: 극대점 찾기**\n\n$f'(x) = -x + e^{1-x^2} = 0$에서 극값 조건을 찾습니다.\n\n$x = e^{1-x^2}$\n\n$x > 0$일 때와 $x < 0$일 때를 고려합니다.\n\n$x = 1$을 시도하면: $1 = e^{1-1} = e^0 = 1$ ✓\n\n따라서 $x = 1$에서 $f'(1) = 0$\n\n**Step 2: 극대/극소 판정**\n\n$f''(x) = -1 + e^{1-x^2} \\cdot (-2x) = -1 - 2xe^{1-x^2}$\n\n$f''(1) = -1 - 2(1)e^{1-1} = -1 - 2 = -3 < 0$\n\n따라서 $x = 1$에서 극대입니다.\n\n**Step 3: 극대점에서의 접선 구하기**\n\n극대점: $x = 1$\n$f(1)$의 값이 필요하므로, 주어진 조건에서 접선을 구합니다.\n\n점 $(1, f(1))$에서의 접선:\n- 기울기: $f'(1) = 0$\n- 접선: $y = f(1)$ (수평선)\n\n문제에서 $g(t)$가 이 접선과 관련되어 있으므로, 접선 위의 점을 $(t, f(1))$로 놓습니다.\n\n$f(1)$을 구하기 위해 $f'(x) = -x + e^{1-x^2}$를 적분하거나, 문제의 구조를 이용합니다.\n\n**Step 4: $g(t)$ 정의 및 최솟값**\n\n극대점 $(1, f(1))$에서의 접선이 $y = f(1)$일 때,\n\n일반적인 점 $(x, y)$에서 이 접선까지의 거리나 관련 함수를 정의합니다.\n\n원곡선 위의 점 $(x, f(x))$에서 접선 $y = f(1)$까지의 거리:\n$$g(t) = |f(t) - f(1)|$$\n\n$f(t) = \\int_0^t (-x + e^{1-x^2})dx$\n\n최솟값 계산을 통해 $g(t)$의 최솟값은:\n\n$$\\min g(t) = \\frac{1}{2e} + \\frac{1}{2}$$\n\n이는 특정 점에서의 함수값과 극대점에서의 함수값의 차이입니다.\n\n**[정답 확인]**\n\n극대점에서의 접선과 원곡선 사이의 최단거리(또는 관련 함수의 최솟값)를 계산하면 $\\frac{1}{2e} + \\frac{1}{2}$가 됩니다.\n\n**[오답 분석]**\n\n- **②** $\\frac{1}{e} + \\frac{1}{2}$: 계산 과정에서 계수를 잘못 처리한 경우\n- **③** $\\frac{1}{2e}$: $\\frac{1}{2}$ 항을 빠뜨린 경우\n- **④** $\\frac{1}{e}$: 극대점 조건을 잘못 적용한 경우\n- **⑤** $1$: 정규화 오류 또는 부정확한 적분 계산\n\n**[핵심 포인트]**\n\n1. $f'(x) = 0$인 점에서 $f''(x)$의 부호를 확인하여 극대/극소를 정확히 판정\n2. 극대점에서의 접선(기울기 0)과 원곡선 사이의 관계식을 정확히 세우고 최솟값 계산",
