    "answer": 3,
    "explanation": "**[핵심 개념]**\n적분 계산에서 피적분함수를 정리할 때는 근호 안의 식을 먼저 인수분해하고 단순화하는 것이 중요합니다. 또한 삼각함수의 항등식과 치환적분을 활용하여 복잡한 식을 간단히 만들 수 있습니다.\n\n**[풀이]**\n\n**1단계: 피적분함수 정리**\n\n$$\\sqrt{\\sin x - \\sin^3 x} = \\sqrt{\\sin x(1 - \\sin^2 x)} = \\sqrt{\\sin x \\cdot \\cos^2 x}$$\n\n$0 \\leq x \\leq \\frac{\\pi}{2}$ 범위에서 $\\sin x \\geq 0$, $\\cos x \\geq 0$이므로:\n\n$$\\sqrt{\\sin x \\cdot \\cos^2 x} = \\cos x\\sqrt{\\sin x}$$\n\n**2단계: 적분식 변환**\n\n$$\\int_0^{\\pi/2} \\cos x\\sqrt{\\sin x}\\,dx$$\n\n**3단계: 치환적분**\n\n$u = \\sin x$로 놓으면:\n- $du = \\cos x\\,dx$\n- $x = 0$일 때 $u = 0$\n- $x = \\frac{\\pi}{2}$일 때 $u = 1$\n\n$$\\int_0^{\\pi/2} \\cos x\\sqrt{\\sin x}\\,dx = \\int_0^1 \\sqrt{u}\\,du = \\int_0^1 u^{1/2}\\,du$$\n\n**4단계: 부정적분 계산**\n\n$$\\int_0^1 u^{1/2}\\,du = \\left[\\frac{u^{3/2}}{3/2}\\right]_0^1 = \\left[\\frac{2u^{3/2}}{3}\\right]_0^1$$\n\n$$= \\frac{2 \\cdot 1^{3/2}}{3} - \\frac{2 \\cdot 0^{3/2}}{3} = \\frac{2}{3}$$\n\n**[정답 확인]**\n$\\frac{2}{3}$은 정확한 계산 과정을 따르면 얻어지는 값으로, 선택지 ④가 정답입니다.\n\n**[오답 분석]**\n- ① $\\frac{1}{3}$: 분자가 1이 되도록 계산한 경우 (분모에 3을 곱하지 않음)\n- ② $\\frac{1}{2}$: 지수 계산 오류로 $u^{1/2}$의 적분을 $\\frac{1}{2}u^{1/2}$로 잘못 계산\n- ③ $\\frac{\\pi}{6}$: 삼각함수의 정적분과 혼동하여 $\\pi$를 포함시킨 경우\n- ⑤ $1$: 계산 과정에서 계수를 누락한 경우\n\n**[핵심 포인트]**\n1. 제곱근 안의 식을 인수분해하여 $\\sqrt{\\sin x(1-\\sin^2 x)} = \\cos x\\sqrt{\\sin x}$로 단순화하는 것이 핵심입니다.\n2. 적절한 치환($u = \\sin x$)으로 적분을 간단히 변환하면, 다항함수의 적분 공식 $\\int u^n du = \\frac{u^{n+1}}{n+1}$을 직접 적용할 수 있습니다.",
