    "problem": "함수 $f(x)$가 $f(1) = 8$이고, 역함수 $g(x)$에 대하여 $\\displaystyle\\int_1^2 g(f(x)) \\cdot f'(x)\\,dx = 25$일 때, $f(2)$의 값은?",
