    "explanation": "**[핵심 개념]**\n분자의 차수가 분모의 차수보다 크거나 같을 때는 다항식 나눗셈을 이용하여 피적분함수를 정리해야 합니다. 일반적으로 $\\frac{f(x)}{g(x)} = q(x) + \\frac{r(x)}{g(x)}$ 형태로 변형한 후 적분합니다. 또한 $\\int \\frac{1}{x}\\,dx = \\ln|x| + C$ 공식을 활용합니다.\n\n**[풀이]**\n\n$\\displaystyle\\int_0^{10} \\frac{x+2}{x+1}\\,dx$를 계산하기 위해 먼저 피적분함수를 정리합니다.\n\n**Step 1: 다항식 나눗셈으로 함수 변형**\n\n$\\frac{x+2}{x+1}$를 분해합니다. 분자를 분모로 표현하면:\n\n$$x+2 = (x+1) + 1$$\n\n따라서:\n$$\\frac{x+2}{x+1} = \\frac{(x+1)+1}{x+1} = \\frac{x+1}{x+1} + \\frac{1}{x+1} = 1 + \\frac{1}{x+1}$$\n\n**Step 2: 적분 계산**\n\n$$\\int_0^{10} \\frac{x+2}{x+1}\\,dx = \\int_0^{10} \\left(1 + \\frac{1}{x+1}\\right)\\,dx$$\n\n$$= \\left[x + \\ln|x+1|\\right]_0^{10}$$\n\n**Step 3: 정적분의 계산**\n\n상한과 하한을 대입합니다:\n\n$$= \\left(10 + \\ln 11\\right) - \\left(0 + \\ln 1\\right)$$\n\n$$= 10 + \\ln 11 - 0$$\n\n$$= 10 + \\ln 11$$\n\n**[정답 확인]**\n다항식 나눗셈으로 $1 + \\frac{1}{x+1}$로 변형한 후 적분하면 $[x + \\ln(x+1)]_0^{10} = 10 + \\ln 11$이므로 정답은 ④입니다.\n\n**[오답 분석]**\n- ① $10 + \\ln 10$: $\\ln 11$을 잘못 계산하거나 상한에서 $\\ln 10$을 대입한 경우\n- ② $10 - \\ln 11$: 부호를 잘못 처리한 경우\n- ③ $11 + \\ln 10$: 상한값 10을 x값으로 잘못 더하거나 로그값을 잘못 계산한 경우\n- ⑤ $11 + \\ln 11$: 상한값을 $[x]$에서 $x=11$로 잘못 해석한 경우\n\n**[핵심 포인트]**\n분자의 차수가 분모 이상일 때는 반드시 **다항식 나눗셈으로 먼저 정리**하고, 로그함수의 적분에서 **$\\ln 1 = 0$임을 잊지 않기**가 중요합니다.",
