    "explanation": "**[핵심 개념]**\n점의 위치를 나타내는 함수 $s(t)$에서 속도는 위치를 시간에 대해 미분한 도함수 $v(t) = s'(t)$로 구합니다. 특정 시각에서의 속도는 그 시각에서의 도함수 값입니다.\n\n**[풀이]**\n\n주어진 위치 함수는 $s(t) = t^3 - 3t^2 + 2t$입니다.\n\n**1단계: 속도 함수 구하기**\n\n속도는 위치의 도함수이므로:\n$$v(t) = s'(t) = \\frac{d}{dt}(t^3 - 3t^2 + 2t)$$\n\n미분 공식 $\\frac{d}{dt}(t^n) = nt^{n-1}$을 적용하면:\n$$v(t) = 3t^2 - 6t + 2$$\n\n**2단계: $t=1$에서의 속도 구하기**\n\n$t=1$을 속도 함수에 대입합니다:\n$$v(1) = 3(1)^2 - 6(1) + 2$$\n$$v(1) = 3 - 6 + 2$$\n$$v(1) = -1$$\n\n**[정답 확인]**\n$t=1$에서 속도 함수 $v(t) = 3t^2 - 6t + 2$에 $t=1$을 대입하면 $v(1) = 3 - 6 + 2 = -1$이므로 정답입니다.\n\n**[오답 분석]**\n- **0을 선택한 경우**: 가속도 $a(t) = 6t - 6$을 구해서 $a(1) = 0$과 혼동했을 가능성이 있습니다.\n- **1을 선택한 경우**: 속도를 구할 때 부호를 실수했거나, $v(1) = |{-1}| = 1$로 잘못 계산했을 가능성이 있습니다.\n- **2를 선택한 경우**: 상수항만 답으로 착각했거나 미분 과정에서 계산 실수를 했을 가능성이 있습니다.\n\n**[핵심 포인트]**\n- 속도 = 위치의 1차 도함수이며, 음수 속도는 음의 방향(왼쪽)으로 이동함을 의미합니다.\n- 도함수 계산 후 반드시 주어진 시각의 값을 대입하는 단계를 놓치지 않아야 합니다.",
