    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n이 문제는 $\\frac{0}{0}$ 꼴의 부정형 극한으로, 로피탈의 정리(L'Hôpital's Rule)를 적용해야 합니다. 또한 $x^x$를 미분할 때 $x^x = e^{x\\ln x}$로 변형하여 연쇄법칙을 사용합니다. 테일러 전개를 이용한 방법도 효과적입니다.\n\n**[풀이]**\n\n**방법 1: 로피탈의 정리 (2차 적용)**\n\n$x = 1$을 대입하면:\n- 분자: $1^1 - 1 = 0$\n- 분모: $(1-1)^2 = 0$\n\n$\\frac{0}{0}$ 꼴이므로 로피탈의 정리를 적용합니다.\n\n먼저 $x^x$의 도함수를 구합니다:\n$$\\frac{d}{dx}(x^x) = \\frac{d}{dx}(e^{x\\ln x}) = e^{x\\ln x} \\cdot (\\ln x + 1) = x^x(\\ln x + 1)$$\n\n**1차 미분:**\n$$\\lim_{x \\to 1} \\frac{x^x(\\ln x + 1) - 1}{2(x-1)}$$\n\n$x = 1$을 대입하면:\n- 분자: $1^1(0 + 1) - 1 = 0$\n- 분모: $0$\n\n여전히 $\\frac{0}{0}$ 꼴이므로 다시 로피탈의 정리를 적용합니다.\n\n**2차 미분:**\n\n분자를 미분하면:\n$$\\frac{d}{dx}[x^x(\\ln x + 1) - 1] = [x^x(\\ln x + 1)]' = x^x(\\ln x + 1)^2 + x^x \\cdot \\frac{1}{x}$$\n$$= x^x(\\ln x + 1)^2 + x^{x-1}$$\n\n분모를 미분하면:\n$$\\frac{d}{dx}[2(x-1)] = 2$$\n\n따라서:\n$$\\lim_{x \\to 1} \\frac{x^x(\\ln x + 1)^2 + x^{x-1}}{2}$$\n\n$x = 1$을 대입:\n$$= \\frac{1^1(0 + 1)^2 + 1^{1-1}}{2} = \\frac{1 \\cdot 1 + 1}{2} = \\frac{2}{2} = 1$$\n\n**방법 2: 테일러 전개 (검증)**\n\n$x = 1 + h$ (단, $h \\to 0$)로 놓으면:\n\n$$x^x = (1+h)^{1+h} = e^{(1+h)\\ln(1+h)}$$\n\n$\\ln(1+h) = h - \\frac{h^2}{2} + \\frac{h^3}{3} + O(h^4)$이므로:\n\n$$(1+h)\\ln(1+h) = (1+h)\\left(h - \\frac{h^2}{2} + O(h^3)\\right) = h + h^2 - \\frac{h^2}{2} + O(h^3) = h + \\frac{h^2}{2} + O(h^3)$$\n\n따라서:\n$$x^x = e^{h + \\frac{h^2}{2} + O(h^3)} = 1 + \\left(h + \\frac{h^2}{2}\\right) + \\frac{1}{2}\\left(h + \\frac{h^2}{2}\\right)^2 + O(h^3)$$\n$$= 1 + h + \\frac{h^2}{2} + \\frac{h^2}{2} + O(h^3) = 1 + h + h^2 + O(h^3)$$\n\n분자: $x^x - x = (1 + h + h^2 + O(h^3)) - (1 + h) = h^2 + O(h^3)$\n\n분모: $(x-1)^2 = h^2$\n\n$$\\lim_{h \\to 0} \\frac{h^2 + O(h^3)}{h^2} = 1$$\n\n**[정답 확인]**\n\n로피탈의 정리를 두 번 적용하거나 테일러 전개를 이용하면 모두 $1$이 나오므로 정답은 ④입니다.\n\n**[오답 분석]**\n\n- ① $-\\frac{1}{2}$: 로피탈 적용 시 부호를 잘못 계산한 경우\n- ② $0$: 분자가 $h^2$ 차수임을 간과하고 1차 미분 후 조기에 계산을 멈춘 경우\n- ③ $\\frac{1}{2}$: 2차 미분에서 $x^{x-1}$ 항을 빠뜨린 경우\n- ⑤ $\\frac{3}{2}$: 계산 실수로 불필요한 항을 추가한 경우\n\n**[핵심 포인트]**\n\n1. $x^x$의 도함수는 $x^x(\\ln x + 1)$임을 정확히 기억할 것\n2. 부정형이 지속되면 로피탈의 정리를 반복 적용하되, 각 단계에서 정확한 미분이 필수적입니다.",
