    "answer": 2,
    "explanation": "**[핵심 개념]**\n- 합성함수의 미분법(연쇄법칙): $(f \\circ g)'(x) = f'(g(x)) \\cdot g'(x)$\n- 주어진 함수 방정식에서 함수의 명시적 형태를 구한 후 미분\n- 치환을 통해 함수의 정의역을 확장하는 방법\n\n**[풀이]**\n\n**Step 1: 함수 $f$의 명시적 형태 구하기**\n\n주어진 조건: $f(x^2 + 1) = x^4 + 4x^2 + 3$\n\n$t = x^2 + 1$로 치환하면:\n- $x^2 = t - 1$\n- $x^2 + 1 = t$이므로 $x^2 \\geq 0$에서 $t \\geq 1$\n\n우변을 $t$로 표현하면:\n$$f(t) = x^4 + 4x^2 + 3 = (x^2)^2 + 4x^2 + 3 = (t-1)^2 + 4(t-1) + 3$$\n\n**Step 2: 우변 정리**\n\n$$(t-1)^2 + 4(t-1) + 3 = t^2 - 2t + 1 + 4t - 4 + 3$$\n$$= t^2 + 2t + 0 = t^2 + 2t$$\n\n따라서 $t \\geq 1$일 때:\n$$f(t) = t^2 + 2t$$\n\n**Step 3: 함수의 정의역 확인**\n\n$f$가 모든 실수에서 미분가능하다는 조건으로부터, $f(t) = t^2 + 2t$는 모든 실수 $t$에서 성립합니다.\n\n**Step 4: 미분하기**\n\n$$f(t) = t^2 + 2t$$\n$$f'(t) = 2t + 2$$\n\n**Step 5: $f'(2)$ 계산**\n\n$$f'(2) = 2(2) + 2 = 4 + 2 = 6$$\n\n**[정답 확인]**\n\n$f(t) = t^2 + 2t$에서 $f'(t) = 2t + 2$이고, $f'(2) = 6$이므로 정답은 ③번입니다.\n\n**[오답 분석]**\n\n- ① $2$: 상수항만 계산한 경우\n- ② $4$: $f'(2) = 2 \\times 2 = 4$로, 상수항 $+2$를 빠뜨린 경우\n- ④ $8$: $f'(2) = 2 \\times (2+1) = 6$을 계산하다가 착각한 경우\n- ⑤ $10$: 계산 실수로 $2t + 6$ 등으로 잘못 미분한 경우\n\n**[핵심 포인트]**\n\n함수 방정식 $f(g(x)) = h(x)$가 주어질 때, **치환 $t = g(x)$를 이용하여 $f(t)$의 명시적 형태를 먼저 구한 후 미분**하는 것이 핵심입니다. 연쇄법칙을 직접 적용하는 것보다 함수를 명확히 먼저 파악하는 것이 오류를 줄입니다.",
