    "answer": 0,
    "explanation": "**[핵심 개념]**\n삼차함수가 서로 다른 세 실근을 가지려면 극값이 존재해야 하고, 극댓값과 극솟값이 서로 다른 부호를 가져야 합니다. 즉, $f'(x) = 0$이 서로 다른 두 실근을 가지며, 그 두 점에서의 함수값이 서로 다른 부호여야 합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f'(x) = 3x^2 - 3a$$\n\n**Step 2: $f'(x) = 0$이 서로 다른 두 실근을 가지는 조건**\n$$3x^2 - 3a = 0$$\n$$x^2 = a$$\n\n이 방정식이 서로 다른 두 실근을 가지려면:\n$$a > 0$$\n\n$a > 0$일 때, $x = \\pm\\sqrt{a}$\n\n**Step 3: 극값 구하기**\n극값의 위치를 $x = \\sqrt{a}$, $x = -\\sqrt{a}$라 하면:\n\n$$f(\\sqrt{a}) = (\\sqrt{a})^3 - 3a\\sqrt{a} = a\\sqrt{a} - 3a\\sqrt{a} = -2a\\sqrt{a}$$\n\n$$f(-\\sqrt{a}) = (-\\sqrt{a})^3 - 3a(-\\sqrt{a}) = -a\\sqrt{a} + 3a\\sqrt{a} = 2a\\sqrt{a}$$\n\n**Step 4: 극댓값과 극솟값의 부호 확인**\n- $f(-\\sqrt{a}) = 2a\\sqrt{a}$ (극댓값)\n- $f(\\sqrt{a}) = -2a\\sqrt{a}$ (극솟값)\n\n$a > 0$일 때:\n- 극댓값: $2a\\sqrt{a} > 0$\n- 극솟값: $-2a\\sqrt{a} < 0$\n\n극댓값과 극솟값이 서로 다른 부호이므로, 중간값 정리에 의해 세 개의 서로 다른 실근이 존재합니다.\n\n**[정답 확인]**\n$a > 0$일 때만 극값이 존재하면서 동시에 극댓값과 극솟값이 부호가 반대이므로 서로 다른 세 실근을 가집니다.\n\n**[오답 분석]**\n\n- **② $a < 0$**: $a < 0$이면 $x^2 = a$는 실근이 없으므로 $f'(x) = 0$이 실근을 갖지 않습니다. 따라서 극값이 없어 근이 1개만 존재합니다.\n\n- **③ $a > 1$**: 문제는 $a > 0$이면 충분하므로, $a > 1$은 과도한 조건입니다. $0 < a < 1$일 때도 세 실근을 가집니다.\n\n- **④ $a \\geq 0$**: $a = 0$이면 $f(x) = x^3$이 되어 $x = 0$이 중근이므로 서로 다른 세 실근을 가지지 않습니다.\n\n- **⑤ $a \\neq 0$**: $a < 0$인 경우 실근이 1개만 존재하므로 조건을 만족하지 않습니다.\n\n**[핵심 포인트]**\n삼차함수가 서로 다른 세 실근을 가지는 조건은 **도함수가 서로 다른 두 실근을 가지면서, 그 두 극값이 서로 다른 부호**를 가져야 한다는 것입니다. 이 경우 $a > 0$이 필수 조건입니다.",
