    "problem": "다항함수 $f(x)$가 $f'(x) = 4x^3 - 2x$이고 $f(0) = 3$일 때, $f(2)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 15,
    "explanation": "**[핵심 개념]**\n이 문제는 미분과 적분의 역관계를 이용하는 문제입니다. 도함수 $f'(x)$가 주어졌을 때, 원함수 $f(x)$를 구하기 위해서는 부정적분(역미분)을 이용합니다. 또한 초기조건 $f(0) = 3$을 사용하여 적분상수를 결정합니다.\n\n**[풀이]**\n\n**1단계: 부정적분을 이용하여 $f(x)$ 구하기**\n\n$f'(x) = 4x^3 - 2x$이므로, 양변을 $x$에 대해 적분합니다.\n\n$$f(x) = \\int (4x^3 - 2x) dx$$\n\n각 항을 차례대로 적분하면:\n$$f(x) = \\int 4x^3 dx - \\int 2x dx = 4 \\cdot \\frac{x^4}{4} - 2 \\cdot \\frac{x^2}{2} + C$$\n\n$$f(x) = x^4 - x^2 + C$$\n\n여기서 $C$는 적분상수입니다.\n\n**2단계: 초기조건을 이용하여 적분상수 $C$ 구하기**\n\n$f(0) = 3$이라는 조건을 사용합니다.\n\n$$f(0) = 0^4 - 0^2 + C = 3$$\n\n$$C = 3$$\n\n**3단계: $f(x)$의 완전한 형태 결정**\n\n$$f(x) = x^4 - x^2 + 3$$\n\n**4단계: $f(2)$ 계산**\n\n$$f(2) = 2^4 - 2^2 + 3 = 16 - 4 + 3 = 15$$\n\n**[정답 확인]**\n$f(x) = x^4 - x^2 + 3$에서 $f'(x) = 4x^3 - 2x$ (확인됨), $f(0) = 3$ (확인됨), $f(2) = 15$ (정답)\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 실수를 분석하면:\n- **11**: 적분상수를 빼먹은 경우 ($C = 0$으로 계산)\n- **19**: 적분상수를 잘못 구한 경우\n- **13**: 계산 실수로 $f(2) = 16 - 4 + 1 = 13$으로 잘못 계산\n\n**[핵심 포인트]**\n부정적분 결과에는 반드시 적분상수 $C$가 포함되며, 초기조건(여기서는 $f(0) = 3$)을 이용하여 이 상수값을 반드시 결정해야 합니다. 적분상수를 구하지 않으면 답이 달라집니다.",
