    "problem": "다항함수 $f(x)$가 $f'(x) = 6x^2 + 5$이고 $f(0) = 3$일 때, $f(1)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 10,
    "explanation": "**[핵심 개념]**\n도함수가 주어졌을 때 원함수를 구하는 것은 부정적분(역미분)을 이용합니다. 도함수 $f'(x)$를 적분하면 원함수 $f(x)$를 얻을 수 있으며, 이때 초기조건(boundary condition)을 사용하여 적분상수를 결정합니다.\n\n**[풀이]**\n\n**1단계: 주어진 조건 정리**\n- $f'(x) = 6x^2 + 5$\n- $f(0) = 3$\n- 구하는 값: $f(1)$\n\n**2단계: $f'(x)$를 적분하여 $f(x)$ 구하기**\n\n$$f(x) = \\int f'(x) \\, dx = \\int (6x^2 + 5) \\, dx$$\n\n각 항을 적분하면:\n$$f(x) = 6 \\cdot \\frac{x^3}{3} + 5x + C = 2x^3 + 5x + C$$\n\n여기서 $C$는 적분상수입니다.\n\n**3단계: 초기조건 $f(0) = 3$을 이용하여 적분상수 결정**\n\n$$f(0) = 2(0)^3 + 5(0) + C = 3$$\n\n$$C = 3$$\n\n**4단계: $f(x)$의 구체적인 형태**\n\n$$f(x) = 2x^3 + 5x + 3$$\n\n**5단계: $f(1)$ 계산**\n\n$$f(1) = 2(1)^3 + 5(1) + 3 = 2 + 5 + 3 = 10$$\n\n**[정답 확인]**\n$f(x) = 2x^3 + 5x + 3$에서 $f'(x) = 6x^2 + 5$이고 $f(0) = 3$을 모두 만족하므로, $f(1) = 10$이 정답입니다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으므로, 일반적인 오류를 언급하면:\n- 적분상수를 고려하지 않으면 $2 + 5 = 7$ 같은 잘못된 답이 나옴\n- 초기조건을 잘못 적용하면 다른 $C$ 값이 나와 최종 답이 달라짐\n- 미분과 적분을 헷갈리면 원점에서 시작\n\n**[핵심 포인트]**\n도함수가 주어졌을 때는 **적분**으로 원함수를 구하고, 반드시 **초기조건을 사용하여 적분상수를 결정**해야 합니다. 이것이 미적분학의 기본정리를 다루는 핵심입니다.",
