    "explanation": "**[핵심 개념]**\n이 문제는 미분과 적분의 역관계를 이용하는 문제입니다.\n- 도함수 $f'(x)$가 주어졌을 때, 원래 함수 $f(x)$를 구하려면 부정적분(역미분)을 이용합니다.\n- 부정적분의 결과에는 상수항이 포함되며, 초기조건 $f(0) = 3$을 이용하여 이 상수를 결정합니다.\n- 공식: $\\int (ax^n) dx = \\frac{a}{n+1}x^{n+1} + C$\n\n**[풀이]**\n\n**Step 1: 도함수를 적분하여 원함수 구하기**\n\n$f'(x) = 3x^2 + 4x$이므로, 양변을 $x$에 대해 적분합니다.\n\n$$f(x) = \\int (3x^2 + 4x) dx$$\n\n항별로 적분하면:\n$$f(x) = \\int 3x^2 dx + \\int 4x dx$$\n\n$$f(x) = 3 \\cdot \\frac{x^3}{3} + 4 \\cdot \\frac{x^2}{2} + C$$\n\n$$f(x) = x^3 + 2x^2 + C$$\n\n**Step 2: 초기조건을 이용하여 상수 $C$ 결정**\n\n$f(0) = 3$이므로:\n\n$$f(0) = 0^3 + 2(0)^2 + C = 3$$\n\n$$C = 3$$\n\n**Step 3: 원함수 완성**\n\n$$f(x) = x^3 + 2x^2 + 3$$\n\n**Step 4: $f(1)$ 계산**\n\n$$f(1) = 1^3 + 2(1)^2 + 3$$\n\n$$f(1) = 1 + 2 + 3 = 6$$\n\n**[정답 확인]**\n$f(x) = x^3 + 2x^2 + 3$에서 $f'(x) = 3x^2 + 4x$ ✓, $f(0) = 3$ ✓이므로 모든 조건을 만족하며, $f(1) = 6$입니다.\n\n**[오답 분석]**\n객관식 선택지가 없어 오답 분석은 생략되었습니다. 만약 선택지가 있다면:\n- 상수 $C$를 구하지 않고 $f(x) = x^3 + 2x^2$로 계산하면 $f(1) = 3$ (오답)\n- 적분 과정에서 계산 실수가 있으면 다른 값이 나올 수 있습니다.\n\n**[핵심 포인트]**\n1. **도함수가 주어질 때는 부정적분을 이용하여 원함수를 구합니다.**\n2. **부정적분 결과의 상수항은 반드시 초기조건으로 결정해야 합니다.** (상수 $C$를 잊으면 안 됩니다)",
