    "answer": 17,
    "explanation": "**[핵심 개념]**\n- 부정적분(원시함수): 주어진 도함수 $f'(x)$로부터 원래 함수 $f(x)$를 구하는 과정\n- 부정적분의 공식: $\\int x^n dx = \\frac{x^{n+1}}{n+1} + C$ (단, $n \\neq -1$)\n- 초기조건: 적분상수를 결정하기 위해 주어진 조건 $f(1) = 6$을 사용\n\n**[풀이]**\n\n**Step 1: 주어진 도함수를 적분하여 $f(x)$ 구하기**\n\n$f'(x) = 3x^2 + 2x + 1$이므로, 양변을 $x$에 대해 적분합니다.\n\n$$f(x) = \\int (3x^2 + 2x + 1) dx$$\n\n각 항을 개별적으로 적분하면:\n\n$$f(x) = \\int 3x^2 dx + \\int 2x dx + \\int 1 dx$$\n\n$$f(x) = 3 \\cdot \\frac{x^3}{3} + 2 \\cdot \\frac{x^2}{2} + x + C$$\n\n$$f(x) = x^3 + x^2 + x + C$$\n\n여기서 $C$는 적분상수입니다.\n\n**Step 2: 초기조건 $f(1) = 6$을 이용하여 적분상수 $C$ 결정**\n\n$x = 1$을 $f(x)$에 대입하면:\n\n$$f(1) = 1^3 + 1^2 + 1 + C = 6$$\n\n$$1 + 1 + 1 + C = 6$$\n\n$$3 + C = 6$$\n\n$$C = 3$$\n\n**Step 3: $f(2)$ 계산**\n\n따라서 $f(x) = x^3 + x^2 + x + 3$이므로:\n\n$$f(2) = 2^3 + 2^2 + 2 + 3$$\n\n$$f(2) = 8 + 4 + 2 + 3 = 17$$\n\n**[정답 확인]**\n$f(x) = x^3 + x^2 + x + 3$이 $f'(x) = 3x^2 + 2x + 1$과 $f(1) = 6$ 두 조건을 모두 만족하고, 이로부터 $f(2) = 17$이 올바르게 계산됩니다.\n\n**[오답 분석]**\n- **15**: $f(2) = 8 + 4 + 2 + 1 = 15$로 계산하면 $C$ 값을 잘못 구한 경우 (예: $C = 1$로 잘못 계산)\n- **18**: $C$ 값을 구할 때 계산 실수로 $C = 4$라고 하면 $f(2) = 8 + 4 + 2 + 4 = 18$\n- **14**: 적분 과정에서 계수를 잘못 처리하거나 상수항을 누락한 경우\n\n**[핵심 포인트]**\n- 도함수가 주어졌을 때는 **부정적분**을 통해 원함수를 구하고, 주어진 조건으로 **적분상수를 결정**해야 한다.\n- 적분 후 반드시 초기조건을 대입하여 적분상수를 구하는 단계를 빠뜨리지 말 것.",
