    "explanation": "**[핵심 개념]**\n이 문제는 부정적분(역미분)과 초기조건을 이용하는 기본 개념을 다룹니다.\n- 도함수 $f'(x)$가 주어졌을 때, 원함수 $f(x)$를 구하려면 부정적분을 이용합니다.\n- 부정적분: $\\int f'(x)dx = f(x) + C$ (C는 적분상수)\n- 초기조건 $f(0) = 3$을 이용하여 적분상수를 결정합니다.\n\n**[풀이]**\n\n**1단계: 주어진 도함수를 이용하여 원함수 구하기**\n\n$f'(x) = 6x^2 + 2$이므로, 양변을 적분합니다.\n\n$$f(x) = \\int (6x^2 + 2)dx$$\n\n각 항을 적분하면:\n$$f(x) = 6 \\cdot \\frac{x^3}{3} + 2x + C = 2x^3 + 2x + C$$\n\n여기서 $C$는 적분상수입니다.\n\n**2단계: 초기조건을 이용하여 적분상수 결정**\n\n$f(0) = 3$이라는 조건을 이용합니다.\n\n$$f(0) = 2(0)^3 + 2(0) + C = 3$$\n\n$$C = 3$$\n\n따라서 원함수는:\n$$f(x) = 2x^3 + 2x + 3$$\n\n**3단계: $f(2)$ 계산**\n\n$$f(2) = 2(2)^3 + 2(2) + 3$$\n$$= 2 \\cdot 8 + 4 + 3$$\n$$= 16 + 4 + 3$$\n$$= 23$$\n\n**[정답 확인]**\n$f(x) = 2x^3 + 2x + 3$에서 도함수를 구하면 $f'(x) = 6x^2 + 2$ ✓, $f(0) = 3$ ✓이므로 정답이 맞습니다.\n\n**[오답 분석]**\n- **19**: 적분상수를 빼먹고 $f(x) = 2x^3 + 2x$로 계산한 경우\n- **20**: 계산 실수로 $2 \\times 8 = 14$로 잘못 계산한 경우\n- **21**: 초기조건을 제대로 반영하지 못한 경우\n\n**[핵심 포인트]**\n1. 도함수가 주어지면 **부정적분**으로 원함수를 구하고, 반드시 **적분상수 C**를 포함해야 합니다.\n2. 초기조건(한 점의 함숫값)을 이용하여 적분상수를 **유일하게 결정**하는 것이 중요합니다.",
