    "answer": 5,
    "explanation": "**[핵심 개념]**\n이 문제는 도함수가 주어졌을 때 원함수를 구하는 부정적분(역미분) 문제입니다. 핵심 공식은 다음과 같습니다:\n- 도함수 $f'(x)$가 주어지면, 부정적분을 통해 $f(x) = \\int f'(x)dx + C$ 형태로 구합니다.\n- 초기조건 $f(0) = 1$을 이용하여 적분상수 $C$를 결정합니다.\n- 멱함수의 적분: $\\int x^n dx = \\frac{x^{n+1}}{n+1} + C$\n\n**[풀이]**\n\n**Step 1: 도함수를 적분하여 $f(x)$ 구하기**\n\n$$f'(x) = 6x^2 + 2x + 1$$\n\n양변을 $x$에 대해 적분하면:\n\n$$f(x) = \\int (6x^2 + 2x + 1)dx$$\n\n각 항을 개별적으로 적분합니다:\n\n$$f(x) = 6 \\cdot \\frac{x^3}{3} + 2 \\cdot \\frac{x^2}{2} + x + C$$\n\n$$f(x) = 2x^3 + x^2 + x + C$$\n\n**Step 2: 초기조건을 이용하여 적분상수 $C$ 결정**\n\n$f(0) = 1$이라는 조건을 대입합니다:\n\n$$f(0) = 2(0)^3 + (0)^2 + 0 + C = 1$$\n\n$$C = 1$$\n\n따라서:\n$$f(x) = 2x^3 + x^2 + x + 1$$\n\n**Step 3: $f(1)$ 계산**\n\n$$f(1) = 2(1)^3 + (1)^2 + 1 + 1$$\n\n$$f(1) = 2 + 1 + 1 + 1 = 5$$\n\n**[정답 확인]**\n$f(x) = 2x^3 + x^2 + x + 1$에서 $f'(x) = 6x^2 + 2x + 1$ (미분으로 검증 가능)이고, $f(0) = 1$을 만족하며, $f(1) = 5$입니다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답은 다음과 같습니다:\n- **4**: 적분상수를 빠뜨리거나 $C=0$으로 잘못 계산한 경우\n- **6**: 적분 계산 실수 (예: $6x^2$을 적분할 때 $6x^3$으로 잘못 계산)\n- **3**: 초기조건을 무시하고 $C=0$으로 가정한 후 계산한 경우\n\n**[핵심 포인트]**\n1. 도함수가 주어지면 **적분으로 원함수를 복원**하고, 반드시 **초기조건으로 적분상수를 결정**해야 합니다.\n2. 부정적분 후 미분으로 검증하면 계산 실수를 줄일 수 있습니다.",
