    "type": "함수증감",
    "problem": "함수 $f(x) = x^3 + ax^2 - 9x + b$가 $x = 1$에서 극소이고 극댓값이 $28$일 때, $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n함수의 극값은 도함수를 이용하여 구합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호 변화로 극대/극소를 판정합니다. 극소 조건과 극댓값 조건을 동시에 만족하는 미지수를 구해야 합니다.\n\n**[풀이]**\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 + ax^2 - 9x + b$$\n$$f'(x) = 3x^2 + 2ax - 9$$\n\n**Step 2: $x=1$에서 극소 조건 적용**\n$x=1$에서 극소이므로 $f'(1) = 0$이어야 합니다.\n$$f'(1) = 3(1)^2 + 2a(1) - 9 = 0$$\n$$3 + 2a - 9 = 0$$\n$$2a = 6$$\n$$a = 3$$\n\n**Step 3: 극값점 찾기**\n$a = 3$을 대입하면:\n$$f'(x) = 3x^2 + 6x - 9 = 3(x^2 + 2x - 3) = 3(x+3)(x-1)$$\n\n따라서 $f'(x) = 0$일 때 $x = -3$ 또는 $x = 1$\n\n**Step 4: 극값의 성질 판정**\n$f'(x) = 3(x+3)(x-1)$의 부호 변화:\n- $x < -3$일 때: $f'(x) > 0$ (증가)\n- $-3 < x < 1$일 때: $f'(x) < 0$ (감소)\n- $x > 1$일 때: $f'(x) > 0$ (증가)\n\n따라서 $x = -3$에서 극대, $x = 1$에서 극소 ✓\n\n**Step 5: 극댓값 조건으로 $b$ 구하기**\n극댓값이 28이므로 $f(-3) = 28$:\n$$f(-3) = (-3)^3 + 3(-3)^2 - 9(-3) + b = 28$$\n$$-27 + 27 + 27 + b = 28$$\n$$27 + b = 28$$\n$$b = 1$$\n\n**Step 6: 답 구하기**\n$$a + b = 3 + 1 = 4$$\n\n**[정답 확인]**\n$a=3, b=1$을 원래 함수에 대입하면 $f(x) = x^3 + 3x^2 - 9x + 1$이고, $f'(x) = 3(x+3)(x-1)$에서 $x=-3$에서 극대값 $f(-3)=28$, $x=1$에서 극소값을 가지므로 모든 조건을 만족합니다.\n\n**[오답 분석]**\n이 문제는 객관식이 아닌 단답형이므로 오답 분석이 해당되지 않습니다. 다만 계산 실수 가능 지점:\n- $f'(1)=0$에서 $a$를 잘못 구하는 경우\n- $f(-3)=28$을 계산할 때 부호 실수하는 경우\n- 극대/극소를 반대로 판정하는 경우\n\n**[핵심 포인트]**\n극값 조건은 $f'(x) = 0$과 부호 변화로 판정하며, 주어진 조건들(극소 위치, 극댓값)을 식으로 표현하여 미지수를 단계적으로 결정합니다.",
