    "explanation": "**[핵심 개념]**\n함수의 극값을 구하기 위해서는 도함수를 이용합니다. $f'(x) = 0$인 점에서 극값을 가지며, $f'(x)$의 부호 변화를 통해 극댓값과 극솟값을 판별합니다. $f'(x) > 0$에서 $f'(x) < 0$으로 변하면 극댓값, $f'(x) < 0$에서 $f'(x) > 0$으로 변하면 극솟값입니다.\n\n**[풀이]**\n\n**1단계: 도함수 구하기**\n$$f(x) = 3x^3 - 9x^2 + a$$\n$$f'(x) = 9x^2 - 18x = 9x(x-2)$$\n\n**2단계: 극값을 갖는 점 찾기**\n$$f'(x) = 0 \\Rightarrow 9x(x-2) = 0$$\n$$x = 0 \\text{ 또는 } x = 2$$\n\n**3단계: 극댓값과 극솟값 판별**\n- $x < 0$일 때: $f'(x) = 9x(x-2) > 0$ (증가)\n- $0 < x < 2$일 때: $f'(x) = 9x(x-2) < 0$ (감소)\n- $x > 2$일 때: $f'(x) = 9x(x-2) > 0$ (증가)\n\n따라서 $x = 0$에서 극댓값, $x = 2$에서 극솟값을 가집니다.\n\n**4단계: 극댓값 조건으로 $a$ 구하기**\n$$f(0) = 3(0)^3 - 9(0)^2 + a = a$$\n\n극댓값이 20이므로:\n$$a = 20$$\n\n**5단계: 극솟값 구하기**\n$$f(2) = 3(2)^3 - 9(2)^2 + 20$$\n$$= 3 \\cdot 8 - 9 \\cdot 4 + 20$$\n$$= 24 - 36 + 20$$\n$$= 8$$\n\n**[정답 확인]**\n극솟값은 $x=2$에서의 함숫값이고, $a=20$을 대입하여 계산하면 $f(2) = 8$입니다.\n\n**[오답 분석]**\n이는 객관식이 아닌 단답형 문제이므로 오답 분석이 해당되지 않습니다. 다만 $a$ 값을 구하지 않고 바로 극솟값을 구하거나, $x=0$과 $x=2$의 역할을 헷갈리면 오답이 됩니다.\n\n**[핵심 포인트]**\n극댓값과 극솟값의 위치를 도함수의 부호 변화로 정확히 판별하고, 주어진 조건(극댓값이 20)을 이용해 상수항 $a$를 먼저 구한 후 극솟값을 계산하는 것이 중요합니다.",
