    "answer": 9,
    "explanation": "**[핵심 개념]**\n곡선 위의 한 점에서의 접선을 구하기 위해서는:\n1. 곡선의 도함수를 구해 그 점에서의 기울기(미분값)를 구한다\n2. 점-기울기 형태의 직선 방정식을 세운다: $y - y_1 = m(x - x_1)$\n3. 이를 $y = mx + b$ 형태로 정리하여 $y$절편 $b$를 구한다\n\n**[풀이]**\n\n**1단계: 주어진 점이 곡선 위에 있는지 확인**\n\n점 $(1, 5)$를 곡선 $y = x^3 - 5x^2 + 3x + 6$에 대입:\n$$y = 1^3 - 5(1)^2 + 3(1) + 6 = 1 - 5 + 3 + 6 = 5$$ ✓\n\n**2단계: 도함수 구하기**\n\n$$y = x^3 - 5x^2 + 3x + 6$$\n$$\\frac{dy}{dx} = 3x^2 - 10x + 3$$\n\n**3단계: $x=1$에서의 기울기 구하기**\n\n$$m = 3(1)^2 - 10(1) + 3 = 3 - 10 + 3 = -4$$\n\n**4단계: 접선의 방정식 구하기**\n\n점 $(1, 5)$를 지나고 기울기가 $-4$인 직선:\n$$y - 5 = -4(x - 1)$$\n$$y - 5 = -4x + 4$$\n$$y = -4x + 9$$\n\n**5단계: $y$절편 구하기**\n\n$x = 0$일 때: $y = -4(0) + 9 = 9$\n\n**[정답 확인]**\n접선의 방정식 $y = -4x + 9$에서 $y$절편(즉, $x=0$일 때의 $y$ 값)은 **9**이다.\n\n**[오답 분석]**\n선택지가 없으므로 생략\n\n**[핵심 포인트]**\n- 접선의 기울기 = 그 점에서의 미분값\n- 직선의 $y$절편은 $x=0$을 대입했을 때의 $y$ 값",
