    "explanation": "**[핵심 개념]**\n곡선 $y = f(x)$에 그은 접선의 방정식을 구하기 위해서는:\n1. 접점을 $(a, f(a))$로 설정\n2. 접선의 기울기는 도함수값: $f'(a)$\n3. 접선의 방정식: $y - f(a) = f'(a)(x - a)$\n4. 구한 접선이 주어진 조건(기울기, y절편, 지나는 점)을 만족하는지 확인\n\n**[풀이]**\n\n곡선 $y = x^3 - 3x^2 - x + 2$에서 접점을 $(a, a^3 - 3a^2 - a + 2)$라 하자.\n\n**Step 1: 도함수 구하기**\n$$f(x) = x^3 - 3x^2 - x + 2$$\n$$f'(x) = 3x^2 - 6x - 1$$\n\n**Step 2: 기울기 조건 적용**\n접선의 기울기가 8이므로:\n$$f'(a) = 8$$\n$$3a^2 - 6a - 1 = 8$$\n$$3a^2 - 6a - 9 = 0$$\n$$a^2 - 2a - 3 = 0$$\n$$(a - 3)(a + 1) = 0$$\n$$a = 3 \\text{ 또는 } a = -1$$\n\n**Step 3: 각 경우의 접선 구하기**\n\n**경우 1: $a = 3$일 때**\n- 접점: $(3, 27 - 27 - 3 + 2) = (3, -1)$\n- 접선: $y - (-1) = 8(x - 3)$\n- $y = 8x - 24 - 1 = 8x - 25$\n- y절편: $-25$ (음수) ✗\n\n**경우 2: $a = -1$일 때**\n- 접점: $(-1, -1 - 3 + 1 + 2) = (-1, -1)$\n- 접선: $y - (-1) = 8(x - (-1))$\n- $y + 1 = 8(x + 1)$\n- $y = 8x + 8 - 1 = 8x + 7$\n- y절편: $7$ (양수) ✓\n\n**Step 4: 점 $(1, k)$를 지나는지 확인**\n$$k = 8(1) + 7 = 15$$\n\n**[정답 확인]**\n접선 $y = 8x + 7$이 기울기 8, y절편 7(양수)의 조건을 만족하고, 점 $(1, 15)$를 지나므로 $k = 15$가 정답이다.\n\n**[오답 분석]**\n- $a = 3$인 경우 y절편이 음수가 되어 조건을 만족하지 않음\n- 계산 실수로 $8 \\times 1 - 25 = -17$ 등으로 잘못 계산하면 오답\n\n**[핵심 포인트]**\n1. 접선의 기울기 조건에서 여러 접점이 나올 수 있으므로, y절편의 부호 조건을 반드시 확인해야 함\n2. 접점을 $(a, f(a))$로 설정하고 $f'(a) = 8$을 이용하는 것이 가장 체계적인 풀이법",
